// Strategies + conditions
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Serialize, Deserialize, Default)]
#[serde(default, rename_all = "camelCase")]
pub struct Condition {
    pub id: String,
    pub indicator: String,
    pub source: String,
    pub op: String,
    pub value: f64,
    #[serde(default)]
    pub settings: Value,
}

#[derive(Clone, Debug, Serialize, Deserialize, Default)]
#[serde(default, rename_all = "camelCase")]
pub struct Strategy {
    pub id: String,
    pub name: String,
    pub category: String,
    pub timeframe: String,
    pub security_id: i64,
    pub exchange_segment: String,
    pub instrument: String,
    pub trading_symbol: String,
    pub side: String,
    pub enabled: bool,
    pub conditions: Vec<Condition>,
    /// Last time (ms) an entry signal fired; debounces re-entry.
    pub last_signal: i64,
    pub last_error: String,
    /// Scanner-generated (Top Movers / MCX commodity) instrument.
    /// Synthetic rows carry no conditions - the indicator-filter gate is the
    /// entry rule - so the engine does not require a saved strategy for them.
    #[serde(default)]
    pub synthetic: bool,
    /// Authoritative contract lot size for a synthetic scanner instrument (0 =
    /// resolve from the scrip master as usual).
    #[serde(default)]
    pub lot: f64,
    /// Research group this strategy belongs to (old AST `groupOf(method)`):
    /// "candlestick" | "elliott" | "indicator" | "pane" | "symmetry" |
    /// "structure" | "atr" | "other". Drives the "Research stream" scoping
    /// checkboxes: when a side has stream groups ticked, only its strategies
    /// whose group is in that list run ("other"/empty always runs).
    #[serde(default)]
    pub group: String,
    /// Manual one-off order placed from an Order Placement card. Manual entries
    /// derive the option leg from the order side when the chart is an index
    /// (BUY = CE, SELL = PE) instead of reading the global Option Type setting.
    #[serde(default)]
    pub manual: bool,
    /// Top Movers gainer/loser scanner leg marker. Leg selection was removed
    /// from the backend, so this no longer picks a CE/PE contract by itself.
    #[serde(default)]
    pub movers_leg: bool,
    /// Liquid F&O scanner leg marker. Liquid legs size their quantity and
    /// iceberg-slice from the dedicated `liquid_auto_lot_*` / `liquid_slice_*`
    /// settings instead of the global ones, so this scanner's lot policy stays
    /// isolated from Top Movers / indices / commodities.
    #[serde(default)]
    pub liquid_leg: bool,
}

/// One pre-scanned "Leg Book" entry. When a Top-Movers stock is first picked the
/// engine scans its option chain ONCE and freezes the green + fastest-rising
/// strikes here, keyed by the underlying security id. Every subsequent entry
/// reuses these saved contracts instead of re-walking / warming the chain on each
/// pass; the entry is rebuilt only when the pick, its bound side, the nearest
/// expiry or the chosen strike's plus sign changes, or the 15-minute monitoring
/// window elapses.
#[derive(Clone)]
struct BookLeg {
    /// Bound option side the legs were scanned for ("CE" for a gainer, "PE" for a
    /// loser). A side flip invalidates the entry so it is re-scanned on the new
    /// side instead of reusing the frozen opposite leg.
    side: String,
    /// Nearest expiry the entry was resolved under; a roll to the next expiry
    /// invalidates it.
    expiry: String,
    /// First +green strike in the "Execute Trade In" walk order - consumed by the
    /// "Only +green premium strikes" preference. `None` when the whole side was
    /// minus at scan time (the entry then blocks rather than buying a minus leg).
    green: Option<Strategy>,
    /// Highest LTP change % (ties broken by the absolute LTP change) among the
    /// +green strikes - consumed by the "Pick fastest positive rising LTP"
    /// preference. Always +green; `None` when nothing on the side is green.
    fastest: Option<Strategy>,
    /// The +green rising strikes of the bound side ranked most-risen first (the
    /// same published LTP change % ordering `fastest` uses), capped to the
    /// "Fastest-Rising Strikes" count. Consumed by the "Picked Strikes" readout,
    /// which lists one row per saved strike.
    fastest_list: Vec<Strategy>,
    /// Scan time (ms). After the 15-minute sign-monitoring window the entry is
    /// re-scanned so a stock that has since found a faster rising strike is
    /// refreshed.
    built_ms: i64,
}

impl BookLeg {
    /// The frozen contract the current preference asks for: the fastest riser
    /// when "Pick fastest positive rising LTP" is on, else the first +green
    /// strike. `None` means the preference is OFF (caller falls back to ATM) or
    /// no +green strike was saved on this side.
    fn preferred(&self, settings: &Settings) -> Option<&Strategy> {
        if settings.fastest_rising {
            self.fastest.as_ref().or(self.green.as_ref())
        } else if settings.only_positive {
            self.green.as_ref()
        } else {
            None
        }
    }
}

/// How long a saved Leg Book entry is monitored for before a full re-scan: within
/// this window the engine only re-checks the saved strike's plus sign (cheap),
/// and a sign break - or the window elapsing - triggers a fresh scan for that one
/// stock.
const LEG_BOOK_TTL_MS: i64 = 15 * 60 * 1000;

// ---------------------------------------------------------------------------
// Persisted document
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(default, rename_all = "camelCase")]
pub struct RtDoc {
    pub settings: Settings,
    pub method: String,
    pub order_cfg: HashMap<String, Value>,
    /// Per-engine broker routing: broker id -> send this engine's orders to it.
    /// Only brokers that are switched ON and fully configured in the shared
    /// Broker Settings tab can actually receive an order; an EMPTY map keeps the
    /// legacy behaviour (Dhan only), so an untouched install is unaffected.
    pub brokers: BTreeMap<String, bool>,
    pub strategies: Vec<Strategy>,
    pub positions: Vec<Value>,
    pub closed: Vec<Value>,
    pub armed: bool,
    pub engine_on: bool,
    pub auto_lots: bool,
    pub logs: Vec<Value>,
    pub last_square_off_day: String,
    /// IST day-key of the last F&O-stock expiry-day auto square-off run, so the
    /// expiry guard fires its square-off at most once per expiry day.
    pub last_expiry_square_off_day: String,
    /// Saved AST templates: name -> snapshot `{ side, savedAt, settings }`.
    pub templates: BTreeMap<String, Value>,
    /// Per-strategy selection map (old AST `state.selected`); the engine runs the
    /// ticked strategies in addition to the AI-picked ones.
    pub selected: BTreeMap<String, bool>,
    /// Strategy staging list: Auto Experiment / saved strategies waiting to be
    /// sent to (or already sent to) the engine.
    pub staging: Vec<Value>,
    pub staging_auto: bool,
    /// Entry-timing diagnostics: one row per filter-alignment episode, newest first.
    pub entry_timing: Vec<Value>,
    /// Best-performing strategies auto-saved for one-click re-run.
    pub final_strategies: Vec<Value>,
    /// Keys the operator removed from the Final list (never re-added by the scan).
    pub final_excluded: BTreeMap<String, bool>,
    /// Realised outcome buckets keyed by `regime|instrument|side`, fed by every
    /// closed engine trade. The brain blends this ground truth with the candle
    /// backtest so its filter ranking is gradually corrected by real fills.
    pub evidence: BTreeMap<String, crate::brain::RealisedBucket>,
}

impl Default for RtDoc {
    fn default() -> Self {
        Self {
            settings: Settings::default(),
            method: "super".into(),
            order_cfg: HashMap::new(),
            brokers: BTreeMap::new(),
            strategies: Vec::new(),
            positions: Vec::new(),
            closed: Vec::new(),
            armed: false,
            engine_on: false,
            auto_lots: false,
            logs: Vec::new(),
            last_square_off_day: String::new(),
            last_expiry_square_off_day: String::new(),
            templates: BTreeMap::new(),
            selected: BTreeMap::new(),
            staging: Vec::new(),
            staging_auto: false,
            entry_timing: Vec::new(),
            final_strategies: Vec::new(),
            final_excluded: BTreeMap::new(),
            evidence: BTreeMap::new(),
        }
    }
}

/// Dhan-style broker charge simulation, ported 1:1 from the Python paper-trade
/// engine (`static/papertrade.js`). All rates are Dhan's published retail
/// tariffs (dhan.co/pricing):
///   Delivery: brokerage Rs 0, STT 0.1% (buy+sell), NSE txn 0.0030699%,
///             SEBI 0.0001%, stamp 0.015% (buy), IPFT 0.0000001%, GST 18%
///   Intraday: brokerage Rs 20 or 0.03% (lower of the two), STT 0.025% (sell),
///             NSE txn 0.0030699%, SEBI 0.0001%, stamp 0.003% (buy),
///             IPFT 0.0000001%, GST 18%
///   Options:  brokerage Rs 20 / executed order, STT 0.0625% of premium (sell),
///             NSE txn 0.03503% of premium, SEBI 0.0001%, stamp 0.003% (buy),
///             IPFT 0.0000001%, GST 18%
///   Futures:  brokerage Rs 20 / executed order, STT 0.02% of turnover (sell),
///             NSE txn 0.00173% of turnover, SEBI 0.0001%, stamp 0.003% (buy),
///             IPFT 0.0000001%, GST 18%
/// Rounding follows the Dhan contract-note rule: STT + stamp duty to the nearest
/// rupee, every other component to 2 dp. Mirrored by the frontend `legCharges()`
/// so the paper wallet, Closed Trades table and Paper Stats all agree.
#[derive(Clone, Copy)]
struct ChargeRates {
    brokerage_flat: f64,
    brokerage_pct: f64,
    txn_pct: f64,
    stt_buy_pct: f64,
    stt_sell_pct: f64,
    sebi_pct: f64,
    stamp_buy_pct: f64,
    stamp_sell_pct: f64,
    gst_pct: f64,
    ipft_pct: f64,
}

const CHARGES_DELIVERY: ChargeRates = ChargeRates {
    brokerage_flat: 0.0,
    brokerage_pct: 0.0,
    txn_pct: 0.0030699,
    stt_buy_pct: 0.1,
    stt_sell_pct: 0.1,
    sebi_pct: 0.0001,
    stamp_buy_pct: 0.015,
    stamp_sell_pct: 0.0,
    gst_pct: 18.0,
    ipft_pct: 0.0000001,
};
const CHARGES_INTRADAY: ChargeRates = ChargeRates {
    brokerage_flat: 20.0,
    brokerage_pct: 0.03,
    txn_pct: 0.0030699,
    stt_buy_pct: 0.0,
    stt_sell_pct: 0.025,
    sebi_pct: 0.0001,
    stamp_buy_pct: 0.003,
    stamp_sell_pct: 0.0,
    gst_pct: 18.0,
    ipft_pct: 0.0000001,
};
const CHARGES_OPTIONS: ChargeRates = ChargeRates {
    brokerage_flat: 20.0,
    brokerage_pct: 0.0,
    txn_pct: 0.03503,
    stt_buy_pct: 0.0,
    stt_sell_pct: 0.0625,
    sebi_pct: 0.0001,
    stamp_buy_pct: 0.003,
    stamp_sell_pct: 0.0,
    gst_pct: 18.0,
    ipft_pct: 0.0000001,
};
const CHARGES_FUTURES: ChargeRates = ChargeRates {
    brokerage_flat: 20.0,
    brokerage_pct: 0.0,
    txn_pct: 0.00173,
    stt_buy_pct: 0.0,
    stt_sell_pct: 0.02,
    sebi_pct: 0.0001,
    stamp_buy_pct: 0.003,
    stamp_sell_pct: 0.0,
    gst_pct: 18.0,
    ipft_pct: 0.0000001,
};

/// Charge segment for a position / symbol: OPT* -> options, FUT* -> futures,
/// otherwise delivery (equity / index spot). Mirrors Python `segmentFor()`.
fn charges_segment(instrument: &str, trading_symbol: &str) -> &'static str {
    let inst = instrument.trim().to_ascii_uppercase();
    if matches!(inst.as_str(), "OPTIDX" | "OPTSTK" | "OPTFUT" | "OPT") {
        return "options";
    }
    if matches!(inst.as_str(), "FUTIDX" | "FUTSTK" | "FUTCOM" | "FUT") {
        return "futures";
    }
    let nm = trading_symbol.trim().to_ascii_uppercase();
    let has_ce_pe = nm
        .split(|c: char| !c.is_ascii_alphanumeric())
        .any(|w| w == "CE" || w == "PE");
    if has_ce_pe {
        return "options";
    }
    "delivery"
}

fn charges_rates(segment: &str) -> ChargeRates {
    match segment {
        "options" => CHARGES_OPTIONS,
        "futures" => CHARGES_FUTURES,
        "intraday" => CHARGES_INTRADAY,
        _ => CHARGES_DELIVERY,
    }
}

/// Per-component charge line for one order side (turnover = qty x price).
#[derive(Clone, Copy, Default)]
struct SideCharges {
    brokerage: f64,
    txn: f64,
    stt: f64,
    sebi: f64,
    stamp: f64,
    ipft: f64,
    gst: f64,
    total: f64,
}

impl SideCharges {
    fn to_json(&self) -> serde_json::Value {
        json!({
            "brokerage": self.brokerage,
            "txn": self.txn,
            "stt": self.stt,
            "sebi": self.sebi,
            "stamp": self.stamp,
            "ipft": self.ipft,
            "gst": self.gst,
            "total": self.total,
        })
    }
}

/// One side's charges for `segment`. STT + stamp round to the nearest rupee,
/// every other component to 2 dp (Dhan contract-note rule).
fn side_charges(segment: &str, is_buy: bool, turnover: f64) -> SideCharges {
    let c = charges_rates(segment);
    let t = turnover.abs();
    if t <= 0.0 {
        return SideCharges::default();
    }
    let mut brokerage = c.brokerage_flat;
    if c.brokerage_pct > 0.0 {
        let pct = (t * c.brokerage_pct) / 100.0;
        brokerage = if c.brokerage_flat > 0.0 {
            c.brokerage_flat.min(pct)
        } else {
            pct
        };
    }
    let txn = t * c.txn_pct / 100.0;
    let stt = ((if is_buy { c.stt_buy_pct } else { c.stt_sell_pct }) * t / 100.0).round();
    let sebi = t * c.sebi_pct / 100.0;
    let stamp = ((if is_buy { c.stamp_buy_pct } else { c.stamp_sell_pct }) * t / 100.0).round();
    let ipft = t * c.ipft_pct / 100.0;
    let gst = (brokerage + txn + sebi + ipft) * c.gst_pct / 100.0;
    SideCharges {
        brokerage: round2(brokerage),
        txn: round2(txn),
        stt,
        sebi: round2(sebi),
        stamp,
        ipft,
        gst: round2(gst),
        total: round2(brokerage + txn + stt + sebi + stamp + ipft + gst),
    }
}

/// Full round-trip charge estimate for a position closed at `exit`. Mirrors
/// Python `computeChargesForTrade()`; the entry leg used `pos.side` and the exit
/// leg the opposite side, so STT lands on the sell leg and stamp on the buy leg.
#[allow(dead_code)]
struct TradeCharges {
    segment: &'static str,
    entry: SideCharges,
    exit: SideCharges,
    total: f64,
    gross: f64,
    net: f64,
}

/// Round-trip charge total (entry + exit legs) for any engine, including the
/// equity delivery engine. Exposed so Net Take-Profit computes the same charges
/// as the realtime engine instead of keeping a second copy of the rate tables.
pub(crate) fn round_trip_charges(
    entry: f64,
    exit: f64,
    qty: f64,
    side: &str,
    instrument: &str,
    trading_symbol: &str,
    gross: f64,
) -> Option<f64> {
    compute_charges_for_trade(entry, exit, qty, side, instrument, trading_symbol, gross)
        .map(|c| c.total)
}

fn compute_charges_for_trade(
    entry: f64,
    exit: f64,
    qty: f64,
    side: &str,
    instrument: &str,
    trading_symbol: &str,
    gross: f64,
) -> Option<TradeCharges> {
    let q = qty.abs();
    if q <= 0.0 || entry.abs() <= 0.0 || exit.abs() <= 0.0 {
        return None;
    }
    let segment = charges_segment(instrument, trading_symbol);
    let is_long = !side.eq_ignore_ascii_case("SELL");
    let entry_c = side_charges(segment, is_long, entry.abs() * q);
    let exit_c = side_charges(segment, !is_long, exit.abs() * q);
    let total = round2(entry_c.total + exit_c.total);
    Some(TradeCharges {
        segment,
        entry: entry_c,
        exit: exit_c,
        total,
        gross: round2(gross),
        net: round2(gross - total),
    })
}

/// Net Take-Profit give-back floor. `None` until the peak net profit has
/// crossed the operator's rupee floor (feature not armed). Once armed, the
/// floor is `giveback_pct` below the peak, clamped to the minimum so a locked
/// trade can never book below it. `giveback_pct <= 0` or `>= 100` falls back to
/// the built-in 25%.
fn net_tp_floor(net_peak: f64, min: f64, giveback_pct: f64) -> Option<f64> {
    if min <= 0.0 || net_peak < min {
        return None;
    }
    let gb = if giveback_pct > 0.0 && giveback_pct < 100.0 {
        giveback_pct
    } else {
        25.0
    };
    Some((net_peak * (1.0 - gb / 100.0)).max(min))
}

/// Deterministic-per-seed PRNG (xorshift64*) for simulated paper outcomes, so a
/// rejection decision needs no external RNG dependency.
fn paper_rand01(seed: u64) -> f64 {
    let mut x = seed.wrapping_mul(0x2545F4914F6CDD1D).wrapping_add(0x9E3779B97F4A7C15);
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    let v = x.wrapping_mul(0x2545F4914F6CDD1D);
    (v >> 11) as f64 / (1u64 << 53) as f64
}

fn paper_seed(extra: i64) -> u64 {
    (now_ms() as u64) ^ (extra as u64).rotate_left(17)
}

/// Apply adverse slippage to a simulated fill: a BUY fills above the mark, a
/// SELL fills below it, by `bps` basis points of the mark.
fn paper_fill_price(mark: f64, is_buy: bool, bps: f64) -> f64 {
    let slip = (mark * bps / 10_000.0).abs();
    if is_buy {
        mark + slip
    } else {
        (mark - slip).max(0.05)
    }
}

/// A snapshot of the bid/ask spread config that can be carried into closures
/// (net-TP marking, target economics) without borrowing the whole `Settings`.
#[derive(Clone, Copy, Default)]
struct PaperSpread {
    on: bool,
    rs: f64,
    pct: f64,
}

impl From<&Settings> for PaperSpread {
    fn from(s: &Settings) -> Self {
        PaperSpread { on: s.paper_bid_ask_on, rs: s.paper_bid_ask_rs, pct: s.paper_bid_ask_pct }
    }
}

impl PaperSpread {
    /// Full spread in rupees for this mark (0 when off/empty).
    fn full(&self, mark: f64) -> f64 {
        if !self.on || mark <= 0.0 {
            return 0.0;
        }
        let rs = self.rs.max(0.0);
        let pct = (mark * self.pct.max(0.0) / 100.0).abs();
        // Never let the synthetic spread exceed twice the price: a fill is only
        // pushed by half the spread, so a >200% spread would drive a SELL below 0.
        (rs + pct).min(mark * 2.0)
    }

    /// Half spread in rupees - the per-side cost added on a BUY / removed on a SELL.
    fn half(&self, mark: f64) -> f64 {
        self.full(mark) / 2.0
    }

    /// Cross the mark by half the spread toward the adverse side, then apply
    /// slippage on top. When the feature is OFF this is exactly the old
    /// slippage-only fill.
    fn fill(&self, mark: f64, is_buy: bool, slip_bps: f64) -> f64 {
        let half = self.half(mark);
        let crossed = if is_buy {
            mark + half
        } else {
            (mark - half).max(0.05)
        };
        paper_fill_price(crossed, is_buy, slip_bps)
    }
}

/// One paper fill with BOTH models applied in order: the bid/ask spread is
/// crossed first (the price you actually transact at), then the slippage/impact
/// is added on top of it. Stacking them mirrors reality - you pay the spread
/// and then your own order's impact - and keeps the existing slippage-only
/// behaviour identical when the spread is OFF.
fn paper_exec_fill(mark: f64, is_buy: bool, settings: &Settings) -> f64 {
    PaperSpread::from(settings).fill(mark, is_buy, settings.paper_slippage_bps)
}

/// Paper-only F&O limit price for a BUY: a marketable price placed above the
/// market (never below it) so the order is certain to fill, exactly like a Dhan
/// market order. Sized generously enough (0.5% or one tick, whichever is
/// larger) that it is always marketable.
fn fno_limit_buy_price(ltp: f64) -> f64 {
    let protect = (ltp * 0.005).max(0.05);
    round2(ltp + protect)
}

/// Realized P&L of a closed trade: the stored net (after charges) when the
/// "Deduct Dhan charges" toggle is on, else the gross `pnl`. Real Dhan trades
/// settle charges broker-side (net == gross) and never turn the toggle on.
fn closed_pnl(c: &Value, charges_on: bool) -> f64 {
    if charges_on && c.get("netPnl").is_some() {
        jf(c, "netPnl")
    } else {
        jf(c, "pnl")
    }
}

/// Sum of realized P&L across closed trades.
fn realized_pnl(closed: &[Value], charges_on: bool) -> f64 {
    closed.iter().map(|c| closed_pnl(c, charges_on)).sum()
}

/// Smart P&L summary strip (old app `renderSummary`): "Smart Live P&L (gross)" is
/// `realized + unrealized`, "Smart Realized P&L" is the closed book's net,
/// "Smart Win Rate" and "Smart Trades (W/L)" come from the same closed trades
/// (L = total - wins, exactly like the old app) and "Smart Charges" sums every
/// banked charge. Computed from the FULL closed ledger, not the snapshot page,
/// so the strip never shrinks as trades age out.
fn smart_stats(closed: &[Value], positions: &[Value], charges_on: bool) -> Value {
    let realized = realized_pnl(closed, charges_on);
    // Live P&L is gross: running trades never deduct broker charges, which are
    // applied once at close and surface in the realized total.
    let unrealized: f64 = positions.iter().map(|p| jf(p, "pnl")).sum();
    let wins = closed.iter().filter(|c| closed_pnl(c, charges_on) > 0.0).count();
    let losses = closed.iter().filter(|c| closed_pnl(c, charges_on) < 0.0).count();
    let charges_total: f64 = closed.iter().map(|c| jf(c, "charges")).sum();
    let win_rate = if closed.is_empty() { 0.0 } else { wins as f64 / closed.len() as f64 * 100.0 };
    // Normalize negative zero so an empty book serializes as `0`, not `-0`.
    let z = |x: f64| if x == 0.0 { 0.0 } else { round2(x) };
    json!({
        "realized": z(realized),
        "unrealized": z(unrealized),
        "net": z(realized + unrealized),
        "wins": wins,
        "losses": losses,
        "total": closed.len(),
        "running": positions.len(),
        "charges": z(charges_total),
        "chargesOn": charges_on,
        "winRate": z(win_rate),
    })
}

/// Cost locked by open positions (qty x entry, falling back to fill/ltp), plus
/// the position count. Lock-free so callers already holding the doc lock can use
/// it without re-entering the (non-reentrant) mutex.
fn locked_margin_of(positions: &[Value]) -> (f64, i64) {
    let locked = positions
        .iter()
        .map(|p| {
            let qty = jf(p, "qty").abs();
            let entry = {
                let e = jf(p, "entry");
                if e > 0.0 {
                    e
                } else {
                    let f = jf(p, "fillPrice");
                    if f > 0.0 {
                        f
                    } else {
                        jf(p, "ltp")
                    }
                }
            };
            qty * entry
        })
        .sum();
    (locked, positions.len() as i64)
}

/// Pure margin gate: the block reason when a leg's required margin exceeds the
/// budget still free after the running trades, else `None`. In-memory arithmetic
/// only (microseconds), so it can be called both as an early pre-check and at the
/// actual fill without changing behaviour.
fn margin_block_reason(required: f64, budget: f64, locked: f64, running: i64) -> Option<String> {
    let available = (budget - locked).max(0.0);
    if required > available {
        Some(format!(
            "trade blocked: required margin {} > available {} (Margin {} - locked {} by {} running trade{})",
            round2(required),
            round2(available),
            round2(budget),
            round2(locked),
            running,
            if running == 1 { "" } else { "s" }
        ))
    } else {
        None
    }
}

/// Paper wallet balance BEFORE the running trades' margin is committed:
/// starting capital + realized P&L. The margin budget is sized against this so
/// the locked margin of open positions is subtracted exactly once (by the entry
/// gate / margin bar) instead of twice.
fn paper_wallet_of(cap: f64, closed: &[Value], charges_on: bool) -> f64 {
    (cap.max(0.0) + realized_pnl(closed, charges_on)).max(0.0)
}

/// Paper wallet base balance (before realized P&L). The shared-margin
/// allotment is the ONLY source: it sizes how much the tab may lock AND is the
/// wallet's opening balance, so there is no separate "Capital Rs" setting any
/// more. Realized P&L still grows/shrinks the running wallet exactly as before.
fn paper_base_of(engine_id: &str) -> f64 {
    crate::shared_margin::cap_for(engine_id).unwrap_or(0.0)
}

/// Paper wallet free cash: balance - margin locked by the open paper positions.
/// Derived (never stored) so it can never drift. This is the amount shown as the
/// account's available balance; the margin budget is sized against
/// [`paper_wallet_of`] instead, so the lock is never counted twice.
fn paper_available_of(cap: f64, closed: &[Value], positions: &[Value], charges_on: bool) -> f64 {
    let (locked, _) = locked_margin_of(positions);
    (paper_wallet_of(cap, closed, charges_on) - locked).max(0.0)
}

/// Durable state file names, one per independent engine. The real engine's
/// `ALGODHAN_STATE_PATH` override never applies to a paper engine, and each
/// paper engine keeps its own file so their books can never share state.
const STATE_FILE_REAL: &str = "algodhan_realtime_state.json";
const STATE_FILE_REAL2: &str = "algodhan_realtime2_state.json";
const STATE_FILE_REAL3: &str = "algodhan_realtime3_state.json";
const STATE_FILE_PAPER: &str = "algodhan_paper_state.json";
const STATE_FILE_PAPER2: &str = "algodhan_paper2_state.json";
const STATE_FILE_PAPER3: &str = "algodhan_paper3_state.json";
/// Equity Indicator Based Trade: an independent paper engine that trades ONLY
/// liquid NSE cash EQUITY (spot, delivery CNC) - no indices, no F&O options, no
/// commodities, no strikes / premiums / option chain. It is gated by the
/// BULLISH indicator filters ONLY (bearish filters have no function). Its own
/// durable state file and in-memory book; shares NO data with any other engine.
const STATE_FILE_PAPER4: &str = "algodhan_paper4_state.json";
/// Durable cache of the daily full-universe cash-equity liquidity scan (the
/// ranked stock list + the per-day turnover baseline the growth score needs).
/// Kept on disk so a restart does not lose the day's scan and the previous
/// session's turnover baseline, which would otherwise take two trading days to
/// rebuild the growth comparison.
const EQUITY_LIQUIDITY_FILE: &str = "algodhan_equity_liquidity_scan.json";
/// Auto Experiment: a complete, fully independent clone of Paper Trade (all
/// universes: stocks + indices + option-chain commodities) that shares NO data
/// with any other engine - its own durable state file and in-memory book.
const STATE_FILE_AUTOEXP: &str = "algodhan_autoexp_state.json";
/// AI Trader (Paper): an autonomous, brain-driven engine that deep-analyses the
/// operator's selected universe (indices / commodities / F&O stocks) with the
/// multi-factor decision layer and places/cuts trades on its own - simulated
/// execution, its own durable state file, shares NO data with any other engine.
const STATE_FILE_AITRADER: &str = "algodhan_aitrader_state.json";
/// AI Trader (Live): the same autonomous brain-driven engine, but places REAL
/// Dhan orders. Its own durable state file and in-memory book, so it can never
/// disturb another engine's positions.
const STATE_FILE_AITRADERLIVE: &str = "algodhan_aitraderlive_state.json";

/// Universal saved-template pool shared by every engine tab. Templates are
/// stored once here (with the engine they were saved from) instead of inside a
/// single engine's book, so any tab can apply any saved template.
const TEMPLATE_POOL_FILE: &str = "algodhan_template_pool.json";
pub type TemplatePool = Arc<Mutex<BTreeMap<String, Value>>>;

fn state_path(name: &str) -> PathBuf {
    // Durable location first: an explicit override, else a `data/` directory in
    // the process working dir. /tmp is only a last resort (wiped on reboot), so
    // the saved strategies/settings survive a restart.
    if name == STATE_FILE_REAL {
        if let Ok(p) = std::env::var("ALGODHAN_STATE_PATH") {
            if !p.trim().is_empty() {
                return PathBuf::from(p);
            }
        }
    }
    let dir = std::env::var("ALGODHAN_DATA_DIR")
        .ok()
        .filter(|s| !s.trim().is_empty())
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("data"));
    if std::fs::create_dir_all(&dir).is_ok() {
        return dir.join(name);
    }
    std::env::temp_dir().join(name)
}

/// Atomic JSON write: serialize to a sibling temp file then rename over the
/// target, so a crash mid-write cannot leave a truncated state file.
fn write_atomic(path: &Path, bytes: &[u8]) -> std::io::Result<()> {
    let tmp = path.with_extension("json.tmp");
    std::fs::write(&tmp, bytes)?;
    match std::fs::rename(&tmp, path) {
        Ok(()) => Ok(()),
        Err(e) => {
            let _ = std::fs::remove_file(&tmp);
            Err(e)
        }
    }
}

/// Parse a universal template pool file. Accepts both `{ "templates": {...} }`
/// (the format we write) and a bare `{ name: {...} }` map for older files.
fn parse_template_pool(s: &str) -> BTreeMap<String, Value> {
    let Ok(v) = serde_json::from_str::<Value>(s) else {
        return BTreeMap::new();
    };
    let body = v.get("templates").cloned().unwrap_or(v);
    serde_json::from_value::<BTreeMap<String, Value>>(body).unwrap_or_default()
}

fn write_template_pool(path: &Path, pool: &BTreeMap<String, Value>) -> std::io::Result<()> {
    let bytes = serde_json::to_vec(&json!({ "templates": pool }))
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
    write_atomic(path, &bytes)
}

/// Load the one universal template pool, or migrate the templates already saved
/// inside the six engine state files on first run. The pool file is separate so
/// saving/deleting a template from any tab affects every tab immediately.
pub fn shared_template_pool() -> TemplatePool {
    let path = state_path(TEMPLATE_POOL_FILE);
    let exists = path.is_file();
    let mut pool = if exists {
        std::fs::read_to_string(&path)
            .map(|s| parse_template_pool(&s))
            .unwrap_or_default()
    } else {
        BTreeMap::new()
    };
    if !exists {
        let engines = [
            (STATE_FILE_REAL, "realtime", "Realtime Trading Engine"),
            (STATE_FILE_REAL2, "realtime2", "Realtime Trading Engine 2"),
            (STATE_FILE_REAL3, "realtime3", "Realtime Trading Engine 3"),
            (STATE_FILE_PAPER, "paper", "Paper Trade"),
            (STATE_FILE_PAPER2, "paper2", "Paper Trade 2"),
            (STATE_FILE_PAPER3, "paper3", "Paper Trade 3"),
            (STATE_FILE_PAPER4, "paper4", "Equity Indicator Based Trade"),
            (STATE_FILE_AUTOEXP, "autoexp", "Auto Experiment"),
            (STATE_FILE_AITRADER, "aitrader", "AI Trader (Paper)"),
            (STATE_FILE_AITRADERLIVE, "aitraderlive", "AI Trader (Live)"),
        ];
        for (file, id, label) in engines {
            let Ok(s) = std::fs::read_to_string(state_path(file)) else {
                continue;
            };
            let Ok(doc) = serde_json::from_str::<RtDoc>(&s) else {
                continue;
            };
            for (name, mut t) in doc.templates {
                if t.get("origin").is_none() {
                    t["origin"] = json!(label);
                }
                if t.get("originId").is_none() {
                    t["originId"] = json!(id);
                }
                pool.entry(name).or_insert(t);
            }
        }
        if !pool.is_empty() {
            let _ = write_template_pool(&path, &pool);
        }
    }
    Arc::new(Mutex::new(pool))
}

pub(crate) fn persist_template_pool(pool: &TemplatePool) {
    let bytes = {
        let Ok(p) = pool.lock() else {
            return;
        };
        serde_json::to_vec(&json!({ "templates": &*p })).ok()
    };
    if let Some(bytes) = bytes {
        let _ = write_atomic(&state_path(TEMPLATE_POOL_FILE), &bytes);
    }
}

/// The Realtime Trading Engine and Paper Trade 1 no longer expose the Indices
/// (Top-Movers) picker nor the Commodity (MCX) scanner, and their run-in /
/// trade-in routing offers F&O stocks only. This clears the removed scanner
/// state and pins the removed routing fields to their defaults so a saved file,
/// an import or a settings POST can never arm them on these two engines. The
/// shared scanner / option-chain helpers stay intact for Paper Trade 2.
fn strip_realtime_pt1_extras(s: &mut Settings) {
    s.movers_indices.clear();
    s.movers_index_legs.clear();
    s.commodity_on = false;
    s.commodity_list.clear();
    s.commodity_legs.clear();
    // Paper Trade 2's per-instrument trend following is not exposed here.
    s.index_trend_on = false;
    s.index_trend_conf_inds.clear();
    s.comm_trend_on = false;
    s.comm_trend_conf_inds.clear();
    s.run_index = "spot".into();
    s.run_comm = "spot".into();
    s.trade_in_index = "premium".into();
    s.trade_in_comm = "premium".into();
}

/// Paper Trade 2 is an **indices + option-chain commodities only** book. This
/// strips everything the tab no longer exposes so a saved file, an import or a
/// settings POST can never arm a removed feature on the engine:
///   * no NIFTY Trend Following (and therefore no F&O-stock picks),
///   * no NIFTY BB%b (Pane) section,
///   * no Top Movers stock scan (the operator's index picks stay),
///   * commodities are limited to those that actually list an option chain.
fn sanitize_indices_commodities(s: &mut Settings) {
    s.nifty_trend_on = false;
    s.nifty_trend_pct_on = false;
    s.nifty_trend_conf_inds.clear();
    s.nifty_net_strict = false;
    s.nifty_all_agree_strict = false;
    s.bbpct_pane_on = false;
    s.bbpct_zone_on = false;
    s.bbpct_trend_on = false;
    s.bbpct_combo_on = false;
    // Only the operator indices remain: the stock gainer/loser scan is removed.
    s.movers_gainers = 0;
    s.movers_losers = 0;
    // The Liquid F&O stock scanner is a full-engine feature (Realtime / Paper
    // Trade 1) - strip it here so a saved file, import or settings POST can
    // never arm it on an indices/commodities book.
    s.liquid_on = false;
    s.liquid_gainers = 0;
    s.liquid_losers = 0;
    s.liquid_gainer = 0;
    s.liquid_loser = 0;
    s.liquid_list.clear();
    // The dedicated Liquid F&O lot policy belongs to the same scanner, so it is
    // inert (and reset) wherever the scanner itself is stripped.
    s.liquid_auto_lot_on = false;
    s.liquid_slice_on = false;
    // The operator's explicit CE/PE leg per added index is kept: Paper Trade 2
    // exposes the same leg dropdown as the other tabs, and the chosen leg is the
    // contract that trades (CE = bullish filters, PE = bearish filters). Drop
    // only legs whose index was removed so a stale leg can never linger.
    s.movers_index_legs.retain(|l| s.movers_indices.contains(&l.security_id));
    // Keep only commodities that are live MCX contracts AND that list options
    // (this book builds CE/PE legs). Once the scrip master is ready this drops
    // stale saved ids: the old bundled fallback ids (`500001..500015`) were never
    // real MCX contracts, rolled/expired contract ids stop being tradeable, and
    // futures-only names have no leg to trade. While the master is still warming
    // both checks return `None` and everything is KEPT - a restart before the
    // master loads must not wipe the operator's added commodities. An empty list
    // stays empty: the engine never invents a default set.
    s.commodity_list.retain(|id| {
        crate::market::commodity_is_live_contract(*id) != Some(false)
            && crate::market::commodity_has_options(*id) != Some(false)
    });
    // Keep the operator's chosen commodity leg, dropping any leg for a commodity
    // that was just removed (e.g. a stale/futures-only MCX name).
    s.commodity_legs.retain(|l| s.commodity_list.contains(&l.security_id));
}

/// Paper Trade 2 is an **indices only** book. On top of
/// [`sanitize_indices_commodities`] this clears every commodity field so a saved
/// file, an import or a settings POST can never arm an MCX instrument on a tab
/// that no longer exposes the commodity picker.
fn sanitize_indices_only(s: &mut Settings) {
    s.commodity_on = false;
    s.commodity_list.clear();
    s.commodity_legs.clear();
    s.comm_trend_on = false;
    s.comm_trend_conf_inds.clear();
}

/// Paper Trade 3 is a **commodities only** book. On top of
/// [`sanitize_indices_commodities`] this clears every index field so a saved
/// file, an import or a settings POST can never arm an index instrument on a tab
/// that no longer exposes the index picker.
fn sanitize_commodities_only(s: &mut Settings) {
    s.movers_on = false;
    s.movers_indices.clear();
    s.movers_index_legs.clear();
    s.index_trend_on = false;
    s.index_trend_conf_inds.clear();
}

/// Equity Indicator Based Trade (Paper Trade 4) is a **liquid NSE cash equity
/// only** book: no indices, no F&O option strikes, no commodities, no premium
/// chart, no option chain. Every entry is gated by the BULLISH indicator filters
/// ONLY, so this sanitizer:
///   * pins the equity-only flag ON (so the run/trade path stays on spot),
///   * strips every index / commodity / option-strike / premium scanner field,
///   * keeps ONLY bullish indicator filters ticked (bearish filters, primary
///     filters and any option-leg routing are cleared or ignored).
/// It runs on load, import and settings POST so a saved file or a hand-written
/// API call can never re-arm a removed option feature on this tab.
fn sanitize_equity_indicators(s: &mut Settings) {
    s.equity_only = true;
    // No indices / commodities / Top Movers indices.
    s.movers_on = false;
    s.movers_indices.clear();
    s.movers_index_legs.clear();
    s.commodity_on = false;
    s.commodity_list.clear();
    s.commodity_legs.clear();
    s.index_trend_on = false;
    s.index_trend_conf_inds.clear();
    s.comm_trend_on = false;
    s.comm_trend_conf_inds.clear();
    s.nifty_trend_on = false;
    s.nifty_trend_pct_on = false;
    s.nifty_trend_conf_inds.clear();
    s.bbpct_pane_on = false;
    s.bbpct_zone_on = false;
    s.bbpct_trend_on = false;
    s.bbpct_combo_on = false;
    // No strike ladder / premium routing / manual strikes / +green legs.
    s.manual_strikes_enabled = false;
    s.manual_strikes.clear();
    s.only_positive = false;
    s.fastest_rising = false;
    s.premium_only = false;
    // Everything runs AND trades on the cash spot chart.
    s.run_index = "spot".into();
    s.run_fno = "spot".into();
    s.run_comm = "spot".into();
    s.trade_in_index = "spot".into();
    s.trade_in_fno = "spot".into();
    s.trade_in_comm = "spot".into();
    // Bullish-only gate: drop every ticked bearish filter, the bearish primary
    // set, and any bearish leg pin so only bullish filters can gate an entry.
    s.filters.retain(|k, v| !*v || filter_is_bull(k));
    s.entry_primary_filters.retain(|k| filter_is_bull(k));
    s.option_side = "CE".into();
    // The daily cash-equity liquidity scan is this book's universe; leave its
    // master (`liquid_on`) and trade-count in the operator's control but keep
    // them inside a sane band.
    s.liquid_trade_count = s.liquid_trade_count.clamp(1, 500);
    if hhmm_to_minutes(&s.liquid_scan_time).is_none() {
        s.liquid_scan_time = "09:20".into();
    }
    s.liquid_scan_min_turnover_cr = s.liquid_scan_min_turnover_cr.max(0.0);
    s.filter_mode = true;
}

// ---------------------------------------------------------------------------
// Broker-side account cache
// ---------------------------------------------------------------------------

/// One aggregated "why didn't this entry fire" reason.
///
/// Every gate in `scan_signals` that silently drops a signal records here, so
/// the UI can show the operator the CURRENT blocking reason (with a live count
/// and the last detail) instead of a quiet engine with no explanation. Rows are
/// keyed by a coarse reason code so repeated drops for different strategies
/// collapse into one line; the detail keeps the newest concrete message.
#[derive(Clone, Debug)]
pub(crate) struct BlockerRow {
    /// Severity: `info` for a normal held/skip gate, `warn` for a hard block
    /// the operator probably needs to change a setting to clear.
    pub level: &'static str,
    /// Short human label for the reason (stable, used as the row key).
    pub code: String,
    /// Newest concrete detail (strategy name, numbers, exact gate text).
    pub detail: String,
    /// How many times this gate dropped a signal since the last reset (counted
    /// at most once per second, so a 100ms scan cadence does not inflate it).
    pub count: u64,
    /// Epoch ms of the most recent drop.
    pub last_ms: i64,
    /// Epoch ms when this reason was first seen in the current run.
    pub first_ms: i64,
    /// Epoch ms of the last `count` increment, kept separate from `last_ms` so
    /// the once-per-second count throttle still works while `last_ms` tracks
    /// the newest observation.
    pub last_count_ms: i64,
    /// Up to a few example strategy names this happened to.
    pub samples: Vec<String>,
}

#[derive(Clone)]
pub struct RealtimeState {
    pub dhan: DhanState,
    /// Paper-trading mode: the exact same engine/signals/risk logic, but every
    /// execution touchpoint (entry fill, exit fill, broker reconciliation,
    /// account/margin wallet) is simulated locally instead of sent to Dhan.
    pub paper: bool,
    /// Durable state-file name for THIS engine (see the `STATE_FILE_*` consts).
    /// Stored so `save()` persists each independent engine to its own file.
    state_file: &'static str,
    doc: Arc<Mutex<RtDoc>>,
    /// Universal saved-template pool shared by all engine tabs.
    template_pool: TemplatePool,
    ltp: Arc<Mutex<HashMap<i64, f64>>>,
    broker_positions: Arc<Mutex<Vec<Value>>>,
    broker_holdings: Arc<Mutex<Vec<Value>>>,
    funds: Arc<Mutex<Value>>,
    last_funds: Arc<AtomicI64>,
    last_ltp: Arc<AtomicI64>,
    /// Last broker fill-reconciliation poll (ms), so the order book is not
    /// fetched every 100ms loop tick.
    last_fills: Arc<AtomicI64>,
    /// Last broker Super-Order poll (ms), kept at 1s like the order book.
    last_super: Arc<AtomicI64>,
    /// Last post-reconnect broker resync (ms), so a websocket that flaps does
    /// not re-issue the order-book / positions fetch on every blip.
    last_reconnect: Arc<AtomicI64>,
    /// Previous Dhan connection / feed-up flag, used to fire `reconcile_reconnect`
    /// on the false -> true edge (a fresh Connect, or a feed that came back).
    was_conn: Arc<AtomicBool>,
    was_feed: Arc<AtomicBool>,
    last_sig: Arc<Mutex<HashMap<String, i64>>>,
    /// Entry-signal consumed latch: strategy id -> whether the current signal has
    /// already been consumed (order queued, or a margin block swallowed it). Used
    /// by the legacy single-position fallback, the margin "no late entry" path and
    /// the delayed-entry edge release. The multi-position "fresh signal" mode now
    /// keys its entry rate on `sig_bar` (one fresh position per new bar) instead
    /// of this latch.
    sig_state: Arc<Mutex<HashMap<String, bool>>>,
    /// Per-bar "fresh signal" cursor for the multi-position "fresh signal" mode:
    /// strategy id -> the bar bucket (`time_ms / bar_ms`) in which its last fresh
    /// signal was consumed. A new position is allowed on the NEXT new bar (bucket
    /// change) while the entry gate still holds, so a signal that keeps holding
    /// opens exactly one position per bar instead of only once ever or one every
    /// scan tick. Keyed on the bar so intra-bar ticks never stack.
    sig_bar: Arc<Mutex<HashMap<String, i64>>>,
    /// Signal-end debounce: strategy id -> millisecond timestamp when its leg's
    /// gate was FIRST seen failing on the current run of failures. A single-scan
    /// flicker must not end the signal, so the pulse is only reset once the gate
    /// has stayed false continuously for `SIGNAL_END_DEBOUNCE_MS`. The entry
    /// clears the marker, so a brief dip inside one signal keeps it running.
    sig_fail_since: Arc<Mutex<HashMap<String, i64>>>,
    /// Rate-limit drop latch: strategy id -> millisecond timestamp when its
    /// current signal was DROPPED because the orders/sec window was saturated.
    /// Unlike a held/queued entry (which would fill seconds later at a worse
    /// price), a rate-limited entry is skipped outright and must NOT be retried
    /// on the next scan tick. The latch is cleared only when the signal resets
    /// (the gate stops holding), so the next genuine fresh signal is allowed.
    rl_skip: Arc<Mutex<HashMap<String, i64>>>,
    /// "Repeat-entry latch" arm state: strategy id -> whether a new entry is
    /// armed. Starts armed (an absent key reads as armed); an entry disarms it,
    /// and it only re-arms after the strategy's gate has been continuously OFF
    /// for `entry_latch_secs`.
    entry_latch_armed: Arc<Mutex<HashMap<String, bool>>>,
    /// "Repeat-entry latch" OFF timer: strategy id -> millisecond timestamp when
    /// its gate was FIRST seen OFF after being disarmed. Removed the moment the
    /// gate is seen ON again, so the OFF run must be continuous to re-arm.
    entry_latch_off_since: Arc<Mutex<HashMap<String, i64>>>,
    /// "Re-entry cooldown": strategy id -> epoch ms until which a new entry on
    /// that strategy is blocked after its last position closed.
    entry_cooldown_until: Arc<Mutex<HashMap<String, i64>>>,
    /// Cached ATR per `security:segment:instrument:timeframe` `(at_ms, atr)`.
    /// AI SL/TP/trail reuse a recent ATR instead of paying a throttled Dhan
    /// candle round-trip on every entry (that fetch was a 3-10s entry lag).
    atr_cache: Arc<Mutex<HashMap<String, (i64, f64)>>>,
    /// Cached Live Data Pool readout `(at_ms, payload)`; short TTL so the 2s UI
    /// poll never hammers Dhan and starves the chart's candle fetches.
    pool_cache: Arc<Mutex<(i64, Value)>>,
    /// Guards the background Data Pool refresh so the endpoint never blocks the
    /// caller on the ~12 throttled Dhan candle fetches a compute needs.
    pool_busy: Arc<AtomicBool>,
    /// Latest movers bias: 0 balanced/unknown, +1 gainers lead, -1 losers lead.
    mover_bias: Arc<AtomicI64>,
    last_movers: Arc<AtomicI64>,
    /// Millisecond clock of the last REST fallback the scanner universe paid for
    /// while the live feed was NOT streaming. Without this the engine re-fetched
    /// the whole universe every ~100ms tick while the feed was down, which kept
    /// Dhan's rate limit tripped and made the disconnect permanent.
    last_scan_rest: Arc<AtomicI64>,
    /// Millisecond clock of the last COMPLETED `scan_signals` pass, plus a
    /// monotonic counter of passes started and of entries actually placed.
    /// Used by the "Why no trades?" diagnostics to prove the scan is alive
    /// (heartbeat) instead of silently dead - the one failure mode the blocker
    /// panel cannot see, because a dead scan records no blocker at all.
    scan_heartbeat: Arc<AtomicI64>,
    /// Millisecond clock of the last engine-loop iteration. Proves the loop
    /// itself is alive even while the engine is OFF / disarmed (in which case no
    /// scan and therefore no heartbeat would exist).
    loop_heartbeat: Arc<AtomicI64>,
    /// Times the engine loop went around since boot.
    loop_passes: Arc<AtomicI64>,
    scan_passes: Arc<AtomicI64>,
    entries_placed: Arc<AtomicI64>,
    /// Millisecond clock of the last entry that reached the broker (paper or
    /// live), for the "no entry for N minutes" auto-capture trigger.
    last_entry_ms: Arc<AtomicI64>,
    /// Throttle for the MCX commodity "Picked Strikes" refresh (millisecond
    /// clock). Kept separate from `last_movers` so the commodity rows are
    /// populated even when Top Movers is OFF.
    last_commodity: Arc<AtomicI64>,
    /// Last brain recomputation (ms), so the ranking walk runs at most once a
    /// minute instead of on every scan tick.
    last_brain: Arc<AtomicI64>,
    /// Cached movers rows for the UI `(at_ms, payload)`.
    movers_cache: Arc<Mutex<(i64, Value)>>,
    /// Cached Liquid-F&O scanner rows for the UI `(at_ms, payload)`. Kept apart
    /// from `movers_cache` because it ranks a different universe (liquid index
    /// constituents only) and drives its own leg set.
    liquid_cache: Arc<Mutex<(i64, Value)>>,
    /// Last Liquid-F&O scan (ms), throttled like the Top Movers pass.
    last_liquid: Arc<AtomicI64>,
    /// Daily full-universe cash-equity liquidity scan result for the Equity
    /// Indicator Based Trade book `(at_ms, payload)`. The payload carries the
    /// ranked stock rows (`stocks`), the scan timestamp and the day-key it was
    /// computed for (`day`), so the engine only reruns it once per IST day (or
    /// when the operator forces a refresh). Deliberately separate from
    /// `liquid_cache`, which the F&O engines rank by intraday gainers/losers.
    equity_liquidity_cache: Arc<Mutex<(i64, Value)>>,
    /// Guard so the (heavy) full-universe liquidity scan can never run twice
    /// concurrently.
    equity_liquidity_busy: Arc<AtomicBool>,
    /// Set by the "Scan now" button: forces the next liquidity scan to run even
    /// before the daily scan time (or after it already ran today).
    equity_liquidity_force: Arc<AtomicBool>,
    /// Last daily equity-liquidity scan attempt (ms), its own cadence clock so it
    /// never fights the F&O Liquid scanner's `last_liquid` throttle.
    last_equity_liquidity: Arc<AtomicI64>,
    /// Pre-scanned "Leg Book": per Top-Movers underlying (keyed by its security
    /// id) the green + fastest-rising strike resolved once when the stock is
    /// picked. Entries are frozen and reused by every entry until the pick, its
    /// side, the nearest expiry or the chosen strike's plus sign changes.
    leg_book: Arc<Mutex<HashMap<i64, BookLeg>>>,
    /// NIFTY trend-following direction derived from the selected straight-line
    /// indicators: 0 neutral, +1 bullish (trade Top Gainers), -1 bearish (trade
    /// Top Losers).
    nifty_dir: Arc<AtomicI64>,
    /// Composite range-regime flag for "No trade on sideways trend". Only used
    /// while the setting is ON; refreshed from the live NIFTY series and
    /// fail-closed (true) when the series cannot be read.
    nifty_sideways: Arc<AtomicBool>,
    /// Last sideways readout `{on, sideways, adx, chop, slopeAtr, rangeAtr,
    /// score}` for the status header.
    nifty_sideways_read: Arc<Mutex<Value>>,
    /// Throttle for the NIFTY sideways refresh (ms clock).
    last_sideways_scan: Arc<AtomicI64>,
    /// Straight-line indicators currently reading bullish. A bullish line is
    /// assigned to the Top Gainer side, so only it gates the gainer legs.
    nifty_bull_filters: Arc<Mutex<Vec<String>>>,
    /// Straight-line indicators currently reading bearish - assigned to the Top
    /// Loser side.
    nifty_bear_filters: Arc<Mutex<Vec<String>>>,
    /// Net direction of the COMMITTED straight-line read (0 = the committed side
    /// read a tie / none). Refreshed from each confirmed read rather than the raw
    /// per-tick flicker, so the strict net-direction gate blocks on a real change
    /// of side - not on a millisecond wiggle of the live forming bar.
    nifty_raw_net: Arc<AtomicI64>,
    /// All-lines-agree state of the assigned straight-line confirmation
    /// indicators: +1 when every line reads bullish (bull set non-empty, bear set
    /// empty), -1 when every line reads bearish, 0 when the read is mixed / tied
    /// / unavailable. Drives the strict all-lines-agree gate.
    nifty_agree: Arc<AtomicI64>,
    /// Live BB%b OB/OS zone REGIME used as an entry gate by the BB%b (Pane)
    /// confirmation modes: +1 while the zone is oversold (CE location), -1 while
    /// overbought (PE location), 0 while no enabled zone crossing has committed
    /// yet. This never sets the NIFTY direction; it only confirms which side the
    /// NIFTY Trend Following direction has already chosen may enter.
    nifty_zone_dir: Arc<AtomicI64>,
    /// Live BB%b (Pane) line-trend REGIME used as an entry gate by the BB%b
    /// confirmation modes: +1 while the line's newest segment is rising (green,
    /// bullish / CE location), -1 while falling (red, bearish / PE location), 0
    /// while flat / not warm. Like `nifty_zone_dir` this is a pure gate - the
    /// BB%b pane can never set or override the NIFTY direction.
    nifty_bbpct_line_dir: Arc<AtomicI64>,
    last_trend: Arc<AtomicI64>,
    last_nifty_scan: Arc<AtomicI64>,
    /// Cached NIFTY-trend pick rows `(at_ms, payload)` for the UI + pick tagging.
    nifty_picks: Arc<Mutex<(i64, Value)>>,
    /// Paper Trade 2 per-instrument trend following: cached `(at_ms, payload)`
    /// where payload is `[{securityId, side}]` for each added index / commodity
    /// whose OWN confirmation-indicator trend resolved a committed side.
    index_trend_picks: Arc<Mutex<(i64, Value)>>,
    comm_trend_picks: Arc<Mutex<(i64, Value)>>,
    /// Per-instrument trend readout for the UI: `[{securityId, name, trend,
    /// leg, flipped, prevLeg, flippedAt, ...}]` for every added index/commodity,
    /// including neutral reads. Published by `refresh_index_comm_trends`.
    index_trend_status: Arc<Mutex<Value>>,
    comm_trend_status: Arc<Mutex<Value>>,
    /// Last committed leg + last flip time per instrument, used to detect a
    /// CE<->PE leg flip and keep showing it after the flip. A neutral read does
    /// not erase the last committed leg.
    index_trend_last: Arc<Mutex<HashMap<i64, (String, i64, String)>>>,
    comm_trend_last: Arc<Mutex<HashMap<i64, (String, i64, String)>>>,
    /// Throttle (ms clock) for the per-instrument trend refresh.
    last_inst_trend: Arc<AtomicI64>,
    /// Last NIFTY trend-change signal: `{from,to,at,seq}` where `from`/`to` are
    /// 0 / +1 / -1. Bumped the instant the assigned straight-line indicators flip,
    /// so running strategies can switch leg + strikes without waiting for a bar.
    nifty_flip: Arc<Mutex<Value>>,
    /// Monotonic counter of NIFTY trend flips (never resets while the engine runs).
    nifty_seq: Arc<AtomicI64>,
    /// Throttle for the tick-native NIFTY flip watchdog (millisecond clock).
    last_nifty_flip: Arc<AtomicI64>,
    /// Throttle for the colour-based NIFTY confirmation scan. When colour mode is
    /// ON the assigned straight-line indicators' colour is re-read on this fixed
    /// cadence (see `COLOR_SCAN_MS`) instead of on every tick.
    last_color_scan: Arc<AtomicI64>,
    /// Candidate next NIFTY direction awaiting confirmation (0 = none pending).
    /// Set the first time a read disagrees with the committed side; only becomes
    /// the committed side once it has persisted `NIFTY_FLIP_CONFIRM_MS`.
    nifty_pending_dir: Arc<AtomicI64>,
    /// Millisecond clock when `nifty_pending_dir` was first read.
    nifty_pending_since: Arc<AtomicI64>,
    /// Millisecond clock when the live read first came back as a tie / no-vote
    /// while a side was committed. A tie HOLDS the committed side (never frees
    /// both legs), but a tie that lasts `NIFTY_TIE_CLEAR_MS` means the
    /// confirmation indicators no longer resolve a direction at all, so the side
    /// is dropped and the next resolved read re-arms from neutral.
    nifty_zero_since: Arc<AtomicI64>,
    /// Per-indicator votes of the last NIFTY trend read:
    /// `[{id, side}]` with side 1 = bullish, -1 = bearish, 0 = flat/unresolved.
    /// Readout only - never feeds the gate.
    nifty_votes: Arc<Mutex<Value>>,
    /// Order timestamps (ms) in the last second, powering the orders/sec cap.
    order_times: Arc<Mutex<Vec<i64>>>,
    /// Paper-only simulated entry latency: strategy id -> due ms for entries
    /// currently queued by `queue_delayed_entry`. The map doubles as the
    /// in-flight guard so the 100ms scanner never queues the same strategy
    /// twice while its delayed order is still pending.
    paper_pending: Arc<Mutex<HashMap<String, i64>>>,
    /// Paper-only simulated exit latency: position id -> due ms for exits
    /// currently queued by `queue_delayed_exit`. Doubles as the in-flight guard
    /// so the position manager cannot queue the same stop exit twice while its
    /// delayed order is still pending.
    paper_exit_pending: Arc<Mutex<HashMap<String, i64>>>,
    /// Cached broker margin-calculator responses `(at_ms, price, Option<resp>)`.
    /// Dhan's margin API is throttled to ~1 call/second, so without this every
    /// option-chain / instrument switch paid that round-trip and the chart load
    /// queued behind it. The requirement moves slowly, so a short TTL is safe;
    /// `None` is cached too so a rejected contract (e.g. an index) does not
    /// re-throttle on every switch.
    margin_cache: Arc<Mutex<HashMap<String, (i64, f64, Option<MarginResponse>)>>>,
    /// Cached scanner/strategy option legs `(at_ms, rows)` powering the "Picked
    /// Strikes" readout - every resolved CE/PE contract the engine will execute.
    picked_strikes: Arc<Mutex<(i64, Vec<Value>)>>,
    /// Last option-premium leg the engine resolved per running strategy, keyed
    /// `strategyId -> { run, trade }`. Powers the Running Strategies view so each
    /// row can name (and open) the exact chart it evaluates the entry on and
    /// executes the order on - spot strategies fall back to the strategy's own
    /// instrument, so only the resolved premium contracts need caching here.
    strat_legs: Arc<Mutex<HashMap<String, Value>>>,
    /// Entry-timing diagnostics: strategy id -> `(metAt_ms, orders_at_meet)` for
    /// the currently-armed filter-alignment episode.
    et_pending: Arc<Mutex<HashMap<String, (i64, i64)>>>,
    /// Whole-engine counter of AST orders placed, used for the entry-timing
    /// "orders placed in this window" column.
    et_placed: Arc<AtomicI64>,
    /// "Why aren't trades firing?" blocker tracker: block reason -> aggregated
    /// row (count, last seen, level, latest detail, sample strategy names).
    /// Fed from every gate that silently drops a signal, so the UI can explain
    /// the current reason instead of leaving the operator with a quiet engine.
    blockers: Arc<Mutex<HashMap<String, BlockerRow>>>,
    /// Throttle map for repeated skip/diagnostic log lines (key -> last ms).
    log_throttle: Arc<Mutex<HashMap<String, i64>>>,
    /// Set by `POST /api/rt/tick` ("Run / Tick Now"): the engine loop consumes
    /// it to perform one immediate evaluation pass instead of waiting for the
    /// next scheduled tick.
    force_tick: Arc<AtomicBool>,
    /// Millisecond clock of the last COMPLETED background scanner refresh pass.
    /// The scanner REST work (Top Movers / Liquid F&O / trend sections) used to
    /// run inline in the engine loop, so a Dhan rate-limit hold blocked the whole
    /// loop and froze entries entirely. It now runs on its own task and the loop
    /// only reads the caches, flagging a stale pass instead of stalling.
    scanner_heartbeat: Arc<AtomicI64>,
    /// Guard so two background scanner passes can never overlap (the previous
    /// pass may still be waiting out a Dhan hold).
    scanner_busy: Arc<AtomicBool>,
    /// Candle series currently warming from a background REST seed, keyed by
    /// `"{exch}:{sec}:{tf}"`. The evaluation loop never blocks on that seed: it
    /// reads the live series and, when cold, asks for a background fetch and
    /// evaluates on the next pass instead. A synchronous seed inside the scan was
    /// one of the ways a slow / rate-limited Dhan call froze the whole engine.
    seed_inflight: Arc<Mutex<std::collections::HashSet<String>>>,
    /// Negative cache for option-leg resolution: `"{security_id}:{side}"` -> the
    /// epoch ms at which a resolve last came back with no contract (missing
    /// expiry / empty strike bucket / all strikes red). Without it a stock whose
    /// premium leg cannot be resolved is re-resolved on EVERY scan tick (100ms),
    /// which is what produced hundreds of `no-premium` blocker hits and kept the
    /// option chain / quote surface busy.
    no_premium_until: Arc<Mutex<HashMap<String, i64>>>,
}

/// One row of the per-instrument trend readout. `prev` is the instrument's last
/// committed `(leg, last_flip_ms, leg_before_that_flip)`: a differing new leg is
/// a CE<->PE flip, while a neutral read keeps showing the last committed leg and
/// the last flip. Returns the JSON row plus the new map entry to keep (None for a
/// neutral read, so the last leg survives).
#[cfg(test)]
fn inst_trend_status_row(
    sid: i64,
    name: &str,
    dir: i64,
    prev: Option<&(String, i64, String)>,
    now: i64,
    inds: &[String],
) -> (Value, Option<(String, i64, String)>) {
    inst_trend_status_row_votes(sid, name, dir, prev, now, inds, &[])
}

/// [`inst_trend_status_row`] plus each confirmation indicator's vote, so the
/// readout can show WHY an instrument reads BULLISH / BEARISH / NEUTRAL.
fn inst_trend_status_row_votes(
    sid: i64,
    name: &str,
    dir: i64,
    prev: Option<&(String, i64, String)>,
    now: i64,
    inds: &[String],
    votes: &[(String, i8)],
) -> (Value, Option<(String, i64, String)>) {
    let side = if dir > 0 {
        "CE"
    } else if dir < 0 {
        "PE"
    } else {
        ""
    };
    let prev_side = prev.map(|(s, _, _)| s.as_str()).unwrap_or("");
    let prev_flip_at = prev.map(|(_, t, _)| *t).unwrap_or(0);
    let prev_flip_from = prev.map(|(_, _, f)| f.as_str()).unwrap_or("");
    let flipped = !side.is_empty() && !prev_side.is_empty() && prev_side != side;
    let flipped_at = if flipped { now } else { prev_flip_at };
    let flip_from = if flipped { prev_side } else { prev_flip_from };
    let trend = if dir > 0 {
        "BULLISH"
    } else if dir < 0 {
        "BEARISH"
    } else {
        "NEUTRAL"
    };
    let row = json!({
        "securityId": sid,
        "name": name,
        "trend": trend,
        "dir": dir,
        "leg": side,
        "lastLeg": if side.is_empty() { prev_side } else { side },
        "flipFrom": flip_from,
        "newLeg": !side.is_empty() && prev_side.is_empty(),
        "flipped": flipped,
        "flippedAt": flipped_at,
        "indicators": inds,
        "votes": votes
            .iter()
            .map(|(id, side)| json!({ "id": id, "side": side }))
            .collect::<Vec<Value>>(),
    });
    let next = if side.is_empty() {
        None
    } else {
        Some((side.to_string(), flipped_at, flip_from.to_string()))
    };
    (row, next)
}

/// Composite range-regime read used by the "No trade on sideways trend"
/// switch. Four independent signals vote:
///   * ADX(14) below 20 (no directional strength) - weight 2
///   * Choppiness(14) above 61.8 (overlapping bars) - weight 2
///   * |EMA20 slope over 10 bars| below 0.15 ATR (flat mean) - weight 2
///   * 20-bar high-low range below 2.5 ATR (compressed range) - weight 1
///   * close within 0.5 ATR of EMA20 (balanced around the mean) - weight 1
/// A score of 3 or more is sideways. That needs at least one strong pair, so a
/// single quiet indicator can never block a genuine trend, while a true range
/// (low ADX + high chop, or flat slope + high chop) is caught.
#[derive(Clone, Copy, Debug)]
struct SidewaysRead {
    sideways: bool,
    adx: f64,
    chop: f64,
    slope_atr: f64,
    range_atr: f64,
    score: i32,
}

impl SidewaysRead {
    fn reason(&self) -> String {
        format!(
            "sideways regime (ADX {:.1}, CHOP {:.1}, EMA slope {:.2} ATR, 20-bar range {:.2} ATR)",
            self.adx, self.chop, self.slope_atr, self.range_atr
        )
    }
}

fn candle_true_range(c: &[Candle], i: usize) -> f64 {
    if i == 0 {
        return (c[0].high - c[0].low).max(0.0);
    }
    (c[i].high - c[i].low)
        .max((c[i].high - c[i - 1].close).abs())
        .max((c[i].low - c[i - 1].close).abs())
}

/// Simple average true range over the last `period` bars (regime reads only, so
/// the plain average is sufficient and avoids a second Wilder state machine).
fn regime_atr(c: &[Candle], period: usize) -> Option<f64> {
    if period == 0 || c.len() < period + 1 {
        return None;
    }
    let start = c.len() - period;
    let sum: f64 = (start..c.len()).map(|i| candle_true_range(c, i)).sum();
    let atr = sum / period as f64;
    if atr.is_finite() && atr > 0.0 {
        Some(atr)
    } else {
        None
    }
}

/// Wilder ADX. Needs at least `2 * period` candles to produce a stable value.
fn adx_last(c: &[Candle], period: usize) -> Option<f64> {
    if period < 2 || c.len() < period * 2 {
        return None;
    }
    let mut trs = Vec::with_capacity(c.len() - 1);
    let mut pdms = Vec::with_capacity(c.len() - 1);
    let mut ndms = Vec::with_capacity(c.len() - 1);
    for i in 1..c.len() {
        let up = c[i].high - c[i - 1].high;
        let down = c[i - 1].low - c[i].low;
        pdms.push(if up > down && up > 0.0 { up } else { 0.0 });
        ndms.push(if down > up && down > 0.0 { down } else { 0.0 });
        trs.push(candle_true_range(c, i));
    }
    if trs.len() < period * 2 - 1 {
        return None;
    }
    let mut tr_s: f64 = trs[..period].iter().sum();
    let mut pdm_s: f64 = pdms[..period].iter().sum();
    let mut ndm_s: f64 = ndms[..period].iter().sum();
    let mut dxs: Vec<f64> = Vec::new();
    let dx_at = |tr_s: f64, pdm_s: f64, ndm_s: f64| -> f64 {
        if tr_s <= 0.0 {
            return 0.0;
        }
        let pdi = 100.0 * pdm_s / tr_s;
        let ndi = 100.0 * ndm_s / tr_s;
        if pdi + ndi <= 0.0 {
            0.0
        } else {
            100.0 * (pdi - ndi).abs() / (pdi + ndi)
        }
    };
    dxs.push(dx_at(tr_s, pdm_s, ndm_s));
    for i in period..trs.len() {
        tr_s = tr_s - tr_s / period as f64 + trs[i];
        pdm_s = pdm_s - pdm_s / period as f64 + pdms[i];
        ndm_s = ndm_s - ndm_s / period as f64 + ndms[i];
        dxs.push(dx_at(tr_s, pdm_s, ndm_s));
    }
    if dxs.len() < period {
        return None;
    }
    let mut adx: f64 = dxs[..period].iter().sum::<f64>() / period as f64;
    for dx in &dxs[period..] {
        adx = (adx * (period as f64 - 1.0) + dx) / period as f64;
    }
    adx.is_finite().then_some(adx)
}

/// Choppiness index (0..100): high values mean the path covers little net
/// distance relative to its true range, i.e. a range / sideways market.
fn choppiness_last(c: &[Candle], period: usize) -> Option<f64> {
    if period < 2 || c.len() < period + 1 {
        return None;
    }
    let start = c.len() - period;
    let mut sum_tr = 0.0;
    let mut hi = f64::MIN;
    let mut lo = f64::MAX;
    for i in start..c.len() {
        sum_tr += candle_true_range(c, i);
        hi = hi.max(c[i].high);
        lo = lo.min(c[i].low);
    }
    let span = hi - lo;
    if span <= 0.0 || sum_tr <= 0.0 {
        return None;
    }
    let ci = 100.0 * (sum_tr / span).log10() / (period as f64).log10();
    ci.is_finite().then_some(ci)
}

fn ema_value(c: &[Candle], period: usize) -> Option<f64> {
    if period == 0 || c.len() < period {
        return None;
    }
    let k = 2.0 / (period as f64 + 1.0);
    let mut e = c[0].close;
    for x in &c[1..] {
        e = x.close * k + e * (1.0 - k);
    }
    e.is_finite().then_some(e)
}

fn sideways_read(c: &[Candle]) -> Option<SidewaysRead> {
    if c.len() < 35 {
        return None;
    }
    let adx = adx_last(c, 14)?;
    let chop = choppiness_last(c, 14)?;
    let atr = regime_atr(c, 14)?;
    let ema = ema_value(c, 20)?;
    let ema_prev = ema_value(&c[..c.len().saturating_sub(10)], 20)?;
    let slope_atr = (ema - ema_prev).abs() / atr;
    let start = c.len() - 20;
    let hi = c[start..].iter().map(|x| x.high).fold(f64::MIN, f64::max);
    let lo = c[start..].iter().map(|x| x.low).fold(f64::MAX, f64::min);
    let range_atr = (hi - lo) / atr;
    let near_ema = (c[c.len() - 1].close - ema).abs() / atr;
    let mut score = 0;
    if adx < 20.0 {
        score += 2;
    }
    if chop > 61.8 {
        score += 2;
    }
    if slope_atr < 0.15 {
        score += 2;
    }
    if range_atr < 2.5 {
        score += 1;
    }
    if near_ema < 0.5 {
        score += 1;
    }
    Some(SidewaysRead {
        sideways: score >= 3,
        adx,
        chop,
        slope_atr,
        range_atr,
        score,
    })
}

/// Verdict of the "ignore fake breakouts / reversals" filter. `fake` = the
/// move is a small blip that must not open a NEW trade; `reason` explains why
/// (surfaced in the entry-blocker log). When the filter is OFF the caller never
/// invokes this, so a false verdict can never affect legacy behaviour.
struct FakeMoveRead {
    fake: bool,
    reason: &'static str,
    adx: f64,
    chop: f64,
    move_atr: f64,
}

/// Evaluate whether the newest price action on `c` is a genuine trend move in
/// the `bull` direction, or a fake breakout / fake reversal that should be
/// ignored. Every check is fail-OPEN on missing data (returns `fake = false`
/// when a series/regime cannot be measured) so a thin feed never silently
/// blocks every entry; only measurable contradictions mark a move fake.
///
/// Checks, in order (first failure wins):
///  1. Persistence: the last `bars` closed candles must ALL close on `bull`'s
///     side of the window's open - a one-bar flip is a fake reversal.
///  2. ATR displacement: the net move must be >= `atr_mult` x ATR - a poke
///     smaller than noise is a fake breakout.
///  3. Structure: bull needs higher-high + higher-low vs the prior bar, bear
///     the mirror - a lone close without structure is not a trend.
///  4. Volume: the newest closed candle must carry >= `vol_mult` x the window's
///     average volume (skipped when the series has no volume data).
///  5. Regime: ADX >= `adx_min` and chop <= `chop_max` - blocks entries inside
///     a choppy / range-bound tape even when a candle pokes out.
fn anti_fake_read(c: &[Candle], bull: bool, s: &Settings) -> FakeMoveRead {
    let bars = s.anti_fake_bars.clamp(1, 20);
    let atr_mult = s.anti_fake_atr_mult.clamp(0.0, 5.0);
    let vol_mult = s.anti_fake_vol_mult.clamp(0.0, 5.0);
    let adx_min = s.anti_fake_adx_min.clamp(0.0, 100.0);
    let chop_max = s.anti_fake_chop_max.clamp(0.0, 100.0);
    let neutral = FakeMoveRead { fake: false, reason: "", adx: 0.0, chop: 0.0, move_atr: 0.0 };
    if c.len() < 35 {
        return neutral;
    }
    let Some(atr) = regime_atr(c, 14) else { return neutral };
    let Some(adx) = adx_last(c, 14) else { return neutral };
    let Some(chop) = choppiness_last(c, 14) else { return neutral };
    let n = c.len();
    let win = bars.min(n - 1);
    let base = c[n - 1 - win];
    let last = c[n - 1];
    let prev = c[n - 2];
    let move_atr = (last.close - base.open).abs() / atr;
    let read = |fake: bool, reason: &'static str| FakeMoveRead { fake, reason, adx, chop, move_atr };

    // 1. Persistence: every bar in the window must close on the entry's side.
    for i in (n - win)..n {
        let up = c[i].close > c[i].open;
        let down = c[i].close < c[i].open;
        if bull && !up {
            return read(true, "no persistent bullish closes - fake reversal/blip");
        }
        if !bull && !down {
            return read(true, "no persistent bearish closes - fake reversal/blip");
        }
    }
    // 1b. Cooldown right after a flip: if the newest bar's side differs from the
    //     immediately preceding bars, a fresh reversal just printed. Require at
    //     least `cooldown` bars of the new side before trusting it, so the small
    //     flip that always follows a real turn is not traded as its own signal.
    let cooldown = s.anti_fake_cooldown_bars.clamp(0, 50);
    if cooldown > 0 {
        let side_at = |i: usize| -> i8 {
            if c[i].close > c[i].open { 1 } else if c[i].close < c[i].open { -1 } else { 0 }
        };
        let cur_side = if bull { 1 } else { -1 };
        let mut run = 0usize;
        let mut i = n;
        while i > 0 {
            i -= 1;
            if side_at(i) == cur_side {
                run += 1;
            } else {
                break;
            }
        }
        if run < cooldown {
            return read(true, "too soon after a side flip - small reversal cooldown");
        }
    }
    // 2. ATR displacement across the window.
    if move_atr < atr_mult {
        return read(true, "net move smaller than ATR multiple - fake breakout");
    }
    // 3. Structure: newest closed bar must make the trend's own swing.
    if bull && !(last.high > prev.high && last.low > prev.low) {
        return read(true, "no higher-high/higher-low structure - fake breakout");
    }
    if !bull && !(last.high < prev.high && last.low < prev.low) {
        return read(true, "no lower-high/lower-low structure - fake breakout");
    }
    // 4. Wick rejection: the candle must not close back inside the prior range
    //    (a long rejection wick = a failed breakout / reversal trap).
    let rng = (prev.high - prev.low).max(atr * 0.1);
    if bull && last.close < prev.high - 0.25 * rng {
        return read(true, "bullish close rejected back into range - fake breakout");
    }
    if !bull && last.close > prev.low + 0.25 * rng {
        return read(true, "bearish close rejected back into range - fake breakout");
    }
    // 5. Volume confirmation, only when the series actually carries volume. A
    //    candle carrying clearly less than `vol_mult` x the window average is a
    //    thin move the market did not follow (< 1.0 = "below average" guard).
    let vol_in_window: f64 = ((n - win - 1)..n).map(|i| c[i].volume).sum();
    if vol_in_window > 0.0 && last.volume > 0.0 {
        let avg = vol_in_window / (win + 1) as f64;
        if avg > 0.0 && last.volume < vol_mult * avg {
            return read(true, "breakout candle volume below average - thin fake move");
        }
    }
    // 6. Regime: must be trending, not choppy.
    if adx < adx_min {
        return read(true, "ADX below minimum - choppy tape, no real trend");
    }
    if chop > chop_max {
        return read(true, "Choppiness above maximum - range-bound, fake move");
    }
    FakeMoveRead { fake: false, reason: "", adx, chop, move_atr }
}

/// Process-wide registry of the constructed engines, keyed by engine id. The
/// diagnostics module uses it to inspect EVERY tab (paper included) from a
/// single JSON endpoint instead of one route per engine.
static ENGINES: OnceLock<Mutex<HashMap<&'static str, RealtimeState>>> = OnceLock::new();

fn engine_registry() -> &'static Mutex<HashMap<&'static str, RealtimeState>> {
    ENGINES.get_or_init(|| Mutex::new(HashMap::new()))
}

fn register_engine(state_file: &'static str, st: &RealtimeState) {
    let id = match state_file {
        STATE_FILE_REAL => "realtime",
        STATE_FILE_REAL2 => "realtime2",
        STATE_FILE_REAL3 => "realtime3",
        STATE_FILE_PAPER => "paper",
        STATE_FILE_PAPER2 => "paper2",
        STATE_FILE_PAPER3 => "paper3",
        STATE_FILE_PAPER4 => "paper4",
        STATE_FILE_AUTOEXP => "autoexp",
        STATE_FILE_AITRADER => "aitrader",
        STATE_FILE_AITRADERLIVE => "aitraderlive",
        _ => return,
    };
    if let Ok(mut m) = engine_registry().lock() {
        m.insert(id, st.clone());
    }
}

/// Every registered engine id, in tab order.
pub fn rt_engine_ids() -> Vec<&'static str> {
    vec!["realtime", "realtime2", "realtime3", "paper", "paper2", "paper3", "paper4", "autoexp", "aitrader", "aitraderlive"]
}

impl RealtimeState {
    pub fn new(dhan: DhanState) -> Self {
        Self::new_mode(dhan, false, STATE_FILE_REAL)
    }

    /// Paper-trade engine: identical logic, simulated execution + wallet, and a
    /// completely separate durable state file so paper strategies/settings never
    /// touch the real engine's book.
    pub fn new_paper(dhan: DhanState) -> Self {
        Self::new_mode(dhan, true, STATE_FILE_PAPER)
    }

    /// Second, fully independent paper-trade engine (`/api/paper2/*`): the same
    /// logic and simulated execution as `new_paper`, but its own durable state
    /// file and in-memory book, so it shares NO data with the first paper
    /// engine.
    pub fn new_paper2(dhan: DhanState) -> Self {
        Self::new_mode(dhan, true, STATE_FILE_PAPER2)
    }

    /// Third, fully independent paper-trade engine (`/api/paper3/*`): an exact
    /// clone of Paper Trade 2's indices + option-chain commodities engine, but
    /// with its own durable state file and in-memory book, so it executes its
    /// own simulated trades and shares NO data with any other engine.
    pub fn new_paper3(dhan: DhanState) -> Self {
        Self::new_mode(dhan, true, STATE_FILE_PAPER3)
    }

    /// Equity Indicator Based Trade (`/api/paper4/*`): an independent paper
    /// engine that trades ONLY liquid NSE cash EQUITY (spot, delivery) and is
    /// gated by the BULLISH indicator filters only. No indices, no F&O options,
    /// no commodities, no strikes / premium chart / option chain. Own durable
    /// state file and in-memory book - shares NO data with any other engine.
    pub fn new_paper4(dhan: DhanState) -> Self {
        Self::new_mode(dhan, true, STATE_FILE_PAPER4)
    }

    /// Auto Experiment engine (`/api/autoexp/*`): a complete, fully independent
    /// clone of Paper Trade. It runs the same AI Smart engine on the live Dhan
    /// feed with simulated execution over the full universe (stocks + indices +
    /// option-chain commodities), but has its own durable state file and
    /// in-memory book, so it shares NO data with any other engine.
    pub fn new_autoexp(dhan: DhanState) -> Self {
        Self::new_mode(dhan, true, STATE_FILE_AUTOEXP)
    }

    /// AI Trader (Paper) engine (`/api/aitrader/*`): an autonomous, deep-analysis
    /// engine. It runs the multi-factor brain over the operator's selected
    /// universe and places/cuts trades on its own with simulated execution. Own
    /// durable state file and in-memory book - shares NO data with any engine.
    pub fn new_aitrader(dhan: DhanState) -> Self {
        Self::new_mode(dhan, true, STATE_FILE_AITRADER)
    }

    /// AI Trader (Live) engine (`/api/aitraderlive/*`): the same autonomous,
    /// deep-analysis brain, but places REAL Dhan orders. Own durable state file
    /// and in-memory book - shares NO data with any engine.
    pub fn new_aitraderlive(dhan: DhanState) -> Self {
        Self::new_mode(dhan, false, STATE_FILE_AITRADERLIVE)
    }

    /// Second independent LIVE engine (`/api/realtime2/*`): places REAL Dhan
    /// orders, but its own durable state file and in-memory book, so it shares
    /// NO data with the first real engine. Same indices + option-chain
    /// commodities book as Paper Trade 2 (no Top Movers stocks).
    pub fn new_realtime2(dhan: DhanState) -> Self {
        Self::new_mode(dhan, false, STATE_FILE_REAL2)
    }

    /// Third independent LIVE engine (`/api/realtime3/*`): places REAL Dhan
    /// orders with its own durable state file and in-memory book. It runs the
    /// exact same indices + option-chain commodities engine as Paper Trade 2 /
    /// Realtime Trading Engine 2, but shares NO data with either of them.
    pub fn new_realtime3(dhan: DhanState) -> Self {
        Self::new_mode(dhan, false, STATE_FILE_REAL3)
    }

    /// Attach the process-wide universal template pool. Every engine tab gets the
    /// same `Arc`, so a template saved in one tab is visible in all of them.
    pub fn with_template_pool(mut self, pool: TemplatePool) -> Self {
        self.template_pool = pool;
        self
    }

    /// Stable engine key used to tag saved templates with their origin.
    fn engine_id(&self) -> &'static str {
        match self.state_file {
            STATE_FILE_REAL => "realtime",
            STATE_FILE_REAL2 => "realtime2",
            STATE_FILE_REAL3 => "realtime3",
            STATE_FILE_PAPER => "paper",
            STATE_FILE_PAPER2 => "paper2",
            STATE_FILE_PAPER3 => "paper3",
            STATE_FILE_PAPER4 => "paper4",
            STATE_FILE_AUTOEXP => "autoexp",
            STATE_FILE_AITRADER => "aitrader",
            STATE_FILE_AITRADERLIVE => "aitraderlive",
            _ => "engine",
        }
    }

    /// Human-readable origin shown next to a saved template.
    fn engine_label(&self) -> &'static str {
        match self.state_file {
            STATE_FILE_REAL => "Realtime Trading Engine",
            STATE_FILE_REAL2 => "Realtime Trading Engine 2",
            STATE_FILE_REAL3 => "Realtime Trading Engine 3",
            STATE_FILE_PAPER => "Paper Trade",
            STATE_FILE_PAPER2 => "Paper Trade 2",
            STATE_FILE_PAPER3 => "Paper Trade 3",
            STATE_FILE_PAPER4 => "Equity Indicator Based Trade",
            STATE_FILE_AUTOEXP => "Auto Experiment",
            STATE_FILE_AITRADER => "AI Trader (Paper)",
            STATE_FILE_AITRADERLIVE => "AI Trader (Live)",
            _ => "Engine",
        }
    }

    /// True for the engines that trade an indices + option-chain commodities only
    /// book (Paper Trade 2/3 and Realtime Trading Engine 2/3): no Top Movers
    /// stocks, no NIFTY Trend Following, no BB%b pane.
    fn indices_commodities_only(&self) -> bool {
        matches!(
            self.state_file,
            STATE_FILE_PAPER2 | STATE_FILE_PAPER3 | STATE_FILE_REAL2 | STATE_FILE_REAL3
        )
    }

    /// True for the engine that trades **indices only** (Paper Trade 2): the
    /// commodity picker, the commodity leg book and the Commodities Trend
    /// Following section are removed, so a saved file or a settings POST can
    /// never arm an MCX trade on that tab.
    fn indices_only(&self) -> bool {
        matches!(self.state_file, STATE_FILE_PAPER2)
    }

    /// True for the engine that trades **commodities only** (Paper Trade 3): the
    /// index picker, the Top Movers scan and the Indices Trend Following section
    /// are removed, so a saved file or a settings POST can never arm an index
    /// trade on that tab.
    fn commodities_only(&self) -> bool {
        matches!(self.state_file, STATE_FILE_PAPER3)
    }

    /// True for the Equity Indicator Based Trade engine (Paper Trade 4): it
    /// trades only liquid NSE cash equity (spot, delivery) and is gated by the
    /// bullish indicator filters only. There are no indices, no F&O options, no
    /// commodities, no strikes and no premium chart on this book.
    fn equity_indicators_only(&self) -> bool {
        matches!(self.state_file, STATE_FILE_PAPER4)
    }

    /// True for the Auto Experiment engine: the "Auto Trading (trend + SL +
    /// trail + target)" preset is removed from this tab only. A saved file or a
    /// settings POST can never arm it here; every other engine keeps the feature.
    fn auto_trade_removed(&self) -> bool {
        matches!(self.state_file, STATE_FILE_AUTOEXP)
    }

    /// True for the two AI Trader engines (paper + live). These tabs are
    /// autonomous: the multi-factor brain is always in charge, so the "Auto
    /// Trading (trend + filters + SL + trail + target)" preset is pinned ON and
    /// the operator sets only the universe (indices / commodities / F&O) and
    /// risk. The brain then ranks the filters, picks the side, sizes the trade
    /// and drives the adaptive exit on its own.
    fn ai_trader(&self) -> bool {
        matches!(self.state_file, STATE_FILE_AITRADER | STATE_FILE_AITRADERLIVE)
    }

    /// Whether the operator's index universe is part of this engine's scan. The
    /// equity-only book has no indices at all.
    fn allows_indices(&self) -> bool {
        !self.commodities_only() && !self.equity_indicators_only()
    }

    /// Whether the operator's commodity universe is part of this engine's scan.
    /// The equity-only book has no commodities at all.
    fn allows_commodities(&self) -> bool {
        !self.indices_only() && !self.equity_indicators_only()
    }

    /// Whether the Liquid F&O stock scanner belongs to this engine. Like the
    /// Top Movers stock scan, only the full engines (Realtime Trading Engine and
    /// Paper Trade 1) carry it - the indices-only / commodities-only books do
    /// not, and neither do RT2/RT3. The equity-only book DOES carry a stock
    /// scanner (its entire universe is stocks), so it is allowed here too.
    fn allows_liquid_stocks(&self) -> bool {
        !self.indices_commodities_only()
    }

    /// Every underlying the Liquid F&O list is currently showing: the scanner's
    /// own top gainers / top losers / hand-added names, plus the operator's
    /// explicit gainer / loser dropdown picks and saved adds. Top Movers must
    /// never re-list one of these stocks - the Liquid F&O list is the single
    /// owner of a shared stock, so the same common name can never sit in both
    /// readouts at once.
    fn liquid_owned_ids(&self, settings: &Settings) -> std::collections::HashSet<i64> {
        let mut owned = std::collections::HashSet::new();
        if !settings.liquid_on || !self.allows_liquid_stocks() {
            return owned;
        }
        let payload = self.liquid_cache.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
        for key in ["gainers", "losers", "added"] {
            for r in jarr(&payload, key) {
                let sid = ji(&r, "securityId");
                if sid > 0 {
                    owned.insert(sid);
                }
            }
        }
        for sid in &settings.liquid_list {
            if *sid > 0 {
                owned.insert(*sid);
            }
        }
        if settings.liquid_gainer > 0 {
            owned.insert(settings.liquid_gainer);
        }
        if settings.liquid_loser > 0 {
            owned.insert(settings.liquid_loser);
        }
        owned
    }

    /// Apply this engine's hard constraints to a settings blob that came from a
    /// save / import / template. The indices + commodities engines strip the
    /// stock / NIFTY-trend / BB%b features; every other engine is pinned to the
    /// Indicator-filters run mode and keeps only the F&O-stock routing.
    fn enforce_constraints(&self, s: &mut Settings) {
        if self.auto_trade_removed() {
            // Auto Experiment tab: the Auto Trading preset feature is removed.
            // A saved file or a raw POST can never re-arm it here; open trades
            // keep their existing SL / trail / target protection untouched.
            s.auto_trade_on = false;
        }
        if self.ai_trader() {
            // AI Trader tabs are autonomous: the brain must stay in charge of the
            // filter ranking / side / exits. Pinning Auto Trading ON here means a
            // raw settings POST or a restored file can never switch the brain
            // off and leave the engine trading stale filters. The universe and
            // risk fields the operator set are preserved.
            s.auto_trade_on = true;
            s.filter_mode = true;
        }
        if self.equity_indicators_only() {
            sanitize_equity_indicators(s);
        } else if self.indices_commodities_only() {
            sanitize_indices_commodities(s);
            if self.indices_only() {
                sanitize_indices_only(s);
            }
            if self.commodities_only() {
                sanitize_commodities_only(s);
            }
            s.filter_mode = true;
        } else {
            strip_realtime_pt1_extras(s);
            s.filter_mode = true;
        }
    }

    fn new_mode(dhan: DhanState, paper: bool, state_file: &'static str) -> Self {
        let path = state_path(state_file);
        // Read the durable file, else migrate a legacy /tmp state file if the
        // durable one does not exist yet.
        let mut doc = std::fs::read_to_string(&path)
            .ok()
            .or_else(|| {
                // Legacy /tmp migration applies to the real engine only; the
                // paper book must never inherit the real one.
                if paper {
                    return None;
                }
                let legacy = std::env::temp_dir().join("algodhan_realtime_state.json");
                if legacy != path {
                    std::fs::read_to_string(legacy).ok()
                } else {
                    None
                }
            })
            .and_then(|s| serde_json::from_str::<RtDoc>(&s).ok())
            .unwrap_or_default();
        // Old-app migration: a missing/non-positive "Max trades" count defaults
        // to 5 so ticking the box never silently means "no cap".
        if doc.settings.trade_limit_count <= 0 {
            doc.settings.trade_limit_count = 5;
        }
        // Orders/sec: 0 (or nonsense) means "unset" -> default 6; anything above
        // the Dhan ceiling is clamped to 30.
        if doc.settings.order_per_sec <= 0 {
            doc.settings.order_per_sec = 6;
        }
        doc.settings.order_per_sec = order_per_sec_budget(doc.settings.order_per_sec);
        // Engine Scan interval: keep it inside the floor/ceiling so a saved 0 or a
        // nonsense value can never make the engine spin or misbehave.
        doc.settings.scan_interval_ms = scan_interval_budget(doc.settings.scan_interval_ms);
        doc.settings.scan_bar_close_tf = scan_bar_close_tf(&doc.settings.scan_bar_close_tf).to_string();
        // Paper Trade 2/3 and Realtime Trading Engine 2/3 are indices +
        // option-chain commodities only: strip the stock scanner, NIFTY Trend
        // Following and the BB%b pane a saved file may carry.
        match state_file {
            STATE_FILE_PAPER4 => {
                sanitize_equity_indicators(&mut doc.settings);
            }
            STATE_FILE_PAPER2
            | STATE_FILE_PAPER3
            | STATE_FILE_REAL2
            | STATE_FILE_REAL3 => {
                sanitize_indices_commodities(&mut doc.settings);
                if state_file == STATE_FILE_PAPER2 {
                    sanitize_indices_only(&mut doc.settings);
                }
                if state_file == STATE_FILE_PAPER3 {
                    sanitize_commodities_only(&mut doc.settings);
                }
                doc.settings.filter_mode = true;
            }
            // Indicator-filters is the only run mode exposed in the UI, so every
            // other engine (Realtime + Paper Trade 1) is pinned to it, and the
            // removed Index / Commodity scanner state is stripped.
            _ => {
                strip_realtime_pt1_extras(&mut doc.settings);
                doc.settings.filter_mode = true;
            }
        }
        // Auto Experiment tab: the Auto Trading preset feature is removed from
        // this engine only, so a saved file can never re-arm it.
        if state_file == STATE_FILE_AUTOEXP {
            doc.settings.auto_trade_on = false;
        }
        // AI Trader engines are autonomous: the brain is always in charge, so the
        // Auto Trading preset is pinned ON. The universe + risk knobs stay the
        // operator's; the brain recomputes the filter ranking / side / exits on
        // every cycle. Pinning here means a saved file can never leave the AI tab
        // "on" with the brain switched off (which would trade stale filters).
        if matches!(state_file, STATE_FILE_AITRADER | STATE_FILE_AITRADERLIVE) {
            if !doc.settings.auto_trade_on {
                apply_auto_trade_preset(&mut doc.settings);
            }
            doc.settings.auto_trade_on = true;
        }
        // A stored `pointTrailBrokerOnly` from the old rule is cleared ONLY when
        // the position carries no broker-owned trail. A position routed to a
        // native-trail broker (`trailOwner == "broker"`) must keep that marker,
        // otherwise a restart would restart a competing app-side trail.
        for p in doc.positions.iter_mut() {
            if !js(p, "trailOwner").eq_ignore_ascii_case("broker") {
                p["pointTrailBrokerOnly"] = json!(false);
            }
        }
        let st = Self {
            dhan,
            paper,
            state_file,
            doc: Arc::new(Mutex::new(doc)),
            template_pool: Arc::new(Mutex::new(BTreeMap::new())),
            ltp: Arc::new(Mutex::new(HashMap::new())),
            broker_positions: Arc::new(Mutex::new(Vec::new())),
            broker_holdings: Arc::new(Mutex::new(Vec::new())),
            funds: Arc::new(Mutex::new(json!({}))),
            last_funds: Arc::new(AtomicI64::new(0)),
            last_ltp: Arc::new(AtomicI64::new(0)),
            last_fills: Arc::new(AtomicI64::new(0)),
            last_super: Arc::new(AtomicI64::new(0)),
            last_reconnect: Arc::new(AtomicI64::new(0)),
            was_conn: Arc::new(AtomicBool::new(false)),
            was_feed: Arc::new(AtomicBool::new(false)),
            last_sig: Arc::new(Mutex::new(HashMap::new())),
            sig_state: Arc::new(Mutex::new(HashMap::new())),
            sig_bar: Arc::new(Mutex::new(HashMap::new())),
            sig_fail_since: Arc::new(Mutex::new(HashMap::new())),
            rl_skip: Arc::new(Mutex::new(HashMap::new())),
            entry_latch_armed: Arc::new(Mutex::new(HashMap::new())),
            entry_latch_off_since: Arc::new(Mutex::new(HashMap::new())),
            entry_cooldown_until: Arc::new(Mutex::new(HashMap::new())),
            atr_cache: Arc::new(Mutex::new(HashMap::new())),
            pool_cache: Arc::new(Mutex::new((0, Value::Null))),
            pool_busy: Arc::new(AtomicBool::new(false)),
            mover_bias: Arc::new(AtomicI64::new(0)),
            last_movers: Arc::new(AtomicI64::new(0)),
            last_scan_rest: Arc::new(AtomicI64::new(0)),
            scan_heartbeat: Arc::new(AtomicI64::new(0)),
            loop_heartbeat: Arc::new(AtomicI64::new(0)),
            loop_passes: Arc::new(AtomicI64::new(0)),
            scan_passes: Arc::new(AtomicI64::new(0)),
            entries_placed: Arc::new(AtomicI64::new(0)),
            last_entry_ms: Arc::new(AtomicI64::new(0)),
            last_commodity: Arc::new(AtomicI64::new(0)),
            last_brain: Arc::new(AtomicI64::new(0)),
            movers_cache: Arc::new(Mutex::new((0, Value::Null))),
            liquid_cache: Arc::new(Mutex::new((0, Value::Null))),
            last_liquid: Arc::new(AtomicI64::new(0)),
            equity_liquidity_cache: Arc::new(Mutex::new((0, Value::Null))),
            equity_liquidity_busy: Arc::new(AtomicBool::new(false)),
            equity_liquidity_force: Arc::new(AtomicBool::new(false)),
            last_equity_liquidity: Arc::new(AtomicI64::new(0)),
            leg_book: Arc::new(Mutex::new(HashMap::new())),
            nifty_dir: Arc::new(AtomicI64::new(0)),
            nifty_sideways: Arc::new(AtomicBool::new(false)),
            nifty_sideways_read: Arc::new(Mutex::new(Value::Null)),
            last_sideways_scan: Arc::new(AtomicI64::new(0)),
            nifty_bull_filters: Arc::new(Mutex::new(Vec::new())),
            nifty_bear_filters: Arc::new(Mutex::new(Vec::new())),
            nifty_raw_net: Arc::new(AtomicI64::new(0)),
            nifty_agree: Arc::new(AtomicI64::new(0)),
            nifty_zone_dir: Arc::new(AtomicI64::new(0)),
            nifty_bbpct_line_dir: Arc::new(AtomicI64::new(0)),
            last_trend: Arc::new(AtomicI64::new(0)),
            last_nifty_scan: Arc::new(AtomicI64::new(0)),
            nifty_picks: Arc::new(Mutex::new((0, Value::Null))),
            index_trend_picks: Arc::new(Mutex::new((0, Value::Null))),
            comm_trend_picks: Arc::new(Mutex::new((0, Value::Null))),
            index_trend_status: Arc::new(Mutex::new(Value::Null)),
            comm_trend_status: Arc::new(Mutex::new(Value::Null)),
            index_trend_last: Arc::new(Mutex::new(HashMap::new())),
            comm_trend_last: Arc::new(Mutex::new(HashMap::new())),
            last_inst_trend: Arc::new(AtomicI64::new(0)),
            nifty_flip: Arc::new(Mutex::new(Value::Null)),
            nifty_seq: Arc::new(AtomicI64::new(0)),
            last_nifty_flip: Arc::new(AtomicI64::new(0)),
            last_color_scan: Arc::new(AtomicI64::new(0)),
            nifty_pending_dir: Arc::new(AtomicI64::new(0)),
            nifty_pending_since: Arc::new(AtomicI64::new(0)),
            nifty_zero_since: Arc::new(AtomicI64::new(0)),
            nifty_votes: Arc::new(Mutex::new(Value::Null)),
            order_times: Arc::new(Mutex::new(Vec::new())),
            paper_pending: Arc::new(Mutex::new(HashMap::new())),
            paper_exit_pending: Arc::new(Mutex::new(HashMap::new())),
            margin_cache: Arc::new(Mutex::new(HashMap::new())),
            picked_strikes: Arc::new(Mutex::new((0, Vec::new()))),
            strat_legs: Arc::new(Mutex::new(HashMap::new())),
            et_pending: Arc::new(Mutex::new(HashMap::new())),
            et_placed: Arc::new(AtomicI64::new(0)),
            blockers: Arc::new(Mutex::new(HashMap::new())),
            log_throttle: Arc::new(Mutex::new(HashMap::new())),
            force_tick: Arc::new(AtomicBool::new(false)),
            scanner_heartbeat: Arc::new(AtomicI64::new(0)),
            scanner_busy: Arc::new(AtomicBool::new(false)),
            no_premium_until: Arc::new(Mutex::new(HashMap::new())),
            seed_inflight: Arc::new(Mutex::new(std::collections::HashSet::new())),
        };
        // Resume the operator's saved master-switch state: ON stays ON (armed
        // unless today's auto square-off already ran), OFF stays OFF.
        st.sync_auto_armed();
        register_engine(state_file, &st);
        st.clone().spawn_engine();
        st.clone().spawn_scanners();
        st.clone().spawn_guard();
        st.clone().spawn_nifty_watch();
        st
    }

    /// Keep the armed flag consistent with the master switch.
    ///
    /// The master button owns `engine_on`; this helper only derives `armed`:
    /// ON -> armed (unless the auto square-off already ran today), OFF ->
    /// disarmed. The engine loop calls it so the next IST day re-arms by itself
    /// while the master is ON, and startup calls it so a restart resumes the
    /// saved state instead of silently starting or stopping the engine.
    fn sync_auto_armed(&self) -> bool {
        let today = ist_day_key();
        let (changed, engine_on, armed) = {
            let Some(mut d) = self.doc() else { return false };
            let armed = master_armed(d.engine_on, &d.last_square_off_day, &today);
            let changed = d.armed != armed;
            if changed {
                d.armed = armed;
            }
            (changed, d.engine_on, armed)
        };
        if changed {
            if armed {
                self.log("info", "master ON: engine ARMED");
            } else if engine_on {
                self.log(
                    "info",
                    "master ON: new entries blocked for today (auto square-off already ran)",
                );
            } else {
                self.log("info", "master OFF: engine stopped + disarmed");
            }
            self.save();
        }
        changed
    }

    fn save(&self) {
        // Serialize under the lock (cheap-ish) but NEVER do the disk write while
        // holding it: the paper state carries the whole closed ledger (multi-MB),
        // so a slow write under `self.doc` used to stall every snapshot/scan and
        // made the whole pane feel frozen. Clone the bytes, drop the guard, then
        // write outside the lock.
        let bytes = {
            let d = match self.doc.lock() {
                Ok(d) => d,
                Err(_) => return,
            };
            match serde_json::to_string(&*d) {
                Ok(s) => s,
                Err(_) => return,
            }
        };
        let _ = write_atomic(&state_path(self.state_file), bytes.as_bytes());
    }

    fn log(&self, level: &str, msg: &str) {
        let entry = json!({ "t": now_ms(), "level": level, "msg": msg });
        if let Ok(mut d) = self.doc.lock() {
            d.logs.push(entry);
            let n = d.logs.len();
            if n > 600 {
                d.logs.drain(0..n - 600);
            }
        }
    }

    /// Emit a log line at most once per `ttl_ms` for a given `key`, so rapidly
    /// re-evaluated skips (no option contracts, empty scanner, ...) do not spam
    /// the Condition Log every engine tick.
    fn log_throttled(&self, key: &str, ttl_ms: i64, level: &str, msg: &str) {
        let now = now_ms();
        {
            let mut m = match self.log_throttle.lock() {
                Ok(m) => m,
                Err(_) => return,
            };
            if let Some(last) = m.get(key) {
                if now - *last < ttl_ms {
                    return;
                }
            }
            m.insert(key.to_string(), now);
            if m.len() > 2000 {
                m.retain(|_, v| now - *v < 3_600_000);
            }
        }
        self.log(level, msg);
    }

    /// Negative-cache key for one underlying + option side.
    fn no_premium_key(sid: i64, side: &str) -> String {
        format!("{}:{}", sid, side.to_uppercase())
    }

    /// True while a previous resolve of this underlying + side failed recently
    /// enough that re-resolving on every 100ms scan tick would be pure waste.
    fn no_premium_cached(&self, sid: i64, side: &str) -> bool {
        let key = Self::no_premium_key(sid, side);
        let now = now_ms();
        self.no_premium_until
            .lock()
            .map(|m| m.get(&key).map(|until| *until > now).unwrap_or(false))
            .unwrap_or(false)
    }

    /// Record that this underlying + side has no resolvable premium leg for the
    /// next [`NO_PREMIUM_CACHE_MS`], so the scan stops hammering the resolver
    /// (and the blocker panel stops inflating its count) until the timer lapses.
    fn mark_no_premium(&self, sid: i64, side: &str) {
        let key = Self::no_premium_key(sid, side);
        let now = now_ms();
        if let Ok(mut m) = self.no_premium_until.lock() {
            m.insert(key, now + NO_PREMIUM_CACHE_MS);
            if m.len() > 4096 {
                m.retain(|_, until| *until > now);
            }
        }
    }

    /// A resolve succeeded: forget any negative entry so the very next scan can
    /// re-resolve normally.
    fn clear_no_premium(&self, sid: i64, side: &str) {
        let key = Self::no_premium_key(sid, side);
        if let Ok(mut m) = self.no_premium_until.lock() {
            m.remove(&key);
        }
    }

    fn doc(&self) -> Option<std::sync::MutexGuard<'_, RtDoc>> {
        self.doc.lock().ok()
    }

    /// Drop saved commodity ids that are not live MCX contracts once the scrip
    /// master is authoritative. Returns how many ids were removed.
    ///
    /// This repairs state that was persisted before the fix (the old bundled
    /// fallback ids `500001..500015`) and any contract the exchange has since
    /// rolled. It is intentionally a no-op while the master is still warming so
    /// it can never delete the operator's picks from an incomplete view, and it
    /// only writes the state file when something actually changed.
    pub fn reconcile_commodity_contracts(&self) -> usize {
        if crate::scrip::warm_status() != "ready" {
            return 0;
        }
        let removed = {
            let Ok(mut d) = self.doc.lock() else { return 0 };
            let before = d.settings.commodity_list.len();
            d.settings
                .commodity_list
                .retain(|id| crate::market::commodity_is_live_contract(*id) != Some(false));
            let keep = d.settings.commodity_list.clone();
            d.settings
                .commodity_legs
                .retain(|l| keep.contains(&l.security_id));
            before.saturating_sub(d.settings.commodity_list.len())
        };
        if removed > 0 {
            self.save();
            self.log(
                "warn",
                &format!(
                    "removed {removed} commodity id(s) that are not live MCX contracts"
                ),
            );
        }
        removed
    }

    /// Full durable engine state (`RtDoc`) as JSON for the Backup tab. This is
    /// the *entire* engine: settings, indicator filters, strategies, saved
    /// templates, staging/final lists, open positions and the whole closed
    /// ledger (trade statistics) - not just the derived UI snapshot.
    pub fn export_state(&self) -> Value {
        self.doc()
            .and_then(|d| serde_json::to_value(&*d).ok())
            .unwrap_or(Value::Null)
    }

    /// Replace the whole durable engine state from a backup, then persist it to
    /// disk. Only a syntactically valid `RtDoc` is accepted. Returns the number
    /// of strategies + positions + closed trades restored for the status line.
    pub fn import_state(&self, v: &Value) -> Result<usize, String> {
        let mut parsed: RtDoc = serde_json::from_value(v.clone())
            .map_err(|e| format!("invalid engine state: {e}"))?;
        // Apply the same normalisation the startup loader does, so a restored
        // state can never carry a nonsense order-rate value.
        if parsed.settings.trade_limit_count <= 0 {
            parsed.settings.trade_limit_count = 5;
        }
        if parsed.settings.order_per_sec <= 0 {
            parsed.settings.order_per_sec = 6;
        }
        parsed.settings.order_per_sec = order_per_sec_budget(parsed.settings.order_per_sec);
        parsed.settings.scan_interval_ms = scan_interval_budget(parsed.settings.scan_interval_ms);
        parsed.settings.scan_bar_close_tf = scan_bar_close_tf(&parsed.settings.scan_bar_close_tf).to_string();
        // Paper Trade 3 refuses the index / commodity scanner features, and
        // Paper Trade 2 refuses the stock / NIFTY-trend / BB%b features, even
        // when a backup tries to restore them.
        self.enforce_constraints(&mut parsed.settings);
        let count = parsed.strategies.len() + parsed.positions.len() + parsed.closed.len();
        {
            let mut d = self.doc.lock().map_err(|_| "state lock poisoned".to_string())?;
            *d = parsed;
        }
        self.save();
        // Resume exactly what the backup carried: a saved ON stays ON (and is
        // armed unless today's square-off already ran), a saved OFF stays OFF.
        self.sync_auto_armed();
        // Force the next scanner passes to rebuild against the restored state.
        self.last_movers.store(0, Ordering::Relaxed);
        self.last_scan_rest.store(0, Ordering::Relaxed);
        self.last_nifty_scan.store(0, Ordering::Relaxed);
        self.last_trend.store(0, Ordering::Relaxed);
        Ok(count)
    }

    /// Closed-trade ledger + armed flag for the Trade Stats report. Uses the
    /// full ledger (not the snapshot's 500-row cap) so period windows and the
    /// time-of-day analysis see the entire executed history.
    pub fn stats_input(&self) -> (Vec<Value>, bool) {
        match self.doc() {
            Some(d) => (d.closed.clone(), d.armed),
            None => (Vec::new(), false),
        }
    }

    /// Cheap stable hash of the closed ledger + armed flag, seeded by `seed`, so
    /// the stats endpoint can detect an unchanged ledger and answer from its cache
    /// WITHOUT cloning the whole (multi-MB) ledger first.
    pub fn closed_signature(&self, seed: u64) -> u64 {
        use std::collections::hash_map::DefaultHasher;
        use std::hash::{Hash, Hasher};
        let mut h = DefaultHasher::new();
        seed.hash(&mut h);
        if let Some(d) = self.doc() {
            d.armed.hash(&mut h);
            d.closed.len().hash(&mut h);
            for c in &d.closed {
                c.hash(&mut h);
            }
        }
        h.finish()
    }

    fn ltp_of(&self, sec_id: i64, exch: &str) -> f64 {
        if let Some(v) = self.ltp.lock().ok().and_then(|m| m.get(&sec_id).copied()) {
            if v > 0.0 {
                return v;
            }
        }
        if let Ok(q) = self.dhan.market.quotes.lock() {
            if let Some(v) = q.get(&crate::market::quote_key(sec_id, exch)) {
                if let Some(p) = v.get("ltp").and_then(|x| x.as_f64()) {
                    return p;
                }
            }
        }
        0.0
    }

    /// Refresh the engine LTP cache from a set of scanner quote rows. Called on
    /// every `quote_rows` return path so the entry path resolves option strikes
    /// against the current underlying price. Skipping this on the all-from-feed
    /// fast path left `ltp` pinned to its startup/pre-open value, which resolved
    /// far-from-ATM strikes (e.g. a -20% mover's deep-ITM 1900-PE instead of the
    /// near-ATM leg the readout showed).
    fn seed_ltp_from_rows(&self, rows: &[Value]) {
        if let Ok(mut m) = self.ltp.lock() {
            for r in rows {
                let id = r.get("securityId").and_then(|x| x.as_i64()).unwrap_or(0);
                let l = r.get("last").and_then(|x| x.as_f64()).unwrap_or(0.0);
                if id > 0 && l > 0.0 {
                    m.insert(id, l);
                }
            }
        }
    }

    /// Paper entries are REST-free, so a freshly subscribed leg's first tick can
    /// lag the subscription by a few hundred ms. Poll the live feed over a short
    /// bounded window instead of failing the entry, so a signal is not lost
    /// merely because the quote had not landed yet.
    async fn wait_feed_ltp(&self, sec_id: i64, exch: &str, timeout_ms: u64) -> f64 {
        let first = self.ltp_of(sec_id, exch);
        if first > 0.0 {
            return first;
        }
        let mut waited = 0u64;
        while waited < timeout_ms {
            tokio::time::sleep(Duration::from_millis(60)).await;
            waited += 60;
            let ltp = self.ltp_of(sec_id, exch);
            if ltp > 0.0 {
                return ltp;
            }
        }
        0.0
    }

    /// Ask a background task to REST-seed one candle series. Deduplicated by
    /// `"{exch}:{sec}:{tf}"`, so a scan that finds the series still cold every
    /// 100ms queues exactly one fetch instead of one per pass. The fetch itself
    /// waits on the shared Dhan gate, which is why it must never run inline in
    /// the evaluation loop.
    fn request_candle_seed(&self, sec_id: i64, exch: &str, inst: &str, tf: &str) {
        if sec_id <= 0 {
            return;
        }
        let key = format!("{}:{}:{}", exch.to_uppercase(), sec_id, tf);
        {
            let Ok(mut g) = self.seed_inflight.lock() else { return };
            if !g.insert(key.clone()) {
                return;
            }
        }
        let this = self.clone();
        let (inst, tf) = (inst.to_string(), tf.to_string());
        let (exch, key2) = (exch.to_string(), key);
        // Bound the number of seeds queued on the Dhan data gate. When the budget
        // is full this pass is skipped (the key is removed below) so the scanner
        // retries on its next tick; that keeps the gate's reservation horizon
        // short enough that an operator chart request never starves behind a wall
        // of background seeds.
        let slot = match this.dhan.try_seed_slot() {
            Some(s) => s,
            None => {
                if let Ok(mut g) = this.seed_inflight.lock() {
                    g.remove(&key2);
                }
                return;
            }
        };
        tokio::spawn(async move {
            let _slot = slot;
            if !this.dhan.rate_limited() {
                if let Ok(c) = this.dhan.fetch_candles(sec_id, &exch, &inst, &tf).await {
                    this.dhan.market.seed_bars(sec_id, &exch, &tf, c);
                }
            }
            if let Ok(mut g) = this.seed_inflight.lock() {
                g.remove(&key2);
            }
        });
    }

    /// Tick-native candle series.
    ///
    /// First use seeds the series from one REST fetch; every later call is
    /// served from the in-memory series the live websocket feed keeps patching,
    /// so the strategy scan never waits on (or goes stale behind) a REST
    /// round-trip. If the feed goes quiet the series ages out after
    /// [`LIVE_BAR_TTL`] and the next call re-seeds from REST.
    ///
    /// The raw series is transformed into the operator-selected chart type
    /// (Candlestick / Heikin Ashi / Line / Renko) ONLY while the "Filters on
    /// display chart" master switch is ON, so every indicator filter and
    /// entry/exit the caller derives runs on the chart the operator chose. With
    /// the switch OFF (default) the raw series is used unchanged.
    async fn live_candles(
        &self,
        sec_id: i64,
        exch: &str,
        inst: &str,
        tf: &str,
    ) -> Result<Vec<Candle>, dhan_hq::DhanError> {
        let raw = if let Some(c) = self.dhan.market.live_bars_for(sec_id, exch, tf, LIVE_BAR_TTL) {
            c
        } else if self.dhan.rate_limited() {
            // Dhan's data gate is holding after a 429. A REST call here would
            // sleep for the whole penalty (up to 120s) INSIDE the scan loop, which
            // is exactly what froze entries. Serve the last series instead (it is
            // still tick-advanced) and let the gate reopen on its own.
            match self
                .dhan
                .market
                .live_bars_for(sec_id, exch, tf, Duration::from_secs(900))
            {
                Some(stale) => stale,
                None => {
                    return Err(dhan_hq::DhanError::Message(
                        "Dhan data gate is holding after a rate limit; no live series yet".into(),
                    ))
                }
            }
        } else {
            // Cold series: ask for a BACKGROUND seed and return the last known
            // series (if any) this pass. Seeding synchronously here is what let a
            // single throttled Dhan candle call hold the whole evaluation loop for
            // seconds at a time - the loop now never waits on it.
            self.request_candle_seed(sec_id, exch, inst, tf);
            match self
                .dhan
                .market
                .live_bars_for(sec_id, exch, tf, Duration::from_secs(900))
            {
                Some(stale) => stale,
                None => {
                    return Err(dhan_hq::DhanError::Message(
                        "candle series is warming from a background seed".into(),
                    ))
                }
            }
        };
        let settings = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        Ok(apply_engine_chart(raw, &settings))
    }

    /// `(ltp, oi, volume)` for a security from the shared live-quote cache. The
    /// Order Placement cards and the Auto-Lots liquidity gate read the exact same
    /// live market data the engine trades on.
    fn quote_fields(&self, sec_id: i64, exch: &str) -> (f64, f64, f64) {
        let key = crate::market::quote_key(sec_id, exch);
        if let Ok(q) = self.dhan.market.quotes.lock() {
            if let Some(v) = q.get(&key) {
                let f = |k: &str| v.get(k).and_then(|x| x.as_f64()).unwrap_or(0.0);
                return (f("ltp"), f("oi"), f("volume"));
            }
        }
        (self.ltp_of(sec_id, exch), 0.0, 0.0)
    }

    /// `(change, change_pct)` for a security from the shared live-quote cache, with
    /// a fallback to `ltp - prev_ltp` when the feed only published prices. `(0, 0)`
    /// when unquoted. Surfaced on the trade lists so the option premium's
    /// plus/minus sign - the whole point of the "+green premium" pick - is visible
    /// next to the trade.
    fn quote_change(&self, sec_id: i64, exch: &str) -> (f64, f64) {
        let key = crate::market::quote_key(sec_id, exch);
        if let Ok(q) = self.dhan.market.quotes.lock() {
            if let Some(v) = q.get(&key) {
                let f = |k: &str| v.get(k).and_then(|x| x.as_f64()).unwrap_or(0.0);
                // Use the PUBLISHED change / change_pct exactly as the option
                // chain shows them. Never substitute the tick-to-tick direction
                // when change is 0: that made the executed-trade row show a
                // minus sign on a strike the chain shows as plus (or "--"),
                // because the last tick happened to print down.
                let chg = f("change");
                let pct = f("change_pct");
                return (round2(chg), round2(pct));
            }
        }
        (0.0, 0.0)
    }

    /// Whether this engine books Dhan broker charges against realized P&L.
    /// Real Dhan trades settle charges broker-side, so only the paper engine
    /// honours the "Deduct Dhan charges" toggle.
    pub fn charges_on(&self) -> bool {
        self.paper && self.doc().map(|d| d.settings.broker_charges).unwrap_or(true)
    }

    /// Realized paper P&L (sum of every closed paper trade).
    fn paper_realized(&self) -> f64 {
        self.doc()
            .map(|d| realized_pnl(&d.closed, d.settings.broker_charges))
            .unwrap_or(0.0)
    }

    /// Paper wallet: base balance + realized P&L - margin locked by the open
    /// paper positions. The base is this tab's shared-margin allotment (the
    /// only capital source; no separate "Capital Rs" setting). Derived (never
    /// stored) so it can never drift.
    fn paper_available(&self) -> f64 {
        self.doc()
            .map(|d| {
                paper_available_of(
                    paper_base_of(self.engine_id()),
                    &d.closed,
                    &d.positions,
                    d.settings.broker_charges,
                )
            })
            .unwrap_or(0.0)
    }

    /// Real Dhan funds available (falls back to None when unknown/zero).
    fn available_funds(&self) -> Option<f64> {
        if self.paper {
            return Some(self.paper_available());
        }
        let f = self.funds.lock().ok()?;
        f.get("availabelBalance")
            .or_else(|| f.get("availableBalance"))
            .and_then(|x| x.as_f64())
            .filter(|v| *v > 0.0)
    }

    /// AI Smart margin budget for THIS tab = its shared-margin allotment (see
    /// [`crate::shared_margin`]). The shared allotment is the ONLY margin source
    /// now: the old per-tab "Margin Rs / Margin to use % / Dynamic margin"
    /// settings are gone. Checkbox OFF (or an empty family pool, e.g. an empty
    /// real Dhan account) resolves to Rs 0, so the tab cannot enter a trade.
    fn margin_budget(&self) -> f64 {
        crate::shared_margin::cap_for(self.engine_id()).unwrap_or(0.0)
    }

    /// Total cost locked by open engine positions (qty x entry), plus the count.
    fn locked_margin(&self) -> (f64, i64) {
        let positions = self.doc().map(|d| d.positions.clone()).unwrap_or_default();
        locked_margin_of(&positions)
    }

    /// Margin gate for an already-sized entry: `Some(reason)` when the required
    /// margin (qty x price) exceeds the budget still free after the running
    /// trades. Used by the "skip when margin unavailable" guard and by the live
    /// entry gate, so both make the identical, deterministic decision.
    fn margin_block_for_qty(&self, qty: i64, ltp: f64) -> Option<String> {
        let budget = self.margin_budget();
        // The shared allotment is the only margin source, so a Rs 0 budget means
        // "this tab is not allotted any margin" (checkbox OFF, or the family
        // pool is empty). Every entry is blocked - never silently allowed the
        // way the old unset legacy budget used to disable the gate.
        if budget <= 0.0 {
            return Some(
                "trade blocked: no shared margin allotted to this tab (set an allotment in the Margin allotment panel)"
                    .into(),
            );
        }
        if ltp <= 0.0 || qty <= 0 {
            return None;
        }
        let (locked, running) = self.locked_margin();
        margin_block_reason(qty as f64 * ltp, budget, locked, running)
    }

    /// Early "skip when margin unavailable" pre-check used before a signal is
    /// queued. Mirrors the entry gate's qty sizing for the manual-lots case; when
    /// Auto-Lots is on the qty is sized to fit the budget, so this returns `None`
    /// and the exact gate inside `open_entry` still governs. Returns the block
    /// reason when the signal would be rejected for margin, so the caller can
    /// consume the signal instead of retrying it into a late fill.
    fn early_margin_skip_reason(&self, strat: &Strategy, ltp: f64) -> Option<String> {
        let (auto_lots, liquid_auto_lots, lots, lot_size) = self
            .doc()
            .map(|d| {
                (
                    d.auto_lots,
                    d.settings.liquid_auto_lot_on,
                    d.settings.lots,
                    d.settings.lot_size,
                )
            })
            .unwrap_or((false, false, 1.0, 0.0));
        // Auto-Lot sizes the qty to fit the budget, so the exact gate inside
        // `open_entry` has to decide instead of this pre-check. A liquid leg with
        // its own Liquid Auto-Lot ON is auto-sized the same way even when the
        // global switch is off.
        if auto_lots || (strat.liquid_leg && liquid_auto_lots) {
            return None;
        }
        let lot = if strat.lot > 0.0 {
            strat.lot
        } else if lot_size > 0.0 {
            lot_size
        } else {
            scrip::get()
                .and_then(|s| s.lot_for(&strat.trading_symbol, &strat.exchange_segment).map(|(l, _)| l))
                .unwrap_or(1.0)
        };
        let qty = (lots.max(1.0) * lot).round() as i64;
        self.margin_block_for_qty(qty, ltp)
    }

    /// Net realised P&L for the current IST day, using the same net/gross rule
    /// as the summary strip. Drives the daily loss cap.
    fn realized_net_today(&self) -> f64 {
        let Some(d) = self.doc() else { return 0.0 };
        let charges_on = !self.paper || d.settings.broker_charges;
        let start = ist_day_start_ms();
        d.closed
            .iter()
            .filter(|c| ji(c, "closedAt") >= start)
            .map(|c| closed_pnl(c, charges_on))
            .sum()
    }

    /// Total rupees currently at risk across open positions: the distance from
    /// the live mark to the hard stop, times qty. A position with no stop
    /// contributes its full notional to the worst case, so an unprotected trade
    /// can never be treated as risk-free.
    fn open_risk_rupees(&self) -> f64 {
        let Some(d) = self.doc() else { return 0.0 };
        let mut total = 0.0;
        for p in &d.positions {
            let qty = jf(p, "filledQty").max(jf(p, "qty")).abs();
            if qty <= 0.0 {
                continue;
            }
            let entry = jf(p, "fillPrice").max(jf(p, "entry"));
            let ltp = self.ltp_of(ji(p, "securityId"), &js(p, "exchangeSegment"));
            let mark = if ltp > 0.0 { ltp } else { entry };
            let sl = {
                let overall = jf(p, "overallSl");
                if overall > 0.0 { overall } else { jf(p, "sl") }
            };
            let per_unit = if sl > 0.0 {
                (mark - sl).abs()
            } else {
                // No stop: the entire premium is at risk.
                mark
            };
            total += per_unit * qty;
        }
        total
    }

    /// Risk gate for a NEW entry. Returns the block reason when the brain's
    /// capital-protection rules say no. Every check is opt-in (a 0 setting
    /// disables it) so the engine keeps its historical behaviour when the
    /// operator has not configured risk limits.
    fn risk_entry_block(&self) -> Option<String> {
        let s = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        // 0) Volatility band. The brain owns this read: a quiet tape cannot pay
        // for the round trip and a wild one clips stops, so it deliberately
        // stands aside instead of trading through a bad regime.
        if s.auto_trade_on && s.brain_no_trade_vol {
            return Some(
                "trade blocked: brain volatility band is NO-TRADE (ATR% at an extreme of its own recent range - widen or disable the vol band in Brain Risk settings to trade this tape)"
                    .into(),
            );
        }
        // 1) Daily loss cap. Stops the whole day once the realised book is deep
        // enough in the red - the single most effective way to avoid a bad
        // session turning catastrophic.
        if s.risk_daily_loss_cap > 0.0 {
            let realized = self.realized_net_today();
            if realized <= -s.risk_daily_loss_cap {
                return Some(format!(
                    "trade blocked: daily loss cap hit (realized Rs {realized:.0} vs cap Rs -{:.0}) - no new entries today",
                    s.risk_daily_loss_cap
                ));
            }
        }
        // 2) Total open risk cap.
        if s.risk_max_open > 0.0 {
            let open = self.open_risk_rupees();
            if open >= s.risk_max_open {
                return Some(format!(
                    "trade blocked: open risk Rs {open:.0} already at the cap Rs {:.0}",
                    s.risk_max_open
                ));
            }
        }
        // 3) Opening-noise guard: no entries in the first N minutes of the
        // session, where spreads are widest and the first candles repaint.
        if s.entry_no_trade_before_min > 0.0 {
            let secs = crate::market::now_secs() + 19800;
            let mins = (secs.rem_euclid(86_400)) as f64 / 60.0;
            let open_min = 9.0 * 60.0 + 15.0;
            if mins >= open_min && mins < open_min + s.entry_no_trade_before_min {
                return Some(format!(
                    "trade blocked: opening noise guard ({:.0} min after open)",
                    s.entry_no_trade_before_min
                ));
            }
        }
        None
    }

    /// Size an entry from RISK instead of margin when the operator set a
    /// per-trade risk budget. Returns `None` when risk sizing is off, so the
    /// caller keeps the historical lots/margin path untouched.
    fn risk_sized_qty(&self, ltp: f64, stop_distance: f64, lot: f64, max_qty: i64) -> Option<i64> {
        let s = self.doc()?.settings.clone();
        if s.risk_per_trade <= 0.0 || !s.auto_trade_on {
            return None;
        }
        // Margin still caps the size: cash can never be exceeded just because the
        // risk budget would allow more contracts.
        let budget = self.margin_budget();
        let margin_cap_qty = if ltp > 0.0 && budget > 0.0 {
            (budget / ltp).floor() as i64
        } else {
            0
        };
        let plan = crate::brain::risk_based_qty(
            s.risk_per_trade,
            stop_distance,
            lot,
            margin_cap_qty,
            max_qty,
        );
        Some(plan.qty)
    }

    /// Whether the operator enabled "skip trade when margin unavailable".
    fn skip_margin_block_enabled(&self) -> bool {
        self.doc().map(|d| d.settings.skip_on_margin_block).unwrap_or(false)
    }

    /// Consume a signal because margin blocked it: latch the fresh edge so the
    /// SAME signal can never re-queue and fill late. A genuinely new signal
    /// (after the gate resets) is still allowed.
    fn consume_signal_for_margin(&self, strategy_id: &str) {
        self.set_sig_state(strategy_id, true);
    }

    /// Entry-signal consumed latch state (unit-test/inspection helper): whether
    /// the current signal for this strategy has already been consumed.
    #[cfg(test)]
    fn sig_state_is_set(&self, strategy_id: &str) -> bool {
        self.sig_state
            .lock()
            .ok()
            .and_then(|m| m.get(strategy_id).copied())
            .unwrap_or(false)
    }

    /// Record the entry-gate result for the multi-position "fresh signal" edge
    /// detector. `true` as soon as an entry is placed so a gate that stays true
    /// does not stack another position until it resets and re-triggers.
    fn set_sig_state(&self, strategy_id: &str, val: bool) {
        if let Ok(mut m) = self.sig_state.lock() {
            if m.len() > 5000 {
                m.clear();
            }
            m.insert(strategy_id.to_string(), val);
        }
    }

    /// Release the fresh-signal edge for a queued entry that resolved without
    /// actually filling (margin block, rejection, engine stopped/disarmed). In
    /// "fresh signal" mode the edge is consumed at queue time, so a fill that
    /// never lands must hand it back; otherwise the strategy latches silent and
    /// stops trading until the gate happens to reset and print a brand-new
    /// signal.
    fn release_fresh_edge(&self, strategy_id: &str) {
        self.clear_signal_edge(strategy_id);
    }

    /// End the current signal for a strategy: the gate stopped holding, so the
    /// next time it holds is a brand-new fresh signal. Clears the fresh-edge flag,
    /// any rate-limit drop latch and the stale delayed-entry metAt marker, so the
    /// next genuine signal starts clean.
    fn clear_signal_edge(&self, strategy_id: &str) {
        self.set_sig_state(strategy_id, false);
        self.clear_rl_skip(strategy_id);
        if let Ok(mut m) = self.et_pending.lock() {
            m.remove(strategy_id);
        }
    }

    /// Consume the ENTRY-TIMING pending stamp for an executed entry. The stamp is
    /// keyed by the SCAN strategy id, but the executed leg can carry a DIFFERENT
    /// id: a frozen Top-Movers Leg Book leg is `pick:<sid>:<side>` while the scan
    /// stamped `scan:<sid>:<side>`. `origin_id` carries the scan id from the
    /// caller so the row is still produced; `None` (manual / direct entries whose
    /// leg id already matches) falls back to the leg's own id.
    fn take_entry_timing(&self, leg_id: &str, origin_id: Option<&str>) -> Option<(i64, i64)> {
        let key = origin_id.unwrap_or(leg_id);
        self.et_pending.lock().ok().and_then(|mut m| m.remove(key))
    }

    /// Record a "why didn't this entry fire" reason.
    ///
    /// Called from every gate in `scan_signals` that drops a signal without
    /// placing an order, so the UI's "Why no trades?" panel can show the live
    /// blocking reason (count + newest detail) rather than an unexplained
    /// quiet engine. `code` is a stable short key (one row per reason), `level`
    /// is `info` for a normal skip or `warn` for a hard block the operator
    /// likely has to fix with a setting.
    pub(crate) fn note_blocker(&self, level: &'static str, code: &str, sample: &str, detail: &str) {
        let now = now_ms();
        let Ok(mut m) = self.blockers.lock() else { return };
        let mut exists = true;
        let row = m.entry(code.to_string()).or_insert_with(|| {
            exists = false;
            BlockerRow {
                level,
                code: code.to_string(),
                detail: detail.to_string(),
                count: 1,
                last_ms: now,
                first_ms: now,
                last_count_ms: now,
                samples: Vec::new(),
            }
        });
        if exists {
            // Count at most once per second per reason: the scan runs every
            // 100ms, so a raw increment would report meaningless numbers like
            // "14302 hits".
            if now - row.last_count_ms >= 1_000 {
                row.count += 1;
                row.last_count_ms = now;
            }
            row.level = level;
            row.detail = detail.to_string();
            row.last_ms = now;
        }
        // Keep up to 4 distinct example strategy names for context.
        let name = sample.trim();
        if !name.is_empty() && row.samples.len() < 4 && !row.samples.iter().any(|s| s == name) {
            row.samples.push(name.to_string());
        }
        if m.len() > 200 {
            m.retain(|_, r| now - r.last_ms < 1_800_000);
        }
    }

    /// Snapshot of every recorded blocker, newest first, with a freshness flag
    /// so the UI can grey out reasons that stopped happening.
    pub(crate) fn blockers_snapshot(&self, within_ms: i64) -> Value {
        let now = now_ms();
        let rows: Vec<Value> = self
            .blockers
            .lock()
            .map(|m| {
                let mut v: Vec<Value> = m
                    .values()
                    .filter(|r| now - r.last_ms <= within_ms)
                    .map(|r| {
                        json!({
                            "code": r.code,
                            "level": r.level,
                            "detail": r.detail,
                            "count": r.count,
                            "lastMs": r.last_ms,
                            "firstMs": r.first_ms,
                            "ageMs": (now - r.last_ms).max(0),
                            "samples": r.samples,
                            "fresh": now - r.last_ms <= 60_000,
                        })
                    })
                    .collect();
                v.sort_by(|a, b| {
                    let ja = a.get("lastMs").and_then(|x| x.as_i64()).unwrap_or(0);
                    let jb = b.get("lastMs").and_then(|x| x.as_i64()).unwrap_or(0);
                    jb.cmp(&ja)
                });
                v
            })
            .unwrap_or_default();
        json!({ "ok": true, "at": now, "blockers": rows })
    }

    /// Engine handle for the diagnostics module: the registry stores a clone of
    /// each engine, so all state is reachable from one snapshot request.
    pub fn engine_handle(&self, id: &str) -> Option<RealtimeState> {
        if self.engine_id() == id {
            return Some(self.clone());
        }
        engine_registry().lock().ok().and_then(|m| m.get(id).cloned())
    }

    /// Freshness of the engine loop (ms stamp; 0 = never ran).
    pub fn diagnostic_loop_heartbeat(&self) -> i64 {
        self.loop_heartbeat.load(Ordering::Relaxed)
    }

    pub fn diagnostic_loop_passes(&self) -> i64 {
        self.loop_passes.load(Ordering::Relaxed)
    }

    /// Freshness of the SIGNAL SCAN (ms stamp; 0 = never ran). This is the value
    /// that separates "gates are blocking" from "the scan itself is dead".
    pub fn diagnostic_scan_heartbeat(&self) -> i64 {
        self.scan_heartbeat.load(Ordering::Relaxed)
    }

    pub fn diagnostic_scan_passes(&self) -> i64 {
        self.scan_passes.load(Ordering::Relaxed)
    }

    /// Freshness of the background scanner pass (ms stamp; 0 = never completed).
    /// A stale value here means Top Movers / Liquid F&O picks are frozen (usually
    /// a Dhan rate-limit hold) while the evaluation loop itself stays alive.
    pub fn diagnostic_scanner_heartbeat(&self) -> i64 {
        self.scanner_heartbeat.load(Ordering::Relaxed)
    }

    pub fn diagnostic_entries_placed(&self) -> i64 {
        self.entries_placed.load(Ordering::Relaxed)
    }

    pub fn diagnostic_last_entry(&self) -> i64 {
        self.last_entry_ms.load(Ordering::Relaxed)
    }

    /// `(engineOn, armed, compact doc state)` for the diagnostics snapshot.
    pub fn diagnostic_engine_state(&self) -> Option<(bool, bool, Value)> {
        let d = self.doc()?;
        let strategies = d.strategies.iter().filter(|s| s.enabled).count();
        let doc = json!({
            "engineOn": d.engine_on,
            "armed": d.armed,
            "filterMode": d.settings.filter_mode,
            "requireCondition": d.settings.require_condition,
            "moversOn": d.settings.movers_on,
            "commodityOn": d.settings.commodity_on,
            "premiumOnly": d.settings.premium_only,
            "lots": d.settings.lots,
            "scanIntervalOn": d.settings.scan_interval_on,
            "scanIntervalMs": d.settings.scan_interval_ms,
            "scanBarClose": d.settings.scan_bar_close,
            "tradeLimit": d.settings.trade_limit,
            "tradeLimitCount": d.settings.trade_limit_count,
            "strategies": d.strategies.len(),
            "enabledStrategies": strategies,
            "selected": d.selected.values().filter(|v| **v).count(),
            "openPositions": d.positions.len(),
            "closedTrades": d.closed.len(),
            "lastSquareOffDay": d.last_square_off_day,
        });
        Some((d.engine_on, d.armed, doc))
    }

    /// `(locked margin, open positions)` for this engine.
    pub fn diagnostic_locked_margin(&self) -> (f64, i64) {
        self.locked_margin()
    }

    /// Clear the recorded blockers (operator pressed "Clear").
    pub(crate) fn clear_blockers(&self) {
        if let Ok(mut m) = self.blockers.lock() {
            m.clear();
        }
    }

    /// Drop specific "state" reasons that are no longer true (feed restored,
    /// market reopened, engine re-armed, ...). Without this a transient row
    /// would linger for the full snapshot window and read as if it were still
    /// blocking, which is worse than showing nothing.
    pub(crate) fn clear_blocker_codes(&self, codes: &[&str]) {
        if let Ok(mut m) = self.blockers.lock() {
            m.retain(|k, _| !codes.iter().any(|c| c == k));
        }
    }

    /// Mark a strategy's current signal as DROPPED because the orders/sec window
    /// was saturated. The latch keeps the same still-true signal from re-queuing
    /// on the next scan tick (which would be a late, chased fill); it is released
    /// when the signal resets (see [`Self::clear_signal_edge`]).
    fn mark_rl_skip(&self, strategy_id: &str) {
        if let Ok(mut m) = self.rl_skip.lock() {
            if m.len() > 5000 {
                m.clear();
            }
            m.insert(strategy_id.to_string(), now_ms());
        }
    }

    /// Whether this strategy's current signal was already dropped by the
    /// orders/sec rate limiter and must be skipped until the signal resets.
    fn rl_skip_active(&self, strategy_id: &str) -> bool {
        self.rl_skip
            .lock()
            .ok()
            .map(|m| m.contains_key(strategy_id))
            .unwrap_or(false)
    }

    /// Release the rate-limit drop latch for a strategy (signal reset / fresh fill).
    fn clear_rl_skip(&self, strategy_id: &str) {
        if let Ok(mut m) = self.rl_skip.lock() {
            m.remove(strategy_id);
        }
    }

    /// Milliseconds per bar for a strategy's engine timeframe.
    fn tf_step_ms(tf: &str) -> i64 {
        match tf.trim().to_lowercase().as_str() {
            "5min" | "5m" => 5 * 60_000,
            "15min" | "15m" => 15 * 60_000,
            "1min" | "1m" => 60_000,
            _ => 60_000,
        }
    }

    /// The bar bucket (bar index since the epoch) for `tf` at `now_ms`.
    fn bar_bucket_at(tf: &str, now: i64) -> i64 {
        now / Self::tf_step_ms(tf)
    }

    /// Multi-position "fresh signal" gate: `true` only when the entry gate holds
    /// on a NEW bar for this strategy - i.e. its last consumed fresh signal was on
    /// a different bar. While the gate keeps holding this opens one position per
    /// bar (not once ever, not once per 100ms tick).
    fn signal_bar_is_fresh(&self, strategy_id: &str, tf: &str, now: i64) -> bool {
        let bucket = Self::bar_bucket_at(tf, now);
        self.sig_bar
            .lock()
            .ok()
            .and_then(|m| m.get(strategy_id).copied())
            != Some(bucket)
    }

    /// Consume the current bar's fresh signal for a strategy, so the still-true
    /// gate cannot stack another position until the next bar opens.
    fn mark_signal_bar(&self, strategy_id: &str, tf: &str, now: i64) {
        if let Ok(mut m) = self.sig_bar.lock() {
            if m.len() > 5000 {
                m.clear();
            }
            m.insert(strategy_id.to_string(), Self::bar_bucket_at(tf, now));
        }
    }

    /// The leg's gate held on this scan: cancel any pending signal-end debounce so
    /// a brief dip inside one signal never ends it.
    fn note_signal_pass(&self, strategy_id: &str) {
        if let Ok(mut m) = self.sig_fail_since.lock() {
            m.remove(strategy_id);
        }
    }

    /// The leg's gate failed on this scan. Returns `true` only once the failure
    /// has been continuous for [`SIGNAL_END_DEBOUNCE_MS`], i.e. a genuine signal
    /// end (reset the pulse) rather than a single-scan flicker.
    fn end_signal_if_due(&self, strategy_id: &str) -> bool {
        let now = now_ms();
        let Ok(mut m) = self.sig_fail_since.lock() else { return false };
        if m.len() > 5000 {
            m.clear();
        }
        let since = *m.entry(strategy_id.to_string()).or_insert(now);
        now - since >= SIGNAL_END_DEBOUNCE_MS
    }

    /// "Repeat-entry latch": whether a new entry is currently armed for this
    /// strategy. An absent key reads as armed (the strategy has never latched).
    fn entry_latch_allows(&self, strategy_id: &str) -> bool {
        self.entry_latch_armed
            .lock()
            .ok()
            .and_then(|m| m.get(strategy_id).copied())
            .unwrap_or(true)
    }

    /// Disarm the repeat-entry latch the instant an entry is placed for this
    /// strategy, and drop any in-progress OFF timer, so the now-true signal
    /// cannot re-enter until the gate turns OFF and stays OFF for the configured
    /// time. Locks are taken one at a time (never nested) to avoid lock-order
    /// deadlocks.
    fn latch_disarm(&self, strategy_id: &str) {
        if let Ok(mut m) = self.entry_latch_armed.lock() {
            if m.len() > 5000 {
                m.clear();
            }
            m.insert(strategy_id.to_string(), false);
        }
        if let Ok(mut m) = self.entry_latch_off_since.lock() {
            m.remove(strategy_id);
        }
    }

    /// Re-arm the repeat-entry latch (used when a queued entry resolved without
    /// filling, so a non-fill does not silently silence the strategy). Also
    /// drops any OFF timer.
    fn latch_rearm(&self, strategy_id: &str) {
        if let Ok(mut m) = self.entry_latch_armed.lock() {
            m.insert(strategy_id.to_string(), true);
        }
        if let Ok(mut m) = self.entry_latch_off_since.lock() {
            m.remove(strategy_id);
        }
    }

    /// The strategy's gate held this scan: cancel any in-progress OFF timer so a
    /// brief ON blip keeps the OFF run from counting. The arm state is left as-is
    /// (an entry keeps the latch disarmed until a real OFF run re-arms it).
    fn latch_note_gate_on(&self, strategy_id: &str) {
        if let Ok(mut m) = self.entry_latch_off_since.lock() {
            m.remove(strategy_id);
        }
    }

    /// The strategy's gate failed this scan. Starts the continuous OFF timer and
    /// re-arms the latch once the OFF run reaches `secs`. `secs <= 0` re-arms on
    /// the first OFF scan.
    fn latch_note_gate_off(&self, strategy_id: &str, secs: f64) {
        let now = now_ms();
        let rearm = {
            let Ok(mut off) = self.entry_latch_off_since.lock() else { return };
            if off.len() > 5000 {
                off.clear();
            }
            let since = *off.entry(strategy_id.to_string()).or_insert(now);
            now - since >= (secs.max(0.0) * 1000.0) as i64
        };
        if rearm {
            if let Ok(mut a) = self.entry_latch_armed.lock() {
                if a.len() > 5000 {
                    a.clear();
                }
                a.insert(strategy_id.to_string(), true);
            }
        }
    }

    /// "Re-entry cooldown": whether a new entry on this strategy is still inside
    /// its post-close cooldown window.
    fn entry_cooldown_active(&self, strategy_id: &str) -> bool {
        let now = now_ms();
        self.entry_cooldown_until
            .lock()
            .ok()
            .and_then(|m| m.get(strategy_id).copied())
            .map(|until| now < until)
            .unwrap_or(false)
    }

    /// Start the post-close cooldown for a strategy. Called on every position
    /// close; a later close on the same strategy extends the window.
    fn mark_entry_cooldown(&self, strategy_id: &str, secs: f64) {
        if secs <= 0.0 {
            return;
        }
        if let Ok(mut m) = self.entry_cooldown_until.lock() {
            if m.len() > 5000 {
                m.clear();
            }
            m.insert(strategy_id.to_string(), now_ms() + (secs * 1000.0) as i64);
        }
    }

    /// Trades already taken for a strategy: open positions plus closed trades.
    /// The "Trades per strategy / Max trades" cap is counted against this.
    fn trades_done(&self, strategy_id: &str) -> i64 {
        self.doc()
            .map(|d| {
                d.positions.iter().filter(|p| js(p, "strategyId") == strategy_id).count()
                    + d.closed.iter().filter(|c| js(c, "strategyId") == strategy_id).count()
            })
            .unwrap_or(0) as i64
    }

    /// True when a running position already holds this exact option contract
    /// (same `securityId`). Used to stop the engine from opening a second entry
    /// on a strike that is already being traded - a fresh-signal re-trigger, a
    /// second strategy resolving to the same strike, or a scan after a restart
    /// (which clears the in-memory signal edge) must not double the position.
    fn contract_running(&self, security_id: i64) -> bool {
        if security_id <= 0 {
            return false;
        }
        self.doc()
            .map(|d| d.positions.iter().any(|p| ji(p, "securityId") == security_id))
            .unwrap_or(false)
    }

    /// Whether a new entry on `security_id` must be blocked as a duplicate of an
    /// already-running position on the same contract. `guard` is false for the
    /// operator-driven Manual Order Placement path; the explicit multi-position
    /// modes are exempt: "repeat while condition holds" (mode B) stacks every
    /// scan, and "fresh signal par position" (mode A) opens one position per new
    /// bar - both must be allowed to stack on the same strike, as designed.
    fn duplicate_entry_blocked(&self, settings: &Settings, security_id: i64, guard: bool) -> bool {
        guard && !settings.multi_always_on && !settings.multi_fresh_on && self.contract_running(security_id)
    }

    /// Open positions whose exposure sits on the OPPOSITE direction of `dir` for
    /// the canonical `underlying`. `dir` is +1 for a bullish exposure (a long
    /// call / long future) and -1 for a bearish one (a long put / short future),
    /// as computed by [`option_exposure_dir`]. Returns `(position id, side)` for
    /// every conflicting row so the caller can close exactly those.
    ///
    /// This is the "one side per underlying" guard. The bullish CE leg and the
    /// bearish PE leg are two separate synthetic strategies, so the legacy
    /// one-position-per-strategy rule never saw them as a pair: a trend flip
    /// opened the opposite leg while the old one was still live and the two legs
    /// cancelled each other's profit. Underlying (not contract) granularity is
    /// what makes the pair visible.
    fn opposite_side_positions(&self, underlying: &str, dir: i32) -> Vec<(String, String)> {
        if underlying.trim().is_empty() || dir == 0 {
            return Vec::new();
        }
        let want = underlying.trim().to_uppercase();
        self.doc()
            .map(|d| {
                d.positions
                    .iter()
                    .filter(|p| {
                        js(p, "underlying").trim().to_uppercase() == want
                            && option_exposure_dir(&js(p, "side"), &js(p, "tradingSymbol")) != dir
                    })
                    .map(|p| (js(p, "id"), js(p, "side")))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Enforce "one side per underlying" for a pending entry on `leg`. When the
    /// guard is off or the leg has no opposite-side conflict it returns
    /// `Ok(None)`. On a conflict it leaves the running position completely
    /// untouched and returns `Ok(Some(reason))` so the caller blocks THIS entry.
    ///
    /// It deliberately does NOT close the opposite leg: force-closing it booked a
    /// `SIDE_FLIP` loss every time a trend wobbled, then re-opened the new side
    /// and churned again on the next flip - the exact self-inflicted bleeding the
    /// guard was supposed to stop. The running position must exit on its own plan
    /// (target / stop / regime flip); the guard's only job is to refuse to add an
    /// opposite exposure underneath it.
    async fn enforce_one_side_per_underlying(
        &self,
        settings: &Settings,
        leg: &Strategy,
        entry_side: &str,
    ) -> Result<Option<String>, String> {
        if !settings.one_side_per_underlying {
            return Ok(None);
        }
        let underlying = underlying_of(&leg.trading_symbol, &leg.exchange_segment);
        let dir = option_exposure_dir(entry_side, &leg.trading_symbol);
        let conflicts = self.opposite_side_positions(&underlying, dir);
        if conflicts.is_empty() {
            return Ok(None);
        }
        let sides: Vec<String> = conflicts.iter().map(|(_, s)| s.clone()).collect();
        Ok(Some(format!(
            "{} - {:?} already running on {underlying}; opposite {} entry blocked until it exits",
            leg.name,
            sides,
            if dir > 0 { "bullish" } else { "bearish" }
        )))
    }

    /// Margin bar readout for the Running Trades section. Takes the already
    /// cloned settings/positions plus the caller-resolved available funds so a
    /// caller holding the doc lock never re-locks it (the paper wallet is derived
    /// from the very same doc snapshot).
    fn margin_info_from(&self, positions: &[Value], available: f64) -> Value {
        let balance = available.max(0.0);
        // Budget = this tab's shared allotment (the only margin source).
        let budget = self.margin_budget();
        let cap = crate::shared_margin::cap_for(self.engine_id());
        let (locked, count) = locked_margin_of(positions);
        json!({
            "budget": round2(budget),
            "locked": round2(locked.max(0.0)),
            "available": round2((budget - locked.max(0.0)).max(0.0)),
            "count": count,
            "configured": cap.map(|c| c > 0.0).unwrap_or(false),
            "allotted": cap.map(|c| c > 0.0).unwrap_or(false),
            "pct": Value::Null,
            "amount": round2(budget),
            "balance": round2(balance),
        })
    }

    /// Dhan `/margincalculator` response for a hypothetical order (margin
    /// required + broker-reported available balance).
    async fn margin_required(
        &self,
        sec_id: i64,
        exch: &str,
        side: &str,
        qty: i64,
        price: f64,
        product: &str,
    ) -> Option<MarginResponse> {
        if qty <= 0 || price <= 0.0 {
            return None;
        }
        // Paper mode never calls the broker margin calculator.
        if self.paper {
            return None;
        }
        // Indices are not tradable instruments, so Dhan rejects a margin request
        // for them (IDX_I). Skip the round-trip entirely - this is the selection
        // present on most option-chain / chart switches, and it used to stall the
        // switch for a throttle plus a rejected call.
        let exch_up = exch.to_uppercase();
        if exch_up.starts_with("IDX") || exch_up == "INDEX" {
            return None;
        }
        // Serve a recent answer for the same contract/side/size when the price has
        // barely moved. The broker margin API is rate-limited to ~1 call/second, so
        // without this cache a strike switch waited ~1.5-2s on it (and the chart's
        // own Dhan candle fetch then queued behind the same throttle).
        let key = format!(
            "{}:{}:{}:{}:{}",
            sec_id,
            exch_up,
            side.to_uppercase(),
            qty,
            product.to_uppercase()
        );
        const MARGIN_TTL_MS: i64 = 20_000;
        if let Ok(g) = self.margin_cache.lock() {
            if let Some((at, cached_price, resp)) = g.get(&key) {
                if now_ms() - *at < MARGIN_TTL_MS
                    && *cached_price > 0.0
                    && (price - *cached_price).abs() / *cached_price < 0.005
                {
                    return resp.clone();
                }
            }
        }
        let client = self.dhan.session_client().await?;
        let client_id = self.dhan.session_client_id().await?;
        let req = MarginRequest {
            dhan_client_id: client_id,
            exchange_segment: seg_from(exch),
            transaction_type: txn(side),
            quantity: qty,
            product_type: product_from(product),
            security_id: sec_id.to_string(),
            price,
            trigger_price: None,
        };
        self.dhan.dhan_acct_throttle().await;
        // A rejected request (bad contract / rate limit) is cached as `None` so the
        // UI answers instantly instead of re-paying the throttle on every switch.
        let resp = client.margin_calculator(&req).await.ok();
        if let Ok(mut g) = self.margin_cache.lock() {
            if g.len() > 512 {
                g.retain(|_, (at, _, _)| now_ms() - *at < MARGIN_TTL_MS);
            }
            g.insert(key, (now_ms(), price, resp.clone()));
        }
        resp
    }

    /// Orders/sec budget: true when fewer than `max_per_sec` orders were
    /// placed in the trailing second.
    #[allow(dead_code)]
    fn order_allow(&self, max_per_sec: i64) -> bool {
        if max_per_sec <= 0 {
            return false;
        }
        let now = now_ms();
        let mut g = match self.order_times.lock() {
            Ok(g) => g,
            Err(_) => return true,
        };
        g.retain(|t| now - *t < 1000);
        (g.len() as i64) < max_per_sec
    }

    #[allow(dead_code)]
    fn order_record(&self) {
        let now = now_ms();
        if let Ok(mut g) = self.order_times.lock() {
            g.push(now);
        }
    }

    // -----------------------------------------------------------------------
    // Engine loop
    // -----------------------------------------------------------------------

    /// Background scanner pass: Top Movers, Liquid F&O and every trend section.
    ///
    /// This is the engine's heaviest Dhan REST consumer (whole-universe quote
    /// walks + candle fetches). It used to run inline in the engine loop, so a
    /// `429` hold (10s, doubling to 120s) blocked the loop itself: the heartbeat
    /// went stale and NOTHING was evaluated - the trade-less stall this task
    /// exists to prevent. It now runs on its own task, never concurrently with
    /// itself, and the engine loop only reads the caches it publishes.
    fn spawn_scanners(self) {
        tokio::spawn(async move {
            loop {
                // Manual Strike Select owns the readout: pause the scanner
                // universe exactly like the inline version did.
                let manual = self
                    .doc()
                    .map(|d| d.settings.manual_strikes_enabled)
                    .unwrap_or(false);
                if !manual && !self.scanner_busy.swap(true, Ordering::AcqRel) {
                    self.refresh_movers().await;
                    self.refresh_liquid().await;
                    self.refresh_equity_liquidity(false).await;
                    self.refresh_nifty_trend().await;
                    self.refresh_nifty_scan().await;
                    self.refresh_commodity_picked().await;
                    self.refresh_index_comm_trends().await;
                    self.scanner_heartbeat.store(now_ms(), Ordering::Relaxed);
                    self.scanner_busy.store(false, Ordering::Release);
                }
                // The individual refreshes keep their own cadence throttles; this
                // only bounds how often the pass is re-attempted.
                tokio::time::sleep(Duration::from_millis(250)).await;
            }
        });
    }

    /// Record a `scanner-stale` blocker when the background scanner pass has not
    /// completed for a while, so a rate-limited / parked scanner is visible in
    /// the "Why no trades?" panel instead of silently producing no picks.
    fn note_stale_scanner(&self) {
        let stamp = self.scanner_heartbeat.load(Ordering::Relaxed);
        if stamp <= 0 {
            return;
        }
        let age = now_ms().saturating_sub(stamp);
        if age >= SCANNER_STALE_MS {
            let hold = self.dhan.rate_hold_remaining();
            let detail = if hold > 0.0 {
                format!(
                    "scanner pass has not completed for {}s - Dhan data gate is holding {} more seconds after a 429 (picks are frozen, entries resume when it clears)",
                    age / 1000,
                    hold
                )
            } else {
                format!(
                    "scanner pass has not completed for {}s - Top Movers / Liquid F&O picks are frozen until it returns",
                    age / 1000
                )
            };
            self.note_blocker("warn", "scanner-stale", "", &detail);
        } else {
            self.clear_blocker_codes(&["scanner-stale"]);
        }
    }

    fn spawn_engine(self) {
        tokio::spawn(async move {
            // Engine loop. Housekeeping runs on a base ~100ms cadence; the entry
            // scan is additionally throttled by the "Engine Scan" setting when it
            // is enabled (see `scan_interval_on` / `scan_interval_ms`). Exits are
            // never throttled - they live in the dedicated 50ms guardian task.
            let mut last_scan = 0i64;
            // Last bar bucket seen in "Countdown to Bar Close" scan mode; a change
            // means a new bar just opened, which is exactly when we scan.
            let mut last_bar_bucket = 0i64;
            loop {
                self.loop_heartbeat.store(now_ms(), Ordering::Relaxed);
                self.loop_passes.fetch_add(1, Ordering::Relaxed);
                // The master switch owns run/stop; this only keeps `armed`
                // consistent with it (and re-arms on the next IST day while the
                // master stays ON). Auto square-off keeps today's entries blocked.
                self.sync_auto_armed();
                // Scanners run whenever their own toggle is ON, independent of the
                // engine run/arm state, so the Top Movers / commodity readouts
                // always fetch (old app polled them outside the run gate).
                // Both the real and paper engines behave identically here; each
                // engine owns its own settings/toggles, so an idle tab only fetches
                // for scanners the operator enabled on that tab.
                let manual_mode = self
                    .doc()
                    .map(|d| d.settings.manual_strikes_enabled)
                    .unwrap_or(false);
                // The scanner REST work runs on its OWN task (see
                // `spawn_scanners`): it is the biggest Dhan data consumer and a
                // rate-limit hold there must never freeze the evaluation loop
                // that this heartbeat proves alive. The loop only publishes the
                // manual rows and reads the scanner caches.
                if manual_mode {
                    // Manual Strike Select (testing): the scanner universes are
                    // inactive, and the Picked Strikes readout is the manual list.
                    self.refresh_manual_picked();
                } else {
                    // Leaving manual mode: drop any leftover manual rows so the
                    // scanner readouts own the list again.
                    self.update_picked("Manual", Vec::new());
                    self.note_stale_scanner();
                }
                // Broker account (funds/positions/holdings) and open-position LTP
                // refresh regardless of run/arm, so the Account view is live
                // whenever Dhan is connected (the old app fetched account data on
                // demand, independent of the engine run state).
                self.refresh().await;
                self.reconcile_fills().await;
                // Resync the broker book on the reconnect edge so a stop leg that
                // fired (or a manual fill) while the feed was down is never lost.
                self.reconcile_reconnect().await;
                let force = self.force_tick.swap(false, Ordering::Relaxed);
                if force {
                    self.log("info", "Force tick: immediate evaluation pass");
                }
                // Read the run state plus the Engine Scan config in a single lock.
                let (on, armed, scan_on, scan_ms, scan_bc, scan_bc_tf) = self
                    .doc()
                    .map(|d| {
                        (
                            d.engine_on,
                            d.armed,
                            d.settings.scan_interval_on,
                            d.settings.scan_interval_ms,
                            d.settings.scan_bar_close,
                            d.settings.scan_bar_close_tf.clone(),
                        )
                    })
                    .unwrap_or((false, false, false, 100, false, "1min".into()));
                if !on {
                    self.note_blocker(
                        "warn",
                        "engine-state",
                        "",
                        "engine is OFF - turn on AI Smart Trading to evaluate signals",
                    );
                }
                if on {
                    self.check_square_off().await;
                    self.check_fno_expiry_square_off().await;
                    if !armed {
                        // Running-but-disarmed places no orders. Surface it on a
                        // throttle so the Condition Log always explains why the
                        // engine looks active yet nothing is being traded.
                        self.note_blocker(
                            "warn",
                            "engine-state",
                            "",
                            "engine ON but disarmed for today - automatic square-off already ran, re-arms next IST day",
                        );
                        self.log_throttled(
                            "engine-disarmed",
                            15_000,
                            "warn",
                            "engine ON, new entries blocked for today because the automatic square-off already ran (auto re-arms next IST day)",
                        );
                    }
                    if armed {
                        self.clear_blocker_codes(&["engine-state"]);
                        // Autonomous brain: while Auto Trading is ON, refresh the
                        // regime + filter ranking (throttled internally) before the
                        // entry scan reads those settings.
                        self.brain_tick().await;
                        // "Engine Scan" throttle. Three cases:
                        //   OFF            -> scan every loop (historical ~100ms).
                        //   ON + bar-close -> scan the instant the selected
                        //                     timeframe rolls to a new bar.
                        //   ON + interval  -> scan every `scan_ms`.
                        // A manual Run / Tick Now always bypasses the wait.
                        let due = if force || !scan_on {
                            true
                        } else if scan_bc {
                            let step = scan_bar_close_step_ms(&scan_bc_tf);
                            now_ms() / step != last_bar_bucket
                        } else {
                            now_ms().saturating_sub(last_scan) >= scan_ms
                        };
                        if due {
                            self.scan_signals().await;
                            last_scan = now_ms();
                            if scan_bc {
                                last_bar_bucket = now_ms() / scan_bar_close_step_ms(&scan_bc_tf);
                            }
                        }
                    }
                } else {
                    // Idle: forget the last bar so re-arming in bar-close mode
                    // fires an immediate scan instead of waiting for the next bar.
                    last_bar_bucket = 0;
                }
                // Broker-side Super legs can trigger while the master is OFF, so
                // reconcile them whenever an engine-held position exists. (Position
                // protection itself lives in the dedicated 50ms guardian task, so
                // a slow scanner REST call can never delay a trailing-stop exit.)
                self.reconcile_super().await;
                // Base cadence: wake at most every 100ms for housekeeping, but
                // honour a sub-100ms Engine Scan value (e.g. 50ms) instead of
                // rounding it up. A larger interval (or bar-close mode) simply
                // leaves the scan gated - 100ms is fast enough to catch a bar
                // boundary the moment it happens.
                let base_ms = if on && scan_on && !scan_bc {
                    scan_ms.clamp(SCAN_INTERVAL_MIN_MS, 100)
                } else {
                    100
                };
                tokio::time::sleep(Duration::from_millis(base_ms.max(SCAN_INTERVAL_MIN_MS) as u64)).await;
            }
        });
    }

    /// Dedicated ultrafast position guardian.
    ///
    /// Runs on its own 50ms timer, independent of the network-bound scanner /
    /// entry loop, so an open trade's trailing stop (and SL / TP) is evaluated
    /// against the freshest tick and booked the instant it is hit. This is what
    /// makes a reversing trade cut immediately instead of after the scanner's
    /// REST round-trips. It only ever exits - new entries stay gated by the main
    /// engine loop's arm state.
    fn spawn_guard(self) {
        tokio::spawn(async move {
            // Wake on every applied market tick so a reversing trade is cut on
            // the very tick that breaches its stop, not on the next poll. The
            // 50ms interval is only a fallback for when the feed is quiet.
            let notify = self.dhan.market.tick_notify();
            let mut tick = tokio::time::interval(Duration::from_millis(50));
            tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            loop {
                let (engine_on, has_positions) = self
                    .doc
                    .lock()
                    .map(|d| (d.engine_on, !d.positions.is_empty()))
                    .unwrap_or((false, false));
                if engine_on || has_positions {
                    tokio::select! {
                        _ = notify.notified() => {}
                        _ = tick.tick() => {}
                    }
                } else {
                    // Idle: don't wake (and take the state lock) on every
                    // market tick; the 50ms poll is enough to notice a position.
                    tick.tick().await;
                }
                // Exits (SL / TP / trail) are managed only while the live feed is
                // streaming, so a stale mark can never book a fake fill. They stay
                // active even when the master switch is OFF as long as a position
                // is open: OFF stops NEW entries, never the protection of an
                // already-running trade.
                if self.dhan.feed_live()
                    && (engine_on
                        || self.doc().map(|d| !d.positions.is_empty()).unwrap_or(false))
                {
                    self.manage_positions().await;
                }
            }
        });
    }

    /// Dedicated tick-native NIFTY trend watchdog.
    ///
    /// Wakes on every applied market tick and re-reads the live forming candle
    /// series, so a bullish<->bearish flip on the assigned straight-line
    /// indicators is applied within milliseconds - never on a candle close. A
    /// 200ms poll is only the fallback for when the feed is quiet.
    fn spawn_nifty_watch(self) {
        tokio::spawn(async move {
            let notify = self.dhan.market.tick_notify();
            let mut tick = tokio::time::interval(Duration::from_millis(200));
            tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            loop {
                tokio::select! {
                    _ = notify.notified() => {}
                    _ = tick.tick() => {}
                }
                let on = self
                    .doc()
                    .map(|d| d.settings.nifty_trend_on && !d.settings.manual_strikes_enabled)
                    .unwrap_or(false);
                if on {
                    self.refresh_nifty_flip().await;
                }
            }
        });
    }

    /// Refresh broker positions, funds and option LTP (rate limited).
    async fn refresh(&self) {
        // Paper mode: publish the virtual wallet (capital + realized P&L - locked
        // margin) into the same funds cache the UI reads, and never call the Dhan
        // account/position/holding APIs. Live leg prices come from the shared
        // quote cache populated by the Dhan feed.
        if self.paper {
            let now = now_ms();
            if now - self.last_funds.load(Ordering::Relaxed) >= 1500 {
                self.last_funds.store(now, Ordering::Relaxed);
                let avail = self.paper_available();
                let cap = paper_base_of(self.engine_id());
                let realized = self.paper_realized();
                if let Ok(mut g) = self.funds.lock() {
                    *g = json!({
                        "availabelBalance": round2(avail),
                        "availableBalance": round2(avail),
                        "openingBalance": round2(cap),
                        "realizedPnl": round2(realized),
                        "paper": true,
                    });
                }
            }
            // Mark open paper positions to the shared Dhan feed quote cache. This
            // is websocket-fed (no REST), and refreshing it here - independent of
            // the paper engine run/arm state - matches how the real tab keeps its
            // LTP cache fresh, so the paper ledger P&L is live even while stopped.
            let open: Vec<(i64, String)> = self
                .doc()
                .map(|d| {
                    d.positions
                        .iter()
                        .map(|p| (ji(p, "securityId"), js(p, "exchangeSegment")))
                        .collect()
                })
                .unwrap_or_default();
            if !open.is_empty() {
                let marks: Vec<(i64, f64)> = {
                    match self.dhan.market.quotes.lock() {
                        Ok(q) => open
                            .iter()
                            .filter_map(|(sid, exch)| {
                                if *sid <= 0 {
                                    return None;
                                }
                                let key = crate::market::quote_key(*sid, exch);
                                q.get(&key)
                                    .and_then(|v| v.get("ltp"))
                                    .and_then(|x| x.as_f64())
                                    .filter(|p| *p > 0.0)
                                    .map(|p| (*sid, p))
                            })
                            .collect(),
                        Err(_) => Vec::new(),
                    }
                };
                if !marks.is_empty() {
                    if let Ok(mut m) = self.ltp.lock() {
                        for (sid, p) in marks {
                            m.insert(sid, p);
                        }
                    }
                }
            }
            return;
        }
        // The process-wide 2s poller owns the Dhan positions API; copy its
        // snapshot locally for the account view / residual square-off. No
        // per-engine portfolio call here.
        let shared_positions = self.dhan.positions_snapshot();
        if let Ok(mut g) = self.broker_positions.lock() {
            *g = shared_positions;
        }
        if !self.dhan.is_connected().await {
            return;
        }
        // Yield Dhan's single data slot while the operator is interacting
        // (chart / option chain / quotes); the 100ms engine tick retries.
        if self.dhan.user_active() {
            return;
        }
        let now = now_ms();
        let last_ltp = self.last_ltp.load(Ordering::Relaxed);
        if now - last_ltp >= 3000 {
            self.last_ltp.store(now, Ordering::Relaxed);
            let open: Vec<(i64, String)> = {
                self.doc()
                    .map(|d| {
                        d.positions
                            .iter()
                            .map(|p| (ji(p, "securityId"), js(p, "exchangeSegment")))
                            .collect()
                    })
                    .unwrap_or_default()
            };
            if !open.is_empty() {
                let mut req: BTreeMap<String, Vec<i64>> = BTreeMap::new();
                for (sid, seg) in open {
                    if sid > 0 {
                        req.entry(seg).or_default().push(sid);
                    }
                }
                if let Some(client) = self.dhan.session_client().await {
                    self.dhan.dhan_throttle().await;
                    match client.market_feed_ltp(&req).await {
                        Ok(resp) => {
                            if let Ok(mut m) = self.ltp.lock() {
                                for (_seg, legs) in resp {
                                    for (sid, e) in legs {
                                        if let Ok(id) = sid.parse::<i64>() {
                                            if e.last_price > 0.0 {
                                                m.insert(id, e.last_price);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        Err(e) => {
                            let _ = e;
                        }
                    }
                }
            }
        }

        let last_funds = self.last_funds.load(Ordering::Relaxed);
        if now - last_funds >= 30000 {
            self.last_funds.store(now, Ordering::Relaxed);
            if let Some(client) = self.dhan.session_client().await {
                self.dhan.dhan_acct_throttle().await;
                match client.fund_limit().await {
                    Ok(f) => {
                        // Real Dhan money drives the REALTIME shared-margin pool
                        // (see `shared_margin`): every live tab is allotted a
                        // slice of this single real balance. A genuine ₹0 balance
                        // is recorded too, so an empty account can never trade.
                        if !self.paper {
                            crate::shared_margin::set_live_funds(f.availabel_balance);
                        }
                        if let Ok(mut g) = self.funds.lock() {
                            *g = serde_json::to_value(&f).unwrap_or(json!({}));
                        }
                    }
                    Err(e) => self.log_throttled(
                        "acct-funds",
                        30_000,
                        "warn",
                        &format!("funds fetch failed: {e}"),
                    ),
                }
                self.dhan.dhan_acct_throttle().await;
                match client.holdings().await {
                    Ok(rows) => {
                        let vals: Vec<Value> = rows
                            .iter()
                            .map(|h| serde_json::to_value(h).unwrap_or(Value::Null))
                            .collect();
                        if let Ok(mut g) = self.broker_holdings.lock() {
                            *g = vals;
                        }
                    }
                    Err(e) if e.is_empty_holdings() => {
                        // A clean account with no delivery holdings is not a
                        // failure: Dhan answers DH-1111 instead of an empty list.
                        // Cache it as empty and keep the Condition Log quiet.
                        if let Ok(mut g) = self.broker_holdings.lock() {
                            g.clear();
                        }
                    }
                    Err(e) => self.log_throttled(
                        "acct-holdings",
                        30_000,
                        "warn",
                        &format!("holdings fetch failed: {e}"),
                    ),
                }
            }
        }
    }

    async fn check_square_off(&self) {
        let (enabled, at, day) = {
            let Some(d) = self.doc() else { return };
            (d.settings.auto_square_off_enabled, d.settings.auto_square_off_time.clone(), d.last_square_off_day.clone())
        };
        if !enabled {
            return;
        }
        let Some(at_min) = hhmm_to_minutes(&at) else { return };
        let today = ist_day_key();
        if day == today || ist_minutes() < at_min {
            return;
        }
        if let Some(d) = self.doc() {
            if d.positions.is_empty() {
                return;
            }
        }
        self.log("warn", &format!("auto square-off at {at}"));
        self.square_off_all("auto_square_off").await;
        if let Some(mut d) = self.doc() {
            d.last_square_off_day = today;
            d.armed = false;
        }
        self.save();
    }

    /// True when today (IST) is an F&O **stock** option expiry day according to
    /// the scrip master. Indices and commodities never qualify. Backs the
    /// Realtime / Paper Trade 1 expiry-day guard; cheap (short-circuits) and
    /// safe when the master is not loaded yet (returns false).
    fn fno_stock_expiry_today(&self) -> bool {
        let Some(sc) = scrip::get() else { return false };
        let day = (crate::market::now_secs() + 19_800) / 86_400;
        sc.is_stock_option_expiry_day(day)
    }

    /// F&O-stock expiry-day guard (Realtime + Paper Trade 1). On an F&O stock
    /// expiry day, once the IST clock reaches the operator's cutoff, square off
    /// every open F&O-stock option position exactly once (indices and
    /// commodities are left alone). Entries for F&O stocks are blocked from the
    /// same minute onwards by `fno_expiry_no_trade` in the scan loop, so no new
    /// stock position can reopen after the flat. The engine stays armed for the
    /// other instrument classes.
    async fn check_fno_expiry_square_off(&self) {
        let (enabled, at, day) = {
            let Some(d) = self.doc() else { return };
            (
                d.settings.fno_expiry_square_off_enabled,
                d.settings.fno_expiry_square_off_time.clone(),
                d.last_expiry_square_off_day.clone(),
            )
        };
        if !enabled {
            return;
        }
        let Some(at_min) = hhmm_to_minutes(&at) else { return };
        let today = ist_day_key();
        if day == today || ist_minutes() < at_min || !self.fno_stock_expiry_today() {
            return;
        }
        let ids: Vec<String> = self
            .doc()
            .map(|d| {
                d.positions
                    .iter()
                    .filter(|p| {
                        category_for(&js(p, "exchangeSegment"), &js(p, "instrument")) == StratCat::Fno
                    })
                    .map(|p| js(p, "id"))
                    .filter(|id| !id.is_empty())
                    .collect()
            })
            .unwrap_or_default();
        if ids.is_empty() {
            // Nothing to flatten today; mark the day so the guard does not
            // re-scan on every pass. The no-trade block still holds.
            if let Some(mut d) = self.doc() {
                d.last_expiry_square_off_day = today;
            }
            self.save();
            return;
        }
        self.log(
            "warn",
            &format!("F&O stock expiry auto square-off at {at} ({} position(s))", ids.len()),
        );
        for id in ids {
            let ltp = self.position_ltp(&id);
            let _ = self.close_position(&id, "fno_expiry_square_off", ltp).await;
        }
        if let Some(mut d) = self.doc() {
            d.last_expiry_square_off_day = today;
        }
        self.save();
    }

    // -----------------------------------------------------------------------
    // Top Movers scanner (auto CE/PE side)
    // -----------------------------------------------------------------------

    /// Strict-gate check for the NIFTY-trend universe (Top Movers Gainers/Losers
    /// + NIFTY-trend picks). `bull` = the leg being considered is a CE / Top
    /// Gainer leg. Returns `false` (hard block) when either enabled strict gate
    /// disagrees with the assigned straight-line confirmation indicators:
    ///   * net gate  (`nifty_net_strict`)       - CE needs raw net > 0, PE < 0;
    ///     a tie / dead-heat fails.
    ///   * agree gate (`nifty_all_agree_strict`) - CE needs every assigned line
    ///     bullish (+1), PE every line bearish (-1); a mixed read fails.
    /// With the feature off, no gate enabled, or NIFTY Trend Following off this
    /// is a no-op (`true`), so nothing else is affected.
    fn nifty_line_side_ok(&self, settings: &Settings, bull: bool) -> bool {
        if !nifty_dir_feature_on(settings) {
            return true;
        }
        // BB%b (Pane) CONFIRMATION gate. The NIFTY direction is owned solely by
        // the NIFTY Trend Following confirmation indicators; this section only
        // confirms that the side matches what its own modes ask for. A bullish
        // (CE) trend trades only while the BB%b line is bullish OR the zone is
        // oversold; a bearish (PE) trend is the exact mirror (line bearish OR
        // overbought). The dedicated COMBO switch requires BOTH the line AND the
        // zone to agree. Per-side checkboxes still apply: a side whose own toggle
        // is OFF is strictly blocked. A mode that is OFF contributes no condition,
        // and with no mode on the whole section restricts nothing.
        if settings.bbpct_pane_on {
            let want = if bull { 1 } else { -1 };
            let line_toggle = if bull { settings.bbpct_trend_bull_on } else { settings.bbpct_trend_bear_on };
            let zone_toggle = if bull { settings.bbpct_os_on } else { settings.bbpct_ob_on };
            let line_ok =
                line_toggle && self.nifty_bbpct_line_dir.load(Ordering::Relaxed) == want;
            let zone_ok = zone_toggle && self.nifty_zone_dir.load(Ordering::Relaxed) == want;
            if settings.bbpct_combo_on {
                // COMBO = double confirmation: line AND zone must both confirm.
                if !(line_ok && zone_ok) {
                    return false;
                }
            } else if settings.bbpct_trend_on || settings.bbpct_zone_on {
                // Individual modes = EITHER one may confirm this side.
                let line_term = settings.bbpct_trend_on && line_ok;
                let zone_term = settings.bbpct_zone_on && zone_ok;
                if !(line_term || zone_term) {
                    return false;
                }
            }
        }
        self.nifty_strict_side_ok(settings, bull)
    }

    /// Only the operator's strict NET / ALL-LINES-agree gates, without the
    /// BB%b (Pane) confirmation. The BB%b pane confirms the NIFTY-trend pick
    /// side; the Top Movers stock legs follow the committed NIFTY direction and
    /// these strict gates, but must not be blocked by a conflicting BB%b zone -
    /// that combination used to stop every movers leg (no strike picks, no
    /// trades) while the committed direction itself was perfectly tradeable.
    fn nifty_strict_side_ok(&self, settings: &Settings, bull: bool) -> bool {
        if !settings.nifty_net_strict && !settings.nifty_all_agree_strict {
            return true;
        }
        if settings.nifty_net_strict {
            let n = self.nifty_raw_net.load(Ordering::Relaxed);
            if bull && n <= 0 {
                return false;
            }
            if !bull && n >= 0 {
                return false;
            }
        }
        if settings.nifty_all_agree_strict {
            let a = self.nifty_agree.load(Ordering::Relaxed);
            if bull && a != 1 {
                return false;
            }
            if !bull && a != -1 {
                return false;
            }
        }
        true
    }

    /// Option side shown in the "No <side> option contracts" diagnostics:
    /// bullish filters -> CE, bearish filters -> PE (matches `target_option_side`).
    fn desired_option_side(&self, settings: &Settings, strat: &Strategy) -> String {
        self.target_option_side(strat, settings).to_string()
    }

    /// Scan universe for the Top Movers scanner: the full market
    /// catalog (dropdown symbols + market-watch companies), NIFTY itself and the
    /// operator's strategy symbols. Indices are only included when
    /// `include_indices` is set; MCX commodities only when `include_commodities`
    /// is set (they fall back to the default MCX set when no custom list exists).
    fn scan_universe(&self, include_indices: bool, include_commodities: bool) -> Vec<(i64, String)> {
        let mut out: Vec<(i64, String)> = Vec::new();
        let mut seen: std::collections::HashSet<i64> = std::collections::HashSet::new();
        // Operator-removed scanner picks: an excluded underlying never enters
        // the universe, so it is neither ranked (Top Movers) nor
        // resolved to an option leg nor traded, until it is restored.
        let excluded: std::collections::HashSet<i64> = self
            .doc()
            .map(|d| d.settings.scanner_exclude.iter().copied().collect())
            .unwrap_or_default();
        let push = |sid: i64, seg: String, out: &mut Vec<(i64, String)>, seen: &mut std::collections::HashSet<i64>| {
            if sid <= 0 || excluded.contains(&sid) || !seen.insert(sid) {
                return;
            }
            let u = seg.to_uppercase();
            if u == "IDX_I" && !include_indices {
                return;
            }
            if u == "MCX_COMM" && !include_commodities {
                return;
            }
            out.push((sid, seg));
        };
        for (sid, seg) in crate::market::securities() {
            push(sid, seg, &mut out, &mut seen);
        }
        if let Some(d) = self.doc() {
            for s in &d.strategies {
                if s.security_id > 0 {
                    push(s.security_id, s.exchange_segment.clone(), &mut out, &mut seen);
                }
            }
            if include_commodities {
                // Only the operator's explicitly added commodities enter the
                // universe; an empty list adds none (never the whole MCX set).
                for id in d.settings.commodity_list.clone() {
                    push(id, "MCX_COMM".to_string(), &mut out, &mut seen);
                }
            }
        }
        out
    }

    /// Build scanner rows for a `(security_id, segment)` universe. Prefers the
    /// live websocket quote cache (populated for every catalog symbol while the
    /// feed is up) and only falls back to Dhan's REST quote API for ids the feed
    /// has not streamed yet. Logs when a scan comes back empty.
    async fn quote_rows(&self, univ: &[(i64, String)]) -> Vec<Value> {
        let mut rows: Vec<Value> = Vec::new();
        let mut missing: Vec<(i64, String)> = Vec::new();
        {
            let cache = self.dhan.market.quotes.lock().ok();
            for (id, seg) in univ {
                if *id <= 0 {
                    continue;
                }
                let key = crate::market::quote_key(*id, seg);
                let cached = cache
                    .as_ref()
                    .and_then(|c| c.get(&key))
                    .filter(|q| q.get("synth").is_none());
                if let Some(q) = cached {
                    let prev = q.get("close").and_then(|x| x.as_f64()).unwrap_or(0.0);
                    let pct = q
                        .get("change_pct")
                        .and_then(|x| x.as_f64())
                        .unwrap_or_else(|| {
                            let chg = q.get("change").and_then(|x| x.as_f64()).unwrap_or(0.0);
                            if prev > 0.0 { chg / prev * 100.0 } else { 0.0 }
                        });
                    let ltp = q
                        .get("ltp")
                        .and_then(|x| x.as_f64())
                        .or_else(|| q.get("last").and_then(|x| x.as_f64()))
                        .unwrap_or(0.0);
                    if ltp > 0.0 {
                        rows.push(json!({
                            "securityId": id,
                            "segment": seg,
                            "last": ltp,
                            "changePct": pct,
                            "volume": q.get("volume").and_then(|x| x.as_f64()).unwrap_or(0.0),
                        }));
                        continue;
                    }
                }
                missing.push((*id, seg.clone()));
            }
        }
        if missing.is_empty() {
            if rows.is_empty() {
                self.log_throttled(
                    "scanner-quote-empty-cache",
                    15_000,
                    "warn",
                    &format!("scanner quote empty for {} ids (feed cache)", univ.len()),
                );
            }
            self.seed_ltp_from_rows(&rows);
            return rows;
        }
        // When the live websocket is NOT streaming the feed cache is empty and
        // this fallback would REST-fetch the whole universe on every ~100ms tick
        // - the loop that keeps Dhan rate-limited and makes the disconnect stick.
        // Allow only an occasional seed while the socket is down, and never while
        // the account is parked or already rate-limited.
        if !self.dhan.feed_live() || self.dhan.rate_limited() {
            if self.dhan.park_active() || self.dhan.rate_limited() {
                return rows;
            }
            let now = now_ms();
            let last = self.last_scan_rest.load(Ordering::Relaxed);
            if last != 0 && now - last < 15_000 {
                return rows;
            }
            self.last_scan_rest.store(now, Ordering::Relaxed);
        }
        let Some(client) = self.dhan.session_client().await else {
            self.log_throttled("scanner-quote-nosession", 15_000, "warn", "scanner quote: no Dhan session client");
            return rows;
        };
        for chunk in missing.chunks(100) {
            // A chunk may have charged the adaptive gate a `429` hold. Stop the
            // pass instead of paying the hold again for every remaining chunk.
            if self.dhan.rate_limited() {
                break;
            }
            let mut req: BTreeMap<String, Vec<i64>> = BTreeMap::new();
            for (id, seg) in chunk {
                if *id > 0 {
                    req.entry(seg.to_uppercase()).or_default().push(*id);
                }
            }
            if req.is_empty() {
                continue;
            }
            self.dhan.dhan_throttle().await;
            match client.market_feed_quote(&req).await {
                Ok(resp) => {
                    self.dhan.note_data_ok();
                    for (seg, m) in resp.iter() {
                        for (sid, q) in m.iter() {
                            let prev = q.ohlc.as_ref().map(|o| o.close).unwrap_or(0.0);
                            let pct = if prev > 0.0 { q.net_change / prev * 100.0 } else { 0.0 };
                            rows.push(json!({
                                "securityId": sid.parse::<i64>().unwrap_or(0),
                                "segment": seg,
                                "last": q.last_price,
                                "changePct": pct,
                                "volume": q.volume,
                            }));
                        }
                    }
                }
                Err(e) => {
                    if e.is_rate_limit() {
                        self.dhan.note_rate_limited();
                    }
                    self.log_throttled(
                        "scanner-quote-failed",
                        15_000,
                        "warn",
                        &format!("scanner quote failed ({} ids): {e}", chunk.len()),
                    )
                }
            }
        }
        if rows.is_empty() {
            self.log_throttled(
                "scanner-quote-empty",
                15_000,
                "warn",
                &format!("scanner quote empty for {} ids", univ.len()),
            );
        }
        // Seed the engine LTP cache from the poll we just paid for, so the entry
        // path reads the underlying's price here instead of making another
        // throttled quote call before it can resolve the option leg.
        self.seed_ltp_from_rows(&rows);
        rows
    }

    /// Liquid F&O scanner: ranks ONLY the liquid index-constituent basket
    /// (NIFTY 50 / BANK NIFTY / SENSEX / FINNIFTY / MIDCAP NIFTY) so every pick
    /// is a stock whose options actually trade. Mirrors the Top Movers payload
    /// shape (`gainers` / `losers` / `bias`) so the UI can reuse its chip
    /// renderer, and also returns the operator's manual adds.
    /// Full NSE cash-equity universe from the scrip master: `(security id,
    /// symbol, exchange segment)`. Only genuine `EQUITY` / series `EQ` rows on
    /// NSE are returned - no indices, no F&O, no BSE duplicates. Returns an
    /// empty list while the master is still warming.
    fn equity_universe() -> Vec<(i64, String, String)> {
        let Some(sc) = scrip::get() else { return Vec::new() };
        let mut out: Vec<(i64, String, String)> = Vec::new();
        for sid in sc.contract_ids() {
            let Some(c) = sc.contract(sid) else { continue };
            if !c.exchange.eq_ignore_ascii_case("NSE") {
                continue;
            }
            if !(c.instrument.eq_ignore_ascii_case("EQUITY") || c.instrument.eq_ignore_ascii_case("EQ")) {
                continue;
            }
            if c.underlying.trim().is_empty() {
                continue;
            }
            out.push((sid, c.underlying.clone(), "NSE_EQ".to_string()));
        }
        out.sort_by(|a, b| a.0.cmp(&b.0));
        out
    }

    /// Chunked `/marketfeed/quote` walk over a large universe. Returns
    /// `(security id, turnover ₹, last price, change %)` per resolved row.
    /// Turnover uses the session VWAP (`average_price`) when Dhan sends it, else
    /// the last traded price. Rate-limit holds stop the pass early instead of
    /// paying the hold for every remaining chunk.
    async fn equity_turnover_rows(&self, univ: &[(i64, String)]) -> Vec<(i64, f64, f64, f64)> {
        let Some(client) = self.dhan.session_client().await else {
            self.log_throttled(
                "equity-liquidity-nosession",
                60_000,
                "warn",
                "equity liquidity scan: no Dhan session client",
            );
            return Vec::new();
        };
        let mut out: Vec<(i64, f64, f64, f64)> = Vec::with_capacity(univ.len());
        // Dhan's market-quote endpoint takes up to 1000 instruments per call, so
        // the whole NSE EQ universe (~1100-1200 names) needs only two requests
        // instead of a dozen. Fewer calls = less time queued behind the shared
        // 1.2s data gate = a scan that finishes in seconds, not minutes.
        for chunk in univ.chunks(1000) {
            // Wait out an adaptive rate-hold instead of aborting the sweep: a
            // manual scan must return the COMPLETE universe, and breaking here
            // would silently rank only the chunks fetched before the 429.
            while self.dhan.rate_limited() {
                tokio::time::sleep(Duration::from_millis(500)).await;
            }
            let mut req: BTreeMap<String, Vec<i64>> = BTreeMap::new();
            for (sid, _sym) in chunk {
                req.entry("NSE_EQ".to_string()).or_default().push(*sid);
            }
            self.dhan.dhan_throttle().await;
            match client.market_feed_quote(&req).await {
                Ok(resp) => {
                    self.dhan.note_data_ok();
                    for (_seg, m) in resp.iter() {
                        for (sid, q) in m.iter() {
                            let Ok(sid) = sid.parse::<i64>() else { continue };
                            let px = if q.average_price > 0.0 { q.average_price } else { q.last_price };
                            if px <= 0.0 || q.volume <= 0.0 {
                                continue;
                            }
                            let turnover = px * q.volume;
                            let prev = q
                                .ohlc
                                .as_ref()
                                .map(|o| o.close)
                                .filter(|c| *c > 0.0)
                                .unwrap_or_else(|| (q.last_price - q.net_change).max(0.0));
                            let pct = if prev > 0.0 { (q.last_price - prev) / prev * 100.0 } else { 0.0 };
                            out.push((sid, turnover, q.last_price, pct));
                        }
                    }
                }
                Err(e) => {
                    if e.is_rate_limit() {
                        self.dhan.note_rate_limited();
                    }
                    self.log_throttled(
                        "equity-liquidity-quote-failed",
                        30_000,
                        "warn",
                        &format!("equity liquidity scan quote failed ({} ids): {e}", chunk.len()),
                    );
                }
            }
        }
        let mut seed: Vec<Value> = Vec::with_capacity(out.len());
        for (sid, _t, last, pct) in &out {
            seed.push(json!({ "securityId": sid, "segment": "NSE_EQ", "last": last, "changePct": pct, "volume": 0.0 }));
        }
        self.seed_ltp_from_rows(&seed);
        out
    }

    /// Daily full-universe cash-equity liquidity scan for the Equity Indicator
    /// Based Trade book. Ranks the whole NSE EQ universe by a **turnover +
    /// growth** score (today's turnover ₹ crore, boosted by the same-time growth
    /// versus the previous scan day), persists the per-day turnover baseline so
    /// the growth comparison survives a restart, and publishes the ranked rows
    /// to `equity_liquidity_cache` for the dropdown and the trade universe.
    ///
    /// It runs at most once per IST day at `liquid_scan_time` (or when the
    /// operator forces "Scan now"), never concurrently, and is a no-op for every
    /// non-equity engine.
    async fn refresh_equity_liquidity(&self, force: bool) {
        let settings = match self.doc() {
            Some(d) => d.settings.clone(),
            None => return,
        };
        if !(self.equity_indicators_only() || settings.equity_only) {
            return;
        }
        // The scheduled scan belongs to the armed universe; when the liquid
        // master is OFF an automatic pass would just burn Dhan data slots for a
        // list nobody trades. A forced "Scan now" still runs so the operator can
        // preview the ranking before arming.
        let forced = force || self.equity_liquidity_force.load(Ordering::Relaxed);
        if !settings.liquid_on && !forced {
            return;
        }
        let now = now_ms();
        if !force && now - self.last_equity_liquidity.load(Ordering::Relaxed) < 30_000 {
            return;
        }
        let today = ist_day_key();
        // Rehydrate from disk on the first pass after a restart: if today's scan
        // was already persisted, restore it so the dropdown fills without paying
        // for a fresh full-universe scan (the day-key guard then sees it done).
        {
            let empty = self
                .equity_liquidity_cache
                .lock()
                .map(|g| g.1.as_object().map(|o| o.get("stocks").and_then(|v| v.as_array()).map(|a| a.is_empty()).unwrap_or(true)).unwrap_or(true))
                .unwrap_or(false);
            if empty {
                if let Ok(s) = std::fs::read_to_string(state_path(EQUITY_LIQUIDITY_FILE)) {
                    if let Ok(v) = serde_json::from_str::<Value>(&s) {
                        if v.get("day").and_then(|d| d.as_str()) == Some(today.as_str())
                            && v.get("stocks").and_then(|d| d.as_array()).map(|a| !a.is_empty()).unwrap_or(false)
                        {
                            let at = v.get("at").and_then(|d| d.as_i64()).unwrap_or(now);
                            let mut payload = v.clone();
                            if let Some(o) = payload.as_object_mut() {
                                o.insert("ok".into(), json!(true));
                            }
                            if let Ok(mut c) = self.equity_liquidity_cache.lock() {
                                *c = (at, payload);
                            }
                        }
                    }
                }
            }
        }
        // Decide whether a scan is due: forced, or the cache was not computed on
        // the current IST day and the clock has reached the operator's scan time.
        let scan_day = {
            let c = self.equity_liquidity_cache.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
            c.get("day").and_then(|v| v.as_str()).unwrap_or("").to_string()
        };
        let due = force
            || self.equity_liquidity_force.swap(false, Ordering::AcqRel)
            || (scan_day != today
                && hhmm_to_minutes(&settings.liquid_scan_time)
                    .map(|m| ist_minutes() >= m)
                    .unwrap_or(true));
        if !due {
            // Publish a "scheduled" payload so the UI can show when the next scan
            // will run instead of an empty dropdown. Deliberately carries NO
            // `day` key: stamping the day here would make the due check believe
            // today's scan already ran and never fire it.
            if let Ok(mut c) = self.equity_liquidity_cache.lock() {
                if !c.1.is_object() {
                    *c = (
                        now,
                        json!({
                            "ok": true,
                            "on": settings.liquid_on,
                            "at": now,
                            "scheduled": settings.liquid_scan_time,
                            "stocks": [],
                        }),
                    );
                }
            }
            return;
        }
        if self.equity_liquidity_busy.swap(true, Ordering::AcqRel) {
            return;
        }
        // RAII guard: whatever happens (request cancelled, Dhan timeout, early
        // return) the busy flag is released, so one aborted scan can never wedge
        // every future scan behind a stuck flag.
        struct BusyGuard(Arc<AtomicBool>);
        impl Drop for BusyGuard {
            fn drop(&mut self) {
                self.0.store(false, Ordering::Release);
            }
        }
        let _busy = BusyGuard(self.equity_liquidity_busy.clone());
        let payload = self.equity_liquidity_scan(&settings, &today).await;
        self.last_equity_liquidity.store(now_ms(), Ordering::Relaxed);
        match payload {
            Some(p) => {
                if let Ok(mut c) = self.equity_liquidity_cache.lock() {
                    *c = (now, p);
                }
            }
            None => {
                // Empty scan (master still warming / no data): remember the
                // attempt so the loop does not hammer REST every tick, but do
                // NOT stamp a day-key (so the next tick can retry once the
                // master is ready or the feed is up).
                if let Ok(mut c) = self.equity_liquidity_cache.lock() {
                    *c = (
                        now,
                        json!({
                            "ok": true,
                            "on": settings.liquid_on,
                            "at": now,
                            "waiting": "scrip",
                            "stocks": [],
                        }),
                    );
                }
            }
        }
    }

    /// The heavy part of [`refresh_equity_liquidity`]: build the universe, fetch
    /// quotes, apply the turnover + growth score and persist the baseline. Split
    /// out so the caller owns the busy-flag lifecycle.
    async fn equity_liquidity_scan(&self, settings: &Settings, today: &str) -> Option<Value> {
        let univ = Self::equity_universe();
        if univ.is_empty() {
            self.log_throttled(
                "equity-liquidity-nowarm",
                60_000,
                "warn",
                "equity liquidity scan: scrip master not ready (no NSE EQ rows)",
            );
            return None;
        }
        let rows = self
            .equity_turnover_rows(&univ.iter().map(|(sid, sym, _)| (*sid, sym.clone())).collect::<Vec<_>>())
            .await;
        if rows.is_empty() {
            return None;
        }
        // Load the persisted baseline. `cur` is the turnover map captured on the
        // last scan day; on a NEW day it becomes the previous-session baseline
        // (`prev`), which is what the growth score compares against.
        let path = state_path(EQUITY_LIQUIDITY_FILE);
        let file = std::fs::read_to_string(&path)
            .ok()
            .and_then(|s| serde_json::from_str::<Value>(&s).ok())
            .unwrap_or(Value::Null);
        let file_day = file.get("day").and_then(|v| v.as_str()).unwrap_or("").to_string();
        if file_day != today {
            // Roll: yesterday's captured turnovers become the baseline.
            let prev = file.get("cur").cloned().unwrap_or(json!({}));
            let mut merged = file.clone();
            if let Some(o) = merged.as_object_mut() {
                o.insert("prev".into(), prev);
            }
            return self.equity_liquidity_score(settings, today, rows, &merged);
        }
        self.equity_liquidity_score(settings, today, rows, &file)
    }

    /// Apply the turnover + growth score to the freshly fetched quote rows and
    /// persist the new ``{day, prev, cur}`` baseline. Pure-ish: the only side
    /// effect is the atomic file write.
    fn equity_liquidity_score(
        &self,
        settings: &Settings,
        today: &str,
        rows: Vec<(i64, f64, f64, f64)>,
        baseline: &Value,
    ) -> Option<Value> {
        let prev_map = baseline.get("prev").and_then(|v| v.as_object());
        let min_cr = settings.liquid_scan_min_turnover_cr.max(0.0);
        let names: HashMap<i64, String> = Self::equity_universe()
            .into_iter()
            .map(|(sid, sym, _)| (sid, sym))
            .collect();
        // The raw turnover capture (for tomorrow's baseline) is kept even for
        // names below the floor, so the growth comparison is complete next day.
        let mut cur_map = serde_json::Map::new();
        for (sid, turnover, _last, _pct) in &rows {
            cur_map.insert(sid.to_string(), json!(turnover));
        }
        let ranked = rank_liquidity(rows, prev_map, min_cr);
        let stocks: Vec<Value> = ranked
            .iter()
            .take(500)
            .map(|r| {
                json!({
                    "securityId": r.sid,
                    "name": names.get(&r.sid).cloned().unwrap_or_default(),
                    "segment": "NSE_EQ",
                    "instrument": "EQUITY",
                    "turnoverCr": round2(r.turnover / 1e7),
                    "growthPct": r.growth.map(|g| round2(g * 100.0)),
                    "score": round2(r.score),
                    "last": round2(r.last),
                    "changePct": round2(r.pct),
                })
            })
            .collect();
        // Persist the rolling baseline: `prev` stays the prior-session map, `cur`
        // becomes this scan's turnover map so TOMORROW's scan can compare. The
        // ranked `stocks` are stored too so a restart can rehydrate the dropdown
        // without re-scanning (the day-key guard then sees today's scan as done).
        let prev_obj = baseline.get("prev").cloned().unwrap_or(json!({}));
        let out_file = json!({
            "day": today,
            "at": now_ms(),
            "prev": prev_obj,
            "cur": Value::Object(cur_map),
            "stocks": stocks,
            "scanned": ranked.len(),
            "tradeCount": settings.liquid_trade_count,
            "minTurnoverCr": min_cr,
        });
        if let Ok(bytes) = serde_json::to_vec(&out_file) {
            let _ = write_atomic(&state_path(EQUITY_LIQUIDITY_FILE), &bytes);
        }
        self.log_throttled(
            "equity-liquidity-scanned",
            5_000,
            "info",
            &format!(
                "equity liquidity scan: {} quotes, {} ranked, top-{} armed",
                ranked.len(),
                stocks.len(),
                settings.liquid_trade_count
            ),
        );
        Some(json!({
            "ok": true,
            "on": settings.liquid_on,
            "at": now_ms(),
            "day": today,
            "scannedAt": now_ms(),
            "scanned": ranked.len(),
            "tradeCount": settings.liquid_trade_count,
            "minTurnoverCr": min_cr,
            "stocks": stocks,
        }))
    }

    async fn refresh_liquid(&self) {
        let now = now_ms();
        if now - self.last_liquid.load(Ordering::Relaxed) < 250 {
            return;
        }
        // The Equity Indicator Based Trade book has NO Liquid-F&O option scanner:
        // its universe is the daily cash-equity liquidity scan. Running the old
        // gainers/losers -> pick_legs resolver here is exactly what made the
        // equity tab show option strikes (YESBANK CE, ...). Publish an inert
        // payload instead (the equity scan owns `equity_liquidity_cache`).
        if self.equity_indicators_only()
            || self.doc().map(|d| d.settings.equity_only).unwrap_or(false)
        {
            self.update_picked("Liquid F&O", Vec::new());
            if let Ok(mut c) = self.liquid_cache.lock() {
                *c = (now, json!({ "ok": true, "on": false, "gainers": [], "losers": [], "added": [], "bias": 0, "equity": true }));
            }
            return;
        }
        // The Liquid F&O scanner belongs to the full engines (Realtime Trading
        // Engine and Paper Trade 1) only. Indices-only / commodities-only books
        // never expose it, so they neither scan the basket nor publish picks.
        if !self.allows_liquid_stocks() {
            self.update_picked("Liquid F&O", Vec::new());
            if let Ok(mut c) = self.liquid_cache.lock() {
                *c = (now, json!({ "ok": true, "on": false, "gainers": [], "losers": [], "added": [], "bias": 0 }));
            }
            return;
        }
        let (on, gain_n, lose_n, manual) = self
            .doc()
            .map(|d| {
                (
                    d.settings.liquid_on,
                    d.settings.liquid_gainers,
                    d.settings.liquid_losers,
                    d.settings.liquid_list.clone(),
                )
            })
            .unwrap_or((false, 3, 3, Vec::new()));
        if !on {
            self.update_picked("Liquid F&O", Vec::new());
            if let Ok(mut c) = self.liquid_cache.lock() {
                *c = (now, json!({ "ok": true, "on": false, "gainers": [], "losers": [], "added": [], "bias": 0 }));
            }
            return;
        }
        // Armed but the feed is not ready: publish an explicit "waiting" payload
        // instead of leaving the previous (possibly OFF) one in the cache, so the
        // readout never claims the scanner is off while its master is ON.
        if !self.dhan.is_connected().await || self.dhan.user_active() {
            if let Ok(mut c) = self.liquid_cache.lock() {
                *c = (
                    now,
                    json!({ "ok": true, "on": true, "at": now, "waiting": "dhan", "gainers": [], "losers": [], "added": [], "bias": 0 }),
                );
            }
            return;
        }
        self.last_liquid.store(now, Ordering::Relaxed);

        // The liquid basket plus any manual adds. Removed scanner picks are
        // honoured exactly like the Top Movers universe (one shared blacklist).
        let excluded: std::collections::HashSet<i64> = self
            .doc()
            .map(|d| d.settings.scanner_exclude.iter().copied().collect())
            .unwrap_or_default();
        let mut univ: Vec<(i64, String)> = Vec::new();
        let mut seen: std::collections::HashSet<i64> = std::collections::HashSet::new();
        for (sid, _name, seg) in crate::market::liquid_stocks() {
            if sid > 0 && !excluded.contains(&sid) && seen.insert(sid) {
                univ.push((sid, seg));
            }
        }
        for sid in &manual {
            if *sid > 0 && !excluded.contains(sid) && seen.insert(*sid) {
                univ.push((*sid, "NSE_EQ".to_string()));
            }
        }
        // Stream the liquid basket (and manual adds) on Ticker packets so its
        // ranking reads the websocket cache instead of REST-seeding the whole
        // basket on every pass. It used to be the one scanner with no
        // subscription at all, which is why it kept charging the data gate.
        self.dhan.watch_scanner_now(&univ);
        let rows: Vec<Value> = self.quote_rows(&univ).await;
        let mut sorted = rows.clone();
        sorted.sort_by(|a, b| jf(b, "changePct").partial_cmp(&jf(a, "changePct")).unwrap_or(std::cmp::Ordering::Equal));
        let gainers: Vec<Value> = sorted
            .iter()
            .filter(|r| jf(r, "changePct") > 0.0)
            .take(gain_n.max(0) as usize)
            .cloned()
            .collect();
        let mut sorted_l = rows.clone();
        sorted_l.sort_by(|a, b| jf(a, "changePct").partial_cmp(&jf(b, "changePct")).unwrap_or(std::cmp::Ordering::Equal));
        let losers: Vec<Value> = sorted_l
            .iter()
            .filter(|r| jf(r, "changePct") < 0.0)
            .take(lose_n.max(0) as usize)
            .cloned()
            .collect();
        let bias = movers_auto_bias(
            gain_n > 0 && !gainers.is_empty(),
            lose_n > 0 && !losers.is_empty(),
            gainers.len() as i64,
            losers.len() as i64,
            rows.iter().filter(|r| jf(r, "changePct") > 0.0).count() as i64,
            rows.iter().filter(|r| jf(r, "changePct") < 0.0).count() as i64,
        );
        let added: Vec<Value> = manual
            .iter()
            .filter_map(|sid| rows.iter().find(|r| ji(r, "securityId") == *sid).cloned())
            .collect();
        let payload = json!({
            "ok": true,
            "on": true,
            "at": now,
            "gainers": gainers,
            "losers": losers,
            "added": added,
            "bias": bias,
        });
        if let Ok(mut c) = self.liquid_cache.lock() {
            *c = (now, payload);
        }
        // Refresh the shared stock Leg Book from the freshly-ranked liquid rows
        // (the Top Movers pass feeds the same book from its own lists). Passing
        // empty mover lists keeps this correct even when the movers master is off
        // but the Liquid F&O master is on.
        let settings = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        self.refresh_leg_book(&settings);
        self.refresh_liquid_picked().await;
    }

    /// "Picked Strikes" rows for the Liquid F&O scanner: gainers -> CE,
    /// losers -> PE, manual adds -> both legs (the indicator gate picks the
    /// side). Reuses the same strike resolution as Top Movers so the readout
    /// and the executed contract can never disagree.
    async fn refresh_liquid_picked(&self) {
        let settings = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        let payload = self.liquid_cache.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
        let mut legs: Vec<Value> = Vec::new();
        let mut push_legs = |sid: i64, side: &str, change_pct: f64, legs: &mut Vec<Value>| {
            let Some((name, seg, inst)) = crate::market::equity_meta(sid) else { return };
            let spot = self.ltp_of(sid, &seg);
            for leg in self.pick_legs(&settings, sid, &name, &seg, &inst, spot, side) {
                let (opt_ltp, opt_change) = self
                    .leg_quote(&leg)
                    .map(|(l, c, _)| (l, c))
                    .unwrap_or((0.0, 0.0));
                legs.push(json!({
                    "securityId": leg.security_id,
                    "underlying": name,
                    "side": side,
                    "tradingSymbol": leg.trading_symbol,
                    "segment": leg.exchange_segment,
                    "instrument": leg.instrument,
                    "spot": round2(spot),
                    "changePct": change_pct,
                    "optionLtp": round2(opt_ltp),
                    "optionChange": round2(opt_change),
                    "source": "Liquid F&O",
                    "runMode": run_mode_for(&seg, &inst, &settings),
                    "underlyingSecurityId": sid,
                    "underlyingSegment": seg,
                    "underlyingInstrument": inst,
                }));
            }
        };
        for r in jarr(&payload, "gainers") {
            push_legs(ji(&r, "securityId"), "CE", jf(&r, "changePct"), &mut legs);
        }
        for r in jarr(&payload, "losers") {
            push_legs(ji(&r, "securityId"), "PE", jf(&r, "changePct"), &mut legs);
        }
        for r in jarr(&payload, "added") {
            let sid = ji(&r, "securityId");
            let chg = jf(&r, "changePct");
            push_legs(sid, "CE", chg, &mut legs);
            push_legs(sid, "PE", chg, &mut legs);
        }
        self.update_picked("Liquid F&O", legs);
    }

    async fn refresh_movers(&self) {
        let now = now_ms();
        if now - self.last_movers.load(Ordering::Relaxed) < 100 {
            return;
        }
        let (movers_on, gain_n, lose_n, indices) = self
            .doc()
            .map(|d| (d.settings.movers_on, d.settings.movers_gainers, d.settings.movers_losers, d.settings.movers_indices.clone()))
            .unwrap_or((false, 5, 5, Vec::new()));
        let (commodity_on, commodity_added) = self
            .doc()
            .map(|d| (d.settings.commodity_on, d.settings.commodity_list.clone()))
            .unwrap_or((false, Vec::new()));
        // Paper Trade 3 (commodities only) is armed by its own commodity master;
        // every other engine (RT / PT1 / PT2 / RT2 / RT3) is armed by the movers
        // master. RT2 / RT3 keep the combined behaviour: the movers master also
        // runs the commodity universe.
        let enabled = if self.commodities_only() { commodity_on } else { movers_on };
        if !enabled {
            self.mover_bias.store(0, Ordering::Relaxed);
            self.update_picked("Top Movers", Vec::new());
            return;
        }
        if !self.dhan.is_connected().await {
            return;
        }
        // Yield Dhan's single data slot while the operator is interacting; the
        // next engine tick retries (last_movers is deliberately left untouched).
        if self.dhan.user_active() {
            return;
        }
        self.last_movers.store(now, Ordering::Relaxed);

        // Paper Trade 2/3 and RT2/RT3 have no stock scanner: only the operator
        // indices and/or the operator's added commodity underlyings enter the
        // scan universe, never the equity set and never the whole MCX set. Paper
        // Trade 2 is indices only; Paper Trade 3 is commodities only.
        let indices_only = self.indices_commodities_only();
        let mut univ: Vec<(i64, String)> = if indices_only {
            let mut v: Vec<(i64, String)> = Vec::new();
            if self.allows_commodities() && commodity_on {
                for c in crate::market::commodity_rows() {
                    if c.has_options && commodity_added.contains(&c.security_id) {
                        v.push((c.security_id, "MCX_COMM".to_string()));
                    }
                }
            }
            v
        } else {
            self.scan_universe(false, commodity_on)
        };
        // Indices live under IDX_I (`IDX_I:<sid>` quote key), not NSE_EQ -
        // otherwise the feed cache lookup never matches and the user's
        // "Indices" picks are silently dropped from the movers scan. Paper
        // Trade 3 (commodities only) never adds them.
        if self.allows_indices() {
            univ.extend(index_legs(&indices));
        }
        univ.sort();
        univ.dedup();
        // Stream the whole scan universe on the live feed so the Top Movers /
        // Top Losers re-rank from the websocket cache (fast) instead of a REST
        // round-trip on every 100ms pass. The universe only needs an LTP for
        // ranking, so it rides on Ticker packets; the first pass still
        // REST-seeds. Option strikes resolved from it are promoted to Full
        // separately by the strike path.
        self.dhan.watch_scanner_now(&univ);
        let rows: Vec<Value> = self.quote_rows(&univ).await;
        // A stock that the Liquid F&O scanner owns (whole liquid basket while it
        // is armed, plus its manual adds and explicit gainer/loser picks) must
        // appear ONLY in the Liquid F&O list. Drop those ids from the Top Movers
        // ranking so the same common stock never shows in both readouts; the top
        // N is then taken from the remaining names, not from a shortened list.
        let settings_for_scope = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        let liquid_owned = self.liquid_owned_ids(&settings_for_scope);
        let rank_rows = exclude_liquid_owned(rows.clone(), &liquid_owned);
        let mut sorted = rank_rows.clone();
        sorted.sort_by(|a, b| jf(b, "changePct").partial_cmp(&jf(a, "changePct")).unwrap_or(std::cmp::Ordering::Equal));
        let gainers: Vec<Value> = sorted.into_iter().take(gain_n.max(0) as usize).collect();
        let mut sorted_l = rank_rows.clone();
        sorted_l.sort_by(|a, b| jf(a, "changePct").partial_cmp(&jf(b, "changePct")).unwrap_or(std::cmp::Ordering::Equal));
        let losers: Vec<Value> = sorted_l.into_iter().take(lose_n.max(0) as usize).collect();
        let up = rank_rows.iter().filter(|r| jf(r, "changePct") > 0.0).count() as i64;
        let down = rank_rows.iter().filter(|r| jf(r, "changePct") < 0.0).count() as i64;
        // Auto CE/PE side (old AST `autoRunInSide` parity): classify the ACTUAL
        // traded universe - the operator's selected top gainers / top losers -
        // not whole-market breadth. Gainers are bullish (CE), losers bearish
        // (PE), so switching "Top gainers" <-> "Top losers" (or setting one
        // count to 0) flips the auto side instead of it being pinned to the
        // market-wide up/down count. When both legs are selected the dominant
        // one wins; an exact tie falls back to market breadth.
        let want_g = gain_n > 0 && !gainers.is_empty();
        let want_l = lose_n > 0 && !losers.is_empty();
        let pos = gainers.iter().filter(|r| jf(r, "changePct") >= 0.0).count() as i64;
        let neg = losers.iter().filter(|r| jf(r, "changePct") < 0.0).count() as i64;
        let bias = movers_auto_bias(want_g, want_l, pos, neg, up, down);
        self.mover_bias.store(bias, Ordering::Relaxed);
        let payload = json!({ "ok": true, "at": now, "gainers": gainers, "losers": losers, "bias": bias, "up": up, "down": down });
        if let Ok(mut c) = self.movers_cache.lock() {
            *c = (now, payload);
        }
        // "Picked Strikes": each gainer resolves to its CE leg, each loser to PE.
        // Only the side the engine is actually trading is surfaced, so switching
        // gainers<->losers (or a trend/direction flip) replaces the previous
        // picks instead of leaving them beside the fresh ones. When no direction
        // is decided both legs are shown.
        let settings = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        // Maintain the Leg Book before the readout: each selected mover (and each
        // Liquid F&O pick) is pre-scanned ONCE (green + fastest rising) and the
        // Picked Strikes rows below then resolve straight from that frozen leg.
        self.refresh_leg_book(&settings);
        // Leg scoping removed: both gainer (CE) and loser (PE) rows always show.
        let active: Option<&str> = None;
        let mut legs: Vec<Value> = Vec::new();
        for (side, list) in [("CE", &gainers), ("PE", &losers)] {
            if active.is_some() && active != Some(side) {
                continue;
            }
            for r in list.iter() {
                let sid = ji(r, "securityId");
                let spot = jf(r, "last");
                let Some((name, seg, inst)) = crate::market::symbol_meta(sid) else { continue };
                // Commodities have their own "Commodities" picked source (so they
                // show even when Top Movers is off); don't double-list them here.
                if commodity_on && seg.eq_ignore_ascii_case("MCX_COMM") {
                    continue;
                }
                // "Pick fastest positive rising LTP": list the ranked +green
                // rising strikes (most-risen first) the book froze for this
                // underlying's bound side - one "Picked Strikes" row per saved
                // strike, up to the "Fastest-Rising Strikes" count. Strict: only
                // strikes whose live premium is genuinely +green are shown, and a
                // stock with no +green strike on its bound side is skipped whole.
                if settings.fastest_rising {
                    for leg in self.book_fastest_list_for(sid, side) {
                        let Some((l, c, p)) = self.leg_quote(&leg) else { continue };
                        if !Self::premium_is_green(l, p, c) {
                            continue;
                        }
                        legs.push(json!({
                            "securityId": leg.security_id,
                            "underlying": name,
                            "side": side,
                            "tradingSymbol": leg.trading_symbol,
                            "segment": leg.exchange_segment,
                            "instrument": leg.instrument,
                            "spot": round2(spot),
                            "changePct": jf(r, "changePct"),
                            "optionLtp": round2(l),
                            "optionChange": round2(c),
                            "source": "Top Movers",
                            "runMode": run_mode_for(&seg, &inst, &settings),
                            "underlyingSecurityId": sid,
                            "underlyingSegment": seg,
                            "underlyingInstrument": inst,
                        }));
                    }
                    continue;
                }
                for leg in self.pick_legs(&settings, sid, &name, &seg, &inst, spot, side) {
                    // The readout lists the COMPLETE selected strike ladder,
                    // including a currently red strike: the +green preference
                    // gates entry, not which strikes the operator selected.
                    // Live quote of the resolved strike (0 when not quoted yet).
                    let (opt_ltp, opt_change) = self
                        .leg_quote(&leg)
                        .map(|(l, c, _)| (l, c))
                        .unwrap_or((0.0, 0.0));
                    legs.push(json!({
                        "securityId": leg.security_id,
                        "underlying": name,
                        "side": side,
                        "tradingSymbol": leg.trading_symbol,
                        "segment": leg.exchange_segment,
                        "instrument": leg.instrument,
                        "spot": round2(spot),
                        "changePct": jf(r, "changePct"),
                        "optionLtp": round2(opt_ltp),
                        "optionChange": round2(opt_change),
                        "source": "Top Movers",
                        "runMode": run_mode_for(&seg, &inst, &settings),
                        "underlyingSecurityId": sid,
                        "underlyingSegment": seg,
                        "underlyingInstrument": inst,
                    }));
                }
            }
        }
        // Operator indices: each resolves to its explicitly assigned leg when
        // one is set; an index with no assignment follows the live global side
        // exactly like a commodity (both legs shown when no direction is
        // decided). The assigned leg is shown regardless of the live auto side.
        for id in &indices {
            let Some((name, seg, inst)) = crate::market::symbol_meta(*id) else { continue };
            let spot = self.ltp_of(*id, &seg);
            let chg = rows
                .iter()
                .find(|r| ji(r, "securityId") == *id)
                .map(|r| jf(r, "changePct"))
                .unwrap_or(0.0);
            let mut sides: Vec<&str> = Vec::new();
            sides.push("CE");
            sides.push("PE");
            for side in sides {
                for leg in self.pick_legs(&settings, *id, &name, &seg, &inst, spot, side) {
                    legs.push(json!({
                        "securityId": leg.security_id,
                        "underlying": name,
                        "side": side,
                        "tradingSymbol": leg.trading_symbol,
                        "segment": leg.exchange_segment,
                        "instrument": leg.instrument,
                        "spot": round2(spot),
                        "changePct": chg,
                        "source": "Top Movers",
                        "runMode": run_mode_for(&seg, &inst, &settings),
                        "underlyingSecurityId": *id,
                        "underlyingSegment": seg,
                        "underlyingInstrument": inst,
                    }));
                }
            }
        }
        self.update_picked("Top Movers", legs);
    }

    /// "Picked Strikes" rows for the MCX commodity scanner, mirroring the Top
    /// Movers / operator-index rows so commodities appear in the Running
    /// Strategies list while they wait for an entry instead of only after a fill.
    /// A commodity with an operator-assigned CE/PE leg trades only that leg; one
    /// with no assignment follows the live global scanner side (both legs shown
    /// when no direction is decided). Futures-only commodities are skipped -
    /// they can never resolve a CE/PE leg.
    async fn refresh_commodity_picked(&self) {
        let now = now_ms();
        if now - self.last_commodity.load(Ordering::Relaxed) < 250 {
            return;
        }
        let (enabled, settings) = self
            .doc()
            .map(|d| (d.settings.commodity_on, d.settings.clone()))
            .unwrap_or((false, Settings::default()));
        if !enabled || settings.commodity_list.is_empty() {
            // Nothing added (or the scanner is off): the readout must be empty.
            // Never fall back to every MCX commodity - merely switching the
            // scanner ON must not pick commodities the operator never added.
            self.update_picked("Commodities", Vec::new());
            return;
        }
        if !self.dhan.is_connected().await || self.dhan.user_active() {
            return;
        }
        self.last_commodity.store(now, Ordering::Relaxed);
        let rows: Vec<_> = crate::market::commodity_rows()
            .into_iter()
            .filter(|c| settings.commodity_list.contains(&c.security_id))
            .collect();
        if rows.is_empty() {
            self.update_picked("Commodities", Vec::new());
            return;
        }
        // Warm the commodity underlyings on the live feed so the ATM centring
        // spot has a quote. Underlyings only need an LTP, so they ride on
        // Ticker packets; the resolved option legs below are promoted to Full
        // by the strike path.
        let univ: Vec<(i64, String)> = rows
            .iter()
            .filter(|c| c.has_options)
            .map(|c| (c.security_id, "MCX_COMM".to_string()))
            .collect();
        self.dhan.watch_scanner_now(&univ);
        let mut legs: Vec<Value> = Vec::new();
        for c in rows {
            if !c.has_options {
                continue;
            }
            let Some((name, seg, inst)) = crate::market::symbol_meta(c.security_id) else { continue };
            let spot = self.ltp_of(c.security_id, &seg);
            let mut sides: Vec<&str> = Vec::new();
            sides.push("CE");
            sides.push("PE");
            for side in sides {
                for leg in self.pick_legs(&settings, c.security_id, &name, &seg, &inst, spot, side) {
                    legs.push(json!({
                        "securityId": leg.security_id,
                        "underlying": name,
                        "side": side,
                        "tradingSymbol": leg.trading_symbol,
                        "segment": leg.exchange_segment,
                        "instrument": leg.instrument,
                        "spot": round2(spot),
                        "changePct": 0.0,
                        "source": "Commodities",
                        "runMode": run_mode_for(&seg, &inst, &settings),
                        "underlyingSecurityId": c.security_id,
                        "underlyingSegment": seg,
                        "underlyingInstrument": inst,
                    }));
                }
            }
        }
        self.update_picked("Commodities", legs);
    }

    async fn movers_readout(&self) -> Value {
        let (at, payload) = self.movers_cache.lock().map(|g| (g.0, g.1.clone())).unwrap_or((0, Value::Null));
        if payload.is_object() {
            payload
        } else {
            json!({ "ok": true, "at": at, "gainers": [], "losers": [], "bias": self.mover_bias.load(Ordering::Relaxed) })
        }
    }

    /// Refresh the NIFTY range-regime flag used by "No trade on sideways
    /// trend". Throttled to 1s; reads the live (tick-advanced) series, never a
    /// REST call. When the switch is OFF the flag is forced false so it can never
    /// block anything. When ON and the series is unavailable the flag is forced
    /// TRUE (fail closed) - an unreadable regime must not allow a new trend
    /// entry.
    fn refresh_nifty_sideways(&self, s: &Settings, tf: &str) {
        if !s.no_trade_sideways {
            self.nifty_sideways.store(false, Ordering::Relaxed);
            if let Ok(mut g) = self.nifty_sideways_read.lock() {
                *g = json!({ "on": false, "sideways": false });
            }
            return;
        }
        let now = now_ms();
        if now - self.last_sideways_scan.load(Ordering::Relaxed) < 1_000 {
            return;
        }
        self.last_sideways_scan.store(now, Ordering::Relaxed);
        // `both` uses the higher (5 min) timeframe for the regime read: a 1 min
        // range inside a trending 5 min chart is a pullback, not a sideways
        // market. The 1 min is still checked by the pre-order strict read.
        let read_tf = if tf.eq_ignore_ascii_case("both") { "5min" } else { tf };
        let read = self
            .dhan
            .market
            .live_bars_for(NIFTY_SEC, "IDX_I", read_tf, Duration::from_secs(60))
            .map(|c| apply_engine_chart(c, s))
            .and_then(|c| sideways_read(&c));
        let (sideways, payload) = match read {
            Some(r) => (
                r.sideways,
                json!({
                    "on": true,
                    "sideways": r.sideways,
                    "adx": round2(r.adx),
                    "chop": round2(r.chop),
                    "slopeAtr": round2(r.slope_atr),
                    "rangeAtr": round2(r.range_atr),
                    "score": r.score,
                    "tf": read_tf,
                }),
            ),
            None => (
                true,
                json!({
                    "on": true,
                    "sideways": true,
                    "reason": "NIFTY regime bars unavailable",
                    "tf": read_tf,
                }),
            ),
        };
        self.nifty_sideways.store(sideways, Ordering::Relaxed);
        if let Ok(mut g) = self.nifty_sideways_read.lock() {
            *g = payload;
        }
    }

    /// NIFTY trend pass #1 - REST-backed direction refresh. Computes every
    /// selected straight-line indicator on the NIFTY candles at the same
    /// timeframe the operator ticked for the charts (`1 min` / `5 min`; both =
    /// the two must agree) and applies the resulting direction. Throttled to 1s
    /// because it may round-trip REST to seed the live series; the tick-native
    /// [`refresh_nifty_flip`] then tracks the forming bar between refreshes.
    async fn refresh_nifty_trend(&self) {
        let now = now_ms();
        if now - self.last_trend.load(Ordering::Relaxed) < 2_500 {
            return;
        }
        let (enabled, tf, conf, slope, color, nbsl) = self
            .doc()
            .map(|d| {
                let s = d.settings.clone();
                (nifty_dir_feature_on(&s), nifty_timeframe(&s), s.nifty_trend_conf_inds.clone(), s.nifty_trend_slope_len, s.nifty_trend_color, s)
            })
            .unwrap_or((false, "5min".into(), Vec::new(), 5, false, Settings::default()));
        self.last_trend.store(now, Ordering::Relaxed);
        if !enabled {
            self.clear_nifty_direction();
            return;
        }
        self.refresh_nifty_sideways(&nbsl, &tf);
        // The BB%b (Pane) section is a CONFIRMATION gate now, never a direction
        // source: the NIFTY Trend Following confirmation indicators below own the
        // side, and BB%b only confirms that the side matches its line / zone /
        // combo condition. Refresh its two live reads so `nifty_line_side_ok` can
        // gate the matching side:
        //   * line - newest BB%b segment rising (+1) / falling (-1);
        //   * zone - OB/OS regime oversold (+1) / overbought (-1).
        // Neither ever feeds `nifty_dir`.
        let bbpct_gate_on = nbsl.bbpct_pane_on
            && (nbsl.bbpct_combo_on || nbsl.bbpct_trend_on || nbsl.bbpct_zone_on);
        if bbpct_gate_on && self.dhan.is_connected().await {
            if nbsl.bbpct_combo_on || nbsl.bbpct_trend_on {
                let line = self
                    .resolve_bbpct_trend(&tf)
                    .await
                    .map(|x| x.2.signum())
                    .unwrap_or(0);
                self.nifty_bbpct_line_dir.store(line, Ordering::Relaxed);
            } else {
                self.nifty_bbpct_line_dir.store(0, Ordering::Relaxed);
            }
            if nbsl.bbpct_combo_on || nbsl.bbpct_zone_on {
                self.nifty_zone_dir
                    .store(self.effective_zone_dir(&tf).await, Ordering::Relaxed);
            } else {
                self.nifty_zone_dir.store(0, Ordering::Relaxed);
            }
        } else if !bbpct_gate_on {
            self.nifty_bbpct_line_dir.store(0, Ordering::Relaxed);
            self.nifty_zone_dir.store(0, Ordering::Relaxed);
        }
        // Colour mode re-reads the assigned indicators on the fixed colour scan
        // cadence, not on the 2.5s REST refresh.
        if color {
            if now - self.last_color_scan.load(Ordering::Relaxed) < COLOR_SCAN_MS {
                return;
            }
            self.last_color_scan.store(now, Ordering::Relaxed);
        }
        if !self.dhan.is_connected().await {
            return;
        }
        if let Some((bull, bear, net, votes)) =
            self.resolve_nifty_direction(&tf, &conf, slope, color, true, &nbsl).await
        {
            self.apply_nifty_direction_votes(bull, bear, net, &tf, &votes);
        }
    }

    /// NIFTY trend tick-native flip watchdog. Reads the live *forming* candle
    /// series (no REST) and re-applies the direction on every market tick, so a
    /// bullish<->bearish flip switches leg/strikes within milliseconds of the
    /// straight line turning - never on a candle close. Old trades are never
    /// closed by a switch.
    async fn refresh_nifty_flip(&self) {
        let now = now_ms();
        if now - self.last_nifty_flip.load(Ordering::Relaxed) < 20 {
            return;
        }
        self.last_nifty_flip.store(now, Ordering::Relaxed);
        let (enabled, tf, conf, slope, color, nbsl) = self
            .doc()
            .map(|d| {
                let s = d.settings.clone();
                (nifty_dir_feature_on(&s), nifty_timeframe(&s), s.nifty_trend_conf_inds.clone(), s.nifty_trend_slope_len, s.nifty_trend_color, s)
            })
            .unwrap_or((false, "5min".into(), Vec::new(), 5, false, Settings::default()));
        if !enabled {
            return;
        }
        self.refresh_nifty_sideways(&nbsl, &tf);
        // Colour mode: re-read the assigned indicators' colour every
        // COLOR_SCAN_MS instead of on every tick.
        if color {
            if now - self.last_color_scan.load(Ordering::Relaxed) < COLOR_SCAN_MS {
                return;
            }
            self.last_color_scan.store(now, Ordering::Relaxed);
        }
        if let Some((bull, bear, net, votes)) =
            self.resolve_nifty_direction(&tf, &conf, slope, color, false, &nbsl).await
        {
            self.apply_nifty_direction_votes(bull, bear, net, &tf, &votes);
        }
    }

    /// One-instrument trend read: `(dir, votes, sideways)` where dir is `+1`
    /// bullish, `-1` bearish, `0` no committed side (or not enough candles yet /
    /// sideways while the no-trade switch is ON). Uses the same straight-line
    /// classification as the NIFTY-trend engine, just applied to an arbitrary
    /// instrument's own candles.
    async fn instrument_trend_read(&self, sid: i64, seg: &str, inst: &str, tf: &str, conf: &[String], s: &Settings) -> (i64, Vec<(String, i8)>, bool) {
        let Ok(c) = self.live_candles(sid, seg, inst, tf).await else {
            return (0, Vec::new(), false);
        };
        if c.len() < 35 {
            return (0, Vec::new(), false);
        }
        let (_, _, net, votes) = nifty_indicator_read(&c, conf, 5, false, s);
        let sideways = s.no_trade_sideways
            && sideways_read(&c).map(|r| r.sideways).unwrap_or(false);
        (if sideways { 0 } else { net.signum() }, votes, sideways)
    }

    /// Instrument trend across the engine timeframe. `both` requires the 1 min
    /// and 5 min reads to agree, mirroring the NIFTY-trend engine. A sideways
    /// read on EITHER timeframe blocks the leg (the no-trade switch is strict).
    async fn instrument_trend(&self, sid: i64, seg: &str, inst: &str, tf: &str, conf: &[String], s: &Settings) -> (i64, Vec<(String, i8)>, bool) {
        if tf.eq_ignore_ascii_case("both") {
            let a = self.instrument_trend_read(sid, seg, inst, "1min", conf, s).await;
            let b = self.instrument_trend_read(sid, seg, inst, "5min", conf, s).await;
            if a.2 || b.2 {
                (0, Vec::new(), true)
            } else if a.0 != 0 && a.0 == b.0 {
                (a.0, a.1, false)
            } else {
                (0, Vec::new(), false)
            }
        } else {
            self.instrument_trend_read(sid, seg, inst, tf, conf, s).await
        }
    }

    /// Fresh single-series trend read for the pre-order gate: only a LIVE series
    /// younger than 3s or a successful REST refetch is accepted. Unlike
    /// `live_candles`, this never falls back to a stale (up to 900s) series - a
    /// dead feed must block the entry, not silently confirm the old side.
    async fn strict_trend_read_one(&self, sid: i64, seg: &str, inst: &str, tf: &str, conf: &[String], s: &Settings) -> Result<i64, String> {
        let raw = if let Some(c) = self.dhan.market.live_bars_for(sid, seg, tf, Duration::from_secs(3)) {
            c
        } else {
            self.dhan
                .fetch_candles(sid, seg, inst, tf)
                .await
                .map_err(|e| format!("fresh {tf} candles unavailable ({e})"))?
        };
        let c = apply_engine_chart(raw, s);
        if c.len() < 35 {
            return Err(format!("only {} {tf} candles - not enough to confirm trend", c.len()));
        }
        if s.no_trade_sideways {
            match sideways_read(&c) {
                Some(r) if r.sideways => return Err(format!("{} on {tf} - no trade", r.reason())),
                Some(_) => {}
                None => return Err(format!("{tf} regime unavailable - no trade")),
            }
        }
        let (_, _, net, _) = nifty_indicator_read(&c, conf, 5, false, s);
        Ok(net.signum())
    }

    /// Strict trend read across the engine timeframe. `both` requires the 1 min
    /// and 5 min reads to agree; a missing / neutral / disagreeing read is an
    /// error so the caller fails closed.
    async fn strict_instrument_trend(&self, sid: i64, seg: &str, inst: &str, tf: &str, conf: &[String], s: &Settings) -> Result<i64, String> {
        if conf.is_empty() {
            return Err("no confirmation indicators configured".into());
        }
        if tf.eq_ignore_ascii_case("both") {
            let a = self.strict_trend_read_one(sid, seg, inst, "1min", conf, s).await?;
            let b = self.strict_trend_read_one(sid, seg, inst, "5min", conf, s).await?;
            if a != 0 && a == b {
                Ok(a)
            } else {
                Err("1min/5min trend disagree or are neutral".into())
            }
        } else {
            self.strict_trend_read_one(sid, seg, inst, tf, conf, s).await
        }
    }

    /// Pre-order anti-fake gate. When "Ignore fake breakouts / reversals" is ON,
    /// read the underlying's live candles and block the entry if the newest move
    /// looks like a small fake breakout / reversal (`anti_fake_read`). A series
    /// that cannot be read is fail-OPEN here (the trend gates already fail
    /// closed), so this filter never turns a feed hiccup into a hard stop.
    async fn anti_fake_entry_ok(
        &self,
        sid: i64,
        seg: &str,
        inst: &str,
        tf: &str,
        bull: bool,
        s: &Settings,
    ) -> Result<(), String> {
        if !s.anti_fake_on {
            return Ok(());
        }
        let read_tf = if tf.eq_ignore_ascii_case("both") { "1min" } else { tf };
        let Ok(c) = self.live_candles(sid, seg, inst, read_tf).await else {
            return Ok(());
        };
        let v = anti_fake_read(&c, bull, s);
        if v.fake {
            return Err(format!(
                "fake move ignored ({}; ADX {:.1}, chop {:.1}, move {:.2} ATR) - entry blocked",
                v.reason, v.adx, v.chop, v.move_atr
            ));
        }
        Ok(())
    }

    /// Final pre-order trend confirmation. The scan arms a side from a cached
    /// trend read; by the time the paper delay / LTP warm-up elapses the trend
    /// can have flipped. Re-read the LIVE trend immediately before the order and
    /// fail closed unless it still matches the side being executed:
    ///   * NIFTY-trend engines: committed NIFTY side must match, no flip may be
    ///     pending, the current read must not be tied, and the BB%b confirmation
    ///     must still hold.
    ///   * Per-instrument trend engines: that instrument's own fresh 1min/5min
    ///     read must still point at the same leg.
    /// Returns an audit snapshot for the position when a gate actually ran.
    /// Strict "double confirmation" against the cached Target Lab research.
    ///
    /// Returns `Ok(None)` when the feature is off, the entry is manual, the side
    /// is not BUY, the underlying is outside the Target Lab universe (the cache
    /// only covers the indices and MCX commodities it refreshes), or no fresh
    /// plan exists. Strict mode takes the LEG from a fresh plan regardless of
    /// confidence (the operator explicitly asked Target Lab to choose the leg);
    /// confidence still controls auto-cut/exit. A contradictory/failed plan is a
    /// hard skip: opposite direction, no target room left, an event blackout, or
    /// a failed feasibility read.
    fn target_research_gate(
        &self,
        settings: &Settings,
        strat: &Strategy,
        side: &str,
        underlying: &str,
    ) -> Result<Option<Value>, String> {
        if !settings.target_confirm_on || strat.manual || !side.eq_ignore_ascii_case("BUY") {
            return Ok(None);
        }
        if !crate::target::covers_underlying(underlying) {
            return Ok(None);
        }
        let exposure = option_exposure_dir(side, &strat.trading_symbol);
        // A cold / missing plan means Target Lab is not currently connected for
        // this underlying. Keep normal scanner behaviour instead of blocking the
        // paper engines; only a fresh plan may override or veto the side.
        let Some(plan) = crate::target::plan_for_underlying(underlying) else {
            return Ok(None);
        };
        let tsid = plan.get("securityId").and_then(|v| v.as_i64()).unwrap_or(0);
        let tseg = plan.get("exchangeSegment").and_then(|v| v.as_str()).unwrap_or("");
        let spot = if tsid > 0 { self.ltp_of(tsid, tseg) } else { 0.0 };
        // Confidence must not veto the entry: in strict mode the operator asked
        // Target Lab to choose the leg, and live plans routinely score below the
        // auto-cut floor. The minimum still gates auto-cut/exit, not entry side.
        target_research_verdict(&plan, exposure, 0.0, spot)?;
        let conf = plan.get("confidence").and_then(|v| v.as_f64()).unwrap_or(0.0);
        Ok(Some(json!({
            "source": "target-lab",
            "side": exposure,
            "confidence": round2(conf),
            "target": plan.get("target").cloned().unwrap_or(Value::Null),
            "stop": plan.get("stop").cloned().unwrap_or(Value::Null),
            "regime": plan.pointer("/research/regime/label").cloned().unwrap_or(Value::Null),
            "checkedAt": now_ms(),
        })))
    }

    async fn trend_entry_confirmation(&self, strat: &Strategy, s: &Settings) -> Result<Option<Value>, String> {
        if !strat.synthetic || strat.manual || s.manual_strikes_enabled {
            return Ok(None);
        }
        let want = match strat.category.to_ascii_uppercase().as_str() {
            "BULLISH" => 1i64,
            "BEARISH" => -1i64,
            _ => return Ok(None),
        };
        // Strict Target Lab mode owns the leg while its plan is actionable and
        // points at this strategy's side: the scan already pinned the strategy,
        // so the separate per-instrument / NIFTY trend read must not veto it with
        // the opposite side. A missing plan leaves the normal trend confirmation
        // in place; confidence never weakens a fresh plan's leg.
        let underlying = underlying_of(&strat.trading_symbol, &strat.exchange_segment);
        if target_plan_side_for(s, &underlying) == Some(strategy_is_bull(strat)) {
            return Ok(None);
        }
        // A delayed paper fill can land after the feed has gone silent; the
        // committed NIFTY side is tick-native, so without live ticks there is
        // nothing valid to confirm against.
        if !self.dhan.feed_live() {
            return Err("live feed not streaming - trend cannot be confirmed".into());
        }
        let tf = nifty_timeframe(s);
        let checked_at = now_ms();
        if self.indices_commodities_only() {
            // The scan hands `open_entry` the RESOLVED option contract, so the
            // trend must be read on its UNDERLYING (index / near-month future),
            // exactly as `refresh_index_comm_trends` does - never on the option's
            // own premium chart. If a trend is armed but the underlying cannot be
            // resolved there is nothing safe to confirm, so fail closed.
            let trend_armed = (self.allows_indices() && s.index_trend_on)
                || (self.allows_commodities() && s.comm_trend_on);
            let under = match underlying_strategy(strat) {
                Some(u) => u,
                None if trend_armed && is_option_leg(strat) => {
                    return Err("underlying not resolved - trend cannot be confirmed".into());
                }
                None => return Ok(None),
            };
            let mut gated: Option<Value> = None;
            if self.allows_indices() && s.index_trend_on && s.movers_indices.contains(&under.security_id) {
                let dir = self
                    .strict_instrument_trend(under.security_id, &under.exchange_segment, &under.instrument, &tf, &s.index_trend_conf_inds, s)
                    .await?;
                if dir != want {
                    return Err(format!(
                        "{} trend now {} vs entry {} - old-side entry blocked",
                        under.trading_symbol,
                        nifty_dir_label(dir),
                        nifty_dir_label(want)
                    ));
                }
                self.anti_fake_entry_ok(under.security_id, &under.exchange_segment, &under.instrument, &tf, want > 0, s).await?;
                gated = Some(json!({ "source": "index", "side": want, "dir": dir, "underlying": under.trading_symbol, "checkedAt": checked_at }));
            }
            if self.allows_commodities() && s.comm_trend_on && s.commodity_list.contains(&under.security_id) {
                let dir = self
                    .strict_instrument_trend(under.security_id, &under.exchange_segment, &under.instrument, &tf, &s.comm_trend_conf_inds, s)
                    .await?;
                if dir != want {
                    return Err(format!(
                        "{} trend now {} vs entry {} - old-side entry blocked",
                        under.trading_symbol,
                        nifty_dir_label(dir),
                        nifty_dir_label(want)
                    ));
                }
                self.anti_fake_entry_ok(under.security_id, &under.exchange_segment, &under.instrument, &tf, want > 0, s).await?;
                gated = Some(json!({ "source": "commodity", "side": want, "dir": dir, "underlying": under.trading_symbol, "checkedAt": checked_at }));
            }
            return Ok(gated);
        }
        // NIFTY trend owns the side of every F&O-stock leg it armed.
        if nifty_dir_feature_on(s) && strat_category(strat) == StratCat::Fno {
            let dir = self.nifty_dir.load(Ordering::Relaxed);
            let pending = self.nifty_pending_dir.load(Ordering::Relaxed);
            let tied = self.nifty_zero_since.load(Ordering::Relaxed) != 0;
            let line_ok = self.nifty_line_side_ok(s, want > 0);
            let sideways = s.no_trade_sideways && self.nifty_sideways.load(Ordering::Relaxed);
            nifty_trend_entry_gate(want, dir, pending, tied, line_ok, sideways)?;
            // Anti-fake gate on the traded underlying's own candles: a stock leg
            // riding a small fake breakout / reversal is blocked even though the
            // NIFTY side itself still reads valid.
            if let Some(u) = underlying_strategy(strat) {
                self.anti_fake_entry_ok(u.security_id, &u.exchange_segment, &u.instrument, &tf, want > 0, s).await?;
            }
            return Ok(Some(json!({
                "source": "nifty",
                "side": want,
                "dir": dir,
                "pending": pending,
                "sideways": sideways,
                "checkedAt": checked_at,
            })));
        }
        Ok(None)
    }

    /// Paper Trade 2 per-instrument trend following. Unlike the NIFTY-trend
    /// engine (which analyses NIFTY once, then picks stocks), this analyses EACH
    /// added index / commodity on its OWN chart with the operator's confirmation
    /// indicators: a bullish line read arms that instrument's CE call leg, a
    /// bearish read its PE put leg. The resolved `[{securityId, side}]` lists are
    /// published for `scanner_targets`, which pins that instrument's leg strictly:
    /// `CE` builds the call leg only and `PE` builds the put leg only, so the
    /// trend can never trade the opposite side. Only runs on the Paper Trade 2
    /// engine.
    async fn refresh_index_comm_trends(&self) {
        if !self.indices_commodities_only() {
            return;
        }
        let now = now_ms();
        if now - self.last_inst_trend.load(Ordering::Relaxed) < 2_500 {
            return;
        }
        self.last_inst_trend.store(now, Ordering::Relaxed);
        let s = match self.doc() {
            Some(d) => d.settings.clone(),
            None => return,
        };
        if !s.index_trend_on && !s.comm_trend_on {
            return;
        }
        let tf = nifty_timeframe(&s);
        let mut index_rows: Vec<Value> = Vec::new();
        let mut index_status: Vec<Value> = Vec::new();
        if self.allows_indices() && s.index_trend_on && !s.index_trend_conf_inds.is_empty() {
            if let Ok(mut g) = self.index_trend_last.lock() {
                g.retain(|id, _| s.movers_indices.contains(id));
            }
            for id in s.movers_indices.clone() {
                let Some((name, seg, inst)) = crate::market::symbol_meta(id) else { continue };
                let prev = self.index_trend_last.lock().ok().and_then(|g| g.get(&id).cloned());
                let (dir, votes, sideways) = self.instrument_trend(id, &seg, &inst, &tf, &s.index_trend_conf_inds, &s).await;
                let (mut row, next) = inst_trend_status_row_votes(
                    id, &name, dir, prev.as_ref(), now, &s.index_trend_conf_inds, &votes,
                );
                if sideways {
                    row["sideways"] = json!(true);
                    row["trend"] = json!("SIDEWAYS");
                }
                if let Some(v) = next {
                    if let Ok(mut g) = self.index_trend_last.lock() {
                        g.insert(id, v);
                    }
                }
                index_status.push(row);
                if dir != 0 {
                    index_rows.push(json!({ "securityId": id, "side": if dir > 0 { "CE" } else { "PE" } }));
                }
            }
        }
        if let Ok(mut g) = self.index_trend_picks.lock() {
            *g = (now, json!(index_rows));
        }
        if let Ok(mut g) = self.index_trend_status.lock() {
            *g = json!(index_status);
        }
        let mut comm_rows: Vec<Value> = Vec::new();
        let mut comm_status: Vec<Value> = Vec::new();
        if self.allows_commodities() && s.comm_trend_on && !s.comm_trend_conf_inds.is_empty() {
            if let Ok(mut g) = self.comm_trend_last.lock() {
                g.retain(|id, _| s.commodity_list.contains(id));
            }
            for id in s.commodity_list.clone() {
                let Some((name, seg, inst)) = crate::market::symbol_meta(id) else { continue };
                let prev = self.comm_trend_last.lock().ok().and_then(|g| g.get(&id).cloned());
                let (dir, votes, sideways) = self.instrument_trend(id, &seg, &inst, &tf, &s.comm_trend_conf_inds, &s).await;
                let (mut row, next) = inst_trend_status_row_votes(
                    id, &name, dir, prev.as_ref(), now, &s.comm_trend_conf_inds, &votes,
                );
                if sideways {
                    row["sideways"] = json!(true);
                    row["trend"] = json!("SIDEWAYS");
                }
                if let Some(v) = next {
                    if let Ok(mut g) = self.comm_trend_last.lock() {
                        g.insert(id, v);
                    }
                }
                comm_status.push(row);
                if dir != 0 {
                    comm_rows.push(json!({ "securityId": id, "side": if dir > 0 { "CE" } else { "PE" } }));
                }
            }
        }
        if let Ok(mut g) = self.comm_trend_picks.lock() {
            *g = (now, json!(comm_rows));
        }
        if let Ok(mut g) = self.comm_trend_status.lock() {
            *g = json!(comm_status);
        }
    }

    /// Resolve the net NIFTY direction for the requested timeframe. `allow_rest`
    /// lets a stale/absent live series trigger a REST seed; the tick watchdog
    /// passes `false` so it can never flood REST between refreshes. `both` needs
    /// the 1 min and 5 min to agree, otherwise the previous direction is kept.
    async fn resolve_nifty_direction(
        &self,
        tf: &str,
        conf: &[String],
        slope_len: i64,
        color: bool,
        allow_rest: bool,
        s: &Settings,
    ) -> Option<(Vec<String>, Vec<String>, i64, Vec<(String, i8)>)> {
        if tf.eq_ignore_ascii_case("both") {
            let a = self.nifty_assignment_for("1min", conf, slope_len, color, allow_rest, s).await;
            let b = self.nifty_assignment_for("5min", conf, slope_len, color, allow_rest, s).await;
            combine_both_reads_votes(a, b)
        } else {
            self.nifty_assignment_for(tf, conf, slope_len, color, allow_rest, s).await
        }
    }

    /// The live zone regime read used by the BB%b (Pane) confirmation gate.
    /// `both` requires the 1 min and 5 min zones to agree; a disagreeing pair is
    /// treated as no committed regime (0). This is a pure gate read - it never
    /// sets the NIFTY direction.
    async fn effective_zone_dir(&self, tf: &str) -> i64 {
        let one = |r: Option<(Vec<String>, Vec<String>, i64)>| r.map(|x| x.2.signum()).unwrap_or(0);
        if tf.eq_ignore_ascii_case("both") {
            let a = one(self.resolve_bbpct_zone("1min").await);
            let b = one(self.resolve_bbpct_zone("5min").await);
            if a == b {
                a
            } else {
                0
            }
        } else {
            one(self.resolve_bbpct_zone(tf).await)
        }
    }

    /// Assignment for one timeframe: `(bull_ids, bear_ids, net, votes)` or
    /// `None` while the NIFTY candles are not warm enough for the straight-line
    /// engine.
    async fn nifty_assignment_for(
        &self,
        tf: &str,
        conf: &[String],
        slope_len: i64,
        color: bool,
        allow_rest: bool,
        s: &Settings,
    ) -> Option<(Vec<String>, Vec<String>, i64, Vec<(String, i8)>)> {
        let c = if allow_rest {
            self.live_candles(NIFTY_SEC, "IDX_I", "INDEX", tf).await.ok()?
        } else {
            // Tick path: serve the live forming series only, accepting it up to
            // 15 min old so a quiet feed never triggers a REST storm. The same
            // chart-type switch as `live_candles` applies, so the fast path can
            // never disagree with the REST path (or the chart) about the series.
            let raw = self
                .dhan
                .market
                .live_bars_for(NIFTY_SEC, "IDX_I", tf, Duration::from_secs(900))?;
            apply_engine_chart(raw, s)
        };
        if c.len() < 35 {
            return None;
        }
        Some(nifty_indicator_read(&c, conf, slope_len, color, s))
    }

    /// Live BB%b OB/OS zone regime on NIFTY spot, read purely as a confirmation
    /// gate for the side NIFTY Trend Following has already chosen.
    ///
    /// Scans the `bbpct` series (computed with the chart defaults, exactly like
    /// the pane indicator) for the most recent zone crossing:
    ///   * crossing above `bbpct_overbought` -> overbought (-1, PE location)
    ///   * crossing below `bbpct_oversold`   -> oversold (+1, CE location)
    /// The later of the two crossings wins, so the regime persists until the
    /// opposite zone is crossed. A zone whose enable switch is OFF is ignored
    /// entirely. Returns `None` while no enabled crossing exists (or the series is
    /// not warm). The result is consumed only as a gate signal; it never commits a
    /// direction.
    async fn resolve_bbpct_zone(&self, tf: &str) -> Option<(Vec<String>, Vec<String>, i64)> {
        let s = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        let c = self.live_candles(NIFTY_SEC, "IDX_I", "INDEX", tf).await.ok()?;
        if c.len() < 35 {
            return None;
        }
        let series = nifty_conf_series("bbpct", &c, &s);
        let data = series.first()?.data.as_slice();
        let ob = s.bbpct_overbought;
        let os = s.bbpct_oversold;
        let ob_on = s.bbpct_ob_on;
        let os_on = s.bbpct_os_on;
        let mut last_above: Option<usize> = None;
        let mut last_below: Option<usize> = None;
        for i in 1..data.len() {
            let prev = data[i - 1].value;
            let cur = data[i].value;
            if ob_on && prev <= ob && cur > ob {
                last_above = Some(i);
            }
            if os_on && prev >= os && cur < os {
                last_below = Some(i);
            }
        }
        let dir = match (last_above, last_below) {
            (Some(a), Some(b)) if a > b => -1,
            (Some(_), Some(_)) => 1,
            (Some(_), None) => -1,
            (None, Some(_)) => 1,
            (None, None) => 0,
        };
        if dir == 0 {
            return None;
        }
        let id = "bbpct_zone".to_string();
        if dir > 0 {
            Some((vec![id], Vec::new(), 1))
        } else {
            Some((Vec::new(), vec![id], -1))
        }
    }

    /// Live BB%b line-trend regime on NIFTY spot, read purely as a confirmation
    /// gate for the side NIFTY Trend Following has already chosen.
    ///
    /// Reads the last two points of the `bbpct` series (the newest segment = the
    /// colour the pane is currently drawing): rising -> +1 (line bullish, CE
    /// location), falling -> -1 (line bearish, PE location). A flat segment returns
    /// `None`. The result is consumed only as a gate signal; it never commits a
    /// direction.
    async fn resolve_bbpct_trend(&self, tf: &str) -> Option<(Vec<String>, Vec<String>, i64)> {
        let s = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        let c = self.live_candles(NIFTY_SEC, "IDX_I", "INDEX", tf).await.ok()?;
        if c.len() < 35 {
            return None;
        }
        let series = nifty_conf_series("bbpct", &c, &s);
        let data = series.first()?.data.as_slice();
        if data.len() < 2 {
            return None;
        }
        let prev = data[data.len() - 2].value;
        let cur = data[data.len() - 1].value;
        let dir = if cur > prev {
            1
        } else if cur < prev {
            -1
        } else {
            0
        };
        if dir == 0 {
            return None;
        }
        let id = "bbpct_trend".to_string();
        if dir > 0 {
            Some((vec![id], Vec::new(), 1))
        } else {
            Some((Vec::new(), vec![id], -1))
        }
    }

    /// Publish a resolved direction: store the per-leg filter split, swap the
    /// sign, and on a change re-arm the strike scan + emit the flip signal/log.
    fn apply_nifty_direction(&self, bull: Vec<String>, bear: Vec<String>, net: i64, tf: &str) {
        self.apply_nifty_direction_votes(bull, bear, net, tf, &[]);
    }

    /// [`apply_nifty_direction`] plus the per-indicator votes of the read, kept
    /// only for the UI readout (`niftyTrend.votes` / per-instrument `votes`).
    fn apply_nifty_direction_votes(
        &self,
        bull: Vec<String>,
        bear: Vec<String>,
        net: i64,
        tf: &str,
        votes: &[(String, i8)],
    ) {
        let d = net.signum();
        let cur = self.nifty_dir.load(Ordering::Relaxed);
        let agree = if !bull.is_empty() && bear.is_empty() {
            1
        } else if bull.is_empty() && !bear.is_empty() {
            -1
        } else {
            0
        };
        if !votes.is_empty() {
            let rows: Vec<Value> = votes
                .iter()
                .map(|(id, side)| json!({ "id": id, "side": side }))
                .collect();
            if let Ok(mut g) = self.nifty_votes.lock() {
                *g = json!(rows);
            }
        }
        if d == cur {
            // The live read agrees with the committed side. Refresh the strict-gate
            // state and the filter split from this read, and drop any in-flight
            // candidate - confirmation must be continuous, not cumulative.
            self.nifty_pending_dir.store(0, Ordering::Relaxed);
            self.nifty_zero_since.store(0, Ordering::Relaxed);
            self.nifty_raw_net.store(d, Ordering::Relaxed);
            self.nifty_agree.store(agree, Ordering::Relaxed);
            if d != 0 {
                if let Ok(mut b) = self.nifty_bull_filters.lock() {
                    *b = bull;
                }
                if let Ok(mut b) = self.nifty_bear_filters.lock() {
                    *b = bear;
                }
            }
            return;
        }
        if d == 0 {
            // A dead-heat carries no committed direction. A momentary tie holds
            // the previous side (never free BOTH legs), and an in-flight flip
            // candidate is kept: a single flat read must not abort a real flip
            // that is still resolving. A tie only stops the confirmation clock
            // (see below). A tie that PERSISTS for NIFTY_TIE_CLEAR_MS means the
            // indicators no longer resolve anything, so the side is dropped and
            // the next resolved read re-arms from neutral - otherwise a stale
            // side would be held forever and a later flip never detected.
            let now = now_ms();
            let z = self.nifty_zero_since.load(Ordering::Relaxed);
            if z == 0 {
                self.nifty_zero_since.store(now, Ordering::Relaxed);
                return;
            }
            if cur == 0 || now.saturating_sub(z) < NIFTY_TIE_CLEAR_MS {
                return;
            }
            self.nifty_dir.store(0, Ordering::Relaxed);
            self.nifty_raw_net.store(0, Ordering::Relaxed);
            self.nifty_agree.store(0, Ordering::Relaxed);
            self.nifty_pending_dir.store(0, Ordering::Relaxed);
            self.nifty_zero_since.store(0, Ordering::Relaxed);
            if let Ok(mut b) = self.nifty_bull_filters.lock() {
                b.clear();
            }
            if let Ok(mut b) = self.nifty_bear_filters.lock() {
                b.clear();
            }
            self.last_nifty_scan.store(0, Ordering::Relaxed);
            self.log(
                "info",
                &format!(
                    "NIFTY trend cleared after a {}s tie on {} - confirmation indicators resolved no side, re-arming from NEUTRAL",
                    NIFTY_TIE_CLEAR_MS / 1000,
                    tf
                ),
            );
            return;
        }
        // The read disagrees with the committed side. The lines are read off the
        // live forming bar on every tick, so a single wiggle can net the opposite
        // sign for a few milliseconds; require the new direction to PERSIST before
        // it replaces the side, otherwise the leg/strikes flip CE<->PE too fast
        // for any entry to survive. From NEUTRAL (no side committed yet) commit at
        // once so startup is not delayed.
        let now = now_ms();
        // Time spent tied/flat does not count towards the confirmation window: a
        // flip that is interrupted by a flat read still needs its full run of
        // resolved opposition, but the interruption no longer throws it away.
        let zero_ms = self.nifty_zero_since.swap(0, Ordering::Relaxed);
        let cand = self.nifty_pending_dir.load(Ordering::Relaxed);
        if cand != d {
            self.nifty_pending_dir.store(d, Ordering::Relaxed);
            self.nifty_pending_since.store(now, Ordering::Relaxed);
            if cur != 0 {
                return;
            }
        } else {
            let mut since = self.nifty_pending_since.load(Ordering::Relaxed);
            if zero_ms != 0 {
                since += now.saturating_sub(zero_ms);
                self.nifty_pending_since.store(since, Ordering::Relaxed);
            }
            if now.saturating_sub(since) < NIFTY_FLIP_CONFIRM_MS {
                return;
            }
        }
        self.nifty_pending_dir.store(0, Ordering::Relaxed);
        if let Ok(mut b) = self.nifty_bull_filters.lock() {
            *b = bull;
        }
        if let Ok(mut b) = self.nifty_bear_filters.lock() {
            *b = bear;
        }
        self.nifty_raw_net.store(d, Ordering::Relaxed);
        self.nifty_agree.store(agree, Ordering::Relaxed);
        let prev = self.nifty_dir.swap(d, Ordering::Relaxed);
        if prev == d {
            return;
        }
        // Re-resolve the picked strikes on the new side immediately; the old
        // trades keep running (a switch never closes them).
        self.last_nifty_scan.store(0, Ordering::Relaxed);
        let seq = self.nifty_seq.fetch_add(1, Ordering::Relaxed) + 1;
        let from = prev.signum();
        if let Ok(mut f) = self.nifty_flip.lock() {
            *f = json!({ "from": from, "to": d, "at": now, "seq": seq, "tf": tf });
        }
        self.log(
            "info",
            &format!(
                "NIFTY trend change {} -> {} on {} (straight-line confirm) - switching leg/strikes, old trades kept running",
                nifty_dir_label(from),
                nifty_dir_label(d),
                tf
            ),
        );
    }

    fn clear_nifty_direction(&self) {
        self.nifty_dir.store(0, Ordering::Relaxed);
        self.nifty_raw_net.store(0, Ordering::Relaxed);
        self.nifty_agree.store(0, Ordering::Relaxed);
        self.nifty_zone_dir.store(0, Ordering::Relaxed);
        self.nifty_bbpct_line_dir.store(0, Ordering::Relaxed);
        self.nifty_pending_dir.store(0, Ordering::Relaxed);
        self.nifty_zero_since.store(0, Ordering::Relaxed);
        if let Ok(mut g) = self.nifty_votes.lock() {
            *g = Value::Null;
        }
        // Force the next colour scan to run immediately when the trend (or its
        // colour mode) is switched back on.
        self.last_color_scan.store(0, Ordering::Relaxed);
        if let Ok(mut b) = self.nifty_bull_filters.lock() {
            b.clear();
        }
        if let Ok(mut b) = self.nifty_bear_filters.lock() {
            b.clear();
        }
    }

    /// NIFTY trend pass #2 - pick + assignment. Top Gainers are gated by the
    /// bullish straight-line filters and resolve to CE legs; Top Losers are
    /// gated by the bearish filters and resolve to PE legs. Both legs come from
    /// the Top Movers scanner lists - NIFTY trend never ranks its own universe,
    /// so with Top Movers off there is nothing to trade. When only one side is
    /// selected only that side trades; when both are selected both filter lists
    /// run, each strictly on its own side.
    async fn refresh_nifty_scan(&self) {
        let now = now_ms();
        if now - self.last_nifty_scan.load(Ordering::Relaxed) < 100 {
            return;
        }
        let (enabled, movers_on, settings) = self
            .doc()
            .map(|d| (nifty_dir_feature_on(&d.settings), d.settings.movers_on, d.settings.clone()))
            .unwrap_or((false, false, Settings::default()));
        if !enabled || !movers_on {
            self.update_picked("NIFTY trend", Vec::new());
            if let Ok(mut g) = self.nifty_picks.lock() {
                *g = (now, Value::Null);
            }
            return;
        }
        if !self.dhan.is_connected().await {
            return;
        }
        // Yield Dhan's single data slot while the operator is interacting; the
        // next engine tick retries (last_nifty_scan is deliberately untouched).
        if self.dhan.user_active() {
            return;
        }
        self.last_nifty_scan.store(now, Ordering::Relaxed);
        // Follow only the net straight-line direction: a bullish NIFTY builds CE
        // legs, a bearish NIFTY PE legs. The opposite side is never armed, even
        // when a single line reads against the majority.
        let dir = self.nifty_dir.load(Ordering::Relaxed);
        let bull_on = dir > 0 && self.nifty_bull_filters.lock().map(|g| !g.is_empty()).unwrap_or(false);
        let bear_on = dir < 0 && self.nifty_bear_filters.lock().map(|g| !g.is_empty()).unwrap_or(false);
        // Strict gate(s): a side that does not match the live assigned-line read
        // (net / all-agree) is dropped here too, so the Picked-Strikes readout
        // never lists a leg the engine would refuse to trade.
        let bull_on = bull_on && self.nifty_line_side_ok(&settings, true);
        let bear_on = bear_on && self.nifty_line_side_ok(&settings, false);
        // No committed direction (or no line assigned yet): nothing to assign.
        if !bull_on && !bear_on {
            self.update_picked("NIFTY trend", Vec::new());
            return;
        }
        // The tradeable universe is exactly the Top Movers scanner lists -
        // NIFTY trend follows the operator's selected Top Gainers / Top Losers.
        let payload = self.movers_cache.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
        let gainers: Vec<Value> = jarr(&payload, "gainers");
        let losers: Vec<Value> = jarr(&payload, "losers");
        let mut legs: Vec<Value> = Vec::new();
        for (side, list, active) in [("CE", &gainers, bull_on), ("PE", &losers, bear_on)] {
            if !active {
                continue;
            }
            for r in list.iter() {
                let sid = ji(r, "securityId");
                let spot = jf(r, "last");
                let Some((name, seg, inst)) = crate::market::symbol_meta(sid) else { continue };
                // NIFTY Trend Following applies to F&O stocks only: an index or
                // commodity underlying in the Top Movers lists is never picked.
                if category_for(&seg, &inst) != StratCat::Fno {
                    continue;
                }
                // "Pick fastest positive rising LTP": mirror the Top-Movers
                // readout exactly - the ranked +green rising strikes the book
                // froze for this underlying's bound side (Top Gainer -> CE, Top
                // Loser -> PE), most-risen first, up to the "Fastest-Rising
                // Strikes" count. Only currently +green strikes are shown.
                if settings.fastest_rising {
                    for leg in self.book_fastest_list_for(sid, side) {
                        let Some((l, c, p)) = self.leg_quote(&leg) else { continue };
                        if !Self::premium_is_green(l, p, c) {
                            continue;
                        }
                        legs.push(json!({
                            "securityId": leg.security_id,
                            "underlying": name,
                            "side": side,
                            "tradingSymbol": leg.trading_symbol,
                            "segment": leg.exchange_segment,
                            "instrument": leg.instrument,
                            "spot": round2(spot),
                            "changePct": jf(r, "changePct"),
                            "optionLtp": round2(l),
                            "optionChange": round2(c),
                            "source": "NIFTY trend",
                            "runMode": run_mode_for(&seg, &inst, &settings),
                            "underlyingSecurityId": sid,
                            "underlyingSegment": seg,
                            "underlyingInstrument": inst,
                        }));
                    }
                    continue;
                }
                for leg in self.pick_legs(&settings, sid, &name, &seg, &inst, spot, side) {
                    // Complete selected ladder; +green gates entry only.
                    legs.push(json!({
                        "securityId": leg.security_id,
                        "underlying": name,
                        "side": side,
                        "tradingSymbol": leg.trading_symbol,
                        "segment": leg.exchange_segment,
                        "instrument": leg.instrument,
                        "spot": round2(spot),
                        "changePct": jf(r, "changePct"),
                        "source": "NIFTY trend",
                        "runMode": run_mode_for(&seg, &inst, &settings),
                        "underlyingSecurityId": sid,
                        "underlyingSegment": seg,
                        "underlyingInstrument": inst,
                    }));
                }
            }
        }
        self.update_picked("NIFTY trend", legs.clone());
        let payload = json!({
            "ok": true, "at": now, "dir": self.nifty_dir.load(Ordering::Relaxed),
            "bullFilters": self.nifty_bull_filters.lock().map(|g| g.clone()).unwrap_or_default(),
            "bearFilters": self.nifty_bear_filters.lock().map(|g| g.clone()).unwrap_or_default(),
            "gainers": gainers, "losers": losers, "picks": legs,
        });
        if let Ok(mut g) = self.nifty_picks.lock() {
            *g = (now, payload);
        }
    }

    async fn nifty_readout(&self) -> Value {
        let (at, payload) = self.nifty_picks.lock().map(|g| (g.0, g.1.clone())).unwrap_or((0, Value::Null));
        if payload.is_object() {
            payload
        } else {
            json!({ "ok": true, "at": at, "dir": self.nifty_dir.load(Ordering::Relaxed), "picks": [] })
        }
    }

    /// Resolve the direction-specific AST template (if assigned) and return its
    /// saved settings, which override the manual gate/filter set for this entry.
    fn template_for_direction(&self, settings: &Settings, _strat: &Strategy) -> Option<Settings> {
        let mut name = String::new();
        if settings.movers_on && !settings.manual_strikes_enabled {
            let b = self.mover_bias.load(Ordering::Relaxed);
            if b > 0 {
                name = settings.mover_bull_template.clone();
            } else if b < 0 {
                name = settings.mover_bear_template.clone();
            }
        }
        if name.is_empty() {
            return None;
        }
        let v = self.template_pool.lock().ok()?.get(&name).cloned()?;
        serde_json::from_value::<Settings>(v.get("settings")?.clone()).ok()
    }

    // -----------------------------------------------------------------------
    // Scanner-driven instruments (Top Movers / MCX commodities)
    // -----------------------------------------------------------------------
    //
    // The scanners decide *what* to trade; the indicator-filter gate decides
    // *when*. Each picked instrument is expanded into a synthetic strategy per
    // side (CE = bullish / PE = bearish) so the normal scan loop runs it through
    // the exact same gate, Dhan option resolution and execution path as a saved
    // strategy - this is the old AST "Indicator filter based trades" behaviour.

    /// Resolve the option leg a scanner pick would execute at `spot` for an
    /// explicit `side` (CE/PE), using the operator's strike preferences. Powers
    /// the "Picked Strikes" readout.
    fn pick_leg(&self, settings: &Settings, sid: i64, name: &str, seg: &str, inst: &str, spot: f64, side: &str) -> Option<Strategy> {
        let side = if side.eq_ignore_ascii_case("PE") { "PE" } else { "CE" };
        let mut s2 = settings.clone();
        s2.option_side = side.to_string();
        let base = self.underlying_base(sid, name, seg, inst, side);
        self.resolve_option_strategy(&base, spot, &s2, true, false)
    }

    /// Every trade (premium) strike a scanner pick would execute on at `spot` for
    /// an explicit `side` (CE/PE) - the whole "Number of Strikes" ladder of the
    /// assigned leg, not just the single picked strike. Powers the "Picked
    /// Strikes (Premium - trade execute)" readout so the list shows exactly the
    /// premium charts the entry will fire on.
    fn pick_legs(&self, settings: &Settings, sid: i64, name: &str, seg: &str, inst: &str, spot: f64, side: &str) -> Vec<Strategy> {
        let side = if side.eq_ignore_ascii_case("PE") { "PE" } else { "CE" };
        let mut s2 = settings.clone();
        s2.option_side = side.to_string();
        // The Picked-Strikes readout lists EVERY strike the operator selected
        // (Above / Below / including ATM ladder), not just the currently +green
        // ones: the entry gate still applies +green, but the readout must show
        // the complete ladder stock-wise so a red strike is visible too.
        s2.only_positive = false;
        let base = self.underlying_base(sid, name, seg, inst, side);
        self.resolve_option_strategies(&base, spot, &s2, true, false)
    }

    /// Synthetic underlying strategy used to resolve an option leg: carries the
    /// scanner's name / segment / instrument and a display id, but no
    /// conditions (the indicator-filter gate is the entry rule).
    ///
    /// The base is ALWAYS a side-pinned leg (`movers_leg = true`) for the caller's
    /// requested `side`. Both callers - the "Picked Strikes" readout (`pick_leg`)
    /// and the Top-Movers Leg Book builder (`build_book_leg`) - pass an explicit
    /// CE/PE, and the resolved contract MUST honour it. Leaving this `false` let
    /// `target_option_side` skip the Top-Movers self-side hard-bind and fall
    /// through to the global NIFTY straight-line lock / auto scanner side, so a
    /// bullish (CE) gainer resolved a PE contract whenever the global direction
    /// was bearish - the readout AND the real frozen leg both inverted CE<->PE.
    fn underlying_base(&self, sid: i64, name: &str, seg: &str, inst: &str, side: &str) -> Strategy {
        let bull = side.eq_ignore_ascii_case("CE");
        // Carry the underlying's real contract lot into the base leg. This base is
        // what the pre-scanned Top-Movers Leg Book strike is built from, so leaving
        // it at 0 dropped the lot on every frozen leg and made the entry fall back
        // to lot 1 (3 units instead of 1800) - the trades closed for 1-2 rupees.
        let lot = scrip::get().and_then(|s| s.lot_for(name, seg).map(|(l, _)| l)).unwrap_or(0.0);
        Strategy {
            id: format!("pick:{}:{}", sid, if bull { "CE" } else { "PE" }),
            name: format!("{name} [{}]", if bull { "CE" } else { "PE" }),
            category: if bull { "BULLISH".into() } else { "BEARISH".into() },
            timeframe: String::new(),
            security_id: sid,
            exchange_segment: seg.to_string(),
            instrument: inst.to_string(),
            trading_symbol: name.to_string(),
            side: "BUY".into(),
            enabled: true,
            conditions: Vec::new(),
            last_signal: 0,
            last_error: String::new(),
            synthetic: true,
            lot,
            group: String::new(),
            manual: false,
            movers_leg: true,
            // Resolver base only; the concrete entry leg carries its own marker.
            liquid_leg: false,
        }
    }

    /// Live `(ltp, change, prev_ltp)` for a resolved contract, or `None` when the
    /// feed has no usable quote for it yet.
    fn leg_quote(&self, c: &Strategy) -> Option<(f64, f64, f64)> {
        let q = self.dhan.market.quotes.lock().ok()?;
        let key = crate::market::quote_key(c.security_id, &c.exchange_segment);
        let v = q.get(&key)?;
        let ltp = v.get("ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
        if ltp <= 0.0 {
            return None;
        }
        let change = v.get("change").and_then(|x| x.as_f64()).unwrap_or(0.0);
        let prev = v.get("prev_ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
        Some((ltp, change, prev))
    }

    /// Sign check for a saved strike, using EXACTLY the engine's existing
    /// `premium_is_green` rule (the option chain's own `+` versus the previous
    /// close; the live tick direction substitutes only when no change has been
    /// published yet). Returns `true` only when the feed has a usable quote and
    /// the premium is genuinely minus; an unknown / not-yet-quoted leg is NOT red.
    fn book_leg_known_red(&self, c: &Strategy) -> bool {
        let Some((ltp, change, prev)) = self.leg_quote(c) else { return false };
        // ltp > 0 is guaranteed by leg_quote: only the SIGN decides.
        !Self::premium_is_green(ltp, prev, change)
    }

    /// Readout guard for the "Picked Strikes" list. When the "+green / fastest"
    /// preference is enforced, a resolved leg whose live premium is genuinely
    /// minus must never be advertised: the entry path blocks that same leg, so
    /// listing it renders a red (falling) premium next to a + chain row and looks
    /// like the engine "picked a minus strike". A leg with no quote yet is kept
    /// visible so the list is never blank while the option chain warms up. When no
    /// green preference is set the operator's explicit Above/Below-ATM choice
    /// stands and a minus leg is listed unchanged.
    fn pick_leg_readout_visible(&self, leg: &Strategy, settings: &Settings) -> bool {
        !Self::enforce_green_filter(false, settings) || !self.book_leg_known_red(leg)
    }

    /// Frozen Leg Book contract for an underlying whose bound side and nearest
    /// expiry still match. The preference setting selects the saved leg ("Pick
    /// fastest" -> fastest riser, "Only +green" -> first +green). `None` when there
    /// is no entry, it belongs to another side/expiry, the preference is off, no
    /// +green strike was saved, or the saved strike is now KNOWN red - the last
    /// case also drops the entry so the next movers pass re-scans that stock.
    fn book_leg_for(&self, sid: i64, expiry: &str, ot: &str, settings: &Settings) -> Option<Strategy> {
        let leg = self.leg_book.lock().ok().and_then(|m| m.get(&sid).cloned())?;
        if !leg.side.eq_ignore_ascii_case(ot) || leg.expiry != expiry {
            return None;
        }
        let chosen = leg.preferred(settings)?.clone();
        // Execution confirmation: never order a saved strike that has since turned
        // minus; drop the entry so the next movers pass re-scans that one stock.
        if self.book_leg_known_red(&chosen) {
            if let Ok(mut m) = self.leg_book.lock() {
                m.remove(&sid);
            }
            return None;
        }
        Some(chosen)
    }

    /// The frozen ranked +green rising list for a Top-Movers underlying on the
    /// requested side ("CE" for a gainer, "PE" for a loser), for the "Picked
    /// Strikes" readout when "Pick fastest positive rising LTP" is on. Entries
    /// that have turned minus in the live feed are dropped. Empty when the book
    /// has no entry (still warming), the side does not match, or nothing is green.
    fn book_fastest_list_for(&self, sid: i64, side: &str) -> Vec<Strategy> {
        let Some(leg) = self.leg_book.lock().ok().and_then(|m| m.get(&sid).cloned()) else {
            return Vec::new();
        };
        if !leg.side.eq_ignore_ascii_case(side) {
            return Vec::new();
        }
        leg.fastest_list
            .into_iter()
            .filter(|c| !self.book_leg_known_red(c))
            .collect()
    }

    /// Nearest F&O expiry for an underlying name / segment, or `None` when the
    /// scrip master cannot resolve it.
    fn nearest_fno_expiry(&self, name: &str, seg: &str) -> Option<String> {
        let sc = scrip::get()?;
        let prefix = scrip::fno_underlying(name);
        if prefix.is_empty() {
            return None;
        }
        let exch = sc.fno_exch(seg, &prefix);
        sc.expiries_for(&prefix, exch)?.first().cloned()
    }

    /// One-time Leg Book scan for a Top-Movers underlying: scans the bound side
    /// ONCE for BOTH preferences and freezes them - the first +green strike (for
    /// "Only +green premium strikes") and the fastest positive rising strike
    /// (highest LTP change %, ties broken by the absolute LTP change, for "Pick
    /// fastest positive rising LTP"). Only +green strikes are ever saved; a
    /// wholly-minus side (or a still-warming chain) stores nothing so the entry
    /// blocks instead of buying a minus leg, and the next movers pass retries.
    fn build_book_leg(&self, sid: i64, name: &str, seg: &str, inst: &str, spot: f64, side: &str, settings: &Settings) -> Option<BookLeg> {
        let expiry = self.nearest_fno_expiry(name, seg)?;
        let base = self.underlying_base(sid, name, seg, inst, side);
        // First +green strike in the "Execute Trade In" walk order.
        let mut s_green = settings.clone();
        s_green.option_side = side.to_string();
        s_green.only_positive = true;
        s_green.fastest_rising = false;
        let green = self.resolve_option_strategy(&base, spot, &s_green, false, true);
        // Ranked +green rising strikes (most-risen first, capped to the
        // "Fastest-Rising Strikes" count). The entry trades the first (the
        // fastest riser); the "Picked Strikes" readout lists them all.
        let fastest_list = self.rising_strike_list(&base, spot, &s_green);
        let fastest = fastest_list.first().cloned();
        if green.is_none() && fastest.is_none() {
            return None;
        }
        Some(BookLeg {
            side: side.to_string(),
            expiry,
            green,
            fastest,
            fastest_list,
            built_ms: now_ms(),
        })
    }

    /// Maintain the Leg Book for the current Top Movers selection. Runs on every
    /// (throttled) movers refresh: prunes entries that are no longer a selected
    /// mover / active side, then re-scans only the underlyings whose entry is
    /// missing, whose bound side flipped, whose nearest expiry rolled, whose saved
    /// strike turned minus, or whose 15-minute sign-monitoring window elapsed. A
    /// populated, still-valid book costs a handful of map lookups and issues NO
    /// new scan, so the engine never re-checks "is this strike green / fastest" on
    /// the hot path.
    /// Whether the stock Leg Book is live: a stock scanner (Top Movers OR Liquid
    /// F&O) is on, this engine carries F&O stocks (not the indices /
    /// commodities-only Paper Trade 2/3), and a strike preference ("Only +green"
    /// / "Pick fastest rising") is on. While live, F&O stock legs are sourced
    /// strictly from the frozen pick - and BOTH scanners feed that same book, so
    /// a liquid F&O stock resolves exactly like a Top Mover (bullish -> CE,
    /// bearish -> PE).
    fn leg_book_active(&self, settings: &Settings) -> bool {
        (settings.movers_on || settings.liquid_on)
            && !self.indices_commodities_only()
            && (settings.only_positive || settings.fastest_rising)
    }

    fn refresh_leg_book(&self, settings: &Settings) {
        // No Leg Book is needed when the scanner is off, this book only trades
        // indices/commodities, or neither preference is on (the engine then uses
        // the plain nearest-ATM strike).
        if !self.leg_book_active(settings) {
            if let Ok(mut m) = self.leg_book.lock() {
                m.clear();
            }
            return;
        }
        // Leg scoping removed: both legs are always kept.
        let active: Option<&str> = None;
        let mut desired: Vec<(i64, String, f64, String, String, String)> = Vec::new();
        // Unified feed: Top Movers gainers/losers AND Liquid F&O gainers/losers
        // populate the SAME Leg Book, so a liquid stock resolves exactly like a
        // Top Mover (bullish filter -> CE from a top gainer, bearish -> PE from a
        // top loser). Sourcing both from their caches here (rather than from a
        // parameter) means either scanner pass refreshes the whole book without
        // pruning the other pass's legs. Manual liquid adds are
        // direction-agnostic, so they are excluded here and resolved by the trend
        // side at entry time.
        let movers = self
            .movers_cache
            .lock()
            .map(|g| g.1.clone())
            .unwrap_or(Value::Null);
        let liquid = self
            .liquid_cache
            .lock()
            .map(|g| g.1.clone())
            .unwrap_or(Value::Null);
        let mover_gainers: Vec<Value> = if settings.movers_on {
            jarr(&movers, "gainers").into_iter().collect()
        } else {
            Vec::new()
        };
        let mover_losers: Vec<Value> = if settings.movers_on {
            jarr(&movers, "losers").into_iter().collect()
        } else {
            Vec::new()
        };
        let liquid_gainers: Vec<Value> = if settings.liquid_on {
            jarr(&liquid, "gainers").into_iter().collect()
        } else {
            Vec::new()
        };
        let liquid_losers: Vec<Value> = if settings.liquid_on {
            jarr(&liquid, "losers").into_iter().collect()
        } else {
            Vec::new()
        };
        let mut seen_sides: std::collections::HashSet<i64> = std::collections::HashSet::new();
        for (side, list) in [
            ("CE", mover_gainers.as_slice()),
            ("PE", mover_losers.as_slice()),
            ("CE", liquid_gainers.as_slice()),
            ("PE", liquid_losers.as_slice()),
        ] {
            if active.is_some() && active != Some(side) {
                continue;
            }
            for r in list {
                let sid = ji(r, "securityId");
                if sid <= 0 {
                    continue;
                }
                // A stock that already holds a frozen leg this pass keeps it (the
                // first ranking wins); a manual add that shows on both legs is
                // skipped so the frozen side is never ambiguous.
                if !seen_sides.insert(sid) {
                    continue;
                }
                // Operator-assigned indices / commodities keep their own explicit
                // resolution (nearest ATM / assigned leg) - never the Leg Book.
                if settings.movers_indices.contains(&sid) {
                    continue;
                }
                let Some((name, seg, inst)) = crate::market::symbol_meta(sid) else { continue };
                if settings.commodity_on && seg.eq_ignore_ascii_case("MCX_COMM") {
                    continue;
                }
                // `last` is absent on a not-yet-quoted liquid row; fall back to the
                // live cache so the ATM centring still has a spot.
                let spot = {
                    let l = jf(r, "last");
                    if l > 0.0 {
                        l
                    } else {
                        self.ltp_of(sid, &seg)
                    }
                };
                desired.push((sid, side.to_string(), spot, name, seg, inst));
            }
        }
        let desired_ids: std::collections::HashSet<i64> = desired.iter().map(|d| d.0).collect();
        if let Ok(mut m) = self.leg_book.lock() {
            m.retain(|sid, _| desired_ids.contains(sid));
        }
        let now = now_ms();
        // Rescan only the entries that are missing / stale; keep the rest frozen.
        let to_build: Vec<(i64, String, f64, String, String, String)> = desired
            .into_iter()
            .filter(|(sid, side, _, name, seg, _)| {
                let existing = self.leg_book.lock().ok().and_then(|m| m.get(sid).cloned());
                match existing {
                    Some(b) => {
                        let exp_ok = self
                            .nearest_fno_expiry(name, seg)
                            .map(|e| e == b.expiry)
                            .unwrap_or(false);
                        let side_ok = b.side.eq_ignore_ascii_case(side);
                        let expired = now.saturating_sub(b.built_ms) >= LEG_BOOK_TTL_MS;
                        // Re-scan as soon as the preference's saved strike has no
                        // +green leg or has turned minus in the live feed.
                        let broke = b.preferred(settings).map(|c| self.book_leg_known_red(c)).unwrap_or(true);
                        !(exp_ok && side_ok && !expired && !broke)
                    }
                    None => true,
                }
            })
            .collect();
        for (sid, side, spot, name, seg, inst) in to_build {
            if let Some(leg) = self.build_book_leg(sid, &name, &seg, &inst, spot, &side, settings) {
                if let Ok(mut m) = self.leg_book.lock() {
                    m.insert(sid, leg);
                }
            }
        }
    }

    /// Replace the "Picked Strikes" rows belonging to one scanner `source`,
    /// keeping the other scanner's rows intact (Top Movers feeds this readout).
    fn update_picked(&self, source: &str, rows: Vec<Value>) {
        // Pre-subscribe every resolved leg on the live feed the moment the
        // scanner picks it. The entry hot path then finds a cached LTP instead
        // of waiting for the subscription's first tick (`wait_feed_ltp`), which
        // is what made several matching stocks enter one-after-another instead
        // of together. Deduplicated inside `watch_options_now`, so re-running
        // this on every 100ms refresh costs nothing after the first pass.
        let secs: Vec<(i64, String)> = rows
            .iter()
            .filter_map(|r| {
                let sid = ji(r, "securityId");
                let seg = js(r, "segment");
                if sid > 0 && !seg.is_empty() {
                    Some((sid, seg))
                } else {
                    None
                }
            })
            .collect();
        self.dhan.watch_options_now(&secs);
        if let Ok(mut g) = self.picked_strikes.lock() {
            g.1.retain(|r| js(r, "source") != source);
            g.1.extend(rows);
            g.0 = now_ms();
        }
    }

    /// Resolve a Manual Strike Select pick to its concrete option contract
    /// (security id, trading symbol, execution segment, instrument). Re-read from
    /// the scrip master on every pass so a rolled/re-issued contract id is never
    /// stale.
    fn manual_contract(&self, m: &ManualStrike) -> Option<(i64, String, String, String)> {
        let sc = scrip::get()?;
        let ot = m.option_type.to_uppercase();
        if !(ot == "CE" || ot == "PE") || m.strike <= 0.0 {
            return None;
        }
        let res = sc.resolve(&m.symbol_name, &m.expiry, m.strike, &ot, &m.exchange_segment)?;
        let prefix = scrip::fno_underlying(&m.symbol_name);
        let exch = sc.fno_exch(&m.exchange_segment, &prefix);
        let seg = fno_segment(exch).to_string();
        let inst = if scrip::is_index_prefix(&prefix) { "OPTIDX" } else { "OPTSTK" }.to_string();
        Some((res.security_id, res.trading_symbol, seg, inst))
    }

    /// "Picked Strikes" rows for Manual Strike Select: the operator's explicit
    /// contracts, in the exact shape the scanner readout uses. The snapshot feeds
    /// these into the UI `strikes` array, so Picked Strikes - and the Running view
    /// - show the manual selection and nothing else while the mode is on.
    fn manual_picked_rows(&self, settings: &Settings) -> Vec<Value> {
        let mut rows: Vec<Value> = Vec::new();
        for m in &settings.manual_strikes {
            let Some((sid, symbol, seg, inst)) = self.manual_contract(m) else { continue };
            let (underlying, useg, uinst) = crate::market::symbol_meta(m.security_id)
                .unwrap_or_else(|| (m.symbol_name.clone(), m.exchange_segment.clone(), String::new()));
            rows.push(json!({
                "securityId": sid,
                "underlying": underlying,
                "side": m.option_type.to_uppercase(),
                "tradingSymbol": symbol,
                "segment": seg,
                "instrument": inst,
                "spot": 0.0,
                "changePct": 0.0,
                "strike": m.strike,
                "expiry": m.expiry,
                "source": "Manual",
                "runMode": run_mode_for(&seg, &inst, settings),
                "underlyingSecurityId": m.security_id,
                "underlyingSegment": useg,
                "underlyingInstrument": uinst,
            }));
        }
        rows
    }

    /// In Manual Strike Select the Picked Strikes readout is the manual list, not
    /// the scanner resolution. Replaces every row instead of merging a source.
    fn refresh_manual_picked(&self) {
        let settings = match self.doc() {
            Some(d) => d.settings.clone(),
            None => return,
        };
        let rows = self.manual_picked_rows(&settings);
        if let Ok(mut g) = self.picked_strikes.lock() {
            g.1 = rows;
            g.0 = now_ms();
        }
    }

    /// Remember the option-premium leg the engine resolved for a running
    /// strategy. `kind` is `"run"` (the chart the entry conditions are evaluated
    /// on) or `"trade"` (the chart the order executes on). The Running
    /// Strategies view reads these so it can show - and open - the exact chart
    /// each strategy is running on instead of only the picked strikes.
    fn record_strat_leg(&self, id: &str, kind: &str, s: &Strategy) {
        if id.is_empty() || s.security_id <= 0 {
            return;
        }
        if let Ok(mut m) = self.strat_legs.lock() {
            let e = m.entry(id.to_string()).or_insert_with(|| json!({}));
            if let Some(o) = e.as_object_mut() {
                o.insert(
                    kind.to_string(),
                    json!({
                        "securityId": s.security_id,
                        "tradingSymbol": s.trading_symbol,
                        "segment": s.exchange_segment,
                        "instrument": s.instrument,
                    }),
                );
            }
        }
    }

    /// Equity-only scanner universe for the Equity Indicator Based Trade tab.
    /// It builds one plain spot BUY strategy per name from the DAILY liquidity
    /// scan's ranked stock list (the `liquid_trade_count` most-liquid NSE cash
    /// equities by turnover + growth) plus the operator's hand-added names. The
    /// ticked BULLISH indicator filters are the whole entry rule; bearish filters
    /// have no function here. There is no option leg, strike, premium or index.
    fn equity_scanner_targets(&self, settings: &Settings) -> Vec<Strategy> {
        // The equity universe is armed by the liquid master. The book only ever
        // trades the bullish side, so when no bullish filter is ticked there is
        // nothing to gate an entry either.
        if !settings.liquid_on {
            return Vec::new();
        }
        let bull_on = settings.filters.iter().any(|(k, v)| *v && filter_is_bull(k))
            || primary_keys_for_side(settings, true).iter().any(|k| filter_is_bull(k));
        if !bull_on {
            return Vec::new();
        }
        // The trade universe is the daily liquidity scan's ranked list, capped at
        // the operator's "number of stocks to trade". Fall back to the liquid
        // index basket only until the first scan lands, so an armed engine is
        // never silently dead on the first tick.
        let excluded: std::collections::HashSet<i64> =
            settings.scanner_exclude.iter().copied().collect();
        let ranked: Vec<(i64, Option<String>)> = {
            let payload = self.equity_liquidity_cache.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
            jarr(&payload, "stocks")
                .iter()
                .map(|r| {
                    let sid = ji(r, "securityId");
                    let name = r.get("name").and_then(|v| v.as_str()).filter(|s| !s.is_empty()).map(|s| s.to_string());
                    (sid, name)
                })
                .collect()
        };
        let take_n = settings.liquid_trade_count.clamp(0, 500) as usize;
        let mut picks: Vec<(i64, Option<String>)> = Vec::new();
        let mut seen: std::collections::HashSet<i64> = std::collections::HashSet::new();
        if !ranked.is_empty() {
            for (sid, name) in ranked.into_iter().filter(|(sid, _)| *sid > 0 && !excluded.contains(sid)) {
                if picks.len() >= take_n {
                    break;
                }
                if seen.insert(sid) {
                    picks.push((sid, name));
                }
            }
        } else {
            for (sid, name, _seg) in crate::market::liquid_stocks() {
                if sid > 0 && !excluded.contains(&sid) && seen.insert(sid) {
                    picks.push((sid, Some(name)));
                }
            }
        }
        // The operator's hand-added names are always included (beyond top-N), so
        // a manual override can never be silently dropped by the cap.
        for sid in &settings.liquid_list {
            if *sid > 0 && !excluded.contains(sid) && seen.insert(*sid) {
                picks.push((*sid, None));
            }
        }
        let mut out: Vec<Strategy> = Vec::with_capacity(picks.len());
        for (sid, known_name) in picks {
            // Guard against a hand-added id that is not cash equity: when the
            // scrip master knows the contract and it is not an EQUITY/EQ NSE row,
            // this book must never trade it (no index, option or future).
            if let Some(c) = scrip::get().and_then(|sc| sc.contract(sid).cloned()) {
                let is_cash = c.exchange.eq_ignore_ascii_case("NSE")
                    && (c.instrument.eq_ignore_ascii_case("EQUITY") || c.instrument.eq_ignore_ascii_case("EQ"));
                if !is_cash {
                    continue;
                }
            }
            // Resolve the name from the scrip master first (the full universe),
            // then the small catalog, so a scanned name is never blank.
            let scrip_name = scrip::get().and_then(|sc| sc.contract(sid).map(|c| c.underlying.clone()));
            let meta = crate::market::equity_meta(sid);
            let name = known_name
                .or(scrip_name)
                .or_else(|| meta.as_ref().map(|(n, _, _)| n.clone()))
                .unwrap_or_else(|| sid.to_string());
            let seg = "NSE_EQ".to_string();
            let inst = "EQUITY".to_string();
            let id = format!("eqscan:{}:BUY", sid);
            out.push(Strategy {
                id,
                name: format!("{name} [equity bullish]"),
                category: "BULLISH".into(),
                timeframe: String::new(),
                security_id: sid,
                exchange_segment: seg,
                instrument: inst,
                trading_symbol: name,
                side: "BUY".into(),
                enabled: true,
                conditions: Vec::new(),
                last_signal: 0,
                last_error: String::new(),
                synthetic: true,
                lot: 1.0,
                group: String::new(),
                manual: false,
                movers_leg: false,
                liquid_leg: true,
            });
        }
        out
    }

    /// Premium-chart-only strict trend pin.
    ///
    /// In premium-only mode, when a trend-following section is ON, every leg it
    /// OWNS is pinned to the committed trend side: a bullish committed trend arms
    /// ONLY the CE call leg and a bearish one ONLY the PE put leg. The opposite
    /// leg is never built, so a premium-chart book can never hold a losing
    /// opposite-side leg through a trend flip. A neutral / uncommitted read arms
    /// nothing for that underlying - the side is never guessed.
    ///
    /// Coverage is deliberate so untouched setups keep their behaviour:
    ///   * Indices Trend Following owns the operator's index set.
    ///   * Commodities Trend Following owns the operator's commodity set.
    ///   * NIFTY Trend Following owns the index / F&O stock legs.
    ///
    /// Returns `Some(Some(bull))` to pin the leg, `Some(None)` to drop the
    /// underlying (no committed side), and `None` when no trend section covers it
    /// (the caller leaves the leg untouched).
    fn premium_trend_pin(&self, settings: &Settings, sid: i64) -> Option<Option<bool>> {
        let pick_side = |payload: &Value| -> Option<bool> {
            for r in payload.as_array().into_iter().flatten() {
                if ji(r, "securityId") == sid {
                    let side = js(r, "side");
                    if side.eq_ignore_ascii_case("CE") {
                        return Some(true);
                    }
                    if side.eq_ignore_ascii_case("PE") {
                        return Some(false);
                    }
                }
            }
            None
        };
        if self.allows_indices() && settings.index_trend_on && settings.movers_indices.contains(&sid) {
            let payload = self.index_trend_picks.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
            return Some(pick_side(&payload));
        }
        if self.allows_commodities() && settings.comm_trend_on && settings.commodity_list.contains(&sid) {
            let payload = self.comm_trend_picks.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
            return Some(pick_side(&payload));
        }
        if settings.nifty_trend_on {
            if let Some((_, seg, inst)) = crate::market::symbol_meta(sid) {
                if matches!(category_for(&seg, &inst), StratCat::Fno | StratCat::Index) {
                    let dir = self.nifty_dir.load(Ordering::Relaxed);
                    return Some(if dir > 0 {
                        Some(true)
                    } else if dir < 0 {
                        Some(false)
                    } else {
                        None
                    });
                }
            }
        }
        None
    }

    /// Apply [`premium_trend_pin`] to a fully-built scan universe: for every leg
    /// running on the premium chart, keep only the committed trend side, drop
    /// both legs of an underlying that has no committed side yet, and leave
    /// spot-routed / uncovered underlyings untouched. No-op outside premium mode.
    fn apply_premium_trend_pin(&self, settings: &Settings, out: Vec<Strategy>) -> Vec<Strategy> {
        out.into_iter()
            .filter(|s| {
                // Only legs actually trading their option-premium chart are
                // strictly pinned; a category left on the spot chart keeps the
                // normal bull/bear gating.
                if !premium_only_for(s, settings) {
                    return true;
                }
                match self.premium_trend_pin(settings, s.security_id) {
                    Some(Some(want_bull)) => strategy_is_bull(s) == want_bull,
                    Some(None) => false,
                    None => true,
                }
            })
            .collect()
    }

    fn scanner_targets(&self, settings: &Settings) -> Vec<Strategy> {
        // Equity Indicator Based Trade (Paper Trade 4): a completely separate
        // universe - liquid NSE cash EQUITY only, BUY side only, gated by the
        // BULLISH indicator filters only. No indices, no options, no strikes, no
        // commodities. Every name resolves to its NSE_EQ / EQ row and is a plain
        // spot BUY; the option-leg machinery below is never reached.
        if self.equity_indicators_only() || settings.equity_only {
            return self.equity_scanner_targets(settings);
        }
        let (bull_side, bear_side) = if premium_only_active(settings) {
            // "Premium chart only (run + trade)": only the BULLISH indicator
            // filters gate entries, and they gate BOTH legs - the Top Gainer CE
            // call leg AND the Top Loser PE put leg. Bearish indicator filters
            // have no function in this mode, so they never arm (or veto) a side.
            // The operator's selected side still narrows this via `side_allowed`.
            let any = settings.filters.iter().any(|(k, v)| *v && filter_is_bull(k))
                || primary_keys_for_side(settings, true).iter().any(|k| filter_is_bull(k));
            (any, any)
        } else {
            (
                settings.filters.iter().any(|(k, v)| *v && filter_is_bull(k))
                    || primary_keys_for_side(settings, true).iter().any(|k| filter_is_bull(k)),
                settings.filters.iter().any(|(k, v)| *v && filter_is_bear(k))
                    || primary_keys_for_side(settings, false).iter().any(|k| filter_is_bear(k)),
            )
        };
        // Paper Trade 2 per-instrument trend following: each added index /
        // commodity supplies the side its OWN confirmation-indicator trend
        // resolved. These rows are their own universe (armed by the trend toggle,
        // not by the filter sides), so they are collected before the side guards.
        let index_trend_rows = if self.indices_commodities_only() && self.allows_indices() && settings.index_trend_on {
            self.index_trend_picks.lock().map(|g| g.1.clone()).unwrap_or(Value::Null)
        } else {
            Value::Null
        };
        let comm_trend_rows = if self.indices_commodities_only() && self.allows_commodities() && settings.comm_trend_on {
            self.comm_trend_picks.lock().map(|g| g.1.clone()).unwrap_or(Value::Null)
        } else {
            Value::Null
        };
        let trend_armed = index_trend_rows.as_array().map(|a| !a.is_empty()).unwrap_or(false)
            || comm_trend_rows.as_array().map(|a| !a.is_empty()).unwrap_or(false);
        if !bull_side && !bear_side && !trend_armed {
            return Vec::new();
        }
        // Top-Movers / NIFTY straight-line side scoping (`side_allowed`) and the
        // auto CE/PE bias (`active_side`) have been removed: every selected
        // underlying builds both legs and the indicator filter gate decides which
        // side fires. The one exception is the NIFTY Trend Following master: when
        // it is ON its committed side owns the Top Movers stock legs too (see the
        // movers block below), so the opposite leg is never built.
        let (allow_bull, allow_bear) = (true, true);
        // While a per-instrument trend section is ON, its instruments are owned
        // entirely by that section: the plain "Indices & Commodities" scanner must
        // not arm them (so the manual leg dropdown is strictly inactive - it can
        // neither override nor force the side). Trend-owned, but no committed
        // direction yet = no trade this pass (never guess a side).
        let index_trend_owned = self.indices_commodities_only() && self.allows_indices() && settings.index_trend_on;
        let comm_trend_owned = self.indices_commodities_only() && self.allows_commodities() && settings.comm_trend_on;

        fn add(
            out: &mut Vec<Strategy>,
            seen: &mut std::collections::HashSet<String>,
            sid: i64,
            force: Option<bool>,
            allow_bull: bool,
            allow_bear: bool,
            movers_leg: bool,
            liquid_leg: bool,
            settings: &Settings,
        ) {
            if sid <= 0 {
                return;
            }
            // A stock scanner pick (`movers_leg`) must resolve to the equity row:
            // ids like `25` are shared by an index and a stock in the catalog.
            let meta = if movers_leg {
                crate::market::equity_meta(sid)
            } else {
                crate::market::symbol_meta(sid)
            };
            let Some((name, seg, inst)) = meta else { return };
            // Strict Target Lab owns the leg for the underlyings it covers: the
            // scan builds only the plan's CE/PE side and ignores the indicator
            // filters' own side / Top-Movers pin. With no fresh plan
            // (disconnected, cold or stale) `force` is used normally; confidence
            // never weakens a fresh plan's leg (it only gates auto-cut/exit).
            let plan_force = target_plan_side_for(settings, &name);
            let force = plan_force.or(force);
            // "Strike: Option Type" (Both CE & PE / Call / Put) RESTRICTS which
            // legs the automatic universe may build on top of every scanner pin:
            // "Call (CE)" arms only call legs and "Put (PE)" only put legs, while
            // "Both" leaves the pin unchanged. A pin that points at the excluded
            // side builds NOTHING (a bearish stock is never silently converted
            // into a call). Strict Target Lab plans and manual-strike overrides
            // own their leg and are never restricted.
            let force = if plan_force.is_none() && !settings.manual_strikes_enabled {
                match settings.option_side.to_ascii_uppercase().as_str() {
                    // Bearish pin excluded outright; an unpinned underlying builds
                    // only the call leg.
                    "CE" if force == Some(false) => return,
                    // Bullish pin excluded outright; an unpinned underlying builds
                    // only the put leg.
                    "PE" if force == Some(true) => return,
                    "CE" => Some(true),
                    "PE" => Some(false),
                    _ => force,
                }
            } else {
                force
            };
            let lot = crate::scrip::get()
                .and_then(|s| s.lot_for(&name, &seg).map(|(l, _)| l))
                .unwrap_or(0.0);
            let mk = |out: &mut Vec<Strategy>, seen: &mut std::collections::HashSet<String>, bull: bool| {
                let key = format!("scan:{}:{}", sid, if bull { "CE" } else { "PE" });
                if !seen.insert(key.clone()) {
                    // Same underlying already armed by an earlier scanner block
                    // (e.g. Top Movers picked it before the Liquid F&O scanner
                    // did). The leg is shared, but a Liquid origin must still get
                    // the Liquid lot policy - upgrade the existing row instead of
                    // dropping the marker with the duplicate.
                    if liquid_leg {
                        if let Some(existing) = out.iter_mut().find(|x| x.id == key) {
                            existing.liquid_leg = true;
                        }
                    }
                    return;
                }
                out.push(Strategy {
                    id: key,
                    name: format!("{} [scan {}]", name, if bull { "bullish" } else { "bearish" }),
                    category: if bull { "BULLISH".into() } else { "BEARISH".into() },
                    timeframe: String::new(),
                    security_id: sid,
                    exchange_segment: seg.clone(),
                    instrument: inst.clone(),
                    trading_symbol: name.clone(),
                    side: "BUY".into(),
                    enabled: true,
                    conditions: Vec::new(),
                    last_signal: 0,
                    last_error: String::new(),
                    synthetic: true,
                    lot,
                    group: String::new(),
                    manual: false,
                    movers_leg,
                    liquid_leg,
                });
            };
            match force {
                Some(true) => {
                    if allow_bull {
                        mk(out, seen, true);
                    }
                }
                Some(false) => {
                    if allow_bear {
                        mk(out, seen, false);
                    }
                }
                None => {
                    if allow_bull {
                        mk(out, seen, true);
                    }
                    if allow_bear {
                        mk(out, seen, false);
                    }
                }
            }
        }

        let mut out: Vec<Strategy> = Vec::new();
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();

        // Manual Strike Select (testing): the tradeable universe is the operator's
        // explicit picks instead of the Top Movers / NIFTY-trend / commodity
        // scanners. Each picked underlying becomes a synthetic strategy on the
        // side(s) the operator chose, so the ticked Indicator filters gate entries
        // on the manual strikes exactly like the normal Indicator-filters mode -
        // the engine still only ever executes the manual contracts.
        if settings.manual_strikes_enabled {
            for (sid, has_ce, has_pe) in manual_target_specs(&settings.manual_strikes) {
                if has_ce {
                    add(&mut out, &mut seen, sid, Some(true), allow_bull, allow_bear, false, false, settings);
                }
                if has_pe {
                    add(&mut out, &mut seen, sid, Some(false), allow_bull, allow_bear, false, false, settings);
                }
            }
            return out;
        }

        // Paper Trade 2 trades indices + option-chain commodities only.
        let indices_only = self.indices_commodities_only();

        // Commodities (MCX): ONLY the operator's explicitly added set. An empty
        // list arms nothing - never default to the whole commodity universe, or
        // switching the scanner ON would trade commodities the operator never
        // added.
        if settings.commodity_on && self.allows_commodities() {
            let rows: Vec<_> = crate::market::commodity_rows()
                .into_iter()
                .filter(|c| settings.commodity_list.contains(&c.security_id))
                .filter(|c| !indices_only || c.has_options)
                .collect();
            for c in rows {
                if comm_trend_owned {
                    continue;
                }
                // No leg is pinned by the scanner: the selected commodity builds
                // both legs and the indicator filter gate decides the side.
                add(&mut out, &mut seen, c.security_id, None, allow_bull, allow_bear, false, false, settings);
            }
        }

        // Top Movers: each selected gainer / loser underlying is a universe entry
        // pinned to its own side - a Top Gainer arms the CE call leg, a Top Loser
        // the PE put leg. The indicator filter gate still decides *when* it
        // enters, but the side can never flip (the Leg Book holds a CE pick for a
        // gainer and a PE pick for a loser only). Operator indices are included as
        // their own universe entries.
        //
        // While NIFTY Trend Following is ON it owns the side of these stock legs:
        // a bullish NIFTY read arms ONLY the Top Gainers (CE) and a bearish read
        // ONLY the Top Losers (PE). Before this, the plain movers block kept
        // building both legs, so a Top Loser PE could enter while the committed
        // NIFTY trend was bullish (and a Top Gainer CE while it was bearish). No
        // committed direction (dir == 0) arms nothing, matching the NIFTY picks
        // pass; already-open opposite-side positions are left to their own
        // SL/target/trail - the gate only stops new entries.
        if settings.movers_on {
            let payload = self.movers_cache.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
            if !indices_only {
                let sideways_block = settings.no_trade_sideways
                    && nifty_dir_feature_on(settings)
                    && self.nifty_sideways.load(Ordering::Relaxed);
                let (movers_bull, movers_bear) = if sideways_block {
                    (false, false)
                } else if nifty_dir_feature_on(settings) {
                    let dir = self.nifty_dir.load(Ordering::Relaxed);
                    (
                        dir > 0 && self.nifty_strict_side_ok(settings, true),
                        dir < 0 && self.nifty_strict_side_ok(settings, false),
                    )
                } else {
                    (true, true)
                };
                if movers_bull {
                    for r in jarr(&payload, "gainers") {
                        add(&mut out, &mut seen, ji(&r, "securityId"), Some(true), true, true, true, false, settings);
                    }
                }
                if movers_bear {
                    for r in jarr(&payload, "losers") {
                        add(&mut out, &mut seen, ji(&r, "securityId"), Some(false), true, true, true, false, settings);
                    }
                }
            }
            for id in &settings.movers_indices {
                if !self.allows_indices() || index_trend_owned {
                    continue;
                }
                add(&mut out, &mut seen, *id, None, allow_bull, allow_bear, false, false, settings);
            }
        }

        // Liquid F&O stocks: the day's top gainers (CE) and top losers (PE) from
        // the liquid index-constituent basket, plus the operator's explicit
        // gainer / loser dropdown picks and hand-added names. A gainer is pinned
        // to the call leg and a loser to the put leg (same rule as Top Movers);
        // a hand-added stock builds both legs and lets the indicator gate choose
        // the side. No sideways/trend gate here - this scanner is its own
        // universe and the indicator filters still decide WHEN a leg enters.
        if settings.liquid_on && self.allows_liquid_stocks() {
            let payload = self.liquid_cache.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
            if !indices_only {
                for r in jarr(&payload, "gainers") {
                    add(&mut out, &mut seen, ji(&r, "securityId"), Some(true), allow_bull, allow_bear, true, true, settings);
                }
                for r in jarr(&payload, "losers") {
                    add(&mut out, &mut seen, ji(&r, "securityId"), Some(false), allow_bull, allow_bear, true, true, settings);
                }
                for r in jarr(&payload, "added") {
                    add(&mut out, &mut seen, ji(&r, "securityId"), None, allow_bull, allow_bear, true, true, settings);
                }
            }
            if settings.liquid_gainer > 0 {
                add(&mut out, &mut seen, settings.liquid_gainer, Some(true), allow_bull, allow_bear, true, true, settings);
            }
            if settings.liquid_loser > 0 {
                add(&mut out, &mut seen, settings.liquid_loser, Some(false), allow_bull, allow_bear, true, true, settings);
            }
        }

        // Paper Trade 2 per-instrument trend following: the committed trend side
        // PINS the leg - CE = call leg only, PE = put leg only. The opposite leg
        // is never built, so a bullish trend can never enter a put and vice
        // versa. The indicator filter gate still decides WHEN that pinned leg
        // enters. A missing/unknown side is skipped, never guessed.
        if self.indices_commodities_only() {
            let groups: [(&Value, bool); 2] = [
                (&index_trend_rows, self.allows_indices()),
                (&comm_trend_rows, self.allows_commodities()),
            ];
            for (rows, allowed) in groups {
                if !allowed {
                    continue;
                }
                for p in rows.as_array().into_iter().flatten() {
                    let sid = ji(p, "securityId");
                    if sid <= 0 {
                        continue;
                    }
                    let side = js(p, "side");
                    let force = if side.eq_ignore_ascii_case("CE") {
                        Some(true)
                    } else if side.eq_ignore_ascii_case("PE") {
                        Some(false)
                    } else {
                        continue;
                    };
                    add(&mut out, &mut seen, sid, force, true, true, false, false, settings);
                }
            }
        }

        // NIFTY trend: the trend direction PINS the leg - a bullish trend arms
        // the CE call leg of a Top Gainer, a bearish trend the PE put leg of a Top
        // Loser. `refresh_nifty_scan` already gated each pick by its side (gainers
        // -> CE, losers -> PE, straight-line / BB%b Pane confirmation), so the
        // pick's own `side` is authoritative here: only that leg is armed instead
        // of both. Only F&O-stock underlyings ever run - an index or commodity
        // pick is dropped.
        if nifty_dir_feature_on(settings) && !indices_only {
            let sideways_block = settings.no_trade_sideways && self.nifty_sideways.load(Ordering::Relaxed);
            if sideways_block {
                return self.apply_premium_trend_pin(settings, out);
            }
            let payload = self.nifty_picks.lock().map(|g| g.1.clone()).unwrap_or(Value::Null);
            for p in jarr(&payload, "picks") {
                let sid = ji(&p, "underlyingSecurityId");
                if sid <= 0 {
                    continue;
                }
                let side = js(&p, "side");
                let force = if side.eq_ignore_ascii_case("CE") {
                    Some(true)
                } else if side.eq_ignore_ascii_case("PE") {
                    Some(false)
                } else {
                    None
                };
                let Some((_, seg, inst)) = crate::market::symbol_meta(sid) else { continue };
                if category_for(&seg, &inst) != StratCat::Fno {
                    continue;
                }
                add(&mut out, &mut seen, sid, force, allow_bull, allow_bear, false, false, settings);
            }
        }

        self.apply_premium_trend_pin(settings, out)
    }

    // -----------------------------------------------------------------------
    // Signal scan
    // -----------------------------------------------------------------------

    async fn scan_signals(&self) {
        // Heartbeat: proving the scan actually runs is the ONE thing the blocker
        // list cannot show - a dead / never-scheduled scan records no blocker, so
        // the operator would see an empty panel and no reason. Stamp the attempt
        // here (before any early return) so "scanAgeSec" in the diagnostics tells
        // apart "gates blocking" from "scan never ran".
        self.scan_passes.fetch_add(1, Ordering::Relaxed);
        self.scan_heartbeat.store(now_ms(), Ordering::Relaxed);
        // Entries only while Dhan is connected AND the live feed is streaming a
        // fresh tick: a silent / closed / disconnected feed must not trade on a
        // stale mark (which would produce fake results).
        if !self.dhan.is_connected().await || !self.dhan.feed_live() {
            let why = if !self.dhan.is_connected().await {
                "Dhan session not connected (connect first)"
            } else {
                "live feed is not streaming a fresh tick"
            };
            self.note_blocker("warn", "feed", "", why);
            return;
        }
        // Feed is healthy again: drop the transient connection reason so the
        // panel does not keep showing a block that has already cleared.
        self.clear_blocker_codes(&["feed"]);
        let (mut strategies, selected, trade_limit, trade_limit_count, ai_trades, movers_on, settings0, operator_time_ok) = {
            let Some(d) = self.doc() else { return };
            (
                d.strategies.clone(),
                d.selected.clone(),
                d.settings.trade_limit,
                d.settings.trade_limit_count.max(0),
                d.settings.ai_trades,
                d.settings.movers_on,
                d.settings.clone(),
                d.strategy_time_ok(),
            )
        };
        let now_secs = crate::market::now_secs();
        // Hard market-closed gate: outside the NSE cash/F&O session only the MCX
        // commodity session (till 23:00) is live. If both are shut there is
        // nothing to trade at all, so skip the whole pass.
        if !nse_session_open(now_secs) && !mcx_session_open(now_secs) {
            self.note_blocker("warn", "market-closed", "", "market closed (NSE 09:15-15:30, MCX till 23:00) - no entries this pass");
            self.log_throttled("session-closed", 60_000, "info", "market closed (NSE 09:15-15:30, MCX till 23:00) - no entries this pass");
            return;
        }
        self.clear_blocker_codes(&["market-closed"]);
        // F&O-stock expiry-day guard: on a stock expiry day, block new
        // F&O-stock entries either for the WHOLE day ("No trade on expiry day")
        // or from the operator's cutoff onwards (paired with the automatic
        // square-off in `check_fno_expiry_square_off`). Indices and commodities
        // are unaffected.
        let fno_expiry_time_block = settings0.fno_expiry_square_off_enabled
            && hhmm_to_minutes(&settings0.fno_expiry_square_off_time)
                .map(|m| ist_minutes() >= m)
                .unwrap_or(false);
        let fno_expiry_no_trade = (settings0.fno_expiry_no_trade_day_enabled || fno_expiry_time_block)
            && self.fno_stock_expiry_today();
        // Scanner-picked instruments (Top Movers / MCX commodities)
        // join the run set as synthetic strategies so the indicator-filter gate +
        // Dhan execution path below drives real trades for them too.
        strategies.extend(self.scanner_targets(&settings0));
        let commodity_on = settings0.commodity_on;
        // A strategy runs when it is enabled in the Saved Strategies table, OR it
        // is ticked into the AST run set (`selected`, also fed by AI auto-pick)
        // and "Call manually selected strategies" is on, OR it is one of the
        // live top-N AI trader picks while "Smart AI trader picked strategies"
        // is on (old AST `activeStrategies()` parity - AI picks keep updating
        // every scan instead of only at Fetch time).
        let ai_picks: std::collections::BTreeSet<String> =
            if settings0.ai_pick { self.doc().map(|d| ai_pick_ids(&d).into_iter().collect()).unwrap_or_default() } else { Default::default() };
        let call_manual = settings0.call_manual;
        // Run mode (old AST run-mode section): Indicator-filters mode runs
        // ONLY the scanner-universe synthetic strategies - their entry rule is
        // the ticked indicator filters, gated by majority (or strict AND / AI
        // Brain when those are enabled). This is the only mode exposed in the
        // UI, so `filter_mode` defaults to true. The legacy Normal mode
        // (`filter_mode == false`, run the ticked / enabled / AI-picked
        // strategies with the indicator filters acting as extra gates) is
        // retained solely for Paper Trade 3, which forces it off.
        let filter_mode = settings0.filter_mode;
        // A strategy runs when enabled / manually ticked / AI-picked. The
        // "Research stream" scoping (`stream_allows`) has been removed.
        let in_run = |s: &Strategy| {
            s.synthetic == filter_mode
                && (s.enabled || (call_manual && *selected.get(&s.id).unwrap_or(&false)) || ai_picks.contains(&s.id))
        };
        let eligible = strategies
            .iter()
            .filter(|s| in_run(s) && s.security_id > 0 && (!s.conditions.is_empty() || s.synthetic))
            .count();
        if eligible == 0 && !movers_on && !commodity_on {
            let why = if settings0.equity_only {
                "No tradeable equity instruments - turn the Liquid Equity master ON and tick at least one BULLISH indicator filter"
            } else {
                "No tradeable instruments resolved - open a chart symbol, enable Top Movers or Commodities, and tick at least one indicator filter"
            };
            self.note_blocker("warn", "no-instruments", "", why);
            self.log_throttled("no-instruments", 15_000, "warn", why);
        }
        self.log_throttled(
            "scan-diag",
            15_000,
            "info",
            &format!("scan pass: {} strategies, {} eligible, filter_mode={} movers={} comm={}", strategies.len(), eligible, filter_mode, movers_on, commodity_on),
        );
        // Per-strategy scan gap. When Engine Scan is active the outer engine loop
        // already gates the whole pass (fixed interval or bar close), so the
        // per-strategy throttle is disabled (0) and every eligible strategy is
        // evaluated on that pass. With Engine Scan off, keep the historical
        // 100ms per-strategy cadence.
        let scan_gap_ms: i64 = if settings0.scan_interval_on {
            0
        } else {
            100
        };
        for mut strat in strategies {
            if !in_run(&strat) || strat.security_id <= 0 || (strat.conditions.is_empty() && !strat.synthetic) {
                continue;
            }
            // Hard market-closed gate per instrument: NSE cash/F&O only in
            // 09:15-15:30, MCX commodities till 23:00. A closed market never
            // places a trade, even if an outer pass slipped through.
            if !strat_session_open(strat_category(&strat), operator_time_ok, now_secs) {
                self.note_blocker(
                    "info",
                    "session",
                    &strat.name,
                    &format!("{} - outside its trade window (session / start-after / no-trade-after)", strat.name),
                );
                continue;
            }
            // F&O-stock expiry-day no-trade block: on a stock expiry day, no new
            // stock entry may fire - either all day ("No trade on expiry day") or
            // from the cutoff onwards. Only the F&O class is gated; indices /
            // commodities / cash equity keep running.
            if fno_expiry_no_trade && !settings0.equity_only && strat_category(&strat) == StratCat::Fno {
                self.note_blocker(
                    "info",
                    "fno-expiry",
                    &strat.name,
                    &format!("{} - F&O stock expiry day guard is blocking new stock entries", strat.name),
                );
                continue;
            }
            // One shared budget for all three paper tabs, another for all three
            // live tabs. The entry scan only PEEKS: a saturated window drops the
            // signal (never queues it at a chased price), while the actual fill /
            // send boundary reserves the slot.
            let group = if self.paper { Group::Paper } else { Group::Real };
            let order_per_sec = order_rate::cap(group);
            let settings = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
            // Engine controls: the 1min/5min checkboxes (or the strategy's own TF
            // when "Use AST settings" is off) and Multi-TF confirm choose the run
            // chart's timeframe. Override the strategy's stored TF so every
            // downstream fetch (spot, option premium, AI ATR SL) uses it.
            let mtf_tfs = if settings.mtf { mtf_pair(&settings) } else { None };
            strat.timeframe = match &mtf_tfs {
                Some((entry, _)) => entry.clone(),
                None => engine_tf(&settings, &strat),
            };
            // Multi-position support: count the strategy's open positions, kept
            // for the legacy single-position fallback. The old hard stop ("never
            // open a second position for the same strategy") is gone - the entry
            // gate further down decides how many concurrent positions a strategy
            // may hold, capped only by the global orders/sec limit.
            let running = self
                .doc()
                .map(|d| d.positions.iter().filter(|p| js(p, "strategyId") == strat.id).count())
                .unwrap_or(0);
            let now = now_ms();
            // Tick-native: every strategy is evaluated on the LIVE forming bar at
            // the engine's ultrafast cadence. There is no closed-bar wait and no
            // bar-grid self-throttle any more, so a signal fires on the very tick
            // it appears instead of at the next bar close.
            {
                let last = self.last_sig.lock().ok().and_then(|m| m.get(&strat.id).copied()).unwrap_or(0);
                if now - last < scan_gap_ms {
                    continue;
                }
                if let Ok(mut m) = self.last_sig.lock() {
                    m.insert(strat.id.clone(), now);
                }
            }
            let candles = match self
                .live_candles(strat.security_id, &strat.exchange_segment, &strat.instrument, &strat.timeframe)
                .await
            {
                Ok(c) if c.len() >= 3 => c,
                Ok(c) => {
                    self.note_blocker(
                        "info",
                        "candles",
                        &strat.name,
                        &format!("{} [{}] - only {} candles available", strat.name, strat.timeframe, c.len()),
                    );
                    if strat.synthetic {
                        self.log_throttled(&format!("nofetch:{}", strat.id), 60_000, "warn", &format!("scan: only {} candles for {} [{}]", c.len(), strat.name, strat.timeframe));
                    }
                    continue;
                }
                Err(e) => {
                    self.note_blocker(
                        "warn",
                        "candles",
                        &strat.name,
                        &format!("{} [{}] - candle fetch failed: {e}", strat.name, strat.timeframe),
                    );
                    if strat.synthetic {
                        self.log_throttled(&format!("nofetch:{}", strat.id), 60_000, "warn", &format!("scan: candle fetch failed for {}: {e}", strat.name));
                    }
                    continue;
                }
            };
            // Live forming bar: offset 0 is the bar currently being built from
            // the tick stream, so a rule reacts to the moving price itself - never
            // to a bar that had to close first.
            let offset = 0usize;
            // "Strategy should be run in": spot chart (the strategy's own
            // instrument), the resolved option-premium chart, or both (dual
            // confirmation). Every evaluated chart must pass before entry.
            let run_mode = run_mode_of(&strat, &settings);
            let want_spot = run_mode != "premium";
            // `futures` is the commodity near-month contract, i.e. its own spot
            // chart (old app maps futures -> spot), never the option premium.
            let want_premium = run_mode != "spot" && run_mode != "futures";
            let mut eval: Vec<(Strategy, Vec<Candle>)> = Vec::new();
            // Premium-only per-strike analysis: the individual selected strike
            // charts are collected HERE (never into `eval`, which stays the
            // strategy-level SPOT confirmation set). Each strike is then gated on
            // its OWN premium chart below, so one failing strike can never veto
            // (or force) the others - the whole "Execute Trade In" ladder is
            // analysed strike by strike and only the passing strikes fire.
            let mut premium_strikes: Vec<(Strategy, Vec<Candle>)> = Vec::new();
            if want_spot {
                // "Run Strategy In: Spot chart" for an option-instrument strategy
                // must analyse the UNDERLYING spot chart, not the option's own
                // premium chart. Fall back to the strategy's own candles if the
                // underlying cannot be resolved.
                if is_option_leg(&strat) {
                    if let Some(pair) = self.underlying_candles(&strat).await {
                        self.record_strat_leg(&strat.id, "run", &pair.0);
                        eval.push(pair);
                    } else {
                        self.record_strat_leg(&strat.id, "run", &strat);
                        eval.push((strat.clone(), candles.clone()));
                    }
                } else {
                    self.record_strat_leg(&strat.id, "run", &strat);
                    eval.push((strat.clone(), candles.clone()));
                }
            }
            if want_premium {
                let side = self.desired_option_side(&settings, &strat);
                if self.no_premium_cached(strat.security_id, &side) {
                    // A recent resolve failed for this underlying + side. Skip the
                    // whole resolution instead of re-walking the option chain on
                    // every 100ms tick; the cache lapses on its own. The blocker is
                    // still refreshed so the panel keeps naming the live reason.
                    if run_mode == "premium" {
                        self.note_blocker(
                            "warn",
                            "no-premium",
                            &strat.name,
                            &format!("{} - no {side} option contracts available (premium leg missing, retrying in {})", strat.name, (NO_PREMIUM_CACHE_MS / 1000)),
                        );
                        continue;
                    }
                } else {
                    let pairs = self.premium_candles_all(&strat, &settings).await;
                    if pairs.is_empty() {
                        self.mark_no_premium(strat.security_id, &side);
                        if run_mode == "premium" {
                            self.note_blocker(
                                "warn",
                                "no-premium",
                                &strat.name,
                                &format!("{} - no {side} option contracts available (premium leg missing)", strat.name),
                            );
                            self.log_throttled(
                                &format!("skip-premium:{}:{side}", strat.id),
                                60_000,
                                "warn",
                                &format!(
                                    "No {side} option contracts for {} - skipping ({side} leg)",
                                    strat.name
                                ),
                            );
                            continue;
                        }
                        if run_mode == "both" {
                            self.note_blocker(
                                "warn",
                                "no-premium",
                                &strat.name,
                                &format!("{} - dual run needs spot + premium, {side} option leg missing", strat.name),
                            );
                            self.log_throttled(
                                &format!("skip-both:{}:{side}", strat.id),
                                60_000,
                                "warn",
                                &format!(
                                    "No {side} option contracts for {} - skipping (dual run needs spot + premium)",
                                    strat.name
                                ),
                            );
                        }
                    } else {
                        self.clear_no_premium(strat.security_id, &side);
                        premium_strikes = pairs;
                    }
                }
            }
            if eval.is_empty() && premium_strikes.is_empty() {
                self.note_blocker(
                    "warn",
                    "no-premium",
                    &strat.name,
                    &format!("{} - no evaluable chart (spot/premium both unavailable)", strat.name),
                );
                continue;
            }
            let mut all_pass = true;
            let synth = strat.synthetic;
            // When the strategy also runs on the spot chart (`both` mode), every
            // spot leg must pass exactly as before (the `eval` loop below). In
            // premium-only mode `eval` is empty and the per-strike premium ladder
            // owns the gate.
            // Strikes whose OWN premium chart passed the indicator gate. Only
            // these are eligible to fire; a strike with no chart or a failing
            // gate is skipped THIS scan (it keeps its place in the ladder).
            let mut passing_strikes: Vec<Strategy> = Vec::new();
            let mut gate_settings = self.template_for_direction(&settings, &strat).unwrap_or_else(|| settings.clone());
            // The live "Premium chart only" switch AND the live run-in routing
            // (Indices / F&O stocks / Commodities) must win over a direction
            // template, so a template can never silently turn the
            // bullish-filter-only rule back off (or on) for a category.
            gate_settings.premium_only = settings.premium_only;
            gate_settings.run_index = settings.run_index.clone();
            gate_settings.run_fno = settings.run_fno.clone();
            gate_settings.run_comm = settings.run_comm.clone();
            // "Require condition" must win over a direction template too, so a
            // template can never silently switch the strict condition gate off.
            gate_settings.require_condition = settings.require_condition;
            for (s, c) in &eval {
                // One memo scope per leg: conditions, indicator gate and
                // fresh-meet all read the same candle slice, so every shared
                // indicator is derived once instead of once per check. The scope
                // drops at the end of this iteration (no await inside), so it can
                // never outlive the borrowed candles.
                let _gate_scope = IndScope::enter();
                // "Flip Trigger": when ON it becomes the WHOLE entry rule - the
                // ordinary condition + indicator-filter gate is bypassed and only
                // the flip vote (share of straight-line / OI-Trend / Trend-Core
                // lines pointing this leg's way) decides the entry.
                let flip_on = gate_settings.flip_trigger_on;
                // Synthetic scanner instruments carry no entry conditions of their
                // own - the ticked indicator filters are the whole entry rule.
                let cond_ok = flip_on || synth || conditions_met(&s.conditions, c, offset);
                // Every tab (including Paper Trade 3) runs the same filter gate;
                // "Require condition" only controls whether the strategy's own
                // condition rule is mandatory, never the indicator gate.
                let fg = if flip_on {
                    flip_trigger_pass(&gate_settings, s, c, offset)
                } else {
                    filter_gate(&gate_settings, s, c, offset)
                };
                if !cond_ok || !fg {
                    if strat.synthetic {
                        let bull_s = premium_only_for(s, &gate_settings) || strategy_is_bull(s);
                            let keys: Vec<String> = gate_settings
                                .filters
                                .iter()
                                .filter(|(k, v)| {
                                    **v && !is_stream_flag(k)
                                        && (if bull_s { filter_is_bull(k) } else { filter_is_bear(k) })
                                })
                                .map(|(k, _)| k.clone())
                                .collect();
                        // Arrow filters are OR-ed into one trigger, so list them as a
                        // group instead of reporting each arrow as an individual fail.
                        let arrow_on = keys.iter().any(|k| is_arrow_flag(k));
                        let arrow_pass = arrow_on
                            && keys.iter().any(|k| {
                                is_arrow_flag(k) && filter_eval(k, c, offset).unwrap_or(false)
                            });
                        let failed: Vec<String> = keys
                            .iter()
                            .filter(|k| !is_arrow_flag(k) && filter_eval(k, c, offset) == Some(false))
                            .cloned()
                            .collect();
                        let gate_expl = filter_gate_explain(&gate_settings, s, c, offset);
                        self.note_blocker(
                            "info",
                            "gate",
                            &strat.name,
                            &format!("{} - indicator gate not satisfied: {gate_expl}", strat.name),
                        );
                        self.log_throttled(
                            &format!("gate:{}", strat.id),
                            60_000,
                            "info",
                            &format!("scan gate fail {}: cond={cond_ok} filter={fg} overallDir={} arrow=[{arrow_on}/{arrow_pass}] gate=[{gate_expl}] keys={keys:?} failed={failed:?}", strat.name, settings.overall_dir),
                        );
                    } else {
                        self.note_blocker(
                            "info",
                            "gate",
                            &strat.name,
                            &format!("{} - entry condition / indicator filter not met", strat.name),
                        );
                    }
                    all_pass = false;
                    break;
                }
            }
            // Per-strike premium gate. Every selected strike is analysed on its
            // OWN premium chart; the ones that pass become the fire set. This is
            // the premium-only equivalent of the spot gate above: instead of one
            // chart deciding for the whole ladder, each strike decides for itself.
            if !premium_strikes.is_empty() {
                for (s, c) in &premium_strikes {
                    let _gate_scope = IndScope::enter();
                    let flip_on = gate_settings.flip_trigger_on;
                    let cond_ok = flip_on || synth || conditions_met(&s.conditions, c, offset);
                    let fg = if flip_on {
                        flip_trigger_pass(&gate_settings, s, c, offset)
                    } else {
                        filter_gate(&gate_settings, s, c, offset)
                    };
                    if cond_ok && fg {
                        passing_strikes.push(s.clone());
                        self.log_throttled(
                            &format!("strike-pass:{}:{}", strat.id, s.security_id),
                            30_000,
                            "info",
                            &format!("premium strike PASS {} -> {}", strat.name, s.trading_symbol),
                        );
                    } else {
                        let gate_expl = filter_gate_explain(&gate_settings, s, c, offset);
                        self.log_throttled(
                            &format!("strike-fail:{}:{}", strat.id, s.security_id),
                            60_000,
                            "info",
                            &format!("premium strike FAIL {} -> {}: cond={cond_ok} filter={fg} gate=[{gate_expl}]", strat.name, s.trading_symbol),
                        );
                    }
                }
                if passing_strikes.is_empty() {
                    self.note_blocker(
                        "info",
                        "gate",
                        &strat.name,
                        &format!("{} - no selected strike passed the indicator filter on its own premium chart", strat.name),
                    );
                    all_pass = false;
                }
            }
            if !all_pass {
                if self.end_signal_if_due(&strat.id) {
                    self.clear_signal_edge(&strat.id);
                }
                if settings.entry_latch_on {
                    self.latch_note_gate_off(&strat.id, settings.entry_latch_secs);
                }
                continue;
            }
            // Spot forming-candle colour gate: a Top Gainer (bullish) leg may enter
            // only while the spot chart's live forming candle is GREEN, a Top Loser
            // (bearish) leg only while it is RED. The signal is HELD (not consumed)
            // while the candle is the wrong colour, so a still-met condition enters
            // as soon as the colour flips. Runs only when the entry rule is on the
            // spot chart and the checkbox is on.
            if let Some(reason) = self.spot_candle_gate_skip(&settings, &strat).await {
                self.note_blocker("info", "spot-candle", &strat.name, &format!("{} - {reason}", strat.name));
                self.log_throttled(
                    &format!("candlegate:{}", strat.id),
                    10_000,
                    "info",
                    &format!("skip entry {}: {reason}", strat.name),
                );
                if self.end_signal_if_due(&strat.id) {
                    self.clear_signal_edge(&strat.id);
                }
                if settings.entry_latch_on {
                    self.latch_note_gate_off(&strat.id, settings.entry_latch_secs);
                }
                continue;
            }
            // Trend check before entry: after the filter condition is met, the
            // underlying spot chart's current trend must agree with the leg's
            // side (bullish for a CE, bearish for a PE). A sideways / opposite
            // tape skips the entry; the signal is HELD so a later scan can enter
            // once the trend lines up. Pure pre-order filter - independent of
            // whether any trend-following master is switched ON.
            if let Some(reason) = self.entry_trend_check_skip(&settings, &strat).await {
                self.note_blocker("info", "entry-trend", &strat.name, &format!("{} - {reason}", strat.name));
                self.log_throttled(
                    &format!("entrytrend:{}", strat.id),
                    10_000,
                    "info",
                    &format!("skip entry {}: {reason}", strat.name),
                );
                if self.end_signal_if_due(&strat.id) {
                    self.clear_signal_edge(&strat.id);
                }
                if settings.entry_latch_on {
                    self.latch_note_gate_off(&strat.id, settings.entry_latch_secs);
                }
                continue;
            }
            // Multi-TF confirm: the higher ticked timeframe must also satisfy the
            // same gate (old `evalEntryMtfLive` trend leg) before the entry fires.
            if let Some((_, trend_tf)) = &mtf_tfs {
                for (s, _) in &eval {
                    let tc = match self
                        .live_candles(s.security_id, &s.exchange_segment, &s.instrument, trend_tf)
                        .await
                    {
                        Ok(c) if c.len() >= 3 => c,
                        _ => {
                            all_pass = false;
                            break;
                        }
                    };
                    if !(synth || conditions_met(&s.conditions, &tc, offset))
                        || !filter_gate(&gate_settings, s, &tc, offset)
                    {
                        all_pass = false;
                        break;
                    }
                }
                if !all_pass {
                    self.note_blocker(
                        "info",
                        "mtf",
                        &strat.name,
                        &format!("{} - higher-timeframe confirmation did not agree", strat.name),
                    );
                    if self.end_signal_if_due(&strat.id) {
                        self.clear_signal_edge(&strat.id);
                    }
                    if settings.entry_latch_on {
                        self.latch_note_gate_off(&strat.id, settings.entry_latch_secs);
                    }
                    continue;
                }
            }
            // The whole gate (spot + premium + multi-TF) held on this scan: the
            // signal is still running, so cancel any pending signal-end debounce.
            self.note_signal_pass(&strat.id);
            if settings.entry_latch_on {
                self.latch_note_gate_on(&strat.id);
            }
            // Multi-position entry gate (replaces the old single-position rule).
            // Always-on stacks a position every scan while the gate holds; fresh
            // fires ONE position per new bar (bar bucket change) while the gate
            // holds, so a long-running signal keeps entering on each fresh bar
            // without stacking on every 100ms tick. Concurrent positions are
            // unlimited; the orders/sec cap below still bounds the fill rate. With
            // both toggles off the legacy "one open position per strategy" applies.
            let entry_allowed = if settings.multi_always_on {
                true
            } else if settings.multi_fresh_on {
                self.signal_bar_is_fresh(&strat.id, &strat.timeframe, now)
            } else {
                running == 0
            };
            if !entry_allowed {
                self.note_blocker(
                    "info",
                    "already-running",
                    &strat.name,
                    &format!("{} - a position is already running (legacy one-position rule)", strat.name),
                );
                continue;
            }
            // Rate-limit drop latch: this strategy's CURRENT signal was dropped
            // because the orders/sec window was saturated. It must not be held
            // and retried on the next scan tick (that is exactly the late,
            // chased fill we are removing). Skip until the signal resets, when
            // `clear_signal_edge` releases the latch so a fresh signal is allowed.
            if self.rl_skip_active(&strat.id) {
                self.note_blocker(
                    "info",
                    "orders-per-sec",
                    &strat.name,
                    &format!("{} - orders/sec window was full, signal dropped (not retried until it re-arms)", strat.name),
                );
                self.log_throttled(
                    &format!("rldrop:{}", strat.id),
                    10_000,
                    "info",
                    &format!("skip {} (orders/sec window full: signal dropped, not held)", strat.name),
                );
                continue;
            }
            // "Repeat-entry latch": a still-true signal cannot re-enter until the
            // gate has turned OFF (and stayed OFF for `entry_latch_secs`). Layered
            // on top of the multi-position modes, so it works for every tab.
            if settings.entry_latch_on && !self.entry_latch_allows(&strat.id) {
                self.note_blocker(
                    "info",
                    "latch",
                    &strat.name,
                    &format!("{} - repeat-entry latch: signal has not re-armed yet (wait {}s of gate OFF)", strat.name, settings.entry_latch_secs),
                );
                self.log_throttled(
                    &format!("latch:{}", strat.id),
                    10_000,
                    "info",
                    &format!("skip repeat entry {} (latch: signal not re-armed)", strat.name),
                );
                continue;
            }
            // "Re-entry cooldown": block a new entry while inside the window that
            // started when this strategy's last position closed.
            if settings.entry_cooldown_on && self.entry_cooldown_active(&strat.id) {
                self.note_blocker(
                    "info",
                    "cooldown",
                    &strat.name,
                    &format!("{} - re-entry cooldown active after its last exit", strat.name),
                );
                self.log_throttled(
                    &format!("cooldown:{}", strat.id),
                    10_000,
                    "info",
                    &format!("skip entry {} (re-entry cooldown active)", strat.name),
                );
                continue;
            }
            // Consume this bar's fresh signal the moment an entry is allowed, so a
            // still-true gate cannot stack a second position inside the same bar.
            if settings.multi_fresh_on && !settings.multi_always_on {
                self.mark_signal_bar(&strat.id, &strat.timeframe, now);
            }
            // "Trade should be executed in": spot keeps the strategy's own
            // tradeable instrument; anything else executes the resolved option
            // premium leg. Index+spot has no directly tradeable spot, so it
            // falls through to the premium leg (same as the old engine).
            let trade_mode = trade_mode_of(&strat, &settings);
            let premium_leg = eval
                .iter()
                .rev()
                .find(|(s, _)| s.instrument.eq_ignore_ascii_case("OPTIDX") || s.exchange_segment.eq_ignore_ascii_case("NSE_FNO"))
                .map(|(s, _)| s.clone());
            // The strike ladder this signal fires on. When the selected strike
            // ladder was analysed per-strike on the premium charts, the fire set
            // is EXACTLY the strikes that passed their own gate - a failing strike
            // is never carried along by a passing sibling.
            let exec_legs: Vec<Strategy> = if !passing_strikes.is_empty() {
                passing_strikes.clone()
            } else if trade_mode == "spot" && strat_category(&strat) != StratCat::Index {
                vec![strat.clone()]
            } else if let Some(p) = premium_leg {
                vec![p]
            } else {
                // Run mode evaluated only the spot chart, but execution targets the
                // option premium: resolve the contract now. The old engine resolves
                // the execution leg regardless of which chart the entry rule ran on;
                // trading the raw spot would book F&O-sized quantity at full notional
                // and trip the margin gate.
                let mut spot = self.ltp_of(strat.security_id, &strat.exchange_segment);
                if spot <= 0.0 {
                    // Make sure the underlying is streaming, then give the feed a
                    // short bounded window to print its first tick (paper never
                    // pays a REST quote for it).
                    self.dhan
                        .subscribe_options(&[(strat.security_id, strat.exchange_segment.clone())])
                        .await;
                    spot = self.wait_feed_ltp(strat.security_id, &strat.exchange_segment, 800).await;
                }
                if spot <= 0.0 && !self.paper && !self.dhan.rate_limited() {
                    spot = self.fetch_ltp(strat.security_id, &strat.exchange_segment).await;
                }
                // Resolve the execution contracts from the operator's strike
                // preferences (ATM / ITM / OTM / strike mode + Number of Strikes).
                let side = self.desired_option_side(&settings, &strat);
                let legs = if self.no_premium_cached(strat.security_id, &side) {
                    Vec::new()
                } else {
                    let legs = self.resolve_option_strategies(&strat, spot, &settings, false, false);
                    if legs.is_empty() {
                        self.mark_no_premium(strat.security_id, &side);
                    } else {
                        self.clear_no_premium(strat.security_id, &side);
                    }
                    legs
                };
                if legs.is_empty() {
                    self.note_blocker(
                        "warn",
                        "no-premium",
                        &strat.name,
                        &format!("{} - no {side} option premium resolved for execution (strike/expiry unavailable or all strikes red)", strat.name),
                    );
                    self.log_throttled(
                        &format!("no-premium:{}:{side}", strat.id),
                        60_000,
                        "warn",
                        &format!("No {side} option premium for {} - skipping execution", strat.name),
                    );
                    continue;
                }
                legs
            };
            // Per-strike pre-filters: publish the executing leg, drop any strike
            // whose exact contract is already running, keep a paper leg streaming,
            // and honour "skip when margin unavailable" for every strike.
            let mut ready: Vec<Strategy> = Vec::with_capacity(exec_legs.len());
            for leg in &exec_legs {
                // Publish the chart the order will actually execute on, mirroring
                // the run leg above, so the Running Strategies view names both.
                self.record_strat_leg(&strat.id, "trade", leg);
                // Same-strike guard: skip the entry when this exact option contract
                // already has a running position. This catches a second strategy
                // resolving to the same strike and a scan after a restart (which
                // clears the in-memory signal edge). It is exempt for the operator's
                // explicit "repeat while condition holds" stacking mode.
                if self.duplicate_entry_blocked(&settings, leg.security_id, true) {
                    self.note_blocker(
                        "info",
                        "duplicate",
                        &strat.name,
                        &format!("{} -> {} - same strike already has a running position", strat.name, leg.trading_symbol),
                    );
                    self.log_throttled(
                        &format!("dupe:{}", strat.id),
                        10_000,
                        "info",
                        &format!(
                            "skip duplicate entry {} -> {} (same strike already running)",
                            strat.name, leg.trading_symbol
                        ),
                    );
                    continue;
                }
                // Paper execution is fully REST-free, so make sure the leg it will
                // trade is streaming on the live websocket before the fill is booked.
                if self.paper {
                    self.dhan
                        .subscribe_options(&[(leg.security_id, leg.exchange_segment.clone())])
                        .await;
                }
                // "One side per underlying": never hold a bullish and a bearish
                // exposure on the same underlying at once. When the opposite side
                // is already running this entry is blocked (the running leg exits
                // on its own plan); we never force-close it to flip, which only
                // booked SIDE_FLIP losses and churned.
                match self
                    .enforce_one_side_per_underlying(&settings, leg, &leg.side)
                    .await
                {
                    Ok(None) => {}
                    Ok(Some(reason)) => {
                        self.note_blocker("info", "side-flip", &strat.name, &format!("{reason}"));
                        self.log_throttled(
                            &format!("sideflip:{}", strat.id),
                            10_000,
                            "info",
                            &format!("skip entry {} -> {}: {reason}", strat.name, leg.trading_symbol),
                        );
                        continue;
                    }
                    Err(reason) => {
                        self.note_blocker("warn", "side-flip", &strat.name, &format!("{reason}"));
                        self.log_throttled(
                            &format!("sideflip:{}", strat.id),
                            10_000,
                            "warn",
                            &format!("skip entry {} -> {}: {reason}", strat.name, leg.trading_symbol),
                        );
                        continue;
                    }
                }
                // "Skip when margin unavailable": decide BEFORE the signal is queued.
                // The margin gate is pure in-memory arithmetic (microseconds), so when
                // the leg's required margin already exceeds the free budget the signal
                // is consumed here - it is never queued/retried, so it can never fill
                // minutes later at a worse price once margin frees. A genuinely new
                // signal after the pulse ends is still allowed.
                if settings.skip_on_margin_block {
                    let leg_ltp = self.ltp_of(leg.security_id, &leg.exchange_segment);
                    if leg_ltp > 0.0 {
                        if let Some(reason) = self.early_margin_skip_reason(leg, leg_ltp) {
                            self.consume_signal_for_margin(&strat.id);
                            self.note_blocker(
                                "warn",
                                "margin",
                                &strat.name,
                                &format!("{} -> {}: {reason}", strat.name, leg.trading_symbol),
                            );
                            self.log_throttled(
                                &format!("marginskip:{}", strat.id),
                                10_000,
                                "warn",
                                &format!(
                                    "skip (margin unavailable, no late entry) {} -> {}: {}",
                                    strat.name, leg.trading_symbol, reason
                                ),
                            );
                            continue;
                        }
                    }
                }
                ready.push(leg.clone());
            }
            if ready.is_empty() {
                continue;
            }
            // Trades per strategy: hard cap counted across open + closed entries.
            // "AI auto trades" removes the cap when enabled. Checked once per
            // signal, not once per strike.
            if !trade_limit_allows(trade_limit, ai_trades, trade_limit_count, self.trades_done(&strat.id)) {
                self.note_blocker(
                    "warn",
                    "trade-limit",
                    &strat.name,
                    &format!(
                        "{} - Max trades per strategy reached ({} of {})",
                        strat.name,
                        self.trades_done(&strat.id),
                        trade_limit_count
                    ),
                );
                continue;
            }
            if let Ok(mut m) = self.last_sig.lock() {
                m.insert(strat.id.clone(), now);
            }
            // Entry-timing diagnostics: stamp the moment the full filter set
            // first held so the eventual fill delay can be reported.
            if let Ok(mut m) = self.et_pending.lock() {
                m.entry(strat.id.clone())
                    .or_insert((now, self.et_placed.load(Ordering::Relaxed)));
            }
            // Paper-only latency simulation: when the operator turns on the
            // execution-delay checkbox, a fresh signal is not filled on this
            // tick. It is queued and placed `paperExecDelayMs` later using the
            // live LTP at that moment - exactly the extra lag the real tab sees
            // between a condition firing and the Dhan order landing. Off this
            // branch is skipped entirely, so the real tab and a paper tab with
            // the box unticked keep behaving identically.
            if self.paper && settings.paper_exec_delay_on && settings.paper_exec_delay_ms > 0.0 {
                self.set_sig_state(&strat.id, true);
                if settings.entry_latch_on {
                    self.latch_disarm(&strat.id);
                }
                // Every selected strike is queued under its own key so the whole
                // ladder fills together after the same delay (the queue de-dupes
                // by key, so a shared id would drop all but the first strike).
                for (k, leg) in ready.iter().enumerate() {
                    let key = if ready.len() == 1 {
                        strat.id.clone()
                    } else {
                        format!("{}::{}", strat.id, k)
                    };
                    self.queue_delayed_entry(&key, leg, settings.paper_exec_delay_ms);
                }
                continue;
            }
            self.set_sig_state(&strat.id, true);
            if settings.entry_latch_on {
                self.latch_disarm(&strat.id);
            }
            // Fire every selected strike on its OWN task in this same pass, so the
            // whole strike ladder places together instead of one strike at a time.
            // The per-strike entry latency (option resolve + first feed tick +
            // margin REST) can never serialise the rest.
            for leg in ready {
                // Orders/sec cap (shared across the three tabs of this group):
                // never send more than the configured number of orders in any
                // trailing one-second window. A saturated window DROPS this entry
                // instead of holding it - latch the signal so it is skipped (not
                // retried) until the gate resets, so it can never fill seconds
                // later at a chased price.
                if !order_rate::has_room(group) {
                    self.mark_rl_skip(&strat.id);
                    self.note_blocker(
                        "info",
                        "orders-per-sec",
                        &strat.name,
                        &format!(
                            "{} -> {} - orders/sec cap {} reached, entry dropped (not held)",
                            strat.name, leg.trading_symbol, order_per_sec
                        ),
                    );
                    self.log_throttled(
                        &format!("rlskip:{}", strat.id),
                        10_000,
                        "info",
                        &format!(
                            "drop entry {} -> {} (orders/sec cap {} reached; not held)",
                            strat.name, leg.trading_symbol, order_per_sec
                        ),
                    );
                    break;
                }
                let me = self.clone();
                let sid = strat.id.clone();
                let synth = strat.synthetic;
                let skip_margin = settings.skip_on_margin_block;
                let latch_on = settings.entry_latch_on;
                let name = strat.name.clone();
                let trade_sym = leg.trading_symbol.clone();
                let trade_inst = leg.instrument.clone();
                tokio::spawn(async move {
                    let entry_result = me.open_entry(&leg, true, Some(sid.as_str())).await;
                    if !me.paper {
                        // Order accepted or rejected: refresh the shared broker
                        // book now instead of waiting for the 2s poller tick.
                        me.dhan.kick_positions();
                    }
                    match entry_result {
                        Ok(()) => {
                            if synth {
                                me.log_throttled(
                                    &format!("entry:{sid}"),
                                    5_000,
                                    "info",
                                    &format!("scan ENTRY ok {name} -> {trade_sym} [{trade_inst}]"),
                                );
                            }
                        }
                        Err(e) => {
                            if skip_margin && e.starts_with("trade blocked:") {
                                // Consume the signal so the still-true gate cannot
                                // re-fire every scan and fill late once margin frees.
                                me.consume_signal_for_margin(&sid);
                                me.note_blocker(
                                    "warn",
                                    "margin",
                                    &name,
                                    &format!("{name} -> {trade_sym}: {e}"),
                                );
                                me.log_throttled(
                                    &format!("marginskip:{sid}"),
                                    10_000,
                                    "warn",
                                    &format!("skip (margin unavailable, no late entry) {name} -> {trade_sym}: {e}"),
                                );
                            } else {
                                me.release_fresh_edge(&sid);
                                if latch_on {
                                    me.latch_rearm(&sid);
                                }
                                let code = classify_entry_error(&e);
                                me.note_blocker(
                                    "warn",
                                    code,
                                    &name,
                                    &format!("{name} -> {trade_sym}: {e}"),
                                );
                                me.log("error", &format!("entry {name} failed: {e}"));
                            }
                            if let Some(mut d) = me.doc() {
                                if let Some(s) = d.strategies.iter_mut().find(|s| s.id == sid) {
                                    s.last_error = e.clone();
                                }
                            }
                        }
                    }
                });
            }
        }
    }

    // -----------------------------------------------------------------------
    // Live Data Pool (AI Smart Trading readout)
    // -----------------------------------------------------------------------

    /// Per-strategy live readout: latest candle + each condition's indicator
    /// value and PASS/FAIL. Mirrors the old app's Data Pool so the operator sees
    /// exactly what the strategies are reading. Cached for a few seconds so the
    /// UI poll cannot starve the chart's Dhan candle budget.
    /// Live Data Pool readout. Always answers from cache (never blocks the UI
    /// poll on the throttled Dhan candle fetches a compute needs); a stale or
    /// forced read kicks a single background refresh whose result lands in the
    /// cache for the next poll.
    async fn pool_readout(&self, force: bool) -> Value {
        let now = now_ms();
        let (has_cache, at, cached) = self
            .pool_cache
            .lock()
            .map(|g| (g.1.is_object(), g.0, g.1.clone()))
            .unwrap_or((false, 0, Value::Null));
        let stale = !has_cache || now - at >= 3000;
        if (has_cache && stale) || force {
            if !self.pool_busy.swap(true, Ordering::AcqRel) {
                let me = self.clone();
                tokio::spawn(async move {
                    let v = me.pool_compute().await;
                    if let Ok(mut g) = me.pool_cache.lock() {
                        *g = (now_ms(), v);
                    }
                    me.pool_busy.store(false, Ordering::Release);
                });
            }
        }
        if has_cache {
            cached
        } else {
            json!({ "ok": true, "at": now, "loading": true, "rows": [], "scanner": [] })
        }
    }

    async fn pool_compute(&self) -> Value {
        let now = now_ms();
        let strategies = self.doc().map(|d| d.strategies.clone()).unwrap_or_default();
        let connected = self.dhan.is_connected().await;
        let mut rows: Vec<Value> = Vec::new();
        for strat in strategies {
            let mut row = json!({
                "id": strat.id,
                "name": strat.name,
                "timeframe": strat.timeframe,
                "securityId": strat.security_id,
                "exchangeSegment": strat.exchange_segment,
                "instrument": strat.instrument,
                "tradingSymbol": strat.trading_symbol,
                "side": strat.side,
                "enabled": strat.enabled,
            });
            if strat.security_id <= 0 || strat.conditions.is_empty() {
                row["readout"] = Value::Null;
                rows.push(row);
                continue;
            }
            if !connected {
                row["readout"] = json!({ "error": "not connected" });
                rows.push(row);
                continue;
            }
            match self
                .live_candles(strat.security_id, &strat.exchange_segment, &strat.instrument, &strat.timeframe)
                .await
            {
                Ok(c) if c.len() >= 2 => {
                    let offset = 0usize;
                    let (pass, conds) = condition_detail(&strat.conditions, &c, offset);
                    let idx = c.len().saturating_sub(1 + offset);
                    let bar = &c[idx];
                    row["readout"] = json!({
                        "candle": {
                            "t": bar.time, "open": bar.open, "high": bar.high,
                            "low": bar.low, "close": bar.close, "volume": bar.volume
                        },
                        "conditions": conds,
                        "pass": pass,
                        "offset": offset,
                    });
                }
                Ok(_) => row["readout"] = json!({ "error": "not enough candles" }),
                Err(e) => row["readout"] = json!({ "error": e.to_string() }),
            }
            rows.push(row);
        }
        // Scanner-resolved instruments (Top Movers / NIFTY trend-following): let
        // the operator see the exact option legs the engine will trade even when
        // no saved strategy targets them. Capped so the chart keeps its candle
        // budget; each row carries the latest live candle when connected.
        let picked = self
            .picked_strikes
            .lock()
            .map(|g| g.1.clone())
            .unwrap_or_default();
        let mut scanner: Vec<Value> = Vec::new();
        for p in picked.iter().take(12) {
            let sid = ji(p, "securityId");
            if sid <= 0 {
                continue;
            }
            let (symbol, seg, inst) = match crate::market::symbol_meta(sid) {
                Some((n, s, i)) => (n, s, i),
                None => (
                    js(p, "tradingSymbol"),
                    js(p, "segment"),
                    String::new(),
                ),
            };
            let mut row = json!({
                "securityId": sid,
                "tradingSymbol": if symbol.is_empty() { js(p, "tradingSymbol") } else { symbol },
                "underlying": js(p, "underlying"),
                "side": js(p, "side"),
                "source": js(p, "source"),
                "segment": if seg.is_empty() { js(p, "segment") } else { seg.clone() },
                "spot": jf(p, "spot"),
                "changePct": jf(p, "changePct"),
            });
            if connected {
                let inst = if inst.is_empty() { "OPTIDX".to_string() } else { inst };
                if let Ok(c) = self.live_candles(sid, &seg, &inst, "5min").await {
                    if let Some(bar) = c.last() {
                        row["candle"] = json!({
                            "t": bar.time, "open": bar.open, "high": bar.high,
                            "low": bar.low, "close": bar.close, "volume": bar.volume
                        });
                    }
                }
            }
            scanner.push(row);
        }
        let payload = json!({ "ok": true, "at": now, "rows": rows, "scanner": scanner });
        if let Ok(mut g) = self.pool_cache.lock() {
            *g = (now, payload.clone());
        }
        payload
    }

    // -----------------------------------------------------------------------
    // Position management
    // -----------------------------------------------------------------------

    /// Re-evaluate the SAME-SIDE indicator filters that armed a position.
    /// Returns `None` when the required candle series is unavailable (a cold feed
    /// must never force an exit), else `Some(true)` when the setup no longer
    /// holds. Each frozen key is OR-ed on the arrow group exactly like the entry
    /// gate so the two rules agree.
    async fn entry_filters_flipped(
        &self,
        id: &str,
        keys: &[String],
        is_buy: bool,
        gates: (ConsensusCfg, PivotTrendCfg, PivotTrendCfg),
    ) -> Option<bool> {
        let (sec, exch, inst, tf) = {
            let d = self.doc()?;
            let p = d.positions.iter().find(|p| js(p, "id") == id)?;
            (
                ji(p, "securityId"),
                js(p, "exchangeSegment"),
                js(p, "instrument"),
                {
                    let raw = js(p, "timeframe");
                    if raw.is_empty() {
                        d.settings
                            .nifty_tf
                            .clone()
                            .trim()
                            .to_string()
                    } else {
                        raw
                    }
                },
            )
        };
        if sec <= 0 {
            return None;
        }
        let candles = match self.live_candles(sec, &exch, &inst, &tf).await {
            Ok(c) if c.len() >= 3 => c,
            _ => return None,
        };
        let (cons, sup, res) = gates;
        let _scope = IndScope::enter();
        let offset = 0usize;
        let side_keys: Vec<&String> = keys
            .iter()
            .filter(|k| {
                if is_buy {
                    filter_is_bull(k)
                } else {
                    filter_is_bear(k)
                }
            })
            .collect();
        if side_keys.is_empty() {
            return None;
        }
        let arrow_keys: Vec<&&String> = side_keys.iter().filter(|k| is_arrow_flag(k)).collect();
        let normal_keys: Vec<&&String> = side_keys.iter().filter(|k| !is_arrow_flag(k)).collect();
        // Arrows are one OR-ed trigger group, matching the entry gate.
        let arrow_ok = arrow_keys.is_empty()
            || arrow_keys
                .iter()
                .any(|k| filter_eval_inner(k, &candles, offset, cons, sup, res).unwrap_or(false));
        if !arrow_ok {
            return Some(true);
        }
        // Ordinary filters must still pass; one failing means the setup is gone.
        let any_failed = normal_keys
            .iter()
            .any(|k| filter_eval_inner(k, &candles, offset, cons, sup, res) == Some(false));
        Some(any_failed)
    }

    async fn manage_positions(&self) {
        let ids: Vec<String> = {
            let Some(d) = self.doc() else { return };
            d.positions
                .iter()
                .filter(|p| !js(p, "status").eq_ignore_ascii_case("closing"))
                .map(|p| js(p, "id"))
                .collect()
        };
        for id in ids {
            let (
                side,
                entry,
                ltp,
                pos_sl,
                overall_sl,
                tp,
                trail,
                point_trail,
                mut peak_profit,
                points_from_pct,
                trail_switch_on,
                ai_trail_on,
                point_trail_on,
                mut net_peak,
                qty,
                instrument,
                trading_symbol,
                mut target_plan,
                target_auto_on,
                target_min_confidence,
                net_tp_on,
                net_tp_min,
                net_tp_giveback_pct,
                slip_bps,
                spread,
                net_deduct_charges,
                breakeven_done,
                partial_done,
                opened_at,
                pos_sl_raw,
                entry_regime,
                exit_policy_cfg,
                brain_regime_now,
                entry_filters,
                filter_flip_on,
                broker_trail_owned,
            ) = {
                let Some(d) = self.doc() else { return };
                let Some(p) = d.positions.iter().find(|p| js(p, "id") == id) else { continue };
                (
                    js(p, "side"),
                    jf(p, "fillPrice").max(jf(p, "entry")),
                    self.ltp_of(ji(p, "securityId"), &js(p, "exchangeSegment")),
                    jf(p, "sl"),
                    jf(p, "overallSl"),
                    jf(p, "tp"),
                    jf(p, "trail"),
                    jf(p, "pointTrail"),
                    jf(p, "peakProfit"),
                    d.settings.trail_points_from_pct,
                    d.settings.manual_trail_sl,
                    d.settings.ai_trail_tp,
                    d.settings.manual_point_trail_sl,
                    jf(p, "netPeak"),
                    jf(p, "filledQty").max(jf(p, "qty")),
                    js(p, "instrument"),
                    js(p, "tradingSymbol"),
                    p.get("targetPlan").cloned().unwrap_or(Value::Null),
                    d.settings.target_auto_on,
                    d.settings.target_min_confidence,
                    d.settings.net_tp_on,
                    d.settings.net_tp_min,
                    d.settings.net_tp_giveback_pct,
                    d.settings.paper_slippage_bps,
                    PaperSpread::from(&d.settings),
                    // Charges are a real cost on every engine: real Dhan trades
                    // settle them broker-side (so the ledger shows gross) but the
                    // Net TP decision must still deduct them.
                    !self.paper || d.settings.broker_charges,
                    jb(p, "breakevenDone"),
                    jb(p, "partialDone"),
                    ji(p, "openedAt"),
                    jf(p, "overallSl").max(jf(p, "sl")),
                    js(p, "entryRegime"),
                    (
                        d.settings.auto_trade_on && d.settings.exit_suite_on,
                        d.settings.exit_partial_frac,
                        d.settings.exit_partial_r,
                        d.settings.exit_breakeven_r,
                        d.settings.exit_time_stop_min,
                        d.settings.exit_on_regime_flip,
                    ),
                    d.settings.brain_regime.clone(),
                    jarr(p, "entryFilters")
                        .iter()
                        .filter_map(|v| v.as_str().map(|x| x.to_string()))
                        .collect::<Vec<String>>(),
                    d.settings.exit_suite_on && d.settings.auto_trade_on && d.settings.exit_on_filter_flip,
                    // A position whose routed broker runs a native trail keeps
                    // the trail broker-side only; the engine must not ratchet a
                    // second stop for the same trade.
                    broker_owns_position_trail(p),
                )
            };
            if ltp <= 0.0 {
                continue;
            }
            // Reflect the fresh LTP on the ledger.
            if let Some(mut d) = self.doc() {
                if let Some(p) = d.positions.iter_mut().find(|p| js(p, "id") == id) {
                    p["ltp"] = json!(ltp);
                }
            }
            // A plan can be missing because the cache was still warming at entry
            // or because auto-cut was enabled after the trade opened. Attach the
            // first matching fresh plan now and keep it frozen from then on; this
            // is also what makes enabling auto-cut cover the EXISTING open book.
            if target_plan.is_null() && target_auto_on && side.eq_ignore_ascii_case("BUY") {
                let exposure = option_exposure_dir(&side, &trading_symbol);
                let underlying = underlying_of(&trading_symbol, "");
                if exposure != 0 {
                    if let Some(plan) = crate::target::plan_for_underlying(&underlying) {
                        let dir = plan.get("direction").and_then(|v| v.as_i64()).unwrap_or(0);
                        let conf = plan.get("confidence").and_then(|v| v.as_f64()).unwrap_or(0.0);
                        let tsid = plan.get("securityId").and_then(|v| v.as_i64()).unwrap_or(0);
                        let tseg = plan.get("exchangeSegment").and_then(|v| v.as_str()).unwrap_or("");
                        let spot = if tsid > 0 { self.ltp_of(tsid, tseg) } else { 0.0 };
                        let econ = target_econ(
                            &plan,
                            &side,
                            &trading_symbol,
                            &instrument,
                            entry,
                            qty,
                            spot,
                            self.paper,
                            slip_bps,
                            spread,
                        );
                        if dir.abs() == 1
                            && dir as i32 == exposure
                            && conf >= target_min_confidence
                            && target_plan_gap_ok(&plan, exposure, spot)
                            && econ.get("ok").and_then(|v| v.as_bool()).unwrap_or(false)
                        {
                            if let Some(mut d) = self.doc() {
                                if let Some(p) = d.positions.iter_mut().find(|p| js(p, "id") == id) {
                                    p["targetPlan"] = plan.clone();
                                    p["targetEcon"] = econ;
                                }
                            }
                            target_plan = plan;
                        }
                    }
                }
            }
            let is_buy = side == "BUY";
            // The overall SL captured at entry is the immutable hard floor.
            let mut overall_sl = if overall_sl > 0.0 { overall_sl } else { pos_sl };

            // --- Brain exit suite (Auto Trading only) ------------------------
            // Runs before the ordinary SL / trail / target checks so a hard exit
            // (time stop, regime flip) wins the race, and a breakeven ratchet
            // tightens the hard floor for the checks that follow. Every rule is
            // opt-in: a 0 value disables it, so a book configured the old way is
            // untouched.
            let (ex_auto, ex_partial_frac, ex_partial_r, ex_be_r, ex_time_min, ex_regime_flip) =
                exit_policy_cfg;
            // Optional filter-flip exit: the entry-time same-side filters must
            // still hold. This is a separate opt-in from the main suite because
            // it needs a candle read per position and is the most trigger-happy
            // rule, so it is never mixed into the price-based suite accidentally.
            if filter_flip_on && !entry_filters.is_empty() {
                let gates = {
                    let s = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
                    (consensus_cfg(&s), support_trend_cfg(&s), resistance_trend_cfg(&s))
                };
                if let Some(flipped) = self
                    .entry_filters_flipped(&id, &entry_filters, is_buy, gates)
                    .await
                {
                    if flipped {
                        self.log(
                            "info",
                            &format!("brain exit {id}: FILTER_FLIP (entry filters no longer hold)"),
                        );
                        if let Err(e) = self.close_position(&id, "FILTER_FLIP", ltp).await {
                            self.log("error", &format!("brain filter-flip exit {id} failed: {e}"));
                        }
                        continue;
                    }
                }
            }
            if ex_auto {
                let risk_per_unit = (entry - pos_sl_raw).abs();
                let risk_per_unit = if risk_per_unit > 0.0 {
                    risk_per_unit
                } else {
                    entry * 0.01
                };
                let age_ms = now_ms() - opened_at;
                let regime_flipped = !entry_regime.is_empty()
                    && !brain_regime_now.is_empty()
                    && !entry_regime.eq_ignore_ascii_case(&brain_regime_now);
                let policy = crate::brain::ExitPolicy {
                    breakeven_r: ex_be_r,
                    partial_frac: ex_partial_frac,
                    partial_r: ex_partial_r,
                    time_stop_ms: (ex_time_min * 60_000.0) as i64,
                    exit_on_regime_flip: ex_regime_flip,
                };
                match crate::brain::evaluate_exit(
                    &policy,
                    is_buy,
                    entry,
                    ltp,
                    risk_per_unit,
                    age_ms,
                    regime_flipped,
                    partial_done,
                    breakeven_done,
                ) {
                    crate::brain::ExitAction::Exit(tag) => {
                        self.log(
                            "info",
                            &format!("brain exit {id}: {tag} (age {}m, R {:.2})", age_ms / 60_000, crate::brain::current_r(is_buy, entry, ltp, risk_per_unit)),
                        );
                        if let Err(e) = self.close_position(&id, tag, ltp).await {
                            self.log("error", &format!("brain exit {id} failed: {e}"));
                        }
                        continue;
                    }
                    crate::brain::ExitAction::MoveStop => {
                        // Ratchet the hard floor to entry: never widen it, only
                        // move it in the profitable direction.
                        let better = if is_buy { entry > overall_sl } else { overall_sl <= 0.0 || entry < overall_sl };
                        if better {
                            overall_sl = entry;
                        }
                        if let Some(mut d) = self.doc() {
                            if let Some(p) = d.positions.iter_mut().find(|p| js(p, "id") == id) {
                                if better {
                                    p["overallSl"] = json!(round2(entry));
                                    p["sl"] = json!(round2(entry));
                                }
                                p["breakevenDone"] = json!(true);
                            }
                        }
                    }
                    crate::brain::ExitAction::Partial => {
                        // A partial exit cancels the broker's protective Super
                        // Order legs before selling the slice, which would leave
                        // the remaining quantity UNPROTECTED until the next tick.
                        // On a real position that carries broker legs we therefore
                        // skip the partial and let the ordinary trail / target
                        // manage the whole size - never a naked remainder.
                        let has_broker_legs = !self.paper
                            && self
                                .doc()
                                .map(|d| {
                                    d.positions
                                        .iter()
                                        .find(|p| js(p, "id") == id)
                                        .map(|p| !jarr(p, "superOrders").is_empty())
                                        .unwrap_or(false)
                                })
                                .unwrap_or(false);
                        let qty_i = qty.round() as i64;
                        let part = ((qty * ex_partial_frac).round() as i64).clamp(0, qty_i.max(0));
                        // A partial must leave a live remainder; otherwise let the
                        // ordinary target / trail book the whole thing.
                        if part > 0 && part < qty_i && !has_broker_legs {
                            self.log(
                                "info",
                                &format!("brain partial {id}: {part}/{qty} at R {:.2}", crate::brain::current_r(is_buy, entry, ltp, risk_per_unit)),
                            );
                            if let Err(e) = self
                                .close_position_partial(&id, "PARTIAL", ltp, part)
                                .await
                            {
                                self.log("error", &format!("brain partial {id} failed: {e}"));
                            }
                            continue;
                        }
                    }
                    crate::brain::ExitAction::None => {}
                }
            }

            // Running per-unit profit peak (drives both trail mechanisms).
            let per_unit = if is_buy { ltp - entry } else { entry - ltp };
            if per_unit > peak_profit {
                peak_profit = per_unit;
            }
            let best = if is_buy {
                entry + peak_profit.max(0.0)
            } else {
                entry - peak_profit.max(0.0)
            };
            // Net Take-Profit: the same peak idea, but on the NET rupee P&L
            // (Dhan charges + expected exit slippage already deducted) instead
            // of the per-unit price move. It only arms once the net peak crosses
            // the operator's rupee floor; after that it gives back a fixed
            // percentage of that peak (25% by default) before exiting.
            let net_at = |px: f64| -> f64 {
                let exit_px = if slip_bps > 0.0 || spread.on {
                    spread.fill(px, !is_buy, slip_bps)
                } else {
                    px
                };
                let gross = if is_buy {
                    (exit_px - entry) * qty
                } else {
                    (entry - exit_px) * qty
                };
                if net_deduct_charges {
                    compute_charges_for_trade(
                        entry,
                        exit_px,
                        qty,
                        &side,
                        &instrument,
                        &trading_symbol,
                        gross,
                    )
                    .map(|c| c.net)
                    .unwrap_or(gross)
                } else {
                    gross
                }
            };
            let net_now = net_at(ltp);
            let net_best = net_at(best);
            if net_best > net_peak {
                net_peak = net_best;
            }
            // Trail SL is profit-armed, never entry-armed, and comes in two
            // flavours that BOTH run app-side:
            //   * percent -> a % of the RUNNING live profit.
            //   * points  -> a price jump behind the best price.
            // With "Pts = % (auto)" linked, the point jump is recomputed every
            // tick as the SAME % of the running profit, so the point stop is the
            // exact point equivalent of the percentage stop (they are equal at
            // every price, not just at entry). Unlinked, the operator's fixed
            // points value is used and the tighter stop wins.
            //
            // Live switches are AUTHORITATIVE. The stored per-position `trail`
            // and `pointTrail` are only the entry-time values; they must never
            // keep ratcheting a stop after the operator unticks the switch.
            // Checking the box OFF disables the app-side trail for EVERY open
            // position immediately, not just for trades opened afterwards.
            let (trail_pct_live, points_live) = live_trail_inputs(
                trail_switch_on,
                ai_trail_on,
                point_trail_on,
                points_from_pct,
                trail,
                point_trail,
                peak_profit,
            );
            // Native-trail positions are ratcheted by the broker's own OMS, so
            // the engine never computes a second app-side stop for them (one
            // position, one trail). `broker_trail_owned` freezes that decision at
            // entry from the routed brokers + method, so a later settings edit
            // cannot start a competing engine trail on a running trade.
            let (sl, trail_source) = if broker_trail_owned {
                (overall_sl, "")
            } else {
                active_trail_stop(is_buy, entry, peak_profit, trail_pct_live, points_live, overall_sl)
            };
            let sl_trailed = !trail_source.is_empty();
            if let Some(mut d) = self.doc() {
                if let Some(p) = d.positions.iter_mut().find(|p| js(p, "id") == id) {
                    p["best"] = json!(round2(best));
                    p["sl"] = json!(round2(sl));
                    p["slTrailed"] = json!(sl_trailed);
                    p["peakProfit"] = json!(round2(peak_profit));
                    p["netPeak"] = json!(round2(net_peak));
                    p["netNow"] = json!(round2(net_now));
                    // Live point distance actually used by the trail (the stored
                    // `pointTrail` stays the entry jump sent to the broker).
                    p["pointTrailLive"] = json!(round2(points_live));
                }
            }
            // All exits are attached to the position and checked exactly (never
            // on the rounded display price) on every market tick:
            //   * overall SL  -> immutable floor captured at entry
            //   * trail SL    -> percent of the running live profit
            //   * take profit -> fixed target
            let hit_overall = overall_sl > 0.0
                && ((is_buy && ltp <= overall_sl) || (!is_buy && ltp >= overall_sl));
            let hit_trail = sl_trailed
                && ((is_buy && ltp <= sl) || (!is_buy && ltp >= sl));
            let hit_tp = tp > 0.0 && ((is_buy && ltp >= tp) || (!is_buy && ltp <= tp));
            // Target Lab auto-exit: the frozen plan is expressed on the
            // UNDERLYING, so it is evaluated against the underlying's live price
            // (index spot / commodity future), never the option premium.
            let hit_trend_target = target_auto_on && {
                let pdir = target_plan.get("direction").and_then(|v| v.as_i64()).unwrap_or(0);
                let tgt = target_plan.get("target").and_then(|v| v.as_f64()).unwrap_or(0.0);
                let tsid = target_plan.get("securityId").and_then(|v| v.as_i64()).unwrap_or(0);
                let tseg = target_plan.get("exchangeSegment").and_then(|v| v.as_str()).unwrap_or("");
                let exp = target_plan.get("expiresAt").and_then(|v| v.as_i64()).unwrap_or(0);
                let exposure = option_exposure_dir(&side, &trading_symbol) as i64;
                // Buy-only: this exit applies to an actual BUY trade whose
                // underlying exposure matches the plan (BUY CE for a call plan,
                // BUY PE for a put plan). Sell/short legs are never auto-cut.
                if !is_buy || pdir.abs() != 1 || exposure != pdir || tgt <= 0.0 || tsid <= 0 {
                    false
                } else if exp > 0 && now_ms() > exp {
                    false
                } else {
                    let u = self.ltp_of(tsid, tseg);
                    let level_hit = u > 0.0 && if pdir > 0 { u >= tgt } else { u <= tgt };
                    if !level_hit {
                        false
                    } else {
                        // The underlying reached the target. ALWAYS close here: a
                        // target that is hit and then left open only reverses into
                        // the hard stop and turns a green trade red. If the option
                        // premium did not advance enough to cover charges the exit
                        // is booked at a small loss, never a naked reversal - the
                        // whole point of the Target Lab plan is that its target is
                        // the exit.
                        true
                    }
                }
            };
            let net_tp_floor = net_tp_floor(net_peak, net_tp_min, net_tp_giveback_pct);
            let hit_net_tp = net_tp_on && net_tp_floor.map(|f| net_now < f).unwrap_or(false);
            let reason = if hit_tp {
                "TARGET"
            } else if hit_trend_target {
                "TREND_TARGET"
            } else if hit_trail {
                trail_source
            } else if hit_net_tp {
                "NET_TP"
            } else if hit_overall {
                "STOP_LOSS"
            } else {
                ""
            };
            if !reason.is_empty() {
                // Paper books a stop exit at the level that triggered it, so the
                // cut lands exactly at the configured stop even when a single tick
                // gaps straight through it (booking the live mark would otherwise
                // realise the whole gap as extra loss). Real positions keep the
                // live mark; the broker's actual fill is reconciled separately.
                let exit_px = if self.paper {
                    match reason {
                        "STOP_LOSS" => overall_sl,
                        "TARGET" | "NET_TP" | "TREND_TARGET" => ltp,
                        _ => sl,
                    }
                } else {
                    ltp
                };
                // Paper-only exit latency: when enabled, the exit is not booked
                // on the triggering tick. It is queued and lands `paper_exit_delay_ms`
                // later at the SAME level it would have booked without the delay
                // (stop -> stop level, trail -> trail level, target -> target), so
                // the delay only postpones the cut and never re-prices it. (Re-pricing
                // to the live mark turned profit-locking trail exits into losses.)
                let (exit_delay_on, exit_delay_ms) = self
                    .doc()
                    .map(|d| (d.settings.paper_exit_delay_on, d.settings.paper_exit_delay_ms))
                    .unwrap_or((false, 0.0));
                if self.paper && exit_delay_on && exit_delay_ms > 0.0 {
                    self.queue_delayed_exit(&id, reason, exit_px, exit_delay_ms);
                    continue;
                }
                if let Err(e) = self.close_position(&id, reason, exit_px).await {
                    self.log("error", &format!("exit {id} failed: {e}"));
                }
                continue;
            }
        }
    }

    /// Reconcile broker-side Super Orders: if Dhan triggered a leg, book it.
    async fn reconcile_super(&self) {
        if self.paper {
            return;
        }
        let ids: Vec<String> = {
            let Some(d) = self.doc() else { return };
            d.positions
                .iter()
                .filter(|p| jb(p, "broker"))
                .flat_map(|p| jarr(p, "superOrders").into_iter().filter_map(|v| v.as_str().map(String::from)))
                .collect()
        };
        if ids.is_empty() {
            return;
        }
        let now = now_ms();
        if now - self.last_super.load(Ordering::Relaxed) < 1000 {
            return;
        }
        self.last_super.store(now, Ordering::Relaxed);
        let Some(client) = self.dhan.session_client().await else { return };
        self.dhan.dhan_order_read_throttle().await;
        let Ok(orders) = client.super_orders().await else { return };
        for o in orders {
            let oid = o.get("orderId").and_then(|v| v.as_str()).unwrap_or("").to_string();
            if oid.is_empty() || !ids.contains(&oid) {
                continue;
            }
            let status = o.get("orderStatus").and_then(|v| v.as_str()).unwrap_or("");
            let legs = o.get("legs").and_then(|v| v.as_array()).cloned().unwrap_or_default();
            let mut triggered: Option<(String, f64)> = None;
            for l in &legs {
                let ls = l.get("orderStatus").and_then(|v| v.as_str()).unwrap_or("");
                let leg = l.get("legName").and_then(|v| v.as_str()).unwrap_or("");
                if matches!(ls, "TRADED" | "COMPLETED") && leg != "ENTRY_LEG" {
                    let px = l.get("triggerPrice").and_then(|v| v.as_f64()).unwrap_or(0.0);
                    triggered = Some((leg.to_string(), px));
                }
            }
            let entry_done = legs.iter().any(|l| {
                l.get("legName").and_then(|v| v.as_str()) == Some("ENTRY_LEG")
                    && matches!(l.get("orderStatus").and_then(|v| v.as_str()), Some("TRADED") | Some("COMPLETED"))
            });
            // Find the position that owns this super order.
            let pid = self.doc().and_then(|d| {
                d.positions
                    .iter()
                    .find(|p| jarr(p, "superOrders").iter().any(|v| v.as_str() == Some(oid.as_str())))
                    .map(|p| js(p, "id"))
            });
            let Some(pid) = pid else { continue };
            if let Some((leg, px)) = triggered {
                self.log("info", &format!("super order {oid} leg {leg} triggered"));
                let ltp = if px > 0.0 { px } else { self.position_ltp(&pid) };
                // A broker STOP_LOSS_LEG fill above the entry floor (below it for
                // a SELL) means Dhan's point `trailingJump` had ratcheted the
                // stop; label that exit as a points Trail SL so the ledger shows
                // which mechanism closed the trade.
                let trail_hit = self
                    .doc()
                    .and_then(|d| {
                        d.positions.iter().find(|p| js(p, "id") == pid).map(|p| {
        let point = {
            let live = jf(p, "pointTrailLive");
            if live > 0.0 { live } else { jf(p, "pointTrail") }
        };
                            let floor = jf(p, "overallSl");
                            let is_buy = js(p, "side") == "BUY";
                            point > 0.0
                                && floor > 0.0
                                && if is_buy { ltp > floor + 1e-9 } else { ltp < floor - 1e-9 }
                        })
                    })
                    .unwrap_or(false);
                let reason = if leg == "TARGET_LEG" {
                    "TARGET"
                } else if trail_hit {
                    "TRAIL_SL_PTS"
                } else {
                    "STOP_LOSS"
                };
                let _ = self.close_position(&pid, reason, ltp).await;
            } else if entry_done {
                if let Some(mut d) = self.doc() {
                    if let Some(p) = d.positions.iter_mut().find(|p| js(p, "id") == pid) {
                        if jf(p, "fillPrice") <= 0.0 {
                            let avg = legs
                                .iter()
                                .find(|l| l.get("legName").and_then(|v| v.as_str()) == Some("ENTRY_LEG"))
                                .and_then(|l| l.get("averageTradedPrice").and_then(|v| v.as_f64()))
                                .unwrap_or(0.0);
                            if avg > 0.0 {
                                p["fillPrice"] = json!(avg);
                                p["entry"] = json!(avg);
                            }
                        }
                    }
                }
                self.dhan.kick_positions();
            } else if status.eq_ignore_ascii_case("CANCELLED") || status.eq_ignore_ascii_case("REJECTED") {
                self.log("warn", &format!("super order {oid} is {status}"));
                self.dhan.kick_positions();
            }
        }
    }

    /// Broker-confirmed fill reconciliation for normal / forever / slice orders
    /// and for closed-trade exit prices. Dhan's order book is the source of truth
    /// for `averageTradedPrice` + `filledQty`, so estimates are replaced as soon
    /// as the exchange reports a fill. Throttled so the 100ms loop does not hammer
    /// the order book.
    async fn reconcile_fills(&self) {
        if self.paper {
            return;
        }
        if !self.dhan.is_connected().await {
            return;
        }
        // Only bother when something is still an estimate.
        let (open_ids, exits): (Vec<String>, Vec<String>) = self
            .doc()
            .map(|d| {
                let open = d
                    .positions
                    .iter()
                    .filter(|p| !jb(p, "reconciled"))
                    .flat_map(|p| jarr(p, "orderIds").into_iter().filter_map(|v| v.as_str().map(String::from)))
                    .collect();
                let exits = d
                    .closed
                    .iter()
                    .filter(|c| jb(c, "exitPending"))
                    .flat_map(|c| jarr(c, "exitOrderIds").into_iter().filter_map(|v| v.as_str().map(String::from)))
                    .collect();
                (open, exits)
            })
            .unwrap_or_default();
        if open_ids.is_empty() && exits.is_empty() {
            return;
        }
        let now = now_ms();
        // 1s cadence: execution / rejection visibility without touching the
        // shared data slot used by quotes and candles.
        if now - self.last_fills.load(Ordering::Relaxed) < 1000 {
            return;
        }
        self.last_fills.store(now, Ordering::Relaxed);
        let Some(client) = self.dhan.session_client().await else { return };
        self.dhan.dhan_order_read_throttle().await;
        let Ok(book) = client.order_book().await else { return };
        let map: HashMap<String, (f64, i64, String)> = book
            .iter()
            .map(|o| {
                (
                    o.order_id.clone(),
                    (o.average_traded_price, o.filled_qty.max(0), o.order_status.to_uppercase()),
                )
            })
            .collect();
        let mut changed = false;
        let mut refresh_positions = false;
        if let Some(mut d) = self.doc() {
            for p in d.positions.iter_mut() {
                if jb(p, "reconciled") {
                    continue;
                }
                let ids = jarr(p, "orderIds");
                if ids.is_empty() {
                    continue;
                }
                let (mut filled, mut notional, mut terminal) = (0i64, 0f64, true);
                for id in &ids {
                    let Some(oid) = id.as_str() else { continue };
                    match map.get(oid) {
                        Some((avg, f, status)) if *f > 0 => {
                            filled += *f;
                            notional += avg * (*f as f64);
                            if status == "PENDING" || status == "OPEN" || status == "TRANSIT" || status == "PART_TRADED" {
                                terminal = false;
                            }
                        }
                        Some((_, _, status))
                            if !(status == "REJECTED" || status == "CANCELLED" || status == "EXPIRED") =>
                        {
                            terminal = false;
                        }
                        _ => {}
                    }
                }
                if filled > 0 {
                    let avg = round2(notional / filled as f64);
                    if avg > 0.0 {
                        p["fillPrice"] = json!(avg);
                        p["entry"] = json!(avg);
                    }
                    p["filledQty"] = json!(filled);
                    changed = true;
                }
                if terminal {
                    // Even a cancelled/rejected entry must refresh the shared
                    // broker book, otherwise the engine keeps a phantom row.
                    refresh_positions = true;
                }
                if terminal && filled >= ji(p, "qty") {
                    p["reconciled"] = json!(true);
                    changed = true;
                }
            }
            for c in d.closed.iter_mut() {
                if !jb(c, "exitPending") {
                    continue;
                }
                let ids = jarr(c, "exitOrderIds");
                let mut notional = 0f64;
                let mut filled = 0i64;
                let mut terminal = true;
                for id in &ids {
                    let Some(oid) = id.as_str() else { continue };
                    match map.get(oid) {
                        Some((avg, f, status)) if *f > 0 => {
                            notional += avg * (*f as f64);
                            filled += *f;
                            if status == "PENDING" || status == "OPEN" || status == "TRANSIT" || status == "PART_TRADED" {
                                terminal = false;
                            }
                        }
                        Some((_, _, status))
                            if !(status == "REJECTED" || status == "CANCELLED" || status == "EXPIRED") =>
                        {
                            terminal = false;
                        }
                        _ => {}
                    }
                }
                if filled > 0 {
                    let exit = round2(notional / filled as f64);
                    let qty = ji(c, "qty");
                    let entry = jf(c, "entry");
                    let pnl = if js(c, "side") == "BUY" {
                        (exit - entry) * qty as f64
                    } else {
                        (entry - exit) * qty as f64
                    };
                    c["exit"] = json!(exit);
                    c["pnl"] = json!(round2(pnl));
                    c["exitPending"] = json!(false);
                    changed = true;
                }
                if terminal {
                    refresh_positions = true;
                }
                if terminal && filled <= 0 {
                    c["exitPending"] = json!(false);
                    changed = true;
                }
            }
        }
        if changed {
            self.save();
        }
        if changed || refresh_positions {
            self.dhan.kick_positions();
        }
    }

    /// Post-reconnect broker resync.
    ///
    /// The durable engine book survives a Dhan socket/network drop, so a running
    /// trade's SL / trail / target keeps evaluating from memory and never loses
    /// its levels. What can drift while the feed is down is the *broker* side: the
    /// native Super-Order stop leg can fire, a manual trade can appear, an exit
    /// can be rejected, or a partial exit can settle. This pass runs once on every
    /// false -> true edge of "connected" / "feed streaming" and re-aligns the two
    /// books:
    ///   * book a trade the broker already closed (native SL leg / manual exit),
    ///   * align a trade whose broker qty is smaller (a partial exit while offline),
    ///   * adopt an untracked broker position so SL / trail protect it,
    ///   * re-adopt an exposure whose exit order never filled.
    /// It never overwrites the operator's SL / trail / target values, so after a
    /// reconnect a running trade's protection is exactly what it was before.
    async fn reconcile_reconnect(&self) {
        if self.paper {
            return;
        }
        // Fire only on the false -> true edge, so a fresh Connect and every
        // websocket recovery trigger exactly one resync.
        let conn = self.dhan.is_connected().await;
        let up = self.dhan.feed_up();
        let was_conn = self.was_conn.swap(conn, Ordering::Relaxed);
        let was_feed = self.was_feed.swap(up, Ordering::Relaxed);
        if !((conn && !was_conn) || (up && !was_feed)) {
            return;
        }
        // A flapping socket must not hammer Dhan's order / portfolio APIs.
        let now = now_ms();
        if now - self.last_reconnect.load(Ordering::Relaxed) < 5_000 {
            return;
        }
        self.last_reconnect.store(now, Ordering::Relaxed);

        let Some(client) = self.dhan.session_client().await else { return };
        self.dhan.dhan_order_read_throttle().await;
        let book = match client.order_book().await {
            Ok(b) => b,
            Err(_) => return,
        };
        self.dhan.dhan_acct_throttle().await;
        let rows = match client.positions().await {
            Ok(r) => r,
            Err(_) => return,
        };

        // Broker net signed qty + average entry per (security, segment).
        struct BrokerPos {
            net: i64,
            avg: f64,
            symbol: String,
        }
        let mut broker: HashMap<(i64, String), BrokerPos> = HashMap::new();
        for r in &rows {
            let sid = r.security_id.parse::<i64>().unwrap_or(0);
            if sid <= 0 || r.net_qty == 0 {
                continue;
            }
            let long = r.position_type.eq_ignore_ascii_case("LONG");
            let avg = if long { r.buy_avg } else { r.sell_avg };
            let avg = if avg > 0.0 { avg } else { r.cost_price };
            let key = (sid, r.exchange_segment.to_uppercase());
            let e = broker.entry(key).or_insert(BrokerPos {
                net: 0,
                avg,
                symbol: r.trading_symbol.clone(),
            });
            e.net += r.net_qty;
            if avg > 0.0 {
                e.avg = avg;
            }
            if e.symbol.is_empty() {
                e.symbol = r.trading_symbol.clone();
            }
        }

        // A filled order on the security in the position's exit direction is hard
        // evidence the broker closed (or partly closed) the trade while the feed
        // was down. Newest update_time wins.
        let exit_fill = |sid: i64, side: &str| -> Option<f64> {
            let want = if side == "BUY" { "SELL" } else { "BUY" };
            book.iter()
                .filter(|o| {
                    o.security_id == sid.to_string()
                        && o.transaction_type.eq_ignore_ascii_case(want)
                        && o.filled_qty > 0
                        && o.average_traded_price > 0.0
                })
                .max_by(|a, b| a.update_time.cmp(&b.update_time))
                .map(|o| o.average_traded_price)
        };

        let (positions, settings, method) = {
            let Some(d) = self.doc() else { return };
            (d.positions.clone(), d.settings.clone(), d.method.clone())
        };
        if positions.is_empty() && broker.is_empty() {
            return;
        }

        // 1. Book trades the broker already closed while we were blind.
        let mut skip: std::collections::HashSet<(i64, String)> = std::collections::HashSet::new();
        let mut to_close: Vec<(String, String, f64)> = Vec::new();
        for p in &positions {
            if js(p, "status").eq_ignore_ascii_case("closing") {
                continue;
            }
            let sid = ji(p, "securityId");
            if sid <= 0 {
                continue;
            }
            let key = (sid, js(p, "exchangeSegment").to_uppercase());
            if broker.get(&key).map(|b| b.net).unwrap_or(0) != 0 {
                continue;
            }
            // Too fresh to judge: the entry may still be in transit.
            let opened = ji(p, "openedAt");
            if opened > 0 && now - opened < 5_000 {
                skip.insert(key);
                continue;
            }
            let entry_filled = jb(p, "reconciled")
                || ji(p, "filledQty") > 0
                || jarr(p, "orderIds").iter().any(|id| {
                    id.as_str()
                        .map(|s| book.iter().any(|o| o.order_id == s && o.filled_qty > 0))
                        .unwrap_or(false)
                });
            if !entry_filled {
                skip.insert(key);
                continue;
            }
            let side = js(p, "side");
            let fill = exit_fill(sid, &side);
            if fill.is_none() && rows.is_empty() {
                // No exit order visible and the portfolio answered empty: could be
                // a flaky empty response. Never book a close on a hunch.
                self.log_throttled(
                    "rt-recon-ambiguous",
                    30_000,
                    "warn",
                    &format!(
                        "reconnect: {} not seen at the broker yet; keeping the trade and retrying",
                        js(p, "tradingSymbol")
                    ),
                );
                skip.insert(key);
                continue;
            }
            let px = fill.unwrap_or_else(|| {
                let l = self.ltp_of(sid, &js(p, "exchangeSegment"));
                if l > 0.0 { l } else { jf(p, "ltp") }
            });
            let px = if px > 0.0 { px } else { jf(p, "fillPrice").max(jf(p, "entry")) };
            let reason = if fill.is_some() { "SL_LEG_FILLED" } else { "BROKER_CLOSED" };
            to_close.push((js(p, "id"), reason.to_string(), px));
        }
        for (id, reason, px) in &to_close {
            if self.close_position_ex(id, reason, *px, Some(Vec::new()), None).await.is_ok() {
                self.log(
                    "warn",
                    &format!("reconnect: booked broker-side exit for {id} ({reason}) @ {px:.2}"),
                );
            }
        }

        // 2. Align engine qty when the broker shows a smaller same-side net (a
        //    partial exit while offline). A single engine leg is the normal case.
        let engine_net: HashMap<(i64, String), i64> = {
            let Some(d) = self.doc() else { return };
            let mut m: HashMap<(i64, String), i64> = HashMap::new();
            for p in &d.positions {
                if js(p, "status").eq_ignore_ascii_case("closing") {
                    continue;
                }
                let sid = ji(p, "securityId");
                if sid <= 0 {
                    continue;
                }
                let q = ji(p, "qty");
                let signed = if js(p, "side") == "BUY" { q } else { -q };
                *m.entry((sid, js(p, "exchangeSegment").to_uppercase())).or_insert(0) += signed;
            }
            m
        };
        for (key, b) in &broker {
            if skip.contains(key) {
                continue;
            }
            let e = engine_net.get(key).copied().unwrap_or(0);
            if e == 0 || (e > 0) != (b.net > 0) || b.net.abs() >= e.abs() {
                continue;
            }
            let ids: Vec<String> = {
                let Some(d) = self.doc() else { continue };
                d.positions
                    .iter()
                    .filter(|p| {
                        !js(p, "status").eq_ignore_ascii_case("closing")
                            && ji(p, "securityId") == key.0
                            && js(p, "exchangeSegment").eq_ignore_ascii_case(&key.1)
                    })
                    .map(|p| js(p, "id"))
                    .collect()
            };
            if ids.len() == 1 {
                let remain = b.net.abs();
                if let Some(mut d) = self.doc() {
                    if let Some(p) = d.positions.iter_mut().find(|p| js(p, "id") == ids[0]) {
                        p["qty"] = json!(remain);
                        let lot = jf(p, "lotSize");
                        if lot > 0.0 {
                            p["lots"] = json!((remain as f64 / lot).round());
                        }
                        p["mismatch"] = json!(true);
                    }
                }
                self.log(
                    "warn",
                    &format!(
                        "reconnect: broker shows a partial exit on security {}; engine qty aligned to the open {} so the exit cannot flip the position",
                        key.0, remain
                    ),
                );
                self.save();
            } else if ids.len() > 1 {
                skip.insert(key.clone());
                self.log_throttled(
                    "rt-recon-split",
                    30_000,
                    "warn",
                    &format!(
                        "reconnect: broker net {} differs from the engine book for security {}; please review manually",
                        b.net, key.0
                    ),
                );
            }
        }

        // 3. Adopt broker exposure the engine does not fully track so it is
        //    protected by the configured SL / trail instead of sitting naked.
        let covered: HashMap<(i64, String), i64> = {
            let Some(d) = self.doc() else { return };
            let mut m: HashMap<(i64, String), i64> = HashMap::new();
            for p in &d.positions {
                if js(p, "status").eq_ignore_ascii_case("closing") {
                    continue;
                }
                let sid = ji(p, "securityId");
                if sid <= 0 {
                    continue;
                }
                let q = ji(p, "qty");
                let signed = if js(p, "side") == "BUY" { q } else { -q };
                *m.entry((sid, js(p, "exchangeSegment").to_uppercase())).or_insert(0) += signed;
            }
            m
        };
        let mut adopted: Vec<Value> = Vec::new();
        let mut adopted_keys: Vec<(i64, String, bool)> = Vec::new();
        for (key, b) in &broker {
            if skip.contains(key) {
                continue;
            }
            let e = covered.get(key).copied().unwrap_or(0);
            let delta = reconnect_delta(e, b.net);
            if delta == 0 {
                continue;
            }
            let seg = key.1.clone();
            let avg = if b.avg > 0.0 { b.avg } else { self.ltp_of(key.0, &seg) };
            if avg <= 0.0 {
                self.log_throttled(
                    "rt-recon-noavg",
                    30_000,
                    "warn",
                    &format!("reconnect: no entry price for broker position {}; not adopting", key.0),
                );
                continue;
            }
            let side = if delta > 0 { "BUY" } else { "SELL" };
            let qty = delta.abs();
            let (sl, tp, trail, point_trail) =
                levels_for(&settings, &json!({}), side, avg, 0.0, 0.0, 0.0);
            let protected = sl > 0.0 || tp > 0.0 || trail > 0.0 || point_trail > 0.0;
            adopted.push(json!({
                "id": gen_id("rtadopt"),
                "strategyId": "recovered",
                "strategyName": "Recovered (broker)",
                "method": method,
                "securityId": key.0,
                "exchangeSegment": seg,
                "instrument": "",
                "tradingSymbol": b.symbol,
                "underlying": underlying_of(&b.symbol, &seg),
                "side": side,
                "qty": qty,
                "lots": 0.0,
                "lotSize": 0.0,
                "filledQty": qty,
                "entry": round2(avg),
                "fillPrice": round2(avg),
                "ltp": round2(avg),
                "sl": round2(sl),
                "overallSl": round2(sl),
                "tp": round2(tp),
                "trail": round2(trail),
                "pointTrail": round2(point_trail),
                "pointTrailBrokerOnly": false,
                // An adopted broker position carries no known broker trail, so the
                // engine owns the single stop for it.
                "trailOwner": "engine",
                "brokers": [],
            "peakProfit": 0.0,
            "netPeak": 0.0,
                "best": round2(avg),
                "orderIds": [],
                "superOrders": [],
                "broker": true,
                "reconciled": true,
                "adopted": true,
                "status": "running",
                "orderType": "MARKET",
                "limitPrice": 0.0,
                "openedAt": now,
                "log": [{ "t": now, "msg": "recovered from the broker after a reconnect" }],
            }));
            adopted_keys.push((key.0, key.1.clone(), protected));
        }
        if !adopted.is_empty() {
            let n = adopted.len();
            if let Some(mut d) = self.doc() {
                for p in adopted {
                    d.positions.push(p);
                }
            }
            for (sid, seg, protected) in &adopted_keys {
                self.dhan.subscribe_options(&[(*sid, seg.clone())]).await;
                if *protected {
                    self.log(
                        "warn",
                        &format!("reconnect: adopted broker position {} ({}) so SL / trail protect it", sid, seg),
                    );
                } else {
                    self.log(
                        "warn",
                        &format!(
                            "reconnect: adopted broker position {} ({}) but no SL / trail / target is configured - set one to protect it",
                            sid, seg
                        ),
                    );
                }
            }
            self.save();
            self.log("info", &format!("reconnect: broker resync adopted {n} position(s)"));
        }
    }

    fn position_ltp(&self, id: &str) -> f64 {
        let (sid, exch) = self
            .doc()
            .and_then(|d| d.positions.iter().find(|p| js(p, "id") == id).map(|p| (ji(p, "securityId"), js(p, "exchangeSegment"))))
            .unwrap_or((0, String::new()));
        self.ltp_of(sid, &exch)
    }

    // -----------------------------------------------------------------------
    // Entry / exit
    // -----------------------------------------------------------------------

    /// The CE/PE leg a strategy trades.
    ///
    /// The indicator filters wire to the charts by their own side: BULLISH
    /// indicator filters drive the CE call leg, BEARISH indicator filters the PE
    /// put leg. The leg is decided solely by the strategy's filter side - no
    /// Option Type dropdown, assigned leg, trend lock or other override.
    fn target_option_side(&self, strat: &Strategy, settings: &Settings) -> &'static str {
        let _ = settings;
        if strategy_is_bull(strat) {
            "CE"
        } else {
            "PE"
        }
    }

    /// Testing-only Manual Strike Select: when enabled and the operator has
    /// picked at least one contract for the strategy's underlying, return that
    /// contract instead of the automatic ATM / strike-mode resolution. Prefers a
    /// pick whose side matches `target_option_side` (nearest to spot when several
    /// exist) and falls back to the nearest pick of either side. Returns `None`
    /// when the mode is off, the list is empty, or no pick matches the strategy's
    /// underlying - callers then keep the normal resolution.
    fn resolve_manual_strike(&self, strat: &Strategy, spot: f64, settings: &Settings) -> Option<Strategy> {
        if !settings.manual_strikes_enabled || settings.manual_strikes.is_empty() {
            return None;
        }
        let sc = scrip::get()?;
        let prefix = scrip::fno_underlying(&strat.trading_symbol);
        if prefix.is_empty() {
            return None;
        }
        let want = self.target_option_side(strat, settings);
        let mut matching: Vec<&ManualStrike> = settings
            .manual_strikes
            .iter()
            .filter(|m| {
                m.strike > 0.0
                    && (m.option_type.eq_ignore_ascii_case("CE") || m.option_type.eq_ignore_ascii_case("PE"))
                    && scrip::fno_underlying(&m.symbol_name) == prefix
            })
            .collect();
        if matching.is_empty() {
            return None;
        }
        // Prefer the wanted side; if the operator only picked the other side, use
        // it anyway (manual mode is an explicit testing override, not a filter).
        let side_match: Vec<&ManualStrike> = matching
            .iter()
            .copied()
            .filter(|m| m.option_type.eq_ignore_ascii_case(want))
            .collect();
        if !side_match.is_empty() {
            matching = side_match;
        }
        let pick = if spot > 0.0 {
            matching
                .iter()
                .copied()
                .min_by(|a, b| {
                    (a.strike - spot)
                        .abs()
                        .partial_cmp(&(b.strike - spot).abs())
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
        } else {
            matching.first().copied()
        }?;
        let ot = pick.option_type.to_uppercase();
        let res = sc.resolve(&pick.symbol_name, &pick.expiry, pick.strike, &ot, &pick.exchange_segment)?;
        let exch = sc.fno_exch(&pick.exchange_segment, &prefix);
        let seg = fno_segment(exch);
        let mut out = strat.clone();
        out.security_id = res.security_id;
        out.exchange_segment = seg.to_string();
        out.instrument = if scrip::is_index_prefix(&prefix) {
            "OPTIDX"
        } else if exch.eq_ignore_ascii_case("MCX") || exch.eq_ignore_ascii_case("NCDEX") {
            "OPTFUT"
        } else {
            "OPTSTK"
        }
        .to_string();
        out.trading_symbol = res.trading_symbol;
        Some(out)
    }

    /// Whether the "+green / fastest positive rising" strike filter must be
    /// enforced for a resolution. It applies to every Leg Book build and to any
    /// entry whose operator has either preference switched ON, so a minus (red)
    /// strike is never silently booked on a saved strategy, NIFTY-trend,
    /// operator index or commodity. With both preferences OFF the operator's
    /// explicit Above/Below-ATM choice (or the nearest ATM leg) stands. Pure so
    /// the rule is trivially testable.
    fn enforce_green_filter(for_build: bool, settings: &Settings) -> bool {
        for_build || settings.only_positive || settings.fastest_rising
    }

    /// Resolve an index/underlying strategy into a concrete option contract:
    /// nearest expiry, ATM/ITM/OTM strike from the scrip master, CE for bullish
    /// (or BUY) and PE for bearish (or SELL). Mirrors the old engine's option
    /// selection. Returns `None` when the scrip master cannot resolve it.
    fn resolve_option_strategy(&self, strat: &Strategy, spot: f64, settings: &Settings, provisional: bool, for_build: bool) -> Option<Strategy> {
        let sc = scrip::get()?;
        // Manual Strike Select (testing) wins over every automatic preference.
        if let Some(m) = self.resolve_manual_strike(strat, spot, settings) {
            return Some(m);
        }
        if spot <= 0.0 {
            return None;
        }
        let prefix = scrip::fno_underlying(&strat.trading_symbol);
        if prefix.is_empty() {
            return None;
        }
        let exch = sc.fno_exch(&strat.exchange_segment, &prefix);
        let expiries = sc.expiries_for(&prefix, exch)?;
        // Paper Trade 2's indices / commodities must trade the SAME expiry and
        // strikes the option-chain screen shows. The engine previously always took
        // the local scrip master's nearest series, which can differ from the
        // broker's authoritative chain expiry - so the resolved strikes were not
        // in the displayed chain at all. Align to the chain's own ladder here.
        let expiry = if self.indices_commodities_only() {
            let chain = crate::optionchain::chain_expiries(
                strat.security_id,
                &strat.exchange_segment,
                &strat.trading_symbol,
            );
            let usable = chain.into_iter().find(|e| {
                !e.is_empty()
                    && sc
                        .bucket(exch, &prefix, e)
                        .map(|b| !b.is_empty())
                        .unwrap_or(false)
            });
            usable.or_else(|| expiries.first().cloned())?
        } else {
            expiries.first()?.clone()
        };
        let bucket = sc.bucket(exch, &prefix, &expiry)?;
        if bucket.is_empty() {
            return None;
        }
        let all_strikes: Vec<f64> = bucket.keys().map(|k| *k as f64 / 100.0).collect();
        let mut full_idx = 0usize;
        let mut best = f64::MAX;
        for (i, s) in all_strikes.iter().enumerate() {
            let d = (s - spot).abs();
            if d < best {
                best = d;
                full_idx = i;
            }
        }
        // Restrict Paper Trade 2's candidate ladder to the exact ATM +/- window
        // the option-chain screen renders, so a strike the engine picks is always
        // a strike present in the chain (never an off-window strike).
        let (strikes, idx) = if self.indices_commodities_only() && !for_build {
            let w = crate::optionchain::OPTION_CHAIN_WINDOW;
            let lo = full_idx.saturating_sub(w);
            let hi = (full_idx + w + 1).min(all_strikes.len());
            let sub = all_strikes[lo..hi].to_vec();
            (sub, full_idx - lo)
        } else {
            (all_strikes, full_idx)
        };
        let ot = self.target_option_side(strat, settings);
        // Picked-Strike wiring: the Leg Book freezes the strike each Top-Movers
        // underlying trades (the +green / fastest rising CE pick for a Top Gainer,
        // the PE pick for a Top Loser). While the book is live an F&O stock leg is
        // resolved ONLY from that pick, so the indicator filters never fall through
        // to a nearby ATM strike: a BULLISH (CE) filter leg comes only from a Top
        // Gainer's picked CE strike and a BEARISH (PE) filter leg only from a Top
        // Loser's picked PE strike. With no pick for the underlying / side the
        // entry is held (`None`). Indices, commodities and the manual override are
        // never book-bound. The builder is the only caller passing `for_build`.
        if !for_build {
            if let Some(mut frozen) = self.book_leg_for(strat.security_id, &expiry, ot, settings) {
                // The frozen contract is resolved from a generic `underlying_base`
                // leg, so carry the caller's Liquid F&O marker onto it - otherwise
                // a liquid entry sourced from the Leg Book would lose its dedicated
                // Auto-Lot / slicing config.
                frozen.liquid_leg = strat.liquid_leg;
                return Some(frozen);
            }
            if self.leg_book_active(settings) && strat_category(strat) == StratCat::Fno {
                return None;
            }
        }
        // Strike selection preference (the "Execute Trade In" dropdown supplies the
        // direction for all of them):
        //   * "Only +green premium strikes"  -> first rising (+green) strike.
        //   * "Pick fastest positive rising LTP" -> the biggest riser (max LTP
        //     change %) among the rising strikes; implies +green eligibility.
        //   * "Opposite side fallback" -> if the chosen side is entirely minus,
        //     retry the opposite side of ATM in the same leg.
        //
        // The +green / fastest filter is enforced EVERYWHERE, not only while
        // building a Top-Movers leg: saved strategies, NIFTY-trend and operator
        // indices / commodities all walk the chosen direction for a rising
        // premium too. When the whole side is minus the entry is BLOCKED (returns
        // `None`) rather than silently booking the nearest ATM strike, which is
        // exactly what let a minus (red) strike get picked. Only when both
        // preferences are OFF does the operator's explicit Above/Below-ATM
        // choice apply directly (Paper Trade 2) or the nearest ATM leg stand.
        let enforce_green = Self::enforce_green_filter(for_build, settings);
        let strike_idx = if enforce_green {
            match self.pick_strike_pref(strat, exch, &expiry, &strikes, idx, ot, settings, provisional, !self.indices_commodities_only()) {
                Some(i) => i,
                None => return None,
            }
        } else if self.indices_commodities_only() {
            self.direct_strike_index(strat, &expiry, &strikes, idx, ot, settings)?
        } else {
            idx
        };
        let strike = strikes[strike_idx];
        self.contract_for_strike(strat, &expiry, strike, &ot, &prefix, exch)
    }

    /// The +green strikes of `order` (a walk of strike indices for one leg),
    /// classified from the live quote cache under a single lock and returned in
    /// walk order as `(strike_index, published change %, published change)`.
    /// Only a genuinely rising premium (the option chain's own `+`) is kept, so a
    /// minus (red) strike never enters the fire set.
    fn green_strikes_in_order(
        &self,
        strat: &Strategy,
        expiry: &str,
        strikes: &[f64],
        ot: &str,
        order: &[usize],
    ) -> Vec<(usize, f64, f64)> {
        let Some(sc) = scrip::get() else { return Vec::new() };
        let prefix = scrip::fno_underlying(&strat.trading_symbol);
        let seg = fno_segment(sc.fno_exch(&strat.exchange_segment, &prefix));
        let mut cands: Vec<(usize, i64)> = Vec::with_capacity(order.len());
        for i in order {
            if let Some(r) = sc.resolve(&strat.trading_symbol, expiry, strikes[*i], ot, &strat.exchange_segment) {
                if r.security_id > 0 {
                    cands.push((*i, r.security_id));
                }
            }
        }
        let mut out: Vec<(usize, f64, f64)> = Vec::new();
        let Ok(q) = self.dhan.market.quotes.lock() else { return out };
        for (i, sid) in cands {
            let Some(v) = q.get(&crate::market::quote_key(sid, seg)) else { continue };
            let ltp = v.get("ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
            if ltp <= 0.0 {
                continue;
            }
            let change = v.get("change").and_then(|x| x.as_f64()).unwrap_or(0.0);
            let prev = v.get("prev_ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
            if !Self::premium_is_green(ltp, prev, change) {
                continue;
            }
            let pct = v.get("change_pct").and_then(|x| x.as_f64()).unwrap_or(0.0);
            out.push((i, pct, change));
        }
        out
    }

    /// Every strike a single spot-chart entry should fire on AT ONCE: the
    /// operator's "Number of Strikes" (`strike_count`) strikes of the SAME leg
    /// the single resolver already chose (CE for a bullish filter / Top Gainer,
    /// PE for a bearish filter / Top Loser - the assigned leg is never forced or
    /// flipped here), selected along the "Execute Trade In" direction from ATM
    /// (Above / Below / including ATM) and - when a +green / fastest-rising
    /// preference is on - only from the genuinely rising premiums. "Including
    /// ATM" modes add the ATM leg on top of Number of Strikes (Above incl. ATM +
    /// 1 = ATM and one above). Returns the single resolver's leg alone when
    /// "Number of Strikes" is unset (0) or the leg is manual, so every other
    /// behaviour is unchanged.
    fn resolve_option_strategies(
        &self,
        strat: &Strategy,
        spot: f64,
        settings: &Settings,
        provisional: bool,
        for_build: bool,
    ) -> Vec<Strategy> {
        let base = match self.resolve_option_strategy(strat, spot, settings, provisional, for_build) {
            Some(b) => b,
            None => return Vec::new(),
        };
        let n = settings.strike_count.max(0) as usize;
        if n == 0 || base.manual {
            return vec![base];
        }
        let Some(sc) = scrip::get() else { return vec![base] };
        if spot <= 0.0 || option_strike_type(&base.trading_symbol).is_none() {
            return vec![base];
        }
        let prefix = scrip::fno_underlying(&strat.trading_symbol);
        if prefix.is_empty() {
            return vec![base];
        }
        let exch = sc.fno_exch(&strat.exchange_segment, &prefix);
        let Some(expiries) = sc.expiries_for(&prefix, exch) else { return vec![base] };
        let Some(expiry) = expiries.first().cloned() else { return vec![base] };
        let Some(bucket) = sc.bucket(exch, &prefix, &expiry) else { return vec![base] };
        if bucket.is_empty() {
            return vec![base];
        }
        let all_strikes: Vec<f64> = bucket.keys().map(|k| *k as f64 / 100.0).collect();
        let mut full_idx = 0usize;
        let mut best = f64::MAX;
        for (i, s) in all_strikes.iter().enumerate() {
            let d = (s - spot).abs();
            if d < best {
                best = d;
                full_idx = i;
            }
        }
        let (strikes, idx) = if self.indices_commodities_only() && !for_build {
            let w = crate::optionchain::OPTION_CHAIN_WINDOW;
            let lo = full_idx.saturating_sub(w);
            let hi = (full_idx + w + 1).min(all_strikes.len());
            (all_strikes[lo..hi].to_vec(), full_idx - lo)
        } else {
            (all_strikes, full_idx)
        };
        let ot = self.target_option_side(strat, settings);
        let mode = Self::effective_green_walk_mode(&settings.strike_mode, !self.indices_commodities_only());
        let order = Self::chain_window_order(strikes.len(), idx, mode);
        if order.is_empty() {
            return vec![base];
        }
        // "Including ATM" modes count the ATM leg IN ADDITION to the operator's
        // Number of Strikes (Above incl. ATM + 1 => ATM and one strike above = 2
        // legs), while the strict Above / Below modes fire exactly Number of
        // Strikes.
        let including_atm = mode.eq_ignore_ascii_case("above_atm")
            || mode.eq_ignore_ascii_case("below_atm")
            || mode.eq_ignore_ascii_case("both_atm_inc")
            || mode.eq_ignore_ascii_case("atm");
        let want = if including_atm { n + 1 } else { n };
        let chosen_idx: Vec<usize> = if Self::enforce_green_filter(for_build, settings) {
            let mut greens = self.green_strikes_in_order(strat, &expiry, &strikes, &ot, &order);
            if greens.is_empty() {
                // No rising premium on the selected side at all: keep exactly what
                // the single resolver decided (which already applied the
                // opposite-side fallback / block).
                return vec![base];
            }
            if settings.fastest_rising {
                greens.sort_by(|a, b| {
                    if Self::rising_score_better((b.1, b.2), (a.1, a.2)) {
                        std::cmp::Ordering::Greater
                    } else if Self::rising_score_better((a.1, a.2), (b.1, b.2)) {
                        std::cmp::Ordering::Less
                    } else {
                        std::cmp::Ordering::Equal
                    }
                });
            }
            greens.into_iter().take(want).map(|(i, _, _)| i).collect()
        } else {
            // No +green preference: the operator's explicit Above/Below-ATM
            // selection decides. Mirror the single-pick step formula for every
            // step 1..=want so "Above including ATM, 1 strike" fires ATM and
            // ATM+1, and "Above including ATM, 3 strikes" fires ATM..ATM+3
            // (de-duplicated when the chain clamps at an edge or the mode is
            // ATM-only).
            let is_ce = ot.eq_ignore_ascii_case("CE");
            let mut idxs: Vec<usize> = Vec::with_capacity(want);
            for j in 1..=want as i64 {
                let i = Self::direct_mode_strike_idx(strikes.len(), idx, &settings.strike_mode, j, is_ce);
                if !idxs.contains(&i) {
                    idxs.push(i);
                }
            }
            idxs
        };
        if chosen_idx.is_empty() {
            return vec![base];
        }
        let mut out: Vec<Strategy> = Vec::with_capacity(want);
        for i in &chosen_idx {
            if let Some(c) = self.contract_for_strike(strat, &expiry, strikes[*i], &ot, &prefix, exch) {
                if !out.iter().any(|x| x.security_id == c.security_id) {
                    out.push(c);
                }
            }
        }
        // The single resolver's leg always leads the fire set even when the walk
        // landed elsewhere (e.g. a frozen leg-book pick), so nothing about the
        // existing "picked strike" behaviour changes.
        if !out.iter().any(|c| c.security_id == base.security_id) {
            out.insert(0, base.clone());
        }
        out.truncate(want);
        if out.is_empty() {
            vec![base]
        } else {
            out
        }
    }

    /// Build the concrete option contract for a resolved (expiry, strike, side):
    /// carries the base strategy's metadata and the Dhan instrument type the
    /// segment needs. Shared by the single-leg resolver and the ranked
    /// fastest-rising list so both name the same contract the same way.
    fn contract_for_strike(
        &self,
        strat: &Strategy,
        expiry: &str,
        strike: f64,
        ot: &str,
        prefix: &str,
        exch: &str,
    ) -> Option<Strategy> {
        let sc = scrip::get()?;
        let res = sc.resolve(&strat.trading_symbol, expiry, strike, ot, &strat.exchange_segment)?;
        let seg = fno_segment(exch);
        let mut out = strat.clone();
        out.security_id = res.security_id;
        out.exchange_segment = seg.to_string();
        // Dhan needs OPTIDX for index options, OPTSTK for stock options and
        // OPTFUT for MCX commodity options; the wrong type makes `/charts`
        // answer an empty payload (or one junk bar), so a commodity CE/PE leg
        // would never resolve.
        out.instrument = if scrip::is_index_prefix(prefix) {
            "OPTIDX"
        } else if exch.eq_ignore_ascii_case("MCX") {
            "OPTFUT"
        } else {
            "OPTSTK"
        }
        .to_string();
        out.trading_symbol = res.trading_symbol;
        Some(out)
    }

    /// The +green rising strikes of a side-pinned underlying's bound leg, ranked
    /// most-risen first by the published LTP change % (ties broken by the absolute
    /// LTP change), capped to the "Fastest-Rising Strikes" count. Only strikes
    /// whose live premium is genuinely +green are eligible, so a minus strike is
    /// never listed. The WHOLE option-chain window is scanned (both sides of ATM,
    /// same leg) in one pass, so a rising strike is found even when the "Execute
    /// Trade In" direction alone is wholly minus. Empty when the feed has no
    /// quoted +green strike yet.
    fn rising_strike_list(&self, strat: &Strategy, spot: f64, settings: &Settings) -> Vec<Strategy> {
        let Some(sc) = scrip::get() else { return Vec::new() };
        if spot <= 0.0 {
            return Vec::new();
        }
        let prefix = scrip::fno_underlying(&strat.trading_symbol);
        if prefix.is_empty() {
            return Vec::new();
        }
        let exch = sc.fno_exch(&strat.exchange_segment, &prefix);
        let Some(expiries) = sc.expiries_for(&prefix, exch) else { return Vec::new() };
        let Some(expiry) = expiries.first().cloned() else { return Vec::new() };
        let Some(bucket) = sc.bucket(exch, &prefix, &expiry) else { return Vec::new() };
        if bucket.is_empty() {
            return Vec::new();
        }
        let all_strikes: Vec<f64> = bucket.keys().map(|k| *k as f64 / 100.0).collect();
        let mut full_idx = 0usize;
        let mut best = f64::MAX;
        for (i, s) in all_strikes.iter().enumerate() {
            let d = (s - spot).abs();
            if d < best {
                best = d;
                full_idx = i;
            }
        }
        let w = crate::optionchain::OPTION_CHAIN_WINDOW;
        let lo = full_idx.saturating_sub(w);
        let hi = (full_idx + w + 1).min(all_strikes.len());
        let ot = self.target_option_side(strat, settings);
        let seg = fno_segment(exch);
        // Resolve every strike in the window, then read all their signs under a
        // single quote-cache lock and keep the +green ones.
        let mut green: Vec<(usize, i64, f64, f64)> = Vec::new();
        for i in lo..hi {
            if let Some(r) = sc.resolve(&strat.trading_symbol, &expiry, all_strikes[i], &ot, &strat.exchange_segment) {
                if r.security_id > 0 {
                    green.push((i, r.security_id, 0.0, 0.0));
                }
            }
        }
        if green.is_empty() {
            return Vec::new();
        }
        {
            let Ok(q) = self.dhan.market.quotes.lock() else { return Vec::new() };
            green.retain_mut(|l| {
                let Some(v) = q.get(&crate::market::quote_key(l.1, seg)) else { return false };
                let ltp = v.get("ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
                if ltp <= 0.0 {
                    return false;
                }
                let change = v.get("change").and_then(|x| x.as_f64()).unwrap_or(0.0);
                let prev = v.get("prev_ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
                if !Self::premium_is_green(ltp, prev, change) {
                    return false;
                }
                l.2 = v.get("change_pct").and_then(|x| x.as_f64()).unwrap_or(0.0);
                l.3 = change;
                true
            });
        }
        green.sort_by(|a, b| {
            if Self::rising_score_better((b.2, b.3), (a.2, a.3)) {
                std::cmp::Ordering::Greater
            } else if Self::rising_score_better((a.2, a.3), (b.2, b.3)) {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        });
        let n = settings.fastest_count.max(1) as usize;
        green
            .into_iter()
            .take(n)
            .filter_map(|(i, _, _, _)| self.contract_for_strike(strat, &expiry, all_strikes[i], &ot, &prefix, exch))
            .collect()
    }

    /// The full walk order of strike indices for the "Execute Trade In" dropdown,
    /// starting at ATM `idx` and continuing outward in the selected direction to
    /// the chain's edge. The "+green" scan follows this order and only stops at
    /// the first strike whose premium is plus - "Number of Strikes" does NOT cap
    /// this walk, so a run of minus strikes is skipped over to the next strike in
    /// the same leg (e.g. Above ATM: idx+1 minus -> idx+2 -> idx+3 ...).
    ///
    /// `above`/`above_atm` go up, `below`/`below_atm` go down, `both_atm`/
    /// `both_atm_inc` alternate up/down outward, `atm` is the ATM leg only.
    fn green_walk_order(len: usize, idx: usize, mode: &str) -> Vec<usize> {
        let eq = |s: &str| mode.eq_ignore_ascii_case(s);
        let mut out: Vec<usize> = Vec::with_capacity(len);
        if eq("atm") {
            out.push(idx);
            return out;
        }
        let upward = eq("above") || eq("above_atm");
        let downward = eq("below") || eq("below_atm");
        let both = eq("both_atm") || eq("both_atm_inc");
        // "*_ATM*" modes include the ATM leg itself first.
        if eq("above_atm") || eq("below_atm") || eq("both_atm_inc") {
            out.push(idx);
        }
        if upward {
            let mut j = idx as i64 + 1;
            while j < len as i64 {
                out.push(j as usize);
                j += 1;
            }
        } else if downward {
            let mut j = idx as i64 - 1;
            while j >= 0 {
                out.push(j as usize);
                j -= 1;
            }
        } else if both {
            let mut k = 1i64;
            loop {
                let up = idx as i64 + k;
                let dn = idx as i64 - k;
                let mut any = false;
                if up < len as i64 {
                    out.push(up as usize);
                    any = true;
                }
                if dn >= 0 {
                    out.push(dn as usize);
                    any = true;
                }
                if !any {
                    break;
                }
                k += 1;
            }
        } else {
            // Unknown mode: fall back to the ATM leg only.
            out.push(idx);
        }
        out
    }

    /// The absolute strike indices the "+green / fastest-rising" detection is
    /// allowed to see, in the walk order the "Execute Trade In" dropdown asks for.
    /// The candidate set is clipped to the exact ATM +/- `OPTION_CHAIN_WINDOW`
    /// ladder the option-chain screen renders, so a strike the chain never shows
    /// (e.g. a far-OTM 540-CE on a ladder that runs wide) can never be picked.
    /// The direction (Above/Below ATM), the minus-skip to the next strike and the
    /// opposite-side fallback all stay exactly as they were - only the strikes
    /// considered for the plus/rising sign come from the option chain.
    fn chain_window_order(strikes_len: usize, idx: usize, mode: &str) -> Vec<usize> {
        let w = crate::optionchain::OPTION_CHAIN_WINDOW;
        let lo = idx.saturating_sub(w);
        let hi = (idx + w + 1).min(strikes_len);
        if hi <= lo {
            return Vec::new();
        }
        let sub_idx = idx - lo;
        Self::green_walk_order(hi - lo, sub_idx, mode)
            .into_iter()
            .map(|i| i + lo)
            .collect()
    }

    /// The walk mode the "+green / fastest-rising" scan actually uses. Every
    /// engine EXCEPT Paper Trade 2 treats the "Only ATM" selection as "Below
    /// including ATM": when the ATM strike is minus the scan skips it and keeps
    /// stepping DOWN the same leg (CE/PE) until it finds a +green strike,
    /// blocking only when the whole downward run is minus. Paper Trade 2 keeps
    /// "Only ATM" pinned to the ATM strike itself (`atm_scans_below == false`).
    /// Every non-ATM mode is passed through unchanged on all engines. Pure so
    /// the rule is trivially testable.
    fn effective_green_walk_mode(mode: &str, atm_scans_below: bool) -> &str {
        if atm_scans_below && mode.eq_ignore_ascii_case("atm") {
            "below_atm"
        } else {
            mode
        }
    }

    /// The single strike index the "Execute Trade In" dropdown targets when the
    /// +green / fastest-rising preferences are OFF: step `count` strikes from ATM
    /// in the mode's direction. `above`/`below` step strictly off ATM,
    /// `above_atm`/`below_atm`/`both_atm_inc` count the ATM leg as the first step,
    /// and the two-sided modes send the CE leg up and the PE leg down so "Above
    /// and below ATM, N strikes" means the Nth above for CE and the Nth below for
    /// PE. The result is always clamped to the chain. This is what makes the
    /// Above/Below-ATM selection work independently of the +green base.
    fn direct_mode_strike_idx(len: usize, idx: usize, mode: &str, count: i64, is_ce: bool) -> usize {
        if len == 0 {
            return 0;
        }
        let last = len as i64 - 1;
        let i = (idx as i64).min(last);
        let step = if count <= 0 { 1 } else { count };
        let eq = |s: &str| mode.eq_ignore_ascii_case(s);
        let target = if eq("atm") {
            i
        } else if eq("above") {
            i + step
        } else if eq("above_atm") {
            i + step - 1
        } else if eq("below") {
            i - step
        } else if eq("below_atm") {
            i - step + 1
        } else if eq("both_atm") {
            if is_ce { i + step } else { i - step }
        } else if eq("both_atm_inc") {
            if is_ce { i + step - 1 } else { i - step + 1 }
        } else {
            i
        };
        target.clamp(0, last) as usize
    }

    /// Paper Trade 2's indices / commodities resolve the "Execute Trade In" strike
    /// directly when the +green / fastest-rising preferences are OFF: the exact
    /// Above/Below-ATM step, else the nearest strike to it that actually resolves
    /// a contract (so a sparse chain or a missing step never blocks the entry).
    fn direct_strike_index(
        &self,
        strat: &Strategy,
        expiry: &str,
        strikes: &[f64],
        idx: usize,
        ot: &str,
        settings: &Settings,
    ) -> Option<usize> {
        if strikes.is_empty() {
            return None;
        }
        let sc = scrip::get()?;
        let is_ce = ot.eq_ignore_ascii_case("CE");
        let want =
            Self::direct_mode_strike_idx(strikes.len(), idx, &settings.strike_mode, settings.strike_count, is_ce) as i64;
        let n = strikes.len() as i64;
        let mut d = 0i64;
        while d < n {
            for cand in [want - d, want + d] {
                if cand < 0 || cand >= n {
                    continue;
                }
                let i = cand as usize;
                if sc
                    .resolve(&strat.trading_symbol, expiry, strikes[i], ot, &strat.exchange_segment)
                    .is_some()
                {
                    return Some(i);
                }
            }
            d += 1;
        }
        None
    }

    /// Pure sign decision for the "+green" scan. Given the live LTP, the previous
    /// print's LTP and the published change, it returns the LTP's own plus sign
    /// (tick-to-tick) and the change's plus sign. `None` when there is no usable
    /// positive LTP. State-free so it is trivially testable.
    ///
    /// The LTP sign is *never* derived from a previous close: it compares the
    /// current print against the previous print. Only when no previous print has
    /// been observed yet does it fall back to the change's sign so the scan can
    /// still decide on the very first evaluation.
    ///
    /// A strike whose change is not available (never seeded / genuinely flat, i.e.
    /// `0`) leans on the live print for that half of the decision, so the scan
    /// still works without a REST seed. A genuine minus change is never bought.
    fn premium_signs_from(ltp: f64, prev_ltp: f64, change: f64) -> Option<(bool, bool)> {
        if ltp <= 0.0 {
            return None;
        }
        let ltp_plus = if prev_ltp > 0.0 { ltp > prev_ltp } else { change > 0.0 };
        let chg_plus = if change != 0.0 { change > 0.0 } else { ltp_plus };
        Some((ltp_plus, chg_plus))
    }

    /// True when a strike's premium is "+green" the way the option chain shows it:
    /// the published `change` versus the previous close is positive. The live
    /// tick direction is consulted only when no change has been published yet
    /// (`premium_signs_from` already substitutes it as `chg_plus`), so a +green
    /// strike whose most recent print dipped is still eligible. A genuinely minus
    /// change is never green, even if the last tick printed up.
    fn premium_is_green(ltp: f64, prev_ltp: f64, change: f64) -> bool {
        matches!(Self::premium_signs_from(ltp, prev_ltp, change), Some((_, true)))
    }

    /// The opposite ATM side of a single-sided "Execute Trade In" mode, or `None`
    /// when the mode already covers both sides / is ATM-only (no opposite to fall
    /// back to). Above <-> Below (including-ATM variants mirror each other).
    fn opposite_side_mode(mode: &str) -> Option<&'static str> {
        if mode.eq_ignore_ascii_case("above") {
            Some("below")
        } else if mode.eq_ignore_ascii_case("above_atm") {
            Some("below_atm")
        } else if mode.eq_ignore_ascii_case("below") {
            Some("above")
        } else if mode.eq_ignore_ascii_case("below_atm") {
            Some("above_atm")
        } else {
            None
        }
    }

    /// True when score `a` = (published change %, absolute change) outranks `b`:
    /// a higher LTP change % wins; an equal change % is broken by the higher
    /// absolute LTP change. Pure so the "fastest positive rising" ranking is
    /// trivially testable.
    fn rising_score_better(a: (f64, f64), b: (f64, f64)) -> bool {
        a.0 > b.0 || (a.0 == b.0 && a.1 > b.1)
    }

    /// Read one ordered leg list under a single quote-cache lock and report the
    /// best eligible rising strike, whether any strike on this side had a live
    /// quote, and the still-unquoted candidates (in order) the caller should warm
    /// next.
    ///
    /// Eligible = its published `change` versus the previous close is positive
    /// (the option chain's own "+"), or - when no change has been published yet -
    /// its live LTP ticked up. A minus change is never eligible even if the last
    /// tick printed up.
    /// With `fastest` the scan keeps going and keeps the strike with the highest
    /// published `change_pct` (ties broken by the absolute `change`); otherwise it
    /// returns the first rising strike in walk order.
    fn scan_strike_order(
        &self,
        legs: &[(usize, i64)],
        seg: &str,
        fastest: bool,
    ) -> (Option<(usize, i64)>, bool, Vec<(i64, String)>) {
        let mut best: Option<(usize, i64)> = None;
        let mut best_key: Option<(f64, f64)> = None;
        let mut any_quoted = false;
        let mut unquoted: Vec<(i64, String)> = Vec::new();
        let Ok(q) = self.dhan.market.quotes.lock() else {
            return (None, false, unquoted);
        };
        for (i, sid) in legs {
            let key = crate::market::quote_key(*sid, seg);
            let Some(v) = q.get(&key) else {
                unquoted.push((*sid, seg.to_string()));
                continue;
            };
            let ltp = v.get("ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
            if ltp <= 0.0 {
                unquoted.push((*sid, seg.to_string()));
                continue;
            }
            any_quoted = true;
            let change = v.get("change").and_then(|x| x.as_f64()).unwrap_or(0.0);
            let prev = v.get("prev_ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
            // "Only +green" follows the option chain's own "+": a premium that is
            // positive versus its previous close (the published `change`). The
            // live tick direction is only a fallback when no change is published
            // (`premium_signs_from` folds that into `chg_plus`). Requiring the last
            // tick to also be up rejected a +green strike whose very last print
            // dipped, so the engine appeared to ignore positive strikes that the
            // option chain clearly showed.
            if !Self::premium_is_green(ltp, prev, change) {
                continue;
            }
            if !fastest {
                best = Some((*i, *sid));
                break;
            }
            let pct = v.get("change_pct").and_then(|x| x.as_f64()).unwrap_or(0.0);
            let score = (pct, change);
            let better = match best_key {
                None => true,
                Some(bk) => Self::rising_score_better(score, bk),
            };
            if better {
                best_key = Some(score);
                best = Some((*i, *sid));
            }
        }
        (best, any_quoted, unquoted)
    }

    /// Pick the strike for the "Execute Trade In" direction, wiring the strike
    /// preferences together:
    ///   * "Only +green premium strikes" walks the chosen direction and takes the
    ///     FIRST rising (+green) strike; the walk is NOT capped by "Number of
    ///     Strikes" so a run of minus strikes is skipped to the next strike.
    ///   * "Pick fastest positive rising LTP" scans the same direction and takes
    ///     the BIGGEST riser - the highest published LTP change % among the rising
    ///     strikes (ties broken by the absolute LTP change).
    ///   * "Opposite side fallback" -> only once the ENTIRE selected side has a
    ///     live quote and every strike is minus, the opposite side of ATM
    ///     (Above <-> Below) is scanned in the SAME option leg (CE/PE).
    /// Any still-unquoted candidate on the chosen side is warmed first so a rising
    /// strike that lives on the chosen side is never missed. `None` only when no
    /// rising strike exists in either direction.
    ///
    /// The scan reads every candidate's signs/change under a single quote-cache
    /// lock, so it stays well inside the entry latency budget and never buys a
    /// falling premium.
    fn pick_strike_pref(
        &self,
        strat: &Strategy,
        exch: &str,
        expiry: &str,
        strikes: &[f64],
        idx: usize,
        ot: &str,
        settings: &Settings,
        provisional: bool,
        atm_scans_below: bool,
    ) -> Option<usize> {
        // Warm the whole candidate walk in one pass so a pick can land on the
        // very next 100ms scanner tick instead of advancing 8 strikes per pass.
        const WARM_PER_CALL: usize = 128;
        let fastest = settings.fastest_rising;
        let sc = scrip::get()?;
        let walk_mode = Self::effective_green_walk_mode(&settings.strike_mode, atm_scans_below);
        let order = Self::chain_window_order(strikes.len(), idx, walk_mode);
        if order.is_empty() {
            return None;
        }
        let seg = fno_segment(exch);
        let resolve_order = |order: &[usize]| -> Vec<(usize, i64)> {
            let mut v: Vec<(usize, i64)> = Vec::with_capacity(order.len());
            for i in order {
                if let Some(r) = sc.resolve(&strat.trading_symbol, expiry, strikes[*i], ot, &strat.exchange_segment) {
                    if r.security_id > 0 {
                        v.push((*i, r.security_id));
                    }
                }
            }
            v
        };
        let primary = resolve_order(&order);
        if primary.is_empty() {
            return None;
        }
        let (mut best, any_quoted, mut warm) = self.scan_strike_order(&primary, seg, fastest);
        // The selected side still has unquoted candidates: warm them and let the
        // next evaluation judge them instead of falling back early, so a rising
        // strike on the chosen side is never skipped.
        if best.is_none() && !warm.is_empty() {
            warm.truncate(WARM_PER_CALL);
            self.dhan.watch_options_now(&warm);
            // Readout (provisional): never leave the picked-strike list blank
            // while the +green quotes warm up. But only name the nearest
            // contract while its sign is still UNKNOWN - a strike that is
            // already quoted and minus is one the engine will NOT trade, so
            // showing it would advertise a red strike as the pick (and its
            // premium would read minus next to a + chain row). The strict entry
            // path still returns None until a genuinely rising premium appears.
            if provisional {
                let (_, sid) = primary[0];
                let known_red = self
                    .dhan
                    .market
                    .quotes
                    .lock()
                    .ok()
                    .and_then(|g| g.get(&crate::market::quote_key(sid, seg)).cloned())
                    .map(|v| {
                        let ltp = v.get("ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
                        let change = v.get("change").and_then(|x| x.as_f64()).unwrap_or(0.0);
                        let prev = v.get("prev_ltp").and_then(|x| x.as_f64()).unwrap_or(0.0);
                        ltp > 0.0 && !Self::premium_is_green(ltp, prev, change)
                    })
                    .unwrap_or(false);
                if !known_red {
                    return Some(primary[0].0);
                }
            }
            return None;
        }
        // The ENTIRE selected side is quoted and every strike is minus -> try the
        // opposite ATM side, in the same leg, before giving up on the entry.
        if best.is_none() && settings.fallback_opposite_side && any_quoted {
            if let Some(omode) = Self::opposite_side_mode(&settings.strike_mode) {
                let oorder = Self::chain_window_order(strikes.len(), idx, omode);
                let olegs = resolve_order(&oorder);
                if !olegs.is_empty() {
                    let (obest, _, ow) = self.scan_strike_order(&olegs, seg, fastest);
                    best = obest;
                    warm.extend(ow);
                }
            }
        }
        if let Some((i, sid)) = best {
            // Make sure the chosen leg is streaming even if it was already cached.
            self.dhan.watch_options_now(&[(sid, seg.to_string())]);
            return Some(i);
        }
        if !warm.is_empty() {
            warm.truncate(WARM_PER_CALL);
            self.dhan.watch_options_now(&warm);
        }
        // The selected side is fully quoted and every strike is minus (and no
        // opposite-side fallback found a riser): there is no +green strike to
        // trade, so the entry is blocked AND the "Picked Strikes" readout shows
        // nothing for this leg instead of a misleading minus (red) strike. The
        // warm-up fallback above still names the nearest contract while the
        // signs are still unknown.
        None
    }

    /// Whether an option's own premium is consistent with the underlying: a long
    /// option can never be worth less than its intrinsic value, so a print below
    /// intrinsic means the option feed (or the underlying's) is stale/crossed and
    /// must not be filled. The 2% slack absorbs the underlying's own last-trade
    /// lag without letting a genuinely stale premium through. Fails open for
    /// non-options, unknown symbols or a missing underlying quote.
    fn option_premium_sane(&self, opt: &Strategy, premium: f64) -> bool {
        if premium <= 0.0 {
            return false;
        }
        let Some((strike, ot)) = option_strike_type(&opt.trading_symbol) else { return true };
        let Some(und) = underlying_strategy(opt) else { return true };
        let spot = self.ltp_of(und.security_id, &und.exchange_segment);
        if spot <= 0.0 {
            return true;
        }
        let intrinsic = if ot.eq_ignore_ascii_case("PE") {
            (strike - spot).max(0.0)
        } else {
            (spot - strike).max(0.0)
        };
        premium >= intrinsic * 0.98
    }

    /// Resolve a strategy to its option-premium contract and fetch that chart's
    /// candles (used by "run in premium" / dual-confirmation modes). `None` when
    /// the contract or its candles cannot be resolved.
    /// Fetch the underlying spot chart's candles for an option-instrument
    /// strategy so "Run Strategy In: Spot chart" evaluates on the underlying
    /// (`None` when the strategy is not an option or the underlying is unknown).
    async fn underlying_candles(&self, strat: &Strategy) -> Option<(Strategy, Vec<Candle>)> {
        let spot = underlying_strategy(strat)?;
        let c = self
            .live_candles(spot.security_id, &spot.exchange_segment, &spot.instrument, &spot.timeframe)
            .await
            .ok()?;
        if c.len() < 3 {
            return None;
        }
        Some((spot, c))
    }

    async fn premium_candles(&self, strat: &Strategy, settings: &Settings) -> Option<(Strategy, Vec<Candle>)> {
        // ATM/ITM/OTM strike selection needs the UNDERLYING spot. For an
        // option-instrument strategy `strat.security_id` is the option itself,
        // whose premium would pick the wrong strike, so resolve the underlying.
        let (spot_sid, spot_seg) = match underlying_strategy(strat) {
            Some(u) => (u.security_id, u.exchange_segment),
            None => (strat.security_id, strat.exchange_segment.clone()),
        };
        let mut spot = self.ltp_of(spot_sid, &spot_seg);
        if spot <= 0.0 {
            // The underlying is not streaming yet. Subscribe it on the live feed
            // (paper is REST-free by design) and give the socket a short bounded
            // window to deliver its first tick. Previously paper returned `None`
            // here immediately, so any scanner pick whose underlying had not been
            // subscribed reported "no option contracts available" forever.
            self.dhan
                .subscribe_options(&[(spot_sid, spot_seg.clone())])
                .await;
            spot = self.wait_feed_ltp(spot_sid, &spot_seg, 1500).await;
        }
        if spot <= 0.0 && !self.paper && !self.dhan.rate_limited() {
            // Live may pay one REST LTP call, but never while Dhan's data gate is
            // holding after a 429 - that call would sleep the whole penalty inside
            // the scan loop.
            spot = self.fetch_ltp(spot_sid, &spot_seg).await;
        }
        if spot <= 0.0 {
            return None;
        }
        // An already-resolved option contract must re-resolve from its
        // UNDERLYING: `resolve_option_strategy` derives the F&O prefix from
        // `trading_symbol`, and a full contract symbol
        // ("RELIANCE-Oct2026-2900-CE") has no expiry bucket, so passing the
        // contract straight in always resolved to `None`.
        let res = match underlying_strategy(strat) {
            Some(u) => self.resolve_option_strategy(&u, spot, settings, false, false)?,
            None => self.resolve_option_strategy(strat, spot, settings, false, false)?,
        };
        // Publish the resolved premium chart so the Running Strategies view can
        // show which chart this strategy's entry conditions are evaluated on.
        self.record_strat_leg(&strat.id, "run", &res);
        // Keep the resolved paper leg streaming so its premium ticks arrive over
        // the websocket (paper never pays a REST quote for it).
        if self.paper {
            self.dhan
                .subscribe_options(&[(res.security_id, res.exchange_segment.clone())])
                .await;
        }
        let c = self
            .live_candles(res.security_id, &res.exchange_segment, &res.instrument, &res.timeframe)
            .await
            .ok()?;
        if c.len() < 3 {
            return None;
        }
        Some((res, c))
    }

    /// Premium-only multi-strike analysis. Resolves EVERY strike the operator's
    /// "Execute Trade In" + "Number of Strikes" selection covers and returns each
    /// one's premium chart, so the indicator filters can be evaluated per strike.
    ///
    /// `premium_candles` only ever resolves the single picked strike, yet in
    /// "Premium chart only (run + trade)" mode the whole strike ladder used to
    /// execute off that one strike's chart. Here every selected strike gets its
    /// own chart; the scan loop then fires only the strikes whose own filters
    /// pass. No selected strike is ever dropped from the resolution - a failing
    /// strike is skipped for that scan, not removed from the ladder.
    async fn premium_candles_all(&self, strat: &Strategy, settings: &Settings) -> Vec<(Strategy, Vec<Candle>)> {
        let (spot_sid, spot_seg) = match underlying_strategy(strat) {
            Some(u) => (u.security_id, u.exchange_segment),
            None => (strat.security_id, strat.exchange_segment.clone()),
        };
        let mut spot = self.ltp_of(spot_sid, &spot_seg);
        if spot <= 0.0 {
            self.dhan
                .subscribe_options(&[(spot_sid, spot_seg.clone())])
                .await;
            spot = self.wait_feed_ltp(spot_sid, &spot_seg, 1500).await;
        }
        if spot <= 0.0 && !self.paper && !self.dhan.rate_limited() {
            spot = self.fetch_ltp(spot_sid, &spot_seg).await;
        }
        if spot <= 0.0 {
            return Vec::new();
        }
        let legs = match underlying_strategy(strat) {
            Some(u) => self.resolve_option_strategies(&u, spot, settings, false, false),
            None => self.resolve_option_strategies(strat, spot, settings, false, false),
        };
        if self.paper {
            let subs: Vec<(i64, String)> = legs
                .iter()
                .map(|l| (l.security_id, l.exchange_segment.clone()))
                .collect();
            if !subs.is_empty() {
                self.dhan.subscribe_options(&subs).await;
            }
        }
        let mut out: Vec<(Strategy, Vec<Candle>)> = Vec::with_capacity(legs.len());
        for leg in legs {
            let c = match self
                .live_candles(leg.security_id, &leg.exchange_segment, &leg.instrument, &leg.timeframe)
                .await
            {
                Ok(c) if c.len() >= 3 => c,
                _ => continue,
            };
            out.push((leg, c));
        }
        if let Some((first, _)) = out.first() {
            self.record_strat_leg(&strat.id, "run", first);
        }
        out
    }

    /// Single-instrument LTP straight from Dhan's `/marketfeed/ltp`.
    async fn fetch_ltp(&self, sid: i64, exch: &str) -> f64 {
        let Some(client) = self.dhan.session_client().await else { return 0.0 };
        let mut req: BTreeMap<String, Vec<i64>> = BTreeMap::new();
        req.entry(exch.to_string()).or_default().push(sid);
        self.dhan.dhan_throttle().await;
        if let Ok(resp) = client.market_feed_ltp(&req).await {
            for (_s, legs) in resp {
                for (_id, e) in legs {
                    if e.last_price > 0.0 {
                        return e.last_price;
                    }
                }
            }
        }
        0.0
    }

    /// Volatility-based AI levels: ATR from recent candles sets the stop at
    /// 1.5x ATR, the target at 3x ATR and the trail distance at 1x ATR.
    ///
    /// The ATR is cached for a minute and any fetch is hard-bounded, so a slow
    /// or throttled Dhan candle call can never hold an entry order back by
    /// seconds (the entry latency that made every fill chase the move).
    /// The candle series the brain reads the market regime from.
    ///
    /// Stock / NIFTY engines read the NIFTY spot index (the market-wide regime
    /// that actually drives correlated stock moves). The indices-only book reads
    /// its first configured index, the commodities-only book its first commodity.
    /// A blank universe falls back to the first saved strategy's instrument.
    fn brain_reference_series(&self, s: &Settings) -> Option<(i64, String, String, String)> {
        let tf = if s.nifty_tf.trim().is_empty() { "5min".to_string() } else { s.nifty_tf.trim().to_string() };
        if self.indices_only() {
            let id = *s.movers_indices.first()?;
            return Some((id, "IDX_I".into(), "INDEX".into(), tf));
        }
        if self.commodities_only() {
            let id = *s.commodity_list.first()?;
            return Some((id, "MCX_COMM".into(), "FUTCOM".into(), tf));
        }
        if !self.indices_commodities_only() {
            return Some((NIFTY_SEC, "IDX_I".into(), "INDEX".into(), tf));
        }
        if let Some(id) = s.movers_indices.first() {
            return Some((*id, "IDX_I".into(), "INDEX".into(), tf));
        }
        if let Some(id) = s.commodity_list.first() {
            return Some((*id, "MCX_COMM".into(), "FUTCOM".into(), tf));
        }
        let d = self.doc()?;
        let st = d.strategies.iter().find(|x| x.security_id > 0)?;
        Some((st.security_id, st.exchange_segment.clone(), st.instrument.clone(), st.timeframe.clone()))
    }

    /// Read the reference series, compute the plan and commit it. Returns the
    /// applied plan so the caller can log it.
    async fn brain_decide(&self, sec: i64, exch: &str, inst: &str, tf: &str) -> Option<BrainPlan> {
        // Paper stays REST-free: it only reads the live websocket series, exactly
        // like `ai_levels`. The real engine may seed from REST when the live
        // series is still cold.
        let candles = if self.paper {
            self.dhan.market.live_bars_for(sec, exch, tf, LIVE_BAR_TTL)?
        } else {
            match tokio::time::timeout(Duration::from_millis(2000), self.live_candles(sec, exch, inst, tf)).await {
                Ok(Ok(c)) => c,
                _ => return None,
            }
        };
        let settings = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
        let mut plan = brain_plan(&candles, &settings)?;

        // --- Realised feedback -------------------------------------------
        // The candle backtest is a prior; real fills are ground truth. Once a
        // regime/instrument/side bucket has enough closed trades, a negative
        // realised average R vetoes that side outright and a positive one is
        // written into the readout so the operator sees the live edge.
        if let Some(d) = self.doc() {
            let inst_class = instrument_class(inst, "");
            let mut feedback: Vec<String> = Vec::new();
            for (bull, side_tag) in [(true, "BUY"), (false, "SELL")] {
                let key = crate::brain::evidence_key(plan.regime, inst_class, side_tag);
                let Some(b) = d.evidence.get(&key) else { continue };
                if b.trades < 20 {
                    continue;
                }
                let avg = b.avg_r();
                if avg <= 0.0 {
                    if bull {
                        plan.bull.clear();
                        plan.bull_blocked = true;
                    } else {
                        plan.bear.clear();
                        plan.bear_blocked = true;
                    }
                    feedback.push(format!(
                        "{side_tag} vetoed by realised edge {avg:+.2}R over {} trades",
                        b.trades
                    ));
                } else {
                    feedback.push(format!(
                        "{side_tag} realised {avg:+.2}R win {:.0}% over {} trades",
                        b.win_rate() * 100.0,
                        b.trades
                    ));
                }
            }
            if !feedback.is_empty() {
                plan.note.push_str(" | feedback: ");
                plan.note.push_str(&feedback.join("; "));
            }
        }

        if let Some(mut d) = self.doc() {
            brain_apply_plan(&mut d.settings, &plan);
        }
        Some(plan)
    }

    /// Periodic brain tick. Only runs while Auto Trading is ON - the brain is the
    /// thing that decides the preset's adaptive values, so it must never touch a
    /// manual (Auto Trading OFF) configuration. Throttled so the ranking walk is
    /// not repeated on every 100ms scan.
    async fn brain_tick(&self) {
        let (auto_on, ref_series) = {
            let Some(d) = self.doc() else { return };
            if !d.settings.auto_trade_on {
                return;
            }
            (true, self.brain_reference_series(&d.settings))
        };
        if !auto_on {
            return;
        }
        let Some((sec, exch, inst, tf)) = ref_series else { return };
        // At most one recompute per minute: regimes and hit-rates do not change
        // meaningfully inside a minute, and the backtest walk is the expensive
        // part of the scan.
        let now = now_ms();
        let last = self.last_brain.load(Ordering::Relaxed);
        if now.saturating_sub(last) < BRAIN_REFRESH_MS {
            return;
        }
        match self.brain_decide(sec, &exch, &inst, &tf).await {
            Some(plan) => {
                self.last_brain.store(now, Ordering::Relaxed);
                self.log("info", &format!("Brain: {}", plan.note));
                self.save();
            }
            None => {
                // No candle series yet (feed cold / REST unavailable). Retry on a
                // short cadence instead of on every 100ms loop tick, so a dead
                // feed can never turn the brain into a REST hammer.
                self.last_brain.store(now - (BRAIN_REFRESH_MS - BRAIN_RETRY_MS), Ordering::Relaxed);
            }
        }
    }

    async fn ai_levels(&self, strat: &Strategy, side: &str, ltp: f64) -> Option<(f64, f64, f64, f64)> {
        let key = format!(
            "{}:{}:{}:{}",
            strat.security_id,
            strat.exchange_segment.to_uppercase(),
            strat.instrument.to_uppercase(),
            strat.timeframe
        );
        let atr = if let Some(a) = self.cached_atr(&key, 60_000) {
            a
        } else {
            // Paper never REST-seeds a candle series; it reads the live websocket
            // series only, so paper execution stays completely REST-free.
            let candles = if self.paper {
                let raw = match self
                    .dhan
                    .market
                    .live_bars_for(strat.security_id, &strat.exchange_segment, &strat.timeframe, LIVE_BAR_TTL)
                {
                    Some(c) if c.len() >= 15 => c,
                    _ => return None,
                };
                // Same chart-type switch as `live_candles`, so the paper ATR can
                // never read a different series than the rest of the engine.
                let es = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
                apply_engine_chart(raw, &es)
            } else {
                let fut = self
                    .live_candles(strat.security_id, &strat.exchange_segment, &strat.instrument, &strat.timeframe);
                match tokio::time::timeout(Duration::from_millis(1500), fut).await {
                    Ok(Ok(c)) if c.len() >= 15 => c,
                    _ => return None,
                }
            };
            let settings: algo_core::model::Settings = Default::default();
            let out = algo_core::compute("atr", &candles, &settings);
            let a = out
                .first()
                .and_then(|s| s.data.last())
                .map(|p| p.value)
                .filter(|v| *v > 0.0)?;
            if let Ok(mut m) = self.atr_cache.lock() {
                m.insert(key, (now_ms(), a));
            }
            a
        };
        // Brain risk multipliers: when Auto Trading drives the brain, the stop /
        // trail / target are the regime-sized values it committed. Outside that
        // mode they keep the historical 1.5xATR stop and 3xATR target.
        let (sl_mult, trail_mult, rr) = {
            let st = self.doc().map(|d| d.settings.clone()).unwrap_or_default();
            brain_risk_mults(&st)
        };
        let is_buy = side == "BUY";
        let risk = sl_mult * atr;
        let sl = if is_buy { ltp - risk } else { ltp + risk };
        let tp = if is_buy { ltp + risk * rr } else { ltp - risk * rr };
        let trail_atr = trail_mult * atr;
        Some((sl.max(0.05), tp.max(0.05), atr, trail_atr))
    }

    fn cached_atr(&self, key: &str, max_age_ms: i64) -> Option<f64> {
        let g = self.atr_cache.lock().ok()?;
        let (at, v) = g.get(key)?;
        if *v > 0.0 && now_ms() - *at <= max_age_ms {
            Some(*v)
        } else {
            None
        }
    }

    /// Paper-only simulated execution latency.
    ///
    /// Queues a qualifying entry and places it `delay_ms` after the condition
    /// first held (using the live LTP at that moment, like a real order that
    /// lands a little late). Disabling the feature means this is never called.
    /// While the order is in flight the strategy id stays in `paper_pending`,
    /// so the 100ms scanner cannot queue a duplicate; it is removed once the
    /// entry resolves. If the engine stops or is disarmed during the wait the
    /// queued order is dropped, matching the live tab's arm gate.
    fn queue_delayed_entry(&self, id: &str, strat: &Strategy, delay_ms: f64) {
        let due = now_ms() + delay_ms.max(0.0) as i64;
        {
            let Ok(mut m) = self.paper_pending.lock() else { return };
            if m.contains_key(id) {
                return;
            }
            m.insert(id.to_string(), due);
        }
        let me = self.clone();
        let id = id.to_string();
        let strat = strat.clone();
        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(delay_ms.max(0.0) as u64)).await;
            let ready = me
                .doc
                .lock()
                .map(|d| d.engine_on && d.armed)
                .unwrap_or(false);
            if ready {
                let group = if me.paper { Group::Paper } else { Group::Real };
                if !order_rate::has_room(group) {
                    // Shared group cap already saturated: drop, never hold and
                    // fill later at a chased price. The edge was consumed when
                    // this delayed entry was queued, so keep it consumed.
                    me.mark_rl_skip(&strat.id);
                    me.log_throttled(
                        &format!("rlskip-delay:{}", strat.id),
                        10_000,
                        "info",
                        &format!(
                            "drop delayed entry {} -> {} (orders/sec cap {} reached; not held)",
                            strat.name,
                            strat.trading_symbol,
                            order_rate::cap(group)
                        ),
                    );
                    return;
                }
                let entry_result = me.open_entry(&strat, true, Some(id.as_str())).await;
                if !me.paper {
                    me.dhan.kick_positions();
                }
                match entry_result {
                    Ok(()) => {
                        me.log_throttled(
                            &format!("delay-entry:{}", strat.id),
                            5_000,
                            "info",
                            &format!(
                                "paper delayed ENTRY ok (+{:.0}ms) {} -> {}",
                                delay_ms, strat.name, strat.trading_symbol
                            ),
                        );
                    }
                    Err(e) => {
                        // The fresh-signal edge was consumed when the order was
                        // queued. If it never fills (margin block / rejection /
                        // no premium) release the edge so the still-true gate can
                        // re-trigger, instead of latching silent until the gate
                        // happens to reset and print a new signal. EXCEPTION:
                        // when "skip when margin unavailable" is ON, a margin
                        // block must NOT hand the edge back - doing so is exactly
                        // what let the same signal re-queue and fill minutes later
                        // at a worse price. Consume it instead.
                        if me.skip_margin_block_enabled() && e.starts_with("trade blocked:") {
                            me.consume_signal_for_margin(&strat.id);
                            me.note_blocker(
                                "warn",
                                "margin",
                                &strat.name,
                                &format!("{} -> {}: {e}", strat.name, strat.trading_symbol),
                            );
                            me.log_throttled(
                                &format!("marginskip:{}", strat.id),
                                10_000,
                                "warn",
                                &format!(
                                    "skip (margin unavailable, no late entry) {} -> {}: {e}",
                                    strat.name, strat.trading_symbol
                                ),
                            );
                        } else {
                            me.release_fresh_edge(&strat.id);
                            let code = classify_entry_error(&e);
                            me.note_blocker(
                                "warn",
                                code,
                                &strat.name,
                                &format!("{} -> {}: {e}", strat.name, strat.trading_symbol),
                            );
                            me.log_throttled(
                                &format!("delay-fail:{}", strat.id),
                                5_000,
                                "error",
                                &format!("delayed entry {} failed: {e}", strat.name),
                            );
                        }
                        if let Some(mut d) = me.doc() {
                            if let Some(s) = d.strategies.iter_mut().find(|s| s.id == strat.id) {
                                s.last_error = e.clone();
                            }
                        }
                    }
                }
            } else {
                // Dropped before it could fill: release the fresh edge too.
                me.release_fresh_edge(&strat.id);
                me.log_throttled(
                    &format!("delay-cancel:{}", strat.id),
                    5_000,
                    "info",
                    &format!("paper delayed entry {} dropped: engine stopped/disarmed", strat.name),
                );
            }
            if let Ok(mut m) = me.paper_pending.lock() {
                m.remove(&id);
            }
        });
    }

    /// Paper-only simulated exit latency.
    ///
    /// Queues a stop / trail-stop / target exit and books it `delay_ms` after
    /// the level first triggered, at the SAME `exit_px` the exit would have
    /// booked without the delay (stop -> stop level, trail -> trail level,
    /// target -> target). The delay only postpones the cut; it never re-prices
    /// it, so the paper P&L semantics stay identical to delay-off. While the
    /// exit is in flight the position id stays in `paper_exit_pending`, so the
    /// position manager cannot queue the same exit twice; it is removed once
    /// resolved. Disabling the feature means this is never called.
    fn queue_delayed_exit(&self, id: &str, reason: &str, exit_px: f64, delay_ms: f64) {
        let due = now_ms() + delay_ms.max(0.0) as i64;
        {
            let Ok(mut m) = self.paper_exit_pending.lock() else { return };
            if m.contains_key(id) {
                return;
            }
            m.insert(id.to_string(), due);
        }
        let me = self.clone();
        let id = id.to_string();
        let reason = reason.to_string();
        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(delay_ms.max(0.0) as u64)).await;
            let open = me
                .doc()
                .map(|d| d.positions.iter().any(|p| js(p, "id") == id))
                .unwrap_or(false);
            if open {
                match me.close_position(&id, &reason, exit_px).await {
                    Ok(()) => me.log_throttled(
                        &format!("delay-exit:{id}"),
                        5_000,
                        "info",
                        &format!(
                            "paper delayed EXIT {reason} (+{:.0}ms) booked at {:.2}",
                            delay_ms, exit_px
                        ),
                    ),
                    Err(e) => me.log("error", &format!("delayed exit {id} failed: {e}")),
                }
            }
            if let Ok(mut m) = me.paper_exit_pending.lock() {
                m.remove(&id);
            }
        });
    }

    /// Spot forming-candle colour gate. Returns `Some(reason)` when an entry must
    /// be skipped right now because the spot chart's live forming candle is the
    /// wrong colour for this leg's direction: a bullish leg (Top Gainer) may enter
    /// only on a GREEN candle, a bearish leg (Top Loser) only on a RED one. Returns
    /// `None` when the gate is off, the order is the operator's manual order, the
    /// entry rule is not evaluated on the spot chart, or the required colour is
    /// present. A doji (close == open) is neither green nor red, so the entry is
    /// held until a coloured candle forms.
    async fn spot_candle_gate_skip(&self, settings: &Settings, strat: &Strategy) -> Option<String> {
        if !settings.spot_candle_gate || strat.manual {
            return None;
        }
        // Only when the entry rule runs on the spot chart. A premium-only or
        // futures-only run has no spot candle to read, so the gate is a no-op.
        let run_mode = run_mode_of(strat, settings);
        if run_mode != "spot" && run_mode != "both" {
            return None;
        }
        // The spot chart is the strategy's own chart for a cash/stock leg, and the
        // resolved underlying spot for an option leg. When the underlying of an
        // option leg cannot be resolved we must NOT fall back to the option's own
        // premium candle - that compares the premium colour, not the spot, and
        // blocked perfectly valid entries. Fail open (no gate) in that case.
        let spot = match underlying_strategy(strat) {
            Some(u) => u,
            None if is_option_leg(strat) => return None,
            None => strat.clone(),
        };
        let candles = self
            .live_candles(spot.security_id, &spot.exchange_segment, &spot.instrument, &spot.timeframe)
            .await
            .ok()?;
        // Offset 0 (the live forming bar) is the last candle in the series.
        let last = candles.last()?;
        let bull = strategy_is_bull(strat);
        if !spot_candle_color_ok(bull, last.open, last.close) {
            return Some(if bull {
                "spot candle not green (Top Gainer needs green)".into()
            } else {
                "spot candle not red (Top Loser needs red)".into()
            });
        }
        None
    }

    /// "Trend check before entry": after the indicator-filter condition is met,
    /// read the CURRENT trend on the underlying (spot) chart and refuse the entry
    /// unless it agrees with the leg's side. This is a pure pre-order filter - it
    /// runs whether or not any trend-following master is switched ON, so a
    /// bullish filter can never buy a CE (or a bearish filter a PE) into an
    /// opposite / flat tape. Returns `Some(reason)` when the entry must be
    /// skipped, `None` when it may proceed (or the switch is off / manual order).
    ///
    /// The read is a composite of three independent votes on the same candles the
    /// chart draws:
    ///   * the operator's confirmation-indicator net direction (the trend engines'
    ///     own set, with a built-in EMA/Supertrend fallback when none is set),
    ///   * the EMA20 slope over the last 10 bars,
    ///   * price vs EMA20,
    /// gated by the composite range-regime read (ADX / choppiness / slope / range
    /// compression). A range-bound or neutral tape blocks BOTH sides, so only a
    /// genuine move in the leg's direction lets the trade through.
    async fn entry_trend_check_skip(&self, settings: &Settings, strat: &Strategy) -> Option<String> {
        if !settings.entry_trend_check_on || strat.manual {
            return None;
        }
        // The trend that matters is the one on the trade's UNDERLYING spot chart;
        // a resolved option contract's own premium chart is not the trend.
        let source = if is_option_leg(strat) {
            match underlying_strategy(strat) {
                Some(u) => u,
                None => strat.clone(),
            }
        } else {
            strat.clone()
        };
        let tf = engine_tf(settings, &source);
        let candles = match self
            .live_candles(source.security_id, &source.exchange_segment, &source.instrument, &tf)
            .await
        {
            Ok(c) if c.len() >= 35 => c,
            Ok(_) => return Some("trend check: not enough candles to read the trend yet".into()),
            Err(e) => return Some(format!("trend check: candle series unavailable ({e})")),
        };
        let cat = strat_category(strat);
        let conf = entry_trend_conf_inds(settings, cat);
        let bull = strategy_is_bull(strat);
        let read = entry_trend_read(&candles, &conf, settings);
        if !read.ok {
            return Some(format!(
                "trend check: {} (need {} trend)",
                read.reason,
                if bull { "bullish" } else { "bearish" }
            ));
        }
        let want = if bull { 1 } else { -1 };
        if read.dir != want {
            return Some(format!(
                "trend check: {} trend vs {} entry - opposite-side trade skipped",
                if read.dir > 0 { "bullish" } else { "bearish" },
                if bull { "bullish(CE)" } else { "bearish(PE)" }
            ));
        }
        None
    }

    /// Execution-instant re-check of the ticked Indicator-filter set (plus any
    /// saved strategy conditions). The scan decides an entry on the live forming
    /// bar, but the order is only booked AFTER two asynchronous latency windows -
    /// the paper execution delay (`paperExecDelayMs`) and the option-feed LTP
    /// warm-up (`wait_feed_ltp`, up to 1.5s). The filter can stop holding inside
    /// those windows, which is exactly how a signal whose condition had already
    /// flipped still filled "late". This re-runs the SAME gate the scan ran (same
    /// run-mode chart set, same direction template) on the CURRENT candles and
    /// blocks the fill when it no longer holds; the caller then releases the
    /// fresh-signal edge and retries on a later scan. Manual Order Placement is
    /// exempt (explicit operator intent). Every engine, including Paper Trade 3,
    /// runs the same gate.
    async fn entry_filter_gate_now(&self, strat: &Strategy) -> bool {
        let Some(settings) = self.doc().map(|d| d.settings.clone()) else { return true };
        // Nothing to re-check when no same-side filter is ticked and the operator
        // did not force a condition / flip trigger. This also keeps a normal leg
        // with an empty filter set from depending on a candle fetch at fill time.
        // Synthetic scanner legs are excluded: with no filter they would enter on
        // every scan, so the gate still blocks them.
        let has_primary = settings.entry_primary_on
            && settings
                .entry_primary_filters
                .iter()
                .any(|k| !k.trim().is_empty() && !is_stream_flag(k));
        if !strat.synthetic
            && !settings.require_condition
            && !settings.flip_trigger_on
            && !has_primary
            && !settings
                .filters
                .iter()
                .any(|(k, v)| *v && !is_stream_flag(k))
        {
            return true;
        }
        let mut gate_settings = self
            .template_for_direction(&settings, strat)
            .unwrap_or_else(|| settings.clone());
        // The live "Premium chart only" switch and run-in routing must win over a
        // direction template, exactly like the scan's gate settings.
        gate_settings.premium_only = settings.premium_only;
        gate_settings.run_index = settings.run_index.clone();
        gate_settings.run_fno = settings.run_fno.clone();
        gate_settings.run_comm = settings.run_comm.clone();
        gate_settings.require_condition = settings.require_condition;
        // Mirror the scan's timeframe choice. The scan overwrites the strategy's
        // TF with the engine timeframe (the Multi-TF entry leg, else `engine_tf`)
        // before it evaluates the gate. A resolved / frozen option leg carries an
        // EMPTY TF, so without this override the recheck would fetch candles on a
        // different series than the scan and read a different (failing) filter
        // result - blocking every fill as a false "stale entry".
        let mut strat_owned = strat.clone();
        let mtf_tfs = if settings.mtf { mtf_pair(&settings) } else { None };
        strat_owned.timeframe = match &mtf_tfs {
            Some((entry, _)) => entry.clone(),
            None => engine_tf(&settings, &strat_owned),
        };
        let strat = &strat_owned;
        let run_mode = run_mode_of(strat, &settings);
        let offset = 0usize;
        // Rebuild the same chart set the scan evaluated: the spot chart (the
        // option's UNDERLYING when an option leg is passed) and/or the premium
        // chart, per the run mode.
        let mut eval: Vec<(Strategy, Vec<Candle>)> = Vec::new();
        if run_mode != "premium" {
            if is_option_leg(strat) {
                if let Some(pair) = self.underlying_candles(strat).await {
                    eval.push(pair);
                } else if let Ok(c) = self
                    .live_candles(strat.security_id, &strat.exchange_segment, &strat.instrument, &strat.timeframe)
                    .await
                {
                    if c.len() >= 3 {
                        eval.push((strat.clone(), c));
                    }
                }
            } else if let Ok(c) = self
                .live_candles(strat.security_id, &strat.exchange_segment, &strat.instrument, &strat.timeframe)
                .await
            {
                if c.len() >= 3 {
                    eval.push((strat.clone(), c));
                }
            }
        }
        if run_mode != "spot" && run_mode != "futures" {
            // At fill time `strat` is already the concrete option contract the
            // order executes on. Re-check THAT contract's premium chart: calling
            // the resolver again with a contract symbol cannot find an expiry
            // bucket and can also pick a different strike, which blocked every
            // premium-mode fill with a false "indicator filter no longer holds".
            if is_concrete_option_contract(strat) {
                if let Ok(c) = self
                    .live_candles(strat.security_id, &strat.exchange_segment, &strat.instrument, &strat.timeframe)
                    .await
                {
                    if c.len() >= 3 {
                        eval.push((strat.clone(), c));
                    }
                }
            } else if let Some(pair) = self.premium_candles(strat, &gate_settings).await {
                eval.push(pair);
            }
        }
        if eval.is_empty() {
            return false;
        }
        let synth = strat.synthetic;
        let _fill_cross_grace = CrossFillGraceGuard::enter();
        for (s, c) in &eval {
            if c.len() < 3 {
                return false;
            }
            let _scope = IndScope::enter();
            let flip_on = gate_settings.flip_trigger_on;
            let cond_ok = flip_on || synth || conditions_met(&s.conditions, c, offset);
            let fg = if flip_on {
                flip_trigger_pass(&gate_settings, s, c, offset)
            } else {
                filter_gate(&gate_settings, s, c, offset)
            };
            if !cond_ok || !fg {
                return false;
            }
        }
        true
    }

    /// `origin_id` is the id of the strategy the ENTRY-TIMING stamp was recorded
    /// under, which is the SCAN strategy's id. The executed leg can carry a
    /// DIFFERENT id (a frozen Top-Movers Leg Book leg is `pick:<sid>:<side>` while
    /// the scan stamped `scan:<sid>:<side>`), so the pending marker must be
    /// removed by the origin id - otherwise the ENTRY TIMING DIAGNOSTICS row is
    /// never produced. `None` (manual orders) falls back to the leg's own id.
    async fn open_entry(&self, strat: &Strategy, guard_duplicates: bool, origin_id: Option<&str>) -> Result<(), String> {
        let (settings, method, auto_lots, cfg, route_map) = {
            let Some(d) = self.doc() else { return Err("state lock".into()) };
            (
                d.settings.clone(),
                d.method.clone(),
                d.auto_lots,
                d.order_cfg.clone(),
                d.brokers.clone(),
            )
        };
        // Real Dhan orders need the Dhan REST client; other brokers have their
        // own adapter and must not require a Dhan login. Paper trades only need a
        // live quote (from the shared feed) and never touch an order API.
        // Resolved after the route is known, below.
        let mut client: Option<dhan_hq::DhanClient> = None;
        let mut client_id = String::new();
        // Multi-broker routing: which brokers THIS engine may send the entry to.
        // Paper books never place a real order, so the route stays empty there.
        // A ticked broker that is switched OFF / still missing keys in Broker
        // Settings is dropped by `resolve_route` and reported once here instead
        // of silently swallowing the entry; every surviving broker has a real
        // order adapter, so the route IS the delivery list.
        let route: Vec<String> = if self.paper {
            Vec::new()
        } else {
            let usable = crate::brokers::enabled_configured();
            let resolved = crate::brokers::resolve_route(
                &route_map,
                &usable,
                crate::brokers::any_configured(),
            );
            for id in &resolved {
                if !crate::brokers::adapter_ready(id) {
                    self.log_throttled(
                        &format!("broker-adapter-{id}"),
                        60_000,
                        "warn",
                        &format!("broker {id}: no order adapter in this build - entry skipped for it"),
                    );
                }
            }
            let live: Vec<String> = resolved
                .iter()
                .filter(|id| crate::brokers::adapter_ready(id))
                .cloned()
                .collect();
            if live.is_empty() {
                // No deliverable broker: every tick is off / none is fully
                // configured. Refuse instead of quietly falling back to Dhan -
                // "no broker selected" must never mean "send it to Dhan anyway".
                return Err(
                    if resolved.is_empty() {
                        "no order route: Broker Settings me koi broker ON + fully configured nahi hai, ya Order Placement Method me sab untick hain"
                    } else {
                        "no order route: every ticked broker lacks an order adapter in this build"
                    }
                    .to_string(),
                );
            }
            // The Dhan dispatch path below needs the Dhan session; every other
            // broker authenticates from its own stored credentials.
            if live.iter().any(|id| id.eq_ignore_ascii_case("dhan")) {
                client = Some(self.dhan.session_client().await.ok_or(
                    "not connected to Dhan: header Connect karo ya Dhan ka tick hatao",
                )?);
                client_id = self.dhan.session_client_id().await.ok_or("no client id")?;
            }
            live
        };

        let mut strat = strat.clone();
        let mut exch = if strat.exchange_segment.is_empty() { "NSE_FNO".to_string() } else { strat.exchange_segment.clone() };
        // Paper entries fill entirely from the shared live feed: never fall back
        // to a Dhan REST quote. A cold cache just means the subscription's first
        // tick has not landed yet, so wait for it briefly; only if it never
        // arrives does the scan retry on its next pass (paper stays REST-free).
        let mut ltp = self.ltp_of(strat.security_id, &exch);
        if ltp <= 0.0 && self.paper {
            self.dhan
                .subscribe_options(&[(strat.security_id, exch.clone())])
                .await;
            ltp = self.wait_feed_ltp(strat.security_id, &exch, 1_500).await;
        }
        if ltp <= 0.0 && !self.paper {
            ltp = self.fetch_ltp(strat.security_id, &exch).await;
        }
        if ltp <= 0.0 {
            return Err(if self.paper {
                "paper: no live feed LTP yet for entry".into()
            } else {
                "no LTP available".into()
            });
        }

        // Underlying/index strategies: resolve the option contract now from the
        // operator's strike preferences (ATM / ITM / OTM / strike mode).
        if strat.instrument.eq_ignore_ascii_case("INDEX") || strat.exchange_segment.eq_ignore_ascii_case("IDX_I") {
            let resolved = self.resolve_option_strategy(&strat, ltp, &settings, false, false);
            if let Some(res) = resolved {
                strat = res;
                exch = strat.exchange_segment.clone();
                // Stream the contract on the live websocket so paper gets its
                // premium tick without any REST call.
                self.dhan.subscribe_options(&[(strat.security_id, exch.clone())]).await;
                let al = self.ltp_of(strat.security_id, &exch);
                ltp = if al > 0.0 {
                    al
                } else if self.paper {
                    self.wait_feed_ltp(strat.security_id, &exch, 1_500).await
                } else {
                    self.fetch_ltp(strat.security_id, &exch).await
                };
                if ltp <= 0.0 {
                    return Err(if self.paper {
                        "paper: waiting for live feed LTP on resolved option".into()
                    } else {
                        "no LTP for resolved option".into()
                    });
                }
            }
        }
        // Phantom-profit guard: a long option is never worth less than its
        // intrinsic value, so a premium below intrinsic means the option's feed
        // print (or the underlying's) is stale or crossed. Booking an entry on
        // such a print is exactly what produced fake deep-ITM profits - filled at
        // a stale-low premium, then exited at the true higher one when the next
        // print landed. Skip the entry instead of trading on an inconsistent LTP.
        if option_strike_type(&strat.trading_symbol).is_some() && !self.option_premium_sane(&strat, ltp) {
            return Err("stale option LTP (premium below intrinsic); entry skipped".into());
        }
        // Execution-time +green guard: the "Only +green premium strikes" /
        // "Pick fastest positive rising LTP" preference is applied during strike
        // SELECTION, but the chosen leg can reach here from a frozen Leg Book, a
        // saved option strategy or an operator index/commodity path that never
        // re-walked the chain - and the sign can flip between scan and fill.
        // Re-read the leg's PUBLISHED change at the fill so a minus (red) premium
        // can never be booked while the preference is ON. Manual orders are exempt
        // (the operator explicitly chose that contract). A missing quote is not
        // treated as red - the caller has already waited for a live LTP.
        if !strat.manual
            && (settings.only_positive || settings.fastest_rising)
            && is_option_leg(&strat)
        {
            if let Some((_ltp, change, _prev)) = self.leg_quote(&strat) {
                if change < 0.0 {
                    self.log(
                        "warn",
                        &format!(
                            "skip entry {} ({}) - premium change {:.2} is minus; +green filter blocks this leg",
                            strat.name, strat.trading_symbol, change
                        ),
                    );
                    return Err(format!(
                        "minus-premium: {} change {:.2}",
                        strat.trading_symbol, change
                    ));
                }
            }
        }
        // Execution-instant candle re-check: the candle can flip between the scan
        // and the fill (especially for the 200ms delayed paper entry), so the same
        // spot-candle rule is enforced here too - Top Gainer needs a green forming
        // candle, Top Loser a red one. Returns an error so the caller releases the
        // signal and retries on a later scan instead of consuming it.
        if let Some(reason) = self.spot_candle_gate_skip(&settings, &strat).await {
            return Err(format!("candle gate: {reason}"));
        }
        // Execution-instant trend re-check: the tape can roll over between the
        // scan and the fill, so the "trend check before entry" rule is enforced
        // here too. Returns an error so the caller releases the fresh-signal edge
        // and retries on a later scan instead of executing into a flat/opposite
        // trend.
        if let Some(reason) = self.entry_trend_check_skip(&settings, &strat).await {
            return Err(format!("trend check: {reason}"));
        }
        // Execution-instant Indicator-filter re-check: the scan's gate ran on the
        // forming bar, but the paper execution delay and the option-feed LTP
        // warm-up can elapse before the fill, letting the filter stop holding.
        // Block the stale fill here; the caller releases the fresh-signal edge
        // and retries on a later scan instead of booking a signal whose
        // condition has already flipped.
        if !strat.manual && !self.entry_filter_gate_now(&strat).await {
            self.log(
                "info",
                &format!(
                    "skip stale entry {} -> {}: indicator filter no longer holds at fill",
                    strat.name, strat.trading_symbol
                ),
            );
            return Err("stale entry: indicator filter no longer holds".into());
        }
        // Same-contract guard: never open a second entry on an option contract
        // that already has a running position. Checked here (after the contract is
        // fully resolved) so it covers index strategies too, and skipped for
        // Manual Order Placement (operator-driven) and for the explicit
        // "repeat while condition holds" stacking mode.
        if self.duplicate_entry_blocked(&settings, strat.security_id, guard_duplicates) {
            return Err(format!(
                "duplicate: {} {} already running - second entry on the same strike skipped",
                strat.trading_symbol, strat.instrument
            ));
        }
        // Final trend confirmation immediately before execution: the scan's
        // cached trend read can be up to 2.5s old (and a failed REST refresh can
        // serve much older bars), so a side that flipped between scan and fill
        // must never be executed. Fails closed when the live read is neutral,
        // stale, disagreeing, or a flip is still confirming.
        let trend_gate = match self.trend_entry_confirmation(&strat, &settings).await {
            Ok(v) => v,
            Err(reason) => {
                self.log(
                    "warn",
                    &format!(
                        "skip entry {} -> {}: trend confirmation failed - {reason}",
                        strat.name, strat.trading_symbol
                    ),
                );
                return Err(format!("trend confirmation: {reason}"));
            }
        };
        // Publish the exact contract this entry executes on (option premium for
        // index/F&O, or the strategy's own spot) for the Running Strategies view.
        self.record_strat_leg(&strat.id, "trade", &strat);

        let lot = if strat.lot > 0.0 {
            strat.lot
        } else if settings.lot_size > 0.0 {
            settings.lot_size
        } else {
            scrip::get()
                .and_then(|s| s.lot_for(&strat.trading_symbol, &strat.exchange_segment).map(|(l, _)| l))
                .unwrap_or(1.0)
        };
        let mut qty = (settings.lots.max(1.0) * lot).round() as i64;
        // Liquid F&O legs behave exactly like Top Movers unless their own
        // Auto-Lot switch is ON. With it OFF the leg uses the global Auto-Lot
        // config below, so the normal `Lots` / global Auto-Lot keeps applying.
        let (liquid_auto, liquid_oi_pct, liquid_vol_pct) = entry_auto_lot_cfg(&strat, &settings);
        if auto_lots || liquid_auto {
            // Auto Lots = min(volume% lots, OI% lots, margin lots). The two
            // liquidity caps are operator-set percentages; the smaller lot count
            // wins (e.g. volume 2% -> 20 lots, OI 2% -> 10 lots => 10 lots).
            // Margin lots are sized from this tab's shared-margin allotment, and
            // an empty allotment yields 0 lots so the entry is blocked below.
            // When no signal exists the manual lots are kept.
            let (oi_pct, volume_pct) = if liquid_auto {
                (liquid_oi_pct, liquid_vol_pct)
            } else {
                (settings.auto_lot_oi_pct, settings.auto_lot_volume_pct)
            };
            let (_, oi, volume) = self.quote_fields(strat.security_id, &exch);
            let avail = self.margin_budget();
            if let Some(n) = calc_auto_lots(lot, ltp, oi, volume, avail, oi_pct, volume_pct) {
                qty = (n * lot).round() as i64;
            }
        }
        if qty <= 0 {
            return Err("computed quantity is zero".into());
        }

        // --- Brain capital protection (Auto Trading only) -------------------
        // Checked BEFORE margin so a risk-blocked entry costs no broker work.
        if settings.auto_trade_on {
            if let Some(msg) = self.risk_entry_block() {
                self.log("warn", &msg);
                return Err(msg);
            }
        }

        // Risk-based sizing: when the operator set a per-trade risk budget, the
        // STOP distance decides the size instead of the margin. This is what
        // keeps the rupee risk identical in a tight trend and a wide range.
        if settings.auto_trade_on && settings.risk_per_trade > 0.0 {
            let stop_distance = {
                let atr = self
                    .cached_atr(
                        &format!(
                            "{}:{}:{}:{}",
                            strat.security_id,
                            strat.exchange_segment.to_uppercase(),
                            strat.instrument.to_uppercase(),
                            strat.timeframe
                        ),
                        60_000,
                    )
                    .unwrap_or(0.0);
                if atr > 0.0 {
                    brain_risk_mults(&settings).0 * atr
                } else {
                    0.0
                }
            };
            if stop_distance > 0.0 {
                if let Some(risk_qty) = self.risk_sized_qty(ltp, stop_distance, lot, qty) {
                    if risk_qty <= 0 {
                        let msg = format!(
                            "trade blocked: risk budget Rs {:.0} too small for one lot at stop distance {:.2}",
                            settings.risk_per_trade, stop_distance
                        );
                        self.log("warn", &msg);
                        return Err(msg);
                    }
                    qty = risk_qty;
                }
            }
        }

        // Shared-margin gate: the entry is blocked + warned when this tab has no
        // allotment (Rs 0) or when the required margin (qty x price) exceeds what
        // is still free after the running trades.
        if let Some(msg) = self.margin_block_for_qty(qty, ltp) {
            self.log("warn", &msg);
            return Err(msg);
        }

        let side = if strat.side.eq_ignore_ascii_case("SELL") { "SELL" } else { "BUY" };
        let underlying = underlying_of(&strat.trading_symbol, &exch);
        // Strict Target Lab confirmation: the scan already armed this entry from
        // the indicator filter. When the operator asks for double confirmation,
        // require the cached research plan to independently agree before any
        // order (paper or live) is sent. Checked here so a failed confirmation
        // costs no broker round-trip and never consumes the order-rate slot.
        let research_gate = match self.target_research_gate(&settings, &strat, side, &underlying) {
            Ok(v) => v,
            Err(reason) => {
                self.log(
                    "warn",
                    &format!(
                        "skip entry {} -> {}: research confirmation failed - {reason}",
                        strat.name, strat.trading_symbol
                    ),
                );
                return Err(format!("research confirmation: {reason}"));
            }
        };
        let freeze = scrip::freeze_qty(strat.security_id, &underlying);
        // Iceberg slicing: when ON and the entry's total lots reach the
        // operator's slice threshold, split the entry into child slices of
        // `slice_lots` lots each. The paper engines simulate one fill per slice
        // (one position, many child fills, booked at the weighted-average entry);
        // the Realtime engine sends one real child order per slice. The split is
        // recorded on the position so the UI can show it.
        // Liquid F&O legs may use their OWN iceberg config (switch + threshold +
        // slice size) so the liquid basket slices independently of the global
        // setting. The liquid values apply only while the liquid slicing switch
        // is ON; otherwise the global slicing config governs the leg, exactly
        // like Top Movers.
        let (slice_enabled, slice_limit, slice_lots) = entry_slice_cfg(&strat, &settings);
        let slice_plan: Vec<i64> = if slice_enabled {
            paper_slice_plan(qty, lot, slice_limit, slice_lots)
        } else {
            Vec::new()
        };
        let cfg = cfg.get(&method).cloned().unwrap_or(json!({}));
        let corr = corr_id(&strat.id);

        // AI stop/target from recent volatility (ATR) when any AI risk mode is on;
        // `levels_for` then applies the exact precedence: RR > AI TP, and
        // Manual SL / Trail SL floor the stop.
        // Only fetch the ATR when `levels_for` will actually consume it, so a
        // manual SL / Trail SL entry never pays a candle round-trip before the
        // order goes out.
        let need_ai_sl = (settings.ai_sl || settings.sl_auto) && !settings.manual_sl && !settings.manual_trail_sl;
        let need_ai_trail = settings.ai_trail_tp && !settings.manual_trail_sl;
        let need_ai_tp = settings.ai_tp_pct || settings.ai_trail_tp;
        let (ai_sl, ai_tp, _ai_atr, ai_trail) = if need_ai_sl || need_ai_trail || need_ai_tp {
            self.ai_levels(&strat, side, ltp).await.unwrap_or((0.0, 0.0, 0.0, 0.0))
        } else {
            (0.0, 0.0, 0.0, 0.0)
        };
        let (sl, tp, trail, point_trail) =
            levels_for(&settings, &cfg, side, ltp, ai_sl, ai_tp, ai_trail);
        // One position never carries two trails: when the routed brokers own the
        // trail natively (Dhan Super Order `trailingJump`) AND a jump is actually
        // configured, the engine keeps only the fixed entry stop/target and never
        // ratchets a second stop. With no jump configured the broker would trail
        // nothing, so the engine keeps its own trail instead of leaving the
        // position unprotected.
        let broker_trail = crate::brokers::broker_owns_trail(&route, &method, point_trail);
        let trail_owner = if broker_trail { "broker" } else { "engine" };
        let (trail, point_trail_engine) = if broker_trail {
            (0.0, 0.0)
        } else {
            (trail, point_trail)
        };

        let mut order_ids: Vec<String> = Vec::new();
        let mut super_orders: Vec<String> = Vec::new();
        let mut broker = false;
        let mut filled = 0i64;

        // Paper mode: never touch the broker. The entry is simulated at the live
        // LTP with adverse slippage, rejected with the configured probability,
        // and - when filled - the full quantity is booked at the slipped price.
        // Every risk level (SL/TP/trail) is still computed above and enforced
        // locally by `manage_positions`.
        let is_buy_entry = side.eq_ignore_ascii_case("BUY");
        // F&O limit entry (paper only, BUY only - the algo never sells): mirror
        // how Dhan sends an order - above the market so the order is always
        // marketable and fills immediately, exactly like a market order.
        // `fno_limit_px` is 0 when the toggle is off or the side is a sell, and
        // it is never set below the entry.
        let mut fno_limit_px = 0.0;
        if self.paper && settings.fno_limit_order && is_buy_entry {
            fno_limit_px = fno_limit_buy_price(ltp);
        }
        // Per-slice entry ledger (empty when the entry is not sliced). For the
        // paper engines each entry is a simulated child fill; for the Realtime
        // engine each entry is a real child order. Surfaced on the position and
        // carried onto the closed record so the UI can show the split.
        let mut slice_legs: Vec<Value> = Vec::new();
        // The simulated fill is this order's "send" in paper mode: reserve the
        // shared paper-tab slot here so all three books together respect the cap.
        if self.paper {
            order_rate::reserve_wait(Group::Paper).await;
        }
        let paper_fill = if self.paper {
            // A marketable limit is certain to fill, so the F&O mode never
            // simulates a rejection; the plain market path keeps the configured
            // rejection probability.
            let rej_pct = settings.paper_reject_pct.clamp(0.0, 100.0);
            if fno_limit_px <= 0.0
                && rej_pct > 0.0
                && paper_rand01(paper_seed(strat.security_id)) < rej_pct / 100.0
            {
                let msg = format!("paper entry rejected (simulated {rej_pct}% rejection rate)");
                self.log("warn", &msg);
                return Err(msg);
            }
            filled = qty;
            let base = paper_exec_fill(ltp, is_buy_entry, &settings);
            if slice_plan.is_empty() {
                base
            } else {
                let (legs, avg) = paper_slice_fills(&slice_plan, lot, base, now_ms());
                slice_legs = legs;
                avg
            }
        } else {
            0.0
        };
        let exec_price = if self.paper { paper_fill } else { ltp };
        // --- Dispatch -------------------------------------------------------
        //
        // One entry can be routed to several brokers. Two rules keep this safe:
        //
        //   * the operator's lot count is DIVIDED across the routed brokers (a
        //     10-lot entry over 5 ticked brokers sends 2 lots to each), so total
        //     exposure stays exactly what was configured - never N x the size;
        //   * if any broker rejects, the whole entry fails BEFORE a position is
        //     booked, so the book never claims a fill that only partly happened.
        //     Orders already accepted at earlier brokers are cancelled first.
        //
        // Dhan's `super` / `forever` methods are Dhan-specific order shapes, so
        // they only run when Dhan is the sole route; with a mixed route every
        // broker receives the plain (non-bracket) entry and the engine owns the
        // trail, which is exactly what `brokers::native_trail` encodes.
        let dhan_only = route.iter().all(|b| b.eq_ignore_ascii_case("dhan"));
        let mut qty_sent: i64 = 0;
        // Per-broker quantity actually sent, stored on the position so the exit
        // can flatten exactly the same split. Paper never fills it.
        let mut broker_qty: BTreeMap<String, i64> = BTreeMap::new();
        if !self.paper {
            // Dhan orders by security id and never needed the scrip master, so a
            // cold master only blocks the brokers that must translate the
            // contract into their own token.
            let contract = scrip::get().and_then(|s| s.contract(strat.security_id).cloned());
            if contract.is_none() && !dhan_only {
                return Err(format!(
                    "no contract row for security id {} - scrip master is warming or the strike is unknown",
                    strat.security_id
                ));
            }
            let plan = crate::adapters::split_qty(qty, lot, &route);
            if plan.is_empty() {
                return Err("entry qty is smaller than one lot for any routed broker".into());
            }
            // Broker entry orders placed so far, so a later broker's failure can
            // undo them instead of leaving half the position open.
            let mut placed: Vec<(String, String)> = Vec::new();
            let mut failure: Option<String> = None;

            for (broker, part_qty) in plan.iter() {
                let result = if dhan_only {
                    // Dhan keeps its native order shapes (Super Order target/stop
                    // legs, Forever/GTT) because they are Dhan-only products.
                    self.dhan_entry(
                        broker,
                        client.as_ref(),
                        &client_id,
                        &strat,
                        &cfg,
                        &method,
                        &side,
                        &exch,
                        ltp,
                        sl,
                        tp,
                        point_trail,
                        broker_trail,
                        freeze,
                        &slice_plan,
                        *part_qty,
                        lot,
                        &corr,
                        &mut order_ids,
                        &mut super_orders,
                        &mut slice_legs,
                    )
                    .await
                } else {
                    let order_type = cfg_str(&cfg, "orderType", "MARKET");
                    let price = cfg_f(&cfg, "price", 0.0).max(cfg_f(&cfg, "limitPrice", 0.0));
                    let Some(contract) = contract.clone() else {
                        failure = Some(format!(
                            "{broker}: no contract row for security id {sec_id_placeholder}, cannot place",
                            sec_id_placeholder = strat.security_id
                        ));
                        break;
                    };
                    let req = crate::adapters::OrderReq {
                        contract,
                        side: side.to_string(),
                        qty: *part_qty,
                        order_type: if order_type.is_empty() { "MARKET".into() } else { order_type },
                        price,
                        product: cfg_str(&cfg, "product", "INTRADAY"),
                        ltp,
                        correlation: corr_id(&format!("{}{}", corr, broker)),
                    };
                    match crate::adapters::place(broker, &req).await {
                        Ok(p) => {
                            if p.order_id.is_empty() {
                                order_ids.push(format!("{broker}"));
                            } else {
                                order_ids.push(format!("{broker}:{}", p.order_id));
                            }
                            Ok(())
                        }
                        Err(e) => Err(e),
                    }
                };
                match result {
                    Ok(()) => {
                        qty_sent += *part_qty;
                        broker_qty.insert(broker.to_ascii_lowercase(), *part_qty);
                        placed.push((broker.clone(), part_qty.to_string()));
                    }
                    Err(e) => {
                        failure = Some(format!("{broker} rejected the entry: {e}"));
                        break;
                    }
                }
            }
            if let Some(msg) = failure {
                // Undo whatever already landed so the account is not left with a
                // partial position the book does not know about.
                for (broker, _) in &placed {
                    if broker.eq_ignore_ascii_case("dhan") {
                        // Dhan native entries carry bare order ids and a Super
                        // Order is closed through its dedicated endpoint, not the
                        // plain cancel API.
                        if let Some(client) = self.dhan.session_client().await {
                            for oid in super_orders.iter() {
                                self.dhan.dhan_order_throttle().await;
                                if let Err(e) = client.cancel_super_order(oid).await {
                                    self.log(
                                        "warn",
                                        &format!("rollback cancel super {oid} failed: {e}"),
                                    );
                                }
                            }
                            for oid in order_ids.iter() {
                                self.dhan.dhan_order_throttle().await;
                                let _ = client.cancel_order(oid).await;
                            }
                        }
                        continue;
                    }
                    let prefix = format!("{broker}:");
                    let ids: Vec<String> = order_ids
                        .iter()
                        .filter(|id| id.starts_with(&prefix))
                        .filter_map(|id| id.strip_prefix(&prefix).map(|s| s.to_string()))
                        .collect();
                    for id in ids {
                        if let Err(e) = crate::adapters::cancel(broker, &id).await {
                            self.log(
                                "warn",
                                &format!("rollback cancel {broker} {id} failed: {e}"),
                            );
                        }
                    }
                }
                order_ids.clear();
                super_orders.clear();
                slice_legs.clear();
                self.log("warn", &msg);
                return Err(msg);
            }
            broker = true;
            filled = qty_sent.max(0);
        }

        self.dhan
            .subscribe_options(&[(strat.security_id, exch.clone())])
            .await;

        let pos_id = gen_id("rtpos");
        let slice_note = if slice_legs.is_empty() {
            String::new()
        } else {
            let lots = slice_legs
                .first()
                .and_then(|l| l.get("lots"))
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0);
            format!(" (iceberg {} slices x {} lots)", slice_legs.len(), lots)
        };
        let (entry_chg, entry_chg_pct) = self.quote_change(strat.security_id, &exch);
        let mut position = json!({
            "id": pos_id,
            "strategyId": strat.id,
            "strategyName": strat.name,
            "method": method,
            "securityId": strat.security_id,
            "exchangeSegment": exch,
            "instrument": strat.instrument,
            "tradingSymbol": strat.trading_symbol,
            "underlying": underlying,
            "side": side,
            "qty": qty,
            "lots": if lot > 0.0 { (qty as f64 / lot).round() } else { 0.0 },
            "lotSize": lot,
            "filledQty": filled,
            "slices": json!(slice_legs),
            "entry": round2(exec_price),
            "fillPrice": round2(exec_price),
            "ltp": round2(exec_price),
            "sl": round2(sl),
            "overallSl": round2(sl),
            "tp": round2(tp),
            "trail": round2(trail),
            "pointTrail": round2(if broker_trail { point_trail } else { point_trail_engine }),
            "pointTrailBrokerOnly": broker_trail,
            "trailOwner": trail_owner,
            "brokers": route,
            "brokerQty": broker_qty,
            "peakProfit": 0.0,
                "netPeak": 0.0,
            "best": round2(exec_price),
            "orderIds": order_ids,
            "superOrders": super_orders,
            "broker": broker,
            "reconciled": false,
            "status": "running",
            "orderType": if fno_limit_px > 0.0 { "FNO_LIMIT" } else { "MARKET" },
            "limitPrice": fno_limit_px,
            "openedAt": now_ms(),
            "log": [{
                "t": now_ms(),
                "msg": if fno_limit_px > 0.0 {
                    format!("{method} {side} {qty} @ {exec_price} (F&O LIMIT {fno_limit_px}){slice_note}")
                } else {
                    format!("{method} {side} {qty} @ {exec_price}{slice_note}")
                },
            }],
        });
        // Entry-time premium change (sign + %), captured here so the executed-trade
        // list can show which sign the "+green premium" pick actually bought.
        position["ltpChange"] = json!(entry_chg);
        position["ltpChangePct"] = json!(entry_chg_pct);
        // Freeze the entry-side brain regime so the exit suite can detect a
        // trend<->range flip later. Empty when the brain had no fresh read.
        position["entryRegime"] = json!(settings.brain_regime.clone());
        position["breakevenDone"] = json!(false);
        position["partialDone"] = json!(false);
        // Freeze the SAME-SIDE indicator filters that armed this entry, so the
        // optional "exit on filter flip" rule re-evaluates exactly the rules that
        // justified the trade - not whatever the operator ticks later.
        {
            let bull_side = premium_only_for(&strat, &settings) || side.eq_ignore_ascii_case("BUY");
            let keys: Vec<String> = settings
                .filters
                .iter()
                .filter(|(k, v)| {
                    **v && !is_stream_flag(k)
                        && (if bull_side { filter_is_bull(k) } else { filter_is_bear(k) })
                })
                .map(|(k, _)| k.clone())
                .collect();
            position["entryFilters"] = json!(keys);
            // Freeze the timeframe + instrument the entry was evaluated on, so the
            // optional filter-flip exit re-reads the SAME series instead of
            // guessing a default.
            position["timeframe"] = json!(engine_tf(&settings, &strat));
            position["instrument"] = json!(strat.instrument);
        }
        if let Some(gate) = trend_gate {
            position["trendGate"] = gate;
        }
        if let Some(gate) = research_gate {
            position["researchGate"] = gate;
        }
        // Target Lab auto-exit: freeze the cached research target on the position
        // at entry; `manage_positions` attaches it later if the cache was cold
        // here or auto-cut was enabled after this trade opened. Buy-only book: an actual BUY trade can receive either a call
        // plan (BUY CE / BUY futures) or a put plan (BUY PE), never a sell leg.
        if settings.target_auto_on {
            if let Some(plan) = crate::target::plan_for_underlying(&underlying) {
                let conf = plan.get("confidence").and_then(|v| v.as_f64()).unwrap_or(0.0);
                let pdir = plan.get("direction").and_then(|v| v.as_i64()).unwrap_or(0);
                let exp = option_exposure_dir(&side, &strat.trading_symbol);
                let tsid = plan.get("securityId").and_then(|v| v.as_i64()).unwrap_or(0);
                let tseg = plan.get("exchangeSegment").and_then(|v| v.as_str()).unwrap_or("");
                let spot = if tsid > 0 { self.ltp_of(tsid, tseg) } else { 0.0 };
                let econ = target_econ(
                    &plan,
                    &side,
                    &strat.trading_symbol,
                    &strat.instrument,
                    exec_price,
                    qty as f64,
                    spot,
                    self.paper,
                    settings.paper_slippage_bps,
                    PaperSpread::from(&settings),
                );
                if side.eq_ignore_ascii_case("BUY")
                    && pdir.abs() == 1
                    && exp == pdir as i32
                    && conf >= settings.target_min_confidence
                    && target_plan_gap_ok(&plan, exp, spot)
                    && econ.get("ok").and_then(|v| v.as_bool()).unwrap_or(false)
                {
                    position["targetPlan"] = plan;
                    position["targetEcon"] = econ;
                }
            }
        }
        let placed = self.et_placed.fetch_add(1, Ordering::Relaxed) + 1;
        self.entries_placed.fetch_add(1, Ordering::Relaxed);
        self.last_entry_ms.store(now_ms(), Ordering::Relaxed);
        if let Some(mut d) = self.doc() {
            d.positions.push(position);
            let pending = self.take_entry_timing(&strat.id, origin_id);
            if let Some((met_at, at_meet)) = pending {
                d.entry_timing.insert(
                    0,
                    json!({
                        "strategyId": strat.id,
                        "strategyName": strat.name,
                        "side": side,
                        "metAt": met_at,
                        "entryAt": now_ms(),
                        "delayMs": (now_ms() - met_at).max(0),
                        "ordersWindow": (placed - 1) - at_meet,
                        "status": "entered",
                    }),
                );
                if d.entry_timing.len() > 60 {
                    d.entry_timing.truncate(60);
                }
            }
        }
        self.save();
        self.log("info", &format!("opened {} {} {} @ {:.2}", strat.name, side, qty, ltp));
        Ok(())
    }

    /// Dhan-only entry dispatch, kept byte-for-byte in behaviour with the
    /// original inline block so Super Order target/stop legs, Forever/GTT and
    /// iceberg slicing behave exactly as before. `part_qty` is the quantity
    /// routed to Dhan (the whole entry when Dhan is the only route).
    #[allow(clippy::too_many_arguments)]
    async fn dhan_entry(
        &self,
        broker: &str,
        client: Option<&dhan_hq::DhanClient>,
        client_id: &str,
        strat: &Strategy,
        cfg: &Value,
        method: &str,
        side: &str,
        exch: &str,
        ltp: f64,
        sl: f64,
        tp: f64,
        point_trail: f64,
        broker_trail: bool,
        freeze: f64,
        slice_plan: &[i64],
        part_qty: i64,
        lot: f64,
        corr: &str,
        order_ids: &mut Vec<String>,
        super_orders: &mut Vec<String>,
        slice_legs: &mut Vec<Value>,
    ) -> Result<(), String> {
        let _ = broker;
        let Some(client) = client else {
            return Err("Dhan is not connected: header Connect karo".into());
        };
        let mut filled = 0i64;
            match method {
                "super" => {
                    // Operator toggles are authoritative at the broker too. Dhan
                    // requires a positive target/stop leg, so a disabled target is
                    // parked far away instead of being invented from the method
                    // config (the "target keeps firing after I disabled it" bug).
                    // The Take-Profit target now comes only from RR / AI TP;
                    // the manual "Take Profit %" card is gone.
                    let target = tp;
                    let target = if target > 0.0 { target } else { price_off(ltp, side, 2.0) };
                    // Stop leg: the resolved overall/AI SL first, then an explicitly
                    // configured manual stop. With no SL configured a far protective
                    // price is used so the leg never acts as a surprise tight stop.
                    let stop = if sl > 0.0 {
                        sl
                    } else if self.doc().map(|d| d.settings.manual_sl).unwrap_or(false) && cfg_f(&cfg, "stopLossPrice", 0.0) > 0.0 {
                        cfg_f(&cfg, "stopLossPrice", 0.0)
                    } else if self.doc().map(|d| d.settings.manual_sl).unwrap_or(false) && cfg_f(&cfg, "slPct", 0.0) > 0.0 {
                        price_off(ltp, side, -cfg_f(&cfg, "slPct", 0.0) / 100.0)
                    } else {
                        price_off(ltp, side, -0.5)
                    };

                    // Child-order sizing: the engine-level "Auto Order Slicing" plan
                    // wins; otherwise fall back to the method's own auto-slice /
                    // exchange-freeze chunking. Each child super order keeps its own
                    // native target + stop leg.
                    let method_chunk = {
                        let auto_slice = cfg.get("autoSlice").and_then(|v| v.as_bool()).unwrap_or(false)
                            || cfg_f(&cfg, "autoSlice", 0.0) > 0.0;
                        let slice_ov = cfg_f(&cfg, "sliceQty", 0.0) as i64;
                        if auto_slice && slice_ov > 0 {
                            slice_ov
                        } else if auto_slice && freeze > 0.0 {
                            freeze as i64
                        } else {
                            0
                        }
                    };
                    let pieces = order_pieces(part_qty, &slice_plan, method_chunk);
                    let sliced = pieces.len() > 1;
                    let super_px = {
                        let p = cfg_f(&cfg, "price", 0.0);
                        if p > 0.0 { p } else { round2(ltp) }
                    };
                    for (i, piece) in pieces.into_iter().enumerate() {
                        let child_corr = if sliced { format!("{corr}-s{}", i + 1) } else { corr.to_string() };
                        let body = json!({
                            "dhanClientId": client_id,
                            "transactionType": side,
                            "exchangeSegment": exch,
                            "productType": product_from(cfg_str(&cfg, "product", "INTRADAY")),
                            "orderType": order_type_from(cfg_str(&cfg, "orderType", "MARKET")),
                            "securityId": strat.security_id.to_string(),
                            "quantity": piece,
                            "price": super_px,
                            "targetPrice": round2(target.max(0.05)),
                            "stopLossPrice": round2(stop.max(0.05)),
                            "trailingJump": if broker_trail { point_trail } else { 0.0 },
                            "correlationId": child_corr,
                        });
                        self.dhan.dhan_order_throttle().await;
                        let resp = client.place_super_order(&body).await.map_err(|e| e.to_string())?;
                        let oid = resp.get("orderId").and_then(|v| v.as_str()).unwrap_or("").to_string();
                        if !oid.is_empty() {
                            super_orders.push(oid.clone());
                        }
                        if sliced {
                            slice_legs.push(json!({
                                "qty": piece,
                                "lots": if lot > 0.0 { round2(piece as f64 / lot) } else { 0.0 },
                                "orderId": oid,
                            }));
                        }
                    }
                    let _ = filled;
                }
                "forever" => {
                    let otype = cfg_str(&cfg, "orderType", "LIMIT");
                    let px = cfg_f(&cfg, "price", 0.0);
                    let px = if px > 0.0 { px } else { cfg_f(&cfg, "limitPrice", round2(ltp)) };
                    let pieces = order_pieces(part_qty, &slice_plan, 0);
                    let sliced = pieces.len() > 1;
                    for (i, piece) in pieces.into_iter().enumerate() {
                        let child_corr = if sliced { format!("{corr}-s{}", i + 1) } else { corr.to_string() };
                        let body = json!({
                            "dhanClientId": client_id,
                            "transactionType": side,
                            "exchangeSegment": exch,
                            "productType": product_from(cfg_str(&cfg, "product", "CNC")),
                            "orderType": otype,
                            "securityId": strat.security_id.to_string(),
                            "quantity": piece,
                            "price": px,
                            "triggerPrice": cfg_f(&cfg, "triggerPrice", 0.0),
                            "validity": cfg_str(&cfg, "validity", "DAY"),
                            "correlationId": child_corr,
                        });
                        self.dhan.dhan_order_throttle().await;
                        let resp = client.place_forever(&body).await.map_err(|e| e.to_string())?;
                        let oid = resp.get("orderId").and_then(|v| v.as_str()).unwrap_or("").to_string();
                        if !oid.is_empty() {
                            order_ids.push(oid.clone());
                        }
                        if sliced {
                            slice_legs.push(json!({
                                "qty": piece,
                                "lots": if lot > 0.0 { round2(piece as f64 / lot) } else { 0.0 },
                                "orderId": oid,
                            }));
                        }
                    }
                }
                _ => {
                    let otype = cfg_str(&cfg, "orderType", "MARKET");
                    let mut px = cfg_opt_f(&cfg, "price").or_else(|| cfg_opt_f(&cfg, "limitPrice"));
                    let mut trig = cfg_opt_f(&cfg, "triggerPrice").or_else(|| cfg_opt_f(&cfg, "limitPrice"));
                    if otype.eq_ignore_ascii_case("MARKET") {
                        px = None;
                    }
                    if otype.eq_ignore_ascii_case("LIMIT") && px.is_none() {
                        px = Some(round2(ltp));
                    }
                    if otype.eq_ignore_ascii_case("SL") || otype.eq_ignore_ascii_case("SL-M") {
                        if trig.is_none() {
                            trig = px;
                        }
                    }
                    let disclosed = cfg_opt_f(&cfg, "disclosedQty").map(|v| v as i64).filter(|v| *v > 0);
                    let pieces = order_pieces(part_qty, &slice_plan, 0);
                    let sliced = pieces.len() > 1;
                    for (i, piece) in pieces.into_iter().enumerate() {
                        let child_corr = if sliced { format!("{corr}-s{}", i + 1) } else { corr.to_string() };
                        let req = OrderRequest {
                            dhan_client_id: client_id.to_string(),
                            correlation_id: Some(child_corr),
                            transaction_type: txn(side),
                            exchange_segment: seg_from(&exch),
                            product_type: product_from(cfg_str(&cfg, "product", "INTRADAY")),
                            order_type: order_type_from(otype.clone()),
                            validity: validity_from(cfg_str(&cfg, "validity", "DAY")),
                            security_id: strat.security_id.to_string(),
                            quantity: piece,
                            disclosed_quantity: disclosed,
                            price: px,
                            trigger_price: trig,
                            after_market_order: None,
                            amo_time: None,
                            bo_profit_value: None,
                            bo_stop_loss_value: None,
                        };
                        self.dhan.dhan_order_throttle().await;
                        if method == "slice" || (freeze > 0.0 && piece as f64 > freeze) {
                            let resps = client.slice_order(&req).await.map_err(|e| e.to_string())?;
                            for r in resps {
                                order_ids.push(r.order_id.clone());
                            }
                        } else {
                            let r = client.place_order(&req).await.map_err(|e| e.to_string())?;
                            order_ids.push(r.order_id.clone());
                        }
                        if sliced {
                            slice_legs.push(json!({
                                "qty": piece,
                                "lots": if lot > 0.0 { round2(piece as f64 / lot) } else { 0.0 },
                            }));
                        }
                    }
                }
            }

        Ok(())
    }


/// Split `total` units across `route` in proportion to each broker's open
/// quantity, using largest-remainder so the parts always sum to exactly `total`
/// and no broker is asked for more than it holds.
fn apportion(total: i64, held: &BTreeMap<String, i64>, route: &[String]) -> BTreeMap<String, i64> {
    let mut out: BTreeMap<String, i64> = BTreeMap::new();
    let held_sum: i64 = route
        .iter()
        .filter_map(|b| held.get(&b.to_ascii_lowercase()).copied())
        .filter(|q| *q > 0)
        .sum();
    if total <= 0 || held_sum <= 0 {
        return out;
    }
    let total = total.min(held_sum);
    let mut used = 0i64;
    let mut remainders: Vec<(i64, String)> = Vec::new();
    for b in route {
        let key = b.to_ascii_lowercase();
        let h = held.get(&key).copied().filter(|q| *q > 0).unwrap_or(0);
        if h == 0 {
            continue;
        }
        let exact = total as i128 * h as i128;
        let part = (exact / held_sum as i128) as i64;
        let rem = (exact % held_sum as i128) as i64;
        out.insert(key.clone(), part);
        used += part;
        remainders.push((rem, key));
    }
    remainders.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    let mut left = total - used;
    for (_, key) in remainders {
        if left <= 0 {
            break;
        }
        *out.entry(key).or_insert(0) += 1;
        left -= 1;
    }
    out.retain(|_, q| *q > 0);
    out
}

    async fn close_position(&self, id: &str, reason: &str, exit_price: f64) -> Result<(), String> {
        self.close_position_ex(id, reason, exit_price, None, None).await
    }

    /// Book only `qty` units of an open trade (brain partial profit) and keep the
    /// remainder running. The partial slice goes through the exact same exit path
    /// as a full close (charges, ledger row, broker order), so the books stay
    /// consistent.
    async fn close_position_partial(
        &self,
        id: &str,
        reason: &str,
        exit_price: f64,
        qty: i64,
    ) -> Result<(), String> {
        self.close_position_ex(id, reason, exit_price, None, Some(qty))
            .await
    }

    /// Close a trade on the broker (`recovered = None`) or book an exit the broker
    /// already settled while we were disconnected (`recovered = Some(exit ids)`):
    /// the recovered path sends no new order and never leaves the row "pending".
    /// Both paths share the whole bookkeeping tail.
    async fn close_position_ex(
        &self,
        id: &str,
        reason: &str,
        exit_price: f64,
        recovered: Option<Vec<String>>,
        partial_qty: Option<i64>,
    ) -> Result<(), String> {
        let (pos, settings, cfg_map, method) = {
            let Some(mut d) = self.doc() else { return Err("state lock".into()) };
            let Some(idx) = d.positions.iter().position(|p| js(p, "id") == id) else {
                return Ok(());
            };
            // Atomically claim the position so the 50ms guardian, the broker
            // reconciliation and an operator square-off can never fire two exit
            // orders for the same trade.
            if js(&d.positions[idx], "status").eq_ignore_ascii_case("closing") {
                return Ok(());
            }
            d.positions[idx]["status"] = json!("closing");
            let p = d.positions[idx].clone();
            (p, d.settings.clone(), d.order_cfg.clone(), d.method.clone())
        };
        // Paper exits are simulated, but they still consume this group's shared
        // one-second budget so all three paper books stay inside the same cap.
        // Reserved only AFTER the position is atomically claimed as "closing",
        // so a repeated guardian pass cannot burn extra slots. A recovered exit
        // books an already-settled broker fill and sends nothing.
        if self.paper && recovered.is_none() {
            order_rate::reserve_wait(Group::Paper).await;
        }
        let m = js(&pos, "method");
        let method = if m.is_empty() { method } else { m };
        let side = js(&pos, "side");
        let full_qty = ji(&pos, "qty");
        // A partial booking closes only part of the position; the rest stays open.
        let partial = partial_qty.map(|q| q.clamp(1, full_qty.max(1)));
        let qty = partial.unwrap_or(full_qty);
        let sec_id = ji(&pos, "securityId");
        let exch = js(&pos, "exchangeSegment");
        let entry = jf(&pos, "fillPrice").max(jf(&pos, "entry"));
        // Never book a fake near-zero exit when the live mark is missing. The
        // option feed can briefly drop a strike (illiquid / unsubscribed), and
        // `paper_fill_price` floors a 0 mark to 0.05 - which would fake a 100%
        // loss on a fully healthy position. Fall back to the last stored LTP,
        // then to the entry price.
        let exit_price = if exit_price > 0.0 {
            exit_price
        } else {
            let stored = jf(&pos, "ltp");
            if stored > 0.0 {
                stored
            } else {
                entry
            }
        };
        let broker = jb(&pos, "broker");
        let cfg = cfg_map.get(&method).cloned().unwrap_or(json!({}));
        let is_buy = side == "BUY";
        // Paper exits fill at the mark with the bid/ask spread crossed and then
        // adverse slippage applied. The exit order is the opposite side of the
        // position (a BUY position sells, a SELL position buys), so pass
        // `!is_buy` to get the adverse direction.
        let exit_price = if self.paper {
            paper_exec_fill(exit_price, !is_buy, &settings)
        } else {
            exit_price
        };
        let pnl = if is_buy { (exit_price - entry) * qty as f64 } else { (entry - exit_price) * qty as f64 };

        // Per-broker slice of a partial exit; filled below only when a partial
        // is booked against a position that knows its broker split.
        let mut partial_alloc: BTreeMap<String, i64> = BTreeMap::new();
        // Send the exit order. Square-off by the operator is always allowed,
        // even if the engine was disarmed after the entry. Paper mode books the
        // exit locally at `exit_price` and never touches the broker.
        //
        // A recovered exit is the exception: the broker already flattened this
        // trade while the feed was down (the native Super-Order stop leg fired,
        // or it was closed manually), so we book it as-is and send nothing - a
        // new order here would flip the account into the opposite position.
        let mut exit_order_ids: Vec<String> = Vec::new();
        let mut exit_errors: Vec<String> = Vec::new();
        if let Some(recovered) = recovered {
            exit_order_ids = recovered;
        } else if !self.paper {
            let route: Vec<String> = pos
                .get("brokers")
                .and_then(|v| v.as_array())
                .map(|a| {
                    a.iter()
                        .filter_map(|x| x.as_str())
                        .filter(|id| !id.is_empty())
                        .map(|id| id.to_ascii_lowercase())
                        .collect()
                })
                .unwrap_or_default();
            // A position booked before routing existed carries no `brokers`
            // list; it was Dhan-only by definition.
            let route = if route.is_empty() { vec!["dhan".to_string()] } else { route };
            let exit_side = if is_buy { "SELL" } else { "BUY" };
            let contract = scrip::get().and_then(|s| s.contract(sec_id).cloned());
            // Mirror the entry split: each broker is flattened for exactly the
            // quantity it received. Positions booked before per-broker tracking
            // (or a single-broker Dhan entry) fall back to the whole qty.
            let per_broker: BTreeMap<String, i64> = pos
                .get("brokerQty")
                .and_then(|v| v.as_object())
                .map(|m| {
                    m.iter()
                        .filter_map(|(k, v)| v.as_i64().map(|q| (k.to_ascii_lowercase(), q)))
                        .collect()
                })
                .unwrap_or_default();
            // A partial booking must only flatten its share on each broker: if
            // 3 of 10 lots are booked, each broker that holds 5 gives back 1 or 2,
            // never its full 5.
            if partial.is_some() && !per_broker.is_empty() {
                partial_alloc = Self::apportion(qty, &per_broker, &route);
            }
            for target in &route {
                let key = target.to_ascii_lowercase();
                let tqty = if partial.is_some() && !per_broker.is_empty() {
                    partial_alloc.get(&key).copied().unwrap_or(0)
                } else {
                    per_broker.get(&key).copied().filter(|q| *q > 0).unwrap_or(qty)
                };
                if tqty <= 0 {
                    continue;
                }
                if target.eq_ignore_ascii_case("dhan") {
                    let Some(client) = self.dhan.session_client().await else {
                        exit_errors.push("dhan: not connected".to_string());
                        continue;
                    };
                    let client_id = self.dhan.session_client_id().await.unwrap_or_default();
                    if broker {
                        // Cancel both protective legs, then flatten any residual entry.
                        for so in jarr(&pos, "superOrders") {
                            if let Some(oid) = so.as_str() {
                                self.dhan.dhan_order_throttle().await;
                                let _ = client.cancel_super_order(oid).await;
                            }
                        }
                    }
                    let req = OrderRequest {
                        dhan_client_id: client_id,
                        correlation_id: Some(corr_id(&format!("exit{id}"))),
                        transaction_type: txn(exit_side),
                        exchange_segment: seg_from(&exch),
                        product_type: product_from(cfg_str(&cfg, "product", "INTRADAY")),
                        order_type: OrderType::Market,
                        validity: Validity::Day,
                        security_id: sec_id.to_string(),
                        quantity: tqty,
                        disclosed_quantity: None,
                        price: None,
                        trigger_price: None,
                        after_market_order: None,
                        amo_time: None,
                        bo_profit_value: None,
                        bo_stop_loss_value: None,
                    };
                    self.dhan.dhan_order_throttle().await;
                    let underlying = js(&pos, "underlying");
                    let freeze = scrip::freeze_qty(sec_id, &underlying);
                    if freeze > 0.0 && tqty as f64 > freeze {
                        if let Ok(rs) = client.slice_order(&req).await {
                            for r in rs {
                                exit_order_ids.push(r.order_id);
                            }
                        }
                    } else if let Ok(r) = client.place_order(&req).await {
                        exit_order_ids.push(r.order_id);
                    } else {
                        exit_errors.push("dhan: exit order rejected".to_string());
                    }
                } else {
                    let Some(contract) = contract.clone() else {
                        exit_errors.push(format!(
                            "{target}: no contract row for security id {sec_id}, cannot exit"
                        ));
                        continue;
                    };
                    let req = crate::adapters::OrderReq {
                        contract,
                        side: exit_side.to_string(),
                        qty: tqty,
                        order_type: "MARKET".to_string(),
                        price: 0.0,
                        product: cfg_str(&cfg, "product", "INTRADAY"),
                        ltp: exit_price,
                        correlation: corr_id(&format!("exit{id}{target}")),
                    };
                    match crate::adapters::place(target, &req).await {
                        Ok(p) => {
                            if !p.order_id.is_empty() {
                                exit_order_ids.push(format!("{target}:{}", p.order_id));
                            }
                        }
                        Err(e) => exit_errors.push(format!("{target}: {e}")),
                    }
                }
            }
            if !exit_errors.is_empty() {
                self.log(
                    "error",
                    &format!(
                        "exit {id} could not be delivered to every broker: {}",
                        exit_errors.join("; ")
                    ),
                );
            }
        }

        // Paper trades book an estimated round-trip charge so the wallet and the
        // realized total reflect net P&L exactly like the Closed Trades table —
        // unless the shared "Deduct Dhan charges" toggle is off, in which case the
        // trade is banked gross (netPnl stays null, no charges). Real trades
        // settle charges broker-side, so their net equals the gross.
        let instrument = js(&pos, "instrument");
        let trading_symbol = js(&pos, "tradingSymbol");
        let tc = if self.paper && settings.broker_charges {
            compute_charges_for_trade(
                entry,
                exit_price,
                qty as f64,
                &side,
                &instrument,
                &trading_symbol,
                pnl,
            )
        } else {
            None
        };
        let charges = tc.as_ref().map(|c| c.total).unwrap_or(0.0);
        let net_pnl = if self.paper {
            if settings.broker_charges {
                Some(round2(pnl - charges))
            } else {
                None
            }
        } else {
            Some(round2(pnl))
        };

        let mut closed = json!({
            "id": gen_id("rtclosed"),
            "positionId": id,
            "strategyId": js(&pos, "strategyId"),
            "strategyName": js(&pos, "strategyName"),
            "method": method,
            "securityId": sec_id,
            "exchangeSegment": exch,
            "instrument": instrument,
            "tradingSymbol": trading_symbol,
            "side": side,
            "qty": qty,
            "lots": ji(&pos, "lots"),
            "lotSize": jf(&pos, "lotSize"),
            "entry": round2(entry),
            "exit": round2(exit_price),
            "pnl": round2(pnl),
            "charges": charges,
            "netPnl": net_pnl,
            "chargesSegment": tc.as_ref().map(|c| c.segment).unwrap_or(""),
            "chargesEntry": tc.as_ref().map(|c| c.entry.to_json()).unwrap_or(serde_json::Value::Null),
            "chargesExit": tc.as_ref().map(|c| c.exit.to_json()).unwrap_or(serde_json::Value::Null),
            "reason": reason,
            "exitOrderIds": exit_order_ids,
            "exitPending": !exit_order_ids.is_empty(),
            "openedAt": ji(&pos, "openedAt"),
            "closedAt": now_ms(),
        });
        // Carry the entry-time premium change onto the closed record so the
        // executed-trade list keeps showing the sign the trade was taken on.
        closed["ltpChange"] = json!(jf(&pos, "ltpChange"));
        closed["ltpChangePct"] = json!(jf(&pos, "ltpChangePct"));
        // Carry the frozen Target Lab plan onto the closed ledger so the UI can
        // prove which exits were actually driven by the underlying target
        // (TREND_TARGET) instead of an ordinary SL / trail / Net TP.
        closed["targetPlan"] = pos.get("targetPlan").cloned().unwrap_or(Value::Null);
        closed["targetEcon"] = pos.get("targetEcon").cloned().unwrap_or(Value::Null);
        if reason == "TREND_TARGET" {
            if let Some(plan) = pos.get("targetPlan") {
                let tsid = plan.get("securityId").and_then(|v| v.as_i64()).unwrap_or(0);
                let tseg = plan.get("exchangeSegment").and_then(|v| v.as_str()).unwrap_or("");
                let spot = if tsid > 0 { self.ltp_of(tsid, tseg) } else { 0.0 };
                closed["targetExitSpot"] = json!(round2(spot));
            }
        }
        // Carry the entry slice ledger onto the closed record so the Closed Trades
        // table keeps showing how the entry was split.
        closed["slices"] = pos.get("slices").cloned().unwrap_or(json!([]));
        // Carry the entry order type (MARKET / FNO_LIMIT) and its limit price onto
        // the closed record so the Closed Trades list keeps showing that the entry
        // was placed as an F&O limit order.
        closed["orderType"] = pos.get("orderType").cloned().unwrap_or(json!("MARKET"));
        // Which brokers this trade was routed to, and who owned its trail, so the
        // ledger proves the routing decision instead of inferring it.
        closed["brokers"] = pos.get("brokers").cloned().unwrap_or(json!([]));
        closed["trailOwner"] = pos.get("trailOwner").cloned().unwrap_or(json!("engine"));
        closed["limitPrice"] = pos.get("limitPrice").cloned().unwrap_or(json!(0.0));
        // Carry the stop-loss / trail levels onto the closed record so the Closed
        // Trades table can show the SL that was applied in BOTH points and percent
        // (the % -> points conversion). `sl` is the effective level at close
        // (possibly trailed); `overallSl` the immutable entry-time floor.
        closed["sl"] = pos.get("sl").cloned().unwrap_or(json!(0.0));
        closed["overallSl"] = pos.get("overallSl").cloned().unwrap_or(json!(0.0));
        closed["trail"] = pos.get("trail").cloned().unwrap_or(json!(0.0));
        closed["pointTrail"] = pos.get("pointTrail").cloned().unwrap_or(json!(0.0));
        closed["pointTrailLive"] = pos.get("pointTrailLive").cloned().unwrap_or(json!(0.0));
        let closed_strategy = js(&pos, "strategyId");
        // --- Realised feedback ledger -------------------------------------
        // Every closed trade updates the objective bucket the brain will blend
        // with its candle backtest. Buckets are keyed by regime + instrument
        // class + side so a lesson learned in a trend is not applied to chop.
        {
            let inst_class = instrument_class(&instrument, &trading_symbol);
            let regime = {
                let r = js(&pos, "entryRegime");
                if r.is_empty() {
                    settings.brain_regime.clone()
                } else {
                    r
                }
            };
            let key = crate::brain::evidence_key(&regime, inst_class, &side);
            let net_for_ledger = net_pnl.unwrap_or(pnl);
            let risk_per_unit = (entry - jf(&pos, "overallSl")).abs();
            let r_mult = if risk_per_unit > 0.0 {
                let move_ = if is_buy { exit_price - entry } else { entry - exit_price };
                move_ / risk_per_unit
            } else {
                0.0
            };
            if let Some(mut d) = self.doc() {
                d.evidence
                    .entry(key)
                    .or_default()
                    .record(net_for_ledger, r_mult);
            }
        }
        if let Some(mut d) = self.doc() {
            if let Some(part) = partial {
                // Partial: shrink the live position, keep it running, and remember
                // that the partial has been taken so the brain never repeats it.
                if let Some(p) = d.positions.iter_mut().find(|p| js(p, "id") == id) {
                    let remain = (full_qty - part).max(0);
                    p["qty"] = json!(remain);
                    p["filledQty"] = json!(remain);
                    let lot = jf(p, "lotSize");
                    p["lots"] = if lot > 0.0 { json!((remain as f64 / lot).round()) } else { json!(0.0) };
                    // Keep the per-broker ledger in step with the reduced qty so
                    // the next exit (or a later full close) flattens only what is
                    // still open at each broker.
                    if !partial_alloc.is_empty() {
                        if let Some(m) = p.get_mut("brokerQty").and_then(|v| v.as_object_mut()) {
                            for (broker, closed_qty) in &partial_alloc {
                                if let Some(cur) = m.get_mut(broker).and_then(|v| v.as_i64()) {
                                    let left = (cur - closed_qty).max(0);
                                    m.insert(broker.clone(), json!(left));
                                }
                            }
                            m.retain(|_, v| v.as_i64().unwrap_or(0) > 0);
                        }
                    }
                    p["partialDone"] = json!(true);
                    p["status"] = json!("running");
                }
            } else {
                d.positions.retain(|p| js(p, "id") != id);
            }
            d.closed.push(closed);
        }
        // "Re-entry cooldown": start (or extend) the post-close window on the
        // strategy this position belonged to. Stamped at every close path
        // (SL / trail / square-off / broker recovery) because they all funnel
        // through here.
        if settings.entry_cooldown_on && !closed_strategy.is_empty() {
            self.mark_entry_cooldown(&closed_strategy, settings.entry_cooldown_secs);
        }
        self.save();
        self.log("info", &format!("closed {id} {reason} pnl {pnl:.2}"));
        if !self.paper {
            // Immediate shared positions refresh after every exit attempt, so
            // the account view confirms the fill/rejection without waiting 2s.
            self.dhan.kick_positions();
        }
        Ok(())
    }

    async fn square_off_all(&self, reason: &str) {
        // Snapshot the broker's net positions (and the engine's own signed qty per
        // security) BEFORE flattening the engine book, so any leftover that the
        // engine does not account for - a manual Dhan trade, or the uncovered part
        // of a security the engine also holds - can be squared off too.
        let engine_signed: HashMap<i64, i64> = self
            .doc()
            .map(|d| {
                d.positions
                    .iter()
                    .filter_map(|p| {
                        let sid = ji(p, "securityId");
                        if sid <= 0 {
                            return None;
                        }
                        let qty = ji(p, "qty");
                        let signed = if js(p, "side") == "BUY" { qty } else { -qty };
                        Some((sid, signed))
                    })
                    .collect()
            })
            .unwrap_or_default();
        let broker_snapshot = self
            .broker_positions
            .lock()
            .map(|p| p.clone())
            .unwrap_or_default();

        let ids: Vec<String> = {
            let Some(d) = self.doc() else { return };
            d.positions.iter().map(|p| js(p, "id")).collect()
        };
        for id in ids {
            let ltp = self.position_ltp(&id);
            let _ = self.close_position(&id, reason, ltp).await;
        }
        self.square_off_broker_residuals(&broker_snapshot, &engine_signed, reason)
            .await;
    }

    /// Flatten broker positions the engine does not account for (manual Dhan
    /// trades and any residual net qty on a security the engine also holds).
    async fn square_off_broker_residuals(
        &self,
        broker: &[Value],
        engine_signed: &HashMap<i64, i64>,
        reason: &str,
    ) {
        // Paper trading has no broker positions to flatten.
        if self.paper {
            return;
        }
        let Some(client) = self.dhan.session_client().await else {
            return;
        };
        let client_id = self.dhan.session_client_id().await.unwrap_or_default();
        for p in broker {
            let sid = ji(p, "securityId");
            if sid <= 0 {
                continue;
            }
            let net = ji(p, "netQty");
            let residual = net - engine_signed.get(&sid).copied().unwrap_or(0);
            if residual == 0 {
                continue;
            }
            let seg = js(p, "exchangeSegment");
            let product = js(p, "productType");
            let side = if residual > 0 { "SELL" } else { "BUY" };
            let qty = residual.abs();
            let req = OrderRequest {
                dhan_client_id: client_id.clone(),
                correlation_id: Some(corr_id(&format!("sq{sid}"))),
                transaction_type: txn(side),
                exchange_segment: seg_from(&seg),
                product_type: product_from(&product),
                order_type: OrderType::Market,
                validity: Validity::Day,
                security_id: sid.to_string(),
                quantity: qty,
                disclosed_quantity: None,
                price: None,
                trigger_price: None,
                after_market_order: None,
                amo_time: None,
                bo_profit_value: None,
                bo_stop_loss_value: None,
            };
            self.dhan.dhan_order_throttle().await;
            let underlying = js(p, "tradingSymbol");
            let freeze = scrip::freeze_qty(sid, &underlying);
            let sent = if freeze > 0.0 && qty as f64 > freeze {
                client.slice_order(&req).await.map(|_| ()).map_err(|e| e.to_string())
            } else {
                client.place_order(&req).await.map(|_| ()).map_err(|e| e.to_string())
            };
            match sent {
                Ok(()) => self.log(
                    "warn",
                    &format!("square-off {} {} {} ({}) manual/residual", side, qty, js(p, "tradingSymbol"), reason),
                ),
                Err(e) => self.log(
                    "error",
                    &format!("square-off {} {} failed: {e}", js(p, "tradingSymbol"), sid),
                ),
            }
        }
    }
}

impl RtDoc {
    fn strategy_time_ok(&self) -> bool {
        let now = ist_minutes();
        let sessions = &self.settings.trade_sessions;
        // A live session list is the single authority for entry timing (the UI
        // disables the old single gate while sessions exist), so DON'T AND the
        // legacy Start/No-trade envelope in - sessions replace it entirely.
        if sessions_active(sessions) {
            return sessions_gate_ok(sessions, now);
        }
        time_gate_ok(
            self.settings.start_after_enabled,
            &self.settings.start_after,
            self.settings.no_trade_after_enabled,
            &self.settings.no_trade_after,
            now,
        )
    }
}

/// True when the operator has at least one enabled, well-formed session window.
fn sessions_active(sessions: &[TradeSession]) -> bool {
    sessions.iter().any(|s| {
        if !s.enabled {
            return false;
        }
        match (hhmm_to_minutes(&s.start), hhmm_to_minutes(&s.end)) {
            (Some(a), Some(b)) => a < b,
            _ => false,
        }
    })
}

/// Multi-session intraday gate. When the operator has added sessions, a new
/// entry is only allowed while the current IST minute falls inside at least one
/// ENABLED, well-formed session (inclusive start/end). Disabled, malformed or
/// reversed (start >= end) sessions are ignored; an empty/all-invalid list means
/// "no extra window restriction" so a stray entry can never freeze the engine.
fn sessions_gate_ok(sessions: &[TradeSession], now: i64) -> bool {
    let mut any = false;
    for s in sessions {
        if !s.enabled {
            continue;
        }
        let (Some(a), Some(b)) = (hhmm_to_minutes(&s.start), hhmm_to_minutes(&s.end)) else {
            continue;
        };
        if a >= b {
            continue;
        }
        any = true;
        if now >= a && now <= b {
            return true;
        }
    }
    !any
}

/// Trade-time gate (NSE session), matching the old engine:
///  - "Start trading after" blocks entries before the start minute.
///  - "No trade after" blocks new entries after the cutoff.
/// A malformed time string is treated as "no gate" so a typo can never freeze
/// the engine. Position management / exits are never gated by this.
fn time_gate_ok(start_enabled: bool, start: &str, no_trade_enabled: bool, no_trade: &str, now: i64) -> bool {
    if start_enabled {
        if let Some(m) = hhmm_to_minutes(start) {
            if now < m {
                return false;
            }
        }
    }
    if no_trade_enabled {
        if let Some(m) = hhmm_to_minutes(no_trade) {
            if now > m {
                return false;
            }
        }
    }
    true
}

/// IST minute-of-day, or `None` on a weekend. Mon-Fri only; the day is derived
/// from the epoch (1970-01-01 was a Thursday) so no calendar crate is needed.
fn ist_weekday_minutes(now_secs: i64) -> Option<i64> {
    let ist = now_secs + 19_800; // UTC -> IST
    let weekday = (ist.div_euclid(86_400) + 4).rem_euclid(7);
    if weekday == 0 || weekday == 6 {
        return None;
    }
    Some(ist.rem_euclid(86_400) / 60)
}

/// NSE cash / F&O regular session open: Mon-Fri, IST 09:15-15:30.
fn nse_session_open(now_secs: i64) -> bool {
    matches!(ist_weekday_minutes(now_secs), Some(m) if (9 * 60 + 15..=15 * 60 + 30).contains(&m))
}

/// MCX commodity session open: Mon-Fri, IST 09:00-23:00 (evening session runs
/// past the cash close, which is why commodities trade long after NSE shuts).
fn mcx_session_open(now_secs: i64) -> bool {
    matches!(ist_weekday_minutes(now_secs), Some(m) if (9 * 60..=23 * 60).contains(&m))
}

/// Whether entries are allowed right now for an instrument of `cat`, given the
/// operator's own Trade-times window. Commodities follow the MCX session only
/// (they must keep trading till 23:00); everything else follows the NSE session
/// and is additionally narrowed by the operator window. This is the hard
/// market-closed gate so a closed cash/F&O market can never place trades.
fn strat_session_open(cat: StratCat, operator_time_ok: bool, now_secs: i64) -> bool {
    match cat {
        StratCat::Comm => mcx_session_open(now_secs),
        _ => nse_session_open(now_secs) && operator_time_ok,
    }
}

// ---------------------------------------------------------------------------
// Strategy evaluation
// ---------------------------------------------------------------------------

/// Engine-control timeframe checkboxes (`1 min` / `5 min`), defaulting to 5min
/// when neither is ticked so the engine always has a runnable timeframe.
fn enabled_engine_tfs(settings: &Settings) -> Vec<&'static str> {
    let mut v = Vec::new();
    if settings.tf_1min {
        v.push("1min");
    }
    if settings.tf_5min {
        v.push("5min");
    }
    if v.is_empty() {
        v.push("5min");
    }
    v
}

fn normalize_engine_tf(tf: &str) -> Option<&'static str> {
    let t = tf.trim().to_lowercase().replace(' ', "");
    match t.as_str() {
        "1min" | "1m" => Some("1min"),
        "5min" | "5m" => Some("5min"),
        _ => None,
    }
}

/// Old `pickTimeframe`: a strategy's own 1/5-min timeframe wins over the engine
/// checkboxes; turning on "Use AST settings (own SL/trail/timeframe)" flips it so
/// the engine's ticked timeframe list drives every strategy.
fn engine_tf(settings: &Settings, strat: &Strategy) -> String {
    let enabled = enabled_engine_tfs(settings);
    if settings.use_own_settings {
        return enabled[0].to_string();
    }
    if let Some(own) = normalize_engine_tf(&strat.timeframe) {
        return own.to_string();
    }
    enabled[0].to_string()
}

/// Old `mtfPair`: the lower ticked timeframe triggers entry, the higher one must
/// confirm the trend. `None` unless at least two timeframes are ticked.
fn mtf_pair(settings: &Settings) -> Option<(String, String)> {
    let enabled = enabled_engine_tfs(settings);
    if enabled.len() < 2 {
        return None;
    }
    let entry = if *enabled.last().unwrap() == "5min" { "1min" } else { enabled[0] };
    let trend = if enabled.contains(&"5min") { "5min" } else { *enabled.last().unwrap() };
    if entry == trend {
        None
    } else {
        Some((entry.to_string(), trend.to_string()))
    }
}

// ---------------------------------------------------------------------------
// Chart type: the series every indicator / filter / entry read is evaluated on.
// The operator picks Candlestick / Heikin Ashi / Line / Renko in the engine
// controls; the raw live series is transformed with the very same
// `algo_core::chart_type::build` the chart tab uses, so the algo trades the
// exact chart shown on screen.
// ---------------------------------------------------------------------------

/// Chart kind the engine evaluates on. Unknown / blank settings fall back to
/// plain candles.
fn engine_chart_kind(settings: &Settings) -> ChartKind {
    ChartKind::parse(&settings.chart_kind)
}

/// Renko geometry from the engine settings. Clamped so a stray 0 can never make
/// the brick builder produce an empty / NaN series.
fn engine_renko_cfg(settings: &Settings) -> RenkoConfig {
    RenkoConfig {
        mode: RenkoMode::parse(&settings.renko_mode),
        box_size: settings.renko_box_size,
        atr_length: settings.renko_atr_length.max(1) as usize,
        percentage: settings.renko_percentage,
        wicks: settings.renko_wicks,
        source: RenkoSource::parse(&settings.renko_source),
        non_repaint: settings.renko_non_repaint,
    }
}

/// Transform a raw candle series into the operator-selected chart type, exactly
/// like the chart tab. This only runs while the "Filters on display chart"
/// master switch is ON; with it OFF (default) the raw series is returned
/// untouched, so the legacy candle-based evaluation is preserved bit-for-bit and
/// `Candles` (the default kind) still takes the zero-copy fast path.
fn apply_engine_chart(candles: Vec<Candle>, settings: &Settings) -> Vec<Candle> {
    if !settings.filter_on_display_chart {
        return candles;
    }
    match engine_chart_kind(settings) {
        ChartKind::Candles => candles,
        kind => algo_core::chart_type::build(kind, &candles, &engine_renko_cfg(settings)),
    }
}

/// NIFTY index security id: the instrument the trend-following engine reads the
/// selected straight-line indicators on.
const NIFTY_SEC: i64 = 13;

/// NIFTY trend-following filter assignment (the straight-line -> side mapper).
///
/// Each selected straight-line indicator is computed on the index candles and
/// classified by its *line direction* - the latest plotted value against the one
/// before it: rising -> bullish, falling -> bearish, flat -> neutral. Bullish
/// ids are assigned to the Top Gainer side, bearish ids to the Top Loser side,
/// so a bullish line trades gainers and a bearish line trades losers. Returns
/// `(bullish_ids, bearish_ids, net)` where `net = bullish - bearish`.
/// Compute one NIFTY "Confirm indicators" id. ZigZag EMA length variants
/// (`slema1/9/21/30/50/100`) and the Supertrend ZigZag use fixed, panel-shaped
/// settings so the confirmation read matches the exact line on the chart
/// (ZigZag EMA: Length N, Source Close, Swing 17, Min leg 5; Supertrend ZigZag:
/// ATR 10, fast 1, slow 0.1, swing 5, min leg 5). Everything else uses the
/// indicator's own defaults.
fn nifty_conf_series(id: &str, candles: &[Candle], s: &Settings) -> Vec<algo_core::model::SeriesOut> {
    match id {
        "slema1" | "slema9" | "slema21" | "slema30" | "slema50" | "slema100" => {
            let len: f64 = id.trim_start_matches("slema").parse().unwrap_or(9.0);
            let s: algo_core::model::Settings =
                [("length", len), ("swing", 17.0), ("minLeg", 5.0)].into_iter().map(|(k, v)| (k.to_string(), json!(v))).collect();
            algo_core::compute("slema", candles, &s)
        }
        "stzigzag" => {
            let s: algo_core::model::Settings =
                [("atrPeriod", 10.0), ("factorFast", 1.0), ("factorSlow", 0.1), ("swing", 5.0), ("minLeg", 5.0)]
                    .into_iter()
                    .map(|(k, v)| (k.to_string(), json!(v)))
                    .collect();
            algo_core::compute("stzigzag", candles, &s)
        }
        // The BB%b Straight Line confirmation uses the operator's per-filter
        // settings (BB length / std-dev mult / bull threshold / min leg / source /
        // colours / line width) so the line the engine reads matches what the
        // operator configured in its settings dialog.
        "bbpctsl" => {
            let cs: algo_core::model::Settings = vec![
                ("length", json!(s.nbsl_length)),
                ("mult", json!(s.nbsl_mult)),
                ("threshold", json!(s.nbsl_threshold)),
                ("minLeg", json!(s.nbsl_min_leg)),
                ("source", json!(s.nbsl_source)),
                ("upColor", json!(s.nbsl_up_color)),
                ("downColor", json!(s.nbsl_down_color)),
                ("flatColor", json!(s.nbsl_flat_color)),
                ("lineWidth", json!(s.nbsl_line_width)),
            ]
            .into_iter()
            .map(|(k, v)| (k.to_string(), v))
            .collect();
            algo_core::compute("bbpctsl", candles, &cs)
        }
        _ => algo_core::compute(id, candles, &algo_core::model::Settings::default()),
    }
}

/// Is `base` a plain EMA-pair id (`Ema9_21`, `Ema1_300`, ...)?
fn trend_is_ema_pair(base: &str) -> bool {
    let Some(rest) = base.strip_prefix("Ema") else { return false };
    let Some((a, b)) = rest.split_once('_') else { return false };
    !a.is_empty()
        && !b.is_empty()
        && a.chars().all(|c| c.is_ascii_digit())
        && b.chars().all(|c| c.is_ascii_digit())
}

/// Canonical held-state base for one indicator-filter token. The trend follower
/// confirms on the filter's SIDE, not on a one-bar event: a crossover filter is
/// collapsed to its level form (`Ema9_21` -> `MeetEma9_21`, `St1CloseCrossAbove`
/// -> `MeetCloseSt`), which stays true until the opposite crossover prints. That
/// is exactly the flip the trend needs. `None` means the row has no two-sided
/// price-direction state (arrows, research scopes, volatility-only rows) or is
/// already offered through a straight-line chart id.
fn trend_filter_state(base: &str) -> Option<String> {
    if base.is_empty() {
        return None;
    }
    if matches!(
        base,
        "Candle"
            | "Elliott"
            | "Indicator"
            | "Pane"
            | "Symmetry"
            | "Structure"
            | "Atr"
            | "PbrElderforce"
            | "BbwInc"
            | "PbrBbwUp"
            | "PbrAtrUp"
            | "PbrVoloscUp"
            | "GtUp"
            | "GtDown"
            | "LtUp"
            | "LtDown"
    ) {
        return None;
    }
    if base.starts_with("Arrow") {
        return None;
    }
    // "Candle closed above / below <indicator>" rows are one-sided level gates
    // (each side has its own row), so they have no single two-sided "state" id
    // the NIFTY-trend picker could flip. Keep them out of that picker.
    if base.starts_with("ClosedAbove") || base.starts_with("ClosedBelow") {
        return None;
    }
    // The straight-line family is already offered as chart ids (`slconsensus`,
    // `slema9`, `bbpctsl`, ...); do not list it twice.
    if base.starts_with("Sl") || base.starts_with("Vsl") {
        return None;
    }
    if base.starts_with("St10_") {
        return Some(format!("Meet{base}"));
    }
    if base == "St1CloseCrossAbove" || base == "St1CloseCrossBelow" {
        return Some("MeetCloseSt".into());
    }
    if base == "VwapCloseCrossAbove" || base == "VwapCloseCrossBelow" {
        return Some("MeetCloseVwap".into());
    }
    if base == "BbCrossAbove" || base == "BbCrossBelow" {
        return Some("MeetCloseBb".into());
    }
    if base == "PcCrossAbove" || base == "PcCrossBelow" {
        return Some("MeetClosePc".into());
    }
    if base == "PaneCrossUp" || base == "PaneCrossDown" {
        return Some("MeetPaneCross".into());
    }
    if trend_is_ema_pair(base) {
        return Some(format!("Meet{base}"));
    }
    Some(base.to_string())
}

/// Two-sided filter tokens for one trend confirmation id: `(bull token, bear
/// token)`. The picker stores the bullish/neutral row; the trend read asks the
/// filters for BOTH held sides and votes only when exactly one is true, so a
/// stale or ambiguous read never forces a side.
fn trend_filter_tokens(id: &str) -> Option<(String, String)> {
    let (prefixed, base) = if let Some(b) = id.strip_prefix("Bull") {
        (true, b)
    } else if let Some(b) = id.strip_prefix("Bear") {
        (true, b)
    } else {
        (false, id)
    };
    let neutral = match base {
        "IncUp" | "IncDown" => Some(("IncUp", "IncDown")),
        "IncUpAll" | "IncDownAll" => Some(("IncUpAll", "IncDownAll")),
        "GapUp" | "GapDown" => Some(("GapUp", "GapDown")),
        // Crossed above/below EMA 9: the held state is close vs EMA 9.
        "CrossUp" | "CrossDown" => Some(("GtUp", "LtUp")),
        "PaneCrossUp" | "PaneCrossDown" => Some(("BullMeetPaneCross", "BearMeetPaneCross")),
        "PaneIncUpAll" | "PaneIncDownAll" => Some(("PaneIncUpAll", "PaneIncDownAll")),
        _ => None,
    };
    if let Some((b, r)) = neutral {
        return Some((b.to_string(), r.to_string()));
    }
    if !prefixed {
        return None;
    }
    let state = trend_filter_state(base)?;
    Some((format!("Bull{state}"), format!("Bear{state}")))
}

/// Evaluate the two held sides of one trend confirmation. Returns `+1` when only
/// the bullish side holds, `-1` when only the bearish side holds, and `None`
/// while both/neither resolve (warm-up, flat, or a filter that cannot be read).
fn filter_trend_tokens(bull_id: &str, bear_id: &str, candles: &[Candle], s: &Settings) -> Option<i64> {
    if candles.len() < 2 {
        return None;
    }
    // Match the entry gate exactly: same closed-bar offset, same N-bar slope,
    // same crossover read mode, same consensus / trendline geometry settings.
    let offset = usize::from(s.closed_bar_compute);
    let _slope = FilterSlopeBarsGuard::enter(s.ind_filter_slope_on, s.ind_filter_slope_bars);
    let _cross = FilterCrossGuard::enter(s, s.closed_bar_compute);
    let _scope = IndScope::enter();
    let cons = consensus_cfg(s);
    let sup = support_trend_cfg(s);
    let res = resistance_trend_cfg(s);
    let bull = gate_filter_eval(bull_id, candles, offset, cons, sup, res);
    let bear = gate_filter_eval(bear_id, candles, offset, cons, sup, res);
    match (bull, bear) {
        (Some(true), Some(false)) => Some(1),
        (Some(false), Some(true)) => Some(-1),
        _ => None,
    }
}

#[cfg(test)]
fn nifty_indicator_assignment(candles: &[Candle], conf: &[String], slope_len: i64, color: bool, s: &Settings) -> (Vec<String>, Vec<String>, i64) {
    let (bull, bear, net, _) = nifty_indicator_read(candles, conf, slope_len, color, s);
    (bull, bear, net)
}

/// [`nifty_indicator_assignment`] plus each configured indicator's vote
/// (`+1` bull, `-1` bear, `0` flat / not warm), in configuration order. The
/// votes are a readout only - the side is still the net of the resolved votes.
fn nifty_indicator_read(candles: &[Candle], conf: &[String], slope_len: i64, color: bool, s: &Settings) -> (Vec<String>, Vec<String>, i64, Vec<(String, i8)>) {
    let window = nifty_slope_len(slope_len);
    let mut bull: Vec<String> = Vec::new();
    let mut bear: Vec<String> = Vec::new();
    let mut votes: Vec<(String, i8)> = Vec::new();
    let mut seen_trend_pairs: std::collections::HashSet<String> = std::collections::HashSet::new();
    for id in conf {
        // Indicator-filter confirmations are read as their HELD side (bullish
        // bucket / bearish bucket), so selecting e.g. EMA 9 / EMA 21 or a
        // Supertrend pair flips the trend the moment the opposite crossover
        // prints. Chart / straight-line ids keep their existing slope or colour
        // read below.
        if let Some((bull_id, bear_id)) = trend_filter_tokens(id) {
            // One pair counts once even if both its Bull and Bear rows were
            // imported; otherwise the same indicator would vote on both sides
            // and cancel itself out.
            if !seen_trend_pairs.insert(format!("{bull_id}|{bear_id}")) {
                continue;
            }
            match filter_trend_tokens(&bull_id, &bear_id, candles, s) {
                Some(1) => {
                    bull.push(id.clone());
                    votes.push((id.clone(), 1));
                }
                Some(-1) => {
                    bear.push(id.clone());
                    votes.push((id.clone(), -1));
                }
                // A recognised filter confirmation that is still warming up or
                // ambiguous contributes no vote this read; never fall through to
                // `algo_core::compute` (which has no such indicator).
                _ => votes.push((id.clone(), 0)),
            }
            continue;
        }
        let out = nifty_conf_series(id, candles, s);
        // Two reads:
        // * normal (color = false): the direction of the line's LATEST segment
        //   (newest point vs the one before it) - the slope the chart draws on the
        //   right edge. Reading a net window of older legs could report the stale
        //   side after a turn.
        // * color (color = true): the COLOUR the chart draws on the line's last
        //   closed candle - green = bullish, red = bearish. This is the colour the
        //   operator sees, read as-is (never derived from the value slope here).
        // `None` / `Flat` (line not resolved yet or flat) contributes nothing
        // instead of forcing a side, in both modes.
        // Read the VISIBLE drawn output series (the same series the colour mode
        // and the chart use): most indicators draw on series 0, zigzag / combo
        // master draw their straight trendline on series 1. Reading `out.first()`
        // here made the normal (non-colour) mode classify ZigZag / Combo Master
        // from their raw zigzag structure instead of the straight line the
        // operator picked in the "Confirm indicators" dropdown.
        let idx = sl_output_index(id);
        let trend = if color {
            out.get(idx).and_then(|s| color_read_last_closed(s, candles))
        } else {
            out.get(idx).and_then(|s| straight_line_trend_bars(s, candles, 0, window))
        };
        match trend {
            Some(SlTrend::Bull) => {
                bull.push(id.clone());
                votes.push((id.clone(), 1));
            }
            Some(SlTrend::Bear) => {
                bear.push(id.clone());
                votes.push((id.clone(), -1));
            }
            _ => votes.push((id.clone(), 0)),
        }
    }
    let net = bull.len() as i64 - bear.len() as i64;
    (bull, bear, net, votes)
}

/// The two colours the chart's straight-line overlays use for a bullish (rising)
/// leg and a bearish (falling) leg. These are the defaults of the indicator
/// `upColor` / `downColor` settings, and `algo_core` repaints the whole
/// straight-line family with exactly these before returning it, so the colour read
/// here is the colour the operator sees on the chart.
const SL_GREEN: &str = "#26a69a";
const SL_RED: &str = "#ef5350";

/// Read the COLOUR (not the value) of a straight-line series at its newest drawn
/// point: green -> `Bull`, red -> `Bear`. The renderer paints each segment with
/// its END point's colour (`draw_line_series`), so the segment the chart draws
/// across the latest closed candle carries the newest point's colour - exactly
/// the colour the operator sees on the line right now. `offset` skips that many
/// newest points.
///
/// A fixed `len - 2` index is wrong here: most straight-line series are SPARSE
/// (one point per vertex / pivot, not one per candle), so `len - 2` can be many
/// candles - even days - old and read the PREVIOUS leg's colour. The newest point
/// is the only one guaranteed to sit on the segment covering the latest candle.
/// Any other / missing colour reads `None` (non-blocking), so an un-drawn or
/// differently-coloured line never fabricates a side.
#[cfg(test)]
fn color_read(ser: &algo_core::model::SeriesOut, offset: usize) -> Option<SlTrend> {
    let n = ser.data.len();
    let i = n.checked_sub(offset + 1)?;
    let col = ser.data[i].color.as_deref()?.trim().to_ascii_lowercase();
    if col == SL_GREEN {
        Some(SlTrend::Bull)
    } else if col == SL_RED {
        Some(SlTrend::Bear)
    } else {
        None
    }
}

/// Colour the chart paints on the LAST CLOSED candle of a straight-line overlay.
/// A segment is drawn between two consecutive points and painted with its END
/// point's colour, so the segment covering the last closed candle is the one
/// ending at the FIRST point whose time is at or after that candle's time. This
/// is exact for both dense (a point per candle) and sparse (a point per pivot)
/// straight-line series, and it never reads the still-forming candle - the
/// operator-visible colour is only confirmed once the candle closes.
fn color_read_last_closed(ser: &algo_core::model::SeriesOut, candles: &[Candle]) -> Option<SlTrend> {
    if candles.len() < 2 {
        return None;
    }
    let last_closed_time = candles[candles.len() - 2].time;
    let p = ser.data.iter().find(|p| p.time >= last_closed_time)?;
    let col = p.color.as_deref()?.trim().to_ascii_lowercase();
    if col == SL_GREEN {
        Some(SlTrend::Bull)
    } else if col == SL_RED {
        Some(SlTrend::Bear)
    } else {
        None
    }
}

/// Output-series index that carries the drawn (coloured) line for a straight-line
/// indicator id. Every straight-line indicator now draws a single line on
/// series 0 (multi-line indicators were collapsed to their primary line).
fn sl_output_index(_id: &str) -> usize {
    0
}
/// Map a "Straight Line Indicator Color Detection" filter token to the VISIBLE
/// coloured overlay id the chart draws (and its output index). This is
/// deliberately NOT the hidden "…state" id the plain `Sl*` direction filters read:
/// those hidden series carry no green/red colour, while the visible overlay does.
fn sl_color_series(base: &str) -> Option<(&'static str, usize)> {
    Some(match base {
        "ElliottWave" => ("wavefib", 0),
        "SupplyDemand" => ("supplydemand", 0),
        "PriceAction" => ("pastruct", 0),
        "ZigZag" => ("zzline", 0),
        "ComboMaster" => ("trendmaster", 0),
        "PaneConsensus" => ("panemaster", 0),
        "AutoTrendline" => ("autotrend", 0),
        "Pitchfork" => ("pitchfork", 0),
        "TrendProjection" => ("projline", 0),
        "GannFan" => ("gannfan", 0),
        "FibFan" => ("fibfan", 0),
        "Srema" => ("srema", 0),
        "StraightEma" => ("slema", 0),
        "Vl" => ("vl", 0),
        "BbPctSl" => ("bbpctsl", 0),
        "Consensus" => ("slconsensus", 0),
        "Support" => ("supline", 0),
        "Resistance" => ("resline", 0),
        "OverallConsensusPrice" => ("slallconsensuso", 0),
        "PriceActionDiv" => ("padivo", 0),
        _ => return None,
    })
}

/// Colour read for one visible straight-line overlay on the LAST CLOSED candle:
/// green passes the bull side, red passes the bear side. A missing/other colour
/// is undecided (`None`) so the caller can fail closed.
fn color_line_dir(id: &str, idx: usize, bull: bool, candles: &[Candle]) -> Option<bool> {
    let out = ind_series(id, candles, &algo_core::model::Settings::default());
    let s = out.get(idx)?;
    match color_read_last_closed(s, candles)? {
        SlTrend::Bull => Some(bull),
        SlTrend::Bear => Some(!bull),
        SlTrend::Flat => None,
    }
}

/// Straight-line trend window length. At least 3 points so the net move has more
/// than a single step to average over; values above the available history clamp
/// on read.
fn nifty_slope_len(v: i64) -> usize {
    v.clamp(3, 200) as usize
}

/// Trend read of one straight-line series.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SlTrend {
    /// The drawn line is rising.
    Bull,
    /// The drawn line is falling.
    Bear,
    /// The line is flat; upstream keeps the previous side.
    Flat,
}

/// Fraction of a straight-line's own magnitude that a move must cover, over the
/// whole lookback, to count as a real trend instead of trading-range noise. This
/// is the ABSOLUTE half of the noise floor below: unlike the relative half it does
/// NOT shrink when the line's own recent volatility collapses, so a quiet/choppy
/// stretch whose average step has gone to near zero can no longer pass just
/// because its tiny steps are "large" relative to that collapsed average. In other
/// words, this is what stops the "chhoti chhoti trend" entries.
const STRAIGHT_LINE_MIN_MOVE_FRAC: f64 = 0.0008;

/// Read the CURRENT trend of a straight-line series.
///
/// The trend is the NET move over the recent `window` points (a sustained move,
/// not one bar's tick), with two guards:
///   * NOISE FLOOR - the net must clear `max(half the recent average absolute
///     step, a small fraction of the line's own magnitude)`. The relative half
///     alone always adapts to the local scale (so it collapses to zero in a quiet
///     stretch and every tiny step passes); the absolute half is fixed to price,
///     so small "trends" are rejected outright.
///   * TURN GUARD - if the net is up but the newest segment has already reversed
///     by more than the floor (or vice versa), the line is NOT trending that way
///     right now, so it reads `Flat` instead of firing a stale side.
///
/// `Flat` = no tradeable trend (callers fail closed). `None` = still warming up
/// (fewer than 3 points / non-finite): warm-up must never fabricate a direction.
fn straight_line_trend(ser: &algo_core::model::SeriesOut, offset: usize, window: usize) -> Option<SlTrend> {
    let end = ser.data.len().checked_sub(offset)?;
    if end < 3 {
        return None;
    }
    let newest = ser.data[end - 1].value;
    if !newest.is_finite() {
        return None;
    }
    // Sustained move: net across the recent `window` points, not just the latest
    // single step, so a one-tick wiggle can never authorise a trend.
    let span = window.max(3).min(end - 1);
    let base = ser.data[end - 1 - span].value;
    if !base.is_finite() {
        return None;
    }
    let net = newest - base;
    let start = end.saturating_sub(span + 1);
    let vals: Vec<f64> = (start..end).map(|i| ser.data[i].value).collect();
    if !vals.iter().all(|v| v.is_finite()) {
        return None;
    }
    let sum_step: f64 = vals.windows(2).map(|w| (w[1] - w[0]).abs()).sum();
    let mean_step = sum_step / (vals.len() - 1) as f64;
    // Relative floor (half the recent average step) OR absolute, price-scaled
    // floor - whichever is larger. See STRAIGHT_LINE_MIN_MOVE_FRAC.
    let abs_floor = newest.abs().max(base.abs()) * STRAIGHT_LINE_MIN_MOVE_FRAC;
    let eps = (mean_step * 0.5).max(abs_floor);
    let last = newest - ser.data[end - 2].value;
    if net > eps {
        // Reject a line that is already giving the rise back on the newest step.
        if last < -eps {
            Some(SlTrend::Flat)
        } else {
            Some(SlTrend::Bull)
        }
    } else if net < -eps {
        if last > eps {
            Some(SlTrend::Flat)
        } else {
            Some(SlTrend::Bear)
        }
    } else {
        Some(SlTrend::Flat)
    }
}

/// [`straight_line_trend`] read by BAR instead of by series point. Straight-line
/// overlays are SPARSE (one point per swing vertex), so a "Slope from N bars"
/// window counted in points could span days and classify the line from a stale
/// vertex. This maps every bar in the window onto the drawn line
/// ([`series_value_at_bar`]) and applies the same noise floor / turn guard, so
/// the read matches the line the chart is drawing on those bars.
fn straight_line_trend_bars(
    ser: &algo_core::model::SeriesOut,
    candles: &[Candle],
    offset: usize,
    window: usize,
) -> Option<SlTrend> {
    let span = window.max(3);
    if candles.len() < offset + span + 1 {
        return None;
    }
    let mut vals: Vec<f64> = Vec::with_capacity(span + 1);
    for i in 0..=span {
        vals.push(series_value_at_bar(ser, candles, offset + i)?);
    }
    if !vals.iter().all(|v| v.is_finite()) {
        return None;
    }
    let newest = vals[0];
    let base = vals[span];
    let net = newest - base;
    let sum_step: f64 = vals.windows(2).map(|w| (w[1] - w[0]).abs()).sum();
    let mean_step = sum_step / span as f64;
    let abs_floor = newest.abs().max(base.abs()) * STRAIGHT_LINE_MIN_MOVE_FRAC;
    let eps = (mean_step * 0.5).max(abs_floor);
    let last = vals[0] - vals[1];
    if net > eps {
        if last < -eps {
            Some(SlTrend::Flat)
        } else {
            Some(SlTrend::Bull)
        }
    } else if net < -eps {
        if last > eps {
            Some(SlTrend::Flat)
        } else {
            Some(SlTrend::Bear)
        }
    } else {
        Some(SlTrend::Flat)
    }
}

/// NIFTY trend timeframe: the timeframe the operator ticked for the engine
/// charts (`1 min` / `5 min`). Both ticked = `both`, i.e. the two must agree
/// before the trend is allowed to switch. Falls back to 5min when neither is
/// ticked, matching the engine default.
/// Merge the two per-timeframe reads of a NIFTY direction source (confirmation
/// indicators, BB%b zone, or BB%b line trend). When BOTH sides resolved they must
/// share the same committed sign, else the pair disagrees and no flip is
/// committed (`None`). A single-sided read passes through unchanged, matching the
/// historical `resolve_nifty_direction` behaviour where an unwarmed timeframe is
/// treated as non-blocking.
#[cfg(test)]
fn combine_both_reads(
    a: Option<(Vec<String>, Vec<String>, i64)>,
    b: Option<(Vec<String>, Vec<String>, i64)>,
) -> Option<(Vec<String>, Vec<String>, i64)> {
    match (a, b) {
        (Some(xa), Some(xb)) => {
            if xa.2.signum() == xb.2.signum() {
                Some(xb)
            } else {
                None
            }
        }
        (Some(x), None) => Some(x),
        (None, Some(x)) => Some(x),
        (None, None) => None,
    }
}

/// [`combine_both_reads`] for reads that also carry per-indicator votes. The
/// committed read's votes are published (the 5 min read when both agree).
fn combine_both_reads_votes(
    a: Option<(Vec<String>, Vec<String>, i64, Vec<(String, i8)>)>,
    b: Option<(Vec<String>, Vec<String>, i64, Vec<(String, i8)>)>,
) -> Option<(Vec<String>, Vec<String>, i64, Vec<(String, i8)>)> {
    match (a, b) {
        (Some(xa), Some(xb)) => {
            if xa.2.signum() == xb.2.signum() {
                Some(xb)
            } else {
                None
            }
        }
        (Some(x), None) => Some(x),
        (None, Some(x)) => Some(x),
        (None, None) => None,
    }
}

fn nifty_timeframe(settings: &Settings) -> String {
    let tfs = enabled_engine_tfs(settings);
    if tfs.len() >= 2 {
        "both".to_string()
    } else {
        tfs[0].to_string()
    }
}

fn nifty_dir_label(d: i64) -> &'static str {
    match d {
        1 => "BULLISH(CE)",
        -1 => "BEARISH(PE)",
        _ => "NEUTRAL",
    }
}

/// Pre-order verdict for the NIFTY-trend side lock. Every disagreement is a
/// block: a neutral committed side, an in-flight flip (old side still committed
/// while the new one confirms), a currently tied read, a side mismatch, or a
/// BB%b confirmation that stopped holding between scan and fill.
fn nifty_trend_entry_gate(want: i64, dir: i64, pending: i64, tied: bool, line_ok: bool, sideways: bool) -> Result<(), String> {
    if want == 0 {
        return Err("entry side unknown - blocked".into());
    }
    if sideways {
        return Err("NIFTY is sideways - no new trend entry".into());
    }
    if dir == 0 {
        return Err("NIFTY trend neutral - entry blocked".into());
    }
    if pending != 0 {
        return Err(format!(
            "NIFTY flip to {} pending confirmation - old-side entry blocked",
            nifty_dir_label(pending)
        ));
    }
    if tied {
        return Err("NIFTY trend read tied (neutral) - entry blocked".into());
    }
    if dir != want {
        return Err(format!(
            "NIFTY trend {} vs entry {} - old-side entry blocked",
            nifty_dir_label(dir),
            nifty_dir_label(want)
        ));
    }
    if !line_ok {
        return Err("BB%b confirmation no longer holds - entry blocked".into());
    }
    Ok(())
}

/// Whether the NIFTY-direction pipeline should run for this engine. It runs
/// ONLY when the operator has explicitly switched the NIFTY Trend Following
/// master ON. The BB%b (Pane) section no longer self-enables the pipeline: with
/// the master OFF the direction pipeline (and its F&O side lock) is fully inert,
/// no matter which BB%b zone / line-trend / combo switches are left ON. When the
/// master is ON the operator's chosen direction source (confirmation indicators,
/// or the BB%b modes if selected) still applies exactly as before.
fn nifty_dir_feature_on(settings: &Settings) -> bool {
    settings.nifty_trend_on
}

/// Confirmation indicators the Auto Trading preset assigns when the operator has
/// none: two independent held-side reads (fast/slow EMA + the classic 9/21 EMA
/// pair). The NIFTY trend needs at least one of these to commit a side; with an
/// empty list the direction stays 0 and every leg would be blocked.
const AUTO_TRADE_CONF_INDS: &[&str] = &["BullMeetEma1_9", "BullMeetEma9_21"];

/// Bullish / bearish indicator-filter rows the Auto Trading preset enables. They
/// are the same held-side level filters the trend confirmations read, so the
/// entry gate and the direction read can never contradict each other by design.
const AUTO_TRADE_BULL_FILTERS: &[&str] = &["BullMeetEma9_21", "IncUp"];
const AUTO_TRADE_BEAR_FILTERS: &[&str] = &["BearMeetEma9_21", "IncDown"];

// ---------------------------------------------------------------------------
// Autonomous brain (Option A)
//
// This is NOT a hidden second engine and it is not opaque "AI". It is a
// deterministic adaptor that reads the SAME candles, the SAME filters and the
// SAME risk knobs the operator sees, then picks better values for them:
//
//   1. Regime read   - ADX / Choppiness / EMA slope / range compression on the
//                      engine's trend timeframe (`sideways_read`), so the brain
//                      can tell a real trend from a range.
//   2. Filter ranking - every candidate filter is BACKTESTED on the last N bars
//                      of that same series: it counts how often the filter held
//                      and the price then moved in its direction by more than a
//                      noise floor (0.25 ATR) over the next few bars. The
//                      highest-expectancy rows are the ones the gate keeps.
//   3. Risk sizing   - ATR stop / trail width / RR target scale with the regime:
//                      a trend gets a normal stop and a wide target, a range
//                      gets a wider stop, a tighter trail and a nearer target.
//
// Every choice is written back into the normal Settings fields and a one-line
// `brain_note` explains WHY, so the operator can audit it. The brain never
// arms the engine master switch and never edits an open position's levels.
// ---------------------------------------------------------------------------

/// One ranked candidate filter plus the full evidence behind it.
#[derive(Clone, Debug)]
struct BrainPick {
    key: String,
    samples: usize,
    /// Measured win rate over the sample (0..1).
    win_rate: f64,
    /// Measured payoff (average win R / average loss R).
    payoff_r: f64,
    /// Conservative net expectancy in R: Wilson lower-bound win rate, real
    /// payoff, round-trip cost deducted. This is the RANKING key.
    net_r: f64,
    /// Out-of-sample net expectancy, when walk-forward validated it.
    oos_r: Option<f64>,
}

/// Minimum time between brain recomputations (regime + filter ranking).
const BRAIN_REFRESH_MS: i64 = 60_000;
/// Retry cadence after a failed read (cold feed), so the brain is not run on
/// every loop tick while it waits for candles. Kept slow because a real-engine
/// retry may pay one REST candle fetch.
const BRAIN_RETRY_MS: i64 = 30_000;
/// Bars of forward movement a filter is scored against.
const BRAIN_FWD_BARS: usize = 12;
/// How many recent bars the ranking walks. 180 gives a full session of 1-min
/// bars or ~3 sessions of 5-min bars, which is enough for a stable read without
/// reaching back into a different market regime.
const BRAIN_LOOKBACK: usize = 180;
/// Minimum usable samples before a filter may be armed.
const BRAIN_MIN_SAMPLES: usize = 20;

/// Bullish candidate rows the brain is allowed to pick from. All of them are
/// plain filter ids the normal gate already understands (`MeetEma*` pairs and
/// the rising-close row), so nothing here can create a new entry mechanism.
const BRAIN_BULL_CANDIDATES: &[&str] = &[
    "BullMeetEma1_9",
    "BullMeetEma9_21",
    "BullMeetEma9_35",
    "BullEmaTrend9",
    "BullEmaTrend21",
    "BullIncUp",
    "BullIncUpAll",
];
const BRAIN_BEAR_CANDIDATES: &[&str] = &[
    "BearMeetEma1_9",
    "BearMeetEma9_21",
    "BearMeetEma9_35",
    "BearEmaTrend9",
    "BearEmaTrend21",
    "BearIncDown",
    "BearIncDownAll",
];

/// The full decision the brain commits for one cycle.
#[derive(Clone, Debug)]
struct BrainPlan {
    regime: &'static str,
    sl_atr: f64,
    trail_atr: f64,
    tp_rr: f64,
    chart_kind: &'static str,
    bull: Vec<BrainPick>,
    bear: Vec<BrainPick>,
    /// The side's pool WAS computable but nothing cleared the cost/cost-adjusted
    /// bar, so the brain deliberately left that side unarmed. Distinguished from
    /// "could not compute anything", where the legacy fallback rows are used.
    bull_blocked: bool,
    bear_blocked: bool,
    /// Volatility zone at decision time (`quiet` / `normal` / `wild`).
    vol_zone: &'static str,
    /// True when the volatility band says "do not open new trades at all".
    no_trade_vol: bool,
    /// Round-trip cost in R used for this decision.
    cost_r: f64,
    note: String,
}

impl BrainPlan {
    fn pick_for_side(&self, bull: bool) -> &[BrainPick] {
        if bull { &self.bull } else { &self.bear }
    }
}

/// Evaluate one filter token on every bar of `candles` so the scoring walk can
/// reuse a single evaluated vector instead of re-deriving the indicator per bar
/// (this is the hot path of a 7-filter x 180-bar x 2-side sweep).
fn brain_filter_firings(
    key: &str,
    candles: &[Candle],
    sc: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> Vec<bool> {
    let n = candles.len();
    let mut out = vec![false; n];
    if n == 0 {
        return out;
    }
    let _scope = IndScope::enter();
    for i in 0..n {
        let offset = n - 1 - i;
        if let Some(true) = filter_eval_inner(key, candles, offset, sc, sup, res) {
            out[i] = true;
        }
    }
    out
}

/// Score one candidate end-to-end: split into in-sample / out-of-sample, require
/// the filter to have worked in BOTH, then rank on the conservative net number.
fn brain_score_candidate(
    key: &str,
    candles: &[Candle],
    atr: f64,
    sl_atr: f64,
    tp_rr: f64,
    cost_r: f64,
    sc: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> Option<BrainPick> {
    let n = candles.len();
    if n < 40 || !(atr > 0.0) {
        return None;
    }
    let bull = filter_is_bull(key);
    let firings = brain_filter_firings(key, candles, sc, sup, res);
    // Walk the most recent window only, but keep enough bars to split.
    let start = n.saturating_sub(BRAIN_LOOKBACK);
    let window = &candles[start..];
    let fires = &firings[start..];
    let (train, _test) = crate::brain::walk_forward_split(window.len(), 0.7);
    if train < 20 || window.len() - train < 5 {
        return None;
    }
    let full = crate::brain::score_filter(bull, fires, window, atr, sl_atr, tp_rr, BRAIN_FWD_BARS)?;
    if full.samples < BRAIN_MIN_SAMPLES {
        return None;
    }
    // Walk-forward: rank on the train half, validate on the held-out half.
    let is_ev = crate::brain::score_filter(bull, &fires[..train], &window[..train], atr, sl_atr, tp_rr, BRAIN_FWD_BARS)?;
    let oos_start = train.saturating_sub(BRAIN_FWD_BARS);
    let oos_ev = crate::brain::score_filter(
        bull,
        &fires[oos_start..],
        &window[oos_start..],
        atr,
        sl_atr,
        tp_rr,
        BRAIN_FWD_BARS,
    );
    let oos_r = oos_ev
        .as_ref()
        .and_then(|o| crate::brain::validated_expectancy(&is_ev, o, cost_r));
    Some(BrainPick {
        key: key.to_string(),
        samples: full.samples,
        win_rate: full.win_rate(),
        payoff_r: full.payoff_r(),
        net_r: full.conservative_net(cost_r),
        oos_r,
    })
}

/// Rank one side's candidate pool best-first.
///
/// A row qualifies only when BOTH hold:
///   * conservative net expectancy is positive (Wilson-bound win rate, real
///     payoff, round-trip cost deducted), and
///   * if walk-forward produced a holdout read, that read is ALSO positive.
/// Rows that cannot compute are left out entirely - never a fabricated score.
fn brain_rank_side(
    candidates: &[&str],
    candles: &[Candle],
    atr: f64,
    sl_atr: f64,
    tp_rr: f64,
    cost_r: f64,
    sc: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> (Vec<BrainPick>, usize) {
    let scored: Vec<BrainPick> = candidates
        .iter()
        .filter_map(|k| brain_score_candidate(k, candles, atr, sl_atr, tp_rr, cost_r, sc, sup, res))
        .collect();
    // How many candidates produced a real measurement at all. Zero means the
    // series is not warm enough to judge this side; a non-zero count with an
    // empty result means the side was judged and lost.
    let computable = scored.len();
    let mut out: Vec<BrainPick> = scored
        .into_iter()
        .filter(|p| p.net_r > 0.0 && p.oos_r.map(|o| o > 0.0).unwrap_or(true))
        .collect();
    out.sort_by(|a, b| {
        b.net_r
            .partial_cmp(&a.net_r)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| b.samples.cmp(&a.samples))
    });
    (out, computable)
}

/// Pure decision function: regime + volatility gate + cost-aware filter ranking
/// + risk sizing + exit policy from a candle series.
///
/// Deterministic - the same series always yields the same plan, which is what
/// makes the brain auditable instead of a black box.
fn brain_plan(candles: &[Candle], settings: &Settings) -> Option<BrainPlan> {
    if candles.len() < 40 {
        return None;
    }
    let atr = regime_atr(candles, 14)?;
    let ltp = candles[candles.len() - 1].close;
    if !(ltp > 0.0) {
        return None;
    }
    let atr_pct = atr / ltp * 100.0;
    let read = sideways_read(candles)?;
    let regime = if read.sideways { "range" } else { "trend" };

    // Risk sizing. A trend is allowed a normal ATR stop and a wide target (the
    // move is expected to extend). A range gets a wider stop so the noise cannot
    // clip it, a tighter trail so a small mean-reversion swing is banked, and a
    // nearer target because range moves do not extend as far.
    let (sl_atr, trail_atr, tp_rr) = if read.sideways {
        (2.2, 0.8, 2.0)
    } else if read.adx >= 30.0 {
        (1.8, 1.3, 3.5)
    } else {
        (1.5, 1.1, 3.0)
    };

    // Volatility gate: the same ATR% measured against the instrument's OWN recent
    // distribution. Too quiet = breakouts fail and costs dominate; too wild =
    // stops get clipped by noise and option spreads blow out. Either extreme is
    // a deliberate no-trade zone.
    let hist = crate::brain::atr_percent_history(candles, 14, 200);
    let pct = crate::brain::percentile_of(atr_pct, &hist);
    let zone = crate::brain::vol_zone(atr_pct, pct);
    let (quiet_gate, wild_gate) = (settings.vol_quiet_pct, settings.vol_wild_pct);
    let no_trade_vol = quiet_gate > 0.0
        && match zone {
            crate::brain::VolZone::Quiet => true,
            crate::brain::VolZone::Wild => wild_gate > 0.0,
            crate::brain::VolZone::Normal => false,
        };
    let vol_zone = match zone {
        crate::brain::VolZone::Quiet => "quiet",
        crate::brain::VolZone::Normal => "normal",
        crate::brain::VolZone::Wild => "wild",
    };

    // Chart choice. Renko removes intrabar noise in a trending, high-volatility
    // series; Heikin Ashi smooths a choppy series; plain candles are the honest
    // default when neither problem is present.
    let chart_kind = if read.sideways && read.chop > 55.0 {
        "heikin_ashi"
    } else if !read.sideways && atr_pct >= 0.35 {
        "renko"
    } else {
        "candles"
    };

    // Rank the filters on the series the engine will actually trade. A coarse
    // Renko box can collapse 180 bars into a dozen bricks, so fall back to raw
    // candles when the transformed series is too short to score.
    let scored: Vec<Candle> = match ChartKind::parse(chart_kind) {
        ChartKind::Candles => candles.to_vec(),
        kind => {
            let built = algo_core::chart_type::build(kind, candles, &engine_renko_cfg(settings));
            if built.len() >= 60 { built } else { candles.to_vec() }
        }
    };
    let score_atr = if scored.len() >= 15 { regime_atr(&scored, 14).unwrap_or(atr) } else { atr };

    // Round-trip cost in R. Options are the expensive case; this is what turns a
    // "55% win rate" into an actual go/no-go.
    // --- Round-trip cost in R, measured on the same scale as the risk -------
    // The comparison that matters is "cost as a FRACTION of the traded price"
    // versus "the stop distance as a FRACTION of the traded price". Mixing an
    // absolute rupee cost with a points risk (the old bug) reported 2.4R on a
    // 5-minute index whose real friction is a few tenths of a percent.
    //
    // Both terms are therefore fractions of turnover, which are scale free:
    //   * cost_frac = round-trip charges / turnover
    //   * risk_frac = stop distance / price = sl_atr x ATR%
    // For an option the PREMIUM moves much more in percent than the underlying,
    // so the risk fraction is multiplied by the option elasticity. That
    // elasticity is the only input the candle series cannot measure, so it is an
    // explicit operator setting (`brain_option_leverage`) rather than a hidden
    // fudge; leaving it at 0 falls back to delta-one futures behaviour.
    let mut cost_model = crate::brain::CostModel::for_instrument("OPTIDX", "");
    if settings.risk_slippage_bps > 0.0 {
        cost_model.slippage_frac = settings.risk_slippage_bps / 10_000.0;
    }
    // One contract, so the fixed per-order brokerage is spread over the real
    // quantity instead of dominating a single unit.
    let nominal_lot = if settings.lot_size > 0.0 {
        settings.lot_size
    } else if settings.lots > 0.0 {
        settings.lots.max(1.0) * 75.0
    } else {
        75.0
    };
    let turnover = ltp * nominal_lot;
    let cost_frac = if turnover > 0.0 {
        cost_model.round_trip(ltp, ltp, nominal_lot) / turnover
    } else {
        0.0
    };
    let opt_lev = if settings.brain_option_leverage > 0.0 {
        settings.brain_option_leverage
    } else {
        1.0
    };
    let risk_frac = sl_atr * (atr_pct / 100.0) * opt_lev;
    let cost_r = if risk_frac > 0.0 {
        (cost_frac / risk_frac).clamp(0.0, 5.0)
    } else {
        0.0
    };

    let sc = consensus_cfg(settings);
    let sup = support_trend_cfg(settings);
    let res = resistance_trend_cfg(settings);
    let (bull, bull_computable) = brain_rank_side(
        BRAIN_BULL_CANDIDATES,
        &scored,
        score_atr,
        sl_atr,
        tp_rr,
        cost_r,
        sc,
        sup,
        res,
    );
    let (bear, bear_computable) = brain_rank_side(
        BRAIN_BEAR_CANDIDATES,
        &scored,
        score_atr,
        sl_atr,
        tp_rr,
        cost_r,
        sc,
        sup,
        res,
    );

    let fmt_pick = |p: &BrainPick| {
        format!(
            "{} net {:+.2}R / win {:.0}% / payoff {:.2} ({}x){}",
            p.key,
            p.net_r,
            p.win_rate * 100.0,
            p.payoff_r,
            p.samples,
            p.oos_r.map(|o| format!(" oos {:+.2}R", o)).unwrap_or_default()
        )
    };
    let side_note = |pos: &[BrainPick], computable: usize| -> String {
        if !pos.is_empty() {
            pos.iter().take(2).map(fmt_pick).collect::<Vec<_>>().join(", ")
        } else if computable > 0 {
            "no positive net edge - side blocked".to_string()
        } else {
            "no filter computable (legacy fallback armed)".to_string()
        }
    };
    // "Blocked" means the side WAS measurable and lost. An unmeasurable side is
    // NOT blocked - it falls back to the legacy rows so a cold series can never
    // leave the engine structurally unable to trade.
    let bull_blocked = bull.is_empty() && bull_computable > 0;
    let bear_blocked = bear.is_empty() && bear_computable > 0;
    let gate_note = if no_trade_vol {
        format!(" | NO-TRADE: volatility {vol_zone} (ATR {:.2}% at p{:.0})", atr_pct, pct)
    } else {
        format!(" | vol={vol_zone} p{:.0}", pct)
    };
    let note = format!(
        "regime={regime} (ADX {:.1}, CHOP {:.1}, score {}/8) | ATR {:.2}%{gate_note} | SL {sl_atr:.1}xATR, trail {trail_atr:.1}xATR, target {tp_rr:.1}R, cost {cost_r:.2}R (lev x{opt_lev:.0}) | chart={chart_kind} | bull [{}] | bear [{}]",
        read.adx,
        read.chop,
        read.score,
        atr_pct,
        side_note(&bull, bull_computable),
        side_note(&bear, bear_computable),
    );

    Some(BrainPlan {
        regime,
        sl_atr,
        trail_atr,
        tp_rr,
        chart_kind,
        bull,
        bear,
        bull_blocked,
        bear_blocked,
        vol_zone,
        no_trade_vol,
        cost_r,
        note,
    })
}

/// Risk multipliers consumed by `ai_levels`: `(stop in ATR, trail in ATR,
/// target in R)`. The brain's committed values apply ONLY while Auto Trading is
/// ON; with it OFF the historical fixed multipliers return, so a manual trade is
/// never repriced by a stale brain decision.
fn brain_risk_mults(s: &Settings) -> (f64, f64, f64) {
    if !s.auto_trade_on {
        return (1.5, 1.0, 3.0);
    }
    (
        if s.brain_sl_atr > 0.0 { s.brain_sl_atr } else { 1.5 },
        if s.brain_trail_atr > 0.0 { s.brain_trail_atr } else { 1.0 },
        if s.brain_tp_rr > 0.0 { s.brain_tp_rr } else { 3.0 },
    )
}


/// Write a committed plan into the settings: risk knobs, chart, the winning
/// filter rows, and the read-only explanation. Only rows from the candidate
/// pool are touched, so an operator filter outside that pool is never silently
/// switched off by the brain.
fn brain_apply_plan(s: &mut Settings, plan: &BrainPlan) {
    s.brain_sl_atr = plan.sl_atr;
    s.brain_trail_atr = plan.trail_atr;
    s.brain_tp_rr = plan.tp_rr;
    s.brain_regime = plan.regime.to_string();
    s.brain_no_trade_vol = plan.no_trade_vol;
    // Volatility zone + measured round-trip cost are published for the readout:
    // the operator must be able to see WHY a tape was skipped (quiet/wild) and
    // how expensive the trip was in R before trusting the filter ranking.
    s.brain_vol_zone = plan.vol_zone.to_string();
    s.brain_cost_r = plan.cost_r;
    s.brain_note = plan.note.clone();
    s.brain_note_ms = now_ms();
    s.chart_kind = plan.chart_kind.to_string();
    // Brain runs on the transformed chart it just chose, so the filters it
    // ranked are evaluated on exactly the series the engine will trade.
    s.filter_on_display_chart = plan.chart_kind != "candles";

    let bull_keep: Vec<&str> = plan.bull.iter().take(2).map(|p| p.key.as_str()).collect();
    let bear_keep: Vec<&str> = plan.bear.iter().take(2).map(|p| p.key.as_str()).collect();
    for k in BRAIN_BULL_CANDIDATES {
        s.filters.insert((*k).to_string(), bull_keep.contains(k));
    }
    for k in BRAIN_BEAR_CANDIDATES {
        s.filters.insert((*k).to_string(), bear_keep.contains(k));
    }
    // Safety net for the "cannot compute anything" case only: a warm-up series
    // with no measurable row on either side keeps the two legacy rows so the
    // engine is never left structurally unable to trade. A side that WAS
    // measurable but lost money stays deliberately blocked - that is the whole
    // point of ranking on measured expectancy.
    if bull_keep.is_empty() && !plan.bull_blocked {
        s.filters.insert("BullMeetEma9_21".into(), true);
    }
    if bear_keep.is_empty() && !plan.bear_blocked {
        s.filters.insert("BearMeetEma9_21".into(), true);
    }
}

/// Apply the coordinated Auto Trading configuration to one engine's settings.
///
/// This is a PRESET, not a hidden second engine: it only fills in the operator
/// settings the existing engine already consumes (trend following, universe,
/// indicator filters, stop/trail/target), so every trade still runs through the
/// normal signal → filter gate → margin gate → order path. It never touches a
/// field that is not already part of the engine's decision, and it never arms
/// the engine master switch (that stays the operator's explicit action).
///
/// Called on the OFF→ON edge only, so an operator who later tweaks a value (a
/// different stop, more gainers, a stricter filter) keeps their change until
/// they toggle Auto Trading off and on again.
fn apply_auto_trade_preset(s: &mut Settings) {
    // --- Trend following: direction decides the CE/PE leg ---
    s.nifty_trend_on = true;
    s.nifty_trend_pct_on = false;
    if s.nifty_trend_conf_inds.is_empty() {
        s.nifty_trend_conf_inds = AUTO_TRADE_CONF_INDS.iter().map(|x| x.to_string()).collect();
    }
    if s.nifty_tf.trim().is_empty() {
        s.nifty_tf = "5min".into();
    }
    // Strict NET agreement keeps CE/PE honest: a single conflicting confirmation
    // line blocks the wrong-side leg instead of averaging it away. This is the
    // "trade with the trend" contract.
    s.nifty_net_strict = true;
    // Never enter into a range: trend following needs an actual trend.
    s.no_trade_sideways = true;

    // Indices / Commodities-only books (Paper Trade 2/3, Realtime 2/3) have no
    // NIFTY-stock trend section - their own per-instrument trend followers are
    // the equivalent switch, so arm those and let `enforce_constraints` strip the
    // NIFTY half. Without this a PT2/PT3 tab would turn Auto Trading on and then
    // have no universe at all.
    s.index_trend_on = true;
    if s.index_trend_conf_inds.is_empty() {
        s.index_trend_conf_inds = AUTO_TRADE_CONF_INDS.iter().map(|x| x.to_string()).collect();
    }
    s.comm_trend_on = true;
    if s.comm_trend_conf_inds.is_empty() {
        s.comm_trend_conf_inds = AUTO_TRADE_CONF_INDS.iter().map(|x| x.to_string()).collect();
    }

    // --- Universe: the trend-pinned movers scan ---
    s.movers_on = true;
    if s.movers_gainers <= 0 {
        s.movers_gainers = 5;
    }
    if s.movers_losers <= 0 {
        s.movers_losers = 5;
    }
    s.filter_mode = true;
    s.call_manual = true;

    // --- Indicator-filter gate: same held-side rows the trend reads ---
    for k in AUTO_TRADE_BULL_FILTERS {
        s.filters.insert((*k).to_string(), true);
    }
    for k in AUTO_TRADE_BEAR_FILTERS {
        s.filters.insert((*k).to_string(), true);
    }
    // Majority is the default confluence; strict AND would require every single
    // row at once and stall entries, so keep it off unless the operator opted in.
    s.require_condition = true;

    // --- Risk: ATR stop, profit-armed trail, Target-Lab auto-cut ---
    s.sl_auto = true;
    s.manual_sl = false;
    s.ai_sl = false;
    s.ai_trail_tp = true;
    // The trail only arms once the trade is in profit, so a losing trade is cut
    // by the ATR stop and a winning one gives back a fixed slice of its run.
    s.manual_trail_sl = false;
    s.trail_points_from_pct = true;
    s.target_auto_on = true;
    if s.target_min_confidence <= 0.0 || s.target_min_confidence > 100.0 {
        s.target_min_confidence = 60.0;
    }

    // --- Sizing / safety ---
    // Late fills are the main source of bad trend entries: a signal that could
    // not be sized is dropped rather than chased minutes later.
    s.skip_on_margin_block = true;
    s.multi_always_on = false;
    s.multi_fresh_on = true;
    s.entry_latch_on = true;
    if s.trade_limit_count <= 0 {
        s.trade_limit_count = 5;
    }
    s.order_per_sec = order_per_sec_budget(s.order_per_sec.max(6));
}

/// When Auto Trading is switched OFF, new entries stop but open trades must keep
/// their protection. This only releases the entry-side switches it owns; the
/// SL / trail / target settings themselves are left untouched so an open
/// position is never stripped of its stop.
fn clear_auto_trade_entry_gates(s: &mut Settings) {
    s.nifty_trend_on = false;
    s.movers_on = false;
    s.no_trade_sideways = false;
    s.index_trend_on = false;
    s.comm_trend_on = false;
}

fn series_value(s: &algo_core::model::SeriesOut, from_end: usize) -> Option<f64> {    let n = s.data.len();
    if n <= from_end {
        return None;
    }
    let p = &s.data[n - 1 - from_end];
    Some(p.value)
}

/// Value of an indicator line as DRAWN on the candle `offset` bars back from the
/// newest one. Straight-line series are sparse (one point per swing vertex), so a
/// point index is not a bar index - the "Slope from N bars" read must map the
/// bar's time onto the line and interpolate along the segment that spans it.
/// Dense series (one point per candle) read their exact value.
fn series_value_at_bar(s: &algo_core::model::SeriesOut, candles: &[Candle], offset: usize) -> Option<f64> {
    let c = candles.get(candles.len().checked_sub(offset + 1)?)?;
    let data = &s.data;
    if data.is_empty() {
        return None;
    }
    let t = c.time;
    let hi = data.partition_point(|p| p.time <= t);
    match (hi.checked_sub(1), data.get(hi)) {
        (Some(i), Some(next)) if next.time > data[i].time => {
            let a = &data[i];
            let f = (t - a.time) as f64 / (next.time - a.time) as f64;
            let v = a.value + (next.value - a.value) * f;
            v.is_finite().then_some(v)
        }
        (Some(i), _) => data[i].value.is_finite().then_some(data[i].value),
        (None, Some(p)) => p.value.is_finite().then_some(p.value),
        (None, None) => None,
    }
}

fn conditions_met(conds: &[Condition], candles: &[Candle], offset: usize) -> bool {
    condition_detail(conds, candles, offset).0
}

/// Evaluate every condition and return `(all_pass, per-condition readout)`.
/// The readout powers the AI Smart Trading "Live Data Pool" panel so the
/// operator can see the exact indicator value and PASS/FAIL the engine used.
fn condition_detail(conds: &[Condition], candles: &[Candle], offset: usize) -> (bool, Vec<Value>) {
    // One memo scope for the whole condition list: a strategy that references
    // the same indicator in several conditions derives it once.
    let _sc = IndScope::enter();
    let mut all = !conds.is_empty();
    let mut rows = Vec::with_capacity(conds.len());
    for c in conds {
        let settings = if c.settings.is_object() {
            c.settings.as_object().cloned().unwrap_or_default().into_iter().collect()
        } else {
            Default::default()
        };
        let out = ind_series(&c.indicator, candles, &settings);
        let series = match c.source.parse::<usize>() {
            Ok(i) => out.get(i),
            Err(_) => out.first(),
        };
        let last = series.and_then(|s| series_value(s, offset));
        let prev = series.and_then(|s| series_value(s, offset + 1));
        let ok = match c.op.as_str() {
            "gt" => last.map(|l| l > c.value).unwrap_or(false),
            "gte" => last.map(|l| l >= c.value).unwrap_or(false),
            "lt" => last.map(|l| l < c.value).unwrap_or(false),
            "lte" => last.map(|l| l <= c.value).unwrap_or(false),
            "cross_up" => last.zip(prev).map(|(l, p)| p <= c.value && l > c.value).unwrap_or(false),
            "cross_down" => last.zip(prev).map(|(l, p)| p >= c.value && l < c.value).unwrap_or(false),
            "rising" => last.zip(prev).map(|(l, p)| l > p).unwrap_or(false),
            "falling" => last.zip(prev).map(|(l, p)| l < p).unwrap_or(false),
            _ => false,
        };
        if !ok {
            all = false;
        }
        rows.push(json!({
            "indicator": c.indicator,
            "source": c.source,
            "op": c.op,
            "target": c.value,
            "value": last,
            "prev": prev,
            "pass": ok,
        }));
    }
    (all, rows)
}

// ---------------------------------------------------------------------------
// Global indicator-filter gate (AI Smart Trading "Indicator filters")
//
// The old engine exposes ~148 Bullish/Bearish filter toggles that act as entry
// gates on top of a strategy's own conditions. They are persisted in
// `settings.filters`; here each enabled toggle on the strategy's side is
// evaluated against the same candle series. Unimplemented / research-stream
// toggles are treated as non-blocking so a missing indicator can never silently
// freeze live trading.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Ultrafast indicator memo layer (scoped + persistent)
// ---------------------------------------------------------------------------
// A single gate pass can evaluate 100+ filters, and each EMA/BB/Supertrend
// filter re-derives the very same indicator series from the same candle slice.
// Two layers collapse that:
//
//   * A *scoped* per-thread cache (`IndScope`) dedupes within one synchronous
//     pass (gate + conditions + dir-guard + fresh-meet). Keyed by slice pointer,
//     so it needs no content hash and dies with the pass.
//   * A *persistent* content-addressed cache (`IND_GLOBAL`) survives across
//     strategy legs and across engine ticks. Two slices with identical contents
//     (different Vecs, different strategies) share one derivation. The key holds
//     a full fingerprint of the candles, so a changed bar can never read a stale
//     series.
//
// Net effect: the engine derives each (candle-content, indicator, settings)
// combination once, instead of once per filter per strategy per tick.
type IndCacheKey = (usize, usize, u64, u64);
type IndGlobalKey = (u64, u64, u64);

struct IndScopeState {
    cache: HashMap<IndCacheKey, Arc<Vec<algo_core::model::SeriesOut>>>,
    fps: HashMap<(usize, usize), u64>,
}

thread_local! {
    static IND_CACHE: RefCell<Option<IndScopeState>> = const { RefCell::new(None) };
}

static IND_GLOBAL: OnceLock<Mutex<HashMap<IndGlobalKey, Arc<Vec<algo_core::model::SeriesOut>>>>> = OnceLock::new();
const IND_GLOBAL_CAP: usize = 8192;

/// How long a tick-maintained live candle series is trusted before the next
/// scan re-seeds it from REST. Kept a few seconds so a subscribed feed keeps the
/// hot path REST-free while an unsubscribe/quiet symbol still self-heals.
const LIVE_BAR_TTL: Duration = Duration::from_secs(2);

/// Age of the last completed background scanner pass after which the "Why no
/// trades?" panel reports `scanner-stale`. The pass normally completes in well
/// under a second; anything this old means the Dhan data gate is holding it (a
/// `429` penalty) or the pass is wedged, so the operator sees frozen picks
/// explained instead of silently empty Top Movers / Liquid F&O lists.
const SCANNER_STALE_MS: i64 = 20_000;

/// How long an underlying + option side whose premium leg could not be resolved
/// (missing expiry, empty strike bucket, or every strike red) is skipped before
/// the resolver is tried again. The scan runs at 100ms, so without this the same
/// failure re-ran the whole option resolution on every tick.
const NO_PREMIUM_CACHE_MS: i64 = 90_000;

/// Fixed cadence at which the colour detection is re-read. Both the NIFTY-trend
/// colour confirmation and the `SlColor*` indicator-filter gate scan the line
/// colour on this interval instead of on every tick.
pub const COLOR_SCAN_MS: i64 = 1_000;

/// How long a leg's gate must stay falsely BEFORE it counts as a new signal. A
/// single stale / flickering scan must not end the current signal pulse, or the
/// "one trade per signal" rule would re-arm and repeat entries on the same
/// signal. Only a continuous failure of at least this long ends the signal and
/// lets the next meet begin a fresh one.
pub const SIGNAL_END_DEBOUNCE_MS: i64 = 3_000;

/// How long a newly-read NIFTY direction must persist before it replaces the
/// committed side. The assigned straight-line lines are read on every market tick
/// (20 ms) off the live forming bar, so a single wiggle - one line stepping back
/// across a pivot while the other sits flat - can net the opposite sign for a
/// few milliseconds. Committing that flicker flipped the leg/strikes CE<->PE
/// dozens of times a minute, so no side ever stayed armed long enough to trade.
/// A genuine turn persists well beyond this window and still flips.
pub const NIFTY_FLIP_CONFIRM_MS: i64 = 1_500;

/// How long a committed NIFTY side is held through a dead-heat (all assigned
/// indicators flat / tied) before the side is dropped. A momentary tie must not
/// free both legs, but a tie that never resolves used to pin the old side
/// forever - so a later genuine turn was never seen and no flip was detected.
pub const NIFTY_TIE_CLEAR_MS: i64 = 5_000;

/// A sampled colour-filter decision plus when it was taken.
#[derive(Clone)]
struct ColorSample {
    at_ms: i64,
    val: Option<bool>,
}

/// Candle-series identity for the colour sample cache: a filter key is unique per
/// instrument series (first bar time + length pins the series), so the same 5s
/// sample is reused across the strategies that share the candles.
type ColorSampleKey = (String, i64, usize, usize);

fn color_samples() -> &'static Mutex<HashMap<ColorSampleKey, ColorSample>> {
    static M: OnceLock<Mutex<HashMap<ColorSampleKey, ColorSample>>> = OnceLock::new();
    M.get_or_init(|| Mutex::new(HashMap::with_capacity(256)))
}

/// True for the dedicated "Straight Line Indicator Color Detection" gate keys.
fn is_color_filter(k: &str) -> bool {
    k.starts_with("BullSlColor") || k.starts_with("BearSlColor")
}

/// Evaluate a colour filter at most once per `COLOR_SCAN_MS`, so the algo reads
/// the assigned straight-line overlays' colour on the fixed cadence rather than
/// re-deriving it on every tick. `None` (line not drawn yet) is cached too, so an
/// un-drawn line is not re-checked until the next scan. The pure `filter_eval`
/// path (used by the colour unit tests) is unaffected.
fn color_filter_sampled(
    k: &str,
    candles: &[Candle],
    offset: usize,
    cons: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> Option<bool> {
    if candles.is_empty() {
        return filter_eval_inner(k, candles, offset, cons, sup, res);
    }
    let key: ColorSampleKey = (k.to_string(), candles[0].time, candles.len(), offset);
    let now = now_ms();
    if let Ok(g) = color_samples().lock() {
        if let Some(s) = g.get(&key) {
            if now - s.at_ms < COLOR_SCAN_MS {
                return s.val;
            }
        }
    }
    let val = filter_eval_inner(k, candles, offset, cons, sup, res);
    if let Ok(mut g) = color_samples().lock() {
        if g.len() > 4096 {
            g.clear();
        }
        g.insert(key, ColorSample { at_ms: now, val });
    }
    val
}

/// Evaluate one gate filter, routing the colour-detection keys through the fixed
/// colour scan so the indicator-filter colour detection shares the same cadence as
/// the NIFTY trend read. Every other filter stays tick-native.
#[inline]
fn gate_filter_eval(
    k: &str,
    candles: &[Candle],
    offset: usize,
    cons: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> Option<bool> {
    if is_color_filter(k) {
        color_filter_sampled(k, candles, offset, cons, sup, res)
    } else {
        filter_eval_inner(k, candles, offset, cons, sup, res)
    }
}

fn ind_global() -> &'static Mutex<HashMap<IndGlobalKey, Arc<Vec<algo_core::model::SeriesOut>>>> {
    IND_GLOBAL.get_or_init(|| Mutex::new(HashMap::with_capacity(512)))
}

#[inline]
fn global_get(key: &IndGlobalKey) -> Option<Arc<Vec<algo_core::model::SeriesOut>>> {
    ind_global().lock().ok().and_then(|g| g.get(key).cloned())
}

#[inline]
fn global_put(key: IndGlobalKey, v: Arc<Vec<algo_core::model::SeriesOut>>) {
    if let Ok(mut g) = ind_global().lock() {
        if g.len() >= IND_GLOBAL_CAP {
            g.clear();
        }
        g.insert(key, v);
    }
}

#[cfg(test)]
fn reset_global_ind_cache() {
    if let Ok(mut g) = ind_global().lock() {
        g.clear();
    }
}

/// RAII scope. Nested scopes share the outermost cache; only the outermost
/// drop clears it, so a helper that opens its own scope can never wipe a
/// caller's memo mid-pass.
struct IndScope {
    outer: bool,
}

impl IndScope {
    #[inline]
    fn enter() -> Self {
        let outer = IND_CACHE.with(|c| {
            let mut slot = c.borrow_mut();
            if slot.is_some() {
                false
            } else {
                *slot = Some(IndScopeState {
                    cache: HashMap::with_capacity(96),
                    fps: HashMap::with_capacity(4),
                });
                true
            }
        });
        IndScope { outer }
    }
}

impl Drop for IndScope {
    #[inline]
    fn drop(&mut self) {
        if self.outer {
            IND_CACHE.with(|c| *c.borrow_mut() = None);
        }
    }
}

#[inline]
fn hash_str(s: &str) -> u64 {
    let mut h = std::collections::hash_map::DefaultHasher::new();
    s.hash(&mut h);
    h.finish()
}

#[inline]
fn hash_settings(s: &algo_core::model::Settings) -> u64 {
    let mut h = std::collections::hash_map::DefaultHasher::new();
    for (k, v) in s.iter() {
        k.hash(&mut h);
        v.hash(&mut h);
    }
    h.finish()
}

/// Full content fingerprint of a candle slice (the persistent cache key's data
/// component). `to_bits` keeps the hash stable for NaN/-0.0 forms.
fn candle_fingerprint(candles: &[Candle]) -> u64 {
    let mut h = std::collections::hash_map::DefaultHasher::new();
    candles.len().hash(&mut h);
    for c in candles {
        c.time.hash(&mut h);
        c.open.to_bits().hash(&mut h);
        c.high.to_bits().hash(&mut h);
        c.low.to_bits().hash(&mut h);
        c.close.to_bits().hash(&mut h);
        c.volume.to_bits().hash(&mut h);
    }
    h.finish()
}

/// Single choke point for the (expensive) indicator derivation, so the memo
/// layer can be instrumented in tests without touching every caller.
#[inline]
fn do_compute(id: &str, candles: &[Candle], settings: &algo_core::model::Settings) -> Vec<algo_core::model::SeriesOut> {
    #[cfg(test)]
    IND_COMPUTE_CALLS.with(|c| c.set(c.get() + 1));
    algo_core::compute(id, candles, settings)
}

#[cfg(test)]
thread_local! {
    static IND_COMPUTE_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(test)]
fn ind_compute_calls() -> usize {
    IND_COMPUTE_CALLS.with(|c| c.get())
}

#[cfg(test)]
fn reset_ind_compute_calls() {
    IND_COMPUTE_CALLS.with(|c| c.set(0));
}

/// Memoised `algo_core::compute`: scoped cache -> persistent content cache ->
/// real derivation. Outside an `IndScope` it is still globally shared, so every
/// caller stays correct and still benefits from cross-strategy reuse.
#[inline]
fn ind_series(id: &str, candles: &[Candle], settings: &algo_core::model::Settings) -> Arc<Vec<algo_core::model::SeriesOut>> {
    let idh = hash_str(id);
    let seth = hash_settings(settings);
    let ptr = candles.as_ptr() as usize;
    let len = candles.len();
    let skey: IndCacheKey = (ptr, len, idh, seth);
    IND_CACHE.with(|c| {
        let mut slot = c.borrow_mut();
        match slot.as_mut() {
            Some(st) => {
                if let Some(hit) = st.cache.get(&skey) {
                    return hit.clone();
                }
                let fp = match st.fps.get(&(ptr, len)) {
                    Some(fp) => *fp,
                    None => {
                        let fp = candle_fingerprint(candles);
                        st.fps.insert((ptr, len), fp);
                        fp
                    }
                };
                let gkey: IndGlobalKey = (fp, idh, seth);
                if let Some(hit) = global_get(&gkey) {
                    st.cache.insert(skey, hit.clone());
                    return hit;
                }
                let v = Arc::new(do_compute(id, candles, settings));
                global_put(gkey, v.clone());
                st.cache.insert(skey, v.clone());
                v
            }
            None => {
                let fp = candle_fingerprint(candles);
                let gkey: IndGlobalKey = (fp, idh, seth);
                if let Some(hit) = global_get(&gkey) {
                    return hit;
                }
                let v = Arc::new(do_compute(id, candles, settings));
                global_put(gkey, v.clone());
                v
            }
        }
    })
}

fn ind_at(id: &str, candles: &[Candle], params: &[(&str, f64)], offset: usize) -> Option<f64> {
    let st: algo_core::model::Settings = params.iter().map(|(k, v)| (k.to_string(), json!(v))).collect();
    let out = ind_series(id, candles, &st);
    out.first().and_then(|s| series_value(s, offset))
}

/// Value of the `idx`-th output series of an indicator (v0 = 0).
fn ind_n(id: &str, candles: &[Candle], params: &[(&str, f64)], idx: usize, offset: usize) -> Option<f64> {
    let st: algo_core::model::Settings = params.iter().map(|(k, v)| (k.to_string(), json!(v))).collect();
    let out = ind_series(id, candles, &st);
    out.get(idx).and_then(|s| series_value(s, offset))
}

fn st_val(factor: f64, candles: &[Candle], offset: usize) -> Option<f64> {
    ind_at("supertrend", candles, &[("atrPeriod", 10.0), ("factor", factor)], offset)
}

/// Bollinger middle band (v1) and Price-Channel midpoint ((v0+v1)/2).
fn bb_mid(candles: &[Candle], offset: usize) -> Option<f64> {
    ind_n("bb", candles, &[("length", 20.0), ("mult", 2.0)], 1, offset)
}
fn pc_mid(candles: &[Candle], offset: usize) -> Option<f64> {
    let h = ind_n("pc", candles, &[("length", 20.0)], 0, offset)?;
    let l = ind_n("pc", candles, &[("length", 20.0)], 1, offset)?;
    Some((h + l) / 2.0)
}

/// Indicator level for the "candle closed above / below" filter family.
/// `rest` is the token after `ClosedAbove` / `ClosedBelow` (e.g. `Ema21`,
/// `St10_2`, `Vwap`, `BbMid`). Read at the SAME bar the close is read from, so
/// the comparison is candle-close vs indicator-on-that-candle.
fn closed_indicator_level(rest: &str, candles: &[Candle], offset: usize) -> Option<f64> {
    if let Some(n) = rest.strip_prefix("Ema") {
        return ema_val(n.parse::<i64>().ok()?, candles, offset);
    }
    if let Some(f) = rest.strip_prefix("St10_") {
        return st_val(f.parse::<f64>().ok()?, candles, offset);
    }
    match rest {
        "Vwap" => ind_at("vwap", candles, &[], offset),
        "BbUpper" => ind_n("bb", candles, &[("length", 20.0), ("mult", 2.0)], 0, offset),
        "BbMid" => bb_mid(candles, offset),
        "BbLower" => ind_n("bb", candles, &[("length", 20.0), ("mult", 2.0)], 2, offset),
        "PcMid" => pc_mid(candles, offset),
        "Hma" => ind_at("hma", candles, &[("length", 20.0)], offset),
        "Ma" => ind_at("ma", candles, &[("length", 20.0)], offset),
        "Smma" => ind_at("smma", candles, &[("length", 20.0)], offset),
        "KeltnerUpper" => ind_n("keltner", candles, &[("length", 20.0), ("mult", 2.0)], 0, offset),
        "KeltnerMid" => ind_n("keltner", candles, &[("length", 20.0), ("mult", 2.0)], 1, offset),
        "KeltnerLower" => ind_n("keltner", candles, &[("length", 20.0), ("mult", 2.0)], 2, offset),
        "DonchianUpper" => ind_n("donchian", candles, &[("length", 20.0)], 0, offset),
        "DonchianMid" => ind_n("donchian", candles, &[("length", 20.0)], 1, offset),
        "DonchianLower" => ind_n("donchian", candles, &[("length", 20.0)], 2, offset),
        "Tenkan" => ind_n("ichimoku", candles, &[], 0, offset),
        "Kijun" => ind_n("ichimoku", candles, &[], 1, offset),
        "SenkouA" => ind_n("ichimoku", candles, &[], 2, offset),
        "SenkouB" => ind_n("ichimoku", candles, &[], 3, offset),
        "Chandelier" => ind_n("chandelier", candles, &[("length", 22.0), ("mult", 3.0)], 0, offset),
        _ => None,
    }
}

/// "Candle closed above / below <indicator>" persistent LEVEL gate.
///
/// True on every scan while the last CLOSED candle's close sits on the wanted
/// side of the indicator, false the moment it does not. The read is pinned to
/// the last closed candle (offset 1) and ignores the forming-bar options, so an
/// intrabar repaint of the live candle can never flip the gate mid-bar. `None`
/// (indicator not warm / not computable) fails closed at the gate.
fn closed_vs_indicator(rest: &str, above: bool, candles: &[Candle]) -> Option<bool> {
    let offset = 1usize;
    let close = close_at(candles, offset)?;
    let level = closed_indicator_level(rest, candles, offset)?;
    Some(if above { close > level } else { close < level })
}

fn close_at(candles: &[Candle], offset: usize) -> Option<f64> {
    let n = candles.len();
    if n <= offset {
        None
    } else {
        Some(candles[n - 1 - offset].close)
    }
}

/// The candlestick value used by the crossover helpers, expressed as EMA(1).
///
/// A 1-period EMA is, by definition, the current bar, so the "EMA1" in
/// "EMA21 crossed below EMA1" / "VWAP cross below EMA1" is just the candle.
/// Only the cross-above/cross-below helpers read this; level, trend and gap
/// confirmations keep using the raw candle close/body instead.
fn ema1(candles: &[Candle], offset: usize) -> Option<f64> {
    close_at(candles, offset)
}

fn ema_val(n: i64, candles: &[Candle], offset: usize) -> Option<f64> {
    if n <= 1 {
        // EMA(1) is the candlestick (bar value).
        ema1(candles, offset)
    } else {
        ind_at("ema", candles, &[("length", n as f64)], offset)
    }
}

fn parse_pair(s: &str) -> Option<(i64, i64)> {
    let mut it = s.split('_');
    let a = it.next()?.parse().ok()?;
    let b = it.next()?.parse().ok()?;
    Some((a, b))
}

/// Candlestick rising/falling between the live bar and the previous bar.
fn rising_close(candles: &[Candle], offset: usize) -> bool {
    matches!((close_at(candles, offset), close_at(candles, offset + 1)), (Some(a), Some(b)) if a > b)
}
fn falling_close(candles: &[Candle], offset: usize) -> bool {
    matches!((close_at(candles, offset), close_at(candles, offset + 1)), (Some(a), Some(b)) if a < b)
}

/// Gap direction from the raw candle body: a bullish gap opens above the prior
/// bar's high, a bearish gap opens below the prior bar's low.
fn gap_dir(candles: &[Candle], offset: usize, up: bool) -> Option<bool> {
    let n = candles.len();
    if n <= offset + 1 {
        return None;
    }
    let cur = &candles[n - 1 - offset];
    let prev = &candles[n - 2 - offset];
    Some(if up { cur.open > prev.high } else { cur.open < prev.low })
}

fn line_dir(id: &str, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let a = ind_at(id, candles, &[], offset)?;
    let b = ind_at(id, candles, &[], offset + 1)?;
    Some(if bull { a > b } else { a < b })
}

/// Direction of a specific output series of an indicator (rising = bull).
fn series_dir(id: &str, params: &[(&str, f64)], idx: usize, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let a = ind_n(id, candles, params, idx, offset)?;
    let b = ind_n(id, candles, params, idx, offset + 1)?;
    Some(if bull { a > b } else { a < b })
}

/// Window (bars) whose average absolute step sets the straight-line noise floor.
const STRAIGHT_LINE_NOISE_WINDOW: usize = 5;

thread_local! {
    /// "Slope from N bars" mode for indicator-FILTER slope reads. `0` = OFF (the
    /// 5-point noise-floor window); `N >= 1` = read the line's slope over the last
    /// N closed bars. Set from the operator setting around each filter evaluation
    /// (`filter_gate_facts`), so every straight-line filter in the Bull/Bear lists
    /// reads the same window. Pure and synchronous (no await between set and read),
    /// so a thread-local is safe here.
    static FILTER_SLOPE_BARS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

fn filter_slope_bars() -> usize {
    FILTER_SLOPE_BARS.with(|c| c.get())
}

/// RAII guard: sets the N-bar slope mode for the current evaluation and restores
/// the previous value on drop (so nested/lent calls never leak the setting).
struct FilterSlopeBarsGuard(usize);
impl FilterSlopeBarsGuard {
    fn enter(on: bool, bars: usize) -> Self {
        let prev = filter_slope_bars();
        let next = if on { bars.max(1) } else { 0 };
        FILTER_SLOPE_BARS.with(|c| c.set(next));
        FilterSlopeBarsGuard(prev)
    }
}
impl Drop for FilterSlopeBarsGuard {
    fn drop(&mut self) {
        let prev = self.0;
        FILTER_SLOPE_BARS.with(|c| c.set(prev));
    }
}

/// Crossover read configuration for the current filter pass. Mirrors the
/// "Slope from N bars" thread-local: the operator setting is copied in around
/// each gate evaluation, so every crossover filter on both sides reads the same
/// bar type and confirmation window.
#[derive(Clone, Copy, Default)]
struct FilterCrossCfg {
    /// True = read the last CLOSED candle, false = the live forming candle.
    closed: bool,
    /// True when the offset handed to the filter pass was ALREADY shifted to the
    /// last closed candle by "Formed candle only (closed bar)". The cross helper
    /// then must not shift it a second time.
    offset_closed: bool,
    /// Bars the cross must have held for (0 = instant, read bar vs previous).
    bars: usize,
}

thread_local! {
    static FILTER_CROSS_CFG: std::cell::Cell<FilterCrossCfg> =
        const { std::cell::Cell::new(FilterCrossCfg { closed: false, offset_closed: false, bars: 0 }) };
}

fn filter_cross_cfg() -> FilterCrossCfg {
    FILTER_CROSS_CFG.with(|c| c.get())
}

/// Set the crossover read configuration for one pass; restored on drop.
struct FilterCrossGuard(FilterCrossCfg);
impl FilterCrossGuard {
    fn enter(settings: &Settings, offset_closed: bool) -> Self {
        let prev = filter_cross_cfg();
        FILTER_CROSS_CFG.with(|c| {
            c.set(FilterCrossCfg {
                closed: settings.closed_bar_compute || settings.ind_cross_on_closed,
                offset_closed,
                bars: settings.ind_cross_bars.min(500),
            })
        });
        FilterCrossGuard(prev)
    }
}
impl Drop for FilterCrossGuard {
    fn drop(&mut self) {
        FILTER_CROSS_CFG.with(|c| c.set(self.0));
    }
}

thread_local! {
    /// Execution-instant re-check mode: a crossover that printed on the decision
    /// bar is still accepted when the fill lands one bar later (bar rollover
    /// inside the paper-delay / feed-LTP window). The scan itself never uses
    /// this - it fires only on the bar the cross actually printed.
    static CROSS_FILL_GRACE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

struct CrossFillGraceGuard(bool);
impl CrossFillGraceGuard {
    fn enter() -> Self {
        let prev = CROSS_FILL_GRACE.with(|c| c.replace(true));
        CrossFillGraceGuard(prev)
    }
}
impl Drop for CrossFillGraceGuard {
    fn drop(&mut self) {
        CROSS_FILL_GRACE.with(|c| c.set(self.0));
    }
}

fn cross_fill_grace() -> bool {
    CROSS_FILL_GRACE.with(|c| c.get())
}

/// Tokens whose evaluation is a crossover EVENT (`cross_from_sign`) rather than
/// a held level. Used only by the fill-time grace above.
fn is_cross_filter_key(k: &str) -> bool {
    let base = k
        .strip_prefix("Bull")
        .or_else(|| k.strip_prefix("Bear"))
        .unwrap_or(k);
    if matches!(
        base,
        "CrossUp"
            | "CrossDown"
            | "PaneCrossUp"
            | "PaneCrossDown"
            | "St1CloseCrossAbove"
            | "St1CloseCrossBelow"
            | "VwapCloseCrossAbove"
            | "VwapCloseCrossBelow"
            | "BbCrossAbove"
            | "BbCrossBelow"
            | "PcCrossAbove"
            | "PcCrossBelow"
    ) {
        return true;
    }
    if let Some(rest) = base.strip_prefix("St10_") {
        return parse_pair(rest).is_some();
    }
    if let Some(rest) = base.strip_prefix("Slema") {
        return parse_pair(rest).is_some();
    }
    if let Some(rest) = base.strip_prefix("Ema") {
        return !rest.starts_with("Trend") && parse_pair(rest).is_some();
    }
    false
}

/// Bar the crossover filters must read: forming (0) or last closed (1). When the
/// pass offset is already closed (global "Formed candle only"), the passed offset
/// is used as-is.
fn cross_base() -> usize {
    let cfg = filter_cross_cfg();
    if cfg.closed && !cfg.offset_closed { 1 } else { 0 }
}

/// Crossover detection over the configured read bar and confirmation window.
/// `sign(offset)` returns the fast-vs-slow side (true = fast above slow) at that
/// bar. `bull` selects the wanted side. With `bars = 0` the cross is read on the
/// base bar vs the bar before it (forming = current tick, closed = last closed).
/// With `bars = N` the wanted side must have held on the base bar and the N bars
/// before it, and the bar before those must be the opposite side - i.e. the
/// cross happened exactly N bars before the read bar and has held since. A read
/// that cannot be computed returns `None` (fail closed at the gate).
fn cross_from_sign<F>(offset: usize, sign: F, bull: bool) -> Option<bool>
where
    F: Fn(usize) -> Option<bool>,
{
    let base = offset + cross_base();
    let now = sign(base)?;
    if now != bull {
        return Some(false);
    }
    let cfg = filter_cross_cfg();
    if cfg.bars == 0 {
        let prev = sign(base + 1)?;
        return Some(prev != now);
    }
    for k in 1..=cfg.bars {
        if sign(base + k)? != now {
            return Some(false);
        }
    }
    let pre = sign(base + cfg.bars + 1)?;
    Some(pre != now)
}

/// Latched level read (Straight-Line EMA crossover rows): the wanted side must
/// hold on the base bar and - when a confirmation window is set - on the N bars
/// before it. No pre-cross requirement, so it stays true while the level stands.
fn level_from_sign<F>(offset: usize, sign: F, bull: bool) -> Option<bool>
where
    F: Fn(usize) -> Option<bool>,
{
    let base = offset + cross_base();
    if sign(base)? != bull {
        return Some(false);
    }
    let bars = filter_cross_cfg().bars;
    for k in 1..=bars {
        if sign(base + k)? != bull {
            return Some(false);
        }
    }
    Some(true)
}

/// Plain N-bar slope of one indicator series: the value on the newest bar vs its
/// value `bars` bars ago (`Some(true)` = rising). `bars = 1` is the
/// newest-vs-previous step; larger `bars` smooths the read.
fn series_dir_bars(id: &str, params: &[(&str, f64)], idx: usize, bull: bool, candles: &[Candle], offset: usize, bars: usize) -> Option<bool> {
    let st: algo_core::model::Settings = params.iter().map(|(k, v)| (k.to_string(), json!(v))).collect();
    let out = ind_series(id, candles, &st);
    let s = out.get(idx)?;
    let a = series_value_at_bar(s, candles, offset)?;
    let b = series_value_at_bar(s, candles, offset + bars)?;
    Some(if bull { a > b } else { a < b })
}

/// Like `series_dir`, but the step must clear the straight-line NOISE FLOOR
/// (`straight_line_trend`) to count as a trend: a move smaller than half the
/// recent average step reads `Flat` and returns `None`, so a sub-noise flicker
/// is never mistaken for a real bull/bear turn. The caller fails closed on
/// `None`, so noise BLOCKS instead of firing a false entry. This is the read the
/// old "Visible Straight Line Filter" used before it was flattened to a plain
/// newest-vs-previous step.
fn series_dir_noisy(id: &str, params: &[(&str, f64)], idx: usize, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    // "Slope from N bars": bypass the noise-floor window and read the plain
    // N-bar slope (N = 1 gives the max-responsiveness newest-vs-previous step).
    let bars = filter_slope_bars();
    if bars >= 1 {
        return series_dir_bars(id, params, idx, bull, candles, offset, bars);
    }
    let st: algo_core::model::Settings = params.iter().map(|(k, v)| (k.to_string(), json!(v))).collect();
    let out = ind_series(id, candles, &st);
    let s = out.get(idx)?;
    match straight_line_trend(s, offset, STRAIGHT_LINE_NOISE_WINDOW)? {
        SlTrend::Bull => Some(bull),
        SlTrend::Bear => Some(!bull),
        SlTrend::Flat => None,
    }
}

/// Level comparison between two output series of one indicator (main vs signal).
fn series_pair(id: &str, params: &[(&str, f64)], ia: usize, ib: usize, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let a = ind_n(id, candles, params, ia, offset)?;
    let b = ind_n(id, candles, params, ib, offset)?;
    Some(if bull { a > b } else { a < b })
}

/// OI Trend gate (old AST `oitrend` indicator): direction of the candle-driven
/// hysteresis regime line (fast 9 / slow 21 / enter 0.45 / exit 0.12). Bullish
/// tolerates a rising line, bearish a falling line. This is the same `regime_line`
/// the chart's OI Trend overlay draws, so the gate matches what the operator sees.
fn oit_dir(bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let reg = algo_core::oi_trend::regime_line(candles, &algo_core::oi_trend::RegimeOpts::default());
    let n = reg.data.len();
    if n <= offset + 1 {
        return None;
    }
    let a = reg.data[n - 1 - offset].value;
    let b = reg.data[n - 2 - offset].value;
    Some(if bull { a > b } else { a < b })
}

/// Candlestick close vs one output series of an indicator (overlay Meet level).
fn close_vs_series(id: &str, params: &[(&str, f64)], idx: usize, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let c = close_at(candles, offset)?;
    let v = ind_n(id, candles, params, idx, offset)?;
    Some(if bull { c > v } else { c < v })
}

/// Overlay/structural indicator id + output index for the OBR (direction) and
/// Straight-Line families.
fn overlay_series(base: &str) -> Option<(&'static str, usize)> {
    Some(match base {
        "Hma" => ("hma", 0),
        "Tenkan" => ("ichimoku", 0),
        "Kijun" => ("ichimoku", 1),
        "SenkouA" => ("ichimoku", 2),
        "Keltner" => ("keltner", 1),
        "Donchian" => ("donchian", 1),
        "TrendCore" => ("vlcore", 0),
        _ => return None,
    })
}

fn sl_series(base: &str) -> Option<(&'static str, usize)> {
    Some(match base {
        "ElliottWave" => ("ewtrend", 0),
        "SupplyDemand" => ("supplydemand", 0),
        "PriceAction" => ("patrend", 0),
        "ZigZag" => ("zzline", 0),
        "ComboMaster" => ("trendmaster", 0),
        "PaneConsensus" => ("panemaster", 0),
        "AutoTrendline" => ("autotrend", 0),
        "Pitchfork" => ("pitchfork", 0),
        "TrendProjection" => ("projline", 0),
        "GannFan" => ("gant", 0),
        "FibFan" => ("fibt", 0),
        "Srema" => ("sremat", 0),
        "StraightEma" => ("slema", 0),
        "BbPctSl" => ("bbpctsl", 0),
        "Support" => ("supline", 0),
        "Resistance" => ("resline", 0),
        _ => return None,
    })
}

/// Straight Line Consensus gate: majority vote of the twelve straight-line
/// indicators (see `algo_core::indicators::sl_consensus_dir`). `offset` bars
/// back; a bar before the consensus resolves returns `None` so the caller treats
/// it as non-blocking, exactly like the other straight-line gates.
#[derive(Clone, Copy)]
struct ConsensusCfg {
    need: i32,
    confirm: usize,
    strength: f64,
}

impl Default for ConsensusCfg {
    fn default() -> Self {
        // Chart-indicator defaults (structural gating on).
        ConsensusCfg { need: 2, confirm: 5, strength: 5.0 }
    }
}

/// Indicator-filter settings for the Consensus filter rows. The operator asked
/// for these to be FIXED (the settings gear was removed): Min net votes 1,
/// Confirm bars 0, Swing strength 2.
fn consensus_cfg(_settings: &Settings) -> ConsensusCfg {
    ConsensusCfg { need: 1, confirm: 0, strength: 2.0 }
}

/// Indicator-filter settings for the Support / Resistance Trendline filter rows.
/// Mirrors the geometry inputs of the `supline` / `resline` chart indicators so
/// the fitted line the gate reads is exactly the line the panel describes.
#[derive(Clone, Copy)]
struct PivotTrendCfg {
    strength: f64,
    atr_period: f64,
    min_pct: f64,
    tol_mult: f64,
    look: f64,
    fwd: f64,
    full_span: bool,
}

impl Default for PivotTrendCfg {
    fn default() -> Self {
        // Chart-indicator defaults (matches the registry `supline` / `resline`).
        PivotTrendCfg {
            strength: 5.0,
            atr_period: 14.0,
            min_pct: 0.05,
            tol_mult: 0.5,
            look: 12.0,
            fwd: 10.0,
            full_span: false,
        }
    }
}

impl PivotTrendCfg {
    fn to_settings(self) -> algo_core::model::Settings {
        let mut st = algo_core::model::Settings::new();
        st.insert("strength".into(), json!(self.strength));
        st.insert("atrPeriod".into(), json!(self.atr_period));
        st.insert("minPct".into(), json!(self.min_pct));
        st.insert("tolMult".into(), json!(self.tol_mult));
        st.insert("look".into(), json!(self.look));
        st.insert("fwd".into(), json!(self.fwd));
        st.insert("fullSpan".into(), json!(self.full_span));
        st
    }
}

fn support_trend_cfg(settings: &Settings) -> PivotTrendCfg {
    PivotTrendCfg {
        strength: settings.sup_strength,
        atr_period: settings.sup_atr_period,
        min_pct: settings.sup_min_pct,
        tol_mult: settings.sup_tol_mult,
        look: settings.sup_look,
        fwd: settings.sup_fwd,
        full_span: settings.sup_full_span,
    }
}

fn resistance_trend_cfg(settings: &Settings) -> PivotTrendCfg {
    PivotTrendCfg {
        strength: settings.res_strength,
        atr_period: settings.res_atr_period,
        min_pct: settings.res_min_pct,
        tol_mult: settings.res_tol_mult,
        look: settings.res_look,
        fwd: settings.res_fwd,
        full_span: settings.res_full_span,
    }
}

/// Direction of a trendline (`supline` / `resline`) fitted with the filter's own
/// geometry settings: `Some(true)` = rising, `Some(false)` = falling. `None` when
/// the line is not drawn yet, so the caller treats it as non-blocking exactly
/// like the other straight-line gates.
fn trend_line_dir(id: &str, cfg: PivotTrendCfg, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let st = cfg.to_settings();
    let out = ind_series(id, candles, &st);
    let s = out.first()?;
    let a = series_value(s, offset)?;
    let b = series_value(s, offset + 1)?;
    Some(if bull { a > b } else { a < b })
}

/// `trend_line_dir` with the straight-line NOISE FLOOR: a step smaller than half
/// the recent average step reads `Flat` (returns `None`) so a fitted support /
/// resistance line's sub-noise wiggle never fakes a trend flip.
fn trend_line_dir_noisy(id: &str, cfg: PivotTrendCfg, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    // "Slope from N bars": read the plain N-bar slope (N = 1 = newest-vs-previous).
    let bars = filter_slope_bars();
    if bars >= 1 {
        let st = cfg.to_settings();
        let out = ind_series(id, candles, &st);
        let s = out.first()?;
        let a = series_value_at_bar(s, candles, offset)?;
        let b = series_value_at_bar(s, candles, offset + bars)?;
        return Some(if bull { a > b } else { a < b });
    }
    let st = cfg.to_settings();
    let out = ind_series(id, candles, &st);
    let s = out.first()?;
    match straight_line_trend(s, offset, STRAIGHT_LINE_NOISE_WINDOW)? {
        SlTrend::Bull => Some(bull),
        SlTrend::Bear => Some(!bull),
        SlTrend::Flat => None,
    }
}

fn sl_consensus_at(candles: &[Candle], offset: usize, sc: ConsensusCfg) -> Option<i32> {
    let dirs = algo_core::indicators::sl_consensus_dir(candles, sc.need, sc.confirm, sc.strength);
    let n = dirs.len();
    if n <= offset {
        return None;
    }
    Some(dirs[n - 1 - offset])
}

fn sl_consensus_ok(bull: bool, candles: &[Candle], offset: usize, sc: ConsensusCfg) -> bool {
    match sl_consensus_at(candles, offset, sc) {
        Some(d) => {
            if bull {
                d >= 0
            } else {
                d <= 0
            }
        }
        None => true,
    }
}

fn sl_consensus_flip(bull: bool, candles: &[Candle], offset: usize, sc: ConsensusCfg) -> bool {
    let now = match sl_consensus_at(candles, offset, sc) {
        Some(d) => d,
        None => return true,
    };
    let prev = sl_consensus_at(candles, offset + 1, sc);
    let want = if bull { 1 } else { -1 };
    now == want && prev != Some(want)
}

/// Fresh trend-start arrow for one line: `true` only on the bar where the line's
/// direction just flipped to the requested side (bullish = rising, bearish =
/// falling). Uses the exact direction the AST "Straight Line" trend filters read,
/// so the arrow a trader sees on the chart is the arrow this gate detects.
///
/// A line that is not drawn yet (no resolved pivots / warm-up) is non-blocking,
/// exactly like the Straight Line trend filters, so an unresolvable indicator can
/// never freeze live entries.
fn arrow_flip(id: &str, idx: usize, bull: bool, candles: &[Candle], offset: usize) -> bool {
    match series_dir(id, &[], idx, bull, candles, offset) {
        Some(now) => {
            let prev = series_dir(id, &[], idx, bull, candles, offset + 1);
            now && prev != Some(true)
        }
        None => true,
    }
}

/// `Arrow*` gate key (prefix already stripped): a fresh up/down arrow on the
/// selected indicator. `Oit` uses the OI-Trend regime line, `TrendCore` the
/// Trend Core overlay, `Vl` the Volume Line; everything else maps through the
/// straight-line catalogue.
fn arrow_gate(rest: &str, bull: bool, candles: &[Candle], offset: usize, sc: ConsensusCfg) -> Option<bool> {
    if rest == "Consensus" {
        return Some(sl_consensus_flip(bull, candles, offset, sc));
    }
    if rest == "Oit" {
        return Some(match oit_dir(bull, candles, offset) {
            Some(now) => {
                let prev = oit_dir(bull, candles, offset + 1);
                now && prev != Some(true)
            }
            None => true,
        });
    }
    // Straight-line fits recompute to a constant slope, so a per-bar slope
    // change never fires and their arrow filter could never trade. Detect the
    // trend-start on the ATR zigzag structure instead - the same structure the
    // chart arrow for these indicators is drawn from.
    if matches!(rest, "Srema" | "AutoTrendline" | "Pitchfork" | "TrendProjection" | "GannFan" | "FibFan" | "Support" | "Resistance") {
        return algo_core::indicators::trend_flip_at(candles, offset, bull, 5.0);
    }
    let (id, idx) = if rest == "TrendCore" {
        overlay_series("TrendCore")?
    } else if rest == "Vl" {
        ("vl", 0)
    } else {
        sl_series(rest)?
    };
    Some(arrow_flip(id, idx, bull, candles, offset))
}

fn ema_family(base: &str, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    if let Some(rest) = base.strip_prefix("Meet") {
        let r = rest.strip_prefix("Ema")?;
        let (a, b) = parse_pair(r)?;
        let va = ema_val(a, candles, offset)?;
        let vb = ema_val(b, candles, offset)?;
        return Some(if bull { va > vb } else { va < vb });
    }
    if let Some(rest) = base.strip_prefix("EmaTrend") {
        let n: i64 = rest.parse().ok()?;
        let va = ema_val(n, candles, offset)?;
        let vp = ema_val(n, candles, offset + 1)?;
        return Some(if bull { va > vp } else { va < vp });
    }
    if let Some(rest) = base.strip_prefix("Ema") {
        if let Some((a, b)) = parse_pair(rest) {
            return cross_from_sign(offset, |o| Some(ema_val(a, candles, o)? > ema_val(b, candles, o)?), bull);
        }
    }
    None
}

/// Bar-aligned value of one ZigZag "Straight Line EMA" (`slema`) line. The line
/// is the polyline through the zigzag vertices, so its value at a bar is the
/// straight leg interpolated to that bar's time (and the last vertex value is
/// carried forward past the last pivot, i.e. the level currently drawn). Uses
/// the chart-shaped settings the "Straight Line Indicators" `StraightEma<n>` rows
/// use: ZigZag EMA length N, swing 5, min leg 5 (the length-1 line uses swing 17),
/// so the gate reads the SAME line the operator sees. Warm-up (no vertex yet)
/// returns `None`, which the gate treats as fail-closed.
fn slema_line_at(len: i64, candles: &[Candle], offset: usize) -> Option<f64> {
    let n = candles.len();
    if offset >= n {
        return None;
    }
    let target = candles[n - 1 - offset].time;
    let (l, swing, min_leg) = if len == 1 { (1.0, 17.0, 5.0) } else { (len as f64, 5.0, 5.0) };
    let st: algo_core::model::Settings = [("length", l), ("swing", swing), ("minLeg", min_leg)]
        .into_iter()
        .map(|(k, v)| (k.to_string(), json!(v)))
        .collect();
    let out = ind_series("slema", candles, &st);
    let s = out.first()?;
    let mut pts: Vec<(i64, f64)> = s.data.iter().filter(|p| p.value.is_finite()).map(|p| (p.time, p.value)).collect();
    if pts.is_empty() {
        return None;
    }
    pts.sort_by_key(|p| p.0);
    if target <= pts[0].0 {
        return Some(pts[0].1);
    }
    let last = pts[pts.len() - 1];
    if target >= last.0 {
        return Some(last.1);
    }
    for w in pts.windows(2) {
        let (t0, v0) = w[0];
        let (t1, v1) = w[1];
        if target >= t0 && target <= t1 {
            if t1 <= t0 {
                return Some(v1);
            }
            let f = (target - t0) as f64 / (t1 - t0) as f64;
            return Some(v0 + (v1 - v0) * f);
        }
    }
    Some(last.1)
}

// ---------------------------------------------------------------------------
// Canonical Pane-indicator sets for the global Pane filters
//
// The old engine scoped "Pane crossover" / "Pane lines all" to the pane
// indicators referenced by the running strategy's template. A single global
// filter set has no template, so the engine evaluates the canonical pane
// momentum pairs the UI documents ("Multi-Line Momentum Gap" family). A pair
// whose series is not computable yet (warm-up / too little history) is skipped;
// when no pair is computable the filter is treated as satisfied (non-blocking),
// exactly like the old engine's empty template-pane list.
// ---------------------------------------------------------------------------

/// (indicator id, main line index, signal line index) pane pairs.
const PANE_PAIRS: &[(&str, usize, usize)] = &[
    ("macd", 0, 1),
    ("ppo", 0, 1),
    ("smiio", 0, 1),
    ("stochrsi", 0, 1),
    ("aroon", 0, 1),
    ("vortex", 0, 1),
    ("adx", 1, 2),
];

/// Single-line pane indicators walked line-by-line by the "pane lines all"
/// direction filter, on top of every line of `PANE_PAIRS`.
const PANE_SINGLE_LINES: &[&str] = &[
    "ao", "smiio", "dpo", "mfi", "uo", "williamsR", "bbpct", "pvt", "ad", "smf",
    "cmf", "cci", "sqzmom", "rsi", "obv", "fisher", "tsi",
];

fn pane_out(id: &str, candles: &[Candle]) -> Arc<Vec<algo_core::model::SeriesOut>> {
    ind_series(id, candles, &algo_core::model::Settings::default())
}

fn pane_out_p(id: &str, params: &[(&str, f64)], candles: &[Candle]) -> Arc<Vec<algo_core::model::SeriesOut>> {
    let st: algo_core::model::Settings = params.iter().map(|(k, v)| (k.to_string(), json!(v))).collect();
    ind_series(id, candles, &st)
}

fn pane_pair_level(id: &str, ia: usize, ib: usize, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let out = pane_out(id, candles);
    let a = out.get(ia).and_then(|s| series_value(s, offset))?;
    let b = out.get(ib).and_then(|s| series_value(s, offset))?;
    Some(if bull { a > b } else { a < b })
}

/// Multi-Line Momentum Gap generic level-hold (old `pbgBull`/`pbgBear`): the
/// main line sits above the signal, the main line is not falling and the signed
/// gap (main - signal) is not shrinking; exact mirror for bear.
fn pbg_hold(out: &[algo_core::model::SeriesOut], vk: usize, ck: usize, bull: bool, offset: usize) -> Option<bool> {
    let m = series_value(out.get(vk)?, offset)?;
    let s0 = series_value(out.get(ck)?, offset)?;
    let vp = series_value(out.get(vk)?, offset + 1)?;
    let s1 = series_value(out.get(ck)?, offset + 1)?;
    if !(m.is_finite() && s0.is_finite() && vp.is_finite() && s1.is_finite()) {
        return Some(true);
    }
    let gap = m - s0;
    let pgap = vp - s1;
    Some(if bull { gap > 0.0 && m >= vp && gap >= pgap } else { gap < 0.0 && m <= vp && gap <= pgap })
}

/// SMI Ergodic special "pair vs Histogram" mode (old `pbgBull`/`pbgBear` with
/// `pair: v2`, user-confirmed orientation): the bull row fires while SMI and its
/// signal both sit below the histogram, both point downward and the histogram
/// itself is falling; the bear row is the exact opposite.
fn pbg_smiio(out: &[algo_core::model::SeriesOut], bull: bool, offset: usize) -> Option<bool> {
    let v = series_value(out.get(0)?, offset)?;
    let s = series_value(out.get(1)?, offset)?;
    let h = series_value(out.get(2)?, offset)?;
    let vp = series_value(out.get(0)?, offset + 1)?;
    let sp = series_value(out.get(1)?, offset + 1)?;
    let hp = series_value(out.get(2)?, offset + 1)?;
    if !(v.is_finite() && s.is_finite() && h.is_finite() && vp.is_finite() && sp.is_finite() && hp.is_finite()) {
        return Some(true);
    }
    Some(if bull {
        v < h && s < h && v < vp && s < sp && h < hp
    } else {
        v > h && s > h && v > vp && s > sp && h > hp
    })
}

/// Vortex custom gap gate: VI+/- are a competing-direction duo, so the trend
/// signal requires BOTH lines committed (level hold, no fresh cross needed).
fn pbg_vortex(out: &[algo_core::model::SeriesOut], bull: bool, offset: usize) -> Option<bool> {
    let vi = series_value(out.get(0)?, offset)?;
    let vm = series_value(out.get(1)?, offset)?;
    let vip = series_value(out.get(0)?, offset + 1)?;
    let vmp = series_value(out.get(1)?, offset + 1)?;
    if !(vi.is_finite() && vm.is_finite() && vip.is_finite() && vmp.is_finite()) {
        return Some(true);
    }
    Some(if bull { vi > vm && vi > vip && vm < vmp } else { vi < vm && vi < vip && vm > vmp })
}

/// ADX custom gate: the ADX gauge must be trending, +DI/-DI must hold the trend
/// side and the +DI/-DI gap must be widening.
fn pbg_adx(out: &[algo_core::model::SeriesOut], bull: bool, offset: usize) -> Option<bool> {
    let a = series_value(out.get(0)?, offset)?;
    let p = series_value(out.get(1)?, offset)?;
    let m = series_value(out.get(2)?, offset)?;
    let ap = series_value(out.get(0)?, offset + 1)?;
    let pp = series_value(out.get(1)?, offset + 1)?;
    let mp = series_value(out.get(2)?, offset + 1)?;
    if !(a.is_finite() && p.is_finite() && m.is_finite() && ap.is_finite() && pp.is_finite() && mp.is_finite()) {
        return Some(true);
    }
    let gap = (p - m).abs();
    let pgap = (pp - mp).abs();
    Some(if bull {
        a > ap && p > m && p >= pp && m <= mp && gap >= pgap
    } else {
        a < ap && p < m && p <= pp && m >= mp && gap >= pgap
    })
}

/// One output series of an indicator as a plain value vector (NaN for warm-up).
fn indicator_values(id: &str, params: &[(&str, f64)], candles: &[Candle]) -> Vec<f64> {
    pane_out_p(id, params, candles)
        .first()
        .map(|s| s.data.iter().map(|p| p.value).collect())
        .unwrap_or_default()
}

enum SigKind {
    Ema(usize),
    Sma(usize),
}

/// Rolling EMA/SMA over a value vector (used for the single-line pane
/// indicators that the old engine exposed a signal line for: RSI/OBV/Fisher/TSI).
fn rolling_signal(vals: &[f64], kind: &SigKind) -> Vec<f64> {
    let n = vals.len();
    let mut out = vec![f64::NAN; n];
    match kind {
        SigKind::Ema(len) => {
            let len = *len;
            if len == 0 {
                return out;
            }
            let k = 2.0 / (len as f64 + 1.0);
            let mut prev = f64::NAN;
            let mut sum = 0.0;
            let mut cnt = 0usize;
            for i in 0..n {
                let v = vals[i];
                if v.is_nan() {
                    continue;
                }
                if prev.is_nan() {
                    sum += v;
                    cnt += 1;
                    if cnt >= len {
                        prev = sum / len as f64;
                        out[i] = prev;
                    }
                } else {
                    prev = v * k + prev * (1.0 - k);
                    out[i] = prev;
                }
            }
        }
        SigKind::Sma(len) => {
            let len = *len;
            if len == 0 {
                return out;
            }
            let mut q: std::collections::VecDeque<f64> = std::collections::VecDeque::new();
            let mut sum = 0.0;
            for i in 0..n {
                let v = vals[i];
                q.push_back(v);
                if !v.is_nan() {
                    sum += v;
                }
                if q.len() > len {
                    if let Some(old) = q.pop_front() {
                        if !old.is_nan() {
                            sum -= old;
                        }
                    }
                }
                if q.len() == len && q.iter().all(|x| !x.is_nan()) {
                    out[i] = sum / len as f64;
                }
            }
        }
    }
    out
}

/// Level comparison of a single-line pane indicator's main line against a
/// rolling signal (old PB_CROSS_LEVEL gates for RSI/OBV/Fisher/TSI).
fn level_vs_signal(id: &str, params: &[(&str, f64)], kind: SigKind, bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let vals = indicator_values(id, params, candles);
    let n = vals.len();
    if n <= offset {
        return None;
    }
    let sig = rolling_signal(&vals, &kind);
    let v = vals[n - 1 - offset];
    let s = sig[n - 1 - offset];
    if v.is_nan() || s.is_nan() {
        return Some(true);
    }
    Some(if bull { v > s } else { v < s })
}

/// Every pane line agrees with the requested direction. Uncomputable lines are
/// skipped; the result is satisfied only when every computable line agrees.
fn pane_all_dirs(bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let mut computed = false;
    for (id, ia, ib) in PANE_PAIRS {
        let out = pane_out(id, candles);
        for idx in [*ia, *ib] {
            if let Some((a, b)) = out
                .get(idx)
                .and_then(|s| series_value(s, offset))
                .zip(out.get(idx).and_then(|s| series_value(s, offset + 1)))
            {
                computed = true;
                if (a > b) != bull {
                    return Some(false);
                }
            }
        }
    }
    for id in PANE_SINGLE_LINES {
        let out = pane_out(id, candles);
        for s in out.iter() {
            if let Some((a, b)) = series_value(s, offset).zip(series_value(s, offset + 1)) {
                computed = true;
                if (a > b) != bull {
                    return Some(false);
                }
            }
        }
    }
    let _ = computed;
    Some(true)
}

/// Auto Support/Resistance per-bar gap (old `autoSRGapSeries`): replay the
/// ATR-scaled ZigZag and return the signed gap from close to the live support
/// (bull) / resistance (bear) line, then report whether that gap has widened
/// over the recent window (>=4 usable points, last > first).
fn asr_gap_rising(bull: bool, candles: &[Candle], offset: usize) -> Option<bool> {
    let n = candles.len();
    if n < 4 {
        return None;
    }
    let atr_per = 14usize;
    let atr_mult = 2.0_f64;
    let min_pct = 0.15_f64;
    let mut atr: Vec<Option<f64>> = vec![None; n];
    let mut sum = 0.0_f64;
    for i in 0..n {
        let c = &candles[i];
        let tr = if i == 0 {
            c.high - c.low
        } else {
            let pc = candles[i - 1].close;
            (c.high - c.low).max((c.high - pc).abs()).max((c.low - pc).abs())
        };
        if i < atr_per {
            sum += tr;
            if i == atr_per - 1 {
                atr[i] = Some(sum / atr_per as f64);
            }
        } else {
            atr[i] = Some((atr[i - 1].unwrap_or(tr) * (atr_per as f64 - 1.0) + tr) / atr_per as f64);
        }
    }
    let th = |i: usize| -> f64 {
        let a = atr[i].unwrap_or(0.0) * atr_mult;
        let p = candles[i].close.abs() * (min_pct / 100.0);
        a.max(p)
    };
    let mut gap: Vec<Option<f64>> = vec![None; n];
    let mut dir = 1i32;
    let mut ext = candles[0].high;
    let mut last_pivot: Option<f64> = None;
    let mut run_min = candles[0].low;
    let mut run_max = candles[0].high;
    for i in 0..n {
        let c = &candles[i];
        if c.low < run_min {
            run_min = c.low;
        }
        if c.high > run_max {
            run_max = c.high;
        }
        if i > 0 {
            let t = th(i);
            if dir >= 0 {
                if c.high > ext {
                    ext = c.high;
                }
                if c.low <= ext - t {
                    last_pivot = Some(ext);
                    dir = -1;
                    ext = c.low;
                }
            } else {
                if c.low < ext {
                    ext = c.low;
                }
                if c.high >= ext + t {
                    last_pivot = Some(ext);
                    dir = 1;
                    ext = c.high;
                }
            }
        }
        let (sup, res) = if dir >= 0 {
            (last_pivot.unwrap_or(run_min), ext)
        } else {
            (ext, last_pivot.unwrap_or(run_max))
        };
        gap[i] = Some(if bull { c.close - sup } else { res - c.close });
    }
    let i = n - 1 - offset;
    let j0 = i.saturating_sub(6);
    let mut vals: Vec<f64> = Vec::new();
    for g in gap.iter().take(i + 1).skip(j0) {
        if let Some(v) = g {
            if v.is_finite() {
                vals.push(*v);
            }
        }
    }
    if vals.len() < 4 {
        return None;
    }
    Some(vals[vals.len() - 1] > vals[0])
}

/// Evaluate one filter toggle. `None` means "no implementation / research
/// stream" and is treated as non-blocking by the gate.
fn filter_eval(key: &str, candles: &[Candle], offset: usize) -> Option<bool> {
    filter_eval_inner(key, candles, offset, ConsensusCfg::default(), PivotTrendCfg::default(), PivotTrendCfg::default())
}

/// Direction read for one straight-line family filter token, shared by the
/// "Straight Line Indicators" (`Sl*`) and "Visible Straight Line Filter"
/// (`Vsl*`) sections so the two can NEVER drift apart. The read is the line's
/// latest plotted value against the previous one - rising = bullish, falling =
/// bearish - i.e. the line's actual bullish/bearish trend, BUT only when the step
/// clears the straight-line NOISE FLOOR: a move smaller than half the recent
/// average step reads Flat and FAILS CLOSED, so a sub-noise flicker can never
/// fire a false entry. A line that cannot be computed (warming up, or no read on
/// the requested bar) also FAILS CLOSED. Returns `None` only for a token outside
/// the family.
fn sl_family_dir(
    rest: &str,
    bull: bool,
    candles: &[Candle],
    offset: usize,
    sc: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> Option<bool> {
    if rest == "Consensus" {
        return Some(sl_consensus_ok(bull, candles, offset, sc));
    }
    // Support / Resistance Trendline filters read the panel's own geometry
    // settings, so the fitted line the gate sees is the line the operator
    // configured.
    if rest == "Support" {
        return Some(trend_line_dir_noisy("supline", sup, bull, candles, offset).unwrap_or(false));
    }
    if rest == "Resistance" {
        return Some(trend_line_dir_noisy("resline", res, bull, candles, offset).unwrap_or(false));
    }
    // Straight-line EMA (ZigZag EMA) trend per EMA length.
    if let Some(suffix) = rest.strip_prefix("StraightEma") {
        let (len, swing, min_leg) = if suffix.is_empty() {
            (9.0, 5.0, 5.0)
        } else if suffix == "1" {
            (1.0, 17.0, 5.0)
        } else {
            (suffix.parse::<f64>().ok()?, 5.0, 5.0)
        };
        return Some(
            series_dir_noisy(
                "slema",
                &[("length", len), ("swing", swing), ("minLeg", min_leg)],
                0,
                bull,
                candles,
                offset,
            )
            .unwrap_or(false),
        );
    }
    // Supertrend ZigZag trend line (chart-indicator defaults).
    if rest == "StZigZag" {
        return Some(
            series_dir_noisy(
                "stzigzag",
                &[("atrPeriod", 10.0), ("factorFast", 1.0), ("factorSlow", 0.1), ("swing", 5.0), ("minLeg", 5.0)],
                0,
                bull,
                candles,
                offset,
            )
            .unwrap_or(false),
        );
    }
    // Structure Based Supply Demand: read the VISIBLE `supplydemand` overlay
    // (the line the chart draws), the SAME series every other SupplyDemand row
    // (arrow / colour / visible straight-line) now reads. The params are the
    // chart's own defaults (structLen 5 / symLegs 3 / eqTol 25 / projCount 1),
    // so the gate matches the overlay the operator sees instead of a differently
    // tuned private copy.
    if rest == "SupplyDemand" {
        return Some(
            series_dir_noisy(
                "supplydemand",
                &[("structLen", 5.0), ("symLegs", 3.0), ("eqTol", 25.0), ("projCount", 1.0)],
                0,
                bull,
                candles,
                offset,
            )
            .unwrap_or(false),
        );
    }
    // Overall Straight Line Consensus (Price): the overall-trend consensus of
    // every straight-line indicator held as ONE straight price line (fixed
    // settings below).
    if rest == "OverallConsensusPrice" {
        return Some(
            series_dir_noisy(
                "slallconsensuso",
                &[
                    ("minAgree", 1.0),
                    ("confirm", 0.0),
                    ("strength", 0.0),
                    ("trendLen", 34.0),
                    ("minSlopePct", 0.0005),
                ],
                0,
                bull,
                candles,
                offset,
            )
            .unwrap_or(false),
        );
    }
    // Price Action Diversionless (Price): the confirmed real-reversal trend held
    // as ONE straight price line (fixed settings below).
    if rest == "PriceActionDiv" {
        return Some(
            series_dir_noisy(
                "padivo",
                &[
                    ("rsiLen", 7.0),
                    ("bbLen", 17.0),
                    ("bbMult", 1.8),
                    ("emaFast", 9.0),
                    ("emaSlow", 21.0),
                    ("atrPeriod", 10.0),
                    ("factorFast", 1.0),
                    ("factorSlow", 2.0),
                    ("divWin", 14.0),
                    ("confirm", 1.0),
                    ("minLeg", 1.0),
                ],
                0,
                bull,
                candles,
                offset,
            )
            .unwrap_or(false),
        );
    }
    // BB%b Straight Line: FIXED operator settings (BB length 17, std.dev mult
    // 1.2, %B bull threshold 0.45, min leg 5, source close). The row has no
    // settings gear; the gate computes `bbpctsl` with exactly these values.
    if rest == "BbPctSl" {
        return Some(
            series_dir_noisy(
                "bbpctsl",
                &[("length", 17.0), ("mult", 1.2), ("threshold", 0.45), ("minLeg", 5.0)],
                0,
                bull,
                candles,
                offset,
            )
            .unwrap_or(false),
        );
    }
    if let Some((id, idx)) = sl_series(rest) {
        return Some(series_dir_noisy(id, &[], idx, bull, candles, offset).unwrap_or(false));
    }
    None
}

/// Every straight-line line the "Flip Trigger" vote watches: the union of the
/// "Straight Line Indicators" (`Sl*`) and "Visible Straight Line Filter" (`Vsl*`)
/// families - counted ONCE each, since both sections read the same underlying
/// line - plus the OI Trend regime line (`Oit`) and the Trend Core line
/// (`TrendCore`). Kept in one place so the frontend list and the backend vote can
/// never drift apart.
const FLIP_TRIGGER_LINES: &[&str] = &[
    "ElliottWave", "SupplyDemand", "PriceAction", "ZigZag", "ComboMaster",
    "PaneConsensus", "AutoTrendline", "Pitchfork", "TrendProjection", "GannFan",
    "FibFan", "Srema", "StraightEma1", "StraightEma5", "StraightEma9",
    "StraightEma30", "StraightEma50", "StraightEma100", "StZigZag", "BbPctSl",
    "Vl", "Consensus", "Support", "Resistance", "OverallConsensusPrice",
    "PriceActionDiv", "Oit", "TrendCore",
];

/// Direction of one Flip-Trigger line: `Some(true)` = the line is rising
/// (bullish), `Some(false)` = falling (bearish), `None` = flat (sub-noise) or not
/// computable yet (warming up). Unlike `sl_family_dir`, the `None` (flat /
/// un-computable) case is PRESERVED so the Flip Trigger can leave such a line out
/// of BOTH the numerator and the denominator instead of failing it closed.
fn flip_line_dir(
    token: &str,
    bull: bool,
    candles: &[Candle],
    offset: usize,
    sc: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> Option<bool> {
    match token {
        // The consensus is an aggregate of the other lines; it is treated as
        // always computable (its own warm-up already reads non-blocking).
        "Consensus" => Some(sl_consensus_ok(bull, candles, offset, sc)),
        "Support" => trend_line_dir_noisy("supline", sup, bull, candles, offset),
        "Resistance" => trend_line_dir_noisy("resline", res, bull, candles, offset),
        "Oit" => oit_dir(bull, candles, offset),
        "Vl" => line_dir("vl", bull, candles, offset),
        "TrendCore" => series_dir("vlcore", &[], 0, bull, candles, offset),
        _ => {
            if let Some(suffix) = token.strip_prefix("StraightEma") {
                let (len, swing, min_leg) = if suffix.is_empty() {
                    (9.0, 5.0, 5.0)
                } else if suffix == "1" {
                    (1.0, 17.0, 5.0)
                } else {
                    (suffix.parse::<f64>().ok()?, 5.0, 5.0)
                };
                return series_dir_noisy(
                    "slema",
                    &[("length", len), ("swing", swing), ("minLeg", min_leg)],
                    0,
                    bull,
                    candles,
                    offset,
                );
            }
            if token == "StZigZag" {
                return series_dir_noisy(
                    "stzigzag",
                    &[("atrPeriod", 10.0), ("factorFast", 1.0), ("factorSlow", 0.1), ("swing", 5.0), ("minLeg", 5.0)],
                    0,
                    bull,
                    candles,
                    offset,
                );
            }
            if token == "SupplyDemand" {
                return series_dir_noisy(
                    "supplydemand",
                    &[("structLen", 5.0), ("symLegs", 3.0), ("eqTol", 25.0), ("projCount", 1.0)],
                    0,
                    bull,
                    candles,
                    offset,
                );
            }
            if token == "OverallConsensusPrice" {
                return series_dir_noisy(
                    "slallconsensuso",
                    &[("minAgree", 1.0), ("confirm", 0.0), ("strength", 0.0), ("trendLen", 34.0), ("minSlopePct", 0.0005)],
                    0,
                    bull,
                    candles,
                    offset,
                );
            }
            if token == "PriceActionDiv" {
                return series_dir_noisy(
                    "padivo",
                    &[
                        ("rsiLen", 7.0), ("bbLen", 17.0), ("bbMult", 1.8),
                        ("emaFast", 9.0), ("emaSlow", 21.0), ("atrPeriod", 10.0),
                        ("factorFast", 1.0), ("factorSlow", 2.0), ("divWin", 14.0),
                        ("confirm", 1.0), ("minLeg", 1.0),
                    ],
                    0,
                    bull,
                    candles,
                    offset,
                );
            }
            if token == "BbPctSl" {
                return series_dir_noisy(
                    "bbpctsl",
                    &[("length", 17.0), ("mult", 1.2), ("threshold", 0.45), ("minLeg", 5.0)],
                    0,
                    bull,
                    candles,
                    offset,
                );
            }
            if let Some((id, idx)) = sl_series(token) {
                return series_dir_noisy(id, &[], idx, bull, candles, offset);
            }
            None
        }
    }
}

/// Flip Trigger vote for one leg, read exactly like the gate: honors the
/// "Formed candle only" (closed-bar) offset shift, and the premium-chart side
/// resolution, then counts how many of the watched lines currently point the
/// leg's way. Returns `(on_side, total)` where `total` is the number of
/// compute-able lines only (flat / warming-up lines are excluded from both).
fn flip_trigger_counts(
    bull: bool,
    candles: &[Candle],
    offset: usize,
    sc: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> (usize, usize) {
    let mut on_side = 0usize;
    let mut total = 0usize;
    for token in FLIP_TRIGGER_LINES {
        if let Some(dir) = flip_line_dir(token, bull, candles, offset, sc, sup, res) {
            total += 1;
            if dir {
                on_side += 1;
            }
        }
    }
    (on_side, total)
}

/// The Flip Trigger entry rule for one leg: pass when the share of compute-able
/// lines pointing the leg's way reaches the operator's `flip_trigger_pct`. This
/// REPLACES the ordinary indicator-filter gate when `flip_trigger_on` is set, so
/// the strict-AND / AI-Brain / majority layers do not apply.
/// Evaluate every PRIMARY "Entry indicator filter" key for one resolved side.
///
/// Returns `true` when the leg is not primary-gated (switch OFF, or no primary
/// key for this side) OR when every configured primary condition passes. The
/// caller MUST have the indicator cache scope open (both gate paths do).
fn primary_gate_pass(settings: &Settings, bull: bool, candles: &[Candle], offset: usize) -> bool {
    let cons = consensus_cfg(settings);
    let sup = support_trend_cfg(settings);
    let res = resistance_trend_cfg(settings);
    primary_keys_for_side(settings, bull)
        .iter()
        .all(|k| gate_filter_eval(k, candles, offset, cons, sup, res).unwrap_or(false))
}

fn flip_trigger_pass(settings: &Settings, strat: &Strategy, candles: &[Candle], offset: usize) -> bool {
    let offset = if settings.closed_bar_compute { offset + 1 } else { offset };
    let _sc = IndScope::enter();
    let bull = premium_only_for(strat, settings) || strategy_is_bull(strat);
    // The PRIMARY "Entry indicator filter" conditions apply to the flip vote too:
    // a failed primary condition blocks the entry before the vote is counted.
    if !primary_gate_pass(settings, bull, candles, offset) {
        return false;
    }
    let (on_side, total) = flip_trigger_counts(
        bull,
        candles,
        offset,
        consensus_cfg(settings),
        support_trend_cfg(settings),
        resistance_trend_cfg(settings),
    );
    if total == 0 {
        return false;
    }
    let pct = settings.flip_trigger_pct.clamp(0.0, 100.0);
    // Round the required count UP so a fraction (e.g. 50% of 7 = 3.5) demands the
    // higher whole number of lines, and always demand at least one.
    let need = (((pct / 100.0) * total as f64).ceil() as usize).max(1);
    on_side >= need
}

/// Minimum separation (as a fraction of price) between the HMA 20 and HMA 40 that
/// the `MeetCross` filter demands before it reads a side, so the two averages
/// touching in a flat market never counts as a crossed-and-holding signal.
const MEET_CROSS_MIN_FRAC: f64 = 0.0005;

fn filter_eval_inner(
    key: &str,
    candles: &[Candle],
    offset: usize,
    sc: ConsensusCfg,
    sup: PivotTrendCfg,
    res: PivotTrendCfg,
) -> Option<bool> {
    let (bull, base) = if let Some(b) = key.strip_prefix("Bull") {
        (true, b)
    } else if let Some(b) = key.strip_prefix("Bear") {
        (false, b)
    } else {
        (true, key)
    };
    // "Candle closed above / below <indicator>" persistent-level family. Handled
    // first so the generic `Sl`/`Meet` prefix branches can never shadow it.
    if let Some(rest) = base.strip_prefix("ClosedAbove") {
        return closed_vs_indicator(rest, true, candles);
    }
    if let Some(rest) = base.strip_prefix("ClosedBelow") {
        return closed_vs_indicator(rest, false, candles);
    }
    match base {
        "IncUp" => Some(rising_close(candles, offset)),
        "IncDown" => Some(falling_close(candles, offset)),
        "IncUpAll" => Some(ema_val(9, candles, offset)? > ema_val(21, candles, offset)? && ema_val(21, candles, offset)? > ema_val(35, candles, offset)?),
        "IncDownAll" => Some(ema_val(9, candles, offset)? < ema_val(21, candles, offset)? && ema_val(21, candles, offset)? < ema_val(35, candles, offset)?),
        "GapUp" => gap_dir(candles, offset, true),
        "GapDown" => gap_dir(candles, offset, false),
        "PaneCrossUp" | "PaneCrossDown" => {
            // Every canonical pane pair's main line crossing its signal line,
            // read on the configured forming/closed bar and confirmation window.
            let up = base == "PaneCrossUp";
            let mut computed = false;
            for (id, ia, ib) in PANE_PAIRS {
                if let Some(ok) = cross_from_sign(
                    offset,
                    |o| {
                        let out = pane_out(id, candles);
                        let a = out.get(*ia).and_then(|s| series_value(s, o))?;
                        let b = out.get(*ib).and_then(|s| series_value(s, o))?;
                        Some(a > b)
                    },
                    up,
                ) {
                    computed = true;
                    if !ok {
                        return Some(false);
                    }
                }
            }
            // No pane pair could be computed: uncomputable, not a pass.
            if computed { Some(true) } else { None }
        }
        "PaneIncUpAll" => pane_all_dirs(true, candles, offset),
        "PaneIncDownAll" => pane_all_dirs(false, candles, offset),
        "MeetPaneCross" => {
            // Level form of the pane crossover: main line still above (bull) /
            // below (bear) the signal line for every canonical pane pair.
            let mut computed = false;
            for (id, ia, ib) in PANE_PAIRS {
                if let Some(ok) = pane_pair_level(id, *ia, *ib, bull, candles, offset) {
                    computed = true;
                    if !ok {
                        return Some(false);
                    }
                }
            }
            if computed { Some(true) } else { None }
        }
        // "Crossed-above indicator pair still above (level)": the primary overlay
        // line (HMA 20) above its doubled-settings twin (HMA 40). A dead-band of a
        // small fraction of price is required, so a one-tick overlap of the two
        // averages in a flat market is NOT read as a bullish (or bearish) hold.
        "MeetCross" => {
            let fast = ind_at("hma", candles, &[("length", 20.0)], offset)?;
            let slow = ind_at("hma", candles, &[("length", 40.0)], offset)?;
            let floor = fast.abs().max(slow.abs()) * MEET_CROSS_MIN_FRAC;
            let sep = fast - slow;
            Some(if bull { sep > floor } else { sep < -floor })
        }
        "Asr" => asr_gap_rising(bull, candles, offset),
        // OI Trend is driven by the live option-chain OI series (the old engine's
        // `oitrend` overlay), which the candle-only filter gate has no access to.
        // It is wired as a non-blocking scope row here instead of a fabricated
        // candle proxy, so enabling it can never freeze live trading.
        "Oit" => oit_dir(bull, candles, offset),
        // Research-stream scope selectors (old `hasStreamFlags`): they choose
        // which research group the engine runs on a side, they are not candle
        // entry gates. `filter_gate` excludes them from the gate set and the
        // engine applies `stream_allows()` to scope the run set by strategy
        // group, so evaluating them here is inert (kept Some for the UI's
        // "every filter computes" contract).
        "Candle" | "Elliott" | "Indicator" | "Pane" | "Symmetry" | "Structure" | "Atr" => {
            Some(true)
        }
        "CrossUp" => cross_from_sign(offset, |o| Some(ema1(candles, o)? > ema_val(9, candles, o)?), true),
        "CrossDown" => cross_from_sign(offset, |o| Some(ema1(candles, o)? > ema_val(9, candles, o)?), false),
        "GtUp" | "GtDown" => close_at(candles, offset).zip(ema_val(9, candles, offset)).map(|(c, e)| c > e),
        "LtUp" | "LtDown" => close_at(candles, offset).zip(ema_val(9, candles, offset)).map(|(c, e)| c < e),
        "BbwInc" => line_dir("bbw", true, candles, offset),
        "Smf" => {
            let a = ind_n("smf", candles, &[("length", 14.0), ("signalLen", 9.0), ("volLen", 20.0)], 0, offset)?;
            let b = ind_n("smf", candles, &[("length", 14.0), ("signalLen", 9.0), ("volLen", 20.0)], 1, offset)?;
            Some(if bull { a > b } else { a < b })
        }
        "VwapCloseCrossAbove" => cross_from_sign(offset, |o| Some(ema1(candles, o)? > ind_at("vwap", candles, &[], o)?), true),
        "VwapCloseCrossBelow" => cross_from_sign(offset, |o| Some(ema1(candles, o)? > ind_at("vwap", candles, &[], o)?), false),
        "MeetCloseVwap" => close_at(candles, offset).zip(ind_at("vwap", candles, &[], offset)).map(|(c, v)| if bull { c > v } else { c < v }),
        "PbrAo" => line_dir("ao", bull, candles, offset),
        "PbrSmiio" => line_dir("smiio", bull, candles, offset),
        "PbrDpo" => line_dir("dpo", bull, candles, offset),
        "PbrMfi" => line_dir("mfi", bull, candles, offset),
        "PbrUo" => line_dir("uo", bull, candles, offset),
        "PbrWilliamsR" => line_dir("williamsR", bull, candles, offset),
        "PbrBbpct" => line_dir("bbpct", bull, candles, offset),
        "PbrPvt" => line_dir("pvt", bull, candles, offset),
        "PbrAd" => line_dir("ad", bull, candles, offset),
        "PbrSmf" => line_dir("smf", bull, candles, offset),
        "PbrCmf" => line_dir("cmf", bull, candles, offset),
        "PbrCci" => line_dir("cci", bull, candles, offset),
        "PbrSqzmom" => line_dir("sqzmom", bull, candles, offset),
        // Force Index is a non-blocking confirmer in the old engine (never
        // gates a trade on its own).
        "PbrElderforce" => Some(true),
        "PbrBbwUp" => line_dir("bbw", true, candles, offset),
        "PbrAtrUp" => line_dir("atr", true, candles, offset),
        "PbrVoloscUp" => line_dir("volosc", true, candles, offset),
        "St1CloseCrossAbove" => {
            cross_from_sign(offset, |o| Some(ema1(candles, o)? > st_val(1.0, candles, o)?), true)
        }
        "St1CloseCrossBelow" => {
            cross_from_sign(offset, |o| Some(ema1(candles, o)? > st_val(1.0, candles, o)?), false)
        }
        "MeetCloseSt" => close_at(candles, offset).zip(st_val(1.0, candles, offset)).map(|(c, s)| if bull { c > s } else { c < s }),
        "BbCrossAbove" | "BbCrossBelow" => {
            let up = base == "BbCrossAbove";
            let crossed = cross_from_sign(offset, |o| Some(ema1(candles, o)? > bb_mid(candles, o)?), up)?;
            if !crossed {
                return Some(false);
            }
            // Old rule: the band midpoint must also slope the cross's way.
            let b = offset + cross_base();
            let m = bb_mid(candles, b)?;
            let mp = bb_mid(candles, b + 1)?;
            Some(if up { m > mp } else { m < mp })
        }
        "PcCrossAbove" | "PcCrossBelow" => {
            let up = base == "PcCrossAbove";
            let crossed = cross_from_sign(offset, |o| Some(ema1(candles, o)? > pc_mid(candles, o)?), up)?;
            if !crossed {
                return Some(false);
            }
            let b = offset + cross_base();
            let m = pc_mid(candles, b)?;
            let mp = pc_mid(candles, b + 1)?;
            Some(if up { m > mp } else { m < mp })
        }
        "MeetCloseBb" => close_at(candles, offset).zip(bb_mid(candles, offset)).map(|(c, m)| if bull { c > m } else { c < m }),
        "MeetClosePc" => close_at(candles, offset).zip(pc_mid(candles, offset)).map(|(c, m)| if bull { c > m } else { c < m }),
        _ => {
            // Fresh up/down arrow on a straight-line / overlay indicator.
            if let Some(rest) = base.strip_prefix("Arrow") {
                return arrow_gate(rest, bull, candles, offset, sc);
            }
            if let Some(rest) = base.strip_prefix("St10_") {
                if let Some((lo, hi)) = parse_pair(rest) {
                    let lo = lo as f64;
                    let hi = hi as f64;
                    return cross_from_sign(offset, |o| Some(st_val(lo, candles, o)? > st_val(hi, candles, o)?), bull);
                }
            }
            if let Some(rest) = base.strip_prefix("MeetSt10_") {
                if let Some((lo, hi)) = parse_pair(rest) {
                    let a = st_val(lo as f64, candles, offset)?;
                    let b = st_val(hi as f64, candles, offset)?;
                    return Some(if bull { a > b } else { a < b });
                }
            }
            // ZigZag "Straight Line EMA" crossover (latched level): fast above
            // (bull) / below (bear) slow, with the same forming/closed read bar
            // and optional N-bar hold window as the event crossovers above.
            if let Some(rest) = base.strip_prefix("MeetSlema") {
                if let Some((a, b)) = parse_pair(rest) {
                    return level_from_sign(offset, |o| Some(slema_line_at(a, candles, o)? > slema_line_at(b, candles, o)?), bull);
                }
            }
            // Overlay Indicator Behaviour (direction mirror) and Overlay Meet.
            if let Some(rest) = base.strip_prefix("Obr") {
                if let Some((id, idx)) = overlay_series(rest) {
                    return series_dir(id, &[], idx, bull, candles, offset);
                }
                return None;
            }
            if let Some(rest) = base.strip_prefix("MeetOvl") {
                if let Some((id, idx)) = overlay_series(rest) {
                    return close_vs_series(id, &[], idx, bull, candles, offset);
                }
                return None;
            }
            // Straight Line Indicator Color Detection: read the COLOUR the chart
            // draws on the line's last CLOSED candle (green = bullish, red =
            // bearish). The colour id is the VISIBLE overlay the operator sees -
            // not the hidden "…state" id the plain Sl* filters read, which carries
            // no green/red colour. `None` (un-drawn / differently-coloured line) is
            // non-blocking, matching the Sl* gates.
            if let Some(rest) = base.strip_prefix("SlColor") {
                return match sl_color_series(rest) {
                    Some((id, idx)) => Some(color_line_dir(id, idx, bull, candles).unwrap_or(false)),
                    None => None,
                };
            }
            // Visible Straight Line Filter: the operator asked for the old
            // visible-line "rising / falling" slope read to be REMOVED and the
            // rows to report a bullish/bearish TREND exactly like the "Straight
            // Line Indicators" section. It now delegates to the SAME
            // `sl_family_dir` read (line's latest plotted value vs the previous
            // one), so a rising line is bullish and a falling line is bearish -
            // the two sections can never disagree. Only the rows unique to this
            // section (Overall Straight Line Consensus Price / Price Action
            // Diversionless Price) get their own trend overlay.
            if let Some(rest) = base.strip_prefix("Vsl") {
                if rest == "Vl" {
                    return line_dir("vl", bull, candles, offset);
                }
                // Delegates to the SAME `sl_family_dir` as the "Straight Line
                // Indicators" section so the two can never disagree. This now
                // also covers Overall Straight Line Consensus Price / Price
                // Action Diversionless Price, which use the fixed filter settings.
                return sl_family_dir(rest, bull, candles, offset, sc, sup, res);
            }
            // ZigZag "Straight Line EMA" crossover EVENT: fires on the bar the
            // fast line crosses the slow line and is false on the next bar unless
            // it crosses again. Read on the same forming/closed bar (and optional
            // N-bar confirmation window) as every other crossover filter.
            if let Some(rest) = base.strip_prefix("Slema") {
                if let Some((a, b)) = parse_pair(rest) {
                    return cross_from_sign(offset, |o| Some(slema_line_at(a, candles, o)? > slema_line_at(b, candles, o)?), bull);
                }
            }
            // Straight Line Indicators (single directional overlay lines):
            // the line's bullish/bearish trend, shared with the Visible section.
            if let Some(rest) = base.strip_prefix("Sl") {
                return sl_family_dir(rest, bull, candles, offset, sc, sup, res);
            }
            if base == "Vl" {
                return line_dir("vl", bull, candles, offset);
            }
            // Multi-Line Momentum Gap (main vs signal level).
            if let Some(rest) = base.strip_prefix("Pbg") {
                return match rest {
                    "Macd" => series_pair("macd", &[], 0, 1, bull, candles, offset),
                    "Ppo" => series_pair("ppo", &[], 0, 1, bull, candles, offset),
                    "Stochrsi" => series_pair("stochrsi", &[], 0, 1, bull, candles, offset),
                    "Tsi" => level_vs_signal("tsi", &[], SigKind::Ema(13), bull, candles, offset),
                    "Rsi" => level_vs_signal("rsi", &[], SigKind::Ema(9), bull, candles, offset),
                    "Obv" => level_vs_signal("obv", &[], SigKind::Sma(30), bull, candles, offset),
                    "Fisher" => level_vs_signal("fisher", &[], SigKind::Ema(3), bull, candles, offset),
                    "Smiio" => pbg_smiio(&pane_out("smiio", candles), bull, offset),
                    "Smf" => pbg_hold(&pane_out("smf", candles), 0, 1, bull, offset),
                    "Aroon" => pbg_hold(&pane_out_p("aroon", &[("length", 25.0)], candles), 0, 1, bull, offset),
                    "Vortex" => pbg_vortex(&pane_out("vortex", candles), bull, offset),
                    "Adx" => pbg_adx(&pane_out("adx", candles), bull, offset),
                    _ => None,
                };
            }
            ema_family(base, bull, candles, offset)
        }
    }
}

fn strategy_is_bull(strat: &Strategy) -> bool {
    let c = strat.category.to_uppercase();
    if c == "BULLISH" {
        true
    } else if c == "BEARISH" {
        false
    } else {
        strat.side.eq_ignore_ascii_case("BUY")
    }
}

/// The CE/PE side Target Lab's cached plan wants for `underlying`, or `None`
/// when strict confirmation is off, the operator is using Manual Strike Select,
/// the underlying is outside the Target Lab universe, or no fresh plan exists.
///
/// Strict mode is authoritative for the LEG. A cold / missing plan falls back to
/// the normal scanner side so an unconnected Target Lab never blocks Paper Trade
/// 2/3; a fresh plan owns the leg even when its confidence is low (confidence
/// still gates auto-cut/exit, not entry side).
fn target_plan_side_for(settings: &Settings, underlying: &str) -> Option<bool> {
    if !settings.target_confirm_on || settings.manual_strikes_enabled {
        return None;
    }
    if !crate::target::covers_underlying(underlying) {
        return None;
    }
    let plan = crate::target::plan_for_underlying(underlying)?;
    target_plan_side(&plan)
}

/// Map a cached Target Lab plan's `direction` (+1 bullish / -1 bearish) to the
/// option leg it owns (`true` = CE, `false` = PE). Pure so it is unit-testable.
fn target_plan_side(plan: &Value) -> Option<bool> {
    match plan.get("direction").and_then(|v| v.as_i64()) {
        Some(d) if d > 0 => Some(true),
        Some(d) if d < 0 => Some(false),
        _ => None,
    }
}

/// Spot forming-candle colour rule for the `spot_candle_gate`: a bullish leg
/// (Top Gainer) requires a GREEN candle (`close > open`), a bearish leg (Top
/// Loser) a RED one (`close < open`). A doji (`close == open`) is neither, so it
/// fails both directions and the entry is held until a coloured candle forms.
fn spot_candle_color_ok(bull: bool, open: f64, close: f64) -> bool {
    if bull {
        close > open
    } else {
        close < open
    }
}

fn filter_is_bull(k: &str) -> bool {
    if k.starts_with("Bull") {
        true
    } else if k.starts_with("Bear") {
        false
    } else {
        k.to_uppercase().contains("UP")
    }
}
fn filter_is_bear(k: &str) -> bool {
    if k.starts_with("Bear") {
        true
    } else if k.starts_with("Bull") {
        false
    } else {
        k.to_uppercase().contains("DOWN")
    }
}

/// "Arrow Detection" toggle (`BullArrow*` / `BearArrow*`). These are collapsed
/// into one OR-ed trigger per side inside the gate, so a single fresh arrow can
/// combine with the ordinary filters instead of every arrow needing to align.
fn is_arrow_flag(k: &str) -> bool {
    k.strip_prefix("Bull")
        .or_else(|| k.strip_prefix("Bear"))
        .map(|b| b.starts_with("Arrow"))
        .unwrap_or(false)
}

/// Research-stream scoping flags (old AST `STREAM_FLAG_GROUPS`). These are not
/// entry gates - they select which research group the engine runs on a side -
/// so they must be excluded from the indicator-filter gate.
fn stream_flag_group(k: &str) -> Option<&'static str> {
    match k {
        k if k == "BullCandle" || k == "BearCandle" => Some("candlestick"),
        k if k == "BullElliott" || k == "BearElliott" => Some("elliott"),
        k if k == "BullIndicator" || k == "BearIndicator" => Some("indicator"),
        k if k == "BullPane" || k == "BearPane" => Some("pane"),
        k if k == "BullSymmetry" || k == "BearSymmetry" => Some("symmetry"),
        k if k == "BullStructure" || k == "BearStructure" => Some("structure"),
        k if k == "BullAtr" || k == "BearAtr" => Some("atr"),
        _ => None,
    }
}

fn is_stream_flag(k: &str) -> bool {
    stream_flag_group(k).is_some()
}

/// Facts behind a `filter_gate` decision, surfaced in the (throttled) gate-fail
/// diagnostics. Cheap to build (no allocation) so the hot path can ignore it.
#[derive(Clone, Copy, Default)]
struct GateFacts {
    pass: usize,
    total: usize,
    strict: bool,
    brain: bool,
    /// PRIMARY ("Entry indicator filter") conditions evaluated in this pass.
    primary_total: usize,
    primary_pass: usize,
    /// True when at least one PRIMARY condition failed, so the entry was blocked
    /// by the primary gate before the secondary filters were considered.
    primary_blocked: bool,
}

/// The PRIMARY entry-indicator keys that gate one leg side.
///
/// The operator adds keys through the "Entry indicator filter" dropdown; the side
/// comes from the key prefix (`Bull*` bullish, `Bear*` bearish), so a single list
/// serves both sides. `bull_side` is the SAME resolved side the ordinary filters
/// use (premium-only mode routes both legs through the bullish set), so a primary
/// condition can never gate a leg the ordinary filters would not gate.
fn primary_keys_for_side(settings: &Settings, bull_side: bool) -> Vec<&String> {
    if !settings.entry_primary_on {
        return Vec::new();
    }
    settings
        .entry_primary_filters
        .iter()
        .filter(|k| !k.trim().is_empty() && !is_stream_flag(k))
        .filter(|k| if bull_side { filter_is_bull(k) } else { filter_is_bear(k) })
        .collect()
}


/// Indicator-filter gate for one side. Every enabled entry-gate mechanism is
/// combined with a strict AND, so they can all run together and none silently
/// disables another:
///   * "All together (strict AND)" -> every enabled filter on the strategy's
///     side must pass. This is gated ONLY by the checkbox; the Indicator-filters
///     run mode does NOT by itself force strict AND.
///   * AI Brain AUTO (score) -> the weighted own-side confluence must also reach
///     the threshold.
/// Without strict AND the gate falls back to a majority of the enabled filters
/// (subject to Brain when it is enabled).
pub(crate) fn filter_gate(settings: &Settings, strat: &Strategy, candles: &[Candle], offset: usize) -> bool {
    filter_gate_facts(settings, strat, candles, offset).0
}

fn filter_gate_facts(settings: &Settings, strat: &Strategy, candles: &[Candle], offset: usize) -> (bool, GateFacts) {
    // "Closed Bar Compute": when ON, every indicator filter in this pass reads
    // the last CLOSED candle (`offset + 1`) instead of the live forming bar, so
    // an intrabar filter value that repaints can never fire (then drop) an
    // entry. A filter that cannot be read that far back fails closed (blocks).
    let offset = if settings.closed_bar_compute { offset + 1 } else { offset };
    // "Slope from N bars" (checkbox + number above the Indicator filters list): for
    // the whole pass every straight-line filter reads its slope over the last N
    // closed bars instead of the 5-point noise-floor window. Guarded so it is
    // restored on return.
    let _slope_bars = FilterSlopeBarsGuard::enter(settings.ind_filter_slope_on, settings.ind_filter_slope_bars);
    // Crossover read mode ("on forming bar" / "on closed bar" + confirmation
    // window). Applied to every crossover filter in this pass; the offset above
    // already carries the closed shift when "Formed candle only" is ON.
    let _cross_cfg = FilterCrossGuard::enter(settings, settings.closed_bar_compute);
    // Ultrafast path: a single memo scope spans the whole pass, so running the
    // 100+ side filters derives each shared indicator (EMA 9/21/35/..., BB, ST,
    // pane lines) once instead of once per filter. This is the hot path of the
    // engine's entry decision.
    let _sc = IndScope::enter();
    // "Premium chart only (run + trade)": every leg (Top Gainer CE and Top Loser
    // PE alike) is gated by the BULLISH indicator filter set. A premium only rises
    // while its own leg is in favour, so the bullish filters are the correct gate
    // on both sides; the bearish filters have no function in this mode. This is
    // decided PER CATEGORY, so Paper Trade 2 can run its Indices / Commodities on
    // the premium chart (bullish-only) while another category stays on spot. The
    // ordinary indicator-filter options (All together strict AND / AI Brain Auto
    // score / majority / Require condition / Flip Trigger) apply exactly as on the
    // spot chart - premium mode only swaps the filter set to the bullish side; it
    // has no separate trigger or override.
    let bull = premium_only_for(strat, settings) || strategy_is_bull(strat);
    let cons = consensus_cfg(settings);
    let sup = support_trend_cfg(settings);
    let res = resistance_trend_cfg(settings);
    // PRIMARY "Entry indicator filter" conditions. These are evaluated FIRST and
    // independently of the strict / brain / majority rules: every primary key for
    // this side must be met before the ordinary (secondary) filters are even
    // looked at. Adding a primary key does NOT tick it in the secondary list, and
    // a key present in both lists is counted only as a primary condition here, so
    // it can never be double-counted.
    let primary_keys = primary_keys_for_side(settings, bull);
    let primary_total = primary_keys.len();
    let mut primary_pass = 0usize;
    for k in &primary_keys {
        if gate_filter_eval(k, candles, offset, cons, sup, res).unwrap_or(false) {
            primary_pass += 1;
        }
    }
    // Every primary condition configured for THIS side must be met. A side with
    // no primary key is simply not primary-gated (see the struct doc), so it can
    // never be blocked by another side's primaries.
    let primary_blocked = primary_total > 0 && primary_pass != primary_total;
    let side_keys: Vec<&String> = settings
        .filters
        .iter()
        .filter(|(k, v)| {
            **v && !is_stream_flag(k)
                && (if bull { filter_is_bull(k) } else { filter_is_bear(k) })
        })
        .map(|(k, _)| k)
        .filter(|k| !primary_keys.iter().any(|p| *p == *k))
        .collect();
    // Arrow Detection filters are a trigger group, not independent confirmations:
    // several arrows would almost never print on the same tick, so requiring them
    // all (strict AND) would make an entry impossible. Collapse the enabled arrow
    // filters for this side into ONE OR-ed condition ("any fresh arrow fires"),
    // then combine that single condition with the ordinary filters below.
    let arrow_keys: Vec<&String> = side_keys.iter().copied().filter(|k| is_arrow_flag(k)).collect();
    let norm_keys: Vec<&String> = side_keys.iter().copied().filter(|k| !is_arrow_flag(k)).collect();
    let arrow_pass = if arrow_keys.is_empty() {
        None
    } else {
        // Fail-closed: an arrow that cannot be computed yet does not count as a
        // trigger (previously `unwrap_or(true)` let an uncomputed arrow fire).
        Some(arrow_keys.iter().any(|k| filter_eval_inner(k, candles, offset, cons, sup, res).unwrap_or(false)))
    };
    let mut f = GateFacts {
        total: norm_keys.len() + usize::from(arrow_pass.is_some()),
        primary_total,
        primary_pass,
        primary_blocked,
        ..Default::default()
    };
    // A failed PRIMARY condition blocks the entry outright - the secondary
    // filters can never override it (that is what makes it PRIMARY).
    if primary_blocked {
        return (false, f);
    }
    for k in &norm_keys {
        let mut ok = gate_filter_eval(k, candles, offset, cons, sup, res).unwrap_or(false);
        if !ok && cross_fill_grace() && is_cross_filter_key(k) {
            ok = gate_filter_eval(k, candles, offset + 1, cons, sup, res).unwrap_or(false);
        }
        if ok {
            f.pass += 1;
        }
    }
    if arrow_pass == Some(true) {
        f.pass += 1;
    }
    // "All together (strict AND)" requires every enabled filter on the
    // strategy's side to pass.
    f.strict = settings.all_in_one;
    if f.strict && f.pass != f.total {
        return (false, f);
    }
    // AI Brain AUTO layers on top of (never instead of) the strict/majority
    // result: the weighted confluence must clear the threshold.
    f.brain = settings.brain_mode.eq_ignore_ascii_case("auto");
    if f.brain {
        if f.total > 0 && (f.pass as f64 / f.total as f64 * 100.0) < settings.brain_threshold as f64 {
            return (false, f);
        }
        return (true, f);
    }
    if f.strict {
        return (true, f);
    }
    if f.total == 0 {
        // A PRIMARY condition alone is a complete entry rule: the operator asked
        // for exactly that condition and selected no extra secondary confirmation
        // (the primary keys already passed above, otherwise we returned early).
        if primary_total > 0 {
            return (true, f);
        }
        // No same-side filter is ticked, so there is no entry rule at all. When
        // "Require condition" is ON the leg must not fire until a condition is
        // actually met - an empty rule counts as NOT met - for every tab,
        // including the stripped Paper Trade 3 engine. A synthetic scanner leg
        // (Top Movers / pick) is likewise blocked: it carries no entry conditions
        // of its own, so with no same-side filter there is nothing to satisfy and
        // it would otherwise enter on every scan (the naked Top-Movers churn). A
        // normal strategy keeps the old behaviour when Require condition is OFF:
        // non-blocking only when the operator has enabled no filters at all; if
        // filters are configured on the opposite side only, there is no same-side
        // confirmation, so the entry is blocked.
        if settings.require_condition || strat.synthetic {
            return (false, f);
        }
        let any_opposite = settings.filters.iter().any(|(k, v)| {
            *v && !is_stream_flag(k)
                && (if bull { filter_is_bear(k) } else { filter_is_bull(k) })
        });
        return (!any_opposite, f);
    }
    // Not strict AND: a majority of the enabled filters must still agree.
    (f.pass * 2 > f.total, f)
}

/// One-line breakdown of a `filter_gate` decision for the gate-fail log, so the
/// operator can see exactly which mechanism (strict AND / brain threshold /
/// majority) allowed or blocked the entry.
fn filter_gate_explain(settings: &Settings, strat: &Strategy, candles: &[Candle], offset: usize) -> String {
    let (ok, f) = filter_gate_facts(settings, strat, candles, offset);
    let score = if f.total > 0 { f.pass as f64 / f.total as f64 * 100.0 } else { 100.0 };
    format!(
        "ok={ok} primary={}/{}{} pass={}/{} score={:.0}% strict={} brain={} thr={}",
        f.primary_pass,
        f.primary_total,
        if f.primary_blocked { " (BLOCKED by primary)" } else { "" },
        f.pass,
        f.total,
        score,
        f.strict,
        f.brain,
        settings.brain_threshold
    )
}

// ---------------------------------------------------------------------------
// "Strategy should be run in" / "Trade should be executed in" routing
// ---------------------------------------------------------------------------

#[derive(PartialEq, Eq, Clone, Copy, Debug)]
enum StratCat {
    Index,
    Fno,
    Comm,
}

fn category_for(seg: &str, inst: &str) -> StratCat {
    let seg = seg.to_uppercase();
    let inst = inst.to_uppercase();
    if inst == "INDEX" || inst == "OPTIDX" || seg == "IDX_I" {
        StratCat::Index
    } else if seg.contains("COMM") || seg.contains("NCD") || inst == "FUTCOM" || inst == "OPTFUT" {
        StratCat::Comm
    } else {
        StratCat::Fno
    }
}

fn strat_category(strat: &Strategy) -> StratCat {
    category_for(&strat.exchange_segment, &strat.instrument)
}

/// True when the strategy already points at a resolved option contract
/// (`OPTIDX` / `OPTSTK` / `OPTFUT`, or any `*_FNO` exchange segment).
fn is_option_leg(s: &Strategy) -> bool {
    let inst = s.instrument.to_uppercase();
    inst.starts_with("OPT") || s.exchange_segment.to_uppercase().ends_with("_FNO")
}

/// True when the strategy already names a concrete option contract (a resolved
/// fill leg), so its premium chart can be read directly instead of resolving a
/// fresh strike from the underlying.
fn is_concrete_option_contract(s: &Strategy) -> bool {
    is_option_leg(s) && option_strike_type(&s.trading_symbol).is_some()
}

/// Whether the "Premium chart only (run + trade)" engine mode is active.
///
/// It is ON when the operator ticks the engine switch, OR when the
/// "Strategy should be run in:" F&O stocks dropdown is pinned to the
/// option-premium chart. In this mode every leg runs AND trades on its
/// selected-strike option-premium chart (Top Gainer on the CE call leg, Top Loser
/// on the PE put leg) and only the BULLISH indicator filters gate entries -
/// bearish indicator filters have no function.
fn premium_only_active(s: &Settings) -> bool {
    s.premium_only || s.run_fno.eq_ignore_ascii_case("premium")
}

/// Whether premium-chart-only gating applies to a strategy category.
///
/// The engine-wide "Premium chart only (run + trade)" switch turns it on for
/// every category. Otherwise the category's own "Strategy should be run in:"
/// routing decides: pinning Indices / F&O stocks / Commodities to the
/// option-premium chart turns premium-only gating on for THAT category alone.
/// In premium-only gating every leg (CE call or PE put) is gated by the BULLISH
/// indicator filters only - bearish filters have no function. When the category
/// is on the spot chart, the normal behaviour applies (bullish filters gate CE,
/// bearish filters gate PE).
fn premium_only_for_cat(cat: StratCat, s: &Settings) -> bool {
    // The equity-only book has no option premium chart at all - everything runs
    // and trades on the cash spot chart.
    if s.equity_only {
        return false;
    }
    if s.premium_only {
        return true;
    }
    match cat {
        StratCat::Index => s.run_index.eq_ignore_ascii_case("premium"),
        StratCat::Fno => s.run_fno.eq_ignore_ascii_case("premium"),
        StratCat::Comm => s.run_comm.eq_ignore_ascii_case("premium"),
    }
}

/// Per-strategy form of [`premium_only_for_cat`] (uses the strategy's category).
fn premium_only_for(strat: &Strategy, s: &Settings) -> bool {
    premium_only_for_cat(strat_category(strat), s)
}

/// Confirmation-indicator set the "Trend check before entry" reads for a
/// category. It reuses the operator's own trend-following selection for that
/// category (so the entry check agrees with the section the operator configured)
/// and falls back to the built-in EMA/Supertrend pair when none is set - the
/// check must always have at least one measurable confirmation.
fn entry_trend_conf_inds(s: &Settings, cat: StratCat) -> Vec<String> {
    let own: &Vec<String> = match cat {
        StratCat::Index => &s.index_trend_conf_inds,
        StratCat::Comm => &s.comm_trend_conf_inds,
        StratCat::Fno => &s.nifty_trend_conf_inds,
    };
    if !own.is_empty() {
        return own.clone();
    }
    ENTRY_TREND_DEFAULT_CONF.iter().map(|x| x.to_string()).collect()
}

/// Built-in fallback confirmation set for the "Trend check before entry" gate:
/// two independent held-side reads (fast/slow EMA + the classic 9/21 EMA pair).
/// Same ids the Auto Trading preset uses, so the read is one the engine already
/// understands.
const ENTRY_TREND_DEFAULT_CONF: &[&str] = &["BullMeetEma1_9", "BullMeetEma9_21"];

/// Verdict of the "Trend check before entry" composite read.
#[derive(Debug)]
struct EntryTrendRead {
    /// `true` when a directional trend was resolved (not sideways / not neutral).
    ok: bool,
    /// +1 bullish, -1 bearish, 0 unresolved.
    dir: i64,
    /// Human-readable explanation shown in the entry-blocker log.
    reason: String,
}

/// Composite current-trend read on the underlying candles for the pre-entry
/// trend gate. Three independent votes are combined with the range-regime read:
///   * the confirmation-indicator net direction,
///   * the EMA20 slope over the last 10 bars,
///   * price vs EMA20.
/// The regime read (ADX / choppiness / EMA slope / range compression) vetoes a
/// range-bound tape outright, so a flat market can never pass in either
/// direction. A net of zero (a tie) is also treated as "no direction". Fails
/// closed with `ok = false` when the series cannot be measured - an unreadable
/// trend must never silently allow an opposite-side entry.
fn entry_trend_read(candles: &[Candle], conf: &[String], s: &Settings) -> EntryTrendRead {
    if candles.len() < 35 {
        return EntryTrendRead { ok: false, dir: 0, reason: "not enough candles".into() };
    }
    let Some(regime) = sideways_read(candles) else {
        return EntryTrendRead { ok: false, dir: 0, reason: "regime unreadable".into() };
    };
    if regime.sideways {
        return EntryTrendRead { ok: false, dir: 0, reason: format!("sideways - {}", regime.reason()) };
    }
    let (_, _, net, _) = nifty_indicator_read(candles, conf, 5, s.nifty_trend_color, s);
    let vote_conf = net.signum();
    let vote_slope = ema_slope_vote(candles);
    let vote_price = price_vs_ema_vote(candles);
    let sum = vote_conf + vote_slope + vote_price;
    let dir = sum.signum();
    if dir == 0 {
        return EntryTrendRead {
            ok: false,
            dir: 0,
            reason: format!(
                "trend neutral (conf {vote_conf:+}, slope {vote_slope:+}, price {vote_price:+})"
            ),
        };
    }
    let label = if dir > 0 { "bullish" } else { "bearish" };
    EntryTrendRead {
        ok: true,
        dir,
        reason: format!(
            "{label} (conf {vote_conf:+}, slope {vote_slope:+}, price {vote_price:+})"
        ),
    }
}

/// EMA20 slope vote over the last 10 bars: +1 rising, -1 falling, 0 flat. Uses a
/// small ATR-relative dead-band so sub-noise drift does not fake a trend.
fn ema_slope_vote(c: &[Candle]) -> i64 {
    let Some(ema) = ema_value(c, 20) else { return 0 };
    let Some(ema_prev) = ema_value(&c[..c.len().saturating_sub(10)], 20) else { return 0 };
    let Some(atr) = regime_atr(c, 14) else { return 0 };
    let delta = ema - ema_prev;
    let band = atr * 0.15;
    if delta > band {
        1
    } else if delta < -band {
        -1
    } else {
        0
    }
}

/// Price vs EMA20 vote: +1 above, -1 below, 0 inside a small ATR band.
fn price_vs_ema_vote(c: &[Candle]) -> i64 {
    let Some(ema) = ema_value(c, 20) else { return 0 };
    let Some(atr) = regime_atr(c, 14) else { return 0 };
    let close = c[c.len() - 1].close;
    let band = atr * 0.1;
    if close > ema + band {
        1
    } else if close < ema - band {
        -1
    } else {
        0
    }
}

/// Chart the strategy conditions are evaluated on: `spot` | `premium` | `both`.
fn run_mode_of(strat: &Strategy, s: &Settings) -> String {
    // The equity-only book always evaluates on the cash spot chart.
    if s.equity_only {
        return "spot".into();
    }
    // "Premium chart only (run + trade)": the strategy / indicator-filter mode
    // runs on the option-premium chart (Top Gainer on the CE leg, Top Loser on the
    // PE leg), never on spot. Decided per category so Paper Trade 2 can run only
    // its premium-routed category on the premium chart.
    if premium_only_for(strat, s) {
        return "premium".into();
    }
    match strat_category(strat) {
        StratCat::Index => s.run_index.clone(),
        StratCat::Fno => s.run_fno.clone(),
        StratCat::Comm => s.run_comm.clone(),
    }
}

/// Chart the order executes on: **always the option-premium contract**, for
/// indices, F&O stocks AND commodities alike (operator directive: "trade should
/// always execute on the premium chart"). The resolved premium leg is chosen by
/// the run/eval path; `trade_mode_of` only labels that intent for the UI.
fn trade_mode_of(_strat: &Strategy, _s: &Settings) -> String {
    // The equity-only book always executes on the cash spot chart - there is no
    // option premium contract to trade.
    if _s.equity_only {
        return "spot".into();
    }
    "premium".into()
}

/// True when the broker's own OMS owns the trailing stop for this position, so
/// `manage_positions` must never ratchet a competing app-side stop. Frozen at
/// entry (`trailOwner`) and mirrored by `pointTrailBrokerOnly` for older rows.
fn broker_owns_position_trail(p: &Value) -> bool {
    js(p, "trailOwner").eq_ignore_ascii_case("broker") || jb(p, "pointTrailBrokerOnly")
}

/// Parse the strike and option type out of a resolved option contract symbol
/// such as `POLICYBZR-Sep2026-1900-PE` (the last two `-` separated fields).
/// Returns `None` for anything that is not a CE/PE option leg.
fn option_strike_type(symbol: &str) -> Option<(f64, &str)> {
    let mut it = symbol.rsplit('-');
    let ot = it.next()?;
    if !(ot.eq_ignore_ascii_case("CE") || ot.eq_ignore_ascii_case("PE")) {
        return None;
    }
    let strike: f64 = it.next()?.trim().parse().ok()?;
    Some((strike, ot))
}

/// Map an option leg (`OPTIDX`/`OPTSTK`/`OPTFUT`, or any `*_FNO` segment) back
/// to its underlying spot instrument. "Run Strategy In: Spot chart" must
/// evaluate the entry conditions on the underlying spot chart, not the option's
/// own premium chart, so the run path calls this before fetching candles.
/// Returns `None` when the strategy is not an option leg or the underlying is
/// not in the app catalog / scrip master.
fn underlying_strategy(strat: &Strategy) -> Option<Strategy> {
    if !is_option_leg(strat) {
        return None;
    }
    // A RESOLVED option contract carries the FULL contract symbol
    // ("RELIANCE-Sep2026-2900-CE"), so `fno_underlying` of the whole string -
    // which only strips spaces - matches no catalog name and this function
    // wrongly returned `None`. The underlying is the leading token before the
    // contract's '-'/' ' separator; a plain UI underlying ("NIFTY 50",
    // "GIFT NIFTY", "RELIANCE") has no separator and is used whole. Match
    // against either candidate so both the raw name and the contract symbol map.
    let contract = strat.trading_symbol.trim();
    let mut prefixes: Vec<String> = Vec::new();
    let full = scrip::fno_underlying(contract);
    if !full.is_empty() {
        prefixes.push(full);
    }
    if let Some(tok) = contract.split(['-', ' ']).next() {
        let p = scrip::fno_underlying(tok);
        if !p.is_empty() && !prefixes.iter().any(|x| x.eq_ignore_ascii_case(&p)) {
            prefixes.push(p);
        }
    }
    if prefixes.is_empty() {
        return None;
    }
    let matches = |name: &str| {
        let n = scrip::fno_underlying(name);
        prefixes.iter().any(|p| p.eq_ignore_ascii_case(&n))
    };
    // Indices + equities from the app catalog (name -> F&O prefix match).
    for (sid, _exch) in crate::market::securities() {
        let Some((name, seg, inst)) = crate::market::symbol_meta(sid) else { continue };
        if !matches(&name) {
            continue;
        }
        if inst.eq_ignore_ascii_case("INDEX") {
            let mut out = strat.clone();
            out.security_id = sid;
            out.exchange_segment = "IDX_I".into();
            out.instrument = "INDEX".into();
            out.trading_symbol = name;
            return Some(out);
        }
        if seg.eq_ignore_ascii_case("NSE_EQ") || seg.eq_ignore_ascii_case("BSE_EQ") {
            let mut out = strat.clone();
            out.security_id = sid;
            out.exchange_segment = seg;
            out.instrument = inst;
            out.trading_symbol = name;
            return Some(out);
        }
    }
    // MCX/NCDEX commodities: the spot/underlying chart is the near-month FUTCOM.
    if let Some(sc) = scrip::get() {
        for c in sc.commodity_futures() {
            if matches(&c.name) {
                let mut out = strat.clone();
                out.security_id = c.security_id;
                out.exchange_segment = "MCX_COMM".into();
                out.instrument = "FUTCOM".into();
                out.trading_symbol = c.trading_symbol;
                return Some(out);
            }
        }
    }
    None
}

/// Run mode for a raw `(segment, instrument)` pair (scanner picks carry the
/// underlying, not a full `Strategy`). Mirrors `run_mode_of`.
fn run_mode_for(seg: &str, inst: &str, s: &Settings) -> String {
    let strat = Strategy {
        exchange_segment: seg.to_string(),
        instrument: inst.to_string(),
        ..Default::default()
    };
    // The equity-only book always evaluates on the cash spot chart.
    if s.equity_only {
        return "spot".into();
    }
    // "Premium chart only (run + trade)": run on the option-premium chart.
    if premium_only_for(&strat, s) {
        return "premium".into();
    }
    match strat_category(&strat) {
        StratCat::Index => s.run_index.clone(),
        StratCat::Fno => s.run_fno.clone(),
        StratCat::Comm => s.run_comm.clone(),
    }
}

/// Dhan exchange segment for a resolved option contract. MCX commodity options
/// (OPTFUT) live in `MCX_COMM`, exactly like their futures, so the old
/// `NSE_FNO else` fallback would send a broken commodity order.
fn fno_segment(exch: &str) -> &'static str {
    match exch.to_uppercase().as_str() {
        "BSE" => "BSE_FNO",
        "MCX" => "MCX_COMM",
        "NCDEX" => "NCD_FNO",
        _ => "NSE_FNO",
    }
}

/// Auto CE/PE bias for the Top Movers scanner (old AST `autoRunInSide` parity).
/// Classifies the ACTUAL traded universe - the operator's selected top gainers
/// / top losers - rather than whole-market breadth, so switching the selection
/// flips the auto side. Gainers -> +1 (CE), losers -> -1 (PE). When both legs
/// are selected the one with more live rows wins; an exact tie falls back to
/// market-wide breadth (`up`/`down`).
fn movers_auto_bias(want_g: bool, want_l: bool, pos: i64, neg: i64, up: i64, down: i64) -> i64 {
    if want_g && want_l {
        if pos > neg {
            1
        } else if neg > pos {
            -1
        } else if down > up {
            -1
        } else if up > down {
            1
        } else {
            0
        }
    } else if want_g {
        1
    } else if want_l {
        -1
    } else {
        0
    }
}

// ---------------------------------------------------------------------------
// Order helpers
// ---------------------------------------------------------------------------

fn cfg_f(cfg: &Value, k: &str, def: f64) -> f64 {
    cfg.get(k).and_then(|x| x.as_f64()).unwrap_or(def)
}
fn cfg_opt_f(cfg: &Value, k: &str) -> Option<f64> {
    cfg.get(k).and_then(|x| x.as_f64()).filter(|v| *v > 0.0)
}
fn cfg_str(cfg: &Value, k: &str, def: &str) -> String {
    cfg.get(k).and_then(|x| x.as_str()).map(|s| s.to_string()).unwrap_or_else(|| def.to_string())
}

/// Entry sizing policy for one leg: `(auto_lot_on, oi_pct, volume_pct)`.
///
/// Liquid F&O legs (`liquid_leg`) behave exactly like Top Movers unless their
/// dedicated Liquid Auto-Lot switch is ON. With the liquid switch ON the liquid
/// caps decide the size; with it OFF the leg falls back to the SAME global
/// Auto-Lot config Top Movers / indices / commodities use (so the operator's
/// normal `Lots` / global Auto-Lot never silently stops applying to liquid).
fn entry_auto_lot_cfg(strat: &Strategy, settings: &Settings) -> (bool, f64, f64) {
    if strat.liquid_leg && settings.liquid_auto_lot_on {
        (
            true,
            settings.liquid_auto_lot_oi_pct,
            settings.liquid_auto_lot_volume_pct,
        )
    } else {
        (
            false,
            settings.auto_lot_oi_pct,
            settings.auto_lot_volume_pct,
        )
    }
}

/// Entry slicing policy for one leg: `(enabled, lot_limit, slice_lots)`.
///
/// Liquid F&O legs use their own iceberg config only while the liquid slicing
/// switch is ON; otherwise they fall back to the global slicing config, exactly
/// like every other scanner leg.
fn entry_slice_cfg(strat: &Strategy, settings: &Settings) -> (bool, f64, f64) {
    if strat.liquid_leg && settings.liquid_slice_on {
        (
            true,
            settings.liquid_slice_lot_limit,
            settings.liquid_slice_lots,
        )
    } else {
        (settings.slice_on, settings.slice_lot_limit, settings.slice_lots)
    }
}

/// Auto-Lots math: `min(volume% lots, OI% lots, margin lots)`.
///
/// The old app capped liquidity participation at a fixed 1% of
/// `min(OI, volume)`. The new app splits that into two independent operator-set
/// percentages - one for traded volume, one for open interest - and takes the
/// *smaller* of the two lot counts, so whichever cap is more conservative wins.
/// Example: volume 2% -> 20 lots, OI 2% -> 10 lots, so 10 lots are bought.
/// Margin then caps by the funds available. Returns `None` (keep manual lots)
/// when no signal is usable.
fn calc_auto_lots(
    lot: f64,
    price: f64,
    oi: f64,
    volume: f64,
    avail: f64,
    oi_pct: f64,
    volume_pct: f64,
) -> Option<f64> {
    if lot <= 0.0 {
        return None;
    }
    let vol_lots = if volume > 0.0 && volume_pct > 0.0 {
        Some((volume * volume_pct / 100.0 / lot).floor())
    } else {
        None
    };
    let oi_lots = if oi > 0.0 && oi_pct > 0.0 {
        Some((oi * oi_pct / 100.0 / lot).floor())
    } else {
        None
    };
    // Whichever liquidity cap asks for the fewer lots wins.
    let mut lots = match (vol_lots, oi_lots) {
        (Some(v), Some(o)) => Some(v.min(o)),
        (Some(v), None) => Some(v),
        (None, Some(o)) => Some(o),
        (None, None) => None,
    };
    if avail > 0.0 && price > 0.0 {
        let m = (avail * 0.95 / (lot * price)).floor();
        lots = Some(match lots {
            Some(l) => l.min(m),
            None => m,
        });
    }
    lots.filter(|l| *l > 0.0)
}

/// Paper-only iceberg slice plan. Given the entry's total `qty` and its per-lot
/// size, return the child-slice quantities when slicing applies:
/// - `limit_lots <= 0` means "no threshold" (slice every entry); otherwise the
///   entry must reach `limit_lots` total lots before it is split.
/// - each full slice is `slice_lots` lots, with the final slice taking the
///   remainder (e.g. 20 lots, limit 20, slice 5 => [5,5,5,5]).
/// Returns an empty vec (single, unsliced entry) when slicing is off, the qty
/// does not reach the threshold, or a slice would not be smaller than the whole.
fn paper_slice_plan(qty: i64, lot: f64, limit_lots: f64, slice_lots: f64) -> Vec<i64> {
    if qty <= 0 || lot <= 0.0 || slice_lots <= 0.0 {
        return Vec::new();
    }
    let total_lots = qty as f64 / lot;
    if limit_lots > 0.0 && total_lots < limit_lots {
        return Vec::new();
    }
    let chunk = ((slice_lots * lot).round() as i64).max(1);
    if chunk >= qty {
        return Vec::new();
    }
    let mut plan = Vec::new();
    let mut rem = qty;
    while rem > 0 {
        let piece = rem.min(chunk);
        plan.push(piece);
        rem -= piece;
    }
    plan
}

/// Child-order sizes for a live entry. The engine-level slicing plan wins when it
/// is non-empty; otherwise the whole order goes out as a single chunk unless the
/// selected method's own auto-slice asks for a positive `fallback_chunk` smaller
/// than the order (the "Slice / Iceberg" card and the Super "Auto Order Slicing"
/// option). Always returns at least one piece for a positive `qty`.
fn order_pieces(qty: i64, plan: &[i64], fallback_chunk: i64) -> Vec<i64> {
    if qty <= 0 {
        return Vec::new();
    }
    if !plan.is_empty() {
        return plan.to_vec();
    }
    let chunk = if fallback_chunk > 0 && fallback_chunk < qty {
        fallback_chunk
    } else {
        qty
    };
    let mut out = Vec::new();
    let mut rem = qty;
    while rem > 0 {
        let piece = rem.min(chunk).max(1);
        rem -= piece;
        out.push(piece);
    }
    out
}

/// Simulate one paper child fill per slice at the (already slipped) mark `px`.
/// Returns the per-slice ledger plus the quantity-weighted average entry. The
/// mark does not move between child fills in the simulation, so the average
/// equals `px`; the ledger is what the UI shows as the sliced entry.
fn paper_slice_fills(plan: &[i64], lot: f64, px: f64, at: i64) -> (Vec<Value>, f64) {
    let px = round2(px);
    let mut legs: Vec<Value> = Vec::new();
    let mut notional = 0.0f64;
    let mut qty = 0i64;
    for &piece in plan {
        legs.push(json!({
            "qty": piece,
            "lots": if lot > 0.0 { round2(piece as f64 / lot) } else { 0.0 },
            "price": px,
            "at": at,
        }));
        notional += px * piece as f64;
        qty += piece;
    }
    let avg = if qty > 0 { notional / qty as f64 } else { px };
    (legs, avg)
}


/// Resolve the entry stop/target/trail set with the old AST precedence:
/// Risk:Reward > AI TP for targets, and Manual SL / Trail SL floor the stop.
/// Returns `(sl, tp, trail_pct, point_trail_points)`.
fn levels_for(
    settings: &Settings,
    cfg: &Value,
    side: &str,
    ltp: f64,
    ai_sl: f64,
    ai_tp: f64,
    ai_trail: f64,
) -> (f64, f64, f64, f64) {
    let is_buy = side == "BUY";
    // The operator's on/off checkboxes are authoritative: a leftover % value or
    // a stale method-config key must never arm a level the operator turned off.
    // This was the "I disabled Target/SL but it still fires" bug - the engine
    // read `manual_*_pct > 0` (and the config fallback) without checking the
    // matching tick.
    let manual_sl_pct = if settings.manual_sl {
        if settings.manual_sl_pct > 0.0 { settings.manual_sl_pct } else { cfg_f(cfg, "slPct", 0.0) }
    } else {
        0.0
    };
    // Overall SL (fixed % off entry) protects capital; Trail SL ratchets the
    // stop behind the peak but never below this floor.
    let sl = if manual_sl_pct > 0.0 {
        price_off(ltp, side, -manual_sl_pct / 100.0)
    } else if (settings.ai_sl || settings.sl_auto) && !settings.manual_sl && !settings.manual_trail_sl && ai_sl > 0.0 {
        ai_sl
    } else {
        0.0
    };
    // Manual Trail SL is gated by its own tick; when ticked without a % fall
    // back to the method config, then 1%.
    // Keep the trail as a PERCENTAGE (not a fixed price distance): the position
    // manager applies the old app profit-giveback formula
    // `stop = entry + (peak - entry) * (1 - trail/100)` so a trade in profit
    // always retains part of the run. Clamp to 0..100 (>=100 would place the
    // stop at/below entry and give the whole run back).
    let trail = if settings.manual_trail_sl {
        let pct = if settings.manual_trail_sl_pct > 0.0 {
            settings.manual_trail_sl_pct
        } else {
            cfg_f(cfg, "trailPct", 1.0)
        };
        pct.clamp(0.0, 100.0)
    } else if settings.ai_trail_tp && ai_trail > 0.0 && ltp > 0.0 {
        // AI trail is an ATR distance; express it as a % of entry so the same
        // profit-giveback formula applies.
        (ai_trail / ltp * 100.0).clamp(0.0, 100.0)
    } else {
        0.0
    };
    // Points trail (Dhan Super-Order style): a fixed price jump behind the best
    // price. "Pts = % (auto)" (linked) derives the broker jump per instrument
    // from the Trail SL % (points = entry premium x pct / 100, floored to one
    // tick) and sends it as the real Super-Order `trailingJump`. App-side, the
    // same link recomputes the jump from the RUNNING profit every tick, so the
    // point stop is the exact point equivalent of the percentage stop. Unlinked,
    // the operator's manual points value (or the method-config jump) is used and
    // the two mechanisms compete. Available on every engine.
    let link_points = settings.trail_points_from_pct && trail > 0.0 && ltp > 0.0;
    let point_trail = if link_points {
        round_to_tick(ltp * trail / 100.0).max(0.05)
    } else if settings.manual_point_trail_sl {
        let pts = if settings.manual_point_trail_sl_points > 0.0 {
            settings.manual_point_trail_sl_points
        } else {
            cfg_f(cfg, "trailingJump", 0.0)
        };
        pts.max(0.0)
    } else {
        0.0
    };
    // Take-profit precedence: RR > AI TP. The manual "Take Profit %" card was
    // removed, so a saved method config `tpPct` can no longer re-arm a hidden
    // target.
    let mut tp = 0.0;
    if settings.rr_enabled {
        // Risk:Reward overrides manual/AI TP: target = SL distance x Target RR.
        let rr = if settings.rr_value > 0.0 { settings.rr_value } else { 2.0 };
        let risk = (ltp - sl).abs();
        if sl > 0.0 && risk > 0.0 {
            tp = if is_buy { ltp + risk * rr } else { ltp - risk * rr };
        }
    } else if (settings.ai_tp_pct || settings.ai_trail_tp) && ai_tp > 0.0 {
        tp = ai_tp;
    }
    (sl.max(0.0), tp.max(0.0), trail, point_trail)
}


/// Post-reconnect exposure the engine must adopt for one security from the
/// broker's signed net minus the engine's signed net:
///   * `0`   the two books agree (nothing to do),
///   * `0` also when the broker net is merely smaller than an engine leg - that
///     is a partial exit, handled by aligning the engine qty, not by adopting an
///     opposite position,
///   * otherwise the extra broker exposure (same direction), or the whole book
///     when the engine holds nothing on the security.
fn reconnect_delta(engine_signed: i64, broker_signed: i64) -> i64 {
    if engine_signed == 0 {
        broker_signed
    } else if (engine_signed > 0) == (broker_signed > 0) && broker_signed.abs() > engine_signed.abs() {
        broker_signed - engine_signed
    } else {
        0
    }
}

fn price_off(price: f64, side: &str, frac: f64) -> f64 {
    let d = price * frac;
    if side == "BUY" {
        price + d
    } else {
        price - d
    }
}

/// Percent-of-running-profit trailing stop.
///
/// `pct` is the share of the RUNNING LIVE PROFIT that may be given back. The
/// stop sits `pct`% of the peak profit behind that peak (converted from the
/// percent to a price distance, i.e. points), and only ratchets forward as the
/// peak grows. It is armed by profit itself, never by the entry price:
///
///   peak profit 1000, pct 10 -> give back 100, stop at 900 profit
///   peak profit 2000, pct 10 -> give back 200, stop at 1800 profit
///
/// A reversal to the stop cuts the trade. The giveback is exactly `pct` of the
/// running profit peak, so the trail arms on ANY profit (even a single rupee)
/// and only gives back its configured share of it - no fixed floor that would
/// otherwise stop out a small winner below entry.
fn profit_trail_stop(is_buy: bool, entry: f64, peak_profit: f64, pct: f64) -> f64 {
    let giveback = peak_profit * pct / 100.0;
    if is_buy {
        entry + peak_profit - giveback
    } else {
        entry - peak_profit + giveback
    }
}

/// Dhan Super-Order style points trail: a FIXED price jump behind the best
/// price. Like the native broker trail it ratchets forward only. Armed by the
/// running profit, so the jump always sits behind the peak, never off entry.
///
/// No tick floor is applied here: when "Pts = % (auto)" is linked the jump is
/// the exact point equivalent of the percentage stop, so both mechanisms must
/// land on the SAME stop price (and `TRAIL_SL_BOTH` owns the exit). The 0.05
/// tick floor belongs to order placement (`levels_for`), not to this app-side
/// comparison - flooring it here made a sub-tick percent trail look different
/// from its own point equivalent and mislabelled the exit as `TRAIL_SL_PCT`.
fn point_trail_stop(is_buy: bool, entry: f64, peak_profit: f64, points: f64) -> f64 {
    let jump = points.max(0.0);
    if is_buy {
        entry + peak_profit - jump
    } else {
        entry - peak_profit + jump
    }
}

/// Resolve the app-side trail inputs for one position from the LIVE operator
/// switches plus the entry-time stored values.
///
/// The stored `trail` / `pointTrail` are frozen at entry, so the manager must
/// re-gate them on the live switches every tick: unticking a switch has to stop
/// the trail immediately for every open position (the "unchecked but trail still
/// fires" bug). Returns `(trail_pct_live, points_live)`; both zero means no
/// app-side trail is active.
///
/// `points_from_pct` ("Pts = % (auto)") derives the point jump from the live
/// percentage, so it is active only while the percentage trail itself is active -
/// the auto-ticked point box must never keep a trail alive after the % switch is
/// unticked. An unlinked manual point trail is gated by its own switch.
fn live_trail_inputs(
    trail_switch_on: bool,
    ai_trail_on: bool,
    point_trail_on: bool,
    points_from_pct: bool,
    stored_trail_pct: f64,
    stored_point_trail: f64,
    peak_profit: f64,
) -> (f64, f64) {
    let pct_active = trail_switch_on || ai_trail_on;
    let trail_pct_live = if pct_active { stored_trail_pct } else { 0.0 };
    let points_live = if points_from_pct {
        if pct_active && trail_pct_live > 0.0 {
            peak_profit.max(0.0) * trail_pct_live / 100.0
        } else {
            0.0
        }
    } else if point_trail_on {
        stored_point_trail
    } else {
        0.0
    };
    (trail_pct_live, points_live)
}

/// Pick the active app-side trail stop. Both the percentage and the points
/// trail are evaluated independently; the tighter stop (never below `floor`)
/// wins. The returned tag names the mechanism that owns the stop so the exit
/// reason can distinguish a percentage Trail SL from a point Trail SL, and
/// `TRAIL_SL_BOTH` when both land on the same price.
fn active_trail_stop(
    is_buy: bool,
    entry: f64,
    peak_profit: f64,
    trail_pct: f64,
    point_points: f64,
    floor: f64,
) -> (f64, &'static str) {
    let mut stop = floor;
    let mut source = "";
    if trail_pct > 0.0 && peak_profit > 0.0 {
        let pct_stop = profit_trail_stop(is_buy, entry, peak_profit, trail_pct);
        if more_favourable(is_buy, pct_stop, stop) {
            stop = pct_stop;
            source = "TRAIL_SL_PCT";
        }
    }
    if point_points > 0.0 && peak_profit > 0.0 {
        let pts_stop = point_trail_stop(is_buy, entry, peak_profit, point_points);
        if more_favourable(is_buy, pts_stop, stop) {
            stop = pts_stop;
            source = "TRAIL_SL_PTS";
        } else if source == "TRAIL_SL_PCT" && (pts_stop - stop).abs() < 1e-6 {
            source = "TRAIL_SL_BOTH";
        }
    }
    (stop, source)
}

/// Whether `a` is a tighter stop than `b` for the given side: a higher stop for
/// a BUY, a lower one for a SELL. A missing `b` is always beaten.
fn more_favourable(is_buy: bool, a: f64, b: f64) -> bool {
    if b <= 0.0 {
        true
    } else if is_buy {
        a > b + 1e-9
    } else {
        a < b - 1e-9
    }
}

/// Orders/sec budget: clamped to 1..30 (Dhan rejects bursts above the venue's
/// rate limit). The operator's number is the max orders sent per second.
fn order_per_sec_budget(ops: i64) -> i64 {
    ops.clamp(1, 30)
}

/// "Engine Scan" interval bounds. A 50ms floor keeps the scan from ever spinning
/// the loop, and the 24h ceiling matches the max a user can express in the UI.
const SCAN_INTERVAL_MIN_MS: i64 = 50;
const SCAN_INTERVAL_MAX_MS: i64 = 86_400_000;

/// Normalise the Engine Scan interval: anything below the floor (including a
/// stray 0/negative) becomes 100ms, and anything above 24h is clamped. Applied
/// on state load and on every settings save so the engine always sees a value it
/// can trust.
fn scan_interval_budget(ms: i64) -> i64 {
    if ms < SCAN_INTERVAL_MIN_MS {
        100
    } else {
        ms.min(SCAN_INTERVAL_MAX_MS)
    }
}

/// Normalise the Engine Scan bar-close timeframe to the two the UI offers. Any
/// unrecognised value falls back to `1min` so the engine never has to guess.
fn scan_bar_close_tf(tf: &str) -> &'static str {
    match tf.trim().to_lowercase().as_str() {
        "5min" | "5m" => "5min",
        _ => "1min",
    }
}

/// Milliseconds in one bar of the given Engine Scan bar-close timeframe.
fn scan_bar_close_step_ms(tf: &str) -> i64 {
    match scan_bar_close_tf(tf) {
        "5min" => 5 * 60_000,
        _ => 60_000,
    }
}

/// Index ids must be scanned under the `IDX_I` segment so their `IDX_I:<sid>`
/// quote key matches the feed cache. Injecting them as `NSE_EQ` silently drops
/// every index from the Top Movers / NIFTY-trend universes.
fn index_legs(ids: &[i64]) -> Vec<(i64, String)> {
    ids.iter()
        .filter(|id| **id > 0)
        .map(|id| (*id, "IDX_I".to_string()))
        .collect()
}

/// Map an entry-rejection message to a stable blocker code, so the "Why no
/// trades?" panel groups similar failures (margin, trend, duplicate, premium)
/// into one row instead of one row per exact message variation.
fn classify_entry_error(e: &str) -> &'static str {
    let l = e.to_ascii_lowercase();
    if l.starts_with("trade blocked:") || l.contains("margin") {
        "margin"
    } else if l.contains("trend confirmation") {
        "trend"
    } else if l.contains("duplicate") {
        "duplicate"
    } else if l.contains("premium") || l.contains("option") {
        "no-premium"
    } else if l.contains("quantity") || l.contains("qty") {
        "quantity"
    } else if l.contains("orders/sec") || l.contains("rate") {
        "orders-per-sec"
    } else if l.contains("disarmed") || l.contains("engine") {
        "engine-state"
    } else if l.contains("research") || l.contains("target") {
        "research"
    } else if l.contains("not connected") || l.contains("feed") {
        "feed"
    } else {
        "order-error"
    }
}

/// "Trades per strategy" gate, exactly like the old engine:
///  - Max trades off            -> unlimited.
///  - "AI auto trades" on       -> the fixed cap is ignored (AI decides), so
///                                 entries are unlimited too.
///  - Max trades on + count > 0 -> allow while `done < count`.
/// A non-positive count is treated as "not configured" and never blocks.
fn trade_limit_allows(trade_limit: bool, ai_trades: bool, count: i64, done: i64) -> bool {
    if !trade_limit || ai_trades || count <= 0 {
        return true;
    }
    done < count
}

/// Directional exposure of a trade on the UNDERLYING: +1 bullish, -1 bearish.
/// BUY CE and SELL PE are long the underlying; BUY PE and SELL CE are short.
/// Futures / equity use the trade side directly.
fn option_exposure_dir(side: &str, trading_symbol: &str) -> i32 {
    let words: Vec<String> = trading_symbol
        .to_uppercase()
        .split(|c: char| !c.is_ascii_alphanumeric())
        .map(|w| w.to_string())
        .collect();
    let is_ce = words.iter().any(|w| w == "CE");
    let is_pe = words.iter().any(|w| w == "PE");
    let buy = side.eq_ignore_ascii_case("BUY");
    if is_ce {
        if buy { 1 } else { -1 }
    } else if is_pe {
        if buy { -1 } else { 1 }
    } else if buy {
        1
    } else {
        -1
    }
}

fn underlying_of(symbol: &str, exch: &str) -> String {
    // A resolved derivative carries the full contract ("NIFTY-Oct2026-22450-PE",
    // "CRUDEOIL-17Nov2026-FUT"). Target Lab caches plans under the canonical
    // underlying ("NIFTY", "CRUDEOIL"), so stripping only spaces would make
    // every auto-cut lookup miss and silently leave positions unprotected.
    let contract = symbol.trim();
    let mut fields = contract.rsplit('-');
    let ot = fields.next().unwrap_or("");
    let base: String = if ot.eq_ignore_ascii_case("CE") || ot.eq_ignore_ascii_case("PE") {
        // Drop strike and expiry, keep every leading '-' token of the name.
        let _ = fields.next();
        let _ = fields.next();
        let rest: Vec<&str> = fields.collect();
        if rest.is_empty() {
            contract.to_string()
        } else {
            rest.into_iter().rev().collect::<Vec<_>>().join("-")
        }
    } else if ot.eq_ignore_ascii_case("FUT") {
        // Futures have no strike: drop the expiry and keep the name.
        let _ = fields.next();
        let rest: Vec<&str> = fields.collect();
        if rest.is_empty() {
            contract.to_string()
        } else {
            rest.into_iter().rev().collect::<Vec<_>>().join("-")
        }
    } else {
        contract.to_string()
    };
    let u = scrip::fno_underlying(&base);
    if !u.is_empty() {
        return u;
    }
    if exch.contains("BSE") {
        base.split(&[' ', '-'][..]).next().unwrap_or(&base).to_uppercase()
    } else {
        base.to_uppercase()
    }
}

fn round2(v: f64) -> f64 {
    (v * 100.0).round() / 100.0
}

/// Round a price distance to the nearest option tick (0.05) with a one-tick
/// floor, so a percentage-derived points trail can never round down to zero
/// (which would silently disable the trail on a cheap premium).
fn round_to_tick(v: f64) -> f64 {
    (v / 0.05).round() * 0.05
}

/// Coarse instrument class for the realised-evidence ledger. Options and
/// futures have very different cost structures, so their results are never
/// pooled in the same bucket.
fn instrument_class(instrument: &str, trading_symbol: &str) -> &'static str {
    let i = instrument.to_ascii_uppercase();
    // The Dhan instrument token is authoritative when present.
    if !i.is_empty() {
        if i.contains("OPT") {
            return "options";
        }
        if i.contains("FUT") {
            return "futures";
        }
        return "equity";
    }
    // No token: fall back to the symbol shape. A CE/PE suffix is only trusted
    // when it follows a space (an F&O symbol like "NIFTY 24000 CE"), so a plain
    // equity that happens to end in "CE" (RELIANCE) is not misclassified.
    let sym = trading_symbol.to_ascii_uppercase();
    let parts: Vec<&str> = sym.split_whitespace().collect();
    if parts.len() >= 2 {
        if let Some(last) = parts.last() {
            if *last == "CE" || *last == "PE" {
                return "options";
            }
            if last.starts_with("FUT") {
                return "futures";
            }
        }
    }
    "equity"
}

fn ist_day_key() -> String {
    let secs = crate::market::now_secs() + 19800;
    let days = secs.div_euclid(86400);
    format!("{days}")
}

/// Start of the current IST day in epoch milliseconds, so "today's realised
/// P&L" can be summed without a timezone library.
fn ist_day_start_ms() -> i64 {
    let days = (crate::market::now_secs() + 19800).div_euclid(86400);
    (days * 86400 - 19800) * 1000
}

/// Entries stay blocked for the rest of the IST day once the automatic
/// square-off has already flattened the book.
fn auto_arm_allowed(last_square_off_day: &str, today: &str) -> bool {
    last_square_off_day != today
}

/// The master switch owns the run state; `armed` is derived from it.
fn master_armed(engine_on: bool, last_square_off_day: &str, today: &str) -> bool {
    engine_on && auto_arm_allowed(last_square_off_day, today)
}

fn txn(side: &str) -> TransactionType {
    if side.eq_ignore_ascii_case("SELL") {
        TransactionType::Sell
    } else {
        TransactionType::Buy
    }
}

fn seg_from(exch: &str) -> ExchangeSegment {
    match exch.to_uppercase().as_str() {
        "IDX_I" => ExchangeSegment::IdxI,
        "NSE_EQ" => ExchangeSegment::NseEq,
        "NSE_FNO" => ExchangeSegment::NseFno,
        "NSE_CURRENCY" => ExchangeSegment::NseCurrency,
        "BSE_EQ" => ExchangeSegment::BseEq,
        "MCX_COMM" => ExchangeSegment::McxComm,
        "BSE_CURRENCY" => ExchangeSegment::BseCurrency,
        "BSE_FNO" => ExchangeSegment::BseFno,
        _ => ExchangeSegment::NseFno,
    }
}

fn product_from<S: AsRef<str>>(s: S) -> ProductType {
    match s.as_ref().to_uppercase().as_str() {
        "CNC" => ProductType::Cnc,
        "MARGIN" => ProductType::Margin,
        "MTF" => ProductType::Mtf,
        "CO" => ProductType::Co,
        "BO" => ProductType::Bo,
        _ => ProductType::Intraday,
    }
}

fn order_type_from<S: AsRef<str>>(s: S) -> OrderType {
    match s.as_ref().to_uppercase().as_str() {
        "LIMIT" => OrderType::Limit,
        "STOP_LOSS" => OrderType::StopLoss,
        "STOP_LOSS_MARKET" => OrderType::StopLossMarket,
        _ => OrderType::Market,
    }
}

fn validity_from<S: AsRef<str>>(s: S) -> Validity {
    if s.as_ref().eq_ignore_ascii_case("IOC") {
        Validity::Ioc
    } else {
        Validity::Day
    }
}

