/// "Why no trades?" readout: every gate that dropped a signal recently, the
/// live margin budget, engine/feed state and the recent order attempts, so the
/// UI can state the exact current reason in one place.
pub async fn blockers_get(State(rt): State<RealtimeState>) -> impl IntoResponse {
    let within: i64 = 30 * 60 * 1000;
    let mut payload = rt.blockers_snapshot(within);
    let (engine_on, armed, lots, auto_lots, skip_margin, latch_on, latch_secs) = rt
        .doc()
        .map(|d| {
            (
                d.engine_on,
                d.armed,
                d.settings.lots,
                d.auto_lots,
                d.settings.skip_on_margin_block,
                d.settings.entry_latch_on,
                d.settings.entry_latch_secs,
            )
        })
        .unwrap_or((false, false, 0.0, false, false, false, 0.0));
    let connected = rt.dhan.is_connected().await;
    let feed_live = rt.dhan.feed_live();
    let budget = rt.margin_budget();
    let (locked, running) = rt.locked_margin();
    if let Some(o) = payload.as_object_mut() {
        o.insert("engineOn".into(), json!(engine_on));
        o.insert("armed".into(), json!(armed));
        o.insert("connected".into(), json!(connected));
        o.insert("feedLive".into(), json!(feed_live));
        o.insert("lots".into(), json!(lots));
        o.insert("autoLots".into(), json!(auto_lots));
        o.insert("skipOnMarginBlock".into(), json!(skip_margin));
        o.insert("entryLatchOn".into(), json!(latch_on));
        o.insert("entryLatchSecs".into(), json!(latch_secs));
        o.insert("marginBudget".into(), json!(round2(budget)));
        o.insert("marginLocked".into(), json!(round2(locked)));
        o.insert("marginFree".into(), json!(round2((budget - locked).max(0.0))));
        o.insert("openPositions".into(), json!(running));
        // A short, plain-language headline the UI shows above the detail rows.
        let headline = if !connected {
            "Dhan not connected - connect first".to_string()
        } else if !feed_live {
            "Live feed is not streaming - waiting for ticks".to_string()
        } else if !engine_on {
            "Engine is OFF - turn on AI Smart Trading".to_string()
        } else if !armed {
            "Engine is ON but disarmed for today (auto square-off already ran)".to_string()
        } else if budget <= 0.0 {
            "No shared margin allotted to this tab - set an allotment".to_string()
        } else if budget - locked <= 0.0 {
            format!(
                "Margin fully locked by {} open position(s) (Rs {:.0} of Rs {:.0}) - square off or raise the allotment",
                running, locked, budget
            )
        } else {
            "Engine is armed and evaluating - see the blocking reasons below".to_string()
        };
        o.insert("headline".into(), json!(headline));
    }
    Json(payload)
}

