pub async fn template_post(State(rt): State<RealtimeState>, Json(v): Json<Value>) -> impl IntoResponse {
    let action = js(&v, "action");
    let name = js(&v, "name");
    let mut out = json!({ "ok": false, "error": "unknown action" });
    let mut after_log: Option<(String, String)> = None;
    match action.as_str() {
        "save" => {
            if name.is_empty() {
                out = json!({ "ok": false, "error": "name required" });
            } else {
                let side = {
                    let s = js(&v, "side");
                    if s.is_empty() { "bullish".to_string() } else { s }
                };
                let built = rt.doc().map(|mut d| {
                    let settings = serde_json::to_value(&d.settings).unwrap_or(json!({}));
                    // Capture the ticked strategy set too, so "Run saved template"
                    // restores the exact run definition (old-app parity).
                    let selected: Vec<String> = d
                        .selected
                        .iter()
                        .filter(|(_, on)| **on)
                        .map(|(id, _)| id.clone())
                        .collect();
                    let tpl = json!({
                        "name": name.clone(),
                        "side": side.clone(),
                        "savedAt": now_ms(),
                        "settings": settings,
                        "selected": selected,
                        "origin": rt.engine_label(),
                        "originId": rt.engine_id()
                    });
                    // Keep a copy in the saving engine's book so the existing
                    // backup/export flow still carries the template.
                    d.templates.insert(name.clone(), tpl.clone());
                    tpl
                });
                if let Some(tpl) = built {
                    if let Ok(mut pool) = rt.template_pool.lock() {
                        pool.insert(name.clone(), tpl);
                    }
                    persist_template_pool(&rt.template_pool);
                    out = json!({ "ok": true, "name": name, "origin": rt.engine_label() });
                }
            }
        }
        "delete" => {
            if let Some(mut d) = rt.doc() {
                d.templates.remove(&name);
            }
            if let Ok(mut pool) = rt.template_pool.lock() {
                pool.remove(&name);
            }
            persist_template_pool(&rt.template_pool);
            out = json!({ "ok": true });
        }
        // "open" is kept for older callers; "apply" is the explicit one-click
        // settings apply used by the universal template row. Both apply settings
        // only. "run" additionally restores the ticked strategies and starts.
        "open" | "apply" | "run" => {
            let tpl = rt
                .template_pool
                .lock()
                .ok()
                .and_then(|pool| pool.get(&name).cloned());
            let Some(t) = tpl else {
                out = json!({ "ok": false, "error": "template not found" });
                rt.save();
                return Json(out);
            };
            if let Some(mut d) = rt.doc() {
                if let Some(sv) = t.get("settings") {
                    if let Ok(s) = serde_json::from_value::<Settings>(sv.clone()) {
                        d.settings = s;
                        rt.enforce_constraints(&mut d.settings);
                    }
                }
                // Templates saved by the Auto Experiment engine embed their own
                // strategy rows. Restore (upsert) them on apply/run so the entry
                // indicator-filter rule the backtest used is actually present in
                // this engine's strategy book - otherwise applying the template
                // would only import settings and the trade could never fire.
                let mut embedded: Vec<String> = Vec::new();
                if let Some(arr) = t.get("strategies").and_then(|x| x.as_array()) {
                    for sv in arr {
                        let Ok(mut s) = serde_json::from_value::<Strategy>(sv.clone()) else {
                            continue;
                        };
                        if s.id.is_empty() {
                            s.id = gen_id("rtstrat");
                        }
                        if let Some(e) = d.strategies.iter_mut().find(|x| x.id == s.id) {
                            *e = s.clone();
                        } else {
                            d.strategies.push(s.clone());
                        }
                        embedded.push(s.id);
                    }
                }
                if action == "run" {
                    let mut restored = 0usize;
                    if let Some(arr) = t.get("selected").and_then(|x| x.as_array()) {
                        let ids: Vec<String> = arr
                            .iter()
                            .filter_map(|x| x.as_str().map(|s| s.to_string()))
                            .collect();
                        if !ids.is_empty() {
                            d.selected.clear();
                            for id in ids {
                                if d.strategies.iter().any(|s| s.id == id) {
                                    d.selected.insert(id, true);
                                    restored += 1;
                                }
                            }
                        }
                    }
                    // Auto Experiment templates list their strategies under
                    // `strategies`, not `selected`. Tick the ones just restored so
                    // "Run" actually starts trading the backtested rule.
                    for id in &embedded {
                        d.selected.insert(id.clone(), true);
                        restored += 1;
                    }
                    d.engine_on = true;
                    let armed = master_armed(true, &d.last_square_off_day, &ist_day_key());
                    d.armed = armed;
                    rt.force_tick.store(true, Ordering::Relaxed);
                    after_log = Some((
                        "info".into(),
                        if armed {
                            format!(
                                "Quick run template \"{name}\" started (armed) - {restored} strategy(s) restored from the template"
                            )
                        } else {
                            format!(
                                "Quick run template \"{name}\" started, but new entries are blocked for today (auto square-off already ran) - {restored} strategy(s) restored"
                            )
                        },
                    ));
                    out = json!({
                        "ok": true,
                        "name": name,
                        "side": js(&t, "side"),
                        "origin": t.get("origin").cloned().unwrap_or(Value::Null),
                        "restored": restored
                    });
                } else {
                    out = json!({
                        "ok": true,
                        "name": name,
                        "side": js(&t, "side"),
                        "origin": t.get("origin").cloned().unwrap_or(Value::Null)
                    });
                }
            }
        }
        _ => {}
    }
    if let Some((level, msg)) = after_log {
        rt.log(&level, &msg);
    }
    rt.save();
    Json(out)
}
pub async fn trend_get(State(rt): State<RealtimeState>) -> impl IntoResponse {
    // NIFTY trend-following readout. Re-run the (throttled) trend + scan passes so
    // the header is fresh even between engine ticks, then return the pick detail.
    let on = rt.doc().map(|d| d.settings.nifty_trend_on).unwrap_or(false);
    rt.refresh_nifty_trend().await;
    rt.refresh_nifty_scan().await;
    let detail = rt.nifty_readout().await;
    let dir = rt.nifty_dir.load(Ordering::Relaxed);
    // Surface each pick by its underlying (the id the UI removes / the scanner
    // excludes), not the resolved option leg.
    let picks: Vec<Value> = jarr(&detail, "picks")
        .iter()
        .map(|p| {
            json!({
                "securityId": ji(p, "underlyingSecurityId"),
                "underlying": js(p, "underlying"),
                "side": js(p, "side"),
                "tradingSymbol": js(p, "tradingSymbol"),
                "changePct": jf(p, "changePct"),
            })
        })
        .collect();
    Json(json!({ "ok": true, "on": on, "dir": dir, "picks": picks, "detail": detail }))
}

/// Pane-only NIFTY Bollinger %B feed for the Paper Trade 3 tab. Returns the
/// normal `bbpct` (Pane) series computed on NIFTY spot at the engine's selected
/// timeframe, so the tab can draw the indicator right under NIFTY Trend
/// Following without embedding a whole candlestick chart. When both 1min + 5min
/// are ticked the engine runs `both`; a single pane can only show one series, so
/// 5min is used (the engine default).
pub async fn nifty_pane_get(State(rt): State<RealtimeState>) -> impl IntoResponse {
    // Paper Trade 2 has no NIFTY BB%b (Pane) section at all: report it inactive
    // so a stale client can never draw or drive the removed pane.
    if rt.indices_commodities_only() {
        return Json(json!({
            "ok": true,
            "on": false,
            "paneOn": false,
            "zoneOn": false,
            "trendOn": false,
            "comboOn": false,
            "combined": false,
            "dir": 0,
            "last": Value::Null,
            "points": [],
        }));
    }
    let s = rt.doc().map(|d| d.settings.clone()).unwrap_or_default();
    let tf = {
        let t = nifty_timeframe(&s);
        if t.eq_ignore_ascii_case("both") {
            "5min".to_string()
        } else {
            t
        }
    };
    let candles = rt
        .live_candles(NIFTY_SEC, "IDX_I", "INDEX", &tf)
        .await
        .unwrap_or_default();
    let series = nifty_conf_series("bbpct", &candles, &s);
    let points: Vec<Value> = series
        .first()
        .map(|ser| ser.data.iter().map(|p| json!([p.time, p.value])).collect())
        .unwrap_or_default();
    let last = series.first().and_then(|ser| ser.data.last()).map(|p| p.value);
    let dir = rt.nifty_dir.load(Ordering::Relaxed);
    Json(json!({
        "ok": true,
        "on": nifty_dir_feature_on(&s),
        "tf": tf,
        "last": last,
        "points": points,
        "paneOn": s.bbpct_pane_on,
        "zoneOn": s.bbpct_zone_on,
        "overbought": s.bbpct_overbought,
        "oversold": s.bbpct_oversold,
        "obOn": s.bbpct_ob_on,
        "osOn": s.bbpct_os_on,
        "trendOn": s.bbpct_trend_on,
        "trendBullOn": s.bbpct_trend_bull_on,
        "trendBearOn": s.bbpct_trend_bear_on,
        "comboOn": s.bbpct_combo_on,
        "combined": s.bbpct_combo_on || (s.bbpct_zone_on && s.bbpct_trend_on),
        "dir": dir,
        "lineDir": rt.nifty_bbpct_line_dir.load(Ordering::Relaxed),
        "zoneDir": rt.nifty_zone_dir.load(Ordering::Relaxed),
    }))
}

