    #[tokio::test]
    async fn liquid_scanner_belongs_only_to_the_full_engines() {
        // Liquid F&O scanner + its lot policy live on Realtime Trading Engine and
        // Paper Trade 1 only. The indices-only / commodities-only books (PT2,
        // PT3, RT2, RT3) strip it on save/import and never scan the basket.
        let full = [
            RealtimeState::new(crate::broker::DhanState::new(crate::market::MarketState::new())),
            RealtimeState::new_paper(crate::broker::DhanState::new(crate::market::MarketState::new())),
        ];
        for rt in &full {
            assert!(rt.allows_liquid_stocks(), "{} keeps the Liquid F&O scanner", rt.state_file);
            let mut s = Settings::default();
            s.liquid_on = true;
            s.liquid_gainers = 3;
            s.liquid_list = vec![2885];
            s.liquid_auto_lot_on = true;
            s.liquid_slice_on = true;
            rt.enforce_constraints(&mut s);
            assert!(s.liquid_on, "{} keeps the liquid master", rt.state_file);
            assert_eq!(s.liquid_gainers, 3);
            assert_eq!(s.liquid_list, vec![2885]);
            assert!(s.liquid_auto_lot_on, "{} keeps the liquid lot policy", rt.state_file);
            assert!(s.liquid_slice_on);
        }

        let stripped = [
            RealtimeState::new_paper2(crate::broker::DhanState::new(crate::market::MarketState::new())),
            RealtimeState::new_paper3(crate::broker::DhanState::new(crate::market::MarketState::new())),
            RealtimeState::new_realtime2(crate::broker::DhanState::new(crate::market::MarketState::new())),
            RealtimeState::new_realtime3(crate::broker::DhanState::new(crate::market::MarketState::new())),
        ];
        for rt in &stripped {
            assert!(!rt.allows_liquid_stocks(), "{} has no Liquid F&O scanner", rt.state_file);
            let mut s = Settings::default();
            s.liquid_on = true;
            s.liquid_gainers = 3;
            s.liquid_losers = 2;
            s.liquid_gainer = 2885;
            s.liquid_loser = 2885;
            s.liquid_list = vec![2885];
            s.liquid_auto_lot_on = true;
            s.liquid_slice_on = true;
            rt.enforce_constraints(&mut s);
            assert!(!s.liquid_on, "{} must drop the liquid master", rt.state_file);
            assert_eq!(s.liquid_gainers, 0);
            assert_eq!(s.liquid_losers, 0);
            assert_eq!(s.liquid_gainer, 0);
            assert_eq!(s.liquid_loser, 0);
            assert!(s.liquid_list.is_empty(), "{} drops the liquid adds", rt.state_file);
            assert!(!s.liquid_auto_lot_on, "{} drops the liquid lot policy", rt.state_file);
            assert!(!s.liquid_slice_on);
        }
    }

    #[tokio::test]
    async fn realtime_and_paper1_strip_index_and_commodity_scanner() {
        // The Realtime Trading Engine and Paper Trade 1 no longer expose the
        // Indices (Top-Movers) picker nor the Commodity (MCX) scanner, so a
        // saved file / import / settings POST must be stripped for them.
        fn seed() -> Settings {
            let mut s = Settings::default();
            s.movers_indices = vec![13];
            s.movers_index_legs = vec![MoversIndexLeg { security_id: 13, side: "CE".into() }];
            s.commodity_on = true;
            s.commodity_list = vec![428348];
            s.commodity_legs = vec![MoversIndexLeg { security_id: 428348, side: "PE".into() }];
            s.run_index = "both".into();
            s.run_comm = "spot".into();
            s.trade_in_index = "futures".into();
            s.trade_in_comm = "futures".into();
            s
        }

        let real = RealtimeState::new(crate::broker::DhanState::new(crate::market::MarketState::new()));
        let mut a = seed();
        real.enforce_constraints(&mut a);
        assert!(a.movers_indices.is_empty(), "real engine drops the index picker");
        assert!(a.movers_index_legs.is_empty());
        assert!(!a.commodity_on, "real engine drops the commodity scanner");
        assert!(a.commodity_list.is_empty());
        assert!(a.commodity_legs.is_empty());
        assert_eq!(a.run_index, "spot");
        assert_eq!(a.trade_in_index, "premium");

        let p1 = RealtimeState::new_paper(crate::broker::DhanState::new(crate::market::MarketState::new()));
        let mut b = seed();
        p1.enforce_constraints(&mut b);
        assert!(b.movers_indices.is_empty(), "paper 1 drops the index picker");
        assert!(!b.commodity_on, "paper 1 drops the commodity scanner");
        assert!(b.commodity_list.is_empty());

        // Paper Trade 2 is indices only: it keeps its index book and drops the
        // commodity scanner entirely.
        let p2 = RealtimeState::new_paper2(crate::broker::DhanState::new(crate::market::MarketState::new()));
        let mut c = seed();
        p2.enforce_constraints(&mut c);
        assert_eq!(c.movers_indices, vec![13], "paper 2 keeps the operator indices");
        assert_eq!(c.movers_index_legs.len(), 1);
        assert!(!c.commodity_on, "paper 2 drops commodities");
        assert!(c.commodity_list.is_empty());
        assert!(c.commodity_legs.is_empty());
    }

    #[test]
    fn direct_mode_strike_idx_steps_above_below_atm() {
        // A 7-strike chain (index 0..=6) with ATM at index 3.
        let len = 7usize;
        let atm = 3usize;
        // Strictly above / below: `strike_count` steps off ATM.
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "above", 1, true), 4);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "above", 3, true), 6);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "below", 1, false), 2);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "below", 3, false), 0);
        // Including-ATM modes count the ATM leg as the first step.
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "above_atm", 1, true), 3);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "above_atm", 3, true), 5);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "below_atm", 1, false), 3);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "below_atm", 3, false), 1);
        // Two-sided modes send CE up and PE down.
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "both_atm", 3, true), 6);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "both_atm", 3, false), 0);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "both_atm_inc", 3, true), 5);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "both_atm_inc", 3, false), 1);
        // ATM-only ignores the step; edges clamp; count <= 0 acts as one step.
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "atm", 5, true), 3);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "above", 99, true), 6);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "below", 99, false), 0);
        assert_eq!(RealtimeState::direct_mode_strike_idx(len, atm, "above", 0, true), 4);
    }

    #[test]
    fn multi_strike_ladder_counts_including_atm_as_an_extra_strike() {
        // "Number of Strikes" fires the whole ladder at once. "Including ATM"
        // modes add the ATM leg on top of the count (Above incl. ATM + 1 = ATM
        // and one above = 2 legs); the strict Above / Below modes fire exactly
        // the count. A 9-strike chain (index 0..=8) with ATM at index 4.
        let len = 9usize;
        let atm = 4usize;
        let including = |mode: &str| {
            mode.eq_ignore_ascii_case("above_atm")
                || mode.eq_ignore_ascii_case("below_atm")
                || mode.eq_ignore_ascii_case("both_atm_inc")
                || mode.eq_ignore_ascii_case("atm")
        };
        let want = |mode: &str, n: usize| n + if including(mode) { 1 } else { 0 };
        let walk = |mode: &str, n: usize| -> Vec<usize> {
            RealtimeState::green_walk_order(len, atm, mode)
                .into_iter()
                .take(want(mode, n))
                .collect()
        };
        let direct = |mode: &str, n: i64, is_ce: bool| -> Vec<usize> {
            let mut out: Vec<usize> = Vec::new();
            for j in 1..=want(mode, n as usize) as i64 {
                let i = RealtimeState::direct_mode_strike_idx(len, atm, mode, j, is_ce);
                if !out.contains(&i) {
                    out.push(i);
                }
            }
            out
        };
        // Above including ATM, 1 strike -> ATM and one above.
        assert_eq!(walk("above_atm", 1), vec![4, 5]);
        assert_eq!(direct("above_atm", 1, true), vec![4, 5]);
        // Above including ATM, 3 strikes -> ATM + three above.
        assert_eq!(walk("above_atm", 3), vec![4, 5, 6, 7]);
        assert_eq!(direct("above_atm", 3, true), vec![4, 5, 6, 7]);
        // Strictly above, 3 -> exactly three, no ATM.
        assert_eq!(walk("above", 3), vec![5, 6, 7]);
        assert_eq!(direct("above", 3, true), vec![5, 6, 7]);
        // Below including ATM, 1 -> ATM and one below.
        assert_eq!(walk("below_atm", 1), vec![4, 3]);
        assert_eq!(direct("below_atm", 1, false), vec![4, 3]);
        // Strictly below, 3 -> exactly three.
        assert_eq!(walk("below", 3), vec![3, 2, 1]);
        assert_eq!(direct("below", 3, false), vec![3, 2, 1]);
    }

    #[test]
    fn paper2_keeps_only_indices_and_option_chain_commodities() {
        // Paper Trade 2 trades indices + option-chain commodities only: the Top
        // Movers stock scan, the NIFTY trend-follow engine, the F&O-stock picks
        // and the NIFTY BB%b (Pane) are all removed, and futures-only
        // commodities are dropped so a stale save/import cannot arm them.
        let _c = crate::market::CommodityFixtureGuard::install();
        let mut s = Settings::default();
        s.nifty_trend_on = true;
        s.nifty_trend_pct_on = true;
        s.nifty_trend_conf_inds = vec!["bbpctsl".into()];
        s.nifty_net_strict = true;
        s.nifty_all_agree_strict = true;
        s.bbpct_pane_on = true;
        s.bbpct_zone_on = true;
        s.bbpct_trend_on = true;
        s.bbpct_combo_on = true;
        s.movers_gainers = 7;
        s.movers_losers = 7;
        s.movers_indices = vec![13];
        s.movers_index_legs = vec![MoversIndexLeg { security_id: 13, side: "CE".into() }];
        // 500001 (GOLD) lists options; 500010 (SILVERM) is futures-only; an
        // unknown id (master not warm) must be KEPT, not silently wiped.
        s.commodity_list = vec![500001, 500010, 9_000_001];
        s.commodity_legs = vec![
            MoversIndexLeg { security_id: 500001, side: "CE".into() },
            MoversIndexLeg { security_id: 500010, side: "PE".into() },
        ];
        sanitize_indices_commodities(&mut s);
        // The NIFTY trend-follow engine + BB%b (Pane) are removed entirely.
        assert!(!s.nifty_trend_on);
        assert!(!s.nifty_trend_pct_on);
        assert!(s.nifty_trend_conf_inds.is_empty());
        assert!(!s.nifty_net_strict);
        assert!(!s.nifty_all_agree_strict);
        assert!(!s.bbpct_pane_on);
        assert!(!s.bbpct_zone_on);
        assert!(!s.bbpct_trend_on);
        assert!(!s.bbpct_combo_on);
        // The stock gainer/loser scan is removed; operator index picks stay.
        assert_eq!(s.movers_gainers, 0);
        assert_eq!(s.movers_losers, 0);
        assert_eq!(s.movers_indices, vec![13]);
        // Paper 2 now exposes the leg dropdown: the operator's chosen CE/PE leg
        // for a kept index survives, and is the contract that trades.
        assert_eq!(s.movers_index_legs.len(), 1, "paper 2 keeps the index leg");
        assert_eq!(s.movers_index_legs[0].security_id, 13);
        assert_eq!(s.movers_index_legs[0].side, "CE");
        // The futures-only commodity is dropped; the option-chain commodity
        // survives, and an unknown id is kept because the scrip master may
        // simply not be warm yet. The leg for the kept commodity survives too,
        // while the dropped commodity's leg is removed.
        assert_eq!(s.commodity_list, vec![500001, 9_000_001]);
        assert_eq!(s.commodity_legs.len(), 1, "paper 2 keeps the commodity leg");
        assert_eq!(s.commodity_legs[0].security_id, 500001);
        assert_eq!(s.commodity_legs[0].side, "CE");
    }

    #[tokio::test]
    async fn commodity_scanner_requires_explicit_adds() {
        // Switching the MCX commodity scanner ON must NOT auto-pick the whole
        // commodity universe: only the operator's explicitly added commodities
        // resolve to targets (and therefore picks). An empty list arms nothing.
        let market = crate::market::MarketState::new();
        let dhan = crate::broker::DhanState::new(market);
        let _c = crate::market::CommodityFixtureGuard::install();
        let rt = RealtimeState::new_paper(dhan);
        let mut s = Settings::default();
        s.commodity_on = true;
        // A bullish filter so the CE side is allowed to build without NIFTY.
        s.filters.insert("BullSlEma5".into(), true);
        let has = |out: &[Strategy], key: &str| out.iter().any(|t| t.id == key);
        let gold_ce = "scan:500001:CE"; // GOLD (MCX_COMM, lists options)

        // Empty list: no commodity is invented, so nothing runs at all.
        s.commodity_list.clear();
        let out = rt.scanner_targets(&s);
        assert!(!has(&out, gold_ce), "an empty commodity list must not arm any commodity");
        assert!(out.is_empty(), "no other scanner is on here, so nothing runs");

        // Explicitly added: the commodity resolves to its target.
        s.commodity_list = vec![500001];
        let out = rt.scanner_targets(&s);
        assert!(has(&out, gold_ce), "an explicitly added commodity must run");

        // A stale / unknown id arms nothing either.
        s.commodity_list = vec![999_999];
        let out = rt.scanner_targets(&s);
        assert!(!has(&out, gold_ce));
    }

