    #[tokio::test]
    async fn entry_timing_marker_is_consumed_by_the_origin_scan_id() {
        // Regression: a frozen Top-Movers leg executes as `pick:<sid>:<side>`
        // while the scan stamped `scan:<sid>:<side>`. Consuming by the origin
        // scan id must still yield the row, otherwise the ENTRY TIMING
        // DIAGNOSTICS section stays empty even though fills happened.
        let market = crate::market::MarketState::new();
        let dhan = crate::broker::DhanState::new(market);
        let rt = RealtimeState::new_paper(dhan);
        rt.et_pending
            .lock()
            .unwrap()
            .insert("scan:7:CE".to_string(), (111_i64, 0_i64));
        assert_eq!(
            rt.take_entry_timing("pick:7:CE", Some("scan:7:CE")),
            Some((111, 0)),
            "the scan id resolves the frozen leg's pending stamp"
        );
        // Direct/manual entries carry no origin id: the leg id is the key.
        rt.et_pending
            .lock()
            .unwrap()
            .insert("manual:1".to_string(), (222_i64, 3_i64));
        assert_eq!(rt.take_entry_timing("manual:1", None), Some((222, 3)));
        assert_eq!(rt.take_entry_timing("absent", None), None);
        let pending = rt.et_pending.lock().unwrap();
        assert!(pending.is_empty(), "every consumed / absent key is gone");
    }

