    #[tokio::test]
    async fn movers_legs_follow_the_committed_nifty_direction() {
        // While NIFTY Trend Following is ON, the committed side owns the Top
        // Movers stock legs: bullish arms only the gainers (CE), bearish only the
        // losers (PE). This stops a Top Loser PE entering during a bullish NIFTY
        // trend (and a Top Gainer CE during a bearish one).
        let market = crate::market::MarketState::new();
        let dhan = crate::broker::DhanState::new(market);
        let rt = RealtimeState::new_paper(dhan);
        let gainer = 13061; // 360ONE (NSE_EQ EQUITY)
        let loser = 21614; // ABCAPITAL (NSE_EQ EQUITY)
        if let Ok(mut g) = rt.movers_cache.lock() {
            *g = (
                now_ms(),
                json!({ "gainers": [{"securityId": gainer, "last": 100.0}], "losers": [{"securityId": loser, "last": 100.0}] }),
            );
        }
        let mut s = Settings::default();
        s.movers_on = true;
        s.nifty_trend_on = true;
        s.filters.insert("BullSlTrend".into(), true);
        s.filters.insert("BearSlTrend".into(), true);
        let ce = format!("scan:{}:CE", gainer);
        let pe = format!("scan:{}:PE", loser);
        let has = |out: &[Strategy], key: &str| out.iter().any(|t| t.id == key);
        let both = |out: &[Strategy]| has(out, &ce) && has(out, &pe);

        // Bullish NIFTY -> Top Gainer CE only.
        rt.nifty_dir.store(1, Ordering::Relaxed);
        let out = rt.scanner_targets(&s);
        assert!(has(&out, &ce) && !has(&out, &pe), "bullish NIFTY arms the Top Gainer CE leg only");

        // Bearish NIFTY -> Top Loser PE only.
        rt.nifty_dir.store(-1, Ordering::Relaxed);
        let out = rt.scanner_targets(&s);
        assert!(has(&out, &pe) && !has(&out, &ce), "bearish NIFTY arms the Top Loser PE leg only");

        // No committed direction -> no movers leg (never guess a side).
        rt.nifty_dir.store(0, Ordering::Relaxed);
        assert!(rt.scanner_targets(&s).is_empty(), "neutral NIFTY arms no movers leg");

        // The strict gates apply to the movers legs too.
        rt.nifty_dir.store(1, Ordering::Relaxed);
        s.nifty_net_strict = true;
        rt.nifty_raw_net.store(-1, Ordering::Relaxed);
        assert!(!has(&rt.scanner_targets(&s), &ce), "net-strict gate blocks the CE leg on a bearish net");
        rt.nifty_raw_net.store(1, Ordering::Relaxed);
        assert!(has(&rt.scanner_targets(&s), &ce), "net-strict gate allows the CE leg on a bullish net");
        s.nifty_net_strict = false;
        s.nifty_all_agree_strict = true;
        rt.nifty_agree.store(0, Ordering::Relaxed);
        assert!(!has(&rt.scanner_targets(&s), &ce), "all-agree gate blocks a mixed read");
        s.nifty_all_agree_strict = false;

        // Master OFF: the Top Movers selection arms both sides again.
        s.nifty_trend_on = false;
        rt.nifty_dir.store(0, Ordering::Relaxed);
        let out = rt.scanner_targets(&s);
        assert!(both(&out), "with NIFTY Trend Following off both selected legs build");

        // Selection still narrows the universe within the allowed side.
        s.nifty_trend_on = true;
        rt.nifty_dir.store(1, Ordering::Relaxed);
        if let Ok(mut g) = rt.movers_cache.lock() {
            *g = (now_ms(), json!({ "gainers": [], "losers": [{"securityId": loser, "last": 100.0}] }));
        }
        assert!(rt.scanner_targets(&s).is_empty(), "bullish NIFTY + losers-only arms nothing");
        if let Ok(mut g) = rt.movers_cache.lock() {
            *g = (now_ms(), json!({ "gainers": [{"securityId": gainer, "last": 100.0}], "losers": [] }));
        }
        let out = rt.scanner_targets(&s);
        assert!(has(&out, &ce) && !has(&out, &pe), "bullish NIFTY + gainers-only runs CE only");
    }

    #[tokio::test]
    async fn premium_only_pins_the_index_trend_leg_to_its_committed_side() {
        // Premium-chart-only + Indices Trend Following: the committed trend side
        // strictly owns the leg - bullish arms ONLY the CE, bearish ONLY the PE,
        // and a neutral / uncommitted read arms nothing. The opposite side is
        // never built, so a reversal cannot leave a losing opposite leg open.
        let rt = RealtimeState::new_paper2(crate::broker::DhanState::new(crate::market::MarketState::new()));
        let sid = 13; // NIFTY 50 (IDX_I INDEX)
        let ce = format!("scan:{}:CE", sid);
        let pe = format!("scan:{}:PE", sid);
        let has = |out: &[Strategy], key: &str| out.iter().any(|t| t.id == key);
        let mut s = Settings::default();
        s.premium_only = true;
        s.index_trend_on = true;
        s.movers_indices = vec![sid];
        s.filters.insert("BullIncUp".into(), true);

        if let Ok(mut g) = rt.index_trend_picks.lock() {
            *g = (now_ms(), json!([{ "securityId": sid, "side": "CE" }]));
        }
        let out = rt.scanner_targets(&s);
        assert!(has(&out, &ce), "bullish trend must arm the CE leg");
        assert!(!has(&out, &pe), "bullish trend must never arm the PE leg");

        if let Ok(mut g) = rt.index_trend_picks.lock() {
            *g = (now_ms(), json!([{ "securityId": sid, "side": "PE" }]));
        }
        let out = rt.scanner_targets(&s);
        assert!(has(&out, &pe), "bearish trend must arm the PE leg");
        assert!(!has(&out, &ce), "bearish trend must never arm the CE leg");

        if let Ok(mut g) = rt.index_trend_picks.lock() {
            *g = (now_ms(), json!([]));
        }
        assert!(rt.scanner_targets(&s).is_empty(), "neutral trend arms nothing (never guesses a side)");

        // Outside premium mode the same neutral read is not pinned and both legs
        // build for a plain (non-trend-owned) index universe - regression guard.
        s.premium_only = false;
        s.index_trend_on = false;
        s.movers_on = true;
        if let Ok(mut g) = rt.movers_cache.lock() {
            *g = (now_ms(), json!({ "gainers": [], "losers": [] }));
        }
        let out = rt.scanner_targets(&s);
        assert!(has(&out, &ce) && has(&out, &pe), "without premium mode the plain index builds both legs");
    }

