    #[test]
    fn concrete_option_contracts_recheck_their_own_premium_chart() {
        // A resolved fill leg names the contract itself, so the fill-time
        // premium re-check must read that contract's chart instead of trying to
        // resolve the contract symbol as an underlying (which has no expiry
        // bucket and blocked every premium-mode fill).
        let leg = Strategy {
            instrument: "OPTSTK".into(),
            exchange_segment: "NSE_FNO".into(),
            trading_symbol: "RELIANCE-Oct2026-2900-CE".into(),
            ..Default::default()
        };
        assert!(is_concrete_option_contract(&leg));
        // The underlying still has to go through the resolver.
        let underlying = Strategy {
            instrument: "EQUITY".into(),
            exchange_segment: "NSE_EQ".into(),
            trading_symbol: "RELIANCE".into(),
            ..Default::default()
        };
        assert!(!is_concrete_option_contract(&underlying));
        // Futures / non-option F&O legs are not concrete option contracts.
        let fut = Strategy {
            instrument: "FUTSTK".into(),
            exchange_segment: "NSE_FNO".into(),
            trading_symbol: "RELIANCE-Oct2026-FUT".into(),
            ..Default::default()
        };
        assert!(!is_concrete_option_contract(&fut));
    }

    #[test]
    fn paper_charges_are_side_aware_and_positive() {
        // A long and its mirrored short must pay the same statutory total: the
        // sell leg carries STT and the buy leg carries stamp, whichever way the
        // trade is expressed.
        let long = compute_charges_for_trade(100.0, 120.0, 50.0, "BUY", "OPTIDX", "NIFTY 24000 CE", 1000.0).unwrap();
        let short = compute_charges_for_trade(120.0, 100.0, 50.0, "SELL", "OPTIDX", "NIFTY 24000 CE", -1000.0).unwrap();
        assert!(long.total > 0.0, "charges must be positive");
        assert_eq!(long.segment, "options");
        assert!((long.total - short.total).abs() < 0.01, "long/short charges should match: {} vs {}", long.total, short.total);
        // net = gross - total round-trip charges.
        assert!((long.net - (long.gross - long.total)).abs() < 0.01);
    }

    #[test]
    fn net_tp_arms_only_after_the_rupee_floor_and_gives_back_25_pct() {
        // Below the floor: never armed, even if the profit is falling.
        assert_eq!(net_tp_floor(499.0, 500.0, 0.0), None);
        // Peak crossed the floor: 25% give-back by default.
        assert_eq!(net_tp_floor(4000.0, 500.0, 0.0), Some(3000.0));
        // A custom give-back is honoured.
        assert_eq!(net_tp_floor(4000.0, 500.0, 10.0), Some(3600.0));
        // The floor is clamped to the minimum, so a small peak never exits below it.
        assert_eq!(net_tp_floor(600.0, 500.0, 25.0), Some(500.0));
        // Nonsense give-back values fall back to 25%.
        assert_eq!(net_tp_floor(4000.0, 500.0, 150.0), Some(3000.0));
    }

    #[test]
    fn net_tp_hit_triggers_only_on_a_drop_through_the_floor() {
        let floor = net_tp_floor(4000.0, 500.0, 0.0).unwrap();
        let exits = |net_now: f64| net_now < floor;
        assert!(!exits(3001.0), "still above the 25% give-back floor");
        assert!(!exits(3500.0), "a shallow dip must hold");
        assert!(exits(2999.0), "a break below the floor must exit");
    }

    #[test]
    fn paper_charge_segments_and_rounding_match_dhan() {
        // Instrument / symbol drives the segment, exactly like Python segmentFor().
        assert_eq!(charges_segment("OPTIDX", "NIFTY 24000 CE"), "options");
        assert_eq!(charges_segment("FUTSTK", "RELIANCE FUT"), "futures");
        assert_eq!(charges_segment("", "NIFTY 24000 PE"), "options");
        assert_eq!(charges_segment("EQUITY", "RELIANCE"), "delivery");
        // Delivery: no brokerage, STT 0.1% on BOTH legs.
        let buy = side_charges("delivery", true, 100_000.0);
        let sell = side_charges("delivery", false, 100_000.0);
        assert_eq!(buy.brokerage, 0.0);
        assert_eq!(buy.stt, 100.0);
        assert_eq!(sell.stt, 100.0);
        // STT rounds to the nearest rupee (0.0625% of 1000 = 0.625 -> 1).
        assert_eq!(side_charges("options", false, 1000.0).stt, 1.0);
        // Stamp rounds to the nearest rupee (0.015% of 10000 = 1.5 -> 2).
        assert_eq!(side_charges("delivery", true, 10_000.0).stamp, 2.0);
        // Options brokerage is a flat Rs 20, so a bigger turnover bends the curve.
        let one = side_charges("options", true, 1_000_000.0);
        let two = side_charges("options", true, 2_000_000.0);
        assert!(two.total < 2.0 * one.total, "brokerage cap should bend the curve: {} -> {}", one.total, two.total);
    }

    #[test]
    fn paper_fill_price_is_adverse_and_bounded() {
        // BUY fills above the mark, SELL below it.
        assert!(paper_fill_price(100.0, true, 50.0) > 100.0);
        assert!(paper_fill_price(100.0, false, 50.0) < 100.0);
        // Zero slippage is an exact fill; a SELL can never fill below zero.
        assert_eq!(paper_fill_price(100.0, true, 0.0), 100.0);
        assert!(paper_fill_price(1.0, false, 100_000.0) >= 0.05);
        // Rejection PRNG stays in [0, 1) for many seeds.
        for i in 0..1000 {
            let r = paper_rand01(paper_seed(i));
            assert!((0.0..1.0).contains(&r), "rand out of range: {r}");
        }
    }

    #[test]
    fn paper_spread_crosses_half_per_side_and_stacks_with_slippage() {
        // OFF = no spread, identical to a slippage-only fill.
        let off = PaperSpread::default();
        assert_eq!(off.full(100.0), 0.0);
        assert_eq!(off.fill(100.0, true, 0.0), 100.0);
        assert_eq!(off.fill(100.0, false, 0.0), 100.0);

        // Rs and % are summed into one full spread; each side pays half.
        let s = PaperSpread { on: true, rs: 1.0, pct: 1.0 };
        // 1 rupee + 1% of 100 = 2 rupees full, 1 rupee half.
        assert!((s.full(100.0) - 2.0).abs() < 1e-9);
        assert!((s.fill(100.0, true, 0.0) - 101.0).abs() < 1e-9);
        assert!((s.fill(100.0, false, 0.0) - 99.0).abs() < 1e-9);

        // Slippage stacks on top of the spread-crossed price.
        let slipped = s.fill(100.0, true, 100.0);
        // 101 crossed, then +1% slippage of 101 = 102.01.
        assert!((slipped - 102.01).abs() < 1e-9);

        // A SELL can never be pushed below the 0.05 floor, even with a huge spread.
        let huge = PaperSpread { on: true, rs: 1_000_000.0, pct: 0.0 };
        assert!(huge.fill(1.0, false, 0.0) >= 0.05);
    }

    #[test]
    fn paper_exec_fill_matches_slippage_only_when_spread_off() {
        let mut s = Settings::default();
        s.paper_slippage_bps = 5.0;
        assert!((paper_exec_fill(100.0, true, &s) - paper_fill_price(100.0, true, 5.0)).abs() < 1e-9);
        assert!((paper_exec_fill(100.0, false, &s) - paper_fill_price(100.0, false, 5.0)).abs() < 1e-9);
    }

    #[test]
    fn fno_limit_buy_price_is_marketable_and_above_entry() {
        // The F&O limit must always sit strictly above the market, so it can
        // never be placed behind/below the entry, and it fills like a market
        // order. Checked across cheap and expensive premiums.
        for px in [0.05, 1.0, 12.76, 100.0, 500.0, 2500.0] {
            let limit = fno_limit_buy_price(px);
            assert!(limit > px, "limit {limit} must be above entry {px}");
            // At least one tick of protection so the order is marketable.
            assert!(limit - px >= 0.049, "limit {limit} too close to entry {px}");
        }
    }

    #[test]
    fn settings_camel_case_roundtrip() {
        let mut s = Settings::default();
        s.option_side = "CE".into();
        s.brain_mode = "auto".into();
        s.all_in_one = true;
        s.filters.insert("BullIncUp".into(), true);
        // Selected Strategies section: manual / AI-pick controls must round-trip
        // with the exact camelCase keys the frontend sends.
        s.call_manual = false;
        s.ai_pick = true;
        s.ai_pick_n = 3;
        s.ai_pick_bull = true;
        s.ai_pick_bear = false;
        // Run-mode section: the frontend sends `filterMode` for the
        // Normal / Indicator-filters mode selector.
        s.filter_mode = true;
        // Scanner "remove" blacklist: the frontend posts `scannerExclude` (int
        // security ids removed from the Top Movers / NIFTY trend picks).
        s.scanner_exclude = vec![17818, 1234];
        // Anti-fake filter: master + thresholds must round-trip camelCase so a
        // generic settings save never drops them.
        s.anti_fake_on = true;
        s.anti_fake_bars = 3;
        s.anti_fake_atr_mult = 0.4;
        s.anti_fake_vol_mult = 0.6;
        s.anti_fake_adx_min = 22.0;
        s.anti_fake_chop_max = 55.0;
        s.anti_fake_cooldown_bars = 4;
        let v = serde_json::to_value(&s).unwrap();
        assert_eq!(v["optionSide"], json!("CE"));
        assert_eq!(v["brainMode"], json!("auto"));
        assert_eq!(v["allInOne"], json!(true));
        assert_eq!(v["filterMode"], json!(true));
        assert_eq!(v["filters"]["BullIncUp"], json!(true));
        assert_eq!(v["callManual"], json!(false));
        assert_eq!(v["aiPick"], json!(true));
        assert_eq!(v["aiPickN"], json!(3));
        assert_eq!(v["aiPickBull"], json!(true));
        assert_eq!(v["aiPickBear"], json!(false));
        assert_eq!(v["scannerExclude"], json!([17818, 1234]));
        assert_eq!(v["antiFakeOn"], json!(true));
        assert_eq!(v["antiFakeBars"], json!(3));
        assert_eq!(v["antiFakeAtrMult"], json!(0.4));
        assert_eq!(v["antiFakeVolMult"], json!(0.6));
        assert_eq!(v["antiFakeAdxMin"], json!(22.0));
        assert_eq!(v["antiFakeChopMax"], json!(55.0));
        assert_eq!(v["antiFakeCooldownBars"], json!(4));
        let back: Settings = serde_json::from_value(v).unwrap();
        assert_eq!(back.option_side, "CE");
        assert!(!back.call_manual && back.ai_pick && back.ai_pick_n == 3);
        assert!(back.filter_mode);
        assert_eq!(back.scanner_exclude, vec![17818, 1234]);
        assert!(back.anti_fake_on && back.anti_fake_bars == 3);
        assert_eq!(back.anti_fake_cooldown_bars, 4);
    }

    #[test]
    fn unknown_filter_blocks_fail_closed() {
        let c = ramp(60, 100.0, 1.0);
        assert_eq!(filter_eval("BullSomeUnimplementedThing", &c, 0), None);
        let mut s = Settings::default();
        s.filters.insert("BullSomeUnimplementedThing".into(), true);
        // An armed filter that cannot be computed no longer counts as a pass, so
        // it blocks instead of firing against the chart.
        assert!(!filter_gate(&s, &bull_strategy(), &c, 0));
    }

    #[test]
    fn entry_primary_filter_gates_before_the_secondary_confirmation() {
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        // Secondary confirmation: one bull filter that PASSES on a rising ramp.
        s.filters.insert("BullIncUp".into(), true);
        // PRIMARY switch ON but no primary key yet -> behaves exactly as before.
        s.entry_primary_on = true;
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "no primary key => old behaviour");

        // A primary bull condition that PASSES plus the passing secondary filter.
        s.entry_primary_filters = vec!["BullMeetEma9_21".into()];
        let (ok, f) = filter_gate_facts(&s, &bull_strategy(), &c, 0);
        assert!(ok, "primary met + secondary met => entry allowed");
        assert_eq!((f.primary_total, f.primary_pass), (1, 1));
        assert!(!f.primary_blocked);

        // Side-scoped: a BEAR-only primary list does not gate a BULL leg, so the
        // bull leg keeps the ordinary secondary rule and still trades.
        s.entry_primary_filters = vec!["BearIncDown".into()];
        let (ok, f) = filter_gate_facts(&s, &bull_strategy(), &c, 0);
        assert!(ok, "no bull-side primary key => not primary-gated on the bull leg");
        assert_eq!((f.primary_total, f.primary_pass), (0, 0));
        assert!(!f.primary_blocked);
        // A bull-side primary that cannot compute fails closed.
        s.entry_primary_filters = vec!["BullSomeUnimplementedThing".into()];
        let (ok, f) = filter_gate_facts(&s, &bull_strategy(), &c, 0);
        assert!(!ok, "uncomputable primary must fail closed");
        assert_eq!((f.primary_total, f.primary_pass), (1, 0));
        assert!(f.primary_blocked);

        // Primary alone (no secondary filter) is a complete entry rule.
        let mut p = Settings::default();
        p.entry_primary_on = true;
        p.entry_primary_filters = vec!["BullIncUp".into()];
        assert!(filter_gate(&p, &bull_strategy(), &c, 0), "primary-only rule allows when met");
        p.entry_primary_filters = vec!["BullSomeUnimplementedThing".into()];
        assert!(!filter_gate(&p, &bull_strategy(), &c, 0), "primary-only rule blocks when unmet");

        // Switch OFF ignores the list entirely.
        p.entry_primary_on = false;
        p.entry_primary_filters = vec!["BullSomeUnimplementedThing".into()];
        // Synthetic legs still need a same-side rule, so they stay blocked, but a
        // normal strategy with no filters keeps the old permissive behaviour.
        assert!(filter_gate(&p, &bull_strategy(), &c, 0), "OFF => primary list ignored");
    }

    #[test]
    fn entry_primary_keys_are_scoped_to_their_own_side() {
        let mut s = Settings::default();
        s.entry_primary_on = true;
        s.entry_primary_filters = vec!["BullIncUp".into(), "BearIncDown".into()];
        let bull = primary_keys_for_side(&s, true);
        let bear = primary_keys_for_side(&s, false);
        assert_eq!(bull, vec![&"BullIncUp".to_string()]);
        assert_eq!(bear, vec![&"BearIncDown".to_string()]);
        // Switch OFF => no primary keys at all.
        s.entry_primary_on = false;
        assert!(primary_keys_for_side(&s, true).is_empty());
    }

    #[test]
    fn strict_and_gate_blocks_on_failure() {
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        s.filters.insert("BullIncUp".into(), true);
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "rising close passes BullIncUp");
        // The armed bull filter cannot gate a bearish strategy: there is no
        // same-side confirmation, so the entry is blocked.
        assert!(!filter_gate(&s, &bear_strategy(), &c, 0), "no same-side filter => blocked");
        s.filters.insert("BearIncDown".into(), true);
        assert!(!filter_gate(&s, &bear_strategy(), &c, 0), "opposing down filter fails");
    }

    #[test]
    fn straight_line_ema_and_all_supertrend_crossovers_are_wired() {
        let c = wave(400, 100.0, 0.5);
        // Every held (Meet) row already existed; the event crosses added to the
        // top section must compute on the same series.
        let bull = filter_eval("BullSlema1_5", &c, 0);
        let bear = filter_eval("BearSlema1_5", &c, 0);
        assert!(bull.is_some(), "BullSlema cross must compute");
        assert!(bear.is_some(), "BearSlema cross must compute");
        // A cross filter is an EVENT: no cross at this bar means both sides are
        // false, and the two sides can never both fire on the same bar.
        assert!(!(bull == Some(true) && bear == Some(true)));
        // Walk the series until a cross actually prints, then prove it is a
        // one-bar event (the same side cannot also be true on the older bar).
        let cross_bar = (1..c.len()).find(|&o| filter_eval("BullSlema1_5", &c, o) == Some(true));
        let cross_bar = cross_bar.expect("a zigzag series must print at least one bullish cross");
        assert_eq!(filter_eval("BearSlema1_5", &c, cross_bar), Some(false));
        assert_eq!(
            filter_eval("BullSlema1_5", &c, cross_bar + 1),
            Some(false),
            "a cross is a one-bar event, not a latched level"
        );
        for k in ["BullSt10_1_2", "BullSt10_1_3", "BullSt10_2_3"] {
            assert!(filter_eval(k, &c, 0).is_some(), "{k} must compute");
        }
        assert!(is_cross_filter_key("BullSlema9_21"));
        assert!(is_cross_filter_key("BearSt10_1_3"));
        assert!(is_cross_filter_key("BullEma9_21"));
        assert!(!is_cross_filter_key("BullMeetSlema9_21"));
        assert!(!is_cross_filter_key("BullMeetEma9_21"));
        assert!(!is_cross_filter_key("BullSt10Meet"));
    }

    #[test]
    fn fill_grace_accepts_a_cross_that_printed_on_the_previous_bar() {
        // 60 flat bars (close == EMA9, so no bullish side), one bar that jumps
        // above EMA9 (the cross), then the newest bar falls back below it. At
        // offset 0 the cross is no longer fresh; at offset 1 it is - exactly the
        // bar rollover that used to reject a legitimate fill.
        let mut closes: Vec<f64> = vec![100.0; 60];
        closes.push(120.0);
        closes.push(100.0);
        let c: Vec<Candle> = closes
            .iter()
            .enumerate()
            .map(|(i, v)| Candle {
                time: i as i64 * 300_000,
                open: *v,
                high: *v,
                low: *v,
                close: *v,
                volume: 1.0,
            })
            .collect();
        let mut s = Settings::default();
        s.filters.insert("BullCrossUp".into(), true);
        assert!(!filter_gate(&s, &bull_strategy(), &c, 0), "no fresh cross on the newest bar");
        {
            let _g = CrossFillGraceGuard::enter();
            assert!(
                filter_gate(&s, &bull_strategy(), &c, 0),
                "fill grace accepts the cross that printed on the previous bar"
            );
        }
        assert!(!filter_gate(&s, &bull_strategy(), &c, 0), "grace must not leak into the scan");
    }

    #[test]
    fn synthetic_pick_without_entry_rule_is_blocked() {
        // A synthetic Top-Movers / pick leg carries no entry conditions of its
        // own; its ticked same-side filters ARE the whole entry rule. With none
        // ticked there is no rule at all, so the leg must not fire - otherwise it
        // re-enters on every scan for as long as the scan list keeps it alive
        // (the naked Top-Movers churn).
        let c = ramp(60, 100.0, 1.0);
        let s = Settings::default();
        let mut synth = bull_strategy();
        synth.synthetic = true;
        assert!(
            !filter_gate(&s, &synth, &c, 0),
            "synthetic leg with no same-side filter has no entry rule => blocked"
        );
        // A normal strategy keeps the old naked-run behaviour when no filter is
        // ticked anywhere.
        assert!(
            filter_gate(&s, &bull_strategy(), &c, 0),
            "normal strategy with no filters configured still runs naked"
        );
    }

    #[test]
    fn require_condition_blocks_when_no_filter_rule() {
        // "Require condition" ON: a leg with no same-side filter has no entry
        // rule, so it must not fire (empty = not met) - for normal strategies too,
        // and for every tab (the flag also overrides the Paper Trade 3 bypass).
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        s.require_condition = true;
        assert!(
            !filter_gate(&s, &bull_strategy(), &c, 0),
            "require-condition blocks an empty entry rule"
        );
        // With the flag off the normal naked-run behaviour is kept.
        s.require_condition = false;
        assert!(filter_gate(&s, &bull_strategy(), &c, 0));
        // A wrong-side-only filter leaves no same-side rule => still blocked.
        let mut wrong_side = Settings::default();
        wrong_side.require_condition = true;
        wrong_side.filters.insert("BearIncDown".into(), true);
        assert!(
            !filter_gate(&wrong_side, &bull_strategy(), &c, 0),
            "wrong-side-only filter has no same-side rule => blocked"
        );
    }

    #[test]
    fn visible_straight_line_filters_gate_the_engine() {
        // A Vsl* key is a first-class entry gate in `filter_gate` - the exact
        // same gate the realtime engine tab and the paper-trade engine share.
        // The Visible rows now report the same bullish/bearish TREND as the
        // Straight Line Indicators rows, so the two gates must be identical.
        let up = ramp(400, 100.0, 0.6);
        let down = ramp(400, 340.0, -0.6);
        let tokens = [
            "ElliottWave", "SupplyDemand", "PriceAction", "ZigZag", "ComboMaster",
            "PaneConsensus", "AutoTrendline", "Pitchfork", "TrendProjection",
            "GannFan", "FibFan", "Srema", "Consensus",
        ];
        let bull = bull_strategy();
        let mut saw_pass = false;
        let mut saw_block = false;
        for tok in tokens {
            let mut vsl = Settings::default();
            vsl.filters.insert(format!("BullVsl{tok}"), true);
            let mut sl = Settings::default();
            sl.filters.insert(format!("BullSl{tok}"), true);
            for candles in [&up, &down] {
                let expect = filter_gate(&vsl, &bull, candles, 0);
                assert_eq!(
                    expect,
                    filter_gate(&sl, &bull, candles, 0),
                    "BullVsl{tok} must gate exactly like BullSl{tok}"
                );
                if expect {
                    saw_pass = true;
                } else {
                    saw_block = true;
                }
            }
        }
        assert!(saw_pass, "at least one line must clear the gate");
        assert!(saw_block, "at least one line must block the gate");
    }

    #[test]
    fn premium_chart_only_gates_every_side_on_bull_filters() {
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        s.filters.insert("BullIncUp".into(), true);
        // The operator also has a bearish filter ticked (e.g. for the PE side).
        s.filters.insert("BearIncDown".into(), true);
        // Normally a bearish strategy is gated by its own bearish filters; the
        // failing bear filter plus the met opposite (bull) filter vetoes.
        assert!(!filter_gate(&s, &bear_strategy(), &c, 0), "bear side uses bear filters normally");
        // "Premium chart only (run + trade)": every leg is gated by the BULLISH
        // filter set (Top Gainer CE and Top Loser PE alike), so the rising ramp
        // passes on the PE side too and the ticked bearish filter has no function.
        s.premium_only = true;
        assert!(filter_gate(&s, &bear_strategy(), &c, 0), "premium chart uses bull filters on the PE side");
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "premium chart uses bull filters on the CE side");

        // The SAME mode also arms when the "Strategy should be run in:" F&O stocks
        // dropdown is pinned to the option-premium chart (engine switch unticked).
        let mut r = Settings::default();
        r.filters.insert("BullIncUp".into(), true);
        r.filters.insert("BearIncDown".into(), true);
        r.run_fno = "premium".into();
        assert!(premium_only_active(&r), "F&O run-in = premium activates premium-only");
        assert!(filter_gate(&r, &bear_strategy(), &c, 0), "F&O premium run gates the PE side on bull filters");
        // Indices/commodities run modes are untouched by this trigger.
        assert_eq!(run_mode_of(&bull_strategy(), &r), "premium");
    }

    #[test]
    fn premium_chart_uses_the_standard_indicator_filter_options() {
        // Premium mode only swaps the gate to the BULLISH filter set; every
        // ordinary indicator-filter option applies unchanged. With "All together
        // (strict AND)" on, BOTH ticked bull filters must pass on the premium
        // chart exactly as on spot - one met filter is NOT enough.
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        s.filters.insert("BullIncUp".into(), true); // passes on a rising ramp
        s.filters.insert("BullGapUp".into(), true); // fails (no gap on a smooth ramp)
        s.all_in_one = true; // strict AND
        // Spot chart: a strict-AND bull leg needs BOTH filters, so it blocks.
        assert!(
            !filter_gate(&s, &bull_strategy(), &c, 0),
            "strict AND blocks the spot leg when one bull filter fails"
        );
        // Premium chart: the SAME strict-AND rule holds on the bullish set, so the
        // CE and the PE premium leg both block - no separate OR trigger.
        s.premium_only = true;
        assert!(
            !filter_gate(&s, &bull_strategy(), &c, 0),
            "premium chart keeps strict AND on the CE leg"
        );
        assert!(
            !filter_gate(&s, &bear_strategy(), &c, 0),
            "premium chart keeps strict AND on the PE leg (bull filters)"
        );
        // With strict AND off, a single ticked bull filter is the premium set for
        // BOTH legs and fires them once it meets its condition.
        let mut one = Settings::default();
        one.filters.insert("BullIncUp".into(), true);
        one.premium_only = true;
        assert!(
            filter_gate(&one, &bull_strategy(), &c, 0),
            "premium chart fires the CE leg on the ticked bull filter"
        );
        assert!(
            filter_gate(&one, &bear_strategy(), &c, 0),
            "premium chart gates the PE leg on the same bull filter"
        );
    }

    #[test]
    fn premium_only_is_per_category_for_spot_vs_premium_routing() {
        // Paper Trade 2 runs Indices + Commodities on independent run-in routing:
        // pinning one category to the option-premium chart must gate IT with the
        // BULLISH filters only, while a category left on the spot chart keeps the
        // normal bull/bear gating (bull -> CE, bear -> PE).
        let c = ramp(60, 100.0, 1.0);
        let index_pe = Strategy {
            id: "idx".into(),
            name: "IDX".into(),
            category: "BEARISH".into(),
            side: "SELL".into(),
            exchange_segment: "IDX_I".into(),
            instrument: "INDEX".into(),
            ..Default::default()
        };
        let comm_pe = Strategy {
            id: "comm".into(),
            name: "COMM".into(),
            category: "BEARISH".into(),
            side: "SELL".into(),
            exchange_segment: "MCX_COMM".into(),
            instrument: "FUTCOM".into(),
            ..Default::default()
        };
        let mut s = Settings::default();
        s.filters.insert("BullIncUp".into(), true);
        s.filters.insert("BearIncDown".into(), true);
        s.run_index = "premium".into();
        s.run_comm = "spot".into();
        // Indices routed to the premium chart: the PE leg is gated by the BULLISH
        // filters only, so the rising ramp passes despite the bearish filter.
        assert_eq!(run_mode_of(&index_pe, &s), "premium");
        assert!(filter_gate(&s, &index_pe, &c, 0), "premium index PE uses bull filters");
        // Commodities left on spot: the PE leg keeps the bearish filter and blocks.
        assert_eq!(run_mode_of(&comm_pe, &s), "spot");
        assert!(!filter_gate(&s, &comm_pe, &c, 0), "spot commodity PE keeps bear filters");
        // Pinning commodities to premium too flips them to bullish-only.
        s.run_comm = "premium".into();
        assert_eq!(run_mode_of(&comm_pe, &s), "premium");
        assert!(filter_gate(&s, &comm_pe, &c, 0), "premium commodity PE uses bull filters");
        // The engine-wide switch turns premium gating on for every category at once.
        let mut o = Settings::default();
        o.filters.insert("BullIncUp".into(), true);
        o.filters.insert("BearIncDown".into(), true);
        o.premium_only = true;
        assert_eq!(run_mode_of(&index_pe, &o), "premium");
        assert!(filter_gate(&o, &index_pe, &c, 0));
        assert_eq!(run_mode_of(&comm_pe, &o), "premium");
        assert!(filter_gate(&o, &comm_pe, &c, 0));
    }

    #[test]
    fn all_in_one_toggles_strict_and_vs_majority() {
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        // On a rising ramp two of the three ticked bull filters pass, one fails.
        s.filters.insert("BullIncUp".into(), true);
        s.filters.insert("BullIncUpAll".into(), true);
        s.filters.insert("BullLtUp".into(), true);
        // Non-strict (default): a majority of the bull filters pass -> allowed.
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "majority clears the non-strict gate");
        // Strict AND: one of the three bull filters fails -> blocked.
        s.all_in_one = true;
        assert!(!filter_gate(&s, &bull_strategy(), &c, 0), "strict AND blocks when any filter fails");
    }

    #[test]
    fn filter_mode_uses_majority_and_combines_with_brain_auto() {
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        // On a rising ramp two of the three ticked bull filters pass, one fails.
        s.filters.insert("BullIncUp".into(), true);
        s.filters.insert("BullIncUpAll".into(), true);
        s.filters.insert("BullLtUp".into(), true);
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "non-filter majority clears");
        // Indicator-filters mode no longer forces strict AND: a majority still
        // clears the gate while the checkbox is off.
        s.filter_mode = true;
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "filter mode falls back to majority");
        // AI Brain AUTO layers on top: a threshold the majority score cannot
        // reach blocks the entry.
        s.brain_mode = "auto".into();
        s.brain_threshold = 90;
        assert!(!filter_gate(&s, &bull_strategy(), &c, 0), "brain threshold above majority score blocks");
        // A threshold the majority score clears allows the entry.
        s.brain_threshold = 50;
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "brain threshold below majority score allows");
        // The strict-AND checkbox alone re-imposes "every filter must pass".
        s.brain_mode = "off".into();
        s.all_in_one = true;
        assert!(!filter_gate(&s, &bull_strategy(), &c, 0), "strict AND blocks when any filter fails");
        // Every ticked filter passing => allowed even under strict AND.
        s.filters.clear();
        s.filters.insert("BullIncUp".into(), true);
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "single passing filter allowed");
    }

    #[test]
    fn arrow_filters_collapse_to_one_or_trigger() {
        let c = wave(400, 100.0, 0.0);
        let mut s = Settings::default();
        s.filter_mode = true;
        s.filters.insert("BullArrowZigZag".into(), true);
        s.filters.insert("BullArrowTrendCore".into(), true);
        // A bar where at least one of the two selected arrows prints.
        let off = (1..300)
            .find(|&o| {
                filter_eval("BullArrowZigZag", &c, o) == Some(true)
                    || filter_eval("BullArrowTrendCore", &c, o) == Some(true)
            })
            .expect("at least one arrow must fire on an oscillating series");
        // All arrow toggles collapse into ONE OR-ed condition, so strict AND with
        // only arrows passes when any single arrow fires (they would almost never
        // print on the same tick if each were counted separately).
        let (ok, f) = filter_gate_facts(&s, &bull_strategy(), &c, off);
        assert!(ok, "any fresh arrow clears the collapsed arrow trigger");
        assert_eq!(f.total, 1, "all enabled arrows collapse into one condition");
        // Ordinary filters stay separate and are combined with the arrow group.
        s.filters.insert("BullIncUp".into(), true);
        let (_, f2) = filter_gate_facts(&s, &bull_strategy(), &c, off);
        assert_eq!(f2.total, 2, "arrow group + one normal filter = two conditions");
    }

    #[test]
    fn brain_auto_only_uses_own_side_score() {
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        s.brain_mode = "auto".into();
        s.brain_threshold = 50;
        s.all_in_one = true;
        s.filters.insert("BullIncUp".into(), true);
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "own side passes the threshold");
        // Only a failing own-side filter remains, so the score drops below the
        // threshold and the entry is blocked. The opposite side is not consulted.
        s.all_in_one = false;
        s.filters.clear();
        s.filters.insert("BullIncDown".into(), true);
        s.filters.insert("BearPbrElderforce".into(), true);
        let (ok, f) = filter_gate_facts(&s, &bull_strategy(), &c, 0);
        assert!(!ok, "own-side score below threshold blocks even with a met opposite filter");
        assert_eq!(f.total, 1, "the bear filter is not part of the bull-side gate");
    }

    #[test]
    fn brain_auto_threshold() {
        let c = ramp(60, 100.0, 1.0);
        let mut s = Settings::default();
        s.brain_mode = "auto".into();
        s.brain_threshold = 50;
        s.filters.insert("BullIncUp".into(), true);
        s.filters.insert("BullEmaTrend9".into(), true);
        s.filters.insert("BullIncUpAll".into(), true);
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "all three pass => score 100");
        s.filters.clear();
        s.filters.insert("BullIncUp".into(), true);
        s.filters.insert("BearIncDown".into(), true);
        s.brain_threshold = 50;
        assert!(filter_gate(&s, &bull_strategy(), &c, 0), "bear filter is not counted on the bull side");
    }

