    #[test]
    fn closed_level_reads_last_closed_candle_and_ignores_forming_repaint() {
        let _g = ind_test_lock();
        // Clean monotonic series (no wobble) so every closed candle sits strictly
        // on one side of its indicators.
        let ramp = |n: usize, start: f64, step: f64| -> Vec<Candle> {
            (0..n)
                .map(|i| {
                    let c = start + step * i as f64;
                    Candle {
                        time: i as i64 * 300_000,
                        open: c - step * 0.5,
                        high: c + step.abs(),
                        low: c - step.abs(),
                        close: c,
                        volume: 1000.0,
                    }
                })
                .collect()
        };
        // Uptrend: every closed candle sits above its EMA, so "closed above"
        // holds and its opposite is false. This is a LEVEL read, not a one-bar
        // cross, so it stays true on every scan.
        let up = ramp(400, 100.0, 0.6);
        assert_eq!(filter_eval("BullClosedAboveEma5", &up, 0), Some(true));
        assert_eq!(filter_eval("BearClosedBelowEma5", &up, 0), Some(false));
        assert_eq!(filter_eval("BullClosedAboveVwap", &up, 0), Some(true));
        assert_eq!(filter_eval("BullClosedAboveSt10_2", &up, 0), Some(true));
        assert_eq!(filter_eval("BullClosedAboveBbMid", &up, 0), Some(true));
        assert_eq!(filter_eval("BullClosedAboveKijun", &up, 0), Some(true));

        // Downtrend flips the whole family.
        let down = ramp(400, 400.0, -0.6);
        assert_eq!(filter_eval("BullClosedAboveEma5", &down, 0), Some(false));
        assert_eq!(filter_eval("BearClosedBelowEma5", &down, 0), Some(true));
        assert_eq!(filter_eval("BearClosedBelowVwap", &down, 0), Some(true));

        // The live FORMING candle is ignored: a huge spike on the newest bar must
        // not change the verdict, because the family reads the last CLOSED bar.
        let mut spiked = down.clone();
        let last = spiked.len() - 1;
        spiked[last].close = 1_000_000.0;
        spiked[last].high = 1_000_100.0;
        assert_eq!(
            filter_eval("BearClosedBelowEma5", &spiked, 0),
            Some(true),
            "an intrabar spike on the forming candle must not flip a closed-bar level gate"
        );

        // Too little history (indicator not warm) fails closed with None.
        assert_eq!(filter_eval("BullClosedAboveEma300", &ramp(10, 100.0, 1.0), 0), None);
    }

