    #[test]
    fn margin_block_reason_blocks_only_when_required_exceeds_free() {
        // 500k budget, 100k locked by one running trade => 400k free.
        assert!(margin_block_reason(300_000.0, 500_000.0, 100_000.0, 1).is_none());
        // Exactly at the free amount is allowed (not strictly greater).
        assert!(margin_block_reason(400_000.0, 500_000.0, 100_000.0, 1).is_none());
        // A rupee over the free amount is blocked, and the reason names the lock.
        let reason = margin_block_reason(400_001.0, 500_000.0, 100_000.0, 1)
            .expect("over-budget entry must be blocked");
        assert!(reason.contains("trade blocked"));
        assert!(reason.contains("locked 100000"));
        // Fully locked budget blocks any positive requirement.
        assert!(margin_block_reason(1.0, 500_000.0, 500_000.0, 3).is_some());
        // A zero requirement never blocks (the "no budget configured" guard
        // lives in `margin_block_for_qty`, not in this pure reason helper).
        assert!(margin_block_reason(0.0, 0.0, 0.0, 0).is_none());
    }

    #[test]
    fn paper_margin_budget_counts_locked_margin_once() {
        // 500k wallet, 100k of open notional: free cash must subtract the lock
        // exactly once (400k), and the paper P&L still moves the wallet itself.
        let cap = 500_000.0;
        let closed: Vec<Value> = Vec::new();
        let positions = vec![json!({ "qty": 1000.0, "entry": 100.0 })];

        let wallet = paper_wallet_of(cap, &closed, false);
        assert!((wallet - 500_000.0).abs() < 1e-9);
        let free = paper_available_of(cap, &closed, &positions, false);
        assert!((free - 400_000.0).abs() < 1e-9);

        let (locked, count) = locked_margin_of(&positions);
        assert!((locked - 100_000.0).abs() < 1e-9);
        assert!((wallet - locked - 400_000.0).abs() < 1e-9);
        assert_eq!(count, 1);
    }

    #[test]
    fn paper_wallet_still_follows_realized_pnl() {
        // Paper tab P&L behaviour is unchanged: the wallet is the shared-margin
        // allotment (its only capital source now) plus realized P&L.
        let _guard = crate::shared_margin::TEST_ALLOT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        // Isolate the family: only paper2 is allotted, so its cap is exactly
        // the allotment (no proportional scaling from sibling tabs).
        crate::shared_margin::set_total_for_test("paper", 500_000.0);
        for id in ["paper", "paper3", "equitypaper"] {
            crate::shared_margin::clear_allot_for_test(id);
        }
        crate::shared_margin::set_allot_for_test("paper2", true, "rs", 0.0, 200_000.0);

        assert!((paper_base_of("paper2") - 200_000.0).abs() < 1e-9);

        let loss = vec![json!({ "pnl": -10_000.0 })];
        assert!((paper_wallet_of(paper_base_of("paper2"), &loss, false) - 190_000.0).abs() < 1e-9);
        let both = vec![json!({ "pnl": -10_000.0 }), json!({ "pnl": 15_000.0 })];
        assert!((paper_wallet_of(paper_base_of("paper2"), &both, false) - 205_000.0).abs() < 1e-9);
        assert!((paper_wallet_of(paper_base_of("paper2"), &[], false) - 200_000.0).abs() < 1e-9);

        // No allotment -> no capital (never a phantom fallback).
        crate::shared_margin::clear_allot_for_test("paper2");
        assert!((paper_base_of("paper2") - 0.0).abs() < 1e-9);
        crate::shared_margin::set_total_for_test("paper", 0.0);
    }

