    #[test]
    fn engine_chart_transform_is_gated_by_the_display_switch() {
        let src = vec![
            Candle { time: 1, open: 100.0, high: 110.0, low: 90.0, close: 100.0, volume: 1.0 },
            Candle { time: 2, open: 100.0, high: 130.0, low: 100.0, close: 120.0, volume: 1.0 },
            Candle { time: 3, open: 120.0, high: 140.0, low: 110.0, close: 130.0, volume: 1.0 },
        ];
        // Switch OFF (default / legacy): the chart type is display-only, so even
        // a non-candle kind leaves the engine on the RAW series, untouched.
        let mut s = Settings::default();
        assert!(!s.filter_on_display_chart, "switch must default OFF (legacy)");
        for kind in ["candles", "heikin_ashi", "line", "renko"] {
            s.chart_kind = kind.into();
            let out = apply_engine_chart(src.clone(), &s);
            assert_eq!(out.len(), 3, "OFF keeps the raw series for {kind}");
            assert!((out[2].close - 130.0).abs() < 1e-9, "OFF returns raw close for {kind}");
        }

        // Switch ON: the engine now evaluates on the selected display chart.
        s.filter_on_display_chart = true;
        s.chart_kind = "candles".into();
        let raw = apply_engine_chart(src.clone(), &s);
        assert!((raw[2].close - 130.0).abs() < 1e-9);

        // Heikin Ashi rewrites the OHLC.
        s.chart_kind = "heikin_ashi".into();
        let ha = apply_engine_chart(src.clone(), &s);
        assert_eq!(ha.len(), 3);
        assert!((ha[1].close - 112.5).abs() < 1e-9, "HA close = (o+h+l+c)/4");

        // Line keeps the raw series (its closes drive the line).
        s.chart_kind = "line".into();
        assert!((apply_engine_chart(src.clone(), &s)[2].close - 130.0).abs() < 1e-9);

        // Renko rebuilds the series into bricks; a bigger move yields bricks.
        s.chart_kind = "renko".into();
        s.renko_box_size = 10.0;
        let bricks = apply_engine_chart(src, &s);
        assert!(!bricks.is_empty());
        for b in &bricks {
            assert!(((b.close - b.open).abs() - 10.0).abs() < 1e-9, "each brick is one box");
        }
    }

    #[test]
    fn calc_auto_lots_uses_liquidity_and_margin_caps() {
        // Defaults 1%/1% reproduce the old app: 1% of min(oi, volume) / lot.
        assert_eq!(calc_auto_lots(50.0, 100.0, 1_000_000.0, 1_000_000.0, 0.0, 1.0, 1.0), Some(200.0));
        // Margin: 95% of available / (lot * price).
        assert_eq!(calc_auto_lots(50.0, 100.0, 0.0, 0.0, 1_000_000.0, 1.0, 1.0), Some(190.0));
        // Both: the tighter cap wins.
        assert_eq!(calc_auto_lots(50.0, 100.0, 1_000_000.0, 1_000_000.0, 1_000_000.0, 1.0, 1.0), Some(190.0));
        // Nothing usable -> keep manual lots.
        assert_eq!(calc_auto_lots(50.0, 100.0, 0.0, 0.0, 0.0, 1.0, 1.0), None);
    }

    #[test]
    fn calc_auto_lots_picks_the_smaller_of_volume_and_oi_percent() {
        // Volume 2% of 50,000 = 1,000 units / lot 50 = 20 lots.
        // OI 2% of 25,000 = 500 units / lot 50 = 10 lots  -> OI cap wins.
        assert_eq!(calc_auto_lots(50.0, 100.0, 25_000.0, 50_000.0, 0.0, 2.0, 2.0), Some(10.0));
        // Flip the volumes: now volume is the tighter cap.
        assert_eq!(calc_auto_lots(50.0, 100.0, 50_000.0, 25_000.0, 0.0, 2.0, 2.0), Some(10.0));
        // Different percents are applied independently: OI 1% of 100,000 = 20 lots,
        // volume 3% of 100,000 = 60 lots -> 20 lots.
        assert_eq!(calc_auto_lots(50.0, 100.0, 100_000.0, 100_000.0, 0.0, 1.0, 3.0), Some(20.0));
        // A zero OI percent drops that cap and volume alone decides.
        assert_eq!(calc_auto_lots(50.0, 100.0, 25_000.0, 50_000.0, 0.0, 0.0, 2.0), Some(20.0));
        // Missing feed data falls back to the other cap (never blocks).
        assert_eq!(calc_auto_lots(50.0, 100.0, 0.0, 50_000.0, 0.0, 2.0, 2.0), Some(20.0));
        assert_eq!(calc_auto_lots(50.0, 100.0, 25_000.0, 0.0, 0.0, 2.0, 2.0), Some(10.0));
        // Margin still applies on top of the liquidity winner.
        assert_eq!(calc_auto_lots(50.0, 100.0, 25_000.0, 50_000.0, 50_000.0, 2.0, 2.0), Some(9.0));
    }

    #[test]
    fn liquid_legs_use_their_own_auto_lot_and_slice_policy() {
        let mut s = Settings::default();
        // Global policy - the SAME one Top Movers / indices / commodities use.
        s.auto_lot_oi_pct = 1.0;
        s.auto_lot_volume_pct = 1.0;
        s.slice_on = true;
        s.slice_lot_limit = 20.0;
        s.slice_lots = 5.0;
        // Dedicated liquid policy.
        s.liquid_auto_lot_on = true;
        s.liquid_auto_lot_oi_pct = 3.0;
        s.liquid_auto_lot_volume_pct = 2.0;
        s.liquid_slice_on = true;
        s.liquid_slice_lot_limit = 10.0;
        s.liquid_slice_lots = 2.0;

        let liquid = Strategy { liquid_leg: true, ..Default::default() };
        let other = Strategy { liquid_leg: false, ..Default::default() };

        // Liquid legs read their dedicated caps while their own switch is ON;
        // every other leg keeps the global config.
        assert_eq!(entry_auto_lot_cfg(&liquid, &s), (true, 3.0, 2.0));
        assert_eq!(entry_auto_lot_cfg(&other, &s), (false, 1.0, 1.0));

        assert_eq!(entry_slice_cfg(&liquid, &s), (true, 10.0, 2.0));
        assert_eq!(entry_slice_cfg(&other, &s), (true, 20.0, 5.0));

        // The plan that actually reaches the order path follows those values:
        // 20 lots, liquid limit 10 / slice 2 => ten 2-lot slices.
        let (on, lim, lots) = entry_slice_cfg(&liquid, &s);
        assert!(on);
        assert_eq!(paper_slice_plan(20, 1.0, lim, lots), vec![2; 10]);
        // The same quantity under the global policy slices 5-lots.
        let (on_g, lim_g, lots_g) = entry_slice_cfg(&other, &s);
        assert!(on_g);
        assert_eq!(paper_slice_plan(20, 1.0, lim_g, lots_g), vec![5; 4]);

        // Liquid switch OFF = behave EXACTLY like Top Movers: fall back to the
        // global Auto-Lot and global slicing config, never to a hard "off".
        s.liquid_auto_lot_on = false;
        assert_eq!(entry_auto_lot_cfg(&liquid, &s), (false, 1.0, 1.0));
        s.liquid_slice_on = false;
        assert_eq!(entry_slice_cfg(&liquid, &s), (true, 20.0, 5.0));
        assert_eq!(paper_slice_plan(20, 1.0, 20.0, 5.0), vec![5; 4]);
        // Global slicing OFF too => no plan, order goes out whole (the normal
        // `Lots` quantity next to Net TP, exactly as for Top Movers).
        s.slice_on = false;
        assert_eq!(entry_slice_cfg(&liquid, &s), (false, 20.0, 5.0));
        assert_eq!(order_pieces(20, &[], 0), vec![20]);

        // A non-liquid leg is NEVER touched by the liquid switches, even when
        // they are the only thing configured.
        s.liquid_auto_lot_on = true;
        s.liquid_slice_on = true;
        s.slice_on = true;
        s.auto_lot_oi_pct = 0.5;
        s.auto_lot_volume_pct = 0.5;
        assert_eq!(entry_auto_lot_cfg(&other, &s), (false, 0.5, 0.5));
        assert_eq!(entry_slice_cfg(&other, &s), (true, 20.0, 5.0));
    }

    #[tokio::test]
    async fn liquid_auto_lot_skips_the_manual_margin_precheck() {
        let market = crate::market::MarketState::new();
        let dhan = crate::broker::DhanState::new(market);
        let rt = RealtimeState::new_paper(dhan);
        let mut liquid = Strategy { liquid_leg: true, ..Default::default() };
        liquid.lot = 50.0;
        let mut other = Strategy::default();
        other.lot = 50.0;
        // A qty this large cannot fit any empty paper budget, so the pre-check
        // would report a block for a manual-lots leg.
        if let Ok(mut d) = rt.doc.lock() {
            d.settings.lots = 10_000.0;
            d.settings.lot_size = 50.0;
            d.settings.liquid_auto_lot_on = true;
        }
        // Liquid leg: its own Auto-Lot sizes it, so the pre-check must defer to
        // the exact gate inside `open_entry`.
        assert_eq!(rt.early_margin_skip_reason(&liquid, 100.0), None);
        // Every other leg is still pre-checked (and blocked here).
        assert!(rt.early_margin_skip_reason(&other, 100.0).is_some());
        // With the liquid switch off the liquid leg is manual-lots again.
        if let Ok(mut d) = rt.doc.lock() {
            d.settings.liquid_auto_lot_on = false;
        }
        assert!(rt.early_margin_skip_reason(&liquid, 100.0).is_some());
    }

    #[tokio::test]
    async fn liquid_leg_marker_is_tagged_only_by_the_liquid_scanner() {
        let market = crate::market::MarketState::new();
        let dhan = crate::broker::DhanState::new(market);
        let rt = RealtimeState::new_paper(dhan);
        let gainer = 13061; // 360ONE (NSE_EQ EQUITY)
        let loser = 21614; // ABCAPITAL (NSE_EQ EQUITY)
        let liquid_id = 2885; // RELIANCE (liquid basket member)
        if let Ok(mut g) = rt.liquid_cache.lock() {
            *g = (
                now_ms(),
                json!({
                    "on": true,
                    "gainers": [{"securityId": liquid_id, "last": 100.0}],
                    "losers": [],
                    "added": []
                }),
            );
        }
        if let Ok(mut g) = rt.movers_cache.lock() {
            *g = (
                now_ms(),
                json!({ "gainers": [{"securityId": gainer, "last": 100.0}], "losers": [{"securityId": loser, "last": 100.0}] }),
            );
        }
        let mut s = Settings::default();
        s.filters.insert("BullSlTrend".into(), true);
        s.filters.insert("BearSlTrend".into(), true);

        // Liquid scanner ON: its legs carry the liquid marker.
        s.liquid_on = true;
        let out = rt.scanner_targets(&s);
        let lq = out.iter().find(|x| x.security_id == liquid_id).expect("liquid leg built");
        assert!(lq.liquid_leg, "liquid scanner leg must be tagged liquid_leg");

        // Top Movers legs never carry it, even though the same cache holds them.
        s.movers_on = true;
        let out = rt.scanner_targets(&s);
        let mv = out.iter().find(|x| x.security_id == gainer).expect("movers leg built");
        assert!(!mv.liquid_leg, "Top Movers leg must NOT be tagged liquid_leg");
        assert!(out.iter().filter(|x| x.security_id == liquid_id).all(|x| x.liquid_leg));

        // Liquid scanner OFF: no leg keeps the marker.
        s.liquid_on = false;
        let out = rt.scanner_targets(&s);
        assert!(out.iter().all(|x| !x.liquid_leg), "no liquid legs once the scanner is off");
    }

    #[tokio::test]
    async fn liquid_owned_stocks_are_excluded_from_the_top_movers_list() {
        // A stock that the Liquid F&O list is showing (its scanner gainers /
        // losers / hand-added names or the operator's explicit pick) must not be
        // re-listed in the Top Movers gainers / losers readout. The liquid list
        // owns it; the movers ranking skips it and takes its top N from the rest.
        let market = crate::market::MarketState::new();
        let dhan = crate::broker::DhanState::new(market);
        let rt = RealtimeState::new_paper(dhan);
        let liquid_id = 2885; // RELIANCE (liquid basket member)
        if let Ok(mut g) = rt.liquid_cache.lock() {
            *g = (
                now_ms(),
                json!({
                    "on": true,
                    "gainers": [{"securityId": liquid_id, "last": 100.0}],
                    "losers": [],
                    "added": []
                }),
            );
        }
        let mut s = Settings::default();

        // Scanner OFF: nothing is owned, so the stock stays rankable.
        s.liquid_on = false;
        assert!(rt.liquid_owned_ids(&s).is_empty());

        // Scanner ON: the shown stock is owned and dropped from movers rows.
        s.liquid_on = true;
        let owned = rt.liquid_owned_ids(&s);
        assert!(owned.contains(&liquid_id), "the liquid gainer is owned by the liquid list");
        let rows = vec![
            json!({"securityId": liquid_id, "changePct": 5.0}),
            json!({"securityId": 13061, "changePct": 3.0}),
        ];
        let ranked = exclude_liquid_owned(rows, &owned);
        assert_eq!(ranked.len(), 1, "only the non-liquid stock stays in the movers ranking");
        assert_eq!(ranked[0]["securityId"], json!(13061));

        // Operator's explicit gainer / loser picks and saved adds are owned too.
        if let Ok(mut g) = rt.liquid_cache.lock() {
            *g = (now_ms(), json!({ "on": true, "gainers": [], "losers": [], "added": [] }));
        }
        s.liquid_list = vec![11536];
        s.liquid_gainer = 21614;
        s.liquid_loser = 13061;
        let owned = rt.liquid_owned_ids(&s);
        assert!(owned.contains(&11536), "hand-added stock is owned");
        assert!(owned.contains(&21614), "explicit gainer pick is owned");
        assert!(owned.contains(&13061), "explicit loser pick is owned");

        // A stocks-only engine never owns liquid names (no liquid scanner there).
        let p2 = RealtimeState::new_paper2(crate::broker::DhanState::new(crate::market::MarketState::new()));
        let mut s2 = Settings::default();
        s2.liquid_on = true;
        s2.liquid_list = vec![11536];
        assert!(p2.liquid_owned_ids(&s2).is_empty());
    }

    #[test]
    fn paper_slice_plan_splits_above_the_lot_threshold() {
        // User's example: 20 lots, limit 20, slice 5 => four 5-lot slices.
        assert_eq!(paper_slice_plan(20, 1.0, 20.0, 5.0), vec![5, 5, 5, 5]);
        // Below the threshold: single entry, no slicing.
        assert_eq!(paper_slice_plan(10, 1.0, 20.0, 5.0), Vec::<i64>::new());
        // Threshold 0 = always slice.
        assert_eq!(paper_slice_plan(10, 1.0, 0.0, 4.0), vec![4, 4, 2]);
        // Slice larger than the whole order => no split.
        assert_eq!(paper_slice_plan(5, 1.0, 0.0, 10.0), Vec::<i64>::new());
        // Disabled (slice 0) or bad lot => inert.
        assert_eq!(paper_slice_plan(20, 1.0, 20.0, 0.0), Vec::<i64>::new());
        assert_eq!(paper_slice_plan(20, 0.0, 20.0, 5.0), Vec::<i64>::new());
        // Non-unit lot size: 20 lots of 50 = 1000 qty, slice 5 lots = 250 each.
        assert_eq!(paper_slice_plan(1000, 50.0, 20.0, 5.0), vec![250, 250, 250, 250]);
    }

    #[test]
    fn order_pieces_prefers_the_engine_plan() {
        // Engine plan wins over the method fallback.
        assert_eq!(order_pieces(1000, &[250, 250, 250, 250], 100), vec![250, 250, 250, 250]);
        // No plan: a fallback chunk smaller than the order is honoured.
        assert_eq!(order_pieces(1000, &[], 300), vec![300, 300, 300, 100]);
        // No plan and no usable fallback: one whole chunk.
        assert_eq!(order_pieces(1000, &[], 0), vec![1000]);
        assert_eq!(order_pieces(1000, &[], 1000), vec![1000]);
        assert_eq!(order_pieces(1000, &[], 5000), vec![1000]);
        // Non-positive qty is inert.
        assert!(order_pieces(0, &[], 100).is_empty());
    }

    #[test]
    fn paper_slice_fills_books_each_slice_at_the_slipped_mark() {
        let (legs, avg) = paper_slice_fills(&[250, 250, 250, 250], 50.0, 100.456, 123);
        assert_eq!(legs.len(), 4);
        assert_eq!(legs[0]["qty"], json!(250));
        assert_eq!(legs[0]["lots"], json!(5.0));
        assert_eq!(legs[0]["price"], json!(100.46));
        assert!((avg - 100.46).abs() < 1e-9, "weighted average = slipped mark");
        // Empty plan inert.
        let (none, avg0) = paper_slice_fills(&[], 50.0, 99.999, 0);
        assert!(none.is_empty());
        assert!((avg0 - 100.0).abs() < 1e-9);
    }

    #[test]
    fn sl_auto_drives_atr_floor() {
        let mut s = Settings::default();
        s.sl_auto = true;
        // ATR stop is honoured only when the auto flag is on.
        let (sl, _, _, _) = levels_for(&s, &json!({}), "BUY", 100.0, 95.0, 110.0, 3.0);
        assert!((sl - 95.0).abs() < 1e-9);
        s.sl_auto = false;
        let (sl2, _, _, _) = levels_for(&s, &json!({}), "BUY", 100.0, 95.0, 110.0, 3.0);
        assert_eq!(sl2, 0.0);
    }

    #[test]
    fn rr_target_overrides_ai_tp() {
        let mut s = Settings::default();
        s.ai_tp_pct = true;
        // Without RR the AI TP wins (the passed-in AI level).
        let (_, tp, _, _) = levels_for(&s, &json!({}), "BUY", 100.0, 95.0, 112.0, 3.0);
        assert!((tp - 112.0).abs() < 1e-9);
        // With RR on: target = |entry - SL| x RR, beating the AI TP%.
        s.rr_enabled = true;
        s.rr_value = 2.0;
        let (_, tp, _, _) = levels_for(&s, &json!({}), "BUY", 100.0, 95.0, 112.0, 3.0);
        assert!((tp - 110.0).abs() < 1e-9);
        // SELL mirrors to the downside.
        let (_, tp, _, _) = levels_for(&s, &json!({}), "SELL", 100.0, 105.0, 90.0, 3.0);
        assert!((tp - 90.0).abs() < 1e-9);
        // RR on but no usable SL distance -> TP stays 0 (nothing to size against).
        let (_, tp, _, _) = levels_for(&s, &json!({}), "BUY", 100.0, 0.0, 110.0, 3.0);
        assert_eq!(tp, 0.0);
    }

